insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'PSA', 119, 102, 'Ndyaaathũka kuma motw’ĩonĩ maku; Nũndũ nũmanyĩĩtye nyie.'),
('kam', 'PSA', 119, 103, 'A! Ndeto syaku syĩ mũyo kaakaanĩ wakwa! Ĩĩ, mũyo kwĩ ũkĩ wa nzũkĩ kanyw’anĩ wakwa!'),
('kam', 'PSA', 119, 104, 'Kwondũ wa mawĩaĩo maku nĩnosaa ũmanyi: Kwondũ wa ũu nĩnĩmenaa kĩla nzĩa ya ũvũngũ.'),
('kam', 'PSA', 119, 105, 'Ndeto yaku nĩ taa wa maũũ makwa, Na kyeni kya nzĩa yakwa.'),
('kam', 'PSA', 119, 106, 'Nĩnĩavĩte, na ngakĩlũlũmĩlya, Atĩ ngeanĩsya motw’ĩo maku malũngalu.'),
('kam', 'PSA', 119, 107, 'Nĩngũthĩnw’a mũno: Nthayũũkya, ame Yeova, kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 108, 'Osa, nĩngũkwĩsũva, nthembo syumĩtw’e nĩ kanyw’a wakwa na ngoo ya kwenda, ame Yeova, Na kũmanyĩsya nyie motw’ĩo maku.'),
('kam', 'PSA', 119, 109, 'Thayũ wakwa wĩ kw’okonĩ kwakwa ĩndĩ yonthe; Ĩndĩ ndyũlawa nĩ mĩao yaku.'),
('kam', 'PSA', 119, 110, 'Ala athũku nĩmandeie na kĩtei; Ĩndĩ ndyaanganga kũma mawĩaĩonĩ maku.'),
('kam', 'PSA', 119, 111, 'Nĩnosete mokũsĩ maku methĩwe ta ũtiĩwa tene na tene; Nũndũ nĩmo ũtanu wa ngoo yakwa.'),
('kam', 'PSA', 119, 112, 'Nĩnelekelye ngoo yakwa kwĩka myamũlo yaku Tene na tene, o kũvika mũminũkĩlyo.'),
('kam', 'PSA', 119, 113, 'Nĩmenaa ala me na mĩtwe ĩlĩ; Ĩndĩ nĩnendaa mĩao yaku.'),
('kam', 'PSA', 119, 114, 'Nue vandũ vakwa va kwĩvitha na ngao yakwa: Nĩnĩkwatasya ndeto yaku.'),
('kam', 'PSA', 119, 115, 'Umai vala nĩĩ, inyw’ĩ eki ma naĩ, Nĩ kana nĩkwate mĩao ya Ngai wakwa.'),
('kam', 'PSA', 119, 116, 'Ndw’ĩĩka kwĩanana na ndeto yaku, nĩ kana nĩkale thayũ; Na ndikasonokee wĩkwatyo wakwa.'),
('kam', 'PSA', 119, 117, 'Ndw’ĩĩka, na ndikethĩwa na mũisyo, Na ngakwataa myamũlo yaku ĩndĩ yonthe.'),
('kam', 'PSA', 119, 118, 'Nũmatw’ĩkĩthĩtye ma mana onthe ala mavĩtanĩasya myamũlo yaku; Nũndũ ũkengani woo nĩ ũvũngũ.'),
('kam', 'PSA', 119, 119, 'Nũvetaa kũasa athũku onthe ma nthĩ ta mavuthĩ: Kwondũ wa ũu nĩnendaa mokũsĩ maku.'),
('kam', 'PSA', 119, 120, 'Mwĩĩ wakwa nũtetemaa nũndũ wa ũkũkĩa; Na nĩngũkĩa mosilĩlo maku.'),
('kam', 'PSA', 119, 121, 'Nĩnĩsilĩte sila wa katĩ na kwĩka ũlũngalu: Ndũkandiĩe athĩn’ya makwa.'),
('kam', 'PSA', 119, 122, 'Ĩthĩwa mũĩkĩĩwa kwa mũthũkũmi waku kwondũ wa ũseo: Ndũkaeke ekathĩĩi manthĩn’ye.'),
('kam', 'PSA', 119, 123, 'Metho makwa nĩmeũseekea kwondũ wa ũtangĩĩo waku, Na kwondũ wa ndeto yaku ndũngalu.'),
('kam', 'PSA', 119, 124, 'Mwĩke mũthũkũmi waku kwĩanana na ũseo waku wĩ wendo, Na kũmanyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 125, 'Nyie nĩ mũthũkũmi waku; nenga ũmanyi, Nĩ kana nĩmanye mokũsĩ maku.'),
('kam', 'PSA', 119, 126, 'Nĩ ĩvinda ya Yeova ya kũtethya wĩa; Nũndũ nĩmatw’ĩkĩthĩtye mĩao yaku ya mana.'),
('kam', 'PSA', 119, 127, 'Kwondũ wa ũu nĩnendaa mĩao yaku Kwĩ thaavu, ĩĩ, kwĩ thaavu ũla mũseo mũno.'),
('kam', 'PSA', 119, 128, 'Kwondũ wa ũu mawĩaĩo maku onthe maũndũnĩ onthe nĩtĩkĩlaa nĩ ma w’o; Na nĩmenaa kĩla nzĩa ya ũvũngũ.'),
('kam', 'PSA', 119, 129, 'Mokũsĩ maku nĩ ma ũseng’ya; Kwondũ wa ũu ngoo yakwa nĩmakwataa.'),
('kam', 'PSA', 119, 130, 'Ũvuan’yo wa ndeto syaku nũetae kyeni; Nũnengae ũmanyi ala mate naw’o.'),
('kam', 'PSA', 119, 131, 'Nĩnaathamisye kanyw’a wakwa mũno, na navevaveva; Nũndũ naĩ na mea ma mĩao yaku.'),
('kam', 'PSA', 119, 132, 'Ĩnthyũũĩe, na kũmbĩw’ĩa tei, Tondũ wakothaa kũmeka ala mayendaa syĩtwa yaku.'),
('kam', 'PSA', 119, 133, 'Lũlũmĩlya matambya makwa ndetonĩ yaku; Na ndũkaeke ũthũku o na wĩva ũnzumbĩke.'),
('kam', 'PSA', 119, 134, 'Mbovosya nume ũthĩn’yonĩ wa andũ: Na ĩndĩ ngakwataa mawĩaĩo maku.'),
('kam', 'PSA', 119, 135, 'Ũthyũ waku ũmũtisĩae mũthũkũmi waku; Na kũmanyĩsya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 136, 'Mbũsĩ sya manzĩ itheeaa kuma methonĩ makwa, Nũndũ amwe matikwataa mĩao yaku.'),
('kam', 'PSA', 119, 137, 'Wĩ mũlũngalu, we Yeova, Na mosilĩlo maku nĩ malũngalu.'),
('kam', 'PSA', 119, 138, 'Nĩwĩaĩte mokũsĩ maku ũlũngalunĩ Na kĩthitonĩ ki.'),
('kam', 'PSA', 119, 139, 'Nĩnĩminĩtwe nĩ kĩwĩu kyakwa, Nĩkwĩthĩwa nthũ syakwa nĩsyũlĩtwe nĩ ndeto syaku.'),
('kam', 'PSA', 119, 140, 'Ndeto yaku nĩ ntheu mũno; Kwondũ wa ũu mũthũkũmi waku nũmyendaa.'),
('kam', 'PSA', 119, 141, 'Nyie nĩ mũnini na mũvũthye; ĩndi ndyũlawa nĩ mawĩaĩo maku.'),
('kam', 'PSA', 119, 142, 'Ũlũngalu waku nĩ ũlũngalu wa tene na tene, Na mĩao yaku nĩ w’o.'),
('kam', 'PSA', 119, 143, 'Thĩna na woo ningwatĩte; Ĩndĩ mĩao yaku nĩ ũtanu wakwa.'),
('kam', 'PSA', 119, 144, 'Mokũsĩ maku nĩ malũngalu tene na tene; Nenga ũmanyi, na ngekala thayũ.'),
('kam', 'PSA', 119, 145, 'Nĩnĩkaĩlĩte na ngoo yakwa yonthe; nzũngĩa, ame Yeova: Ngakwataa myamũlo yaku.'),
('kam', 'PSA', 119, 146, 'Nĩnĩkwĩkaĩlĩte; ndangĩĩa, Na ngakwataa mokũsĩ maku'),
('kam', 'PSA', 119, 147, 'Nĩnaumaalile kĩoko kũitheana, na naĩa: Nĩneekwatisye ndeto syaku.'),
('kam', 'PSA', 119, 148, 'Metho makwa mosyaĩĩsyonĩ ma ũtukũ nĩmasalukĩtye, Nĩ kana nĩsũanĩae ndeto yaku.'),
('kam', 'PSA', 119, 149, 'Ĩthukĩĩsye wasya wakwa kwĩanana na ũseo waku wĩ wendo: Nthayũũkya, ame Yeova, kwĩanana na motw’ĩo maku.'),
('kam', 'PSA', 119, 150, 'Manthengeeaa vakuvĩ ala mavikĩlaa ũthũku; Me kũasa na mĩao yaku.'),
('kam', 'PSA', 119, 151, 'Wĩ vakuvĩ, ame Yeova; Na mĩao yaku yonthe nĩ w’o.'),
('kam', 'PSA', 119, 152, 'Kuma tene nĩnamanyie kuma mokũsĩnĩ maku, Kana nũmalũmĩtye tene na tene.'),
('kam', 'PSA', 119, 153, 'Sũanĩa ũndũ wa thĩna wakwa, noimbonokya; Nũndũ ndyũlawa nĩ mĩao yaku.'),
('kam', 'PSA', 119, 154, 'Ndetea, na kũmbovosya: Nthayũũkya kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 155, 'Ũtangĩĩo wĩ kũasa na ala athũku; Nũndũ matimanthaa myamũlo yaku.'),
('kam', 'PSA', 119, 156, 'Matei maku mololo nĩ manene, ame Yeova: Nthayũũkya kwĩanana na motw’ĩo maku.'),
('kam', 'PSA', 119, 157, 'Athĩn’ya makwa na nthũ syakwa nĩ mbingĩ; Ĩndĩ ndyaaathũka kuma mokũsĩnĩ maku.'),
('kam', 'PSA', 119, 158, 'Nĩnoonie nzeleke, na neew’a woo, Nĩkwĩthĩwa itikwataa ndeto yaku.'),
('kam', 'PSA', 119, 159, 'Sũanĩa ũndũ nendete mawĩaĩo maku: Nthayũũkya, ame Yeova, kwĩanana na ũseo waku wĩ wendo.'),
('kam', 'PSA', 119, 160, 'Kũmbanw’a kwa ndeto yaku yonthe nĩ w’o; Na kĩla ũmwe wa motw’ĩo maku malũngalu nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 119, 161, 'Anene me mbee ũsumbĩnĩ nĩmathĩnĩtye vate kĩtumi; Ĩndĩ ngoo yakwa nĩkĩaa nũndũ wa ndeto syaku.'),
('kam', 'PSA', 119, 162, 'Nĩtanĩaa ndeto yaku, Ta mũndũ ũla wonaa mũtavo mũnene.'),
('kam', 'PSA', 119, 163, 'Nĩmenaa na kũthĩtha ũvũngũ; Ĩndĩ nĩnendaa mĩao yaku.'),
('kam', 'PSA', 119, 164, 'Nĩkũtaĩaa mavinda mũonza kĩla mũthenya, Nũndũ wa motw’ĩo maku malũngalu.'),
('kam', 'PSA', 119, 165, 'Ala mendaa mĩao yaku me na mũuo mũnene; Na mati na ũndũ wa kũmalulutĩkya.'),
('kam', 'PSA', 119, 166, 'Nĩnĩkwatĩtye ũtangĩĩo waku, ame Yeova, Na nĩnĩkĩte mĩao yaku.'),
('kam', 'PSA', 119, 167, 'Ngoo yakwa nĩkwatĩte mokũsĩ maku; Na nĩnĩmendete mũno.'),
('kam', 'PSA', 119, 168, 'Nĩngwatĩte mawĩaĩo maku na mokũsĩ maku; Nũndũ mĩendele yakwa yonthe yĩ mbee waku'),
('kam', 'PSA', 119, 169, 'Kũkaya kwakwa nĩkũthengeee mbee waku, ame Yeova: Nenga ũmanyi kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 170, 'Wĩsũvano wakwa nĩwũke vala ũĩ: Mbonokya kwĩanana na ndeto yaku.'),
('kam', 'PSA', 119, 171, 'Ilomo syakwa nĩsyumye ndaĩa; Nũndũ nũmanyĩasya nyie myamũlo yaku.'),
('kam', 'PSA', 119, 172, 'Ũĩmĩ wakwa nũkumye ndeto yaku; Nũndũ mĩao yaku yonthe nĩ mĩlũngalu.'),
('kam', 'PSA', 119, 173, 'Kw’oko kwaku nĩkwĩyũmban’ye kũndethya; Nũndũ nĩnĩnyuvĩte mawĩaĩo maku.'),
('kam', 'PSA', 119, 174, 'Nĩnendete mũno ũtangĩĩo waku, ame Yeova; Na mĩao yaku nĩ ũtanu wakwa.'),
('kam', 'PSA', 119, 175, 'Thayũ wakwa nĩwĩkalae, na ũkakũtaĩaa; Na motw’ĩo maku nĩmandethye.'),
('kam', 'PSA', 119, 176, 'Nĩnaĩte ta ĩlondu yau; mantha mũthũkũmi waku; Nũndũ ndyũlawa nĩ mĩao yaku.'),
('kam', 'PSA', 120, 1, 'Ũnyamaonĩ wakwa nĩnamwĩkaĩlile Yeova, Na azũngĩa.'),
('kam', 'PSA', 120, 2, 'Vonokya thayũ wakwa, ame Yeova, kuma ilomonĩ ila ineenaa ũvũngũ, Na ũĩmĩnĩ ũla ũkenganaa.'),
('kam', 'PSA', 120, 3, 'Ũkanengwa kyaũ, na ũkekwa ũndũ ũngĩ mwaũ, We ũĩmĩ ũla ũkenganaa?'),
('kam', 'PSA', 120, 4, 'Ũilyĩ mĩsyĩ myũĩ ya ala me ũtonyi, Na makaa ma mũtĩ wĩtawa mũlutemu.'),
('kam', 'PSA', 120, 5, 'Woo nĩ wakwa, nũndũ nĩkalaa ũeni kũũ Meseki, Nũndũ nĩtũaa katĩ wa maeema ma Ketali!'),
('kam', 'PSA', 120, 6, 'Thayũ wakwa wĩkalĩte ĩvinda ĩasa ũtwĩe Vamwe na ũla ũmenaa mũuo.'),
('kam', 'PSA', 120, 7, 'Nyie nĩ wa mũuo: Indĩ yĩla ngũneena, mo nĩ ma kaũ.'),
('kam', 'PSA', 121, 1, 'Ngookĩlĩlya iĩma metho makwa: Ũtethyo wakwa wĩuma va?'),
('kam', 'PSA', 121, 2, 'Ũtethyo wakwa nĩwumaa kwa Yeova, Ũla watw’ĩkĩthisye ĩtu na nthĩ.'),
('kam', 'PSA', 121, 3, 'Ndakaeka kũũ kwakwa kũthingithangw’e: Ũla ũkũsũvĩaa ndakombosya.'),
('kam', 'PSA', 121, 4, 'Sisya, ũla ũsũvĩaa Isilaeli Ndakombosya kana kũkoma.'),
('kam', 'PSA', 121, 5, 'Yeova nĩwe mũsũvĩi waku: Yeova nĩwe muunyĩ waku ngalĩ ya kw’oko kwaku kwa aũme.'),
('kam', 'PSA', 121, 6, 'Syũa yĩtikakũkũna mũthenya, Kana mwei ũtukũ.'),
('kam', 'PSA', 121, 7, 'Yeova akakũsũvĩaa kwa ũthũku w’onthe; Akasũvĩaa thayũ waku.'),
('kam', 'PSA', 121, 8, 'Yeova akasũvĩaa kumaala kwaku na kũsyoka kwaku Kuma yu na kũvika tene na tene.'),
('kam', 'PSA', 122, 1, 'Naĩ na ũtanu yĩla mambĩie, Tũendei nyũmbanĩ ya Yeova.'),
('kam', 'PSA', 122, 2, 'Maũũ maitũ nĩmaũngamĩte Mbingĩlonĩ syaku, we Yelusaleme,'),
('kam', 'PSA', 122, 3, 'Yelusaleme, we nĩwakĩtwe Ta ndũa ĩla ĩkwatanĩte;'),
('kam', 'PSA', 122, 4, 'Vala mbaĩ syambataa, o mbaĩ sya Yeova, Nũndũ nĩ ũtw’ĩo wa Isilaeli, Itũngĩe syĩtwa ya Yeova mũvea.'),
('kam', 'PSA', 122, 5, 'Nũndũ kw’o ivĩla sya ũsumbĩ nĩsiĩtwe ũndũ wa ũsilĩlo, Ivĩla sya ũsumbĩ sya nyũmba ya Ndaviti.'),
('kam', 'PSA', 122, 6, 'Voyai ũndũ wa mũuo wa Yelusaleme: Makaathimĩka ala makwendaa.'),
('kam', 'PSA', 122, 7, 'Mũuo nĩwĩthĩwe nthĩnĩ wa maũvai maku, Na ũathimo nthĩnĩ wa nyũmba syaku nene mbanakavye.'),
('kam', 'PSA', 122, 8, 'Kwondũ wa ana‐a‐asa na atindan’ya makwa, Yu nĩngwasya, Mũuo nĩwĩthĩwe nthĩnĩ waku.'),
('kam', 'PSA', 122, 9, 'Kwondũ wa nyũmba ya Yeova Ngai waitũ Ngakũmanthĩa ũseo.'),
('kam', 'PSA', 123, 1, 'Nĩngũkũkĩlĩlya metho makwa, We ũla wĩkalaa matunĩ.'),
('kam', 'PSA', 123, 2, 'Sisya, o tondũ metho ma athũkũmi masyaĩĩasya kw’oko kwa vwana woo, O tondũ metho ma mwĩĩtu masyaĩĩasya kw’oko kwa vivi wake; No ta ũu metho maitũ masyaĩĩasya Yeova Ngai waitũ, Kũvika atwĩw’ĩa tei.'),
('kam', 'PSA', 123, 3, 'Twĩw’ĩe tei, ame Yeova, twĩw’ĩe tei; Nũndũ tusũĩtwe mũno nĩ kũvũthw’a.'),
('kam', 'PSA', 123, 4, 'Thayũ witũ usũĩtwe mũno Nĩ kũvũĩwa ngũĩ nĩ ala methũmũĩtye, Na mbũthya ya ekathĩĩi.'),
('kam', 'PSA', 124, 1, 'Kethĩwa ti ũndũ wa Yeova ũla waĩ ngalĩ ĩla yaitũ, Isilaeli maneene,'),
('kam', 'PSA', 124, 2, 'Kethĩwa ti ũndũ wa Yeova ũla waĩ ngalĩ ĩla yaitũ, Yĩla andũ matũkĩlĩĩle;'),
('kam', 'PSA', 124, 3, 'Methĩwa matũmelilye twĩ thayũ, Yĩla kũthilĩka kwoo kwatwakanĩe:'),
('kam', 'PSA', 124, 4, 'Manzĩ methĩwa matũvw’ĩkie, Ũsĩ wĩthĩwa wavĩtĩle ĩũlũ wa mathayũ maitũ;'),
('kam', 'PSA', 124, 5, 'Manzĩ ala mekathĩĩaa methĩwa mavĩtĩle ĩũlũ wa mathayũ maitũ.'),
('kam', 'PSA', 124, 6, 'Nataĩwe Yeova, Ũla ũtaatũnengane twĩthĩwe mũtavo maeonĩ moo.'),
('kam', 'PSA', 124, 7, 'Thayũ witũ nũvonokete ta nyũnyi yumĩte kĩteinĩ kya atei mayo: Kĩtei nĩ kĩtw’ĩku, na nĩtũvonokete.'),
('kam', 'PSA', 124, 8, 'Ũtethyo witũ wĩ syĩtwanĩ ya Yeova, Ũla watw’ĩkĩthisye ĩtu na nthĩ.'),
('kam', 'PSA', 125, 1, 'Ala mamũĩkĩĩaa Yeova Mailyĩ kĩĩma kya Saioni, kĩla kĩtathingithĩka, ĩndĩ kĩkalaa tene na tene.'),
('kam', 'PSA', 125, 2, 'O tondũ iĩma ithyũlũlũkĩte Yelusaleme, Now’o Yeova ũthyũlũlũkĩte andũ make Kuma yu na kũvika tene na tene.'),
('kam', 'PSA', 125, 3, 'Nũndũ ndata ya ũsumbĩ ya ũthũku ndĩkekala ĩũlũ wa ũtiĩwa wa alũngalu; Kana ala alũngalu matikaatambũũkye moko moo meke ũthũku.'),
('kam', 'PSA', 125, 4, 'Mekae nesa, ame Yeova, ala aseo, Na ala alũngalu ngoonĩ syoo.'),
('kam', 'PSA', 125, 5, 'Ĩndĩ ũndũ wa ala methyũũaa maende nzĩanĩ syoo nthyoeku, Yeova akamaumaalanĩlya vamwe na eki ma ũthũku. Mũuo nĩwĩthĩwe ĩũlũ wa Isilaeli.'),
('kam', 'PSA', 126, 1, 'Yĩla Yeova watũngie ala masyokie Saioni, Twailyĩ ta ala maotaa ndoto.'),
('kam', 'PSA', 126, 2, 'Nĩvo kanyw’a witũ wausũiwe nĩ kũtheka, Na ũĩmĩ witũ nĩ wini: Nĩvo i mbaĩ syaisye, Yeova nũmekĩte maũndũ manene.'),
('kam', 'PSA', 126, 3, 'Yeova nũtwĩkĩte maũndũ manene, Kwondũ wa ũu twĩ atanu.'),
('kam', 'PSA', 126, 4, 'Tũtũnge tume kũtavwanĩ kwitũ, ame Yeova, Ta mbũsĩ sya ngalĩ ya Ĩtheo.'),
('kam', 'PSA', 126, 5, 'Ala mavuĩaa na methoi makaketha na ũtanu.'),
('kam', 'PSA', 126, 6, 'Ũla umaalaa akĩĩa, akuĩte mbeũ sya kũvuĩa, Vate nzika akasyoka na ũtanu, akuĩte syove syake sya ngetha.'),
('kam', 'PSA', 127, 1, 'Keka Yeova wakaa nyũmba, Matethya wĩa mana ala mamyaka Keka Yeova ũsũvĩaa ndũa, Mũsyaĩĩsya asyaĩĩsya mana.'),
('kam', 'PSA', 127, 2, 'Nĩ mana kwenyu kũkĩla tene, Kũselewa nĩ kũthi kũkoma, Kũya lĩu wa thĩna; Nũndũ nĩwe ũmũnengae mwendwa wake too.'),
('kam', 'PSA', 127, 3, 'Sisya, syana nĩ ũtiĩwa kuma kwa Yeova; Na ũsyao wa ĩvu nĩ ĩtuvi yake.'),
('kam', 'PSA', 127, 4, 'Ta mĩsyĩ kw’okonĩ kwa ngũmbaũ, Now’o syana sya ala ma mũika itilyĩ.'),
('kam', 'PSA', 127, 5, 'Nĩ mũtanu mũndũ ũla wĩ na thyaka wake usũĩtwe nĩsyo: Matikasonoka, Yĩla meũneenea na amaitha moo mbingĩlonĩ.'),
('kam', 'PSA', 128, 1, 'Nĩ mũathime kĩla mũndũ ũla ũkĩaa Yeova, Ũla ũkinyaa nzĩanĩ syake.'),
('kam', 'PSA', 128, 2, 'Nũndũ ũkaĩsaa wĩa wa moko maku: Ũkeethĩwa wĩ na ũtanu, na kũkeethĩwa ũseo kwaku.'),
('kam', 'PSA', 128, 3, 'Kĩveti kyaku kĩkeethĩwa ta mũsavivũ wĩ ũsyao, Nthĩnĩ wa nyũmba yaku; Syana syaku ta mĩmea ya mĩthata, Kũthyũlũlũka mesa yaku.'),
('kam', 'PSA', 128, 4, 'Sisya, ũu now’o mũndũ ũkaathimwa Ũla ũkĩaa Yeova.'),
('kam', 'PSA', 128, 5, 'Yeova nakũathime e Saioni: Naku ũkyona ũseo wa Yelusaleme mĩthenya yonthe ya thayũ waku.'),
('kam', 'PSA', 128, 6, 'Ĩĩ, wone esũkũũu. Mũuo nĩwĩthĩwe ĩũlũ wa Isilaeli.'),
('kam', 'PSA', 129, 1, 'Nĩmanthĩnĩtye mavinda maingĩ kuma wana wakwa, Isilaeli naneene,'),
('kam', 'PSA', 129, 2, 'Nĩmanthĩnĩtye mavinda maingĩ kuma wana wakwa: Ĩndĩ matyaangĩlya vinya.'),
('kam', 'PSA', 129, 3, 'Aĩmi nĩmenzie mũongonĩ wakwa; Maasavisye mĩkao yoo.'),
('kam', 'PSA', 129, 4, 'Yeova nĩ mũlũngalu: Nũtilanĩtye ndii sya ala athũku.'),
('kam', 'PSA', 129, 5, 'Nĩmasonokw’e na kũtũngwa na ĩtina, Onthe ala mamenaa Saioni.'),
('kam', 'PSA', 129, 6, 'Nĩmethĩwe ta nyeki syĩ ĩũlũ wa nyũmba, Ila syũmaa itanamba kwĩana;'),
('kam', 'PSA', 129, 7, 'Mũkethi ndausũasya ngundi ya kw’oko kwake nasyo, Kana ũla wovaa syove sya ngetha ndausũasya kĩthũinĩ kyake:'),
('kam', 'PSA', 129, 8, 'O na ala mavĩtaa matiasya, Ũathimo wa Yeova nĩwĩthĩwe ĩũlũ waku; Nĩtũũkũathima syĩtwanĩ ya Yeova.'),
('kam', 'PSA', 130, 1, 'Nĩ syũngũnĩ nene nĩnĩkwĩkaĩlĩte, ame Yeova.'),
('kam', 'PSA', 130, 2, 'Mwĩaĩi, ĩw’a wasya wakwa: Matũ maku nĩmethukĩĩsye Wasya wa mawĩsũvano makwa.'),
('kam', 'PSA', 130, 3, 'Ethĩwa we, Yeova, ũkatala mothũku, We Mwĩaĩi, nũũ ũtonya kũũngama?'),
('kam', 'PSA', 130, 4, 'Ĩndĩ ve ũekeo kwaku, Nĩ kana ũkĩwe.'),
('kam', 'PSA', 130, 5, 'Nĩngũmweteela Yeova, ngoo yakwa nĩyeteelaa, Na nĩ na wĩkwatyo ndetonĩ yake.'),
('kam', 'PSA', 130, 6, 'Ngoo yakwa nĩyeteelaa Mwĩaĩi Kwĩ ũndũ asyaĩĩsya meteelaa kũkye; Ĩĩ, kwĩ ũndũ asyaĩĩsya meteelaa kũkye.'),
('kam', 'PSA', 130, 7, 'We Isilaeli, ĩkwatye Yeova: Nũndũ kwa Yeova kwĩ ũseo wĩ wendo, Na kwake kwĩ wovosyo mwingĩ.'),
('kam', 'PSA', 130, 8, 'Nake akoovosya Isilaeli Kuma mothũkunĩ make onthe.'),
('kam', 'PSA', 131, 1, 'Yeova, ngoo yakwa ndĩ na mĩng’athĩlĩlyo, kana metho makwa mĩtũlyo; O na ndiendaa maũndũnĩ manene, Kana maũndũnĩ ma ũseng’ya mambĩtũkĩte.'),
('kam', 'PSA', 131, 2, 'Nĩ w’o nĩvindĩthĩtye na kũkilĩthya ngoo yakwa; Ta kana kaaĩu ke na inyia wako, Ta kana kaaĩu now’o ngoo yakwa ĩilyĩ nthĩnĩ wakwa.'),
('kam', 'PSA', 131, 3, 'We Isilaeli, ĩkwatye Yeova Kuma yu na kũvika tene na tene.'),
('kam', 'PSA', 132, 1, 'Yeova, lilikana ũndũ wa Ndaviti Thĩna wake w’onthe;'),
('kam', 'PSA', 132, 2, 'Ũndũ wamwĩvĩtĩe Yeova, Na kũmwĩavĩa Ũla Mwene Vinya wa Yakovo:'),
('kam', 'PSA', 132, 3, 'Vate ndĩi ndikalika wĩkalonĩ wa nyũmba yakwa, Kana kũtũla ũkomonĩ wakwa;'),
('kam', 'PSA', 132, 4, 'Ndikanenga metho makwa too, Kana kũtinan’ya ilomo sya metho;'),
('kam', 'PSA', 132, 5, 'Kũvika noona vandũ va Yeova, Wĩkalo kwondũ wa Ũla Mwene Vinya wa Yakovo.'),
('kam', 'PSA', 132, 6, 'Sisya, nĩtweewie ũvoo wayo ku Evilatha: Nĩtwayonie kĩsesinĩ kĩ mĩtĩ.'),
('kam', 'PSA', 132, 7, 'Tũkalika mawĩkalonĩ make; Tũkathaithĩaa kavĩlanĩ kake ka nyaĩĩ.'),
('kam', 'PSA', 132, 8, 'Ũkĩla, ame Yeova, ũlike vandũ vaku va kũthũmũa; We, na ĩsandũkũ ya vinya waku.'),
('kam', 'PSA', 132, 9, 'Athembi maku nĩmavw’ĩkwe ũlũngalu; Na atheu maku nĩmokĩlye mawasya na ũtanu.'),
('kam', 'PSA', 132, 10, 'Kwondũ wa mũthũkũmi waku Ndaviti Ndũkathyũũe ũthyũ wa mwĩtĩkĩw’a mauta waku.'),
('kam', 'PSA', 132, 11, 'Yeova nĩwĩvĩtĩe Ndaviti w’o; Ndakamwĩthyũĩa: Ma ũsyao wa mwĩĩ waku ngamekalya kĩvĩlanĩ kyaku kya ũsumbĩ.'),
('kam', 'PSA', 132, 12, 'Ethĩwa syana syaku ikakwata ũtianĩo wakwa Na ũkũsĩ wakwa ũla ngaimanyĩsya, O na syana syasyo nikekalaa kĩvĩlanĩ kyaku kya ũsumbĩ tene na tene.'),
('kam', 'PSA', 132, 13, 'Nũndũ Yeova nũnyuvĩte Saioni; Nũmyendete yĩthĩwe ũtũo wake.'),
('kam', 'PSA', 132, 14, 'Vaa nĩ vandũ vakwa va ũthũmũa tene na tene: Ngekalaa vaa; nũndũ nĩnĩvendete.'),
('kam', 'PSA', 132, 15, 'Ngaathima sya ũya sya vo mũno: Ngavũn’ya ngya sya vo na lĩu'),
('kam', 'PSA', 132, 16, 'O na ngavw’ĩka athembi ma vo ũtangĩĩo; Na atheu ma vo makookĩlya mawasya manene na ũtanu.'),
('kam', 'PSA', 132, 17, 'Vu ngathongooesya ũvya wa Ndaviti: Nĩniĩte taa kwondũ wa mwĩtĩkĩw’a mauta wakwa.'),
('kam', 'PSA', 132, 18, 'Amaitha make ngamavw’ĩka nthoni; Ĩndĩ ngovia yake ya ũsumbĩ ĩkaathimĩka ĩũlũ wake mwene.'),
('kam', 'PSA', 133, 1, 'Sisyai, ũndũ ũseo ũnenevete na ũndũ ũseũvĩte Ana‐a‐asa mekalan’ya vamwe me ũmwe!'),
('kam', 'PSA', 133, 2, 'Nĩ ta ala mauta maĩ vata mũno me mũtwe, Ala matheeie kĩng’ew’anĩ, O kĩng’ew’anĩ kya Aluni; Ala matheeie kũvika mĩthyanĩ ya ngũa syake;'),
('kam', 'PSA', 133, 3, 'Ta ĩmwe ya kĩĩma kya Elimoni, Yĩla yĩtheeaa iĩmanĩ sya Saioni: Nũndũ ku Yeova nĩweaĩie ũathimo, O thayũ wa tene na tene.'),
('kam', 'PSA', 134, 1, 'Sisyai, mũtaĩei Yeova, inyw’onthe athũkũmi ma Yeova, Ala mũũngamaa ũtukũ nyũmbanĩ ya Yeova.'),
('kam', 'PSA', 134, 2, 'Ũkĩlyai moko menyu melekele vala vandũ vatheu, Na mũtaĩei Yeova.'),
('kam', 'PSA', 134, 3, 'Yeova nakũathime e Saioni; O ũla watw’ĩkĩthisye ĩtu na nthĩ.'),
('kam', 'PSA', 135, 1, 'Mũtaĩei Yeova. Taĩai syĩtwa ya Yeova: Mũtaĩei, inyw’ĩ athũkũmi ma Yeova,'),
('kam', 'PSA', 135, 2, 'Inyw’ĩ ala mũũngamaa nyũmbanĩ ya Yeova Nthĩnĩ wa nza sya nyũmba ya Ngai waitũ.'),
('kam', 'PSA', 135, 3, 'Mũtaĩei Yeova; nũndũ Yeova nĩ mũseo: Inai mũkĩkumya syĩtwa yake; nũndũ ũũ nĩ ũseo.'),
('kam', 'PSA', 135, 4, 'Nũndũ Yeova nĩwenyuvĩe Yakovo, Na Isilaeli ethĩwe wake mwene.'),
('kam', 'PSA', 135, 5, 'Nũndũ nĩnĩsĩ Yeova nĩ mũnene, Na Mwĩaĩi waitũ e ĩũlũ wa ngai syonthe.'),
('kam', 'PSA', 135, 6, 'Ũndũ o na wĩva ũla Yeova wendie, now’o wekie, Ĩtunĩ na nthĩ, maũkanganĩ na syũngũnĩ syonthe;'),
('kam', 'PSA', 135, 7, 'Ũla ũtumaa mũki kwambata kuma itulunĩ sya nthĩ; Ũla ũseũvĩasya mbua motisi; Ũla wumasya kĩseve ũthwiinĩ wake;'),
('kam', 'PSA', 135, 8, 'Ũla woaie kĩla kyasyaĩtwe mbee kya nthĩ ya Misili, Kya mũndũ o na nyamũ;'),
('kam', 'PSA', 135, 9, 'Ũla waetie syama na moseng’yo katĩ waku, we Misili, Ĩũlũ wa Valao, na ĩũlũ wa athũkũmi make onthe;'),
('kam', 'PSA', 135, 10, 'Ũla wakũnie mbaĩ nyingĩ, Na woaie asumbĩ maĩ na ũtonyi,'),
('kam', 'PSA', 135, 11, 'Sioni mũsumbĩ wa Aamoli, Na Oku mũsumbĩ wa Mbasani, Na mosumbĩ onthe ma Kanaani,'),
('kam', 'PSA', 135, 12, 'Na anengane nthĩ yoo yĩthĩwe ũtiĩwa, Ũtiĩwa wa Isilaeli andũ make.'),
('kam', 'PSA', 135, 13, 'Syĩtwa yaku, ame Yeova, nĩyĩkalaa tene na tene; Syĩtwa yaku ya ũlilikan’yo, ame Yeova, mosyaanĩonĩ onthe.'),
('kam', 'PSA', 135, 14, 'Nũndũ Yeova akasilĩla andũ make, Na kwĩtũnga ũndũ wa athũkũmi make.'),
('kam', 'PSA', 135, 15, 'Mĩvw’anano ya i mbaĩ nĩ vetha na thaavu, Wĩa wa moko ma andũ.'),
('kam', 'PSA', 135, 16, 'Yĩ na makanyw’a, ĩndĩ ndĩneenaa; Yĩ na metho, ĩndĩ ndĩonaa;'),
('kam', 'PSA', 135, 17, 'Yĩ na matũ, ĩndĩ ndĩw’aa; O na kũti mĩthũmũ nongi makanyw’anĩ mayo.'),
('kam', 'PSA', 135, 18, 'Ala mamĩseũvasya makeethĩwa mailyĩ tayo; Ĩĩ, kĩla mũndũ ũla ũmĩĩkĩĩaa.'),
('kam', 'PSA', 135, 19, 'We nyũmba ya Isilaeli, taĩai Yeova: We nyumba ya Aluni, taĩai Yeova:'),
('kam', 'PSA', 135, 20, 'We nyũmba ya Livai, taĩai Yeova: Inyw’ĩ ala mũkĩaa Yeova, taĩai Yeova.'),
('kam', 'PSA', 135, 21, 'Nataĩwe Yeova ku Saioni, Ũla ũtũaa Yelusaleme. Mũtaĩei Yeova.'),
('kam', 'PSA', 136, 1, 'Mũtũngĩei Yeova mũvea; nũndũ nĩ mũseo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 136, 2, 'Mũtũngĩei mũvea Ngai wa i ngai; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 136, 3, 'Mũtũngĩei mũvea Mwĩaĩi wa eaĩi; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 136, 4, 'We ũla e weka wĩkaa moseng’yo manene; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 5, 'Ũla ũndũ wa ũmanyi watw’ĩkĩthisye matu; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 6, 'Ũla walanilye nthĩ ĩũlũ wa manzĩ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 7, 'Ũla wombie syeni nene; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 8, 'Syũa ya kũsumbĩka mũthenya; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 9, 'Mwei na ndata sya kũsumbĩka ũtukũ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 10, 'Ũla wakũnie Misili makithathinĩ moo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 11, 'Na aumisye Isilaeli katĩ woo; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 12, 'Na kw’oko kwĩ vinya, na kw’oko kũtambũũku; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 13, 'Ũla waaanĩlye Ũkanga Mũtune katĩ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 14, 'Na avĩtĩlya Isilaeli katĩ waw’o; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 15, 'Ĩndĩ aanangĩa Valao na nguthu yake Ũkanganĩ Mũtune; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 16, 'Ũla watongoesye andũ make weũnĩ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 17, 'Ũla wakũnie asumbĩ anene; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 18, 'Na kũaa asumbĩ me nguma; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 19, 'Sioni mũsumbĩ wa Aamoli; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 20, 'Na Oku mũsumbĩ wa Mbasani; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 21, 'Na anengane nthĩ yoo yĩthĩwe ũtiĩwa; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 22, 'O ũtiĩwa wa Isilaeli mũthũkũmi wake; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 23, 'Ũla watũlilikanile tũte ndaĩa; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene;'),
('kam', 'PSA', 136, 24, 'Na nũtũvonoketye kuma nthũnĩ sitũ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene:'),
('kam', 'PSA', 136, 25, 'Ũla ũnengae mĩĩ yonthe lĩu; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 136, 26, 'Mũtũngĩei mũvea Ngai wa ĩtunĩ; Nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene.'),
('kam', 'PSA', 137, 1, 'Ndee sya mbũsĩ sya Mbaviloni, Twekalile nthĩ ku, ĩĩ, twaĩa, Yĩla twalilikanile Saioni.'),
('kam', 'PSA', 137, 2, 'Mĩtĩnĩ ĩla ĩmeaa katĩ wasyo Nĩtwanĩkie mbeve sitũ.'),
('kam', 'PSA', 137, 3, 'Nũndũ kw’o ala matũtwaie matũtavĩte matũkũlilye mbathi, Na ala matwanangie menda tũtane, makyasya, Twinĩei wathi ũmwe wa Saioni.'),
('kam', 'PSA', 137, 4, 'Twina ata wathi wa Yeova Twĩ nthĩ ĩngĩ?'),
('kam', 'PSA', 137, 5, 'Ethĩwa ngoolwa nue, we Yelusaleme, Kw’oko kwakwa kwa aũme nĩkũlwe nĩ ũĩ wakw’o.'),
('kam', 'PSA', 137, 6, 'Ũĩmĩ wakwa nũlũman’ye na kaakaa wa kanyw’a wakwa, Ethĩwa ndikũlilikana; Ethĩwa ndikwenda Yelusaleme Kũvĩtũka ũtanu wakwa ũla mũnene mbee.'),
('kam', 'PSA', 137, 7, 'Ame Yeova, lilikanĩla syana sya Etomu Mũthenya wa Yelusaleme; Ila syaisye, Myanange, myanange, O na kũvika wambĩlĩlyo wayo.'),
('kam', 'PSA', 137, 8, 'We mwĩĩtu wa Mbaviloni, ũla wĩ wa kwanangwa, Akeethĩwa mũtanu, ũla wĩkũĩva O tondu we watwĩkie.'),
('kam', 'PSA', 137, 9, 'Akeethĩwa mũtanu, ũla wĩosa na kũng’atangan’ya twana twaku tũnini Ĩvianĩ.'),
('kam', 'PSA', 138, 1, 'Ngakũtũngĩa mũvea na ngoo yakwa yonthe: Ngaina ngĩũkumĩsya mbee wa i ngai.'),
('kam', 'PSA', 138, 2, 'Ngathaitha nelekele ĩkalũ yaku ĩtheu, Na kũtũngĩa mũvea syĩtwa yaku nũndũ wa ũseo waku wĩ wendo na nũndũ wa w’o waku: Nũndũ nũnenevetye ndeto yaku kwĩ syĩtwa yaku yonthe.'),
('kam', 'PSA', 138, 3, 'Mũthenya ũla neetanie now’o wanzũngĩie, Nĩwanũnũmĩlye na vinya ngoonĩ yakwa.'),
('kam', 'PSA', 138, 4, 'Asumbĩ onthe ma nthĩ makakũtũngĩa mũvea, we Yeova, Nũndũ nĩmew’ĩte ndeto sya kanyw’a waku.'),
('kam', 'PSA', 138, 5, 'Ĩĩ, makaina ũndũ wa nzĩa sya Yeova; Nũndũ ũtheu mũtisu wa Yeova nĩ mũnene.'),
('kam', 'PSA', 138, 6, 'Nũndũ o na kau Yeova e ĩũlũ, no wonaa ala enyivya; Ĩndĩ ũla wĩnenevasya nũmwĩsĩ e kũasa.'),
('kam', 'PSA', 138, 7, 'O na ngĩendela thĩnanĩ, ũkambuũkya; Ũkatambũũkĩsya kw’oko kwaku ũthilĩku wa amaitha makwa, Na kw’oko kwaku kwa aũme kũkandangĩĩa.'),
('kam', 'PSA', 138, 8, 'Yeova akeanĩasya maũndũ makwa: Ũseo waku wĩ wendo, ame Yeova, nĩwĩkalaa tene na tene; Ndũkatie mawĩa ma moko maku mwene.'),
('kam', 'PSA', 139, 1, 'Ame Yeova, nĩwĩnguũĩte, na ũkamanya nyie.'),
('kam', 'PSA', 139, 2, 'Nĩwĩsĩ kwĩkala nthĩ kwakwa, na kũkĩla kwakwa; Nũmanyaa ũsũanĩo wakwa wĩ kũasa.'),
('kam', 'PSA', 139, 3, 'Nũthianaa nzĩa yakwa na kũkoma kwakwa, Nĩwĩsĩ nzĩa syakwa syonthe.'),
('kam', 'PSA', 139, 4, 'Nũndũ vati ndeto ũĩmĩnĩ wakwa, Ũtamĩsĩ vyũ, ame Yeova.'),
('kam', 'PSA', 139, 5, 'Nũnziĩĩĩte ĩtina na mbee, Na kũmbilĩĩla kw’oko kwaku.'),
('kam', 'PSA', 139, 6, 'Ũmanyi ta ũsu nĩ ũseng’yo kũmbĩtũka; Nĩ mũtũlu, nditonya kũũkwata.'),
('kam', 'PSA', 139, 7, 'Nithi ku nume vala ve Veva waku? Kana nĩkĩĩa va nume vala ũĩ?'),
('kam', 'PSA', 139, 8, 'Ethĩwa ngambata ĩtunĩ, wĩ vo; Ethiwa ngalan’ya ũkomo wakwa Seoli, sisya, wĩ vo.'),
('kam', 'PSA', 139, 9, 'Ethĩwa ngoosa nthwau sya kĩoko, Na kwĩkalaa itulunĩ sya ũkanga;'),
('kam', 'PSA', 139, 10, 'O na vo kw’oko kwaku kũkandongoesya, Na kw’oko kwaku kwa aũme kũkangwata.'),
('kam', 'PSA', 139, 11, 'Ethĩwa ngasya, Nĩ w’o kĩvindu kĩkambw’ĩka, Na kyeni kĩla kĩnthyũlũlũkĩte kĩkeethĩwa ũtukũ;'),
('kam', 'PSA', 139, 12, 'O na kĩvindu kĩtikwĩvitha, Ĩndĩ ũtukũ nũtisaa o ta mũthenya: Kĩvindu na kyeni syelĩ no ũndũ ũmwe kwaku.'),
('kam', 'PSA', 139, 13, 'Nũndũ nĩwambũmbie ilungu sya nthĩnĩ: Nĩwambw’ĩkie ĩvunĩ ya mwaitũ.'),
('kam', 'PSA', 139, 14, 'Ngakũtũngĩa mũvea; nũndũ nũmbĩtwe wa kũkĩwa na kũseng’ya: Mawĩa maku nĩ ma ũseng’ya; Na ũu ngoo yakwa nĩyĩsĩ nesa ki.'),
('kam', 'PSA', 139, 15, 'Wũmbe wakwa ndwaakũvithwa, Yĩla noombiwe kĩmbithĩnĩ, Na kũthalanĩlw’a kũndũ kwĩ nthĩnĩ wa nthĩ.'),
('kam', 'PSA', 139, 16, 'Metho maku nĩmoonie ndanombĩka; Na ĩvukunĩ yaku mamutha nĩmaandĩkĩtwe onthe, O mĩthenya ĩla yeaĩtwe ũndũ wakwa, Yĩla kũtaĩ ũmwe wamo.'),
('kam', 'PSA', 139, 17, 'O na mosũanĩo maku ũndũ mean’ya vata kũla nĩĩ, ame Ngai! Ũtalo wamo ũndũ ũnenevete!'),
('kam', 'PSA', 139, 18, 'Ethĩwa ngamatala, nĩ maingĩ kũvĩta kĩthangathĩ: O ngĩamũka, nĩ o naku.'),
('kam', 'PSA', 139, 19, 'Vate ndĩi ũkooaa ala athũku, we Ngai: Kwondũ wa ũu umai vala nĩĩ, inyw’ĩ andũ ala mũng’aatũkaw’a nĩ nthakame.'),
('kam', 'PSA', 139, 20, 'Nũndũ nĩmeũkũneenea naĩ, Na amaitha maku nĩmawetaa syĩtwa yaku mana.'),
('kam', 'PSA', 139, 21, 'Ndimamenaa, ame Yeova ala makũmenaa? Na ndyĩw’ĩthaw’a woo nĩ ala makũkĩlĩĩlaa?'),
('kam', 'PSA', 139, 22, 'Nĩngũmamena na kĩmena kĩanĩu: Nĩmatw’ĩkĩte amaitha makwa.'),
('kam', 'PSA', 139, 23, 'Nthiana, ame Ngai, na manya ngoo yakwa: Ndata, na manya mosũanĩo makwa;'),
('kam', 'PSA', 139, 24, 'Noisisya ethĩwa ve nzĩa nthũku nthĩnĩ wakwa, Noindongoeasya nzĩanĩ ya tene na tene.'),
('kam', 'PSA', 140, 1, 'Ame Yeova, mbonokya kwa mũndũ mũthũku; Nzũvĩa kwa mũndũ mũng’endu:'),
('kam', 'PSA', 140, 2, 'Ala masũanĩaa mothũku ngoonĩ syoo; Ĩndĩ yonthe nĩmekwĩyũmban’ya mokite.'),
('kam', 'PSA', 140, 3, 'Nĩmoĩvĩtye nĩmĩ syoo ta sya nzoka; Ũoi wa syĩmbuva wĩ ungu wa ilomo syoo.'),
('kam', 'PSA', 140, 4, 'Nzũvĩa, ame Yeova, kuma mokonĩ ma ũla mũthũku; Nzũvĩa kwa mũndũ mũng’endu: Ala masũanĩĩte kwelelũkasya matambya makwa.'),
('kam', 'PSA', 140, 5, 'Ekathĩĩi nĩmavithĩte kĩtei kwondũ wakwa, o na ndii; Nĩmalaanĩtye kĩtei ũtee wa nzĩa; Nĩmaiĩte mĩkwa mangwatye.'),
('kam', 'PSA', 140, 6, 'Neie Yeova, Nue Ngai wakwa: Ĩthukĩĩsye wasya wa mawĩsũvano makwa, ame Yeova.'),
('kam', 'PSA', 140, 7, 'Ame Yeova Mwĩaĩi, vinya wa ũtangĩĩo wakwa, Nũmbw’ĩkĩte mũtwe wakwa mũthenya wa kaũ.'),
('kam', 'PSA', 140, 8, 'Ame Yeova, ndũkanenge ũla mũthũku ũndũ ũnũkwenda; Ndũkatethye ũsũanĩo wake mũthũku, matikese kwĩnenevya.'),
('kam', 'PSA', 140, 9, 'Ũndũ wa mĩtwe ya ala manthyũlũlũkĩte, Ũthũku wa ilomo syoo ene ũmavw’ĩke.'),
('kam', 'PSA', 140, 10, 'Makaa makanu nĩmamavalũkĩle: Nĩmekw’e mwakinĩ, Maimanĩ maliku, vala matakauma.'),
('kam', 'PSA', 140, 11, 'Ũla ũneenaa ũthũku ndakekale nthĩ: Ũthũku ũkamantha mũndũ mũng’endu ũmwanange.'),
('kam', 'PSA', 140, 12, 'Nĩnĩsĩ Yeova akamalũlũmĩlĩlasya ala mathĩnaa ũvoo woo, Na sila wa katĩ kwondũ wa athĩni.'),
('kam', 'PSA', 140, 13, 'Vate ndĩi ala alũngalu makatũngĩaa syĩtwa yaku mũvea: Ala alũngalu makatũaa vala ũĩ.'),
('kam', 'PSA', 141, 1, 'Yeova, nĩnĩkwĩkaĩlĩte; ĩkalaate wũke vala nĩĩ: Ĩthukĩĩsye wasya wakwa, yĩla ngũkwĩkaĩla.'),
('kam', 'PSA', 141, 2, 'Mboya yakwa nĩyambate mbee waku ta ũvani; Kũkĩlya kwa moko makwa ta nthembo ya wĩoo.'),
('kam', 'PSA', 141, 3, 'Ame Yeova, ia mũsũvĩi mbee wa kanyw’a wakwa; Sũvĩa mũomo wa ilomo syakwa.'),
('kam', 'PSA', 141, 4, 'Ndũkaeke ngoo yakwa yelekele ũndũnĩ ũthũku o na wĩva, Yĩkae meko ma ũthũku Vamwe na ala mekaa ũthũku: Na ndũkandeke nĩye kya ũya kyoo kĩseo.'),
('kam', 'PSA', 141, 5, 'Ũla mũlũngalu nangũne, kũkeethĩwa kũseo; Na nangan’ye, kũkeethĩwa ta mauta ĩũlũ wa mũtwe; Mũtwe wakwa ndũkalee ũu: Nũndũ o na ũthũkunĩ woo ngaendeea na mboya yakwa.'),
('kam', 'PSA', 141, 6, 'Asili moo nĩmavalũkĩtw’e ndee sya ĩvia; Na makeew’a ndeto syakwa; nũndũ syĩ mũyo.'),
('kam', 'PSA', 141, 7, 'O tondũ mũndũ wĩnzaa na kũtilanga mavali, Now’o mavĩndĩ maitũ manyaĩĩkĩte kanyw’anĩ wa Seoli.'),
('kam', 'PSA', 141, 8, 'Nũndũ metho makwa nĩmakũsyaĩĩsye, ame Yeova Mwĩaĩi: Nĩvithaa nthĩnĩ waku; ndũkaatie thayũ wakwa wĩ mũthei.'),
('kam', 'PSA', 141, 9, 'Nzũvĩaa kĩtei kĩla mandeete, Na itei sya eki ma ũthũku.'),
('kam', 'PSA', 141, 10, 'Ala athũku nĩmavalũke iteinĩ syoo ene, Nakwa ngĩvonoka.'),
('kam', 'PSA', 142, 1, 'Nĩmwĩkaĩlaa Yeova na wasya wakwa; Nĩmwĩsũvaa Yeova na wasya wakwa.'),
('kam', 'PSA', 142, 2, 'Nonoasya mũnyungunyĩsyo wakwa mbee wake; Nonanasya thĩna wakwa mbee wake.'),
('kam', 'PSA', 142, 3, 'Yĩla veva wakwa wanthelekele, We nĩweesĩ nzĩa yakwa. Nzĩanĩ ĩla nĩendelaa Nĩmavithĩte kĩtei ũndũ wakwa.'),
('kam', 'PSA', 142, 4, 'Sisya kw’oko kwakwa kwa aũme, wone; Nũndũ vati mũndũ ũla ũmbĩsĩ: Wĩvitho nũmbaĩe; Vai mũndũ ũnũkũũngana na thayũ wakwa.'),
('kam', 'PSA', 142, 5, 'Nĩnakwĩkaĩlile, ame Yeova; Naisye, Nue wĩvitho wakwa, Kĩanda kyakwa nthĩ ya ala me thayũ.'),
('kam', 'PSA', 142, 6, 'Ĩthukĩĩsye kũkaya kwakwa; Nũndũ nĩnyivĩtw’e mũno: Mbonokya kwa ala manthĩnasya; Nũndũ me vinya kwĩ nyie.'),
('kam', 'PSA', 142, 7, 'Umya thayũ wakwa kolokolonĩ, Nĩ kana nĩtũngĩe syĩtwa yaku mũvea: Ala alũngalu makanthyũlũlũka; Ĩndĩ ũkambĩka na ũlau.'),
('kam', 'PSA', 143, 1, 'Ĩw’a mboya yakwa, ame Yeova; ĩthukĩĩsye mawĩsũvano makwa: Nzũngĩa kwondũ wa kĩthito kyaku, na ũlũngalu waku.'),
('kam', 'PSA', 143, 2, 'Na ndũkakwatye sila na mũthũkũmi waku; Nũndũ methonĩ maku vai mũndũ wĩ thayũ mũlũngalu.'),
('kam', 'PSA', 143, 3, 'Nũndũ mũmaitha nũthĩnĩtye ngoo yakwa; Nũkũnĩte thayũ wakwa ũkavika nthĩ: Nũmbĩkalĩtye kũndũ kwĩ kĩvindu, ta ala makwie tene.'),
('kam', 'PSA', 143, 4, 'Kwondũ wa ũu veva wakwa nũthelekele nthĩnĩ wakwa; Ngoo yakwa nthĩnĩ nĩnĩkũũũya.'),
('kam', 'PSA', 143, 5, 'Nĩngũlilikana mĩthenya ya tene; Nĩngũsũanĩa meko maku onthe; Nĩngũsũanĩa wĩa wa moko maku.'),
('kam', 'PSA', 143, 6, 'Nĩngũkũtambũũkĩsya moko makwa: Ngoo yakwa yĩ na waũni ũndũ waku, ta nthĩ nyũmũ.'),
('kam', 'PSA', 143, 7, 'Ĩkalaate kũnzũngĩa, ame Yeova; veva wakwa nũũthelekela: Ndũkambithe ũthyũ waku, Ndikese ũtw’ĩka ta ala matheeaa yĩla ĩimanĩ.'),
('kam', 'PSA', 143, 8, 'Mbĩw’ĩthasya ũseo waku wĩ wendo kĩoko; Nũndũ nĩngũĩkĩĩaa: Manyĩthasya nzĩa ĩla naĩle kũendelaa; Nũndũ nĩngũkĩlĩlasya ngoo yakwa.'),
('kam', 'PSA', 143, 9, 'Ame Yeova, mbonokya kwa amaitha makwa: Nĩngũkĩĩa kwaku ũmbithe.'),
('kam', 'PSA', 143, 10, 'Manyĩsya kwĩka kwenda kwaku; Nũndũ nue Ngai wakwa: Veva waku nĩ mũseo; Ndongoeasya nthĩ ya ũlũngalu.'),
('kam', 'PSA', 143, 11, 'Nthayũũkya, ame Yeova, kwondũ wa syĩtwa yaku: Kwondũ wa ũlũngalu waku umya thayũ wakwa thĩnanĩ.'),
('kam', 'PSA', 143, 12, 'Na kwondũ wa ũseo waku wĩ wendo veta amaitha makwa, Na ananga onthe ala mathĩnasya thayũ wakwa; Nũndũ nyie nĩ mũthũkũmi waku.'),
('kam', 'PSA', 144, 1, 'Nataĩwe Yeova ĩvia yakwa, Ũla ũmanyĩasya moko makwa kaũ, Na syaa syakwa kũkita:'),
('kam', 'PSA', 144, 2, 'Nue ũseo wakwa wĩ wendo, na ngome yakwa, Mwako wakwa mũtũlu wa mũnyoolo, na mũvonokya wakwa; Ngao yakwa, na ũla nĩvithaa nthĩnĩ wake; Ũla ũnyivĩasya andũ makwa methĩwe ungu wakwa.'),
('kam', 'PSA', 144, 3, 'Yeova, mũndũ nĩ mwaũ, ũndũ ũũngana nake? Kana mwana wa mũndũ, ũndũ ũmũlilikana?'),
('kam', 'PSA', 144, 4, 'Mũndũ nĩ ta mũvevo: Mĩthenya yake nĩ ta muunyĩ ũla ũvĩtaa.'),
('kam', 'PSA', 144, 5, 'Inamya matu maku, ame Yeova, noitheea: Kiita iĩma, na ikatoa syũki.'),
('kam', 'PSA', 144, 6, 'Tisĩthya ũtisi, na kũmanyaĩĩkya; Ĩkya mĩsyĩ yaku, na kũmathokoan’ya.'),
('kam', 'PSA', 144, 7, 'Tambũũkya kw’oko kwaku kuma ĩũlũ; Ndangĩĩa, na mbonokya kuma manzĩnĩ maingĩ, Kuma kw’okonĩ kwa andũ ma nthĩ ĩngĩ;'),
('kam', 'PSA', 144, 8, 'Ala maneenaa ũkengani na makanyw’a moo, Na kw’oko kwoo kwa aũme nĩ kw’oko kwa aũme kwa ũvũngũ.'),
('kam', 'PSA', 144, 9, 'Ngakwinĩa wathi weũ, ame Yeova: Ngakũkumya na kĩnanda kĩ ndii ĩkũmi.'),
('kam', 'PSA', 144, 10, 'Nue ũla ũnengae asumbĩ ũtangĩĩo; Ũla ũtangĩĩaa Ndaviti mũthũkũmi waku ũvyũnĩ mwai.'),
('kam', 'PSA', 144, 11, 'Ndangĩĩa, na kũmbonokya kuma kw’okonĩ kwa andũ ma nthĩ ĩngĩ, Ala maneenaa ũkengani na makanyw’a moo, Na kw’oko kwoo kwa aũme nĩ kw’oko kwa aũme kwa ũvũngũ.'),
('kam', 'PSA', 144, 12, 'Yĩla ana maitũ makethĩwa ta mĩkenge meanĩte wananĩ woo, Na eĩtu maitũ ta mavia ma ikotonĩ masũvĩtw’e ta mũvw’ano wa nyũmba nene mbanakavye;'),
('kam', 'PSA', 144, 13, 'Yĩla makũmbĩ maitũ mausũĩte, me na mĩthemba yonthe ya lĩu, Na malondu maitũ maisyanĩaa ngili, na ngili makũmi isesinĩ sitũ;'),
('kam', 'PSA', 144, 14, 'Yĩla ng’ombe sitũ ikuĩte mĩio mũno; Yĩla vate kũvithũkĩwa, kana kũkuthũanw’a, Na vate kĩĩo nzĩanĩ sitũ nene:'),
('kam', 'PSA', 144, 15, 'Nĩ atanu andũ ala me maũndũnĩ mailyĩ ũu; Ĩĩ, nĩ atanu andũ ala Ngai woo nĩ Yeova.'),
('kam', 'PSA', 145, 1, 'Ngakũnenevya, Ngai wakwa, we Mũsumbĩ; Na ngataĩa syĩtwa yaku tene na tene.'),
('kam', 'PSA', 145, 2, 'Kĩla mũthenya ngakũtaĩaa; Na ngataĩaa syĩtwa yaku tene na tene.'),
('kam', 'PSA', 145, 3, 'Yeova, nĩ mũnene, na wa kũtaĩwa mũno; Na ũnene wake ndũmanthĩka.'),
('kam', 'PSA', 145, 4, 'Nzyawa ĩmwe ĩkataĩĩthasya mawĩa maku kwa nzyawa ĩngĩ, Na kũtavanasya meko maku me ũtonyi.'),
('kam', 'PSA', 145, 5, 'Ngasũanĩaa ũnene mũnene wa ndaĩa yaku, Na mawĩa maku ma ũseng’ya.'),
('kam', 'PSA', 145, 6, 'Na andũ makaneenaa ũndũ wa ũtonyi wa meko maku ma kũtĩsya; Nakwa ngatavanasya ũnene waku.'),
('kam', 'PSA', 145, 7, 'Makawetaa ũlilikan’yo wa ũseo waku mũnene, Na kwinaa ũndũ wa ũlũngalu waku.'),
('kam', 'PSA', 145, 8, 'Yeova nĩ mũseo, na e tei; Mũmĩĩsya wa kũthata, na wa ũseo mwingĩ wĩ wendo.'),
('kam', 'PSA', 145, 9, 'Yeova nĩ mũseo kwa onthe; Na matei make mololo me ĩũlũ wa mawĩa make onthe.'),
('kam', 'PSA', 145, 10, 'Mawĩa maku onthe makakũtũngĩaa mũvea, ame Yeova; Na atheu maku makakũtaĩaa.'),
('kam', 'PSA', 145, 11, 'Makawetaa ndaĩa ya ũsumbĩ waku, Na kũneenaa ũndũ wa vinya waku;'),
('kam', 'PSA', 145, 12, 'Nĩ kana mamanyĩthye ana ma andũ meko make me ũtonyi, Na ndaĩa ya ũnene wa ũsumbĩ wake;'),
('kam', 'PSA', 145, 13, 'Ũsumbĩ waku nĩ ũsumbĩ wa tene na tene, Na ũsumbĩko waku nĩwĩkalaa mosyaanĩonĩ onthe.'),
('kam', 'PSA', 145, 14, 'Yeova nũũngamasya onthe ala mavalũkaa, Na kũkĩlya onthe ala makunamĩte.'),
('kam', 'PSA', 145, 15, 'Metho ma onthe nĩmeũkweteela; Na nũmanengae lĩu woo ĩvinda yaw’o.'),
('kam', 'PSA', 145, 16, 'Nũũkũnzũa ũvĩ waku, Na kwĩanĩsya kwenda kwa kĩla kĩndũ kĩ thayũ.'),
('kam', 'PSA', 145, 17, 'Yeova nĩ mũlũngalu nzĩanĩ syake syonthe, Na nĩ mũseo mawĩanĩ make onthe.'),
('kam', 'PSA', 145, 18, 'Yeova e vakuvĩ na onthe ala mamwĩkaĩlaa, Onthe ala mamwĩkaĩlaa na w’o.'),
('kam', 'PSA', 145, 19, 'Akeanĩasya kwenda kwa ala mamũkĩaa; O na akeew’a kũkaya kwoo, na kũmatangĩĩa.'),
('kam', 'PSA', 145, 20, 'Yeova nũsũvĩaa onthe ala mamwendaa; Ĩndĩ ala athũku onthe akamananga.'),
('kam', 'PSA', 145, 21, 'Kanyw’a wakwa ũkaneena ndaĩa ya Yeova; Na mĩĩ yonthe nĩtaĩe syĩtwa yake ĩtheu tene na tene.'),
('kam', 'PSA', 146, 1, 'Mũtaĩei Yeova. Taĩa Yeova, ngoo yakwa.'),
('kam', 'PSA', 146, 2, 'Yĩla nĩ thayũ ngataĩaa Yeova: Ngamwĩnĩaa Ngai wakwa ndaĩa yĩla nĩ thayũ.'),
('kam', 'PSA', 146, 3, 'Ndũkaĩkĩĩe anene me mbee ũsumbĩnĩ, Kana mwana wa mũndũ, ũla ũtatonya kũtethya.'),
('kam', 'PSA', 146, 4, 'Mĩthũmũ yake nĩyumaa, nake nũsyokaa mũthanganĩ wake; Mũthenya o ũsu mosũanĩo make nĩmaaa.'),
('kam', 'PSA', 146, 5, 'Nĩ mũtanu ũla wĩ na Ngai wa Yakovo wa kũmũtethya, Ũla wĩkwatyo wake wĩ vala ve Yeova Ngai wake:'),
('kam', 'PSA', 146, 6, 'Ũla watw’ĩkĩthisye ĩtu na nthĩ. Na ũkanga, na syonthe ila syĩ nthĩnĩ wasyo; Ũla ũlũmasya w’o tene na tene;'),
('kam', 'PSA', 146, 7, 'Ũla ũsilaa sila wa katĩ kwondũ wa ala mathĩnaw’a; Ula ũnengae ala me na nzaa lĩu. Yeova nũthaasya ovwa;'),
('kam', 'PSA', 146, 8, 'Yeova nũsalukasya metho ma ilalinda; Yeova nĩũkĩlasya ala makunamĩte; Yeova nũmendaa ala alũngalu;'),
('kam', 'PSA', 146, 9, 'Yeova nũsũvĩaa ekali ma ũeninĩ; Nũũngamasya ũla wakw’ĩĩwe nĩ ĩthe na ndiwa; Ĩndĩ nzĩa ya ala athũku nũkulumanasya.'),
('kam', 'PSA', 146, 10, 'Yeova akasumbĩkaa tene na tene, Ngai waku, we Saioni, kũvika nzyawa syonthe. Mũtaĩei Yeova.'),
('kam', 'PSA', 147, 1, 'Mũtaĩei Yeova; Nũndũ nĩ ũseo kũmũkumya Ngai waitũ; Nũndũ nĩkwendeeasya, na ndaĩa nĩ nzeo.'),
('kam', 'PSA', 147, 2, 'Yeova nĩwakaa Yelũsaleme; Nĩwũmbanasya alũngw’a ma Isilaeli.'),
('kam', 'PSA', 147, 3, 'Nũvoasya ala matũlĩkile ngoo, Na kwova mawũkite moo.'),
('kam', 'PSA', 147, 4, 'Nũtalaa ndata ũndũ syĩana; Nũsyĩtaa syonthe na masyĩtwa masyo.'),
('kam', 'PSA', 147, 5, 'Mwĩaĩi waitũ nĩ mũnene, na e vinya ũtonyinĩ; Ũmanyi wake ndũthimĩka.'),
('kam', 'PSA', 147, 6, 'Yeova nũũngamasya ala auu: Nũmatheeasya nthĩ ala athũku.'),
('kam', 'PSA', 147, 7, 'Mwinĩei Yeova na mũvea; Mwinĩei Ngai waitũ ndaĩa na mbeve,'),
('kam', 'PSA', 147, 8, 'Ũla ũvw’ĩkaa matu mathweo, Ũla ũseũvĩasya nthĩ mbua, Ũla ũmeasya nyeki iĩmanĩ.'),
('kam', 'PSA', 147, 9, 'Nũnengae nyamũ lĩu wayo, O na tũswii twa ngũngũũ tũla tũũkaya.'),
('kam', 'PSA', 147, 10, 'Ndatanaw’a nĩ vinya wa mbalasi: Ndendeeaw’a nĩ maũũ ma mũndũ.'),
('kam', 'PSA', 147, 11, 'Yeova nĩwendeeaw’a nĩ ala mamũkĩaa, Ala mekwatasya ũseo wake wĩ wendo.'),
('kam', 'PSA', 147, 12, 'Taĩa Yeova, we Yelusaleme; Taĩa Ngai waku, we Saioni.'),
('kam', 'PSA', 147, 13, 'Nũndũ nũsyĩkĩĩte vinya ivingi sya mbingĩlo syaku; Nũathimĩte syana syaku ila syĩ nthĩnĩ waku.'),
('kam', 'PSA', 147, 14, 'Nũtumaa mũuo mĩvakanĩ yaku; Nũkũvũnasya na nganũ ila nzeo mbee.'),
('kam', 'PSA', 147, 15, 'Nũetae mwĩao wake ĩũlũ wa nthĩ; Ndeto yake nĩsembaa mĩtũkĩ mũno.'),
('kam', 'PSA', 147, 16, 'Nũnenganae ĩa ta w’ĩa wa malondu; Nũnyaĩĩkasya ĩmwe yĩkamĩtw’e nĩ mbevo ta mũu.'),
('kam', 'PSA', 147, 17, 'Nĩwĩkasya manzĩ make momĩtw’e nĩ mbevo me tũlungu: Nũũ ũtonya kũũngama mbee wa mbevo yake?'),
('kam', 'PSA', 147, 18, 'Nũetae ndeto yake, natw’o tũitweka: Nũuutanĩthasya kĩseve kyake, na manzĩ maivĩta.'),
('kam', 'PSA', 147, 19, 'Nĩwonanasya ndeto yake kwa Yakovo, Na myamũlo yake na motw’ĩo make kwa Isilaeli.'),
('kam', 'PSA', 147, 20, 'Ndaaĩka mbaĩ o na yĩva ta ũu; Na ũndũ wa motw’ĩo make, ityaamamanya. Mũtaĩei Yeova.'),
('kam', 'PSA', 148, 1, 'Mũtaĩei Yeova. Mũtaĩĩei Yeova kuma matunĩ; Mũtaĩĩei motũlunĩ.'),
('kam', 'PSA', 148, 2, 'Mũtaĩei, inyw’ĩ alaĩka make onthe: Mũtaĩei, nguthu yake yonthe.'),
('kam', 'PSA', 148, 3, 'Mũtaĩei, syũa na mwei: Mũtaĩei, inyw’onthe ndata sya kyeni.'),
('kam', 'PSA', 148, 4, 'Mũtaĩei, inyw’ĩ matu ala me ĩũlũ wa matu, Na inyw’ĩ manzĩ ala mwĩ ĩũlũ wa matu.'),
('kam', 'PSA', 148, 5, 'Nitaĩe syĩtwa ya Yeova; Nũndũ we nĩweaie, na syoombĩka.'),
('kam', 'PSA', 148, 6, 'O na nĩwilũlũmĩlĩtye tene na tene: Nũtw’ĩte ũtw’ĩo ũla ũtakavĩta.'),
('kam', 'PSA', 148, 7, 'Taĩai Yeova kũũ nthĩ, Inyw’ĩ mĩkũnga mĩnene ya ũkanganĩ, o na syũngũ syonthe;'),
('kam', 'PSA', 148, 8, 'Mwaki na mbua ya mavia, ĩa na mũki; Kĩseve kĩnene, ikĩanĩsya ndeto yake;'),
('kam', 'PSA', 148, 9, 'Iĩma na tũlĩma tw’onthe; Mĩtĩ yĩ ũsyao na mĩtĩ ya mĩkũũ yonthe;'),
('kam', 'PSA', 148, 10, 'Nyamũ na indo syonthe; Tũsamũ tũla tũtambũkaa na nyũnyi ila iũlũkaa;'),
('kam', 'PSA', 148, 11, 'Asumbĩ ma nthĩ na ngo syonthe sya andũ; Anene me mbee ũsumbĩnĩ na asili onthe ma nthĩ;'),
('kam', 'PSA', 148, 12, 'Anake o na eĩtu atheu; Atumĩa na syana:'),
('kam', 'PSA', 148, 13, 'Nĩmataĩe syĩtwa ya Yeova; Nũndũ syĩtwa yake yoka nĩ ĩnenevye; Ũtheu mũtisu wake wĩ ĩũlũ wa nthĩ na matu.'),
('kam', 'PSA', 148, 14, 'Nĩwũkĩlĩtye ũvya wa andũ make, Ndaĩa ya atheu make onthe; O na ya ana ma Isilaeli, ũko wa andũ ũla wĩ vakuvĩ nake. Mũtaĩei Yeova.'),
('kam', 'PSA', 149, 1, 'Mũtaĩei Yeova. Mũkumyei Yeova na wathi weũ, Na inĩai ndaĩa yake ũmbanonĩ wa atheu.'),
('kam', 'PSA', 149, 2, 'Isilaeli namũtanĩe ũla wamũmbie: Syana sya Saioni nitane ũndũ wa mũsumbĩ woo.'),
('kam', 'PSA', 149, 3, 'Nitaĩe syĩtwa yake ikĩsũnga: Nĩsine ikĩmũtaĩa na kĩthembe na mbeve.'),
('kam', 'PSA', 149, 4, 'Nũndũ Yeova nũtanĩaa andũ make: Akaanakavya ala auu na ũtangĩĩo.'),
('kam', 'PSA', 149, 5, 'Atheu nĩmekathĩĩe ndaĩanĩ: Nĩmaine ũndũ wa ũtanu me mokomonĩ moo.'),
('kam', 'PSA', 149, 6, 'Motaĩo manene ma Ngai methĩwe makanyw’anĩ moo, Na ũvyũ mũĩ ngalĩ syelĩ mokonĩ moo;'),
('kam', 'PSA', 149, 7, 'Meĩvanĩsye kwa i mbaĩ, Na mosilĩlo ĩũlũ wa ngo sya andũ;'),
('kam', 'PSA', 149, 8, 'Move asumbĩ moo na mĩnyololo, Na anene moo me ndaĩa na mbĩngũ;'),
('kam', 'PSA', 149, 9, 'Meanĩsye ũsilĩlo ĩũlũ woo ũla ũandĩkĩtwe: Ndaĩa ĩno yĩ na atheu make onthe. Mũtaĩei Yeova.'),
('kam', 'PSA', 150, 1, 'Mũtaĩei Yeova. Mũtaĩĩei Ngai vandũnĩ vake vatheu: Mũtaĩĩei ku yayayanĩ ya vinya wake.'),
('kam', 'PSA', 150, 2, 'Mũtaĩei ũndũ wa meko make me ũtonyi: Mũtaĩei kwĩanana na ũnene wake mũnene.'),
('kam', 'PSA', 150, 3, 'Mũtaĩei na wasya wa soo: Mũtaĩei na kĩnanda na mbeve.'),
('kam', 'PSA', 150, 4, 'Mũtaĩei na kĩthembe na kũsũnga: Mũtaĩei na syĩndũ sya kũinga syĩ ndii, na mũtũlilũ.'),
('kam', 'PSA', 150, 5, 'Mũtaĩei na tũmasaya twĩ wasya mũnene: Mũtaĩei na tũmasaya twĩ wasya mũtũlu mũno.'),
('kam', 'PSA', 150, 6, 'Kĩla kĩndũ kĩ mĩthũmũ nĩkĩtaĩe Yeova. Mũtaĩei Yeova.'),
('kam', 'PRO', 1, 1, 'Nthimo sya Solomoni mwana wa Ndaviti, mũsumbĩ wa Isilaeli:'),
('kam', 'PRO', 1, 2, 'Kũmanya ũĩ na ũmanyĩsyo; Kũvathũkan’ya ndeto sya ũmanyi;'),
('kam', 'PRO', 1, 3, 'Kwosa ũmanyĩsyo wa kwĩka ũĩ, Na wa ũlũngalu na wa ũsili wa w’o na katĩ;'),
('kam', 'PRO', 1, 4, 'Kũmũnenga ũla ũte ũmanyi kĩlĩko, Na mwanake ũmanyi na kĩlĩko:'),
('kam', 'PRO', 1, 5, 'Nĩ kana mũndũ ũla mũĩ ew’e, na kwongeleka kwosa momanyĩsyo; Na nĩ kana mũndũ wa ũmanyi akwate motao meanĩu:'),
('kam', 'PRO', 1, 6, 'Kũmanya nthimo, na ũalyũlo wayo, Ndeto sya andũ oĩ, na ndaĩ syoo.'),
('kam', 'PRO', 1, 7, 'Kũmũkĩa Yeova nĩ wambĩlĩlyo wa ũmanyi; Ĩndĩ ala atumanu mavũthasya ũĩ na ũmanyĩsyo.'),
('kam', 'PRO', 1, 8, 'Mwana wakwa, ĩw’a ũmanyĩsyo wa ĩthe waku, Na ndũkaatie mĩao ya inyia waku:'),
('kam', 'PRO', 1, 9, 'Nũndũ makeethĩwa ta ngovia ya mumo mũtwenĩ waku, Na mĩnyoo ngingonĩ yaku.'),
('kam', 'PRO', 1, 10, 'Mwana wakwa, ethĩwa andũ athe nĩmeũkũsengasenga, Ndũketĩkĩle.'),
('kam', 'PRO', 1, 11, 'Ethĩwa makakwĩa, Ũka tũendan’ye, Twoveesye twĩtĩkye nthakame; Twoveesye kĩmbithĩnĩ ala mate na ĩvĩtyo vate kĩtumi;'),
('kam', 'PRO', 1, 12, 'Tũmamelye me thayũ ta Seoli, Na me aima, ta ala matheeaa yĩla iĩmanĩ;'),
('kam', 'PRO', 1, 13, 'Tũkoona syĩndũ syonthe syĩ vata mũno; Tũkausũsya nyũmba sitũ na mũtavo:'),
('kam', 'PRO', 1, 14, 'Ũkekye mũlimano waku vamwe naitũ; Ithyonthe tũkeethĩwa na ngusu ĩmwe:'),
('kam', 'PRO', 1, 15, 'Mwana wakwa, ndũkaendan’ye nzĩanĩ wĩ namo, Siĩĩa kũũ kwaku nzĩanĩ syoo:'),
('kam', 'PRO', 1, 16, 'Nũndũ maũũ moo masembaa meke ũthũku, Na mekalaataa metĩkye nthakame.'),
('kam', 'PRO', 1, 17, 'Nũndũ nĩ mana kũtambũũkya kĩtei Nyũnyi yene:'),
('kam', 'PRO', 1, 18, 'Na asu moveeasya nthakame yoo ene; Moveeasya na kĩmbithĩ mathayũ moo ene.'),
('kam', 'PRO', 1, 19, 'Nĩ w’o itilyĩ nzĩa sya kĩla ũmwe wĩ na ĩtomo ya ũtandĩthyo; Nĩyĩvetaa thayũ wa ene mayo.'),
('kam', 'PRO', 1, 20, 'Ũĩ nũkayĩaa na wasya mũnene nzĩanĩ nene; Nĩumĩasya wasya waw’o kũndũnĩ kwaamu;'),
('kam', 'PRO', 1, 21, 'Nũkayĩaa vandũ va ndaĩa va kũmbanĩa; Ũlikĩlonĩ wa mbingĩlo, Nthĩnĩ wa ndũa, nĩumĩasya ndeto syaw’o:'),
('kam', 'PRO', 1, 22, 'Inyw’ĩ mũte ũmanyi, mũkenda kũtamanya kwenyu kũvika ĩndĩĩ? Na akaakaan’ya matanĩa kũkaakaasyanĩ kwoo, Na ndia kũmena ũmanyi?'),
('kam', 'PRO', 1, 23, 'Ĩthyũũe kwondũ wa kũkanw’a ninyie: Sisyai, ngoonosya veva wakwa ĩũlũ wenyu; Ngamũmanyĩthya ndeto syakwa.'),
('kam', 'PRO', 1, 24, 'Nĩkwĩthĩwa nĩnĩtanĩte, na nĩmũleete; Nĩnĩtambũũkĩtye kw’oko kwakwa, na vati mũndũ ũsisya;'),
('kam', 'PRO', 1, 25, 'Ĩndĩ nĩmũtw’ĩte motao makwa onthe mana, Na mũtikwĩtĩkĩla mokan’yo makwa:'),
('kam', 'PRO', 1, 26, 'O nakwa ngatheka mũthenyanĩ wa wanangĩko wenyu mũnene; Ngavũa ngũĩ yĩla w’ĩa wenyu wĩũka;'),
('kam', 'PRO', 1, 27, 'Yĩla w’ĩa wenyu wĩũka ta kĩlingi, Na wanangĩko wenyu mũnene wĩũka ta kĩlingi; Yĩla monyamao na woo mũnene meũka ĩũlũ wenyu.'),
('kam', 'PRO', 1, 28, 'Nĩvo ĩndĩ makengaĩla, ĩndĩ ndikasũngĩa; Makamantha na kĩthing’ĩĩsyo, ĩndĩ matikambona.'),
('kam', 'PRO', 1, 29, 'Nũndũ nĩmamenie ũmanyi, Na matyaanyuva kũkĩa Yeova,'),
('kam', 'PRO', 1, 30, 'Matyaaĩtĩkĩla motao makwa, Nĩmavũthisye mokan’yo makwa onthe.'),
('kam', 'PRO', 1, 31, 'Kwondũ wa ũu makaya ũsyao wa mĩendele yoo ene, Na kusũwa nĩ mĩtavyo yoo ene.'),
('kam', 'PRO', 1, 32, 'Nũndũ kũsyoka na ĩtina kwa ala mate ũmanyi kũkamoaa, Na kalengo ka ndia kakasyananga.'),
('kam', 'PRO', 1, 33, 'Ĩndĩ o ũla ũmbĩthukĩĩsya akatũaa eyelelye, Na akekala athũmũĩte vate w’ĩa wa ũthũku.'),
('kam', 'PRO', 2, 1, 'Mwana wakwa, ethĩwa ũkakwata ndeto syakwa, Na kwiaa mĩao yakwa nthĩnĩ waku,'),
('kam', 'PRO', 2, 2, 'O na kũtea kũtũ kwaku wose ũĩ, Na kũnengana ngoo yaku ũmanyinĩ;'),
('kam', 'PRO', 2, 3, 'Ĩĩ, ethĩwa ũkaĩĩa kũvathũkan’ya kũseo, Na kũkĩlya wasya waku wone ũmanyi;'),
('kam', 'PRO', 2, 4, 'Ethĩwa ũkoomantha ta vetha, Na kũmantha ta syĩndũ mbithe syĩ vata mũno:'),
('kam', 'PRO', 2, 5, 'Nĩvo ĩndĩ wĩmanya kũmũkĩa Yeova, Na kwona ũĩ wa Ngai.'),
('kam', 'PRO', 2, 6, 'Nũndũ Yeova nũnenganae ũĩ; Kanyw’anĩ wake vaumaa ũmanyĩsyo na ũmanyi:'),
('kam', 'PRO', 2, 7, 'Aiaa ũĩ mwĩanĩu kwondũ wa ala alũngalu; Nake nĩ ngao kwa ala maendaa wĩanĩunĩ;'),
('kam', 'PRO', 2, 8, 'Kana atonye kũsũvĩa nzĩa sya ũsili wa katĩ, Na kũsũvĩaa mĩendele ya atheu make.'),
('kam', 'PRO', 2, 9, 'Nĩvo ĩndĩ wĩmanya ũlũngalu na usili wa w’o, Na katĩ, ĩĩ, kĩla nzĩa nzeo.'),
('kam', 'PRO', 2, 10, 'Nũndũ ũĩ ũkalika ngoonĩ yaku, Na ũmanyi ũkendeesya ngoo yaku;'),
('kam', 'PRO', 2, 11, 'Kĩlĩko kĩkakũsyaĩĩasya; Ũmanyi ũkakũsũvĩaa:'),
('kam', 'PRO', 2, 12, 'Kũũvonokya kuma mĩendelenĩ mĩthũku, Kuma andũnĩ ala maneenaa maũndũ ma ngũlũ;'),
('kam', 'PRO', 2, 13, 'Ala matiaa nzĩa sya ũlũngalu, Maendae mĩendelenĩ ya kĩvindu;'),
('kam', 'PRO', 2, 14, 'Ala matanaw’a nĩ kwĩka ũthũku, Na kwendeew’a nĩ ngũlũ ya ũla mũthũku;'),
('kam', 'PRO', 2, 15, 'Ala athyoekangu mĩendelenĩ yoo, Na me na ngũlũ nzĩanĩ syoo:'),
('kam', 'PRO', 2, 16, 'Kũũvonokya kwa mũndũ mũka mũeni, O kwa ũsu wa nthĩ ĩngĩ ũla wendeeasya na ndeto syake sya ũkathĩĩo;'),
('kam', 'PRO', 2, 17, 'Ũla wũlawa nĩ mũnyanyae wake wa ũika wake, Na wũlawa nĩ ũtianĩo wa Ngai wake:'),
('kam', 'PRO', 2, 18, 'Nũndũ nyũmba yake yangĩe kĩkw’ũnĩ, Na nzĩa syake kwa ala akw’ũ;'),
('kam', 'PRO', 2, 19, 'Kũti waasyoka ĩngĩ alika kwake, O na kũvikĩa nzĩa sya thayũ:'),
('kam', 'PRO', 2, 20, 'Nĩ kana ũende mũendelenĩ wa andũ aseo, Na kũkwata nzĩa sya alũngalu.'),
('kam', 'PRO', 2, 21, 'Nũndũ ala alũngalu makatũa ĩ nthĩ, Na ala eanĩu makamĩkalaa.'),
('kam', 'PRO', 2, 22, 'Ĩndĩ ala athũku makavetwa kuma ĩ nthĩ, Na nzeleke ikakũanĩw’a na mĩi syume nthĩnĩ wayo.'),
('kam', 'PRO', 3, 1, 'Mwana wakwa, ndũkolwe nĩ mĩao yakwa; Ĩndĩ ngoo yaku nĩlũmye mĩao yakwa:'),
('kam', 'PRO', 3, 2, 'Nũndũ ĩkakwongeleela mĩthenya mingĩ, Na myaka ya thayũ na mũuo,'),
('kam', 'PRO', 3, 3, 'Ndũkaaĩtĩkĩle ũseo na w’o ikũtie: Syoveee ngingonĩ yaku; Iandĩke ĩsengeanĩ ya ngoo yaku:'),
('kam', 'PRO', 3, 4, 'Na ĩndĩ ũkoona ũseo na ũmanyi mũseo Methonĩ ma Ngai na ma mũndũ.'),
('kam', 'PRO', 3, 5, 'Ĩkĩĩa Yeova na ngoo yaku yonthe, Na ndũkekwatye ũmanyi waku mwene:'),
('kam', 'PRO', 3, 6, 'Mĩendelenĩ yaku yonthe mũkũsĩĩe we, Na akaũlũngalĩlya nzĩa syaku.'),
('kam', 'PRO', 3, 7, 'Ndũkethĩwe na ũĩ wa metho maku mwene; Mũkĩe Yeova, na ũitia ũthũku:'),
('kam', 'PRO', 3, 8, 'Ũkakwĩkĩa vinya mũkonyo waku, Na mũthungo mavĩndĩ maku.'),
('kam', 'PRO', 3, 9, 'Mũtaĩe Yeova na syĩndũ syaku, Na ũsyao wa mbee wa wingĩvo waku w’onthe:'),
('kam', 'PRO', 3, 10, 'Na kwondũ wa ũu makũmbĩ maku makausũwa nĩ wingĩ, Na maviva maku makausũa na kũng’okwa nĩ mbinyu mbĩthĩ.'),
('kam', 'PRO', 3, 11, 'Mwana wakwa, ndũkavũthye makũna ma Yeova; O na ndũkanow’e nĩ mokan’yo make:'),
('kam', 'PRO', 3, 12, 'Nũndũ ũla Yeova ũmwendaa nũmũkanasya, O tondũ ĩthe wĩkaa mwana ũla ũtanaa kwondũ wake.'),
('kam', 'PRO', 3, 13, 'Mũndũ nĩ mũtanu ũla wonaa ũĩ, Na mũndũ ũla ũkwataa ũmanyi.'),
('kam', 'PRO', 3, 14, 'Nũndũ kwĩthĩwa naw’o kwĩ kavaa kwĩ kwĩthĩwa na vetha, Na ũtandĩthyo waw’o kwĩ thaavu ũla mũseo.'),
('kam', 'PRO', 3, 15, 'Wĩ na vata mũno kwĩ tũvila twa maliani: Na vati kĩmwe kya syĩndũ ila ũtonya kwenda kĩtonya kũvw’ananw’a naw’o.'),
('kam', 'PRO', 3, 16, 'Mĩthenya mingĩ yĩ kw’okonĩ kwaw’o kwa aũme; Kw’okonĩ kwaw’o kwa aka ve mothwii na ndaĩa.'),
('kam', 'PRO', 3, 17, 'Mĩendele yaw’o nĩ mĩendele ya kwendeesya, Na nzĩa syaw’o syonthe nĩ sya mũuo.'),
('kam', 'PRO', 3, 18, 'Nĩ mũtĩ wa thayũ kwa ala mokwataa: Na kĩla ũmwe nĩ mũtanu ũla wĩkalaa naw’o.'),
('kam', 'PRO', 3, 19, 'Yeova kwondũ wa ũĩ nĩwakwatisye wambĩlĩlyo wa nthĩ; Kwondũ wa ũmanyi nĩwalũlũmĩlye matu.'),
('kam', 'PRO', 3, 20, 'Kwondũ wa ũmanyi wake syũngũ nĩsyavingũkie, Na matu nĩmavolotangasya ĩmwe.'),
('kam', 'PRO', 3, 21, 'Mwana wakwa, ndũkaeke syume methonĩ maku; Sũvĩa ũĩ mwĩanĩu na kĩlĩko:'),
('kam', 'PRO', 3, 22, 'Kwondũ wa ũu ikeethĩwa thayũ wa ngoo yaku, Na mumo ngingonĩ yaku.'),
('kam', 'PRO', 3, 23, 'Nĩvo ĩndĩ wĩendaa mĩendelenĩ yaku wĩyelele, Na kũũ kwaku kũtikalulutĩka.'),
('kam', 'PRO', 3, 24, 'Yĩla wĩkoma, ndũkakĩa: Ĩĩ, ũkakoma, na too waku ũkeethĩwa wĩ mũyo.'),
('kam', 'PRO', 3, 25, 'Ndũkakĩe w’ĩa wa kĩthũlũmũko, O na wanangĩko wa ala athũku, yĩla wĩũka:'),
('kam', 'PRO', 3, 26, 'Nũndũ Yeova akeethĩwa ũĩkĩĩi waku, Na akakũsũvĩa kũũ kwaku kũikakwatw’e.'),
('kam', 'PRO', 3, 27, 'Ndũkamaime ũndũ ũseo ala maĩlwe nĩw’o, Yĩla wĩ ũtonyinĩ wa kw’oko kwaku wa kũwĩka.'),
('kam', 'PRO', 3, 28, 'Ndũkatavye mũtũi waku, Enda, na ũkyũka ĩngĩ, Na ũnĩ ngakũnenga; Naku nũkwete ĩ kĩndũ.'),
('kam', 'PRO', 3, 29, 'Ndũkasũanĩĩe mũtũi waku ũthũku, Nũndũ atwĩe eyelele vakuvĩ naku.'),
('kam', 'PRO', 3, 30, 'Ndũkatetan’ye na mũndũ vate kĩtumi, Ethĩwa ndakwĩkĩte ũthũku.'),
('kam', 'PRO', 3, 31, 'Ndũkamwĩw’ĩe kĩwĩu mũndũ wa ũng’endu, Na ndũkanyuve o na ũmwe wa mĩendele yake.'),
('kam', 'PRO', 3, 32, 'Nũndũ ũla wĩ ngũlũ nĩ ũthatyo kwa Yeova; Ĩndĩ ũnyanya wake nĩ wake na ũla mũlũngalu.'),
('kam', 'PRO', 3, 33, 'Kĩumo kya Yeova kĩ nyũmbanĩ ya ũla mũthũku; Ĩndĩ nũathimaa ũtũo wa ala alũngalu.'),
('kam', 'PRO', 3, 34, 'Vate ndĩi nũvũthasya ala mavũthasya; Ĩndĩ anengae mumo ala menyivasya.'),
('kam', 'PRO', 3, 35, 'Ala oĩ makatiĩwa ndaĩa; Ĩndĩ nthoni ikeethĩwa ũnene wa ndia.'),
('kam', 'PRO', 4, 1, 'Ĩw’ai, ana makwa, ũmanyĩsyo wa ĩthe, Na ĩnenganei mũmanye ũmanyi:'),
('kam', 'PRO', 4, 2, 'Nũndũ nĩngũmũnenga ũmanyĩsyo mũseo; Mũtikatie mĩao yakwa.'),
('kam', 'PRO', 4, 3, 'Nũndũ naĩ mwana kwa ĩthe wakwa, Mwololo na ũla mwende methonĩ ma mwaitũ.'),
('kam', 'PRO', 4, 4, 'Na amanyĩisye, na ambĩa: Ngoo yaku yĩkale na ndeto syakwa; Kwata mĩao yakwa, na ĩthĩwa thayũ;'),
('kam', 'PRO', 4, 5, 'Ĩyosee ũĩ, ĩyosee ũmanyi; Ndũkolwe, ndũkatiũũke kuma ndetonĩ sya kanyw’a wakwa;'),
('kam', 'PRO', 4, 6, 'Ndũkaotie, na ũkakwĩkalasya; Wende, na ũkakũsũvĩaa.'),
('kam', 'PRO', 4, 7, 'Ũĩ nĩ ũndũ ũnene mbee; kwondũ wa ũu ĩyosee ũĩ; Ĩĩ, na vamwe na kwosa kwaku kw’onthe ĩyosee ũmanyi.'),
('kam', 'PRO', 4, 8, 'Ũnenevye, naw’o ũkakũnenevya; Ũkakũete ndaĩanĩ, yĩla wĩwĩvĩtĩĩsya.'),
('kam', 'PRO', 4, 9, 'Ũkanenga mũtwe waku ngovia ya mumo; Ngovia ya ũsumbĩ ya ũseo ũkakũnenga.'),
('kam', 'PRO', 4, 10, 'Ĩw’a, we mwana wakwa, na osa ndeto syakwa; Na myaka ya thayũ waku ĩkeethĩwa mingĩ.'),
('kam', 'PRO', 4, 11, 'Nĩnaũmanyĩsya nzĩanĩ ya ũĩ; Nĩnaũtongoesya nzĩanĩ sya ũlũngalu.'),
('kam', 'PRO', 4, 12, 'Yĩla wĩendeeaa, matambya maku matikavivinyawa; Na ethĩwa nũkũsemba, ndũkalulutĩka.'),
('kam', 'PRO', 4, 13, 'Kwata ũlũmye ũmanyĩsyo; ndũkaeke ũthi: Ũsũvĩe; nũndũ nĩ thayũ waku.'),
('kam', 'PRO', 4, 14, 'Ndũkalike nzĩanĩ ya ala athũku, Na ndũkathi mũendelenĩ wa andũ athũku.'),
('kam', 'PRO', 4, 15, 'Myathũkĩe, ndũkamĩvĩtĩle; Ĩthyũũe kũmyuma, na endeea na mbee.'),
('kam', 'PRO', 4, 16, 'Nũndũ matikoma, ate o kwĩka ũthũku; Na too woo nũvetawa, ethĩwa mativalũkasya amwe.'),
('kam', 'PRO', 4, 17, 'Nũndũ maĩsaa lĩu wa ũthũku, Na kũnyw’a mbinyu ya ũng’endu.'),
('kam', 'PRO', 4, 18, 'Ĩndĩ nzĩa ya alũngalu nĩ ta kyeni kya kũikya, Kĩla kĩkenaa mbee na mbee kũvika mũthenya mwĩanĩu.'),
('kam', 'PRO', 4, 19, 'Mũendele wa ũthũku nĩ ta kĩvindu: Matyĩsĩ kĩla kĩmalulutĩkasya.'),
('kam', 'PRO', 4, 20, 'Mwana wakwa, ĩthukĩĩsye ndeto syakwa; Tea kũtũ kwaku wĩw’e ndeto syakwa.'),
('kam', 'PRO', 4, 21, 'Itikaaume methonĩ maku; Syĩkalye ngoonĩ yaku nthĩnĩ.'),
('kam', 'PRO', 4, 22, 'Nũndũ nĩsyo thayũ kwa ala masyonaa, Na vinya wa mĩĩ yoo yonthe.'),
('kam', 'PRO', 4, 23, 'Ĩkalya ngoo yaku na ũthangaau w’onthe; Nũndũ maũndũ ma thayũ maumaa kwayo.'),
('kam', 'PRO', 4, 24, 'Veta kwaku kanyw’a wĩ ũng’endu, Na ilomo syĩ ngũlũ veta kũasa naku.'),
('kam', 'PRO', 4, 25, 'Metho maku masisye o mbee ki, Na ilomo sya itho yaku ikĩsisya syelekele mbee waku.'),
('kam', 'PRO', 4, 26, 'Tindimalya nzĩa ya nyaĩĩ syaku, Na mĩendele yaku yonthe ĩthĩwe ĩmĩlũlũmĩlye.'),
('kam', 'PRO', 4, 27, 'Ndũkaaĩthyũũe ngalĩ ya kw’oko kwa aũme kana kwa aka: Umya kũũ kwaku ũthũkunĩ.'),
('kam', 'PRO', 5, 1, 'Mwana wakwa, ĩthukĩĩsye ũĩ wakwa; Tea kũtũ kwaku wose ũmanyi wakwa:'),
('kam', 'PRO', 5, 2, 'Nĩ kana ũtonye kũsũvĩa kĩlĩko, Na kana ilomo syaku itonye kũlũmya ũmanyi.'),
('kam', 'PRO', 5, 3, 'Nũndũ ilomo sya mũndũ mũka mũeni ilovotangasya ũkĩ wa nzũkĩ, Na kanyw’a wake nĩ mũtendeu kwĩ mauta:'),
('kam', 'PRO', 5, 4, 'Ĩndĩ mũminũkĩlyonĩ e ũũ ta mũtĩ wĩ ũũ, Mũĩ ta ũvyũ mũĩ ngalĩ syelĩ.'),
('kam', 'PRO', 5, 5, 'Maũũ make matheeaa kĩkw’ũnĩ; Matambya make malũmanĩtye na Seoli;'),
('kam', 'PRO', 5, 6, 'Kwondũ wa ũu ndonaa nzĩa ndindimalu ya thayũ: Mĩendele yake ti mĩlũmu, na ndamanya ũu.'),
('kam', 'PRO', 5, 7, 'Na yu kwondũ wa ũu, ana makwa, mbĩthukĩĩsyei, Na mũikatie ndeto sya kanyw’a wakwa.'),
('kam', 'PRO', 5, 8, 'Veta mũendele waku kũasa nake, Na ndũkathi vakuvĩ na mũomo wa nyũmba yake;'),
('kam', 'PRO', 5, 9, 'Ndũkese kũnenga angĩ ndaĩa yaku, Na myaka yaku ala ai;'),
('kam', 'PRO', 5, 10, 'Aeni matikese kusũwa nĩ vinya waku, Na mawĩa maku kwĩthĩwa nyũmbanĩ ya mũndũ wa nthĩ ĩngĩ,'),
('kam', 'PRO', 5, 11, 'Naku ũkesa kũĩa mũminũkĩlyonĩ waku, Yĩla nyama syaku na mwĩĩ waku ikathela,'),
('kam', 'PRO', 5, 12, 'Na kwasya, Ũndũ namenete ũmanyĩsyo, Na ngoo yakwa yavũthĩtye ũkan’yo;'),
('kam', 'PRO', 5, 13, 'O na ndaaĩthukĩĩsya wasya wa amanyĩsya makwa, Kana kũtea kũtũ kwakwa kwa ala mandaaa!'),
('kam', 'PRO', 5, 14, 'Natielye o vanini nĩthĩwe ũthũkunĩ w’onthe Nĩ nthĩnĩ wa ũmbano na ĩkomano.'),
('kam', 'PRO', 5, 15, 'Nyusaa manzĩ kuma kĩthimanĩ kyaku mwene kĩla kyakĩtwe, Na manzĩ ala mavĩtaa kuma kĩthimanĩ kyaku mwene.'),
('kam', 'PRO', 5, 16, 'Mbuluti syaku nĩsyaĩle kũnyaĩĩkw’a kũũ na kũũ, Na tũlũsĩ twa manzĩ nzĩanĩ nene?'),
('kam', 'PRO', 5, 17, 'Methĩwe kwondũ waku wĩ weka, Na ti kwondũ wa aeni ala me kwaku.'),
('kam', 'PRO', 5, 18, 'Nthongo yaku nĩathimwe; Noitanĩa kĩveti kyaku kya ũthoo.'),
('kam', 'PRO', 5, 19, 'Ta ndaatai nga yĩ wendo na ngondi nga yendeeasya, Nondo syakyo nikwĩanĩae mavinda onthe; Naku ũtanĩthaw’e mavinda onthe nĩ wendo wakyo.'),
('kam', 'PRO', 5, 20, 'Nũndũ nĩkĩ we, mwana wakwa, ũtanĩthaw’a nĩ kĩveti kĩeni, Na kũvĩtĩanĩsya kĩthũi na ũla wa nthĩ ĩngĩ?'),
('kam', 'PRO', 5, 21, 'Nũndũ mĩendele ya mũndũ yĩ mbee wa metho ma Yeova; Na nũtindimalasya nzĩa syake syonthe.'),
('kam', 'PRO', 5, 22, 'Mothũku make mwene makakwata ũla mũthũku, Na akalũmw’a nĩ ndii sya naĩ yake.'),
('kam', 'PRO', 5, 23, 'Akakw’a ũndũ wa kwaa ũmanyĩsyo; Na ũtumanunĩ wake mũnene akaa.'),
('kam', 'PRO', 6, 1, 'Mwana wakwa, ethĩwa nũtw’ĩkĩte mũĩkĩĩwa kwa mũtũi waku, Ethĩwa nĩwakwatanie moko maku na mũeni;'),
('kam', 'PRO', 6, 2, 'Nũkwatĩtw’e nĩ ndeto sya kanyw’a waku, Nũtwaĩtwe nĩ ndeto sya kanyw’a waku.'),
('kam', 'PRO', 6, 3, 'Ĩka ũũ yu, mwana wakwa, na ũkĩvonokya mwene, Nũndũ nĩwalika kw’okonĩ kwa mũtũi waku: Enda, wĩnyivye, noimwĩsũva mũtũi waku;'),
('kam', 'PRO', 6, 4, 'Ndũkaeke metho maku makome, Kana kwombosya kwa ilomo sya metho maku;'),
('kam', 'PRO', 6, 5, 'Ĩvonokye ta kĩlong’a kuma kw’okonĩ kwa mũsyĩmi, Na ta nyũnyi kuma kw’okonĩ kwa mũtei wayo.'),
('kam', 'PRO', 6, 6, 'Enda vala ve nditikũ, we ũla mũtulu; Syaĩĩsya mĩkĩle yasyo, na ũkyũĩva:'),
('kam', 'PRO', 6, 7, 'Ila ite mũnene, Mũsyaĩĩsya kana mũsumbĩki'),
('kam', 'PRO', 6, 8, 'Syĩyiĩaa lĩu wasyo ĩvinda ya syũa, Na kwĩyũmbanĩsya lĩu wayo ĩvinda ya ngetha.'),
('kam', 'PRO', 6, 9, 'Ũkakoma kũvika ĩndĩĩ, we mũtulu? Ũkookĩla kuma toonĩ waku ĩndĩĩ?'),
('kam', 'PRO', 6, 10, 'No kũkomanga vanini, kwombosya vanini, O vanini kũkwatan’ya syaa na kũkoma:'),
('kam', 'PRO', 6, 11, 'O ta ũu ũkya waku ũkooka ta mũvutani, Na kwaĩwa kwaku ta mũndũ wĩkĩĩte mĩio ya kaũ.'),
('kam', 'PRO', 6, 12, 'Mũndũ ũte vata, mũndũ wa ũthũku, Nĩ ũla ũendaa na kanyw’a wĩ ngũlũ;'),
('kam', 'PRO', 6, 13, 'Ũla ũvenanĩasya na metho make, ũla ũneenaa na maũũ make, Ũla wonanasya na syaa syake;'),
('kam', 'PRO', 6, 14, 'Ũla ngoonĩ yake ve ngũlũ, Ũla ũsũanĩaa ũthũku ĩndĩ yonthe, Ũla ũvuĩaa kĩthokoo.'),
('kam', 'PRO', 6, 15, 'Kwondũ wa ũu wanangĩko wake mũnene ũkooka na kĩthũlũmũko; O mĩtũkĩ akaanangĩka vate mũiito.'),
('kam', 'PRO', 6, 16, 'Ve maũndũ thanthatũ ala Yeova ũmenete; Ĩĩ, mũonza ala me ũthatyo kwake:'),
('kam', 'PRO', 6, 17, 'Metho me mĩtũlyo, ũĩmĩ ũla ũneenaa ũvũngũ, Moko ala metĩkasya nthakame ĩte ĩvĩtyo;'),
('kam', 'PRO', 6, 18, 'Ngoo ĩla ĩsũanĩaa maũndũ mathũku, Maũũ ala mekalaataa kwĩka ũthũku,'),
('kam', 'PRO', 6, 19, 'Ngũsĩ ya ũvũngũ ĩla ĩneenaa movũngũ, Na ũla ũvuĩaa kĩthokoo katĩ wa ana‐aasa.'),
('kam', 'PRO', 6, 20, 'Mwana wakwa, kwata mwĩao wa ĩthe waku, Na ndũkatie mwĩao wa inyia waku:'),
('kam', 'PRO', 6, 21, 'Myoveee ngoonĩ yaku ĩndĩ yonthe; Myoveee ngingonĩ yaku.'),
('kam', 'PRO', 6, 22, 'Yĩla wĩendaa ĩkakũtongoeasya; Yĩla wĩkomaa, ĩkakũsyaĩĩasya; Na yĩla wĩamũkaa, ĩkaneenaa naku.'),
('kam', 'PRO', 6, 23, 'Nũndũ mwĩao nĩ taa; na mĩao nĩ kyeni; Na mokan’yo ma ũmanyĩsyo nĩ nzĩa ya thayũ:'),
('kam', 'PRO', 6, 24, 'Kũkũsũvĩa vala ve mũndũ mũka mũthũku, Kwa kwendeesya na ndeto sya ũkathĩĩo kwa ũĩmĩ wa mũndũ wa nthĩ ĩngĩ.'),
('kam', 'PRO', 6, 25, 'Ndũkew’ĩe mũmbĩlwe wake mũseo ĩtomo ngoonĩ yaku; O na ndũketĩkĩle akũkwate na ilomo sya metho make.'),
('kam', 'PRO', 6, 26, 'Nũndũ wa ĩlwaya mũndũ mũũme nũvikaa vala ũtonya kwaĩwa nĩ kalungu ka mũkate; Na kĩlaalai nĩkĩsyĩmaa thayũ ũla wĩ vata mũno.'),
('kam', 'PRO', 6, 27, 'Mũndũ nũtonya kũkua mwaki kĩthũinĩ kyake, Na ngũa syake ikalea kũvya?'),
('kam', 'PRO', 6, 28, 'Kana mũndũ nũtonya kũkinyĩla ĩũlũ wa makaa me mwaki, Na maũũ make makalea kũvya?'),
('kam', 'PRO', 6, 29, 'No ta ũu ũla ũlikaa kwa kĩveti kya mũtũi wake; O ũla ũkĩkiita ndatĩa kũsilĩlwa.'),
('kam', 'PRO', 6, 30, 'Andũ mativũthasya kĩng’ei, ethĩwa kĩũya Ũndũ wa kwĩyĩanĩsya yĩla kĩ na nzaa:'),
('kam', 'PRO', 6, 31, 'Ĩndĩ ethĩwa kĩkakwatwa, kĩkatũnga kũndũ mũonza; Kĩkanengane syĩndũ syonthe sya nyũmba yakyo.'),
('kam', 'PRO', 6, 32, 'Ũla wĩkaa ũlaalai na mũndũ mũka nde na ũmanyi: Ũla ũkwenda kwananga ngoo yake mwene nũwĩkaa.'),
('kam', 'PRO', 6, 33, 'Mawũkite na kwanangĩwa ndaĩa akakwata, Na kũvũthw’a kwake kũtikavangũlĩka.'),
('kam', 'PRO', 6, 34, 'Nũndũ kĩwĩu nĩ ũthatu mwai wa mũndũ; Nake ndakew’ĩa tei mũthenya wa kũĩvanĩsya.'),
('kam', 'PRO', 6, 35, 'Ndaketĩkĩla mbovosya o na yĩva; Ndakeanĩwa, o na wamũnenga mĩthĩnzĩo mingĩ.'),
('kam', 'PRO', 7, 1, 'Mwana wakwa, kwata ndeto syakwa, Noyia mĩao yakwa vala ũĩ.'),
('kam', 'PRO', 7, 2, 'Kwata mĩao yakwa na kwĩkala thayũ; Na ũmanyĩsyo wakwa ta kyũma kya itho yaku.'),
('kam', 'PRO', 7, 3, 'Myoveee syaanĩ syaku; Mĩandĩke masengeanĩ ma ngoo yaku.'),
('kam', 'PRO', 7, 4, 'Tavya ũĩ, Nue mwĩĩtu‐a‐ia; Na ĩta ũmanyi mũndũ mũka wa mũvĩa waku:'),
('kam', 'PRO', 7, 5, 'Nĩ kana ikũsiĩĩe kwa mũndũ mũka mũeni, Kwa mũndũ mũka wa nthĩ ĩngĩ ũla wendeeasya na ndeto syake sya ũkathĩĩo.'),
('kam', 'PRO', 7, 6, 'Nũndũ mbũthinĩ ya nyũmba yakwa Nasyaĩlya mĩtĩnĩ yakwa mĩkelangan’ye;'),
('kam', 'PRO', 7, 7, 'Na noona katĩ wa ala mate ũmanyi, Na namũvathũkan’ya katĩ wa imwana, Mwanake ũte na ũmanyi,'),
('kam', 'PRO', 7, 8, 'Aivĩtĩla nzĩanĩ nene vakuvĩ kĩkotonĩ kya ũ mũndũ mũka; Nake athi na nzĩa ya nyũmba ya mũndũ mũka ũsu,'),
('kam', 'PRO', 7, 9, 'Ũmithinĩ, wĩoo wa mũthenya, Ũtukũ katĩ na kĩvindunĩ.'),
('kam', 'PRO', 7, 10, 'Na, sisya, mũndũ mũka akomana nake Ekĩĩte ngũa ya ĩlwaya na e na ũseleke wa ngoo.'),
('kam', 'PRO', 7, 11, '(E na kĩlonzo na ũng’endu; Maũũ make matyĩkalaa nyũmbanĩ yake:'),
('kam', 'PRO', 7, 12, 'Oyu e nzĩanĩ nene, yu e kũndũnĩ kũthanthau, Na oveesya kĩla kĩkotonĩ.)'),
('kam', 'PRO', 7, 13, 'Na ĩndĩ ũ mũndũ mũka amũkwata, na amũmumun’ya, Na e na ũthyũ ũte nthoni amwĩa:'),
('kam', 'PRO', 7, 14, 'Nthembo sya nthembo sya mũuo syĩ nakwa; Ũmũnthĩ nĩnĩanĩsye mawĩvĩto makwa.'),
('kam', 'PRO', 7, 15, 'Kwondũ wa ũu nĩnaumaala kũkomana naku, Kũmantha ũthyũ waku na kĩthing’ĩĩsyo, na nĩnakwona.'),
('kam', 'PRO', 7, 16, 'Nĩnalanĩtye ũkomo wakwa mũto mũseo mũno, Na ngũa syĩ nzoa sya ndii sya Misili.'),
('kam', 'PRO', 7, 17, 'Nĩnyungĩthĩtye ũkomo wakwa Na manemane, na uuti, na mũtalasini.'),
('kam', 'PRO', 7, 18, 'Ũka, twose wĩanĩu witũ wa wendo kũvika kĩoko; Twĩtan’ye ene na mawendo.'),
('kam', 'PRO', 7, 19, 'Nũndũ ũ mũndũ mũũme nde mũsyĩ; Nĩ mũendu kyalo kĩasa:'),
('kam', 'PRO', 7, 20, 'Nũendete na mũvuko wa mbesa; Akenũka mwei walũma nthĩ.'),
('kam', 'PRO', 7, 21, 'Na nũndũ wa ndeto syake nyingĩ sya kwendeesya nũmwĩtĩkĩlĩthasya; Kwondũ wa kwendeesya na ndeto sya ũkathĩĩo sya ilomo syake nũmũkusasya.'),
('kam', 'PRO', 7, 22, 'Nake nũmũatĩĩaa mĩtũkĩ, O tondũ ng’ombe ĩendaa kĩthĩnzĩonĩ, Kana ta ũmwe mũtumanu ũmanyĩaw’a na mbĩngũ;'),
('kam', 'PRO', 7, 23, 'Kũvika mũsyĩ ũtonye ĩtema yake; Tondũ nyũnyi ĩkalaataa kũthi vala ve kĩtei, Na ndĩsĩ atĩ nĩ kwondũ wa thayũ wayo.'),
('kam', 'PRO', 7, 24, 'Yu kwondũ wa ũu, ana makwa, mbĩw’ai, Na ĩthukĩĩsyei ndeto sya kanyw’a wakwa.'),
('kam', 'PRO', 7, 25, 'Ngoo yaku ĩtikelekele mĩendele yake; Ndũkaĩe nzĩanĩ syake.'),
('kam', 'PRO', 7, 26, 'Nũndũ nake nĩwavalũkilye nthĩ aingĩ me okite: Ĩĩ, oawa make onthe nĩ nguthu yĩ vinya.'),
('kam', 'PRO', 7, 27, 'Nyũmba yake nĩ nzĩa ya kũthi Seoli, Kũtheea tũsũmbanĩ twa kĩkw’ũ.'),
('kam', 'PRO', 8, 1, 'Ũĩ ndũkayaa, Na ũmanyi kumya wasya waw’o?'),
('kam', 'PRO', 8, 2, 'Ĩũlũ wa kũndũ kũtũlu nzĩanĩ, Vala nzĩa ikomanĩe, nũũngamaa;'),
('kam', 'PRO', 8, 3, 'Vakuvĩ na mbingĩlo, ũlikĩlonĩ wa ndũa, Ũlikĩlonĩ mĩomonĩ, nĩwũkĩlĩlasya wasya mũnene:'),
('kam', 'PRO', 8, 4, 'Inyw’ĩ aũme, nĩngũmwĩta; Na wasya wakwa nĩ kwa ana ma andũ.'),
('kam', 'PRO', 8, 5, 'Inyw’ĩ mũte ũmanyi, manyai ũĩ; Na, inyw’ĩ ndia, ĩthĩwai na ngoo yĩ ũmanyi.'),
('kam', 'PRO', 8, 6, 'Ĩw’ai, nũndũ nganeena maũndũ manene; Na kũtumũka kwa ilomo syakwa kũkeethĩwa maũndũ ma w’o.'),
('kam', 'PRO', 8, 7, 'Nũndũ kanyw’a wakwa ũkaneena w’o; Na ũthũku nĩ ũthatyo kwa ilomo syakwa.'),
('kam', 'PRO', 8, 8, 'Ndeto syonthe sya kanyw’a wakwa nĩ ndũngalu; Vati ũndũ mũthyoeku kana ngũlũ nthĩnĩ wasyo.'),
('kam', 'PRO', 8, 9, 'Syonthe syĩ ũtheinĩ kwa ũla ũmanyaa, Na sya w’o kwa ala monaa ũmanyi.'),
('kam', 'PRO', 8, 10, 'Osa ũmanyĩsyo wakwa, na ti vetha; Na ũmanyi kwĩ thaavu mũseo mũno.'),
('kam', 'PRO', 8, 11, 'Nũndũ ũĩ nĩ kavaa kwĩ tũvila twa maliani; Na syĩndũ syonthe ila itonya kwendua ititonya kũelekanw’a naw’o.'),
('kam', 'PRO', 8, 12, 'Nyie ũĩ, nĩndw’ĩte kĩlĩko vandũ vakwa va ũtũa, Na kũmantha ũmanyi na ũi wa kĩlĩko.'),
('kam', 'PRO', 8, 13, 'Kũmũkĩa Yeova nĩkw’o kũmena ũthũku: Ngathĩĩo, na wĩnenevyo, na mũendele mũthũku, Na kanyw’a wĩ ngũlũ, isu nĩngwimena.'),
('kam', 'PRO', 8, 14, 'Ũtao nĩ wakwa, na ũĩ mwĩanĩu: Ninyie ũmanyi; nĩ na ũtonyi.'),
('kam', 'PRO', 8, 15, 'Kwondũ wakwa asumbĩ nĩmasumbĩkaa, Na anene me mbee ũsumbĩnĩ nĩmatusaa katĩ.'),
('kam', 'PRO', 8, 16, 'Kwondũ wakwa anene me mbee ũsumbĩnĩ nĩmasumbĩkaa, Na ala me ndaĩa, o na asili onthe ma nthĩ.'),
('kam', 'PRO', 8, 17, 'Nĩnĩmendaa ala mambendaa; Na ala mamanthaa na kĩthing’ĩĩsyo makambona.'),
('kam', 'PRO', 8, 18, 'Ũthwii na ndaĩa syĩ nakwa; Ĩĩ, ũthwii ũla wĩkalaa na ũlũngalu.'),
('kam', 'PRO', 8, 19, 'Ũsyao wakwa nĩ mũseo kwĩ thaavu, ĩĩ, kwĩ thaavu mũseo mũno; Na wongeleko wakwa kwĩ vetha mũseo.'),
('kam', 'PRO', 8, 20, 'Nĩendaa nzĩanĩ ya ũlũngalu, Katĩ wa nzĩa sya ũsili wa katĩ;'),
('kam', 'PRO', 8, 21, 'Nĩ kana nĩtume ala mambendaa matiĩwa ũthwii, Na nĩ kana nusũsye kũndũ kwoo kũla kwiawa ũthwii.'),
('kam', 'PRO', 8, 22, 'Yeova aĩ nakwa mwambĩlĩlyonĩ wa nzĩa yake, Mbee wa mawĩa make ma tene.'),
('kam', 'PRO', 8, 23, 'Nĩnookĩlilw’e kuma tene tene, kuma mwambĩlĩlyonĩ, Nthĩ ĩtanamba kwĩthĩwa.'),
('kam', 'PRO', 8, 24, 'Yĩla kũtaĩ syũngũ, nyie nĩnaumĩlĩtw’e, Yĩla kũtaĩ nthongo syĩ na manzĩ maingĩ.'),
('kam', 'PRO', 8, 25, 'Iĩma itanamba kũlũlũmĩlw’a, Mbee wa tũlĩma nyie nĩnaumĩlĩtw’e;'),
('kam', 'PRO', 8, 26, 'Yĩla ũtaĩ anamba kũtw’ĩkĩthya nthĩ, kana isesi, Kana mwambĩlĩlyo wa kĩtoo kya nthĩ.'),
('kam', 'PRO', 8, 27, 'Yĩla walũmilye matu, naĩ vo: Yĩla waiie kilinge ĩũlũ wa ĩ kyũngũ,'),
('kam', 'PRO', 8, 28, 'Yĩla walũmilye matu ĩũlũ, Yĩla nthongo sya ĩ kyũngũ syatw’ĩkie syĩ vinya,'),
('kam', 'PRO', 8, 29, 'Yĩla wanengie ũkanga mũvaka waw’o, Kana manzĩ matikavĩtye mwĩao wake, Yĩla watwie myambĩlĩlyo ya nthĩ;'),
('kam', 'PRO', 8, 30, 'Ĩvinda yĩu naĩ vakuvĩ nake, mũthũkũmi mũnene; Na naĩ ũtanu wake kĩla mũthenya, Ngĩtanĩa mavinda onthe mbee wake,'),
('kam', 'PRO', 8, 31, 'Ngĩtanĩa nthĩ yake ĩtwĩe andũ; Na ũtanu wakwa waĩ na ana ma andũ.'),
('kam', 'PRO', 8, 32, 'Yu kwondũ wa ũu, ana makwa, mbĩthukĩĩsyai; Nũndũ nĩ aathime ala makwataa nzĩa syakwa.'),
('kam', 'PRO', 8, 33, 'Ĩw’ai ũmanyĩsyo, na ĩthĩwai oĩ, Na mũikolee.'),
('kam', 'PRO', 8, 34, 'Nĩmũathime mũndũ ũla ũmbĩw’aa, Akĩsyaĩĩsya kĩla mũthenya mbingĩlonĩ syakwa, Akyeteela mĩtĩnĩ yĩ ndee sya mĩomo yakwa.'),
('kam', 'PRO', 8, 35, 'Nũndũ ũla ũmbonaa nĩwonaa thayũ, Na akoona ũseo kwa Yeova.'),
('kam', 'PRO', 8, 36, 'Ĩndĩ ũla ũmbĩtanĩasya nĩwĩkaa ngoo yake mwene naĩ: Na onthe ala mamenaa nyie mendaa kĩkw’ũ.'),
('kam', 'PRO', 9, 1, 'Ũĩ nĩwakĩte nyũmba yaw’o; Nĩwasũvĩtye ituĩ mũonza syaw’o:'),
('kam', 'PRO', 9, 2, 'Nĩwũaĩte nyamũ syaw’o; nũvulanĩtye mbinyu yaw’o; O na nĩwalanĩtye mesa yaw’o:'),
('kam', 'PRO', 9, 3, 'Nũtũmĩte eĩtu maw’o; Nĩwũkĩlĩlasya wasya kũndũnĩ kũtũlu mbee kwa ndũa:'),
('kam', 'PRO', 9, 4, 'Ũla ũte na ũĩ, nĩathũkĩle vaa: Na ũndũ wa ũla ũte ũmanyi nũũmũtavya,'),
('kam', 'PRO', 9, 5, 'Ũkai, inyw’ĩ mũye lĩu wakwa, Na nyw’ai mbinyu ĩla nĩvulanĩtye.'),
('kam', 'PRO', 9, 6, 'Ekai, inyw’ĩ mũte na ũmanyi, na mũkĩkala thayũ; Na kũkinya nzĩanĩ ya ũmanyi.'),
('kam', 'PRO', 9, 7, 'Ũla ũmwonasya mũkaakaan’ya mavĩtyo nĩwĩyoseaa kũumangwa; Na ũla ũkanasya mũndũ mũthũku nĩwĩyoseaa ĩlanga.'),
('kam', 'PRO', 9, 8, 'Ndũkakan’ye mũkaakaan’ya, ndakese ũkũmena: Kan’ya mũndũ mũĩ, nake akakwenda.'),
('kam', 'PRO', 9, 9, 'Manyĩsya mũndũ mũĩ, nake akeethĩwa mũĩ mbee: Manyĩsya mũndũ mũlũngalu, nake akongeleka kwosa momanyĩsyo.'),
('kam', 'PRO', 9, 10, 'Kũmũkĩa Yeova nĩkw’o wambĩlĩlyo wa ũĩ; Na kũmũmanya Ũla Mũtheu nĩkw’o ũmanyi.'),
('kam', 'PRO', 9, 11, 'Nũndũ kwondũ wakwa mĩthenya yaku ĩkaingĩvw’a, Na myaka ya thayũ waku ĩkongeleelw’a.'),
('kam', 'PRO', 9, 12, 'Ethwa wĩ mũĩ wĩ mũĩ kwondũ waku mwene; Na ethĩwa nũkaakaanasya, we wĩ weka ũkookua.'),
('kam', 'PRO', 9, 13, 'Mũndũ mũka mũtumanu e na kĩlonzo; Nde ũmanyi, na ndesĩ ũndũ.'),
('kam', 'PRO', 9, 14, 'Nĩwĩkalaa mũomonĩ wa nyũmba yake, Kĩvĩlanĩ kĩ kũndũ kũtũlu kwa ndũa,'),
('kam', 'PRO', 9, 15, 'Amete ala meũvĩta, Ala maendete nzĩanĩ syoo:'),
('kam', 'PRO', 9, 16, 'Ũla ũte na ũĩ, nĩathũkĩle vaa; Na ũle ũte ũmanyi, emwĩa,'),
('kam', 'PRO', 9, 17, 'Manzĩ moyĩtwe me mũyo, Na lĩu ũkĩĩwa kĩmbĩthĩnĩ nĩ wa kwendeesya.'),
('kam', 'PRO', 9, 18, 'Ĩndĩ ũ mũndũ ndesĩ atĩ akw’ũ me vo; Aeni ma ũ mũndũ mũka me syũngũnĩ sya Seoli.'),
('kam', 'PRO', 10, 1, 'Nthĩmo sya Solomoni. Mwana mũĩ nũtanĩthasya ĩthe; Ĩndĩ mwana mũtumanu nĩ kĩmako kya inyia wake.'),
('kam', 'PRO', 10, 2, 'Syĩndũ syũmbanĩtw’e na ũthũku itiunaa; Ĩndĩ ũlũngalu nũvonokasya kuma kĩkw’ũnĩ.'),
('kam', 'PRO', 10, 3, 'Yeova ndakaeka ngoo ya ũla mũlũngalu ĩnyale; Ĩndĩ nũluutĩĩlaa ũtee kwenda kwa ũla mũthũku.'),
('kam', 'PRO', 10, 4, 'Ũla ũtethasya wĩa na kw’oko kũleelu nũtw’ĩkaa ngya; Ĩndĩ kw’oko kwa ũla mũthingu nĩkũthuasya.'),
('kam', 'PRO', 10, 5, 'Ũla wũmbanasya ĩvinda ya syũa nĩ mwana mũĩ; Ĩndĩ ũla ũkomaa ĩvinda ya ngetha nĩ mwana ũla ũsonokasya.'),
('kam', 'PRO', 10, 6, 'Moathimo me ĩũlũ wa mũtwe wa ũla mũlũngalu; Ĩndĩ ũng’endu nũtumĩaw’a kanyw’anĩ wa ũla mũthũku.'),
('kam', 'PRO', 10, 7, 'Ũlilikano wa ũla mũlũngalu nĩ mũathimĩku; Ĩndĩ syĩtwa ya mũthũku yĩkoa.'),
('kam', 'PRO', 10, 8, 'Ala oĩ ngoonĩ makoosa mĩao; Ĩndĩ ndia ĩla ĩvulũkaa ndeto ĩkavalũka.'),
('kam', 'PRO', 10, 9, 'Ũla ũendaa na mĩendele myaĩlu aendaa na ũĩkĩĩi; Ĩndĩ ũla welelũkasya mĩendele yake akamanyĩka.'),
('kam', 'PRO', 10, 10, 'Ũla ũvenanĩasya na itho aetae woo; Ĩndĩ ndia ĩla ĩvulũkaa ndeto ĩkavalũka.'),
('kam', 'PRO', 10, 11, 'Kanyw’a wa alũngalu nĩ nthongo ya thayũ; Ĩndĩ ũng’endu nũtumĩaw’a kanyw’anĩ wa ũla mũthũku.'),
('kam', 'PRO', 10, 12, 'Kĩmena nĩkyũkĩlasya mateta; Ĩndĩ wendo nũvw’ĩkaa mavĩtyo onthe.'),
('kam', 'PRO', 10, 13, 'Ũĩ nĩwonekaa ilomonĩ sya ũla ũvathũkanasya maũndũ; Ĩndĩ ndata nĩ ya mũongo wa ũla ũte na ũmanyi.'),
('kam', 'PRO', 10, 14, 'Andũ oĩ maiaa ũmanyi; Ĩndĩ kanyw’a wa ũla mũtumanu nĩ wanangĩko wa yu.'),
('kam', 'PRO', 10, 15, 'Syĩndũ sya mũndũ mũthwii nĩ ndũa yake yĩ vinya: Wanangĩko wa ngya nĩ ũkya woo.'),
('kam', 'PRO', 10, 16, 'Wĩa wa ũla mũlũngalu wangĩe thayũnĩ; Wongeleko wa ũla mũthũku welekele naĩnĩ.'),
('kam', 'PRO', 10, 17, 'Ũla wĩw’aa aikanw’a e nzĩanĩ ya thayũ; Ĩndĩ ũla ũleaa ũkan’yo nũvĩtasya.'),
('kam', 'PRO', 10, 18, 'Ũla ũvithaa kĩmena nĩ wa ilomo ineenaa ũvũngũ; Na ũla ũneenaa nzukũ nĩ ndia.'),
('kam', 'PRO', 10, 19, 'Wingĩnĩ wa ndeto vatyaa ĩvĩtyo; Ĩndĩ ũla ũsiĩĩaa ilomo syake nĩwĩkaa na ũĩ.'),
('kam', 'PRO', 10, 20, 'Ũĩmĩ wa ũla mũlũngalu nĩ ta vetha mũseo: Ngoo ya ũla mũthũku nĩ ya vata mũnini.'),
('kam', 'PRO', 10, 21, 'Ilomo sya mũlũngalu niathĩasya aingĩ; Ĩndĩ atumanu makusaa nũndũ wa kwaa ũmanyi.'),
('kam', 'PRO', 10, 22, 'Ũathimo wa Yeova, naw’o nũthuasya; Na ndawongelanasya na woo.'),
('kam', 'PRO', 10, 23, 'Nĩ ta ĩthaũ kwa ndia kwĩka ũthũku; Now’o ũilyĩ ũĩ kwa mũndũ wĩ na ũmanyi.'),
('kam', 'PRO', 10, 24, 'W’ĩa wa mũthũku, naw’o ũkooka ĩũlũ wake; Na kwenda kwa alũngalu kũkeanĩwa.'),
('kam', 'PRO', 10, 25, 'Yĩla kĩlingi kyavĩta, mũthũku nde vo; Ĩndĩ ũla mũlũngalu nĩ wambĩlĩlyo wa tene na tene.'),
('kam', 'PRO', 10, 26, 'Tondũ siki ũtilyĩ maeonĩ, na tondũ syũki yĩtilyĩ methonĩ, Now’o mũtulu ũilyĩ kwa ala mamũtũmaa.'),
('kam', 'PRO', 10, 27, 'Kũmũkĩa Yeova nĩkwongelaa mĩthenya; Ĩndĩ myaka ya athũku ĩkakuvĩvw’a.'),
('kam', 'PRO', 10, 28, 'Wĩkwatyo wa mũlũngalu ũkeethĩwa ũtanu; Ĩndĩ weteelo wa mũthũku ũkaa.'),
('kam', 'PRO', 10, 29, 'Nzĩa ya Yeova nĩ ngome yĩ vinya kwa mũlũngalu; Ĩndĩ nĩ wanangĩko kwa eki ma naĩ.'),
('kam', 'PRO', 10, 30, 'Mũlũngalu ndakavetwa nongi; Ĩndĩ mũthũku ndakatũa ĩ nthĩ.'),
('kam', 'PRO', 10, 31, 'Kanyw’a wa mũlũngalu nĩwumasya ũĩ; Ĩndĩ ũĩmĩ wĩ ngũlũ ũkatilwa.'),
('kam', 'PRO', 10, 32, 'Ilomo sya mũlũngalu nĩsyĩsĩ kĩla kĩtĩkĩlĩkaa; Ĩndĩ kanyw’a wa mũthũku nũneenaa na ngũlũ.'),
('kam', 'PRO', 11, 1, 'Kĩthimi kya ũkengani nĩ ũthatyo kwa Yeova; Ĩndĩ ĩvia yĩla yĩthimaa w’o nĩ ũtanu wake.'),
('kam', 'PRO', 11, 2, 'Yĩla ngathĩĩo yoka, nĩvo ĩndĩ nthoni yũkaa; Ĩndĩ ũĩ wĩ na ala menyivasya.'),
('kam', 'PRO', 11, 3, 'Wĩanĩu wa ala alũngalu ũkamatongoeasya; Ĩndĩ ngũlũ sya nzeleke ikasyananga.'),
('kam', 'PRO', 11, 4, 'Ũthwii ndwĩuna mũthenya wa ũthilĩku; Ĩndĩ ũlũngalu nũvonokasya kuma kĩkw’ũnĩ,'),
('kam', 'PRO', 11, 5, 'Ũlũngalu wa ũla mwĩanĩu ũkalũngalya mũendele wake; Ĩndĩ ũla mũthũku akavalũka kwondũ wa ũthũku wake mwene.'),
('kam', 'PRO', 11, 6, 'Ũlũngalu wa ala alũngalu ũkamavonokya; Ĩndĩ nzeleke ikakwatwa nĩ naĩ syasyo.'),
('kam', 'PRO', 11, 7, 'Yĩla mũndũ mũthũku ũkusaa, weteelo wake ũkaa; Na wĩkwatyo wa naĩ ũkyaa.'),
('kam', 'PRO', 11, 8, 'Ũla mũlũngalu nũvonokaw’a kuma thĩnanĩ; Na ũla mũthũku nũlikaa vandũ vake.'),
('kam', 'PRO', 11, 9, 'Mũndũ ũtakĩaa Ngai nĩwanangaa mũtũi wake na kanyw’a wake; Ĩndĩ kwondũ wa ũmanyi ũla mũlũngalu akavonokw’a.'),
('kam', 'PRO', 11, 10, 'Yĩla kũendaa nesa kwa ala alũngalu, ndũa nĩtanaa; Na yĩla ala athũku mekwaa, kwĩ mawasya matũlu.'),
('kam', 'PRO', 11, 11, 'Kwondũ wa ũathimo wa alũngalu ndũa nĩtaĩawa; Ĩndĩ nĩng’uthũlangawa nĩ kanyw’a wa athũku.'),
('kam', 'PRO', 11, 12, 'Ũla ũvũthasya mũtũi wake nde na ũĩ; Ĩndĩ mũndũ wĩ na ũmanyi nũvindasya.'),
('kam', 'PRO', 11, 13, 'Ũla wangangaa e mũsukani nũvuanasya nzama; Ĩndĩ ũla wa veva wĩ kĩthito nũvithaa ũndũ.'),
('kam', 'PRO', 11, 14, 'Vala vate ũtongoi mũĩ, andũ nĩmavalũkaa; Ĩndĩ vala ve wingĩ wa atai vati mũisyo.'),
('kam', 'PRO', 11, 15, 'Ũla ũtw’ĩkaa mũĩkĩĩwa kwondũ wa mũeni akathĩnw’a nĩ ũu; Ĩndĩ ũla ũmenaa ũvoo wa ũĩkĩĩthyo ũsu nĩ mwĩyelelu.'),
('kam', 'PRO', 11, 16, 'Mũndũ mũka mũseo nĩwĩkwatĩlaa ndaĩa; Na andũ ang’endu nĩmekwatĩlaa ũthwii.'),
('kam', 'PRO', 11, 17, 'Mũndũ wĩ tei nĩwĩkaa ngoo yake nesa; Ĩndĩ ũla mwai nũthĩnasya mwĩĩ wake mwene.'),
('kam', 'PRO', 11, 18, 'Ũla mũthũku nĩwĩyoseaa ĩtuvi ya ũkengani; Ĩndĩ ũla ũvuĩaa ũlũngalu e na ĩtuvi yĩte ngana.'),
('kam', 'PRO', 11, 19, 'Ũla mũlũmu ũlũngalunĩ akavikĩa thayũ; Ũla ũatĩĩaa ũthũku ekaa ũu kũvikĩa kĩkw’ũ kyake.'),
('kam', 'PRO', 11, 20, 'Ala me ngũlũ ngoonĩ nĩ ũthatyo kwa Yeova; Ĩndĩ ala eanĩu mĩendelenĩ yoo nĩ ũtanu wake.'),
('kam', 'PRO', 11, 21, 'O na ethĩwa kw’oko kũkakwatana na kw’oko, mũndũ mũthũku ndakatĩa ũkũnwa; Ĩndĩ ũsyao wa ũla mũlũngalu ũkavonoka.'),
('kam', 'PRO', 11, 22, 'Ta ngome ya thaavu ĩnyiũũnĩ ya ngũlũe, Now’o ũilyĩ mũndũ mũka mwanake ũte na kĩlĩko.'),
('kam', 'PRO', 11, 23, 'Kwenda kwa alũngalu no ũseo; Ĩndĩ weteelo wa ala athũku nĩ ũthilĩku.'),
('kam', 'PRO', 11, 24, 'Kwĩ ũla ũnyaĩĩkaa, na ũyingĩva mũno mbee; Na kwĩ ũla ũimaa kũvĩtũka ũndũ waĩle, ĩndĩ ũendeeaa kwaĩwa.'),
('kam', 'PRO', 11, 25, 'Mũndũ mũlau akeethĩwa mũnou; Na ũla ũnyithasya akanyithw’a mwene.'),
('kam', 'PRO', 11, 26, 'Ũla ũimanaa lĩu wa mbaa ngetha, andũ makamũuma; Ĩndĩ ũathimo ũkeethĩwa mũtwenĩ wa ũla ũthooasya.'),
('kam', 'PRO', 11, 27, 'Ũla ũmanthaa ũseo na kĩthing’ĩĩsyo nũmanthaa ũndũ ũseo; Ĩndĩ ũla ũmanthaa ũthũku, ũkooka vala ũĩ.'),
('kam', 'PRO', 11, 28, 'Ũla ũĩkĩĩaa ũthwii wake akavalũka; Ĩndĩ ũla mũlũngalu akaaĩlaa ta ĩtũ yĩũ.'),
('kam', 'PRO', 11, 29, 'Ũla ũthĩnasya nyũmba yake mwene akatiĩwa kĩseve; Na ũla mũtumanu akeethĩwa mũthũkũmi wa ũla mũĩ ngoo.'),
('kam', 'PRO', 11, 30, 'Ũsyao wa ũla mũlũngalu nĩ mũtĩ wa thayũ; Na ũla mũĩ nĩwĩtĩkĩlĩthasya andũ.'),
('kam', 'PRO', 11, 31, 'Sisya, ala alũngalu makaĩvĩwa kũũ nthĩ; Nĩ mbee veana ata ala athũku na eki ma naĩ!'),
('kam', 'PRO', 12, 1, 'O ũla wendaa kwonw’a mavĩtyo eendaa ũmanyi; Ĩndĩ ũla ũmenaa ũkan’yo nĩ ta nyamũ.'),
('kam', 'PRO', 12, 2, 'Mũndũ mũseo akoona ũseo kwa Yeova; Ĩndĩ mũndũ wa mosũanĩo mathũku akamũtw’a mũvĩtan’ya.'),
('kam', 'PRO', 12, 3, 'Mũndũ ndakalũlũmĩlw’a nĩ ũthũku; Ĩndĩ mũi wa ũla mũlũngalu ndũkathingithangw’a.'),
('kam', 'PRO', 12, 4, 'Mũndũ mũka mwaĩlu nĩ ngovia ya ũsumbĩ ya mũũme wake; Ĩndĩ ũla ũsonokasya nĩ ta wou mavĩndĩnĩ make.'),
('kam', 'PRO', 12, 5, 'Mosũanĩo ma ala alũngalu nĩ ma katĩ; Ĩndĩ motao ma ala athũku nĩ ũkengani.'),
('kam', 'PRO', 12, 6, 'Ndeto sya ala athũku nĩ sya kwoveesya nthakame; Ĩndĩ kanyw’a wa ala alũngalu ũkamavonokya.'),
('kam', 'PRO', 12, 7, 'Ala athũku nĩmanangawa, na mati vo; Ĩndĩ nyũmba ya ala alũngalu ĩkaũngama.'),
('kam', 'PRO', 12, 8, 'Mũndũ akataĩwa kwĩanana na ũĩ wake; Ĩndĩ ũla wĩ na ngoo yĩ ngũlũ akavũthw’a.'),
('kam', 'PRO', 12, 9, 'E kavaa ũla ũtalawa ta vathei, na e na mũthũkũmi, Kwĩ ũla wĩtaĩaa, na nde na lĩu.'),
('kam', 'PRO', 12, 10, 'Mũndũ mũlũngalu nũsiasya thayũ wa nyamũ yake; Ĩndĩ matei mololo ma ũla mũthũku no wai.'),
('kam', 'PRO', 12, 11, 'Ũla ũĩmaa nthĩ yake akeethĩwa na lĩu mwingĩ; Ĩndĩ ũla ũatĩĩaa andũ mate kĩĩĩ nde na ũmanyi.'),
('kam', 'PRO', 12, 12, 'Ũla mũthũku nĩwendaa kĩtei kya ala athe; Ĩndĩ mũi wa ũla mũlũngalu nũsyaa ũsyao.'),
('kam', 'PRO', 12, 13, 'Ĩvĩtyonĩ ya ilomo ve kĩtei kwa mũndũ mũthũku; Ĩndĩ ũla mũlũngalu akauma thĩnanĩ.'),
('kam', 'PRO', 12, 14, 'Mũndũ akeanĩw’a nĩ ũseo kwondũ wa ũsyao wa kanyw’a wake; Na meko ma moko ma mũndu makatũngwa kwake.'),
('kam', 'PRO', 12, 15, 'Nzĩa ya ndia nĩ ya w’o methonĩ mayo e yo; Ĩndĩ ũla mũĩ nĩwĩthukĩĩasya ũtao.'),
('kam', 'PRO', 12, 16, 'Ũthatu wa ndia nũmanyĩkaa ũtheinĩ; Ĩndĩ mũndũ wĩ kĩlĩko nũvithaa nthoni.'),
('kam', 'PRO', 12, 17, 'Ũla ũneenaa w’o nĩwonanasya ũlũngalu; Ĩndĩ ngũsĩ ya ũvũngũ, ũkengani.'),
('kam', 'PRO', 12, 18, 'Ve ũla ũneenaa mĩtũkĩ ateũsũanĩa ta kũtonyanga kwa ũvyũ; Ĩndĩ ũĩmĩ wa ũla mũĩ nũvoasya.'),
('kam', 'PRO', 12, 19, 'Kĩlomo kya w’o kĩkalũlũmĩlw’a tene na tene; Ĩndĩ ĩũmĩ ũneenaa ũvũngũ no wa kavinda kanini.'),
('kam', 'PRO', 12, 20, 'Ũkengani wĩ ngoonĩ ya ala masũanĩaa ũthũku; Ĩndĩ ala maseũvasya maũndũ ma mũuo kwoo nĩ ũtanu.'),
('kam', 'PRO', 12, 21, 'Vati ũthũku ũkekĩka kwa ũla mũlũngalu; Ĩndĩ ũla mũthũku akausũwa nĩ ũthũku.'),
('kam', 'PRO', 12, 22, 'Ilomo ila ineenaa ũvũngũ nĩ ũthatyo kwa Yeova; Ĩndĩ ala mekaa w’o nĩ ũtanu wake.'),
('kam', 'PRO', 12, 23, 'Mũndũ wĩ kĩlĩko nũvithaa ũmanyi; Ĩndĩ ngoo ya ndia nĩtavanasya ũtumanu.'),
('kam', 'PRO', 12, 24, 'Kw’oko kwa ũla mũthingu kũkasumbĩka; Ĩndĩ ũla mũtulu akathũkũmĩthw’a.'),
('kam', 'PRO', 12, 25, 'Kĩmako ngoonĩ ya mũndũ nĩkĩminamasya; Ĩndĩ ndeto nzeo nĩmĩtanasya.'),
('kam', 'PRO', 12, 26, 'Ũla mũlũngalu nĩ mũtongoi wa mũtũi wake; Ĩndĩ mũendele wa ala athũku nũmavĩtĩthasya.'),
('kam', 'PRO', 12, 27, 'Mũndũ mũtulu ndavĩvasya kĩla wosaa aisyĩma; Syĩndũ syĩ vata mũno sya andũ nĩ kwondũ wa ala athingu.'),
('kam', 'PRO', 12, 28, 'Mũendelenĩ wa ũlũngalu ve thayũ; Na nzĩanĩ yaw’o vati kĩkw’ũ.'),
('kam', 'PRO', 13, 1, 'Mwana mũĩ nĩwĩw’aa ũmanyĩsyo wa ĩthe wake; Ĩndĩ mũkaakaan’ya ndew’aa ũkan’yo.'),
('kam', 'PRO', 13, 2, 'Mũndũ akaya ũseo kwondũ wa ũsyao wa kanyw’a wake; Ĩndĩ ngoo ya nzeleke ĩkaya ũng’endu.'),
('kam', 'PRO', 13, 3, 'Ũla ũsũvĩaa kanyw’a wake nĩwĩkalasya thayũ wake; Ĩndĩ ũla ũtumũkanganasya ilomo syake mũno akeethĩwa na wanangĩko.'),
('kam', 'PRO', 13, 4, 'Ngoo ya ũla mũtulu nĩyendaa, na ndĩ na kĩndũ; Ĩndĩ ngoo ya ũla mũthingu ĩkeethĩwa nou.'),
('kam', 'PRO', 13, 5, 'Mũndũ mũlũngalu nũmenaa movũngũ; Ĩndĩ mũndũ mũthũku nĩ ũtiiki, na avikĩaa kũsonoka.'),
('kam', 'PRO', 13, 6, 'Ũlũngalu nũsũvĩaa ũla mũlũngalu nzĩanĩ; Ĩndĩ ũthũku nĩwanangaa mũndũ mwathe.'),
('kam', 'PRO', 13, 7, 'Kwĩ ũla wĩthuasya, ĩndĩ nde kĩndũ: Kwĩ ũla wĩtusaa ngya, ĩndĩ e na ũthwii mwingĩ.'),
('kam', 'PRO', 13, 8, 'Mbovosya ya thayũ wa mũndũ nĩ ũthwii wake; Ĩndĩ ngya ndĩw’aa ũkan’yo.'),
('kam', 'PRO', 13, 9, 'Kyeni kya ũla mũlũngalu nĩkĩtanaa; Ĩndĩ taa wa ũla mũthũku ũkavow’a.'),
('kam', 'PRO', 13, 10, 'Kwondũ wa ngathĩĩo nĩkũkaa ngananĩo; Ĩndĩ kwa ala mataawa nesa kwĩ ũĩ.'),
('kam', 'PRO', 13, 11, 'Ũthwii ũla wonekaa na nzĩa ĩtaĩle ũkaolwa; Ĩndĩ ũla ũmbanasya kwondũ wa wĩa akeethĩwa na wongeleko.'),
('kam', 'PRO', 13, 12, 'Wĩkwatyo ũla ũtĩaa nũwaasya ngoo; Ĩndĩ kĩla kyendetwe kyooka, nĩ mũtĩ wa thayũ.'),
('kam', 'PRO', 13, 13, 'O ũla ũvũthasya ndeto nĩwĩeteae wanangĩko; Ĩndĩ ũla ũkĩaa mwĩao akatuvwa.'),
('kam', 'PRO', 13, 14, 'Mwĩao wa ũla mũĩ nĩ nthongo ya thayũ, Nĩ kana mũndũ atie itei sya kĩkw’ũ.'),
('kam', 'PRO', 13, 15, 'Ũmanyi mũseo nũetae ũseo; Ĩndĩ nzĩa ya mũvĩtan’ya nĩ nyũmũ.'),
('kam', 'PRO', 13, 16, 'Kĩla mũndũ wĩ kĩlĩko nũtethasya wĩa na ũmanyi; Ĩndĩ ndia nĩyonanasya ũtumanu wayo.'),
('kam', 'PRO', 13, 17, 'Mũtũmwa mũthũku nũvalũkaa naĩnĩ; Ĩndĩ mũtũmwa wĩ kĩthito nĩ wa ũvosya.'),
('kam', 'PRO', 13, 18, 'Ũkya na nthoni ikeethĩwa sya ũla ũleaa kwonw’a mavĩtyo; Ĩndĩ ũla wĩtĩkĩlaa ũkan’yo akataĩwa.'),
('kam', 'PRO', 13, 19, 'Ũla wendetwe weanĩw’a nĩ mũyo wa ngoo; Ĩndĩ nĩ ũthatyo kwa ndia kũtia naĩ.'),
('kam', 'PRO', 13, 20, 'Endaa na andũ oĩ, ũkeethĩwa mũĩ; Ĩndĩ ũla ũtindanasya na ndia akathĩna.'),
('kam', 'PRO', 13, 21, 'Ũthũku nũatĩĩaa andũ athe; Ĩndĩ ala alũngalu makaĩvwa ũseo.'),
('kam', 'PRO', 13, 22, 'Mũndũ mũseo nũtiĩaa esũkũũe make ũtiĩwa; Na ũthwii wa mũndũ mwathe wiawa kwondũ wa alũngalu.'),
('kam', 'PRO', 13, 23, 'Lĩu mwingĩ wĩ kũĩmanĩ kwa ngya; Ĩndĩ kwĩ kĩla kyanangĩtwe kwondũ wa ũsili ũte wa katĩ.'),
('kam', 'PRO', 13, 24, 'Ũla ũimaa mwana wake ndata yake nũmenaa mwana wake; Ĩndĩ ũla ũmwendaa nũmũkũnaa mavinda maĩle.'),
('kam', 'PRO', 13, 25, 'Ũla mũlũngalu nũĩsaa akavũn’ya thayũ wake; Ĩndĩ ĩvu ya ũla mũthũku yĩkeew’a nzaa.'),
('kam', 'PRO', 14, 1, 'Kĩla mũndũ mũka mũĩ nĩwakaa nyũmba yake; Ĩndĩ ũla mũtumanu nũomboaa na moko make mwene.'),
('kam', 'PRO', 14, 2, 'Ũla ũkinyaa ũlũngalunĩ wake nũkĩaa Yeova; Ĩndĩ ũla wĩ ngũlũ mĩendelenĩ yake nũmũvũthasya.'),
('kam', 'PRO', 14, 3, 'Kanyw’anĩ wa ũla mũtumanu ve ndata kwondũ wa ngathĩĩo yake; Ĩndĩ ilomo sya ala oĩ ikamasũvĩa.'),
('kam', 'PRO', 14, 4, 'Vala vate ng’ombe, vandũ va kũĩthĩw’a nĩ vathei; Ĩndĩ wingĩvo mwingĩ nĩ kwondũ wa vinya wa ng’ombe.'),
('kam', 'PRO', 14, 5, 'Ngũsĩ yĩ kĩthito ndĩneenaa ũvũngũ; Ĩndĩ ngũsĩ ngengani ĩneenaa movũngũ.'),
('kam', 'PRO', 14, 6, 'Mũkaakaan’ya nũmanthaa ũĩ, na ndawonaa; Ĩndĩ ũmanyi nĩwonekaa na ũvũthũ kwa ũla wĩ na kĩlĩko.'),
('kam', 'PRO', 14, 7, 'Lika vala va mũndũ mũtumanu, Na ndũkona kwake ilomo syĩ ũmanyi.'),
('kam', 'PRO', 14, 8, 'Ũĩ wa ũla wĩ kĩlĩko nĩ kũmanya mũendele wake; Ĩndĩ ũtumanu wa ndia nĩ ũkengani.'),
('kam', 'PRO', 14, 9, 'Nthembo kwondũ wa ĩvĩtyo nĩthekeeawa nĩ ndia; Ĩndĩ katĩ wa alũngalu kwĩ kwendana kũseo.'),
('kam', 'PRO', 14, 10, 'Ngoo nĩyĩsĩ ũũ wayo e yo; Na mũeni ndelikasya ũtanunĩ wayo.'),
('kam', 'PRO', 14, 11, 'Nyũmba ya ũla mũthũku ĩkang’uthũlwa; Ĩndĩ ĩeema ya ũla mũlũngalu yĩkaathimĩka.'),
('kam', 'PRO', 14, 12, 'Ve nzĩa ĩla ĩilyĩ ta ya w’o kwa mũndũ; Ĩndĩ mũminũkĩlyo wayo nĩ nzĩa sya kĩkw’ũ.'),
('kam', 'PRO', 14, 13, 'O na kũthekanĩ ngoo yĩ na woo; Na mũminũkĩlyo wa ũtanu nĩ kĩmako.'),
('kam', 'PRO', 14, 14, 'Ũla ũsyokete na ĩtina ngoonĩ yake akausũwa nĩ mĩendele yake mwene; Na mũndũ mũseo akeanĩw’a kuma nthĩnĩ wake mwene.'),
('kam', 'PRO', 14, 15, 'Ũla ũte ũmanyi nĩwĩtĩkĩlaa kĩla ndeto; Ĩndĩ ũla wĩ kĩlĩko asiasya ũndũ ũendaa.'),
('kam', 'PRO', 14, 16, 'Mũndũ mũĩ nũkĩaa na kũtia ũthũku; Ĩndĩ ndia nĩendaa yĩng’athĩlĩtye, na kwĩkwatya mwene.'),
('kam', 'PRO', 14, 17, 'Ũla ũthataa mĩtũkĩ akeka na ũtumanu; Na mũndũ wĩ mosũanĩo mathũku nũmenawa.'),
('kam', 'PRO', 14, 18, 'Ala mate ũmanyi matiĩawa ũtumanu; Ĩndĩ ala me kĩlĩko mekĩawa ngovia ya ũmanyi.'),
('kam', 'PRO', 14, 19, 'Ala athe makunamaa mbee wa ala aseo; Na ala athũku, mbingĩlonĩ sya alũngalũ.'),
('kam', 'PRO', 14, 20, 'Ngya nĩmenawa o na nĩ mũtũi wayo mwene; Ĩndĩ mũthwii e na anyanyae aingĩ.'),
('kam', 'PRO', 14, 21, 'Ũla ũvũthasya mũtũi wake nĩwĩkaa naĩ; Ĩndĩ ũla ũsyĩw’ĩaa ngya tei nĩ mũtanu.'),
('kam', 'PRO', 14, 22, 'Maivĩtasya ala masũanĩaa ũthũku? Ĩndĩ tei na w’o ikeethĩwa sya ala masũanĩaa ũseo.'),
('kam', 'PRO', 14, 23, 'Wĩanĩ w’onthe ve ũtandĩthyo; Ĩndĩ kũneena kwa ilomo kwangĩĩtye ũkyanĩ.'),
('kam', 'PRO', 14, 24, 'Ngovia ya ũsumbĩ ya ala oĩ nĩ ũthwii woo; Ĩndĩ ũtumanu wa ndia no ũtumanu.'),
('kam', 'PRO', 14, 25, 'Ngũsĩ ya w’o nĩvonokasya mathayũ; Ĩndĩ ũla ũneenaa movũngũ nũkenganaa.'),
('kam', 'PRO', 14, 26, 'Nthĩnĩ wa kũmũkĩa Yeova ve ũĩkĩĩi wĩ vinya; Na syana syake ikeethĩwa na wĩvitho.'),
('kam', 'PRO', 14, 27, 'Kũmũkĩa Yeova nĩ nthongo ya thayũ, Nĩ kana mũndũ atie itei sya kĩkw’ũ.'),
('kam', 'PRO', 14, 28, 'Wingĩnĩ wa andũ nĩvo ve ndaĩa ya mũsumbĩ; Ĩndĩ ũolekunĩ wa andũ ve wanangĩko wa mũnene wĩ mbee ũsumbĩnĩ.'),
('kam', 'PRO', 14, 29, 'Ũla mũmĩĩsya wa kũthata nĩ wa ũmanyi mwingĩ; Ĩndĩ ũla wĩ mĩtũkĩ vevanĩ nũnenevasya ũtumanu.'),
('kam', 'PRO', 14, 30, 'Ngoo nduu nĩ thayũ wa mwĩĩ; Ĩndĩ kĩwĩu nĩ wou wa mavĩndĩ.'),
('kam', 'PRO', 14, 31, 'Ũla ũthĩnasya ngya nũvũthasya Mũmbi wake; Ĩndĩ ũla ũmew’ĩaa athĩni tei nũmũtaĩaa.'),
('kam', 'PRO', 14, 32, 'Ũla mũthũku nũtheeaw’a kwĩkanĩ kwake kũthũku; Ĩndĩ ũla mũlũngalu kĩkw’ũnĩ kyake e na wĩvitho.'),
('kam', 'PRO', 14, 33, 'Ũĩ nĩwĩkalaa ngoonĩ ya ũla wĩ na ũmanyi; Ĩndĩ kĩla kĩ nthĩnĩ wa ndia nĩkĩvuanaw’a.'),
('kam', 'PRO', 14, 34, 'Ũlũngalu nũnenevasya mbaĩ; Ĩndĩ naĩ nĩvũthĩthasya ũko o na wĩva wa andũ.'),
('kam', 'PRO', 14, 35, 'Wonan’yo wa ũseo wa mũsumbĩ welekele mũthũkũmi ũla wĩkaa na ũĩ; Ĩndĩ ũthilĩku wake ũkeethĩwa ĩũlũ wa ũla ũsonokasya.'),
('kam', 'PRO', 15, 1, 'Ũsũngĩo mwololo nũthyũũaa ũthilĩku; Ĩndĩ ndeto mbai nĩyũkĩlasya ũthatu.'),
('kam', 'PRO', 15, 2, 'Ũĩmĩ wa ala oĩ nũneenaa ũmanyi katĩ; Ĩndĩ kanyw’a wa ndia nĩwonoasya ũtumanu.'),
('kam', 'PRO', 15, 3, 'Metho ma Yeova me kĩla vandũ, Makĩsyaĩĩsya ũthũku na ũseo.'),
('kam', 'PRO', 15, 4, 'Ũĩmĩ mũuu nĩ mũtĩ wa thayũ; Ĩndĩ ngũlũ syaw’o nĩ kũtũlĩka kwa veva.'),
('kam', 'PRO', 15, 5, 'Ndia nĩvũthasya kwonw’a mavĩtyo nĩ ĩthe wayo; Ĩndĩ ũla wĩtĩkĩlaa ũkan’yo nĩwosaa kĩlĩko.'),
('kam', 'PRO', 15, 6, 'Nyũmbanĩ ya mũlũngalu ve ũthwii mwie mwingĩ; Ĩndĩ motandĩthyonĩ ma ala athũku ve thĩna.'),
('kam', 'PRO', 15, 7, 'Ilomo sya ala oĩ ninyaĩĩkasya ũmanyi; Ĩndĩ ngoo ya mũtumanu ndĩkaa ũu.'),
('kam', 'PRO', 15, 8, 'Nthembo ya ũla mũthũku nĩ ũthatyo kwa Yeova; Ĩndĩ mboya ya ũla mũlũngalu nĩ ũtanu wake.'),
('kam', 'PRO', 15, 9, 'Mũendele wa ũla mũthũku nĩ ũthatyo kwa Yeova; Ĩndĩ nũmwendaa ũla ũatĩĩaa ũlũngalu.'),
('kam', 'PRO', 15, 10, 'Ve kũsilĩlwa kwai kwa ũla ũtiaa ĩ nzĩa; Na ũla ũmenaa kũkanw’a akakw’a.'),
('kam', 'PRO', 15, 11, 'Seoli na Avatoni kwĩ ũtheinĩ mbee wa Yeova; Nĩ mbee veana ata ngoo sya ana ma andũ!'),
('kam', 'PRO', 15, 12, 'Mũkaakaan’ya ndendaa kũkanw’a; Ndaendaa kwa ũla mũĩ.'),
('kam', 'PRO', 15, 13, 'Ngoo ndanu nĩtanĩthasya ũthyũ; Ĩndĩ ũndũ wa woo wa ngoo veva nũtũlĩkaa.'),
('kam', 'PRO', 15, 14, 'Ngoo ya ũla wĩ na ũmanyi nĩmanthaa ũĩ; Ĩndĩ kanyw’a wa ndia nũĩsaa ũtumanu.'),
('kam', 'PRO', 15, 15, 'Mĩthenya yonthe ya ala mathĩnaa nĩ mĩthũku; Ĩndĩ ũla wĩ na ngoo ndanu e na mboka ĩtatw’ĩkanaa.'),
('kam', 'PRO', 15, 16, 'Kavaa kĩndũ kĩnini, vamwe na kũmũkĩa Yeova, Kwĩ ũthwii mwie mwingĩ vamwe na thĩna.'),
('kam', 'PRO', 15, 17, 'Kavaa kũya nyũnyi, vala ve wendo, Kwĩ ng’ombe ĩĩthaw’a kĩtũũnĩ vamwe na kĩmena.'),
('kam', 'PRO', 15, 18, 'Mũndũ mũthilĩku nĩwũkĩlasya ngananĩo; Ĩndĩ mũmĩĩsya wa kũthata mũuasya ĩteta.'),
('kam', 'PRO', 15, 19, 'Nzĩa ya ũla mũtulu ĩilyĩ ta wiio wa mĩw’a; Ĩndĩ nzĩa ya ũla mũlũngalu nĩtw’ĩkĩthaw’a lelũ.'),
('kam', 'PRO', 15, 20, 'Mwana mũĩ nũtanĩthasya ĩthe; Ĩndĩ mũndũ mũtumanu nũvũthasya inyia wake.'),
('kam', 'PRO', 15, 21, 'Ũtumanu nĩ ũtanu kwa ũla ũte na ũĩ; Ĩndĩ mũndũ wĩ na ũmanyi nũlũngalasya mũendele wake.'),
('kam', 'PRO', 15, 22, 'Vala vate ũtao, maũndũ ala masũanĩĩtwe kwĩkwa nĩmanangĩkaa; Ĩndĩ vala ve wingĩ wa atai nĩmalũlũmĩlaw’a.'),
('kam', 'PRO', 15, 23, 'Mũndũ e na ũtanu ũsũngĩonĩ wa kanyw’a wake; Na ndeto ĩvindanĩ yayo, kote nzeo!'),
('kam', 'PRO', 15, 24, 'Kwa ũla mũĩ nzĩa ya thayũ ĩelete ĩũlũ, Nĩ kana ethyũũe na kũtia Seoli ĩtheo.'),
('kam', 'PRO', 15, 25, 'Yeova akakũanĩsya na mĩi nyũmba ya ekathĩĩi; Ĩndĩ akalũlũmĩlya mũvaka wa mũndũ mũka ndiwa.'),
('kam', 'PRO', 15, 26, 'Mosũanĩo mathũku nĩ ũthatyo kwa Yeova; Ĩndĩ ndeto nzeo nĩ ntheu.'),
('kam', 'PRO', 15, 27, 'Ũla wĩ na ĩtomo ya ũtandĩthyo nũthĩnasya nyũmba yake mwene; Ĩndĩ ũla ũmenaa mavaki akekala thayũ.'),
('kam', 'PRO', 15, 28, 'Ngoo ya ũla mũlũngalu nĩsũanĩaa kũsũngĩa; Ĩndĩ kanyw’a wa ũla mũthũku nĩwonoasya maũndũ mathũku.'),
('kam', 'PRO', 15, 29, 'Yeova e kũasa na ũla mũthũku; Ĩndĩ nĩwĩw’aa mboya ya ũla mũlũngalu.'),
('kam', 'PRO', 15, 30, 'Kyeni kya metho nĩkĩtanasya ngoo; Na maũvoo maseo manoasya mavĩndĩ.'),
('kam', 'PRO', 15, 31, 'Kũtũ kũla kwĩthukĩĩasya ũkan’yo wa thayũ Kũkekala katĩ wa ala oĩ.'),
('kam', 'PRO', 15, 32, 'Ũla ũleaa kwonw’a mavĩtyo nũvũthasya thayũ wake mwene; Ĩndĩ ũla wĩthukĩĩasya ũkan’yo nĩwosaa ũmanyi.'),
('kam', 'PRO', 15, 33, 'Kũmũkĩa Yeova nĩ ũmanyĩsyo wa ũĩ; Na wĩnyivyo ũtongoeasya ndaĩa.'),
('kam', 'PRO', 16, 1, 'Maũndũ maseũvye ma ngoo nĩ ma mũndũ; Ĩndĩ ũsũngĩo wa ũĩmĩ wumaa vala ve Yeova.'),
('kam', 'PRO', 16, 2, 'Mĩendele yonthe ya mũndũ nĩ mĩtheu methonĩ make mwene; Ĩndĩ Yeova athimaa maveva.'),
('kam', 'PRO', 16, 3, 'Mwiĩe Yeova mawĩa maku, Na mosũanĩa maku makalũlũmĩlw’a.'),
('kam', 'PRO', 16, 4, 'Yeova nũseũvĩtye kĩla kĩndũ na kĩtumi kyakyo; Ĩĩ, o na athũku kwondũ wa mũthenya wa ũthũku.'),
('kam', 'PRO', 16, 5, 'Kĩla mũndũ ũla wĩ na ngathĩĩo ngoonĩ nĩ ũthatyo kwa Yeova: O na ethĩwa kw’oko kũkakwatana na kw’oko, ndakatĩa kũkũnwa.'),
('kam', 'PRO', 16, 6, 'Kwondũ wa tei na w’o ũthũku nũvw’ĩkĩkaa; Na kwondũ wa kũmũkĩa Yeova andũ nĩmatiaa ũthũku.'),
('kam', 'PRO', 16, 7, 'Yĩla mĩendele ya mũndũ yendeesya Yeova, Atumaa o na amaitha make methĩwa na mũuo nake.'),
('kam', 'PRO', 16, 8, 'Kavaa kĩndũ kĩnini, vamwe na ũlũngalu, Kwĩ motandĩthyo manene vamwe na ũsili ũte wa katĩ.'),
('kam', 'PRO', 16, 9, 'Ngoo ya mũndũ nĩsũanĩaa nzĩa yake; Ĩndĩ Yeova atongoeasya matambya make.'),
('kam', 'PRO', 16, 10, 'Ũvuan’yo mwaĩlu wĩ ilomonĩ sya mũsumbĩ; Kanyw’a wake ndũkavĩtya kũtw’anĩ.'),
('kam', 'PRO', 16, 11, 'Kĩthimi kya w’o na latili sya w’o nĩ sya Yeova; Mavia onthe ma mũvuko ala mathimaa nĩ wĩa wake.'),
('kam', 'PRO', 16, 12, 'Nĩ ũthatyo kwa asumbĩ kwĩka ũthũku; Nũndũ kĩvĩla kya ũsumbĩ nĩkĩlũmaw’a nĩ ũlũngalu.'),
('kam', 'PRO', 16, 13, 'Ilomo ila ineenaa ũlũngalu nĩ ũtanu wa asumbĩ; Na mamwendaa ũla ũneenaa w’o.'),
('kam', 'PRO', 16, 14, 'Ũthilĩku wa mũsumbĩ nĩ ta atũmwa ma kĩkw’ũ; Ĩndĩ mũndũ mũĩ akoousya.'),
('kam', 'PRO', 16, 15, 'Kyeninĩ kya ũthyũ wa mũsumbĩ ve thayũ; Na kwonan’ya kwake kwa ũseo nĩ ta ĩthweo ya mbua ya uũa.'),
('kam', 'PRO', 16, 16, 'Kaĩ nĩ kavaa mũno kwĩthĩwa na ũĩ kwĩ thaavu! Ĩĩ, nĩ kavaa kũnyuva kwĩthĩwa na ũmanyi kwĩ vetha.'),
('kam', 'PRO', 16, 17, 'Lelũ wa ala alũngalu nĩ kũtia ũthũku; Ũla ũsũvĩaa mũendele wake nũsũvĩaa thayũ wake.'),
('kam', 'PRO', 16, 18, 'Ngathĩĩo nĩtongoeasya wanangĩko, Na veva wa wĩng’athĩlĩlyo nũtongoeasya kũvalũka.'),
('kam', 'PRO', 16, 19, 'Nĩ kavaa kwĩthĩwa na veva wa wĩnyivyo vamwe na ngya, Kwĩ kũaana mũtavo na ekathĩĩi.'),
('kam', 'PRO', 16, 20, 'Ũla wĩthukĩĩasya ndeto akona ũseo; Na ũla ũmũĩkĩĩaa Yeova nĩ mũtanu.'),
('kam', 'PRO', 16, 21, 'Ala oĩ ngoonĩ maketwa ma kĩlĩko; Na mũyo wa ilomo nĩwingĩvasya momanyĩsyo.'),
('kam', 'PRO', 16, 22, 'Ũmanyi nĩ mbuluti ya thayũ kwa ũla wĩ naw’o; Ĩndĩ kwonw’a mavĩtyo kwa ndia nĩ ũtumanu wasyo.'),
('kam', 'PRO', 16, 23, 'Ngoo ya ũla mũĩ nĩmanyĩasya kanyw’a wake. Na kwongela ũmanyĩsyo ilomonĩ syake.'),
('kam', 'PRO', 16, 24, 'Ndeto nzeo nĩ ta ĩwa, Syĩ mũyo kwa ngoo, na nivoasya mavĩndĩ.'),
('kam', 'PRO', 16, 25, 'Ve nzĩa ĩla ĩilyĩ ta ya w’o kwa mũndũ, Ĩndĩ mũminũkĩlyo wayo nĩ nzĩa sya kĩkw’ũ.'),
('kam', 'PRO', 16, 26, 'Nzaa ya mũthũkũmi nĩthũkũmaa kwondũ wake; Nũndũ kanyw’a wake nũmũthing’ĩĩsya.'),
('kam', 'PRO', 16, 27, 'Mũndũ ũte kĩĩĩ nũsũanĩaa ũthũku; Na ilomonĩ syake kwĩ ta mwaki ũvĩvasya.'),
('kam', 'PRO', 16, 28, 'Mũndũ wĩ ngũlũ nũnyaĩĩkasya ĩteta; Na ũla ũneenaa na kĩwe ataanasya anyanya anene.'),
('kam', 'PRO', 16, 29, 'Mũndũ mũng’endu asengasengaa mũtũĩ wake, Na kũmũtongoesya mũendelenĩ ũte mũseo.'),
('kam', 'PRO', 16, 30, 'Ũla ũlalasya metho make, nĩwĩkaa ũu asũanĩe maũndũ ma ngũlũ: Ũla ũtumanasya ilomo syake nũtumaa ũthũku wĩthĩwa.'),
('kam', 'PRO', 16, 31, 'Mũtwe wĩ mbuĩ nĩ ngovia ya ũsumbĩ ya ndaĩa; Ũkooneka nzĩanĩ ya ũlũngalu.'),
('kam', 'PRO', 16, 32, 'Mũmĩĩsya wa kũthata e kavaa kwĩ ũla wĩ na ũtonyi; Na ũla ũsumbĩkaa veva wake, e kavaa kwĩ ũla ũkwataa ndũa.'),
('kam', 'PRO', 16, 33, 'Mũlimano nĩwĩkĩtwe ngũanĩ; Ĩndĩ ũndũ ũkethĩwa no kwondũ wa Yeova.'),
('kam', 'PRO', 17, 1, 'Nĩ kavaa kalungu komũ ka ũya, na ũuu vamwe nako, Kwi nyũmba yusũĩte mboka vamwe na ĩteta.'),
('kam', 'PRO', 17, 2, 'Mũthũkũmi ũla wĩkaa na ũĩ akasumbĩka mwana ũla ũsonokasya, Na akeethĩwa na kĩanda ũtiĩwanĩ katĩ wa ana‐a‐ĩthe.'),
('kam', 'PRO', 17, 3, 'Na mbisũ ya kũthesya nĩ kwondũ wa vetha, na iko ĩnene kwondũ wa thaavu; Ĩndĩ Yeova nũtataa ngoo.'),
('kam', 'PRO', 17, 4, 'Mwĩki wa naĩ nĩwĩthukĩĩasya ilomo nthũku; Na mũneeni wa ũvũngũ nũteaa kũtũ ew’e ũĩmĩ mũthũku.'),
('kam', 'PRO', 17, 5, 'Ũla ũthekeeaa ngya nũvũthasya Mũmbi wake; Na ũla ũtanaw’a nĩ wanangĩko mũnene ndakatĩa kũkũnwa.'),
('kam', 'PRO', 17, 6, 'Nzũkũlũ nĩ ngovia ya ũsumbĩ ya andũ akũũ; Na ũtaĩo wa syana nĩ aaĩthe masyo.'),
('kam', 'PRO', 17, 7, 'Kũneena kũseo kũtiaĩle ndia; Nĩ mbee mũno ilomo ila ineenaa ũvũngũ kũlea kwaĩla mũnene wĩ mbee ũsumbĩnĩ.'),
('kam', 'PRO', 17, 8, 'Ĩvaki nĩ ta kavila ke thooa mũnene methonĩ ma ũla wĩ nayo; O vala yĩelekela, nĩyĩunĩkasya.'),
('kam', 'PRO', 17, 9, 'Ũla ũvw’ĩkaa ĩvĩtyo nũmanthaa wendo; Ĩndĩ ũla ũtindaa aineena ũndũ, ataanasya anyanya anene.'),
('kam', 'PRO', 17, 10, 'Ũkan’yo ũlikaa mũno mũndũnĩ wĩ na ũmanyi Kwĩ makũnwa ĩana nthĩnĩ wa ndia.'),
('kam', 'PRO', 17, 11, 'Mũndũ mũthũku nũmanthaa no ũng’endu; Kwondũ wa ũu mũtũmwa mwai akatũmwa okite nake.'),
('kam', 'PRO', 17, 12, 'Kavaa nduva ĩvenetwe tũswii twayo kũkomana na mũndũ, Kwĩ ndia ũtumanunĩ wayo.'),
('kam', 'PRO', 17, 13, 'Ũla ũtũngaa ũthũku vandũ va ũseo, Ũthũku ndũkauma nyũmbanĩ yake.'),
('kam', 'PRO', 17, 14, 'Wambĩlĩlyo wa ĩteta nĩ ta yĩla mũndũ wavũthũa manzĩ; Kwondũ wa ũu eka ngananĩo, kũtanethĩwa ĩteta.'),
('kam', 'PRO', 17, 15, 'Ũla ũtalĩlaa athũku ũlũngalu, na ũla ũtusaa alũngalu avĩtan’ya, Asu elĩ nĩ ũthatyo kwa Yeova.'),
('kam', 'PRO', 17, 16, 'Nĩkĩ mbesa syĩ kw’okonĩ kwa ndia ĩthooe ũĩ, Nayo ndĩ na ũmanyi?'),
('kam', 'PRO', 17, 17, 'Mũnyanya nĩwendanaa ĩndĩ yonthe; Na mwana‐a‐ĩthe asyaiwe kwondũ wa kũthĩnũkasya.'),
('kam', 'PRO', 17, 18, 'Mũndũ ũte ũmanyi nũkwatanasya moko, Na aitw’ĩka mũĩkĩĩthya mũtũi wake ene'),
('kam', 'PRO', 17, 19, 'Ũla wendaa ĩteta endaa ĩvĩtyo: Ũla ũkĩlasya mbingĩlo yake ĩũlũ mũno nũmanthaa wanangĩko.'),
('kam', 'PRO', 17, 20, 'Ũla wĩ na ngoo ngengani ndonaa ũseo o na wĩva; Na ũla wĩ na ũĩmĩ wĩ ngũlũ nũvalũkaa ũthũkunĩ.'),
('kam', 'PRO', 17, 21, 'Ũla ũsyaaa ndia ekaa ũu kwa woo wake; Na ĩthe wa ndia nde na ũtanu nongi.'),
('kam', 'PRO', 17, 22, 'Ngoo ndanu nĩ mũiito mũseo; Ĩndĩ veva mũtũlĩku ũtumaa mavĩndĩ moma.'),
('kam', 'PRO', 17, 23, 'Mũndũ mũthũku nĩwosaa ĩvaki kuma kĩthũinĩ, Elelũkasye nzĩa sya ũsili wa katĩ.'),
('kam', 'PRO', 17, 24, 'Ũĩ wĩ mbee wa ũthyũ wa ũla wĩ na ũmanyi; Ĩndĩ metho ma ndia me itulunĩ sya nthĩ.'),
('kam', 'PRO', 17, 25, 'Mwana mũtumanu nĩ woo kwa ĩthe wake, Na ũũ kwa ũla wamũsyaie.'),
('kam', 'PRO', 17, 26, 'O na kũsilĩla ala alũngalu ti ũseo, Kana kũkũna ala me ndaĩa nũndũ wa ũlũngalu woo.'),
('kam', 'PRO', 17, 27, 'Ũla ũsũvĩaa ndeto syake e na ũĩ; Na ũla wĩ na veva mũuu nĩ mũndũ wĩ na ũmanyi.'),
('kam', 'PRO', 17, 28, 'O na ndia, yĩla ĩvindĩtye, ĩtalawa nĩ mbũĩ; Yĩla ĩtumĩtye ilomo syayo, ĩtalawa yĩ na kĩlĩko.'),
('kam', 'PRO', 18, 1, 'Ũla wĩvathaa amanthaa kwenda kwake mwene, Na alonzanĩlasya ũĩ w’onthe mwĩanĩu.'),
('kam', 'PRO', 18, 2, 'Ndia ndĩtanĩaa ũmanyi, Ĩndĩ no kana ngoo yayo ĩtonye kwĩvuan’ya.'),
('kam', 'PRO', 18, 3, 'Yĩla mũthũku woka, kĩvũthya nakyo nĩkyũkaa, Na vamwe na nzonoko kũkaa kĩvũthya.'),
('kam', 'PRO', 18, 4, 'Ndeto sya kanyw’a wa mũndũ nĩ ta syũngũ; Mbuluti ya ũĩ nĩ ta kalũsĩ kavĩtĩtye.'),
('kam', 'PRO', 18, 5, 'Kwendeesya mũndũ mũthũku ti ũseo, Kana kwelelũkya ala alũngalu silanĩ.'),
('kam', 'PRO', 18, 6, 'Ilomo sya ndia nilikaa ngananĩonĩ, Na kanyw’a wayo nĩwĩtasya makũna.'),
('kam', 'PRO', 18, 7, 'Kanyw’a wa ndia nĩ wanangĩko wayo, Na ilomo syayo nĩ kĩtei kya ngoo yayo.'),
('kam', 'PRO', 18, 8, 'Ndeto sya ũla ũneenaa na kĩwe nĩ ta tũlungu tũseo twa lĩu, Na ilikaa nthĩnĩ ki.'),
('kam', 'PRO', 18, 9, 'O na ũla mũleelu wĩanĩ wake Nĩ mwana‐a‐inyia wa mwanangi.'),
('kam', 'PRO', 18, 10, 'Syĩtwa ya Yeova nĩ mwako mũtũlu wa mũnyoolo, Ũla mũlũngalu akĩĩaa vo, na nde na mũisyo.'),
('kam', 'PRO', 18, 11, 'Syĩndũ sya mũndũ mũthwii nĩ ndũa yake yĩ vinya, Na ta wako mũtũlu ũsũanĩonĩ wake.'),
('kam', 'PRO', 18, 12, 'Wanangĩko ũtanamba kũka ngoo ya mũndũ yĩ na wĩng’athĩlĩlyo; Na wĩnyivyo ũtongoeasya ndaĩa.'),
('kam', 'PRO', 18, 13, 'Ũla ũsũngĩaa atanamba kwĩw’a, Kwake nĩ ũtumanu na nthoni.'),
('kam', 'PRO', 18, 14, 'Veva wa mũndũ ũkatw’ĩĩka wonzu wake; Ĩndĩ veva mũtũlĩku nũũ ũtonya kũmĩĩsya?'),
('kam', 'PRO', 18, 15, 'Ngoo ya ũla wĩ na kĩlĩko nĩyosaa ũmanyi; Na kũtũ kwa ũla mũĩ nĩkũmanthaa ũmanyi.'),
('kam', 'PRO', 18, 16, 'Mũthĩnzĩo wa mũndũ nũmwonasya mwanya, Na kũmũete mbee wa andũ anene.'),
('kam', 'PRO', 18, 17, 'Ũla wambaa kũtetea ũvoo wake nĩwonekaa ta mũlũngalu; Ĩndĩ mũtũi wake ooka nũmũvuanasya.'),
('kam', 'PRO', 18, 18, 'Kũlimana nĩkũtumaa ngananĩo ithela, Na kũtaan’ya ala me na ũtonyi.'),
('kam', 'PRO', 18, 19, 'Mwana‐a‐asa alulutĩkw’a nĩ vinya kũtũngĩka kwĩ ndũa yĩ vinya; Na ngananĩo ta isu nĩ ta ivingi sya nyũmba nene yĩ kĩemo.'),
('kam', 'PRO', 18, 20, 'Ĩvu ya mũndũ yĩkausũw’a nĩ ũsyao wa kanyw’a wake; Akeanĩaw’a nĩ wingĩvo wa ilomo syake.'),
('kam', 'PRO', 18, 21, 'Kĩkw’ũ na thayũ syĩ vinyanĩ wa ũĩmĩ; Na ala mawendaa makaĩsaa ũsyao waw’o.'),
('kam', 'PRO', 18, 22, 'Ũla ũmeasya kĩveti nũmeasya kĩndũ kĩseo; Na kwona ũseo kuma kwa Yeova.'),
('kam', 'PRO', 18, 23, 'Ngya nĩsyĩsũvanaa; Ĩndĩ athwii masũngĩaa na vinya.'),
('kam', 'PRO', 18, 24, 'Ũla ũtumaa ndũũ na andũ aingĩ ekaa ũu ũndũ wa wanangĩko wake mwene; Ĩndĩ ve mũnyanya ũla ũlũmanasya mũno kwĩ mwana‐a‐inyia.'),
('kam', 'PRO', 19, 1, 'Kavaa ngya ĩla ĩkinyaa wĩanĩũnĩ wayo Kwĩ ũla wĩ na ngũlũ ilomonĩ syake na nĩ ndia.'),
('kam', 'PRO', 19, 2, 'O na ĩngĩ, thayũ kwĩthĩwa ũte na ũmanyi ti ũseo; Na ũla wĩkalaataa na maũũ make nũvĩtasya.'),
('kam', 'PRO', 19, 3, 'Ũtumanu wa mũndũ nũthũkasya mũendele wake; Na ngoo yake nĩmũnyungunyĩasya Yeova.'),
('kam', 'PRO', 19, 4, 'Ũthwii nĩwongelaa anyanya aingĩ; Ĩndĩ ngya nĩtaanaw’a na mũnyanyae wayo.'),
('kam', 'PRO', 19, 5, 'Ngũsĩ ya ũvũngũ ndĩkatĩa kũkũnwa; Na ũla ũneenaa movũngũ ndakavonoka.'),
('kam', 'PRO', 19, 6, 'Aingĩ makeesũva ũseo wa mũndũ mũlau; Na kĩla mũndũ nĩ mũnyanya wa ũla ũnenganae mĩthĩnzĩo.'),
('kam', 'PRO', 19, 7, 'Ana‐a‐inyia onthe ma ngya nĩmamĩmenaa: Nĩ mbee veana ata anyanyae mayo kũthi kũasa nayo! Nũmaatĩĩaa na ndeto, ĩndĩ nĩ aendu.'),
('kam', 'PRO', 19, 8, 'Ũla wĩthĩawa na ũĩ nĩwendaa thayũ wake mwene: Ũla ũsũvĩaa ũmanyi akoona ũseo.'),
('kam', 'PRO', 19, 9, 'Ngũsĩ ya ũvũngũ ndĩkatĩa kũkũnwa; Na ũla ũneenaa movũngũ akaaa.'),
('kam', 'PRO', 19, 10, 'Maũndũ ala mendeeasya thayũ ti maĩlu kwondũ wa ndia; Nĩ mbee veana ata kũlea kwaĩla, mũthũkũmi kũsumbĩka anene me mbee ũsumbĩnĩ.'),
('kam', 'PRO', 19, 11, 'Kĩlĩko kya mũndũ nĩkĩtumaa ethĩwa mũmĩĩsya wa kũthata; Na nĩ ndaĩa yake kũekea ĩvĩtyo.'),
('kam', 'PRO', 19, 12, 'Ũthilĩku wa mũsumbĩ nĩ ta kũluma kwa mũnyambũ; Ĩndĩ kwonan’ya kwake kwa ũseo nĩ ta ĩmwe nyekinĩ.'),
('kam', 'PRO', 19, 13, 'Mwana mũtumanu nĩ wanangĩko mũnene wa ĩthe wake; Na mateta ma kĩveti nĩ kũvolotanga kũtatw’ĩkanaa.'),
('kam', 'PRO', 19, 14, 'Nyũmba na mothwii nĩ ũtiĩwa kuma kwa aaĩthe; Ĩndĩ kĩveti kĩ kĩlĩko kyumaa kwa Yeova.'),
('kam', 'PRO', 19, 15, 'Ũtulu nĩwĩkasya toonĩ mũnene; Na mũndũ mũtulu akeew’aa nzaa.'),
('kam', 'PRO', 19, 16, 'Ũla ũkwataa mwĩao nũsũvĩaa thayũ wake; Ĩndĩ ũla ũte kĩio ũndũ wa mĩendele yake akakw’a.'),
('kam', 'PRO', 19, 17, 'Ũla wĩw’ĩaa ngya tei akovethasya Yeova, Na wĩko wake mũseo akamũĩva ĩngĩ.'),
('kam', 'PRO', 19, 18, 'Kũna mwana waku, nũndũ ve wĩkwatyo; Na ndũkende mũno ngoonĩ yaku wanangĩko wake.'),
('kam', 'PRO', 19, 19, 'Mũndũ wa ũthilĩku mũnene akakua ũsilĩlo, Nũndũ ethĩwa ũkamũvonokya, mũvaka wĩke ũu ĩngĩ.'),
('kam', 'PRO', 19, 20, 'Ĩw’a ũtao, na osa ũmanvĩsyo, Nĩ kana wĩthĩwe mũĩ mũminũkĩlyonĩ waku.'),
('kam', 'PRO', 19, 21, 'Kwĩ mosũanĩo maingĩ ngoonĩ ya mũndũ; Ĩndĩ ũtao wa Yeova, nĩw’o wĩĩkalaa.'),
('kam', 'PRO', 19, 22, 'Kĩla kĩtuma mũndũ kwendwa nĩ ũseo wake; Na mũndũ ngya e kavaa kwĩ mũneeni wa ũvũngũ.'),
('kam', 'PRO', 19, 23, 'Kũmũkĩa Yeova nĩkũetae thayũ; Na ũla wĩ nakw’o akekalaa eanĩwe; Ndakokĩwa nĩ ũthũku.'),
('kam', 'PRO', 19, 24, 'Mũndũ mũtulu nũindaa kw’oko kwake ĩsaaninĩ, Na ndeĩtĩkĩla o na kũkũete kanyw’anĩ wake ĩngĩ.'),
('kam', 'PRO', 19, 25, 'Kũna mũkaakaan’ya, na ũla ũte ũmanyi akeemanyĩsya kwĩthĩwa na kĩlĩko; Na kan’ya ũla wĩ na ũmanyi, na akamanya ũĩ.'),
('kam', 'PRO', 19, 26, 'Ũla ũmũng’endeaa ĩthe, na kũlũngya inyia wake, Nĩ mwana ũla ũsonokasya na kũete kĩvũthya.'),
('kam', 'PRO', 19, 27, 'Eka, mwana wakwa, kwĩw’a ũmanyĩsyo Na ĩndĩ ũkĩvĩtya na kũtia ndeto sya ũmanyi.'),
('kam', 'PRO', 19, 28, 'Ngũsĩ ĩte vata nĩthekeeaa ũsili wa katĩ; Na kanyw’a wa ũla mũthũku nũmelasya ũthũku.'),
('kam', 'PRO', 19, 29, 'Mosilĩlo nĩmaseũvĩaw’a akaakaan’ya, Na makũna kwondũ wa mĩongo ya ndia.'),
('kam', 'PRO', 20, 1, 'Mbinyu nĩ mũkaakaan’ya, kĩla kĩtoonasya nĩ kĩlonzo kĩnene; Na ũla ũvĩtasya kwondũ wayo ti mũĩ.'),
('kam', 'PRO', 20, 2, 'Ũtĩsyo wa mũsumbĩ nĩ ta kũluma kwa mũnyambũ: Ũla ũmũthatasya nũvĩtĩasya thayũ wake mwene.'),
('kam', 'PRO', 20, 3, 'Nĩ ndaĩa ya mũndũ kwĩkala kũasa na ĩteta; Ĩndĩ kĩla ndia ĩkatetanasya.'),
('kam', 'PRO', 20, 4, 'Mũndũ mũtulu nũleaa kũĩma nũndũ wa ĩvinda ya mbevo; Kwondũ wa ũu akavoya ĩvinda ya ngetha, na ndakethĩwa na kĩndũ.'),
('kam', 'PRO', 20, 5, 'Ũtao ngoonĩ ya mũndũ nĩ ta kyũngũ; Ĩndĩ mũndũ wĩ ũmanyi akookusya wume.'),
('kam', 'PRO', 20, 6, 'Andũ aingĩ matavanasya kĩla ũmwe ũseo wake mwene; Ĩndĩ mũndũ wĩ kĩthito nũũ ũtonya kũmwona?'),
('kam', 'PRO', 20, 7, 'Mũndũ mũlũngalu ũla ũendaa wĩanĩunĩ wake, Syana syake nĩ ngathime ĩtina wake.'),
('kam', 'PRO', 20, 8, 'Mũsumbĩ ũla wĩkalaa kĩvĩlanĩ kya ũsumbĩ kya kũsila Nũvalaanasya ũthũku w’onthe na metho make.'),
('kam', 'PRO', 20, 9, 'Nũũ ũtonya kwasya, Nĩnĩtheetye ngoo yakwa, Nĩ mũtheu kuma naĩnĩ yakwa?'),
('kam', 'PRO', 20, 10, 'Mavia ala mathimaa matailyĩ ũndũ ũmwe, na ithimi itailyĩ ũndũ ũmwe, Isu syonthe nĩ ũthatyo kwa Yeova.'),
('kam', 'PRO', 20, 11, 'O na kana nĩkemanyĩthanasya kwondũ wa meko mako, Ethĩwa wĩa wako nĩ mũtheu na ethĩwa nĩ mũlũngalu.'),
('kam', 'PRO', 20, 12, 'Kũtũ kũla kwĩw’aa, na itho yĩla yonaa, Yeova nũseũvĩtye syelĩ.'),
('kam', 'PRO', 20, 13, 'Ndũkende too, ndũkese kũvikĩa ũkya; Salukya metho maku, na ũkavũna lĩu.'),
('kam', 'PRO', 20, 14, 'Nĩ kĩthũku, nĩ kĩthũku, easya ũla ũthooaa; Ĩndĩ eeyĩendea, nĩvo ĩndĩ wĩkathĩĩaa.'),
('kam', 'PRO', 20, 15, 'Ve thaavu, na tũvila twa maliani twingĩ mũno; Ĩndĩ ilomo syĩ ũĩ nĩ mũio wa wanake wĩ thooa mũnene.'),
('kam', 'PRO', 20, 16, 'Osa ngũa yake ũla mũĩkĩĩthya kwondũ wa mũeni; Noimwĩkalya ethĩwe ngwatĩlĩlyo ũla mũĩkĩĩthya kwondũ wa andũ ma nthĩ ĩngĩ.'),
('kam', 'PRO', 20, 17, 'Lĩu wa ũvũngũ wĩ mũyo kwa mũndũ; Ĩndĩ ĩtina kanyw’a wake ũkausũa thaathai.'),
('kam', 'PRO', 20, 18, 'Kĩla ũsũanĩo ũlũlũmĩlaw’a nĩ ũtao; Na kwatya kaũ kwondũ wa ũtongoi mũĩ.'),
('kam', 'PRO', 20, 19, 'Ũla ũendaa kũũ na kũũ e mũsukani nũvuanasya nzama: Kwondũ wa ũu ndũkatindan’ye na ũla ũtumũkanganasya ilomo syake mũno.'),
('kam', 'PRO', 20, 20, 'O ũla ũumaa ĩthe kana nyinya, Taa wake ũkavoew’a wiũnĩ wa kĩvindu.'),
('kam', 'PRO', 20, 21, 'Ũtiĩwa nũtonya kwoswa mĩtũkĩ wambĩlĩlyonĩ; Ĩndĩ mũminũkĩlyo waw’o ndũkaathimwa.'),
('kam', 'PRO', 20, 22, 'Ndũkasye, Ngeeĩvanĩsya ũthũku: Mweteele Yeova, nake akakũtangĩĩa.'),
('kam', 'PRO', 20, 23, 'Mavia ala mathimaa matailyĩ ũndũ ũmwe nĩ ũthatyo kwa Yeova; Na kĩthimi kya ũkengani ti kĩseo.'),
('kam', 'PRO', 20, 24, 'Mĩendele ya mũndũ yumaa kwa Yeova; Mũndũ atonya ata ĩndĩ kũmanya nzĩa yake?'),
('kam', 'PRO', 20, 25, 'Nĩ kĩtei kwa mũndũ kũneena na mĩtũkĩ, Kĩĩ nĩ kĩtheu, Na ĩtĩna wa kwĩvĩta aikũlya.'),
('kam', 'PRO', 20, 26, 'Mũsumbĩ mũĩ aũlũkasya ala athũku, Na kũvĩtĩlya ndĩa ya kũvũa ĩũlũ wamo.'),
('kam', 'PRO', 20, 27, 'Veva wa mũndũ nĩ taa wa Yeova, Ũkĩmantha nthĩnĩ wake kw’onthe.'),
('kam', 'PRO', 20, 28, 'Ũseo na w’o masũvĩaa mũsumbĩ; Na kĩvĩla kyake kya ũsumbĩ nĩkĩtw’ĩĩkawa nĩ ũseo.'),
('kam', 'PRO', 20, 29, 'Ndaĩa ya anake nĩ vinya woo; Na wanake wa atumĩa nĩ mũtwe wĩ mbuĩ.'),
('kam', 'PRO', 20, 30, 'Makũna ala mokitĩthasya matheasya ũthũku; Na makũna makĩlika nthĩnĩ ki.'),
('kam', 'PRO', 21, 1, 'Ngoo ya mũsumbĩ yĩ kwiokonĩ kwa Yeova ta mokinyĩlo ma manzĩ: Nake amĩthyũũaa o vala ũnũkwenda.'),
('kam', 'PRO', 21, 2, 'Kĩla mũendele wa mũndũ nĩ mũlũngalu methonĩ make mwene; Ĩndĩ Yeova athimaa ngoo.'),
('kam', 'PRO', 21, 3, 'Kwĩka ũlũngalu na ũsili wa katĩ Nĩkwĩtĩkĩlawa nĩ Yeova kwĩ nthembo.'),
('kam', 'PRO', 21, 4, 'Mũsyaĩlye wa mĩng’athĩlĩlyo, na ngoo ya ngathĩĩo, O taa wa ũla mũthũku, nĩ naĩ.'),
('kam', 'PRO', 21, 5, 'Mosũanĩo ma ala athingu maelete wingĩnĩ wa syĩndũ; Ĩndĩ kĩla mũndũ ũla wĩkalaataa ekalaataa kũvika akaĩwe tũ.'),
('kam', 'PRO', 21, 6, 'Kwosa mothwĩĩ kwondũ wa ĩũmĩ ũla ũneenaa ũvũngũ Nĩ mũki ũtwaawa kũũ na kũũ nĩ ala mamanthaa kĩkw’ũ.'),
('kam', 'PRO', 21, 7, 'Ũng’endu wa ala athũku ũkamatwaa kũasa, Nĩkwĩthĩwa nĩmaleaa kũsila katĩ.'),
('kam', 'PRO', 21, 8, 'Mũendele wa ũla ũitavĩwe nĩ naĩ nĩ mũthyoeku mũno; Ĩndĩ ũndũ wa ũla mũtheu, wĩa wake nĩ mũlũngalu.'),
('kam', 'PRO', 21, 9, 'Nĩ kavaa kwĩkalaa kĩkotonĩ kya nyũmba ĩũlũ, Kwĩ kwĩkalaa na mũndũ mũka wĩ ĩteta nyũmbanĩ nthanthau.'),
('kam', 'PRO', 21, 10, 'Ngoo ya ũla mũthũku nĩyendaa ũthũku: Mũtũi wake ndonaa ũseo methonĩ make.'),
('kam', 'PRO', 21, 11, 'Yĩla mũkaakaan’ya wakũnwa, ũla ũte ũmanyi nũtw’ĩkaa mũĩ; Na yĩla ũla mũĩ wamanyĩw’a, nĩwosaa ũmanyi.'),
('kam', 'PRO', 21, 12, 'Mũndũ mũlũngalu nũsũanĩaa ũndũ wa nyũmba ya ũla mũthũku, Ũndũ athũku mavalũkaw’a manangĩke.'),
('kam', 'PRO', 21, 13, 'O ũla ũkunĩkaa matũ matikew’e kĩĩo kya ngya, Nake akaĩa, ĩndĩ ndakew’ĩka.'),
('kam', 'PRO', 21, 14, 'Mũthĩnzĩo kĩmbithĩnĩ nũvoovasya ũthatu; Na mũthĩnzĩo kĩthũinĩ nũvoovasya ũthilĩku mwai.'),
('kam', 'PRO', 21, 15, 'Nĩ ũtanu kwa ala alũngalu kũsila katĩ; Ĩndĩ nĩ wanangiko kwa eki ma ũthũku.'),
('kam', 'PRO', 21, 16, 'Mũndũ ũla wangangaa kuma nzĩanĩ ya ũmanyi Akathũmũa ũmbanonĩ wa akw’ũ.'),
('kam', 'PRO', 21, 17, 'Ũla wendaa motanu akeethĩwa mũndũ ngya: Ũla wendaa mbinyu na mauta ndakethĩwa mũthwii.'),
('kam', 'PRO', 21, 18, 'Ũla mũthũku nĩ mbovosya kwondũ wa ũla mũlũngalu; Na nzeleke nĩyũkaa vandũ va ũla mũlũngalu.'),
('kam', 'PRO', 21, 19, 'Nĩ kavaa kũtũaa nthĩ yĩ yalata, Kwĩ kũtũaa na mũndũ mũka wĩ ngananĩo na mũnyungunyĩsyo.'),
('kam', 'PRO', 21, 20, 'Ve syĩndũ syĩ vata mũno o na mauta ũtũonĩ wa ala oĩ; Ĩndĩ mũndũ mũtumanu nĩwimelasya.'),
('kam', 'PRO', 21, 21, 'Ũla ũatĩĩaa ũlũngalu na ũseo Nĩwonaa thayũ, na ũlũngalu, na ndaĩa.'),
('kam', 'PRO', 21, 22, 'Mũndũ mũĩ nũlĩsaa alike ndũanĩ ya ala me na ũtonyi, Na aitheeesya vinya wa wĩkwatyo wayo.'),
('kam', 'PRO', 21, 23, 'Ũla ũsũvĩaa kanyw’a wake na ũĩmĩ wake Nũsũvĩaa ngoo yake mathĩna.'),
('kam', 'PRO', 21, 24, 'Mũndũ e na ngathĩĩo na wĩng’athĩlĩlyo, syĩtwa yake nĩ mũkaakaan’ya; Nũtethasya wĩa wĩnenevyonĩ wa ngathĩĩo.'),
('kam', 'PRO', 21, 25, 'Kwenda kwa ũla mũtulu nĩkũmũaaa; Nũndũ moko make nĩmaleaa kũtethya wĩa.'),
('kam', 'PRO', 21, 26, 'Kwĩ ũla wĩw’aa ĩtomo na ũtoonu mũthenya w’onthe; Ĩndĩ ũla mũlũngalu nũnenganae na ndaimaa.'),
('kam', 'PRO', 21, 27, 'Nthembo ya ũla mũthũku nĩ ũthatyo: Nĩ mbee veana ata, yĩla wĩete na kĩlilikano kĩthũku!'),
('kam', 'PRO', 21, 28, 'Ngũsĩ ya ũvũngũ ĩkaaa; Ĩndĩ mũndũ ũla wĩw’aa akaneenaa ĩndĩ yonthe.'),
('kam', 'PRO', 21, 29, 'Mũndũ mũthũku nĩwetasya ũthyũ wake; Ĩndĩ ũndũ wa ũla mũlũngalu, nake nũlũlũmĩlasya mĩendele yake.'),
('kam', 'PRO', 21, 30, 'Vati ũĩ kana ũmanyi Kana ũtao ũtonya kũkita na Yeova.'),
('kam', 'PRO', 21, 31, 'Mbalasi nĩyũmbanĩtw’e ũndũ wa mũthenya wa kaũ; Ĩndĩ ũkĩlyo nĩ wa Yeova.'),
('kam', 'PRO', 22, 1, 'Nĩ kavaa kũnyuva syĩtwa ĩseo kwĩ mothwii manene, Na ũseo ũla wonanaw’a nĩ wendo kwĩ vetha na thaavu.'),
('kam', 'PRO', 22, 2, 'Athwii na ngya makomanaa vamwe: Yeova nĩwe mũmbi woo onthe.'),
('kam', 'PRO', 22, 3, 'Mũndũ wĩ kĩlĩko nĩwonaa ũthũku, na kwĩvitha; Ĩndĩ ala mate ũmanyi nĩmaendeeaa, na kũthĩna.'),
('kam', 'PRO', 22, 4, 'Ĩtuvi ya wĩnyivyo na kũmũkĩa Yeova Nĩ ũthwii, na ndaĩa, na thayũ.'),
('kam', 'PRO', 22, 5, 'Mĩw’a na itei syĩ nzĩanĩ ya ala me na ngũlũ: Ũla ũsũvĩaa ngoo yake akeethĩwa kũasa nasyo.'),
('kam', 'PRO', 22, 6, 'Manyĩsya kana nzĩa ĩla kaĩle kũendaa nayo, O na akũa ndakamĩtia.'),
('kam', 'PRO', 22, 7, 'Mũthwii nũsumbĩkaa ngya; Na ũla ũkovaa nĩ mũthũkũmi wa ũla ũkovethasya.'),
('kam', 'PRO', 22, 8, 'Ũla ũvuĩaa ũthũku akaketha wanangĩko mũnene; Na ndata ya ũthilĩku wake ĩkaa vinya.'),
('kam', 'PRO', 22, 9, 'Ũla wĩ na itho ĩlau akaathimwa; Nũndũ nũnengae ngya kuma lĩunĩ wake.'),
('kam', 'PRO', 22, 10, 'Mwĩkye nza mũkaakaan’ya, na ngananĩo ĩkaumaala; Ĩĩ, ĩteta na nzonoko ikathela.'),
('kam', 'PRO', 22, 11, 'Ũla wendaa ũtheu wa ngoo, Nũndũ wa mumo wa ilomo syake mũsumbĩ akeethĩwa mũnyanyae.'),
('kam', 'PRO', 22, 12, 'Metho ma Yeova masũvĩaa ũla wĩ na ũmanyi; Ĩndĩ nĩwanangaa ndeto sya nzeleke.'),
('kam', 'PRO', 22, 13, 'Mũndũ mũtulu easya, Ve mũnyambũ nza; Ngooaĩwa nzĩanĩ nene.'),
('kam', 'PRO', 22, 14, 'Kanyw’a wa aka aeni nĩ ĩima ĩliku; Ũla ũthĩthawa nĩ Yeova akavalũka nthĩnĩ wayo.'),
('kam', 'PRO', 22, 15, 'Ũtumanu nĩwovetwe ngoonĩ ya kana; Ĩndĩ ndata ya kwon’ya mavĩtyo ĩkoolũngya kũasa nako.'),
('kam', 'PRO', 22, 16, 'Ũla ũthĩnasya ngya nĩ kana aingĩvye ũtandĩthyo wake, Na ũla ũnenganae kwa athwii, akavika kwaĩwanĩ tũ.'),
('kam', 'PRO', 22, 17, 'Tea kũtũ kwaku, nokĩw’a ndeto sya ala oĩ, Noinengane ngoo yaku ũmanyinĩ wakwa.'),
('kam', 'PRO', 22, 18, 'Nũndũ nĩ ũndũ wa kwendeesya ethĩwa ũkasyĩkalya nthĩnĩ waku, Ethĩwa nilũlũmĩlw’e vamwe ilomonĩ syaku.'),
('kam', 'PRO', 22, 19, 'Nĩ kana ũĩkĩĩi waku wĩthĩwe nthĩnĩ wa Yeova, Nĩnĩkũmanyĩthĩtye syo ũmũnthĩ, o we.'),
('kam', 'PRO', 22, 20, 'Ndikũandĩkĩe maũndũ manene Ma motao na ũmanyi,'),
('kam', 'PRO', 22, 21, 'Nĩtume ũmanya ki ndeto sya w’o, Nĩ kana ũmatũngĩae ndeto sya w’o ala makũtũmaa?'),
('kam', 'PRO', 22, 22, 'Ndũkavute ngya, nũndũ nĩ ngya; O na ndũkathĩnye ala athĩni mbingĩlonĩ:'),
('kam', 'PRO', 22, 23, 'Nũndũ Yeova akamatetea, Na kũmavuta thayũ ala mamavutaa.'),
('kam', 'PRO', 22, 24, 'Ndũkatume ndũũ na ũla ũthataa; Na ndũkaendan’ye na mũndũ ũthilĩkaa:'),
('kam', 'PRO', 22, 25, 'Ndũkese kwĩmanyĩsya mĩendele yake, Na kwosea ngoo yaku kĩtei.'),
('kam', 'PRO', 22, 26, 'O na ndũkethĩwe ũmwe wa ala makwatanasya moko, Kana wa aĩkĩĩthya kwondũ wa mathĩĩ.'),
('kam', 'PRO', 22, 27, 'Ethĩwa ndwĩ na kya kũĩva, Aĩle ata kũtwaa ũkomo waku kumya ungu waku?'),
('kam', 'PRO', 22, 28, 'Ndũkaakũĩĩsye kyambo kya mũvaka wa tene, Kĩla aaĩthe maku meekĩie.'),
('kam', 'PRO', 22, 29, 'Nũkwona mũndũ mũthingu wĩanĩ wake? Akaũngama mbee wa asumbĩ; Ndakaũngama mbee wa andũ mate na nguma.'),
('kam', 'PRO', 23, 1, 'Yĩla wĩĩkala nthĩ kũya na mũsumbĩki. Sũanĩa mũno ũla wĩ mbee waku;'),
('kam', 'PRO', 23, 2, 'Nokĩkĩa kavyũ mũmeonĩ waku, Ethĩwa wĩ mũndũ ũla wendaa kũya.'),
('kam', 'PRO', 23, 3, 'Ndũkende sya ũya syake nzeo; Nũndũ nĩ malĩu ma ũkengani.'),
('kam', 'PRO', 23, 4, 'Ndũkenosye wĩthĩwe mũthwii; Ekana na ũĩ waku mwene.'),
('kam', 'PRO', 23, 5, 'Ũkaketeea kĩla kĩte vo? Nũndũ vate ndĩi mothwii nĩmeseũvĩasya nthwau, Ta ndiũ ĩla ĩũlũkaa yelekele ĩtunĩ.'),
('kam', 'PRO', 23, 6, 'Ndũkaye lĩu wa ũla wĩ na itho ĩthũku, O na ndũkende sya ũya syake nzeo:'),
('kam', 'PRO', 23, 7, 'Nũndũ, o tondũ ũsũanĩaa nthĩnĩ wake mwene, now’o ũilyĩ: Ekwĩa, Ya na nyw’a; Ĩndĩ ngoo yake ndĩ vamwe naku.'),
('kam', 'PRO', 23, 8, 'Kalungu kala waya ũkakatavĩka, Na kũsyasya ndeto syaku syĩ mũyo.'),
('kam', 'PRO', 23, 9, 'Ndũkaneene ndia ĩkĩw’a; Nũndũ ĩkavũthya ũĩ wa ndeto syaku.'),
('kam', 'PRO', 23, 10, 'Ndũkaakũĩĩsye kyambo kya mũvaka wa tene; Na ndũkalike mĩũndanĩ ya ala makw’ĩĩwe nĩ aaĩthe:'),
('kam', 'PRO', 23, 11, 'Nũndũ Mwovosya woo e na vinya; Akamatetanĩsya kwaku.'),
('kam', 'PRO', 23, 12, 'Nengane ngoo yaku ũmanyĩsyonĩ, Na matũ maku ndetonĩ sya ũmanyi.'),
('kam', 'PRO', 23, 13, 'Ndũkasiĩĩe ũkan’yo kwa kana; Nũndũ ethĩwa ũkakakũna na ndata, kaikakw’a.'),
('kam', 'PRO', 23, 14, 'Ũkakakũna na ndata, Na kũvonokya thayũ wako kaikalike Seoli.'),
('kam', 'PRO', 23, 15, 'Mwana wakwa, ethĩwa ngoo yaku nĩ mbũĩ, Ngoo yakwa ĩkatana, o ĩ yakwa:'),
('kam', 'PRO', 23, 16, 'Ĩĩ, ngoo yakwa ĩkatana, Yĩla ilomo syaku ineenaa maũndũ ma w’o.'),
('kam', 'PRO', 23, 17, 'Ngoo yaku ndĩkamew’ĩe andũ athe kĩwĩu; Ĩndĩ ĩthĩwa ũkĩmũkĩa Yeova mũthenya w’onthe:'),
('kam', 'PRO', 23, 18, 'Nũndũ vate ndĩi kwĩ ĩtuvi; Na wĩkwatyo waku ndũkavetwa.'),
('kam', 'PRO', 23, 19, 'Ĩw’a we, mwana wakwa, na ĩthĩwa na ũĩ, Noitongoesya ngoo yaku nzĩanĩ.'),
('kam', 'PRO', 23, 20, 'Ndũkethĩwe katĩ wa anywi ma mbinyu Katĩ wa ayi ma nyama na ũtoonu:'),
('kam', 'PRO', 23, 21, 'Nũndũ mũnywi na mũyi makavika ũkyanĩ; Na kwombosya nĩkũmũvw’ĩkaa mũndũ matani.'),
('kam', 'PRO', 23, 22, 'Ĩthukĩĩsye au ũla wakũsyaie, Na ndũkavũthye mwenyu akũa.'),
('kam', 'PRO', 23, 23, 'Thooa w’o, na ndũkothoosye; Ĩĩ, ũĩ, na ũmanyĩsyo, na ũmanyi.'),
('kam', 'PRO', 23, 24, 'Ĩthe wa ũla mũlũngalu akatana mũno; Na ũla wĩsyaa kana koĩ akeethĩwa na ũtanu kwondũ wako.'),
('kam', 'PRO', 23, 25, 'Au na mwenyu methĩwe na mũyo, Na ũla wakũsyaie natane.'),
('kam', 'PRO', 23, 26, 'Mwana wakwa, nenga ngoo yaku; Na metho maku matanĩe nzĩa syakwa.'),
('kam', 'PRO', 23, 27, 'Nũndũ ĩlwaya nĩ mũtaũ mũliku; Na mũndũ mũka wa nthĩ ĩngĩ nĩ ĩima ĩtheke.'),
('kam', 'PRO', 23, 28, 'Ĩĩ, nĩwoveeasya ta mũvutani, Na kwingĩvya nzeleke katĩ wa andũ.'),
('kam', 'PRO', 23, 29, 'Nũũ wĩ na woo? Nũũ wĩ na kĩmako? Nũũ wĩ na ngananĩo? Nũũ wĩ na mũnyungunyĩsyo? Nũũ wĩ na mawũkite vate kĩtumi? Nũũ wĩ na metho matune?'),
('kam', 'PRO', 23, 30, 'Ala mekalaa ĩvinda ĩasa mainyw’a; Ala maendaa mamanthe mbinyu mbulan’ye.'),
('kam', 'PRO', 23, 31, 'Ndũkasisye mbinyu yĩla yatunĩva, Yĩla ĩtisatisĩaa kĩkombenĩ, Yĩla ĩnĩũmeleka nesa:'),
('kam', 'PRO', 23, 32, 'Mũminũkĩlyo nĩũmanaa ta nzoka, Na kũtonya ta kĩmbuva.'),
('kam', 'PRO', 23, 33, 'Metho maku makoona maũndũ maeni, Na ngoo yaku ĩkaneena maũndũ ma ngũlũ.'),
('kam', 'PRO', 23, 34, 'Ĩĩ, ũkeethĩwa ta ũla ũkomaa ũkanganĩ katĩ, Kana ta ũla ũkomaa mũthyanĩ wa mũlingoti.'),
('kam', 'PRO', 23, 35, 'Ũkasya, Nĩmangũnĩte na ndyaaĩkwa ũndũ ũthũku; Nĩmangũnĩte, na ndyaaĩw’a ũndũ: Ngaamũka ĩndĩĩ? Ngamĩmantha ĩngĩ.'),
('kam', 'PRO', 24, 1, 'Ndũkamew’ĩe kĩwĩu andũ athũku; O na ndũkende kwĩthĩwa nao.'),
('kam', 'PRO', 24, 2, 'Nũndũ ngoo syoo nĩsũanĩaa kũthĩn’ya, Na ilomo syoo nineenaa ũndũ wa ũthũku.'),
('kam', 'PRO', 24, 3, 'Kwondũ wa ũĩ nyũmba nĩyakawa; Na kwondũ wa ũmanyi nĩlũmaw’a;'),
('kam', 'PRO', 24, 4, 'Na kwondũ wa ũĩ tũsũmba nĩtusũaw’a Mothwii onthe me vata mũno na ma kwendeesya.'),
('kam', 'PRO', 24, 5, 'Mũndũ mũĩ e na vinya; Ĩĩ, mũndũ wa ũmanyi nĩwingĩvasya ũtonyi.'),
('kam', 'PRO', 24, 6, 'Nũndũ kwondũ wa ũtongoi mũĩ ũkakwatya kaũ waku; Na wingĩnĩ wa atai kwĩ ũkĩlyo.'),
('kam', 'PRO', 24, 7, 'Ũĩ wĩ ĩũlũ mũno kũmĩvĩtũka ndia: Ndĩathamĩasya kanyw’a wayo mbingĩlonĩ.'),
('kam', 'PRO', 24, 8, 'Ũla ũsũanĩaa kwĩka ũthũku, Andũ makamwĩta mũkwatya wa ũthũku.'),
('kam', 'PRO', 24, 9, 'Ũsũanĩo wa ũtumanu nĩ naĩ; Na mũkaakaan’ya nĩ ũthatyo wa andũ.'),
('kam', 'PRO', 24, 10, 'Ethĩwa nũnyalaa mũthenya wa thĩna, Vinya waku nĩ mũnini.'),
('kam', 'PRO', 24, 11, 'Vonokya ala matwaawa kĩkw’ũnĩ, Na ala makilĩlye kũawa sĩsya kana ũmasiĩĩe.'),
('kam', 'PRO', 24, 12, 'Ethĩwa wĩasya, Sisya, tũtyaamanya ũu; Ũla ũthimaa ngoo ndasũanĩaa ũu? Na ũla ũsũvĩaa ngoo yaku, ndesĩ ũu? Na ndakamũĩva kĩla mũndũ kwĩanana na wĩa wake?'),
('kam', 'PRO', 24, 13, 'Mwana wakwa, ya ũkĩ wa nzũkĩ, nũndũ nĩ mũseo; Na mavolotango ma ĩwa me mũyo ũkĩmasama:'),
('kam', 'PRO', 24, 14, 'O ta ũu ũkamanya ũĩ ũilyĩ ũu kwa ngoo yaku; Ethĩwa nũwonete, nĩvo kũkethĩwa ĩtuvi, Na wĩkwatyo waku ndũkavetwa.'),
('kam', 'PRO', 24, 15, 'We mũndũ mũthũku ndũkoveesye ũtũo wa ũla mũlũngalu; Ndũkaanange vandũ vake va ũthũmũa:'),
('kam', 'PRO', 24, 16, 'Nũndũ mũndũ mũlũngalu nũvalũkaa mavinda mũonza, na kũkĩla ĩngĩ: Ĩndĩ ala athũku nĩmanangawa nĩ wanangĩko mũnene.'),
('kam', 'PRO', 24, 17, 'Ndũkatane yĩla mũmaitha waku ũvalũkaa, Na ngoo yaku ndĩkatane yĩla wanangĩkaa;'),
('kam', 'PRO', 24, 18, 'Yeova ndakese kũwona, na ũkamwĩw’ĩthya woo, Na aithyũũa ũthilĩku wake ume kwake.'),
('kam', 'PRO', 24, 19, 'Ndũkenyamasye ũndũ wa eki ma ũthũku; O na ndũkamew’ĩe kĩwĩu ala athũku:'),
('kam', 'PRO', 24, 20, 'Nũndũ kũikethĩwa ĩtuvi ya mũndũ mũthũku; Taa wa ũla mũthũku ũkavow’a.'),
('kam', 'PRO', 24, 21, 'Mwana wakwa, mũkĩe Yeova o na mũsumbĩ; Na ndũkatindan’ye na ala maalyũkaa:'),
('kam', 'PRO', 24, 22, 'Nũndũ wanangĩko woo mũnene ũkookĩla na kĩthũlũmũko; Na kwananga kwa asu elĩ, nũũ ũla ũkwĩsĩ?'),
('kam', 'PRO', 24, 23, 'Ii nasyo nĩ ndeto sya ala oĩ. Kwendeesya andũ ũkĩsila ti kũseo.'),
('kam', 'PRO', 24, 24, 'Ũla ũtavasya ũla mũthũku, Wĩ mũlũngalu, Ngo sya andũ ikamũuma, mbaĩ ikamũthĩtha;'),
('kam', 'PRO', 24, 25, 'Ĩndĩ ala mamũkanasya makeethĩwa atanu, Na ũathimo mũseo ũkamokĩa.'),
('kam', 'PRO', 24, 26, 'Nũmumunyaa ilomo Ũla ũsũngĩaa ũsũngĩo wa w’o.'),
('kam', 'PRO', 24, 27, 'Seũvya wĩa waku na ku nza, Wĩseũvĩsye mũũnda; Na ĩtina aka nyũmba yaku.'),
('kam', 'PRO', 24, 28, 'Ndũkamũkũsĩĩe mũtũi waku vate kĩtumi; Na ndũkakengane na ilomo syaku.'),
('kam', 'PRO', 24, 29, 'Ndũkasye, Ngamwĩka o tondũ ũmbĩkĩte; Ngamũĩva ũ mũndũ kwĩanana na wĩa wake.'),
('kam', 'PRO', 24, 30, 'Navĩtĩla ũtee wa mũũnda wa mũndũ mũtulu, Na mũũnda wa mĩsavivũ wa mũndũ ũtaĩ ũmanyi;'),
('kam', 'PRO', 24, 31, 'Na, sisya, wausũĩte mĩw’a, Na weekunĩkĩlw’e nĩ syĩnyeelya, Na ũvai wa mavia waw’o waĩ mũvalũku.'),
('kam', 'PRO', 24, 32, 'Nĩvo ĩndĩ nasiisye, na kũsũanĩa nesa; Noona, na noosa ũmanyĩsyo:'),
('kam', 'PRO', 24, 33, 'Too mũnini, kwombosya vanini, Kũkwatan’ya syaa vanini ũkome;'),
('kam', 'PRO', 24, 34, 'O ta ũu ũkya waku ũkooka ta mũvutani, Na kwaĩwa kwaku ta mũndũ wĩkĩĩte mĩio ya kaũ.'),
('kam', 'PRO', 25, 1, 'Ii nasyo nĩ nthimo sya Solomoni, ila andũ ma Esekia mũsumbĩ wa Yũta meeyumĩĩĩsye.'),
('kam', 'PRO', 25, 2, 'Nĩ ũtaĩo wa Ngai kũvitha ũndũ; Ĩndĩ ũtaĩo wa asumbĩ nĩ kũmantha ũndũ.'),
('kam', 'PRO', 25, 3, 'O tondũ matunĩ kũtũlĩte, na nthĩ kũlikĩte, Now’o ngoo ya asumbĩ ndĩmanthĩka.'),
('kam', 'PRO', 25, 4, 'Umya makwaũ nthĩnĩ wa vetha, Na kũkaumĩla mũio kwondũ wa mũui waw’o;'),
('kam', 'PRO', 25, 5, 'Umya ala athũku mbee wa mũsumbĩ, Na kĩvĩla kyake kya ũsumbĩ kĩkalũlũmĩlw’a ũlũngalunĩ.'),
('kam', 'PRO', 25, 6, 'Ndũkenenevye vala ve mũsumbĩ, Na ndũkaũngame vandũnĩ va andũ anene:'),
('kam', 'PRO', 25, 7, 'Nũndũ nĩ kavaa ũkewa, Ambata vaa, Kwĩ kũtheeangw’a mũnene wĩ mbee ũsumbĩnĩ ene, Ũla metho maku mamwonete.'),
('kam', 'PRO', 25, 8, 'Ndũkaumaale mĩtũkĩ ũkatete, Ndũkese kũlea kũmanya wa kwĩka mũminũkĩlyonĩ waw’o, Yĩla mũtũi waku ũkũsonoketye.'),
('kam', 'PRO', 25, 9, 'Ĩoan’ye na mũtũi waku, Na ndũkavuan’ye nzama ya ũngĩ;'),
('kam', 'PRO', 25, 10, 'Ũla ũmĩw’aa ndakese ũkũuma, Na nguma yaku nthũku ĩkĩlea kũvetwa.'),
('kam', 'PRO', 25, 11, 'Ndeto ĩneenawa ĩvinda yayo Nĩ ta mosyao ma mũevo ma thaavu kĩkavũnĩ kya vetha.'),
('kam', 'PRO', 25, 12, 'Ta ngome ya kũtũ ya thaavu, na wananake wa thaavu mũseo, Now’o kũilyĩ mũkan’ya mũĩ kũtũnĩ kũla kwĩw’aa.'),
('kam', 'PRO', 25, 13, 'Ta mbevo ya ĩa ĩvinda ya ngetha, Now’o ũilyĩ mũtũmwa wĩ kĩthito kwa ala mamũtũmaa; Nũndũ nũvuũkasya ngoo ya mavwana make.'),
('kam', 'PRO', 25, 14, 'Ta mathweo na kĩseve vate mbua, Now’o ũilyĩ ũla wĩkathĩĩaa na ũkengani kwondũ wa mĩthĩnzĩo yake.'),
('kam', 'PRO', 25, 15, 'Kwondũ wa kũmĩĩsya ĩvinda ĩasa mũsumbĩki nũtonya kũkikw’a, Na ũĩmĩ mwololo nũtũlaa ĩvĩndĩ.'),
('kam', 'PRO', 25, 16, 'Nĩwonete ũkĩ wa nzũkĩ? Ya ũla ũkwĩanĩe, Ndũkese kusũwa nĩw’o, noyũtavĩka.'),
('kam', 'PRO', 25, 17, 'Kũũ kwaku kũikethĩwe nyũmbanĩ ya mũtũi waku kaingĩ, Ndakese kũnow’a nue, na akĩkũmena.'),
('kam', 'PRO', 25, 18, 'Mũndũ ũla ũmũkũsĩĩa mũtũi wake ũvũngũ Nĩ kĩiva kya mũtĩ, na ũvyũ, na mũsyĩ mũĩ.'),
('kam', 'PRO', 25, 19, 'Uĩkĩĩi mũndũnĩ ũte kĩthito ĩvinda ya thĩna Nĩ ta ĩeo ĩtũlĩku, na kũũ kũkitũku.'),
('kam', 'PRO', 25, 20, 'O tondũ mũndũ ũla wumasya ngũa ĩvinda ya mbevo, na ta siki ĩũlũ wa ĩtai, Now’o ũilyĩ ũla winĩaa ngoo ngito mbathi.'),
('kam', 'PRO', 25, 21, 'Ethĩwa mũmaitha waku e na nzaa, mũnenge lĩu wa kũya; Na ethĩwa e na waũni, mũnenge manzĩ ma kũnyw’a:'),
('kam', 'PRO', 25, 22, 'Nũndũ ũkamũmbĩĩa makaa ma mwaki mũtwenĩ wake, Na Yeova akakũĩva.'),
('kam', 'PRO', 25, 23, 'Kĩseve kyumĩte ngalĩ ya ĩũlũ nĩkĩetae mbua; Now’o ũĩmĩ wĩ nzuku ũetae ũthyũ mũthatu.'),
('kam', 'PRO', 25, 24, 'Nĩ kavaa kũtũa kĩkotonĩ kya nyũmba ĩũlũ, Kwĩ kũtũa na mũndũ mũka wĩ ĩteta nyũmbanĩ nthanthau.'),
('kam', 'PRO', 25, 25, 'Ta manzĩ mathithu kwa mũndũ wĩ waũni, Now’o ũilyĩ ũvoo mũseo wumĩte nthĩ yĩ kũasa.'),
('kam', 'PRO', 25, 26, 'Ta nthongo nthokoan’ye, na mbuluti mbukye, Now’o ũilyĩ mũndũ mũlũngalu ũla ũkusĩkaa nĩ ala athũku.'),
('kam', 'PRO', 25, 27, 'Ti ũseo kũya ũkĩ wa nzũkĩ mwingĩ; No ta ũu andũ kũmantha ndaĩa yoo ene nĩ ũthũku.'),
('kam', 'PRO', 25, 28, 'Ũla ũtasiĩĩaa veva wake Nĩ ta ndũa ĩla ĩomboetwe na ĩte na maũvai.'),
('kam', 'PRO', 26, 1, 'Ta ĩa ĩvinda ya syũa, na ta mbua ngethanĩ, O ta ũu ndaĩa ti mbaĩlu kwa ndia.'),
('kam', 'PRO', 26, 2, 'Ta mũthoonzwe kwanganganĩ kwaw’o, ta nthũngũlũlũ kũũlũkanĩ kwayo, Now’o kĩumo kĩte kĩtumi kĩtavũĩlaa.'),
('kam', 'PRO', 26, 3, 'Kĩvoko kwondũ wa mbalasi, mũkwa kwondũ wa mũtwe wa ĩng’oi, Na ndata kwondũ wa mũongo wa ndia.'),
('kam', 'PRO', 26, 4, 'Ndũkasũngĩe ndia kwĩanana na ũtumanu wayo, Ndũkese kwĩthĩwa tayo.'),
('kam', 'PRO', 26, 5, 'Sũngĩa ndia kwĩanana na ũtumanu wayo, Ndĩkese kwĩyona ta mbũĩ.'),
('kam', 'PRO', 26, 6, 'Ũla ũtũmaa ũvoo na kw’oko kwa ndia Nũtilaa maũũ make mwene, na kũnyw’a wasyo.'),
('kam', 'PRO', 26, 7, 'Maũũ ma ala mathuaa nĩmaseesangaa; Now’o ĩilyĩ ngelekan’yo kanyw’anĩ wa ndia.'),
('kam', 'PRO', 26, 8, 'Ta mũndũ ũla woveeaa ĩvia kĩkũthanĩ, Now’o ũilyĩ ũla ũnengae ndia ndaĩa.'),
('kam', 'PRO', 26, 9, 'Ta mwĩw’a ũla ũtonyaa kw’oko kwa mũthengi, Now’o kũilyĩ ngelekan’yo kanyw’anĩ wa ndia.'),
('kam', 'PRO', 26, 10, 'Ta mũndũ wa ũta ũla wũkitaa onthe, Now’o ũilyĩ ũla ũandĩkaa ndia na ũla ũandĩkaa avĩti.'),
('kam', 'PRO', 26, 11, 'Ta ngitĩ ĩla ĩalũkĩlaa matavĩka mayo, Now’o ĩilyĩ ndia ĩla yĩkaa ĩngĩ ũtumanu wayo.'),
('kam', 'PRO', 26, 12, 'Nũkwona mũndũ ũla wĩyonaa mwene ta mũĩ? Kavaa kwĩkwatya ndia kwĩ ũsu.'),
('kam', 'PRO', 26, 13, 'Ũla mũtulu easya, Ve mũnyambũ nzĩanĩ; Mũnyambũ wĩ nzĩanĩ nene.'),
('kam', 'PRO', 26, 14, 'O tondũ mũomo wĩalyũlĩlaa ikwatinĩ syaw’o, Now’o ũla mũtulu wĩkaa ũkomonĩ wake.'),
('kam', 'PRO', 26, 15, 'Ũla mũtulu nũindaa kw’oko kwake ĩsaaninĩ; Nĩ mĩnoo kwake kũkũete ĩngĩ kanyw’anĩ wake.'),
('kam', 'PRO', 26, 16, 'Ũla mũtulu nĩwĩyonaa ta mũĩ Kwĩ andũ mũonza ala matonya kwonan’ya kĩtumi.'),
('kam', 'PRO', 26, 17, 'Ũla ũvĩtaa, na kwĩnyamasya na ĩteta yĩte yake, Ailyĩ ũla ũkwataa ngitĩ matũ.'),
('kam', 'PRO', 26, 18, 'Ta mũndũ wa ndũũka ũla wĩkasya isinga, Na mĩsyĩ, na kĩkw’ũ,'),
('kam', 'PRO', 26, 19, 'Now’o mũndũ ũilyĩ ũla ũkengaa mũtũĩ wake, Na kwasya, Ndiũthaũka?'),
('kam', 'PRO', 26, 20, 'Nũndũ kũte ngũ mwaki nũvoaa; Na vala vate ũla ũneenaa na kĩwe, ngananĩo nĩthelaa.'),
('kam', 'PRO', 26, 21, 'O tondũ makaa mailyĩ vala ve makaa makanu, na ngũ vala ve mwaki, Now’o ũilyĩ mũndũ wa ngananĩo ũndũ wa kwakan’ya ĩteta.'),
('kam', 'PRO', 26, 22, 'Ndeto sya ũla ũneenaa na kĩwe nĩ ta tũlungu tũseo twa lĩu, Na nĩtũlikaa nthĩnĩ ki.'),
('kam', 'PRO', 26, 23, 'Ilomo mbyũvu na ngoo nthũku Iilyĩ ta mũio wa yũmba ũvakĩtwe makwaũ ma vetha.'),
('kam', 'PRO', 26, 24, 'Ũla ũmenanaa evithanasya na ilomo syake; Ĩndĩ nĩwiaa ũkengani nthĩnĩ wake:'),
('kam', 'PRO', 26, 25, 'Yĩla ũnũũneena nesa, ndũkamwĩtĩkĩle; Nũndũ ve mothatyo mũonza ngoonĩ yake:'),
('kam', 'PRO', 26, 26, 'O na ethĩwa kĩmena kyake nĩkĩkwĩvw’ĩka ũĩ wa ũkengani, Ũthũku wake ũkoonanw’a ũtheinĩ mbee wa ũmbano.'),
('kam', 'PRO', 26, 27, 'O ũla wĩnzaa ĩima akavalũka nthĩnĩ wayo; Na ũla ũvingilitasya ĩvia, yĩkasyoka ĩũlũ wake.'),
('kam', 'PRO', 26, 28, 'Ũĩmĩ ũla ũneenaa ũvũngũ nũmenaa ala wũkitĩte; Na kanyw’a wa kwendeesya na ndeto sya ũkathĩĩo nũomboaa.'),
('kam', 'PRO', 27, 1, 'Ndũkekathĩĩe ũndũ wa ũnĩ; Nũndũ ndwĩsĩ ũndũ mũthenya ũtonya kumĩlya.'),
('kam', 'PRO', 27, 2, 'Mũndũ ũngĩ nakũtaĩe, na ti kanyw’a waku mwene; Mũeni, na ti ilomo syaku mwene.'),
('kam', 'PRO', 27, 3, 'Ĩvia nĩ ĩito, na kĩthangathĩ nĩ kĩito; Ĩndĩ ũthatu wa ndia nĩ mũito kwĩ isu syelĩ.'),
('kam', 'PRO', 27, 4, 'Ũthilĩku nĩ mwai, na ũthatu nĩ mũkĩlu vyũ; Ĩndĩ nũũ ũtonya kũũngama mbee wa kĩwĩu?'),
('kam', 'PRO', 27, 5, 'Kavaa ũkan’yo wĩ ũtheinĩ Kwĩ wendo ũvithĩtwe.'),
('kam', 'PRO', 27, 6, 'Mawũkite ma mũnyanya nĩ ma kĩthito; Ĩndĩ momumunyo ma mũmaitha nĩ maingĩ.'),
('kam', 'PRO', 27, 7, 'Mũndũ ũvũnĩte nũmenaa ĩwa; Ĩndĩ kwa mũndũ wĩ na nzaa kĩla kĩndũ kĩ ũũ kĩ mũyo.'),
('kam', 'PRO', 27, 8, 'Ta nyũnyi ĩla yangangaa ĩkĩtia ndala yayo, Now’o mũndũ ũilyĩ ũla wangangaa kuma vandũ vake.'),
('kam', 'PRO', 27, 9, 'Mauta na syĩndũ ila inyungaa nesa matanĩthasya ngoo, No ta ũu mũyo wa mũnyanyae wa mũndũ ũla wumaa ũtaonĩ wa ngoo.'),
('kam', 'PRO', 27, 10, 'Mũnyanyau waku mwene, na mũnyanyae wa au, ndũkamatie; Na ndũkaende nyũmbanĩ ya mwana‐amwenyu mũthenya wa wanangĩko waku mũnene: Kavaa mũtũi ũla wĩ vakuvĩ kwĩ mwana‐a‐inyia ũla wĩ kũasa.'),
('kam', 'PRO', 27, 11, 'Mwana wakwa, ĩthĩwa mũĩ, noitanĩthya ngoo yakwa, Nĩ kana nĩmũsũngĩe ũla ũmbũthasya.'),
('kam', 'PRO', 27, 12, 'Mũndũ wĩ kĩlĩko nĩwonaa ũthũku na kwĩvitha; Ĩndĩ ala mate ũmanyi nĩmaendeeaa na kũthĩna.'),
('kam', 'PRO', 27, 13, 'Osa ngũa yake ũla mũĩkĩĩthya kwondũ wa mũeni; Noimwĩkalya ethĩwe ngwatĩlĩlyo ũla mũĩkĩĩthya kwondũ wa mũndũ mũka wa nthĩ ĩngĩ.'),
('kam', 'PRO', 27, 14, 'Ũla ũathimaa mũnyanyae wake na wasya mũnene, akyũkĩla kĩoko tene, Ũndũ ũsu ũkatalwa kwake nĩ kĩumo.'),
('kam', 'PRO', 27, 15, 'Kũvolotanga ĩvinda yonthe mũthenya wa mbua nyingĩ Na mũndũ mũka ũla ũtetanasya nĩ ũndũ ũmwe:'),
('kam', 'PRO', 27, 16, 'Ũla ũkenda kũmũsiĩĩa asiĩĩaa kĩseve; Na kw’oko kwake kwa aũme nĩkwakwata mauta.'),
('kam', 'PRO', 27, 17, 'Kĩaa nĩkĩnoaa kĩaa; O ta ũu mũndũ nũnoaa ũthyũ wa mũnyanyae.'),
('kam', 'PRO', 27, 18, 'O ũla ũsũvĩaa mũkũyũ akaya ũsyao waw’o; Na ũla ũtaĩaa vwana wake akataĩwa.'),
('kam', 'PRO', 27, 19, 'O tondũ kũilyĩ manzĩnĩ ũthyũ nĩwelekelaa ũthyũ, Now’o ngoo ya mũndũ kwa mũndũ.'),
('kam', 'PRO', 27, 20, 'Seoli na Avatoni kũtikolaa nongi; Na metho ma mũndũ matikolaa nongi.'),
('kam', 'PRO', 27, 21, 'Mbisũ ya ũthesya nĩ kwondũ wa vetha, na iko ĩnene kwondũ wa thaavu; Na mũndũ nũtatawa nĩ kũtaĩwa kwake.'),
('kam', 'PRO', 27, 22, 'O na ethĩwa ũkakimĩa ndia ndĩĩnĩ na mũthi vamwe na nganũ mbũe, Ũtumanu wayo ndũkauma nthĩnĩ wayo.'),
('kam', 'PRO', 27, 23, 'Ĩthĩwa na kĩthito ũndũ wa kũmanya ũndũ ndĩthya syaku sya mbũi na malondu iilyĩ, Noisisya nesa ũndũ wa ndĩthya syaku sya ng’ombe:'),
('kam', 'PRO', 27, 24, 'Nũndũ ũthwii ti wa tene na tene; Na ngovia ya ũsumbĩ nĩyĩkalaa mosyaanĩonĩ onthe?'),
('kam', 'PRO', 27, 25, 'Nyeki nyũmũ nikuĩtwe, na nyeki nziũ nithandĩkangĩte, Na nyũnyi sya iĩmanĩ nĩsyũmbanĩtw’e nthĩnĩ.'),
('kam', 'PRO', 27, 26, 'Tũtena twa malondu nĩ kwondũ wa ngũa syaku, Na mbũi nĩ sya kũthooa mũũnda;'),
('kam', 'PRO', 27, 27, 'Na kũkeethĩwa ĩia ya mbũi yĩanĩe lĩu waku, na lĩu wa andũ ma nyũmba yaku, Na lĩu wa athũkũmi maku eĩtu.'),
('kam', 'PRO', 28, 1, 'Ala athũku nĩmakĩaa yĩla vate mũndũ ũmaatĩĩe; Ĩndĩ ala alũngalu nĩ ngũmbaũ ta mũnyambũ.'),
('kam', 'PRO', 28, 2, 'Kwondũ wa ĩvĩtyo ya nthĩ anene me mbee ũsumbĩnĩ nĩ aingĩ; Ĩndĩ kwondũ wa andũ me ũmanyi na ũĩ nĩendeeaa kwĩkala.'),
('kam', 'PRO', 28, 3, 'Mũndũ mũthĩni ũla ũthĩnasya ngya Nĩ ta mbua ĩtwaĩthasya ĩla ĩtatiaa lĩu o na wĩva.'),
('kam', 'PRO', 28, 4, 'Ala matiaa mĩao mataĩaa ala athũku; Ĩndĩ ala makwataa mĩao makananĩaa nao.'),
('kam', 'PRO', 28, 5, 'Andũ athũku matimanyaa ũsili wa katĩ; Ĩndĩ ala mamanthaa Yeova mamanyaa maũndũ onthe.'),
('kam', 'PRO', 28, 6, 'Kavaa ngya ĩla ĩendaa wĩanĩunĩ wayo, Kwĩ ũla wĩ ngũlũ mĩendelenĩ yake, o na ethĩwa nĩ mũthwii.'),
('kam', 'PRO', 28, 7, 'O ũla ũkwataa mĩao nĩ mwana mũĩ; Ĩndĩ ũla ũtindanasya na ayi nũsonokasya ĩthe.'),
('kam', 'PRO', 28, 8, 'Ũla wongelaa ũthwii wake kwondũ wa kũkovethya atũngĩwe ũtandĩthyo na wongeleko, Ombanasya kwondũ wa ũla wĩw’ĩaa ngya tei.'),
('kam', 'PRO', 28, 9, 'Ula ũthyũũaa kũtũ kwake ndakew’e mĩao, O na mboya yake nĩ ũthatyo.'),
('kam', 'PRO', 28, 10, 'Ũla ũtumaa ũla mũlũngalu atũũa nzĩanĩ nthũku, Akavalũka e we ĩimanĩ yake mwene; Ĩndĩ ala eanĩu makatiĩwa ũseo.'),
('kam', 'PRO', 28, 11, 'Mũndũ mũthwii nĩwĩyonaa mwene ta mũĩ; Ĩndĩ ngya ĩla yĩ na ũmanyi nĩmũthianaa.'),
('kam', 'PRO', 28, 12, 'Yĩla mũlũngalu wakĩlya vinya, ve ndaĩa nene; Ĩndĩ yĩla ũla mũthũku wokĩla, andũ nĩmevithaa.'),
('kam', 'PRO', 28, 13, 'Ũla ũvw’ĩkaa mavĩtyo make ndakaathimĩka; Ĩndĩ ũla ũmaumbũlaa na kũmatia akeew’ĩwa tei.'),
('kam', 'PRO', 28, 14, 'Mũndũ nĩ mũtanu ũla ũkĩaa mavinda onthe; Ĩndĩ ũla wũmasya ngoo yake akavalũka ũthũkunĩ.'),
('kam', 'PRO', 28, 15, 'Ta mũnyambũ ũkĩluma, na nduva ĩkyanganga, Now’o ũilyĩ mũsumbĩki mũthũku ĩũlũ wa andũ ngya.'),
('kam', 'PRO', 28, 16, 'Mũnene wĩ mbee ũsumbĩnĩ ũla ũte ũmanyi nĩ mũthĩn’ya mũnene; Ĩndĩ ũla ũmenaa ĩtomo akongeleela mĩthenya yake.'),
('kam', 'PRO', 28, 17, 'Mũndũ ũla ũitavĩwe nĩ nthakame ya mũndũ o na wĩva Akakĩĩa yĩla ĩimanĩ; mũndũ o na wĩva ndakaamũsiĩĩe.'),
('kam', 'PRO', 28, 18, 'O ũla ũendaa na mĩendele myaĩlu akavonokw’a; Ĩndĩ ũla wĩ na ngũlũ mĩendelenĩ yake akavalũka mĩtũkĩ.'),
('kam', 'PRO', 28, 19, 'Ũla ũĩmaa nthĩ yake akeethĩwa na lĩu mwingĩ; Ĩndĩ ũla ũatĩĩa andũ mate kĩĩi akeethĩwa na ũkya mwĩanĩu.'),
('kam', 'PRO', 28, 20, 'Mũndũ wĩ kĩthito akaingĩvĩwa nĩ moathimo; Ĩndĩ ũla wĩkalaataa ethĩwe na ũthwii ndakatĩa kũkũnwa.'),
('kam', 'PRO', 28, 21, 'Kwĩthĩwa na wendeesyo wa andũ ti ũseo; O na mũndũ kũvĩtya ũndũ wa kĩlungu kya kĩmũtũ.'),
('kam', 'PRO', 28, 22, 'Ũla wĩ na itho ĩthũku nĩwĩkalaataa kũatĩĩa ũthwii, Na ndesĩ kana kwaĩwa kũkamũkĩa.'),
('kam', 'PRO', 28, 23, 'Ũla ũkanasya mũndũ, ĩtina akoona ũseo mwĩngĩ Kwĩ ũla wendeeasya na ndeto sya ũkathĩĩo wa ũĩmĩ.'),
('kam', 'PRO', 28, 24, 'Ũla ũmũvutaa ĩthe wake kana nyinyia, na kwasya, Ti ĩvĩtyo, Ũsu nĩ mũtindan’ya wa mwanangi.'),
('kam', 'PRO', 28, 25, 'Ũla wĩ veva mũtoonu nĩwũkĩlasya ĩteta; Ĩndĩ ũla ũmũĩkĩĩaa Yeova akeethĩwa mũnou.'),
('kam', 'PRO', 28, 26, 'Ũla ũĩkĩĩaa ngoo yake mwene nĩ ndia; Ĩndĩ ũla ũendaa na ũĩ, akavonokw’a.'),
('kam', 'PRO', 28, 27, 'Ũla ũnengae ngya ndakaĩwa nĩ kĩndũ; Ĩndĩ ũla ũvithaa metho make akeethĩwa na iumo nyingĩ'),
('kam', 'PRO', 28, 28, 'Yĩla athũku mookĩla, andũ nĩmevithaa; Ĩndĩ yĩla maaa, alũngalu nĩmaingĩvaa.'),
('kam', 'PRO', 29, 1, 'Ũla aikanw’a kaingĩ ũmasya ngingo yake Akaanangwa na kĩthũlũmũko, vate mũiito.'),
('kam', 'PRO', 29, 2, 'Yĩla ala alũngalu maingĩva, andũ nĩmatanaa; Ĩndĩ yĩla mũndũ mũthũku wasumbĩka, andũ nĩmavevũũkaa.'),
('kam', 'PRO', 29, 3, 'Ũla wendaa ũĩ nũtanĩthasya ĩthe wake; Ĩndĩ ũla ũtindanasya na malwaya nĩwanangaa syĩndũ syake.'),
('kam', 'PRO', 29, 4, 'Mũsumbĩ nũlũlũmĩlasya nthĩ kwondũ wa ũsili wa katĩ; Ĩndĩ ũla wumĩthasya mĩthĩnzĩo na vinya nũmĩkulumanasya.'),
('kam', 'PRO', 29, 5, 'Mũndũ ũla wendeeasya mũtũi wake na ndeto sya ũkathĩĩo Alanĩlasya matambya make kĩtei.'),
('kam', 'PRO', 29, 6, 'Ĩvĩtyonĩ ya mũndũ mũthũku ve kĩtei; Ĩndĩ ũla mũlũngalu nĩwinaa na kũtana.'),
('kam', 'PRO', 29, 7, 'Ũla mũlũngalu nũsiasya ũvoo wa ngya; Ũla mũthũku nde na ũĩ omanye.'),
('kam', 'PRO', 29, 8, 'Akaakaan’ya makwatasya ndũa mwaki; Ĩndĩ andũ oĩ mathyũũaa ũthilĩku ũtee.'),
('kam', 'PRO', 29, 9, 'Ethĩwa mũndũ mũĩ e na ngananĩo na mũndũ mũtumanu, Ethĩwa nũthatĩte kana kũtheka, vatikethĩwa ũthũmũo.'),
('kam', 'PRO', 29, 10, 'Ala mang’aatũkĩtw’e nĩ nthakame mamenaa ũla mwĩanĩu; Na ũndũ wa alũngalu, nao nĩmasũvĩaa thayũ wake.'),
('kam', 'PRO', 29, 11, 'Ndia nĩneenaa ũthatu wayo w’onthe; Ĩndĩ mũndũ mũĩ nĩwũsiĩĩaa na kũkilĩthya.'),
('kam', 'PRO', 29, 12, 'Ethĩwa mũsumbĩki nĩwĩthukĩĩasya ũvũngũ, Athũkũmi make onthe nĩ athũku.'),
('kam', 'PRO', 29, 13, 'Mũndũ ngya na mũthĩn’ya makomanaa vamwe; Yeova nĩwĩkĩaa kyeni metho ma asu elĩ.'),
('kam', 'PRO', 29, 14, 'Mũsumbĩ ũla ũsilĩlaa ngya na kĩthito, Kĩvĩla kyake kya ũsumbĩ kĩkalũlũmĩlw’a tene na tene.'),
('kam', 'PRO', 29, 15, 'Ndata na ũkan’yo ninenganae ũĩ: Ĩndĩ kana kala kalekaw’a kathi ũndũ kekwenda kasonokasya inyia wako.'),
('kam', 'PRO', 29, 16, 'Yĩla athũku maingĩva, kũvĩtya nakw’o nĩkwingĩvaa; Ĩndĩ alũngalu makoona ũvalũko woo.'),
('kam', 'PRO', 29, 17, 'Mwon’ya mwana waku mavĩtyo, na akakũthũmũsya; Ĩĩ, akatanĩthya ngoo yaku.'),
('kam', 'PRO', 29, 18, 'Vala vate woni, andũ nĩmavetaa wĩsiĩĩo; Ĩndĩ ũla ũkwataa mĩao, ũsu nĩ mũtanu.'),
('kam', 'PRO', 29, 19, 'Mũthũkũmi ndonaw’a mavĩtyo na ndeto; O na kau mũmanyaa, ndasũngĩaa.'),
('kam', 'PRO', 29, 20, 'Nũkwona mũndũ wĩ mĩtũkĩ ya kũneena ndetonĩ syake? Kavaa kwĩkwatya ndia kwĩ ũsu.'),
('kam', 'PRO', 29, 21, 'Ũla ũeaa mũthũkũmi wake akĩmũsũvĩa kuma e kana Mũminũkĩlyo akeethĩwa kwake ta mwana.'),
('kam', 'PRO', 29, 22, 'Mũndũ mũthatu nĩwũkĩlasya ĩteta, Na mũndũ mũthilĩku nĩwusũĩte mavĩtyo.'),
('kam', 'PRO', 29, 23, 'Ngathĩĩo ya mũndũ ĩkamũtheesya; Ĩndĩ ũla wĩ na veva wa wĩnyivyo akoosa ndaĩa.'),
('kam', 'PRO', 29, 24, 'O ũla wĩ ngwatanĩo na kĩng’ei amenaa thayũ wake mwene; Nĩwĩw’aa wĩvĩto na ndaneenaa.'),
('kam', 'PRO', 29, 25, 'Kũkĩa mũndũ nĩkũetae kĩtei; Ĩndĩ ũla ũmũĩkĩĩaa Yeova akekalaa ate na mũisyo.'),
('kam', 'PRO', 29, 26, 'Aingĩ nĩmamanthaa ũseo kwa mũsumbĩki; Ĩndĩ ũsilĩlo wa mũndũ nĩwumaa vala ve Yeova.'),
('kam', 'PRO', 29, 27, 'Mũndũ ũte na ũlũngalu nĩ ũthatyo kwa ũla mũlũngalu; Na ũla mũlũngalu ĩ nzĩanĩ nĩ ũthatyo kwa ala athũku.'),
('kam', 'PRO', 30, 1, 'Ndeto sya Akuli mwana wa Yake; ũtao. Ũ mũndũ amwĩa Ithieli, Ithieli na Ukali:'),
('kam', 'PRO', 30, 2, 'Vate ndĩi nĩilyĩ ta nyamũ kũvĩtũka mũndũ o na wĩva, Na ndi na ũmanyi wa mũndũ;'),
('kam', 'PRO', 30, 3, 'Na ndimanyĩte ũĩ, O na ndi na ũmanyi wa Ũla Mũtheu.'),
('kam', 'PRO', 30, 4, 'Nũũ ũla wambatie ĩtunĩ, na akatheea? Nũũ ũla wombanisye kĩseve ngundinĩ syake? Nũũ ũla woveeie manzĩ ngũanĩ yake? Nũũ ũla walũlũmĩlye itulu syonthe sya nthĩ? Syĩtwa yake eetawa ata, na syĩtwa ya mwana wake eetawa ata, ethĩwa nĩwĩsĩ?'),
('kam', 'PRO', 30, 5, 'Kĩla ndeto ya Ngai nĩ ndate: Nake nĩ ngao ya ala mevithaa nthĩnĩ wake.'),
('kam', 'PRO', 30, 6, 'Ndũkongele ndeto syake, Ndakese ũkũkan’ya, na ũkyoneka wĩ mũneeni wa ũvũngũ.'),
('kam', 'PRO', 30, 7, 'Maũndũ elĩ nĩngwĩtĩtye; Ndũkamambate ndanamba ũkw’a:'),
('kam', 'PRO', 30, 8, 'Veta kũasa nakwa maũndũ ma mana na movũngũ; Ndũkanenge ũkya kana ũthwii; Ngathĩsya lĩu ũla ũmbĩanĩe:'),
('kam', 'PRO', 30, 9, 'Ndikese kũvũna vyũ, na ũkũkaĩa, na kwasya, Yeova nũũ? Kana ndikese kwĩthĩwa ngya, na ndyũya, Na kũweta syĩtwa ya Ngai wakwa mana.'),
('kam', 'PRO', 30, 10, 'Ndũkamũsuke mũthũkũmi kwa vwana wake, Ndakese ũkũuma, naku ũituwa mũvĩtan’ya.'),
('kam', 'PRO', 30, 11, 'Ve nzyawa ĩla ĩumaa ĩthe wayo, Na ndĩathimaa inyia wayo.'),
('kam', 'PRO', 30, 12, 'Ve nzyawa ĩla ntheu methonĩ mayo, Na ĩndĩ ndĩthambĩte ũvuku wayo.'),
('kam', 'PRO', 30, 13, 'Ve nzyawa a! Metho mayo me na mĩtũlyo! Na ilomo sya metho moo nĩsyũkĩlĩtw’e.'),
('kam', 'PRO', 30, 14, 'Ve nzyawa maeo mayo nĩ ta mbyũ, na mbosela syayo ta tũvyũ, Ya kwananga ngya kuma nthĩ, na athĩni kuma katĩ wa andũ.'),
('kam', 'PRO', 30, 15, 'Nthambaa yĩ na eĩtu elĩ, metawa, Nenga, nenga. Ve syĩndũ itatũ ila iteanĩawa nongi, Ĩĩ, inya ila itaneenaa, Nũu:'),
('kam', 'PRO', 30, 16, 'Seoli; na ĩvu yĩtasyaaa; Nthĩ ĩtakolaa kĩw’ũ; Na mwaki ũla ũtaneenaa, Nũu.'),
('kam', 'PRO', 30, 17, 'Itho yĩla yĩmũthekeea ĩthe, Na kũvũthya kwĩw’a inyia, Ngũngũũ sya mwandani ikayumya, Na tũswii twa ndiũ tũkayĩya.'),
('kam', 'PRO', 30, 18, 'Kwĩ maũndũ atatũ me ũseng’yo kũmbĩtũka, Ĩĩ, ana ala ndamesĩ:'),
('kam', 'PRO', 30, 19, 'Nzĩa ya ndiũ yayayanĩ; Nzĩa ya nzoka ĩũlũ wa ĩvia; Nzĩa ya ngalawa katĩ wa ũkanga; Na nzĩa ya mũndũ mũũme na mwĩĩtu.'),
('kam', 'PRO', 30, 20, 'Now’o kũilyĩ nzĩa ya mũndũ mũka kĩlaalai; Nũĩsaa na kũvangũla kanyw’a wake, Na kwasya, Ndyĩkĩte ũndũ ũthũku.'),
('kam', 'PRO', 30, 21, 'Nũndũ wa maũndũ atatũ nthĩ nĩtetemaa, Na nũndũ wa ana, ala ĩtatonya kũmĩĩsya:'),
('kam', 'PRO', 30, 22, 'Nũndũ wa mũthũkũmi yĩla ũtw’ĩka mũsumbĩ; Na ndia yĩla yavũna lĩu;'),
('kam', 'PRO', 30, 23, 'Nũndũ wa mũndũ mũka kũmenwa e mũtwae; Na mwĩĩtu mũthũkũmi e mũtiĩwa wa vivi wake.'),
('kam', 'PRO', 30, 24, 'Kwĩ syĩndũ inya ila nini ĩũlũ wa nthĩ, Ĩndĩ syĩ na ũĩ mwingĩ:'),
('kam', 'PRO', 30, 25, 'Nditikũ nĩ andũ mate vinya, Ĩndĩ nĩsyũmbanasya lĩu wasyo ĩvinda ya syũa;'),
('kam', 'PRO', 30, 26, 'Inyowe nĩ andũ mate vinya, Ĩndĩ niseũvasya nyũmba syasyo mavianĩ;'),
('kam', 'PRO', 30, 27, 'Ngie iti na mũsumbĩ, Ĩndĩ nĩsyumalaa syonthe syĩ nguthu;'),
('kam', 'PRO', 30, 28, 'Ĩtelembũ nĩyĩkwataa na moko mayo, Ĩndĩ yĩ nyũmbanĩ nene mbanakavye ya asumbĩ.'),
('kam', 'PRO', 30, 29, 'Kwĩ syĩndũ itatũ ila syaĩlaa mũtambĩlyenĩ wasyo, Ĩĩ, inya ila syaĩlaa ikĩenda:'),
('kam', 'PRO', 30, 30, 'Mũnyambũ, ũla wĩ vinya mbee katĩ wa nyamũ, Na ndwĩthyũũaa kwondũ wa ĩmwe o na yĩva;'),
('kam', 'PRO', 30, 31, 'Ngitĩ yĩ ũsembi; o na nthenge; Na mũsumbĩ ũla ũtang’endeeka.'),
('kam', 'PRO', 30, 32, 'Ethĩwa nĩwĩkĩte ũtumanu ũkĩtũlya mwene, Kana ethĩwa nũsũanĩĩte ũthũku, Kunĩka kanyw’a waku na kw’oko kwaku.'),
('kam', 'PRO', 30, 33, 'Nũndũ kũthuka ĩia nĩkũetae mauta, Na kũmila ĩnyiũũ nĩkumasya nthakame; No ta ũu kũkuthũan’ya ũthilĩku nĩkũetae ĩteta.'),
('kam', 'PRO', 31, 1, 'Ndeto sya mũsumbĩ Lemueli; ũtao ũla inyia wake wamũtaie.'),
('kam', 'PRO', 31, 2, 'Nata, mwana wakwa? Na nata, we mwana wa ĩvu yakwa? Nata, we mwana wa mawĩvĩto makwa?'),
('kam', 'PRO', 31, 3, 'Ndũkanenge aka vinya waku, Kana mĩendele yaku kĩla kyanangaa asumbĩ.'),
('kam', 'PRO', 31, 4, 'Ti ũndũ wa asumbĩ, we Lemueli, ti ũndũ wa asumbĩ kũnyw’a mbinyu; Kana ũndũ wa anene me mbee ũsumbĩnĩ kũkũlya, Kĩla kĩtoonasya kĩĩva?'),
('kam', 'PRO', 31, 5, 'Matikese kũnyw’a na kũlwa nĩ mĩao, Na kwelelũkya ũsili wa katĩ ũla waĩle mũndũ o na wĩva ũla ũthĩnaw’a.'),
('kam', 'PRO', 31, 6, 'Mũnenge ũla ũkilĩlye kwaa kĩla kĩtoonasya, Na mbinyu ala me ũũ ngoonĩ:'),
('kam', 'PRO', 31, 7, 'Nanyw’e, na kũlwa nĩ ũkya wake, Na kũlea kũlilikana thĩna wake ĩngĩ.'),
('kam', 'PRO', 31, 8, 'Athamya kanyw’a waku kwondũ wa ala matatonya kũneena, Kwondũ wa onthe ala matiĩtwe me oka.'),
('kam', 'PRO', 31, 9, 'Athamya kanyw’a waku, tusaa katĩ, Noitw’ĩĩaa ngya na athĩni ũsili wa katĩ.'),
('kam', 'PRO', 31, 10, 'Nũũ ũtonya kũmwona mũndũ mũka mwaĩlu? Nũndũ e vata mũno kwĩ tũvila twa maliani.'),
('kam', 'PRO', 31, 11, 'Ngoo ya mũũme wake nĩmũĩkĩĩaa, Na ndakanyivĩwa nĩ syĩndũ.'),
('kam', 'PRO', 31, 12, 'Nake nũmwĩkaa ũseo na ti ũthũku Mĩthenya yonthe ya thayũ wake.'),
('kam', 'PRO', 31, 13, 'Nũmanthaa w’ĩa wa malondu na katane, Na nũtethasya wĩa na moko make na kwenda kwa ngoo.'),
('kam', 'PRO', 31, 14, 'Ailyĩ ngalawa sya athoosya; Aetae lĩu wake kuma kũasa.'),
('kam', 'PRO', 31, 15, 'Nake nĩwũkĩlaa kwĩ o ũtukũ, Na kũnenga andũ ma nyũmba yake lĩu, Na athũkũmi make eĩtu wĩa woo.'),
('kam', 'PRO', 31, 16, 'Nũsũanĩaa ũndũ wa mũũnda, na akothooa; Nũvandaa mũũnda wa mĩsavivũ na ũtandĩthyo wa moko make.'),
('kam', 'PRO', 31, 17, 'Nũvotoaa kĩnyunyu kyake vinya, Na kwĩkĩa moko make vinya.'),
('kam', 'PRO', 31, 18, 'Nũmanyaa kana syĩndũ syake sya ũthoosya syĩ ũuno; Taa wake ndũvoaa ũtukũ.'),
('kam', 'PRO', 31, 19, 'Nũkwataa na moko make kamũtĩ ka ũkwata maw’ĩa, Na syaa syake nikwataa kĩlingi kya kũlingĩlĩĩla ũlii.'),
('kam', 'PRO', 31, 20, 'Nũtambũũkasya moko make ũndũ wa ngya; Ĩĩ, nũtambũũkasya moko make ũndũ wa athĩni.'),
('kam', 'PRO', 31, 21, 'Ndakĩaa mbevo ya ĩa kwondũ wa andũ ma nyũmba yake; Nũndũ andũ onthe ma nyũmba yake nĩmavw’ĩkĩtwe ngũa ndune mũno.'),
('kam', 'PRO', 31, 22, 'Nĩwĩseũvĩasya mĩto mĩseo mũno; Ngũa yake nĩ katane nzeo na ĩla ndune mũno.'),
('kam', 'PRO', 31, 23, 'Mũũme wake nĩwĩsĩkĩwe mbingĩlonĩ, Yĩla ũnũĩkala katĩ wa atumĩa ma ĩ nthĩ.'),
('kam', 'PRO', 31, 24, 'Nũtumaa ngũa sya katane na kwithoosya, Na kũmũtwaĩa mũthoosya mĩsivi.'),
('kam', 'PRO', 31, 25, 'Vinya na ũnene nĩ ngũa syake; Nake nũthekeea ĩvinda yũkĩte.'),
('kam', 'PRO', 31, 26, 'Nĩwathamasya kanyw’a wake na ũĩ; Na mwĩao wa ũseo wĩ ũĩmĩnĩ wake.'),
('kam', 'PRO', 31, 27, 'Nũsiasya nesa mĩendele ya andũ ma nyũmba yake, Na ndaĩsaa lĩu wa ũtulu.'),
('kam', 'PRO', 31, 28, 'Syana syake nĩsyũkĩlaa, na kũmwĩta mũathime; O na mũũme wake, na amũtaĩa, akyasya:'),
('kam', 'PRO', 31, 29, 'Eĩtu aingĩ nĩmekĩte ũla waĩle, Ĩndĩ we wĩ mbee wa onthe.'),
('kam', 'PRO', 31, 30, 'Wũmbe nĩ ũkengani, na wanake nĩ mana; Ĩndĩ mũndũ mũka ũla ũkĩaa Yeova, akataĩwa.'),
('kam', 'PRO', 31, 31, 'Ũmũnenge wa ũsyao wa moko make; Na mawĩa make nĩmamũtaĩĩe mbingĩlonĩ.'),
('kam', 'ECC', 1, 1, 'Ndeto sya mũtavan’ya, mwana wa Ndaivti, mũsumbĩ ku Yelusaleme.'),
('kam', 'ECC', 1, 2, 'No mana, mana vyũ, easya ũu Mũtavan’ya; no mana, mana vyũ, maundũ onthe nĩ mana.'),
('kam', 'ECC', 1, 3, 'Mũndũ e na ũunĩko mwaũ ũndũ wa wĩa wake w’onthe ũla wĩthĩnĩasya ĩtheo wa syũa?'),
('kam', 'ECC', 1, 4, 'Nzyawa ĩmwe nĩvĩtaa, na nzyawa ĩngĩ nĩyũkaa; ĩndĩ nthĩ nĩyĩkalaa tene na tene.'),
('kam', 'ECC', 1, 5, 'O na syũa nĩyumaa, na syũa nĩyĩthũaa, na kwĩkalaata yĩthi vandũ vayo vala yumaa.'),
('kam', 'ECC', 1, 6, 'Kĩseve nĩkĩendaa kwelekela ngalĩ ya ĩtheo, na kwĩthyũũa kwelekela ngalĩ ya ĩũlũ; nĩkĩthyũlũlũkaa mavinda onthe nzĩanĩ yakyo, na kĩseve nĩkĩsyokaa ĩngĩ ĩthyũlũlũnĩ syakyo.'),
('kam', 'ECC', 1, 7, 'Mbũsĩ syonthe niendaa ũkanganĩ, ĩndĩ ũkanga ndusũaa; vandũ o vala mbũsĩ iendaa, no vo iendaa ĩngĩ.'),
('kam', 'ECC', 1, 8, 'Maũndũ onthe nĩmausũĩtwe nĩ mĩnoo; mũndũ ndatonya kũneenekya; itho yĩtikolaa kwona, kana kũtũ kũkakola kwĩw’a.'),
('kam', 'ECC', 1, 9, 'Kĩla kyaĩ kw’o nokyo kĩkethĩwa; na ũndũ ũla weekiwe now’o ũla ũkekwa: na kũti ũndũ weũ ĩtheo wa syũa.'),
('kam', 'ECC', 1, 10, 'Ve kĩndũ kĩla kĩtonya kũwetwa ũndũ wakyo, Sisya, kĩĩ nĩ kyeũ? Kyaĩ o kw’o kuma tene mũno, mavinda ala maĩ kw’o tũtanethĩwa.'),
('kam', 'ECC', 1, 11, 'Kũti ũlilikano wa nzyawa sya mbee; o na kũtikethĩwa ũlilikano wa nzyawa sya ĩtina ila ikoka, katĩ wa ala makoka ĩtina.'),
('kam', 'ECC', 1, 12, 'Nyie Mũtavany’a naĩ mũsumbĩ ĩũlũ wa Isilaeli ku Yelusaleme.'),
('kam', 'ECC', 1, 13, 'Na neekĩa ngoonĩ yakwa kũmantha na kũthiana na nzĩa ya ũĩ ũvoo wa maũndũ onthe ala mekawa ĩtheo wa ĩtu: nĩ thĩna mũnene ũla Ngaĩ ũnengete ana ma andũ mathĩnaw’e nĩw’o.'),
('kam', 'ECC', 1, 14, 'Nĩnonete mawĩa onthe ala mekawa ĩtheo wa syũa; na, sisya, onthe nĩ mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 1, 15, 'Kĩla kĩthyoeku kĩtitonya kũlũngalw’a; na kĩla kĩte vo kĩtitonya kũtalwa.'),
('kam', 'ECC', 1, 16, 'Nĩnaneenanisye na ngoo yakwa, ngyasya, Sisya, nĩnĩyoseete ũĩ mũnene kũvĩtũka onthe ala maĩ mbee wakwa ku Yelusaleme; ĩĩ, ngoo yakwa nĩyonete ki ũĩ na ũmanyi.'),
('kam', 'ECC', 1, 17, 'Na neekĩa ngoonĩ yakwa nĩmanye ũĩ, na kũmanya ũũũki na ũtumanu: na noona o na ũu naw’o no ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 1, 18, 'Nũndũ nthĩnĩ wa ũĩ mwingĩ kwĩ woo mwingĩ; na ũla wingĩvasya ũmanyi nĩwingĩvĩĩasya woo.'),
('kam', 'ECC', 2, 1, 'Nĩnaneenie ngoonĩ yakwa, Ũka yu, ngakwĩkuũa na motanu; kwondũ wa ũu ĩw’ĩa mũyo motanunĩ: na, sĩsya, ũu naw’o waĩ wa mana.'),
('kam', 'ECC', 2, 2, 'Naisye ũndũ wa kũtheka, Nĩkũũũka; na ũndũ wa ũtanu, Wĩkaa ata?'),
('kam', 'ECC', 2, 3, 'Namanthie ngoonĩ yakwa ũndũ ndonya kũtanĩthya mwĩĩ wakwa na mbinyu, ngoo yakwa ĩkĩndongoesya na ũĩ, na ũndũ ndonya kũkwata ũtumanu, kũvika ndonye kwona ũseo ũla ana ma andũ maĩle kwĩka ĩtheo wa ĩtu mĩthenya yonthe ya thayũ woo.'),
('kam', 'ECC', 2, 4, 'Nĩneeseũvĩsye mawĩa manene, nĩneeyakĩe nyũmba mbingĩ; nĩneevandĩe mĩũnda ya mĩsavivũ;'),
('kam', 'ECC', 2, 5, 'nĩneeseũvĩsye mĩũnda na kũndũ kwanake vyũ, na navanda mĩti nthĩnĩ wa kw’o ya mĩthemba yonthe ya matunda;'),
('kam', 'ECC', 2, 6, 'nĩneeseũvĩsye ndia sya manzĩ, nĩnyithasye na manzĩ asu mũtitũ kũla kũvandĩtwe mĩtĩ mĩnini yĩane;'),
('kam', 'ECC', 2, 7, 'nĩnathooie athũkũmi aũme na eĩtu, na naĩ na athũkũmi ala masyaĩwe nyũmbanĩ yakwa; o na naĩ na ũthwii wa ndĩthya sya ng’ombe na sya mbũi na malondu, kwĩ onthe ala maĩ Yelusaleme mbee wakwa;'),
('kam', 'ECC', 2, 8, 'o na nĩneeyũmbanĩsye vetha na thaavu, na ũthwii wa asumbĩ na wa ilungu nene sya nthĩ; nĩneeyosee aini aũme na aini aka, na motanu ma ana ma andũ, na syĩndũ sya kũinga, nasyo syaĩ sya mĩthemba yonthe.'),
('kam', 'ECC', 2, 9, 'Kwondũ wa ũu naĩ mũnene, na naingĩvĩwe kũvĩtũka onthe ala maĩ Yelusaleme mbee wakwa: o na ũĩ wakwa nĩwekalaa nakwa.'),
('kam', 'ECC', 2, 10, 'Na o kĩla metho makwa mendaa ndyaamavata; ndyaaima ngoo yakwa ũtanu o na wĩva; nũndũ ngoo yakwa yatanaa nũndũ wa wĩa wakwa w’onthe; na ũu waĩ kĩanda kyakwa kwondũ wa wĩa wakwa w’onthe.'),
('kam', 'ECC', 2, 11, 'Na ĩndĩ nasisya wĩa w’onthe ũla moko makwa meekie, na wĩa ũla neethĩnĩsye kũtethya; na, sisya, w’onthe waĩ mana na ta kũsemban’ya na kĩseve, na kũtyaĩ ũunĩko ĩtheo wa syũa.'),
('kam', 'ECC', 2, 12, 'Na ĩndĩ neethyũũa nĩsisye, ũĩ, na ũũũki, na ũtumanu: nũndũ mũndũ ũla wĩũka ĩtina wa mũsumbĩ atonya kwĩka ata? No maũndũ asu ala mathelile kwĩkwa tene.'),
('kam', 'ECC', 2, 13, 'Na ĩndĩ noona kana ũĩ nũvĩtũkĩte motanu kũasa, o tondũ kyeni kĩvĩtũkĩte kĩvindu.'),
('kam', 'ECC', 2, 14, 'Metho ma mũndũ mũĩ me mũtwe kwake, na ndia nĩkinyaa kĩvindunĩ: ĩndĩ noona atĩ ũndũ ũmwe nĩwĩkĩkaa kwa onthe.'),
('kam', 'ECC', 2, 15, 'Nĩvo ĩndĩ naisye ngoonĩ yakwa, O tondũ kwĩkĩkaa kwa ndia, now’o kũkekĩka kwakwa; na ĩndĩ naĩ na ũĩ mũvĩtũku ata? Na ĩndĩ nasya ngoonĩ yakwa, o na ũu naw’o nĩ wa mana.'),
('kam', 'ECC', 2, 16, 'Nũndũ ũndũ wa mũndũ mũĩ, now’o kwa ndia, kũtĩ ũlilikano tene na tene; nũndũ mĩthenya ĩla yũkĩte onthe makethĩwa moolile tene. Na kaĩ mũndũ mũĩ nũkusaa o ta ndia!'),
('kam', 'ECC', 2, 17, 'Kwondũ wa ũu namena thayũ, nũndũ wĩa ũla ũtethaw’a ĩtheo wa syũa, waĩ thĩna kwakwa; nũndũ w’onthe nĩ wa mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 2, 18, 'Na namena wĩa wakwa w’onthe ũla neethĩnĩsye ĩtheo wa syũa, nũndũ no mũvaka nĩũtiĩe mũndũ ũla ũkethĩwa ĩtina wakwa.'),
('kam', 'ECC', 2, 19, 'Na ũla wĩsĩ nũũ ethĩwa akethĩwa mũndũ mũĩ kana ndia? Ĩndĩ nake akethĩwa ĩũlũ wa wĩa wakwa w’onthe ũla neethĩnĩsye, na ũla neeyonanĩthisye nĩ mũĩ nthĩnĩ waw’o ĩtheo wa syũa. Ũu naw’o nĩ wa mana.'),
('kam', 'ECC', 2, 20, 'Kwondũ wa ũu nĩneethyũũie nĩtume ngoo yakwa ĩyĩtũka ũndũ wa wĩa w’onthe ũla neethĩnĩsye ĩtheo wa syũa.'),
('kam', 'ECC', 2, 21, 'Nũndũ kwi mũndũ ũla ũtethasya wĩa wake na ũĩ, na ũmanyi, na ũtuĩka; ĩndĩ akootiĩa mũndũ ũla ũtaotethya wĩthĩwe kĩanda kyake. Ũu naw’o nĩ wa mana, na ũthũku mũnene.'),
('kam', 'ECC', 2, 22, 'Nũndũ mũndũ e na kyaũ kwondũ wa wĩa wake w’onthe, na kĩthing’ĩĩsyo kya ngoo yake, ũla weethĩnĩsye nthĩnĩ wakyo ĩtheo wa syũa?'),
('kam', 'ECC', 2, 23, 'Nũndũ mĩthenya yake yonthe no mawoo, na thĩna wake no woo; ĩĩ, o na ũtukũ ngoo yake ndĩthũmũaa. O na ũu naw’o nĩ wa mana.'),
('kam', 'ECC', 2, 24, 'Kũti ũndũ ũseo kwa mũndũ kũvĩtũka kũya na kũnyw’a, na kũtuma thayũ wake kũtanĩa ũseo wĩanĩ wake. Na ũu naw’o noona atĩwumĩte kw’okonĩ kwa Ngai.'),
('kam', 'ECC', 2, 25, 'Nũndũ nũũ ũtonya kũya, kana nũũ ũtonya kwĩthĩwa na ũtanu, kwĩ nyie?'),
('kam', 'ECC', 2, 26, 'Nũndũ mũndũ ũla ũmwendeeasya Ngai nũmũnengae ũĩ, na ũmanyi, na ũtanu; ĩndĩ nũnengae mũndũ mwathe thĩna, kũmban’ya na kwongeleela, nĩ kana amũngenge ũla ũmwendeeasya Ngai. Ũndũ ũu naw’o nĩ mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 3, 1, 'Kwondũ wa kĩla kĩndũ ve ĩvinda, na ĩvinda kwondũ wa kĩla ũndũ ĩtheo wa ĩtu:'),
('kam', 'ECC', 3, 2, 'ĩvinda ya kũsyawa, na ĩvinda ya kũkw’a; ĩvinda ya kũvanda, na ĩvinda ya kũkũa kĩla kĩvande;'),
('kam', 'ECC', 3, 3, 'ĩvinda ya kũaa, na ĩvinda ya kũvosya; ĩvinda ya kũomboa, na ĩvinda ya kwaka;'),
('kam', 'ECC', 3, 4, 'ĩvinda ya kũĩa, na ĩvinda ya kũtheka; ĩvinda ya kũmeta, na ĩvinda ya kũsunga;'),
('kam', 'ECC', 3, 5, 'ĩvinda ya kwĩkya mavia, na ĩvinda ya kũmban’ya mavia; ĩvinda ya kwĩvĩtĩĩsya, na ĩvinda ya kũlea kwĩvĩtĩĩsya;'),
('kam', 'ECC', 3, 6, 'ĩvinda ya kũmantha, na ĩvinda ya kwasya; ĩvinda ya kũsũvĩa, na ĩvinda ya kwĩkya ũtee;'),
('kam', 'ECC', 3, 7, 'ĩvinda ya kũtembũa, na ĩvinda ya kũtuma; ĩvinda ya kũvindya, na ĩvinda ya kũneena;'),
('kam', 'ECC', 3, 8, 'ĩvinda ya kwenda, na ĩvinda ya kũmena; ĩvinda ya kaũ, na ĩvinda ya mũuo.'),
('kam', 'ECC', 3, 9, 'Mũtethya wa wĩa e na ũunĩko mwaũ ũndũnĩ ũla ũtethasya?'),
('kam', 'ECC', 3, 10, 'Nĩnonete thĩna ũla Ngai ũnengete ana ma andũ mathĩnaw’e nĩw’o.'),
('kam', 'ECC', 3, 11, 'Nũseũvĩtye kĩla kĩndũ kĩthĩwe kĩseo mũno ĩvindanĩ yakyo: o na nĩwiĩte nthĩ yonthe ngoonĩ syoo, o na ũu w’onthe mũndũ ndatonya kũmanya wla ũla Ngaĩ ũtethetye kuma mwambĩlĩyonĩ o kũvika mũminũkĩlyo.'),
('kam', 'ECC', 3, 12, 'Nĩnĩsĩ vati ũndũ ũseo kwoo, kwĩ kũtana na kwĩka ũseo o yĩla me thayũ.'),
('kam', 'ECC', 3, 13, 'Na ĩngĩ nĩ mũthĩnzĩo wa Ngaĩ kana kĩla mũndũ aye na kũnyw’a, na kũtanĩa ũseo wĩanĩ wake w’onthe.'),
('kam', 'ECC', 3, 14, 'Nĩnĩsĩ atĩ o ũla Ngai wĩkaa, ũkekalaa tene na tene: vati ũndũ ũtonya wongeleelwa ũndũnĩ ũsu, kana ũndũ o na wĩva kũolwa; na Ngai nĩwĩkĩte ũu, nĩ kana andũ mamũkĩe.'),
('kam', 'ECC', 3, 15, 'Kĩla kĩ yu, kyaĩ o kw’o tene mũno; na kĩla kĩkeethĩwa kyaĩ o kw’o tene mũno: na Ngai nũmanthaa ĩngĩ kĩla kĩvĩtĩte.'),
('kam', 'ECC', 3, 16, 'Na ĩngĩ noona ĩtheo wa syũa, vandũnĩ va ũsili wa katĩ, atĩ ũthũku wĩ o vo, na vandũnĩ va ũlũngalu, atĩ ũthũku wĩ o vo.'),
('kam', 'ECC', 3, 17, 'Naisye ngoonĩ yakwa, Ngai akasilĩla alũngalu na athũku; nũndũ kwĩ ĩvinda kw’o kwondũ wa kĩla ũndũ na kĩla wĩa.'),
('kam', 'ECC', 3, 18, 'Naisye ngoonĩ yakwa, Nĩ ũndũ wa ana ma andũ, nĩ kana Ngai amatate, na nĩ kana mone atĩ mo ene no ta nyamũ.'),
('kam', 'ECC', 3, 19, 'Nũndũ ũndũ ũla ũkwataa ana ma andũ, nũkwataa nyamũ, kwĩkĩkaa o ũndũ ũmwe kwoo: o ũndũ ũmwe ũkusaa, now’o ĩla ĩngĩ ĩkusaa; ĩĩ, onthe me na mũvevo ũmwe; na mũndũ nde na ũnene kwĩ nyamũ: nũndũ onthe nĩ ma mana.'),
('kam', 'ECC', 3, 20, 'Onthe maendaa vandũ vamwe; onthe nĩ ma kĩtoo, na onthe masyokaa ĩngĩ kĩtoonĩ.'),
('kam', 'ECC', 3, 21, 'Nũũ ũla wĩsĩ veva wa mũndũ, ethĩwa wambataa ĩũlũ, na veva wa nyamũ, ethĩwa ũtheeaa nthĩ?'),
('kam', 'ECC', 3, 22, 'Kwondũ wa ũu noonie vati ũndũ ũseo mbee, kwĩ mũndũ kũtanĩa mawĩa make; nũndũ kyu nĩkyo kĩanda kyake: nũndũ nũũ ũla ũkamũete ĩngĩ one ũndũ ũkethĩwa ĩtina wake?'),
('kam', 'ECC', 4, 1, 'Na ĩndĩ nasyoka na noona mathĩna onthe ala mekawa ĩtheo wa syũa: na, sisya, methoi ma ala mathĩnaw’a, na matyaĩ na mũkiakisya; na ngalĩ ĩla ya athĩn’ya moo kwaĩ vinya; ĩndĩ matyaĩ na mũkiakisya.'),
('kam', 'ECC', 4, 2, 'Kwondũ wa ũu nataĩa ala akw’ũ ala makwie tene kwĩ ala me thayũ kũvika yu;'),
('kam', 'ECC', 4, 3, 'ĩĩ, na mbee wa asu nĩmũtaĩa ũla ũtanamba kwĩthĩwa, ũla ũtaona wĩa mũthũku ũla wĩkawa ĩtheo wa syũa.'),
('kam', 'ECC', 4, 4, 'Nĩvo ĩndĩ noonie wĩa w’onthe na kĩla wĩa wĩ na ũtũĩka, kana kwondũ waw’o mũndũ nũnũkwĩw’ĩwa kĩwĩũ nĩ mũtũi wake. Ũu naw’o nĩ wa mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 4, 5, 'Ndia nĩkwatanasya syaa syayo, na kũya nyama sya mwĩĩ wayo mwene.'),
('kam', 'ECC', 4, 6, 'Ũvĩ ũmwe wusĩe, vamwe na ũuu, wĩ kavaa kwĩ mbĩ ilĩ susĩe wĩa na kũsemban’ya na kĩseve.'),
('kam', 'ECC', 4, 7, 'Nĩvo ĩndĩ nasyokie na noona no mana ĩtheo wa syũa.'),
('kam', 'ECC', 4, 8, 'Kwĩ ũmwe ũla wĩ weka, na nde na ũngĩ wa kelĩ; ĩĩ, nde na mwana kana mwana‐a‐ĩthe; ĩndĩ kũti mũminũkĩlyo wa wĩa wake w’onthe, o na metho make matikolaa ũthwii. Ekũlya, Nĩtethasya wĩa kwondũ waũ, na kũima ngoo yakwa ũseo? O na ũu nĩ ũndũ wa mana, ĩĩ, nĩ thĩna mũnene.'),
('kam', 'ECC', 4, 9, 'Elĩ me kavaa kwĩ ũmwe, nũndũ me na ĩtuvi ĩseo ũndũ wa wĩa woo.'),
('kam', 'ECC', 4, 10, 'Nũndũ ethĩwa makavalũka, ũmwe akookĩlya mũtindan’ya wake; ĩndĩ woo nĩ wa ũla yĩla wĩ weka ũnũũvalũka, na nde na ũngĩ wa kũmũkĩlya.'),
('kam', 'ECC', 4, 11, 'Na ĩngĩ, ethĩwa elĩ makomaa vamwe, nĩvo ĩndĩ me na muutĩa; ĩndĩ ũmwe atonya ata kwĩthĩwa na muutĩa?'),
('kam', 'ECC', 4, 12, 'Na ethĩwa mũndũ akakĩlya vĩnya ũla wi weka, elĩ makamũsiĩĩa; ũlii mũvĩnde na ndii itatũ ndũtw’ĩkaa mĩtũkĩ.'),
('kam', 'ECC', 4, 13, 'Kavaa kĩmwana kĩkya na kyũĩ kwĩ mũsumbĩ mũkũũ na mũtumanu, ũla ũtesĩ nzĩa ya kwosa ũtao ĩngĩ.'),
('kam', 'ECC', 4, 14, 'Nũndũ nĩwaumie kolokolonĩ atw’ĩke mũsumbĩ; ĩĩ, o na ũsumbĩnĩ wake asyaiwe e ngya.'),
('kam', 'ECC', 4, 15, 'Nĩnoonie onthe me thayũ ala makinyaa ĩtheo wa syũa, atĩ maĩ vamwe na kĩmwana, kĩla kya kelĩ, kĩla kyaũngamĩe vandũ vake.'),
('kam', 'ECC', 4, 16, 'Kũtyaĩ mũmĩnũkĩlyo wa andũ onthe, o asu onthe ala waĩ ĩũlũ woo: ĩndĩ ala makooka ĩtina matikamũtanĩa. Vate ndĩĩ o na ũu naw’o nĩ mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 5, 1, 'Sũvĩa kũũ kwaku yĩla ũendaa nyũmbanĩ ya Ngai; nũndũ kũthengeea wĩw’e kwĩ kavaa kwĩ kũnengane nthembo ya ndia: nũndũ ityĩsĩ nĩsyĩkaa ũthũku.'),
('kam', 'ECC', 5, 2, 'Ndũkethĩwe ũkĩvulũka na kanyw’a waku, na ngoo yaku ndĩkekalaate kũneena ũndũ mbee wa Ngaĩ; nũndũ Ngai e ĩtunĩ, naku wĩ nthĩ: kwondũ wa ũu ndeto syaku nĩsyĩthĩwe mbũthũ.'),
('kam', 'ECC', 5, 3, 'Nũndũ ndoto nĩyũkaa nũndũ wa wĩa kwingĩva, na wasya wa ndia nũndũ wa ndeto kwingĩva.'),
('kam', 'ECC', 5, 4, 'Yĩla weevĩtĩa Ngai wĩvĩto, ndũkethĩwe na kĩkono kya kũwĩanĩsya; nũndũ ndatanĩthaw’a nĩ ndia: ĩanĩsya ũla weevĩtie.'),
('kam', 'ECC', 5, 5, 'Nĩ kavaa ũkalea kwĩvĩta, kwĩ kwĩvĩta na ũkĩlea kwĩanĩsya.'),
('kam', 'ECC', 5, 6, 'Ndũkaeke kanyw’a waku ũvĩtĩthya mwĩĩ waku; o na ndũkaneene mbee wa ũla mũlaĩka atĩ nĩ ĩvĩtyo: nũndũ wa kĩ Ngai ũthataa akĩw’a wasya waku, na aiananga wĩa wa moko maku?'),
('kam', 'ECC', 5, 7, 'Nũndũ wingĩvonĩ wa ndoto kwĩ maũndũ ma mana, o na ndetonĩ mbingĩ: ĩndĩ we kĩa Ngai.'),
('kam', 'ECC', 5, 8, 'Ethĩwa wĩona kũthĩnw’a kwa ngya, na ũsili wa katĩ na ũlũngalu maivetwa na ũng’endu kĩlungunĩ kĩnene kya nthĩ, ndũkaseng’e ũndũ wa ũndũ ũsu: nũndũ ũmwe ũla wĩ ĩũlũ kwĩ ala me ĩũlũ nũsiasya; na ve ala me ĩũlũ kwĩ asu.'),
('kam', 'ECC', 5, 9, 'Na ũndũ ũngĩ ũtandĩthyo wa nthĩ nĩ wa onthe: mũsumbĩ we mwene athũkũmawa nĩ mũũnda.'),
('kam', 'ECC', 5, 10, 'Ũla wendaa vetha ndakeanĩwa nĩ vetha; kana ũla wendaa wingĩ vamwe na wingĩvo: o na ũu naw’o nĩ mana.'),
('kam', 'ECC', 5, 11, 'Yĩla syĩndũ syaingĩva, nĩmekwingĩva ala maiĩsaa; na kwĩ ũtethyo mwaũ kwa mwene wasyo, ate o kũsyĩloela na metho make?'),
('kam', 'ECC', 5, 12, 'Too kwa mũndũ ũtethasya wĩa wĩ mũyo, ethĩwa nũĩsaa mũnini kana mwingĩ; ĩndĩ kũvũna kwa mũthwii kũtikũeka akome.'),
('kam', 'ECC', 5, 13, 'Kwĩ ũthũku wĩ woo ũla nonete ĩtheo wa syũa, naw’o nĩ ũũ, ũthwii ũsũvĩawa nĩ mwene waw’o na ũkĩmũetee ũthũku:'),
('kam', 'ECC', 5, 14, 'na mothwii asu makyanangĩka kwondũ wa ũndũ ũthũku; na ethĩwa nake nũsyaĩte mwana, vati kĩndũ kw’okonĩ kwake.'),
('kam', 'ECC', 5, 15, 'O ũndũ waumie ĩvunĩ ya nyinyia, akasyoka e mũthei o tondũ waumie, na ndakatwaa kĩndũ ũndũ wa wĩa wake, kĩla ũtonya kũkua kw’okonĩ kwake.'),
('kam', 'ECC', 5, 16, 'O na ũu naw’o nĩ ũthũku wĩ woo, atĩ o ũndũ wokie, now’o ũkathi; na ũla wĩthĩnĩasya kĩseve e na ũunĩko mwaũ?'),
('kam', 'ECC', 5, 17, 'O na mĩthenya yake yonthe aĩaa kĩvindunĩ, na nũthĩnaw’a mũno, na e na ũwau na ũthilĩku.'),
('kam', 'ECC', 5, 18, 'Sisya, ũla nonete wĩ ũseo na mwaĩlu nĩ mũndũ kũya na kũnyw’a, na kũtanĩaa ũseo wĩanĩ wake w’onthe, ũla wĩthĩnĩasya ĩtheo wa syũa, mĩthenya yonthe ya thayũ wake ũla, Ngai ũmũnengete: nũndũ ũu nĩ kĩanda kyake.'),
('kam', 'ECC', 5, 19, 'O na kĩla mũndũ ũla Ngai ũmũnengete ũthwii na syĩndũ nyingĩ, na ũmũnengete ũtonyi wa kwiĩsaa, na kwosa kĩanda kyake, na kũtana wĩanĩ wake — ũsu nĩw’o mũthĩnzĩo wa Ngai.'),
('kam', 'ECC', 5, 20, 'Nũndũ ndakalilikana mũno mĩthenya ya thayũ wake; nĩkwĩthĩwa Ngai nũmũsũngĩaa ũtanunĩ wa ngoo yake.'),
('kam', 'ECC', 6, 1, 'Ve ũthũku ũla nonete ĩtheo wa syũa, na nĩ mũito ĩũlũ wa andũ:'),
('kam', 'ECC', 6, 2, 'mũndũ ũla Ngai ũmũnengae ũthwii, na syĩndũ mbingĩ, na ndaĩa, na kwondũ wa ũu vati kĩndũ kĩoleku kya kyonthe kĩla ũnũkwenda ũndũ wa thayũ wake, ĩndĩ Ngai ndamũnengaa ũtonyĩ wa kwiĩsaa, ĩndĩ mũeni nĩwiĩsaa; ũu nĩ mana, na nĩ ũwau mũthũku.'),
('kam', 'ECC', 6, 3, 'Ethĩwa mũndũ akasyaa syana ĩana, na kwĩkala thayũ myaka mingĩ, ũkethĩa mĩthenya ya myaka yake nĩ mingĩ, ĩndĩ thayũ wake ndusĩe ũseo, o na nde na athiki; nĩasya, kĩvuno kĩvune nĩ kavaa kwĩ we;'),
('kam', 'ECC', 6, 4, 'nũndũ nĩkyũkaa kya mana, na nĩkĩendaa kĩvindunĩ, na syĩtwa yakyo nĩyĩvw’ĩkĩtwe nĩ kĩvindu;'),
('kam', 'ECC', 6, 5, 'o na ĩngĩ kityaona syũa kana ũyĩmanya; kyu kĩ na ũthũmũo kũte ũla ũngĩ:'),
('kam', 'ECC', 6, 6, 'ĩĩ, o na kethĩwa akekala thayũ myaka ngili kũndũ, kwĩlĩ, na ndatanĩaa ũseo o na wĩva, onthe matiendaa vandũ vamwe?'),
('kam', 'ECC', 6, 7, 'Wĩa w’onthe wa mũndũ nĩ kwondũ wa kanyw’a wake, ĩndĩ nzaa yake ndĩvũnaw’a.'),
('kam', 'ECC', 6, 8, 'Nũndũ ũla mũĩ akĩlĩtye ndia na kyaũ? Kana ũla ngya e na kyaũ, ũla wĩsĩ ũndũ waĩle kũendaa mbee wa ala me thayũ?'),
('kam', 'ECC', 6, 9, 'Kwona kwa metho kwĩ kavaa kwĩ kwanganga na wendi; o na ũu nĩ mana na ta kũsemban’ya na kĩseve.'),
('kam', 'ECC', 6, 10, 'O kĩla kyaĩ kw’o, kyanengiwe syĩtwa tene mũno; na nĩkũmanyĩkĩte atĩ nĩ mũndũ; o na ndatonya kũkĩlan’ya vinya na ũla wĩ ũtonyi kwĩ we.'),
('kam', 'ECC', 6, 11, 'Nĩkwĩthĩwa kwĩ syĩndũ nyingĩ ila singĩvasya maũndũ ma mana, mũndũ ũunĩkĩte na kyaũ?'),
('kam', 'ECC', 6, 12, 'Nũndũ nũũ ũla wĩsĩ ũla ũseo kwa mũndũ thayũnĩ wake, mĩthenya yonthe ya thayũ wake wa mana ũla wanangaa ta muunyĩ? Nũndũ nũũ ũla ũtonya kũtavya mũndũ ũndũ ũkethĩwa ĩtina wake ĩtheo wa syũa?'),
('kam', 'ECC', 7, 1, 'Syĩtwa ĩseo yĩ kavaa kwĩ mauta me vata mũno; na mũthenya wa kũkw’a wĩ kavaa kwĩ mũthenya wa kũsyawa kwa mũndũ.'),
('kam', 'ECC', 7, 2, 'Nĩ kavaa kũthi nyũmbanĩ ya kũmetea kwĩ kũthi nyũmbanĩ ya kũĩĩwa mboka: nũndũ ũu nĩ mũminũkĩlyo wa andũ onthe; na ũla wĩ thayũ akaia ũndũ ũsu ngoonĩ yake.'),
('kam', 'ECC', 7, 3, 'Woo wĩ kavaa kwĩ kũtheka; nũndũ kwondũ wa woo kwoneka ũthyũnĩ ngoo nĩnĩũtanw’a.'),
('kam', 'ECC', 7, 4, 'Ngoo ya ũla mũĩ yĩ nyũmbanĩ ya kũmetea; ĩndĩ ngoo sya ndia syĩ nyũmbanĩ ya kũtanĩa.'),
('kam', 'ECC', 7, 5, 'Nĩ kavaa kwĩw’a ũkan’yo wa ũla mũĩ, kwĩ mũndũ kwĩw’a wathi wa ndia.'),
('kam', 'ECC', 7, 6, 'O tondũ kũilyĩ kũlalamũka kwa mĩw’a ungu wa mbisũ, o ta ũu now’o kũilyĩ kũtheka kwa ndia; o na ũu naw’o nĩ mana.'),
('kam', 'ECC', 7, 7, 'Vate ndĩi kũvutana nĩkũmũtw’ĩkĩthasya mũndũ mũĩ mũtumanu; na ĩvaki nĩyanangaa ũmanyi.'),
('kam', 'ECC', 7, 8, 'Mũminũkĩlyo wa ũndũ nĩ kavaa kwĩ wambĩlĩlyo; na mũmĩĩsya vevanĩ nĩ kavaa kwĩ mwĩkathĩĩi vevanĩ.'),
('kam', 'ECC', 7, 9, 'Ndũkethĩwe wĩ mĩtũkĩ kũthata vevanĩ waku; nũndũ ũthatu wĩkalaa kĩthũinĩ kya ndia.'),
('kam', 'ECC', 7, 10, 'Ndũkasye, Kĩtumi nĩ kyaũ kya mĩthenya ya tene kwĩthĩwa kavaa kwĩ ĩno? Nũndũ ndũkũlasya na ũĩ ũndũnĩ ũsu.'),
('kam', 'ECC', 7, 11, 'Ũĩ nĩ mũseo o ta ũtiĩwa; nĩ mũseo mbee kwa ala monaa syũa.'),
('kam', 'ECC', 7, 12, 'Nũndũ ũĩ nĩ ũsũvĩo, o tondũ mbesa nĩ ũsũvĩo; ĩndĩ ũseo mũnene wa ũmanyi nĩ, atĩ ũĩ nũsũvĩaa thayũ wa ũla wĩ naw’o.'),
('kam', 'ECC', 7, 13, 'Sũanĩa wĩa wa Ngai: nũndũ nũũ ũtonya kũlũngalya kĩla we wathyoekisye?'),
('kam', 'ECC', 7, 14, 'Mũthenya wa ũunĩko tana, na mũthenya wa ũkya sũania; ĩĩ, Ngai nũseũvĩtye ũmwe ũkwatene na ũla ũngĩ, nĩ kana mũndũ ndakamanye ũndũ o na wĩva, ũla ũkethĩwa ĩtina.'),
('kam', 'ECC', 7, 15, 'Ũũ w’onthe nĩnonete mĩthenyanĩ yakwa ya mana: ve ũndũ mũlũngalu ũla waaa ũlũngalunĩ wake, na ve mũndũ mũthũku ũla ũasavasya thayũ wake o akĩka ũthũku.'),
('kam', 'ECC', 7, 16, 'Ndũkethĩwe na ũlũngalu mũvĩtũku; na ndũkethĩwe na ũĩ mũvĩtũku: wĩyanangĩa mwene kĩ?'),
('kam', 'ECC', 7, 17, 'Ndũkethĩwe na ũthũku mũvĩtũku, o na ndũkethĩwe wĩ mũtumanu: wĩkw’a ĩvinda yaku yĩte ĩviku nĩkĩ?'),
('kam', 'ECC', 7, 18, 'Nĩ ũseo ũkwate ũndũ ũũ; ĩĩ, o na ndũkatũnge kw’oko kwaku kuma ũndũnĩ ũya: nũndũ ũla ũmũkĩaa Ngai akeeyumya nthĩnĩ wa asu onthe.'),
('kam', 'ECC', 7, 19, 'Uĩ nĩ vinya kwa mũndũ ũla wĩ na ũĩ kũvĩtũka asumbĩki ĩkũmi ala me ndũani.'),
('kam', 'ECC', 7, 20, 'Vate ndĩi kũti mũndũ mũlũngalũ ĩũlũ wa nthĩ, ũla wĩkaa nesa, ũteka naĩ.'),
('kam', 'ECC', 7, 21, 'O na ndũkethukĩĩsye ndeto syonthe ila ĩneenawa, ndũkese kwĩw’a mũthũkũmĩ waku akĩũuma;'),
('kam', 'ECC', 7, 22, 'nũndũ mavinda maingĩ ngoo yaku nayo nĩyĩsĩ kana we mwene nũumĩte angĩ.'),
('kam', 'ECC', 7, 23, 'Ũu w’onthe nĩndatĩte kwa ũĩ: naisye, ngeethĩwa nĩ mũĩ; ĩndĩ waĩ kũasa nakwa.'),
('kam', 'ECC', 7, 24, 'Ũla wĩ kw’o, wĩ kũasa na ũliku mũno; nũũ ũtonya kũmanya?'),
('kam', 'ECC', 7, 25, 'Nĩneethyũũie, na ngoo yakwa yaiwa kũmanya na kũthiana, na kũmantha ũĩ na kĩtumi kya maũndũ, na kũmanya kana ũthũku nĩ ũtumanu, na ũtumanu naw’o nĩ ũũũki.'),
('kam', 'ECC', 7, 26, 'Nakwa nĩngwona wĩ ũũ kwĩ kĩkw’ũ mũndũ mũka ũla ngoo yake yĩ itei na mĩkwa, na moko make nĩ syĩndũ sya kwova nasyo: o ũla ũmwendeeasya Ngai akavonoka kuma vala ũĩ; ĩndĩ mũndũ mwathe akakwatwa nĩwe.'),
('kam', 'ECC', 7, 27, 'Sisya, nĩnonete ũu, easya Mũtavan’ya, ngĩthiman’ya ũndũ ũmwe na ũla ũngĩ, nĩmanye kĩtumi;'),
('kam', 'ECC', 7, 28, 'Ũndũ ũla ngoo yakwa yendaa kũmantha ĩndĩ ndĩnamba kũwona: mũndũ mũũme ũmwe katĩ wa ngili nĩnonete; ĩndĩ mũndũ mũka katĩ wa asu onthe ndyaona.'),
('kam', 'ECC', 7, 29, 'Sisya, ũndũ ũla nonete nĩ ũũ: Ngai nĩwombie mũndũ e mũlũngalu; ĩndĩ nĩmamanthaa makosokoso maingĩ.'),
('kam', 'ECC', 8, 1, 'Nũũ ũilyĩ ta mũndũ mũĩ? Na nũũ ũla wĩsĩ ũalyũlo wa ũndũ? Ũĩ wa mũndũ nũtisangĩthasya ũthyũ wake, na wũmũ wa ũthyũ wake ũkĩalyũka.'),
('kam', 'ECC', 8, 2, 'Nĩngũkũtaa, Kwata mwĩao wa mũsumbĩ nũndũ wa kũmwĩavĩa Ngai.'),
('kam', 'ECC', 8, 3, 'Ndũkekalaate kuma vala ũĩ: ndũkething’ĩĩsye ũndũnĩ ũthũku: nũndũ nĩwĩkaa o ũndũ ũla ũmwendeeasya.'),
('kam', 'ECC', 8, 4, 'Nũndũ ndeto ya mũsumbĩ yĩ na vinya; na nũũ ũtonya kũmwĩa, Wĩĩka ata?'),
('kam', 'ECC', 8, 5, 'O ũla ũkakwata mwĩao ndakamanya ũndũ ũthũku; na ngoo ya mũndũ mũĩ nĩmanyaa ĩvinda na ũsilĩlo:'),
('kam', 'ECC', 8, 6, 'nũndũ kwondũ wa kĩla ũndũ kwĩ ĩvinda na ũsilĩlo; nĩkwĩthĩwa thĩna wa mũndũ nĩ mũnene ĩũlũ wake:'),
('kam', 'ECC', 8, 7, 'nũndũ ndesĩ ũla ũkethĩwa; nũndũ nũũ ũtonya kũmũtavya kũkethĩwa ata?'),
('kam', 'ECC', 8, 8, 'Vati mũndũ ũla wĩ na vinya ĩũlũ wa veva, wa kũsiĩĩa veva; o na nde na vinya ĩũlũ wa mũthenya wa kĩkw’ũ; na vati kũvutwa kaũnĩ; o na ũthũku ndũkamũvonokya ũla wenenganie kwaw’o.'),
('kam', 'ECC', 8, 9, 'Ũũ w’onthe nĩnonete, na neekĩa ngoo yakwa kĩla wĩanĩ ũla ũtethaw’a ĩtheo wa syũa; kwĩ ĩvinda yĩla mũndũ ũmwe wĩ na vinya ĩũlũ wa ũngĩ na akĩyĩka ũthũku.'),
('kam', 'ECC', 8, 10, 'Na ĩndĩ noona ala athũku mathikwa nthĩ, na mooka mathikonĩ; na ala meekie ũseo maumie vandũ vatheu, na moola ndũanĩ: o na ũu naw’o nĩ mana.'),
('kam', 'ECC', 8, 11, 'Nĩkwĩthĩwa ũtwi ũla ũtusĩaw’a wĩa mũthũku ndwĩanĩaw’a mĩtũkĩ, kwondũ wa ũu ngoo sya ana ma andũ nilũmĩtw’e syĩke ũthũku.'),
('kam', 'ECC', 8, 12, 'O na ethĩwa mũndũ mwathe akeeka ũthũku mavĩnda ĩana, na kwongeleela mĩthenya yake, ĩndĩ vate ndĩi nĩnĩsĩ kũkeethĩwa ũseo kwa ala makĩaa Ngai, ala makĩaa mbee wake:'),
('kam', 'ECC', 8, 13, 'ĩndĩ kũtikethĩwa ũseo kwa ũla mũthũku o nake ndakongeleela mĩthenya yake, ĩla ĩilyĩ ta muunyĩ; nĩkwĩthĩwa ndakĩaa Ngai.'),
('kam', 'ECC', 8, 14, 'Kwĩ ũndũ wa mana ũla wĩkawa ĩũlũ wa nthĩ, atĩ nĩkwĩkĩkaa kwa andũ alũngalu kwĩanana na wĩa wa ala athũku: na ĩngĩ, nĩkwĩkĩkaa kwa andũ athũku kwĩanana na wĩa wa ala alũngalu: naisye o na ũu naw’o nĩ mana.'),
('kam', 'ECC', 8, 15, 'Nĩvo ĩndĩ nataĩe ũtanu, nĩkwĩthĩwa mũndũ nde na ũndũ ũseo mbee ĩtheo wa syũa kwi kũya, na kũnyw’a, na kũtana: nũndũ ũndũ ũsu ũkekalaa nake wĩanĩ wake mĩthenya yonthe ya thayũ wake ũla Ngai ũmũnengete ĩtheo wa syũa.'),
('kam', 'ECC', 8, 16, 'Yĩla nanenganie ngoo yakwa ĩmanye ũĩ, na kwona maũndũ ala mekawa ĩũlũ wa nthĩ (nĩkwĩthĩwa ve ũla ũtaona too na metho make mũthenya kana ũtukũ),'),
('kam', 'ECC', 8, 17, 'nĩvo ĩndĩ noonĩe wĩa w’onthe wa Ngai, atĩ mũndũ ndatonya kũmanya wĩa ũla ũtethaw’a ĩtheo wa syũa: nĩkwĩthĩwa o na mũndũ akethĩn’ya ata kũmantha, ndakawona; ĩĩ o na mbee wa ũu, o na ethĩwa mũndũ mũĩ nũsũanĩaa kũmanya ndakatonya kũwona.'),
('kam', 'ECC', 9, 1, 'Ũu w’onthe naia ngoonĩ yakwa, o kũmantha ũũ w’onthe: atĩ ũla mũlũngalu, na ũla mũĩ, na mawĩa moo me mokonĩ ma Ngai; ethĩwa nĩ wendo kana kĩmena, mũndũ ndawĩsĩ; w’onthe wĩ mbee woo.'),
('kam', 'ECC', 9, 2, 'Maũndũ onthe mokaa ũndũ ũmwe kwa onthe; ve ũndũ ũmwe kwa ũla mũlũngalu na kwa ũla mũthũku; kwa ũla mũseo na kwa ũla mũtheu na ũla mũvuku; kwa ũla ũthembaa na kwa ũla ũtathembaa; o tondũ ũla mũseo ũilyĩ, now’o mũndũ mwathe ũilyĩ; na ũla wĩvĩtaa, o ta ũla ũkĩaa wĩvĩto.'),
('kam', 'ECC', 9, 3, 'Ũũ nĩ ũthũku maũndũnĩ onthe ala mekawa ĩtheo wa syũa, atĩ kwĩ ũndũ ũmwe kwa onthe: ĩĩ o na ĩngĩ ngoo sya ana ma andũ nĩsyusũĩte ũthũku, na ũũũki wĩ ngoonĩ syoo yĩla me thayũ, na ĩtina wa ũu maendaa vala ve akw’ũ.'),
('kam', 'ECC', 9, 4, 'Indĩ kwa ũla ũkwatene na onthe ala me thayũ kwĩ wĩkwatyo; nũndũ ngitĩ yĩ thayũ yĩ kavaa kwĩ mũnyambũ mũkw’ũ.'),
('kam', 'ECC', 9, 5, 'Nũndũ ala me thayũ mesĩ makakw’a; ĩndĩ ala akw’ũ matyĩsĩ ũndũ o na wĩva, o na mati na ĩtũvi ĩngĩ; nũndũ kũlilikanwa kwoo nĩkũlaa.'),
('kam', 'ECC', 9, 6, 'Wendo woo, o na kĩmena kyoo na kĩwĩu kyoo, nĩsyaaie tene mũno; o na mati na kĩanda ĩngĩ tene na tene ũndũnĩ o na wĩva ũla wĩkawa ĩtheo wa syũa'),
('kam', 'ECC', 9, 7, 'Ĩendee, ya kĩmũtũ kyaku na ũtanu, na nyw’a mbinyu yaku na ngoo ndanu; nũndũ Ngai nĩwĩtĩkĩlĩte mawĩa maku.'),
('kam', 'ECC', 9, 8, 'Ngũa syaku nĩsyĩthĩwe syĩ nzaũ mavinda onthe; na mũtwe waku ndũkaanyĩvĩwe nĩ mauta.'),
('kam', 'ECC', 9, 9, 'Ĩkala na ũtanu na kĩveti kĩla ũkyendete mĩthenya yonthe ya thayũ waku wa mana, ũla ũkũnengete ĩtheo wa syũa, mĩthenya yaku yonthe ya mana: nũndũ kyu nĩ kĩanda kyaku wĩ thayũ, na wĩanĩ waku ũla ũtethasya ĩtheo wa syũa.'),
('kam', 'ECC', 9, 10, 'O ũla kw’oko kwaku kwona wa kwĩka, ĩka na vinya waku, nũndũ kũti wĩa kana ũsũanĩo, kana ũmanyi, kana ũĩ, Seoli vala ũendete.'),
('kam', 'ECC', 9, 11, 'Nĩneethyũũie, na noona ĩtheo wa syũa, kana kũsemba ũkĩlanyonĩ ti kwa ala me mĩtũkĩ, kana kũkita kwa ala me vinya, o na kĩmũtũ kwa ũla mũĩ, o na ũthwii kwa andũ me na ũmanyi, kana ũseo kwa ala me na ũtũĩka; ĩndĩ ĩvinda na ĩvuso nĩsyĩkĩkaa kwa onthe.'),
('kam', 'ECC', 9, 12, 'Nũndũ mũndũ nake ndamanyaa ĩvinda yake: ta makũyũ ala makwataw’a kĩteinĩ kĩthũku, na ta nyũnyi ila ikwataw’a na ĩkenge, o ta ũu ana ma andũ makwataw’a ĩvinda ĩthũku, yĩla yĩmavalũkĩlaa na kĩthũlũmũko.'),
('kam', 'ECC', 9, 13, 'O na nĩnonete ũĩ ĩtheo wa syũa ta ũũ, na wooneka kwakwa ta mũnene:'),
('kam', 'ECC', 9, 14, 'Kwaĩ ndũa nini, na andũ avũthũ nthĩnĩ wayo; na kwookie mũsumbĩ mũnene kũkita nayo, na amĩtw’ĩkanĩsya, na amyakĩĩa maũvai matũlu.'),
('kam', 'ECC', 9, 15, 'Na nthĩnĩ wayo kwoonekie mũndũ mũĩ ngya, nake kwondũ wa ũĩ wake amĩvonokya ĩ ndũa; ĩndĩ vatyaĩ mũndũ waalilikana mũndũ ũsu ngya.'),
('kam', 'ECC', 9, 16, 'Nĩvo ĩndĩ naisye, Ũĩ nĩ kavaa kwĩ vinya, o na ũu w’onthe ũĩ wa mũndũ ũsu ngya nũvũthaw’a, na ndeto syake ityĩthukĩĩw’a.'),
('kam', 'ECC', 9, 17, 'Ndeto sya ũla mũĩ ikĩthukĩĩw’a na ũuu nĩ kavaa kwĩ kĩlonzo kya ũla ũsumbĩkaa katĩ wa ndia.'),
('kam', 'ECC', 9, 18, 'Ũĩ wĩ kavaa kwĩ mĩio ya kaũ; ĩndĩ mũndũ ũmwe mwathe nĩwanangaa ũseo mwingĩ.'),
('kam', 'ECC', 10, 1, 'Ngi ngw’ũ nitumaa mauta ma mũseũvya wa syĩndũ ĩla ĩnyungaa nesa maumya mũuke mũthũku; o ta ũu ũtumanu mũnini nũvĩtĩte ũĩ na ndaĩa.'),
('kam', 'ECC', 10, 2, 'Ngoo ya mũndũ mũĩ yĩ kw’okonĩ kwake kwa aũme, ĩndĩ ngoo ya ndia yĩ kw’okonĩ kwayo kwa aka.'),
('kam', 'ECC', 10, 3, 'Ĩĩ, o na ĩngĩ, yĩla ndia ĩendete na nzĩa, ũmanyi wayo nũmĩnyivĩaa, nayo ĩtavasya kĩla mũndũ kana nĩ ndia.'),
('kam', 'ECC', 10, 4, 'Ethĩwa veva wa mũsumbĩki nũũkũkĩlĩla ndũkaume vandũ vaku; nũndũ ũuu nũvoovasya movĩtyo manene.'),
('kam', 'ECC', 10, 5, 'Kwĩ ũthũku ũla nonete ĩtheo wa syũa, naw’o nĩ ĩvĩtyo yĩla yũmaa kwa mũsumbĩki:'),
('kam', 'ECC', 10, 6, 'ũtumanu nĩwiĩtwe motũlunĩ manene, na athwii mekalaa vandũ va ĩtheo.'),
('kam', 'ECC', 10, 7, 'Nĩnonete athũkũmi makuĩtwe nĩ mbalasi, na anene me mbee ũsumbĩnĩ makĩthi na maũũ ĩũlũ wa nthĩ ta athũkũmi.'),
('kam', 'ECC', 10, 8, 'Ũla wĩĩnza ĩima akavalũka nthĩnĩ wayo; na o ũla wĩvũthũa wako nzoka ĩkamũũma.'),
('kam', 'ECC', 10, 9, 'O ũla walasya mavia akakũnwa nĩmo; na ũla watũaa mĩtĩ elikasya mũisyonĩ.'),
('kam', 'ECC', 10, 10, 'Ethĩwa kĩaa nĩ kĩtuvu, na mũndũ ndakĩnoaa, nĩvo ĩndĩ mũvaka ongeleele vinya: ĩndĩ ũĩ nĩwaĩlaa kwa kũvota.'),
('kam', 'ECC', 10, 11, 'Ethĩwa nzoka nĩyaũma ĩtanamba kũvoovw’a nĩvo ĩndĩ kũti ũtandĩthyo wa mũvoosya.'),
('kam', 'ECC', 10, 12, 'Ndeto sya kanyw’a wa mũndũ mũĩ nĩ nzeo; ĩndĩ ilomo sya ndia ĩkamĩmelya.'),
('kam', 'ECC', 10, 13, 'Wambĩlĩlyo wa ndeto sya kanyw’a wayo nĩ ũtumanu; na mũminũkĩlyo wa kũneena kwayo nĩ ũũũki mũthũku.'),
('kam', 'ECC', 10, 14, 'O na ndia nĩyingĩvasya ndeto: ĩndĩ mũndũ ndamanya ũndũ ũkethĩwa; na ũndũ ũla ũkethiwa ĩtina wake, nũũ ũtonya kũmũtavya?'),
('kam', 'ECC', 10, 15, 'Wĩa wa ndia nũnoasya kĩla ĩmwe yasyo; nũndũ ndĩsĩ ũndũ ĩtonya kũthi ndũanĩ.'),
('kam', 'ECC', 10, 16, 'Woo nĩ waku, we nthĩ, yĩla mũsumbĩ waku nĩ kana, na anene maku me mbee ũsumbĩnĩ maĩsaa kĩoko!'),
('kam', 'ECC', 10, 17, 'Wĩ na ũtanu, we nthĩ, yĩla mũsumbĩ waku nĩ mwana wa andũ me ndaĩa, na anene maku me mbee ũsumbĩnĩ maĩsaa ĩvinda yaw’o, ũndũ wa vinya, na ti ũndũ wa ũthengi!'),
('kam', 'ECC', 10, 18, 'Nũndũ wa ũtulu kĩala nĩkĩlikaa nthĩnĩ; na kwondũ wa ũtulu wa moko nyũmba nĩyuasya.'),
('kam', 'ECC', 10, 19, 'Mboka nĩvokawa ũndũ wa kũtheka, na mbinyu nĩtanasya thayũ; na mbesa nisũngĩaa maũndũ onthe.'),
('kam', 'ECC', 10, 20, 'Ndũkamũume mũsumbĩ, aiee, ndũkamũume ũsũanĩonĩ waku; na ndũkaumĩe mũthwii wĩ kasũmbanĩ kaku ka ũkoma: nũndũ nyũnyi ya matunĩ ĩkakua wasya, na kĩla kĩ nthwau kĩkatavan’ya ũvoo ũsu.'),
('kam', 'ECC', 11, 1, 'Ĩkya kĩmũtũ kyaku ĩũlũ wa manzĩ; nũndũ ũkakyona ĩtina wa mĩthenya mingĩ.'),
('kam', 'ECC', 11, 2, 'Nenga andũ mũonza kĩlungu, ĩĩ, o na nyanya; nũndũ ndwĩsĩ ũthũku ũla ũkethĩwa ĩũlũ wa nthĩ.'),
('kam', 'ECC', 11, 3, 'Ethĩwa mathweo nĩmausũĩtwe nĩ mbua, nĩmekwonosya manzĩ mamo ĩũlũ wa nthĩ; na ethĩwa mũtĩ nũũvalũka kwelekela ngalĩ ya ĩtheo, kana kwelekela ngalĩ ya ĩũlũ, vandũ, vala mũtĩ wĩvalũka, vu novo ũkethĩwa.'),
('kam', 'ECC', 11, 4, 'Ũla ũsiasya kĩseve ndakavuĩa; na ũla ũsiasya mathweo ndakaketha.'),
('kam', 'ECC', 11, 5, 'O ũndũ ũtesĩ nzĩa ya kĩseve, kana ũndũ mavĩndĩ meanaa ĩvunĩ ya ũla mũito; o ta ũu ndwĩsĩ wĩa wa Ngai ũla wĩkaa maũndũ onthe.'),
('kam', 'ECC', 11, 6, 'Kĩoko vuĩa mbeũ syaku, na wĩoo ndũkasiĩĩe kw’oko kwaku; nũndũ ndwĩsĩ ila ikaĩla, ethĩwa nĩ ii kana iya, kana ethĩwa syelĩ ikeethĩwa nzeo ũndũ ũmwe.'),
('kam', 'ECC', 11, 7, 'Nĩ w’o kyeni kĩ mũyo, na kũsisya syũa nĩkwendeeasya metho.'),
('kam', 'ECC', 11, 8, 'Ĩĩ, ethĩwa mũndũ akekala thayũ myaka mingĩ, natane nthĩnĩ wayo yonthe; ĩndĩ nalilikane mĩthenya ya kĩvindu, nũndũ ĩkeethĩwa mingĩ. Kyonthe kĩla kyũkaa nĩ mana.'),
('kam', 'ECC', 11, 9, 'Tana, we mwanake, wananĩ waku, na ngoo yaku ĩkũtan’ye mĩthenya ya wana waku, na kinya nzĩanĩ sya ngoo yaku, na kwonanĩ kwa metho maku; ĩndĩ manya we, Ngai akakũete ũsilĩlonĩ ũndũ wa maũndũ asu onthe.'),
('kam', 'ECC', 11, 10, 'Kwondũ wa ũu veta woo ngoonĩ yaku, na ĩkya kũasa ũthũku kuma mwĩĩnĩ waku; nũndũ wana na ũika wa thayũ nĩ mana.'),
('kam', 'ECC', 12, 1, 'O na lilikana Mũmbi waku mĩthenya ya wana waku mĩthenya mĩthũku ĩtanamba kũka, na myaka ĩthengeea, yĩla ũkasya, Ndi na ũtanu nthĩnĩ wayo;'),
('kam', 'ECC', 12, 2, 'syũa, na kyeni na mwei, na ndata itanamba kũya kĩvindu, na mathweo kũsyoka ĩtina wa mbua;'),
('kam', 'ECC', 12, 3, 'mũthenya ũla asũvĩi ma nyũmba makatetema, na andũ me vinya makekunamya, na ala mathiaa maieka nũndũ nĩ avũthũ, na ala mesyaĩlya mbũthinĩ makethĩwa na kĩvindu,'),
('kam', 'ECC', 12, 4, 'na mĩomo ĩkavĩngwa nzĩanĩ nene; yĩla wasya wa kũthia wĩnyiva, na ũmwe akookĩlw’a nĩ wasya wa nyũnyi, na eĩtu onthe ma kwina makatheew’a vyũ;'),
('kam', 'ECC', 12, 5, 'ĩĩ, makakĩa kĩla kĩ ĩũlũ, na motĩsyo makeethĩwa nzĩanĩ; na mũtĩ wa mũlosi ũkalaũka, na kĩtoolĩ kĩkeethĩwa mũio, na kĩla kĩkwendwa kĩkaa; nũndũ mũndũ nũendaa mũsyĩ wake wa tene na tene, na ala mametaa nĩmangangaa nzĩanĩ nene:'),
('kam', 'ECC', 12, 6, 'ũlii wa vetha ũtanamba kũthaw’a, kana mbakũli ya thaavu kũawa, kana kĩtete kũaĩwa nthongonĩ, kana ndĩa kũtw’ĩkĩa kĩthimanĩ,'),
('kam', 'ECC', 12, 7, 'na kĩtoo kĩisyoka nthĩ o ũndũ kyailyĩ, na veva kũsyoka kwa Ngai ũla wonenganie.'),
('kam', 'ECC', 12, 8, 'No mana, mana vyũ, easya ũu Mũtavan’ya, onthe nĩ mana.'),
('kam', 'ECC', 12, 9, 'Na ũndũ ũngĩ, nĩkwĩthĩwa Mũtavan’ya aĩ mũĩ, aendeea na kũmanyĩsya andũ ũmanyi; ĩĩ, nĩwasũanĩaa, na kũmantha, na kwaĩĩa nthimo nyingĩ.'),
('kam', 'ECC', 12, 10, 'Mũtavan’ya nĩwatatie kwona ndeto syĩ mũyo, na ũvoo ũla ũandĩkĩtwe ũlũngalunĩ, o ndeto sya w’o.'),
('kam', 'ECC', 12, 11, 'Ndeto sya ũla mũĩ iilyĩ ta mĩsenge; na ndeto sya anene ala mombanasya, ila syumaw’a nĩ mũĩthi ũmwe no ta mĩsumaa ĩathĩĩtwe.'),
('kam', 'ECC', 12, 12, 'Na mbee wa ũu, mwana wakwa, taĩka; kũti mũminũkĩlyo wa kũseũvya mavuku maingĩ; na kwĩmanyĩsya mũno nĩ mĩnoo ya mwĩĩ.'),
('kam', 'ECC', 12, 13, 'Ũũ nĩw’o mũminũkĩlyo wa ũvoo; w’onthe nĩwĩw’ĩkĩte: Kĩa Ngai, na kwata mĩao yake; nũndũ ũu nĩw’o ũndũ w’onthe waĩlĩte kwĩkawa nĩ mũndũ.'),
('kam', 'ECC', 12, 14, 'Nũndũ Ngaĩ akaete kĩla wĩa ũsilĩlonĩ, vamwe na kĩla ũndũ ũvithĩtwe, ethĩwa nĩ ũseo kana ethĩwa nĩ ũthũku.'),
('kam', 'SNG', 1, 1, 'Wathi wa mbathi, ũla wa Solomoni.'),
('kam', 'SNG', 1, 2, 'We namumunye nyie na momumunyo ma kanyw’a wake: Nũndũ wendo waku wĩ kavaa kwĩ mbinyu.'),
('kam', 'SNG', 1, 3, 'Mauta maku me mũuke mũseo; Syĩtwa yaku nĩ ta mauta metĩkye; Kwondũ wa ũu eĩtu atheu nĩmakwendaa.'),
('kam', 'SNG', 1, 4, 'Ngusya; naitũ nĩtũũkũvikĩla tũsembete: Mũsumbĩ nĩwandetie tũsũmbanĩ twake; Tũkatana na kũkwĩw’ĩa mũyo; Tũkaweta wendo waku kũte mbinyu: Nĩmakwendaa na w’o.'),
('kam', 'SNG', 1, 5, 'Nyie nĩ mwiũ, ĩndĩ nĩ mũmbe nesa, Inyw’ĩ eĩtu ma Yelusaleme, O ta maeema ma Ketali, O ta ngũa sya ũtũta sya Solomoni.'),
('kam', 'SNG', 1, 6, 'Ndũkanzisye, nĩkwĩthĩwa nĩ mũtune, Nũndũ syũa nĩyĩmbĩvĩtye. Ana‐a‐ia makwa nĩmanthatĩe; Mandw’ĩte mũsũvĩi wa miũnda ya mĩsavivũ; Ĩndĩ mũũnda ũla wakwa mwene ndyaosũvĩa.'),
('kam', 'SNG', 1, 7, 'Ndavya, we ũla ngoo yakwa yendete, Vala ũĩthasya ĩĩthya yaku ya mbũi na malondu, Vala ũtindiasya mũthenya katĩ: Nũndũ wa kĩ nĩilyĩ ta ũmwe ũla ũvw’ĩkĩte ũthyũ suka mũvũthũ Ũtee wa ĩĩthya ya mbũi na malondũ ya atindan’ya maku?'),
('kam', 'SNG', 1, 8, 'Ethĩwa ndwĩsĩ, we ũla wĩ mwanakavu kũvĩtũka aka ala angĩ, Ĩendee umaalĩte na malata ma ndĩthya ya mbũi na malondu, Na ũiĩthya tũtenatwaku twambũi ũtee wa maeema ma aĩthi.'),
('kam', 'SNG', 1, 9, 'Ngũvw’anen’ye, we mwendwa wakwa, Na mbalasi yĩ makasyanĩ ma Valao.'),
('kam', 'SNG', 1, 10, 'Matau maku nĩ manake nĩ mũvĩndĩle wa nzw’ĩĩ, Ngingo yaku, na ndii syĩ na tũvila twĩ thooa mũnene.'),
('kam', 'SNG', 1, 11, 'Tũkakũvĩndanĩsya tũkanda twa thaavu, Twĩ na ivungo sya vetha.'),
('kam', 'SNG', 1, 12, 'Yĩla mũsumbĩ wailyĩ mesanĩ yake, Manukato makwa nĩmataavũkie mũuke wamo mũseo.'),
('kam', 'SNG', 1, 13, 'Mwendwa wakwa kwakwa nĩ ta kakusu ka manemane, Kala kaiĩtwe katĩ wa nondo syakwa.'),
('kam', 'SNG', 1, 14, 'Mwendwa wakwa kwakwa nĩ ta kitũngo kya malaa ma mũena Mĩũndanĩ ya mĩsavivũ ya Eni‐ngeti.'),
('kam', 'SNG', 1, 15, 'Sisya, wĩ mwanakavu; mwendwa wakwa; Sisya, wĩ mwanakavu; Metho maku nĩ ta ma mavũĩ.'),
('kam', 'SNG', 1, 16, 'Sisya, wĩ mwanakavu, mwendwa wakwa, ĩĩ, wa kwendeesya: O na ĩngĩ ũkomo witũ wĩ langi wĩ kĩsũnzũni.'),
('kam', 'SNG', 1, 17, 'Mĩamba ya nyũmba yaitũ nĩ ya mĩtĩ ya mĩkũũ, Mĩtĩ ya kĩala nĩ ya mĩtĩ ya mĩsonovali.'),
('kam', 'SNG', 2, 1, 'Nyie nĩ ĩlaa ya lose ya Saloni, Ĩlaa ya lili ya myandanĩ.'),
('kam', 'SNG', 2, 2, 'Ta ĩlaa ya lili katĩ wa mĩw’a, Now’o mwendwa wakwa ũilyĩ katĩ wa eĩtu.'),
('kam', 'SNG', 2, 3, 'O tondũ mũtĩ wa mũevo ũtilyĩ katĩ wa mĩtĩ ya kĩthekanĩ, Now’o mwendwa wakwa ũilyĩ katĩ wa ana aũme. Nĩnekalile nthĩ ĩtheo wa muunyĩ wake nĩ na mũyo mũnene, Na matunda make maĩ mũyo mũsamonĩ wakwa.'),
('kam', 'SNG', 2, 4, 'Andetie nyũmbanĩ ya mboka, Na kĩvevelo kyake ĩũlũ wakwa kyaĩ kya wendo.'),
('kam', 'SNG', 2, 5, 'Mbĩkĩai vinya na tũkũmbwa twa nzavivũ mbovu, mbuũkyai na ũsyao wa mũevo; Nũndũ nĩwaĩtw’e nĩ wendo.'),
('kam', 'SNG', 2, 6, 'Kw’oko kwake kwa aka kwĩ ungu wa mũtwe wakwa, Na kw’oko kwake kwa aũme nĩkwĩmbĩtĩĩsye.'),
('kam', 'SNG', 2, 7, 'Nĩngũmũavĩthya inyw’ĩ, eĩtu ma Yelusaleme, Na nthwaia nga, kana na ndaatai nga sya kĩthekanĩ, Mũtikamũthũlũmũe, kana ũmũamũkya mwendwa wakwa, Kũvika endeew’a.'),
('kam', 'SNG', 2, 8, 'Wasya wa mwendwa wakwa! Sisya, nĩwũkĩte, Akĩtũlĩlanga ĩũlũ wa iĩma, Kũthakathaka ĩũlũ wa tũlĩma.'),
('kam', 'SNG', 2, 9, 'Mwendwa wakwa atilyĩ ta nthwaia nga kana ndaatai nzamba ya mũika: Sisya, aũngamĩte ngalĩ ĩya ya wako witũ; Aisyaĩlya nthĩnĩ mbũthinĩ; Atemethelya metho mĩtĩnĩ mĩkelangan’ye.'),
('kam', 'SNG', 2, 10, 'Mwendwa wakwa nĩwaneenie, na ambĩa, Ũkĩla, mwendwa wakwa, mbanake yakwa, na kwĩendea.'),
('kam', 'SNG', 2, 11, 'Nũndũ, sisya, ĩvinda ya mbevo nĩ ĩvĩtu; Mbua nĩ mbĩtu na ĩkathi;'),
('kam', 'SNG', 2, 12, 'Malaa nĩ moneku ĩũlũ wa nthĩ; Ĩvinda ya kwina ya nyũnyi nĩ yũku, Na wasya wa ndumbũ nũkwĩw’ĩka nthĩ yaitũ;'),
('kam', 'SNG', 2, 13, 'Mũkũyũ nĩwĩw’ĩte makũyũ maw’o methĩ, Na mĩsavivũ nĩ mĩlaũku; Nĩyataavũkĩte mĩuke yayo mĩseo. Ũkĩla, mwendwa wakwa, mbanake yakwa, na kwĩendea.'),
('kam', 'SNG', 2, 14, 'We ĩvũĩ yakwa, wĩ mĩvatĩnĩ ya ivĩsĩ, Wĩvithonĩ wĩ kĩvaũũkonĩ, Eka nzisye ũthyũ waku, Eka nĩw’e wasya waku; Nũndũ wasya waku wĩ mũyo, na ũthyũ waku nĩ mwanake.'),
('kam', 'SNG', 2, 15, 'Tũkwate mbĩwa, mbĩwa ila nini, Ila syanangaa mĩũnda ya mĩsavivũ; Nũndũ mĩũnda yaitũ ya mĩsavivũ nĩ mĩlaũku.'),
('kam', 'SNG', 2, 16, 'Mwendwa wakwa nĩ wakwa, nakwa nĩ wake: Eĩthya ndĩthya yake ya mbũi na malondu katĩ wa malaa ma lili.'),
('kam', 'SNG', 2, 17, 'Kũvika syũa yausya, na myuunyĩ yalalĩla, Ĩthyũũe, mwendwa wakwa, na ĩthĩwa ta nthwaia nga kana ndaatai nzamba ya mũika Ĩũlũ wa iĩma sya Mbetheli.'),
('kam', 'SNG', 3, 1, 'Ũtukũ nĩ ũkomonĩ wakwa Nĩmũmanthie ũla ngoo yakwa yendete: Nĩmũmanthie, ĩndĩ ndinamwona.'),
('kam', 'SNG', 3, 2, 'Nasya, nĩngũkĩla yu, na ngĩthi ngangange ndũanĩ; Nzĩanĩ nene na nzĩanĩ mbaamu Ngamũmantha ũla ngoo yakwa yendete: Namũmantha, ĩndĩ ndinamwona.'),
('kam', 'SNG', 3, 3, 'Asyaĩĩsya ala mangangaa ndũanĩ mambona; Kwa asu nameie, Nĩmwamwona ũla ngoo yakwa yendete?'),
('kam', 'SNG', 3, 4, 'Kwaĩ o kavinda kanini namatia, Yĩla namwonie ũla ngoo yakwa yendete: Namũkwatie, na ndyaamũeka athi, Kũvika namũete nyũmbanĩ ya inyia wakwa, Na kasũmbanĩ ka ũla wangitavie.'),
('kam', 'SNG', 3, 5, 'Nĩngũmũavĩthya, inyw’ĩ eĩtu ma Yelusaleme, Na nthwaia nga kana ndaatai nga sya kĩthekanĩ, Kana mũikamũthũlũmũe, kana kũmũamũkya mwendwa wakwa, Kũvika endeew’a.'),
('kam', 'SNG', 3, 6, 'Ũũ nũũ ũla wambatĩte kuma weũnĩ Ta ituĩ sya syũki, Anyungĩthĩtw’e nĩ manemane na ũvumba, Na mĩtĩ yonthe ya mũthoosya ĩla ĩnyungaa nesa?'),
('kam', 'SNG', 3, 7, 'Sisya, nĩ mũsekeseke wa Solomoni; Andũ mĩongo thanthatũ ngũmbaũ moothyũlũlũkĩte, Ma andũ ngũmbaũ sya Isilaeli.'),
('kam', 'SNG', 3, 8, 'Onthe nĩ akwati ma ũvyũ, na nĩ ai kaũnĩ: Kĩla mũndũ e na ũvyũ wake kĩnyunyunĩ kyake, Nũndũ wa w’ĩa ũtukũ.'),
('kam', 'SNG', 3, 9, 'Mũsumbĩ Solomoni eeseũvĩsya ĩsela ya kĩũsumbĩ Ya mũtĩ wa Levanoni.'),
('kam', 'SNG', 3, 10, 'Aseũvĩsya itũĩ syayo sya vetha, Ĩtina yayo ya thaavu, na wikalo wayo wa ngũa ĩtilyĩ ndune, Nthĩnĩ wayo vanakavĩtw’e na wendo, Waumĩte eĩtunĩ ma Yelusaleme.'),
('kam', 'SNG', 3, 11, 'Umaalai, inyw’ĩ eĩtu ma Saioni, na mũkyona mũsumbĩ Solomoni, E na ngovia ya ũsumbĩ ĩla inyia wake wamwĩkĩie Mũthenya wa kũtwaana kwake, Na mũthenya wa ũtanu wa ngoo yake.'),
('kam', 'SNG', 4, 1, 'Sisya, we wĩ mwanakavu, mwendwa wakwa; sisya, we wĩ mwanakavu; Metho maku nĩ ta ma mavũĩ ungu wa suka waku mũvũthũ wa ũthyũ. Nzw’ĩĩ syaku nĩ ta ndĩthya ya mbũi. Ila itindiaa mwaĩĩonĩ wa kĩĩma kya Ngileati.'),
('kam', 'SNG', 4, 2, 'Maeo maku matilyĩ ta ndĩthya ya malondu maka matilĩtwe maw’ĩa mĩtũkĩ, Ala mambatĩtw’e kuma kũthambw’a, Kĩla yĩmwe yamo yĩ na mavatha, Na vati yĩmwe katĩ wamo yaakw’ĩthya.'),
('kam', 'SNG', 4, 3, 'Ilomo syaku nĩ ta ũlii mũtune mũno, Na kanyw’a waku nĩ mwanake mũno. Nthĩa syaku itilyĩ ta kĩlungu kya ĩkũngũmanga Ungu wa suka waku mũvũthũ.'),
('kam', 'SNG', 4, 4, 'Ngingo yaku ĩtilyĩ ta mwako mũtũlu wa mũnyoolo wa Ndaviti Waakiwe nũndũ wa mĩio ya kaũ, Ũla wanĩkawa tũkalo ngili, Ngao syonthe sya ngũmbaũ.'),
('kam', 'SNG', 4, 5, 'Nondo syaku syelĩ nĩ ta maswii elĩ Ala nĩ mavatha ma nthwaia, Ala maĩsaa katĩ wa malaa ma lili.'),
('kam', 'SNG', 4, 6, 'Kũvika mũthenya ũusye, na myuunyĩ yalalĩle, Ngaenda kĩĩmanĩ kĩ manemane, Na kalĩmanĩ ke ũvumba.'),
('kam', 'SNG', 4, 7, 'We wĩ mwanakavu ki, mwendwa wakwa; Na vati kalanga nthĩnĩ waku.'),
('kam', 'SNG', 4, 8, 'Ũka tũendan’ye kuma Levanoni, mũtwawa wakwa, Wĩ nakwa kuma Levanoni: Sisya kuma mũtumbĩnĩ wa Amana, Kuma mĩtumbĩnĩ ya Senili na Elimoni, Kuma ngunganĩ sya mĩnyambũ, Kuma iĩmanĩ syĩ ngo.'),
('kam', 'SNG', 4, 9, 'We nĩwakũmbaĩthisye ngoo yakwa, mwĩĩtu‐a‐ia, mũtwawa wakwa; We nĩwakũmbaĩthisye ngoo yakwa na yĩmwe ya metho maku, Na mũnyoo ũmwe wa ngingo yaku.'),
('kam', 'SNG', 4, 10, 'Wendo waku ko nĩ mũseo, mwĩĩtu‐a‐ia, mũtwawa wakwa! Wendo waku ko wĩ kavaa kwĩ mbinyu! Na mũuke wa mauta maku kwĩ mĩthemba yonthe ya mĩtĩ ĩla ĩnyungaa nesa!'),
('kam', 'SNG', 4, 11, 'Ilomo syaku, we mũtwawa wakwa, ilovotangaa ta ĩwa: Ũkĩ wa nzũkĩ na ĩia syĩ ungu wa ũĩmĩ waku; Na mũuke wa ngũa syaku ũilyĩ ta mũuke wa Levanoni.'),
('kam', 'SNG', 4, 12, 'Mũũnda mwiie nĩ mwĩĩtu‐a‐ia, mũtwawa wakwa; Mbuluti mbiie, nthongo nziĩle.'),
('kam', 'SNG', 4, 13, 'Mathongooo maku nĩ mũũnda wa makũngamanga, wĩ ũsyao wĩ vata mũno; Mũena vamwe na mĩkenge ya mĩtĩ ĩla ĩseũvw’a manukato,'),
('kam', 'SNG', 4, 14, 'Manukato na manzano, Ithua na mũtalasini, na mĩtĩ yonthe ya ũvumba; Manemane na uuti, na mĩtĩ yonthe mĩseo ĩla ĩnyungaa nesa.'),
('kam', 'SNG', 4, 15, 'We wĩ nthongo ya mĩũnda, Kĩthima kya manzĩ ma thayũ, Na tũlũsĩ tũvĩtĩtye manzĩ kuma Levanoni.'),
('kam', 'SNG', 4, 16, 'Amũka, we kĩseve kya ngalĩ ya ĩũlũ; na ũkyũka we kya ngalĩ ya ĩtheo; Uutanĩai mũũnda wakwa, nĩ kana mĩtĩ ĩla ĩnyungaa nesa ĩtaavũke. Mwendwa wakwa nĩoke mũũndanĩ wake, Na kũya matunda make me vata mũno.'),
('kam', 'SNG', 5, 1, 'Nĩnooka mũũndanĩ wakwa, mwĩĩtu‐a‐ia, mũtwawa wakwa: Nĩnoomban’ya manemane makwa na mĩtĩ yakwa inyungaa nesa; Nĩnaĩsanĩsya ĩwa yakwa na ũkĩ wakwa wa nzũkĩ; Na nanyw’a mbinyu yakwa na ĩia yakwa. Yai, inyw’ĩ anyanyawa; Nyw’a, ĩĩ, nyw’a mũno, mwendwa wakwa.'),
('kam', 'SNG', 5, 2, 'Nĩĩ nĩnakoma, ĩndĩ ngoo yakwa nĩyĩĩamũkĩte: Nĩ wasya wa mwendwa wakwa ũla ũvingũasya, akyasya, Mbingũĩa, mwĩĩtu‐a‐ia, mwendwa wakwa, ĩvũĩ yakwa, ũtaavukw’a wakwa, Nũndũ mũtwe wakwa nĩusũĩte ĩmwe, O na nzw’ĩĩ syakwa mavoloto ma ũtukũ.'),
('kam', 'SNG', 5, 3, 'Nĩnumĩtye ngũa yakwa; nĩmĩkĩa ata? Nĩthambĩtye maũũ makwa; nĩmavukya ata?'),
('kam', 'SNG', 5, 4, 'Mwendwa wakwa ekĩie kw’oko kwake ĩimanĩ ya mũomo, Na ngoo yakwa nĩyakusĩkie nũndũ wake.'),
('kam', 'SNG', 5, 5, 'Nokĩlile kũvingũĩa mwendwa wakwa; Na moko makwa malovotangasya manemane, Na syaa syakwa manemane matweku, Ĩũlũ wa ikwati sya kĩvingi.'),
('kam', 'SNG', 5, 6, 'Navingũĩa mwendwa wakwa; Ĩndĩ mwendwa wakwa aĩ aneetulũla, na akathi. Ngoo yakwa nĩyanthelele yĩla waneenie: Nĩnamũmanthie, ĩndĩ ndyaatonya kũmwona; Namwĩta, ĩndĩ ndaanzũngĩa.'),
('kam', 'SNG', 5, 7, 'Asyaĩĩsya ala mangangaa ndũanĩ mambona, Mangũna, mambũkite; Asũvĩi ma maũvai mambuta suka wakwa.'),
('kam', 'SNG', 5, 8, 'Nĩngũmũavĩthya, eĩtu ma Yelusaleme, Ethĩwa mũkoona mwendwa wakwa, Kana mwĩmwĩa, atĩ nĩnĩwaĩtw’e nĩ wendo.'),
('kam', 'SNG', 5, 9, 'Mwendwa waku nũvĩtũkĩte ũngĩ wendawa ata, We ũla wĩ mwanakavu kũvĩtũka aka ala angĩ? Mwendwa waku nũvĩtũkĩte ũngĩ wendawa ata, Kana ũtũavĩthye ta ũu?'),
('kam', 'SNG', 5, 10, 'Mwendwa wakwa nĩ mweũ na mũtune, Mũnene mbee katĩ wa ngili ĩkũmi.'),
('kam', 'SNG', 5, 11, 'Mũtwe wake nĩ ta thaavu ũla mũseo mbee; Nzw’ĩĩ syake nĩ mbingĩ, na nziũ ta ngũngũũ.'),
('kam', 'SNG', 5, 12, 'Metho make matilyĩ ta ma mavũĩ me ũtee wa tũlũsĩ, Mathambĩtw’e na ĩia, na kwiwa nesa.'),
('kam', 'SNG', 5, 13, 'Matau make nĩ ta ĩvuĩo syĩ mĩtĩ ĩnyungaa nesa, Ta mĩthaĩĩo yĩ nyũnyi syĩ mũyo: Ilomo syake nĩ ta malaa ma lili, inyũlũlũkasya manemane matweku.'),
('kam', 'SNG', 5, 14, 'Moko make nĩ ta ngome sya thaavu syĩ na tũvila twa nzumalati ntheu tũlũmanĩtw’e iĩndĩnĩ syatw’o: Mwĩĩ wake nĩ ta maeo ma nzou manakavĩtw’e na tũvila twa savili.'),
('kam', 'SNG', 5, 15, 'Maũũ make nĩ ta ituĩ sya mavia maseo, me iĩndĩnĩ sya thaavu mũseo: Ũmbe wake ũtilyĩ Levanoni, mũseo mũno ta mĩkũũ.'),
('kam', 'SNG', 5, 16, 'Kanyw’a wake wĩ mũyo mũnene; Ĩĩ, nĩ mwanake ki. Ũũ nĩ mwendwa wakwa, na ũũ nĩ mũnyanyawa, Inyw’ĩ eĩtu ma Yelusaleme.'),
('kam', 'SNG', 6, 1, 'Mwendwa waku aendie kũ, We mwanakavu kũvĩtũka aka ala angĩ? Mwendwa waku ethyũũĩle va, Kana tũmũmanthe vamwe naku?'),
('kam', 'SNG', 6, 2, 'Mwendwa wakwa atheeie mũũndanĩ wake, Ivũĩonĩ syĩ mĩtĩ ĩla ĩnyungaa nesa, Kwĩĩthĩsya mĩũndanĩ, na kũmban’ya malaa ma lili.'),
('kam', 'SNG', 6, 3, 'Nyie nĩ wa mwendwa wakwa, na mwendwa wakwa nĩ wakwa: Eĩthya ndĩthya yake katĩ wa malaa ma lili.'),
('kam', 'SNG', 6, 4, 'We wĩ mwanakavu, mwendwa wakwa, ta Tilisa, Wa kwendeesya ta Yelusaleme, Wa kũtĩsya ta ita syĩ na ivevelo.'),
('kam', 'SNG', 6, 5, 'Thyũũa metho maku maikanzisye, Nũndũ nĩmeũngatha. Nzw’ĩĩ syaku nĩ ta ndĩthya ya mbũĩ, Ila itindiaa mwaĩĩonĩ wa Ngileati.'),
('kam', 'SNG', 6, 6, 'Maeo maku nĩ ta ndĩthya ya malondu maka, Ala mambatĩtw’e kuma kũthambw’a; Kĩla yĩmwe yamo yĩ na mavatha, Na vati yĩmwe katĩ wamo yaakw’ĩthya.'),
('kam', 'SNG', 6, 7, 'Nthia syaku itilyĩ ta kĩlungu kya ĩkũngũmanga Ungu wa suka waku mũvũthũ.'),
('kam', 'SNG', 6, 8, 'Ve aka asumbĩ mĩongo thanthatũ, na aka ngombo mĩongo nyanya, Na eĩtu atheu matatalĩka.'),
('kam', 'SNG', 6, 9, 'Ĩvũĩ yakwa, ũtaavukw’a wakwa, no ũmwe; No ũmwe wa inyia wake; Nowe weka mũnyuve wa ũla wamũsyaie. Eĩtu mamwona, na mamwĩta mũathimwa; Ĩĩ, aka asumbĩ na aka ngombo, na mamũtaĩa.'),
('kam', 'SNG', 6, 10, 'Nũũ ũla ũsiasya ta kũikya, Mwanakavu ta mwei, Mũtheu ta syũa, Wa kũtĩsya ta ita syĩ na ivevelo?'),
('kam', 'SNG', 6, 11, 'Natheea mũũndanĩ wa mĩtĩ ya mbatani, Kũsisya ũthithinĩu wa mĩkenge mwandanĩ, Kũsisya ethĩwa mũsavivũ wĩ wenze, Na mĩkũngũmanga ĩ na malaa.'),
('kam', 'SNG', 6, 12, 'Mbee wa ndanamba kũmanya, ngoo yakwa yambĩkalya Katĩ wa makasya ma andũ makwa anene.'),
('kam', 'SNG', 6, 13, 'Syoka, syoka, we Mũsulami; Syoka, syoka, nĩ kana tũkũsisye. Nĩkĩ mũkũmũsisya Mũsulami, Ta kũsisya mũsũngĩle wa Maanaimu?'),
('kam', 'SNG', 7, 1, 'A! Ũndũ maseũvĩte maũũ maku me iatũnĩ, we mwĩĩtu wa mũnene wĩ mbee ũsumbĩnĩ! Matako maku nĩ mavilingĩku ta tũvila twĩ thooa mũnene, Wĩa wa moko ma ndũĩka.'),
('kam', 'SNG', 7, 2, 'Mwĩĩ waku nĩ ta kĩkombe kĩvilingĩku, Kĩla nthĩnĩ wakyo mbinyu mbulan’ye ĩtanyivaa: Ĩvu yaku nĩ ta kĩvumbu kya nganũ Kĩthyũlũlũkĩtw’e na malaa ma lili.'),
('kam', 'SNG', 7, 3, 'Nondo syaku ilĩ itilyĩ ta maswii elĩ Mavatha ma nthwaia.'),
('kam', 'SNG', 7, 4, 'Ngingo yaku nĩ ta mwako mũtũlu wa mũnyoolo wa maeo ma nzou; Metho maku nĩ ta ndia ila syĩ Esivoni, Ũtee wa mbingĩlo ya Mbathi‐lavimi; Ĩnyiũũ yaku nĩ ta mwako mũtũlu wa mũnyoolo wa Levanoni Ũla welekele Ndamasiku.'),
('kam', 'SNG', 7, 5, 'Mũtwe waku nĩ ta kĩĩma kya Kalimeli, Na nzw’ĩĩ sya mũtwe waku itilyĩ ta ndune; Mũsumbĩ nũlũmĩtwe e mũtave mũvĩndĩlenĩ wasyo.'),
('kam', 'SNG', 7, 6, 'A! Ũndũ wanakavĩte na kwendeesya, Mwendwa, kwondũ wa kũtanĩthya!'),
('kam', 'SNG', 7, 7, 'Kĩũngamo kyaku nĩ ta kya mũtĩ wa mũtende, Na nondo syaku ta itũngo syaw’o.'),
('kam', 'SNG', 7, 8, 'Nasya, nĩngũlĩsa mũtĩ wa mũtende, Nĩngwĩkwatĩla mbonge syaw’o: Nondo syaku nĩsyĩthĩwe ta itũngo sya mũsavivũ, Na mũuke wa mĩthũmũ yaku ta wa ũsyao wa mũtĩ wa mũevo,'),
('kam', 'SNG', 7, 9, 'Na kanyw’a waku ta mbinyu ĩla nzeo mbee, Ĩla ĩmelekaa nesa kwondũ wa mwendwa wakwa, Ĩvĩtĩlaa mbola ilomonĩ sya ala makomete.'),
('kam', 'SNG', 7, 10, 'Nĩ wa mwendwa wakwa; Na kwenda kwake nĩkũmbelekele.'),
('kam', 'SNG', 7, 11, 'Ũka, mwendwa wakwa, tumaale mũũndanĩ; Tũkomele tũmĩsyĩ.'),
('kam', 'SNG', 7, 12, 'Twambate kĩoko tene mĩũndanĩ ya mĩsavivũ; Tũsisye ethĩwa mũsavivũ wĩ wenze, Na malaa maw’o nĩ malaũku, Na mĩkũngũmanga ĩ malaa: Vau ngakũnengea wendo wakwa.'),
('kam', 'SNG', 7, 13, 'Matunda ma kwendana mataavũkasya mũuke mũseo; Na mĩomonĩ yaitũ ve mĩthemba yonthe ya matunda me vata mũno ala meũ na ala ma tene, Ala nakwiĩe, we mwendwa wakwa.'),
('kam', 'SNG', 8, 1, 'A! Kethĩwa wĩthĩwa ta mwana‐a‐ia, Ũla wongie nondo sya mwaitũ! Yĩla nesa ũkũwĩla ũtee, ngakũmumunya; Ĩĩ, na kũti ũmwe wĩmbũthya.'),
('kam', 'SNG', 8, 2, 'Nĩthĩwa ngũtongoesya, na ũkũete nyũmbanĩ ya mwaitũ, Ũla wĩmanyĩsya; Nĩthĩwa ngũnyw’ĩthya mbinyu yĩ mũuke mũseo, Ya ngoyoo ya makũngũmanga makwa.'),
('kam', 'SNG', 8, 3, 'Kw’oko kwake kwa aka kwĩthĩwa ungu wa mũtwe wakwa, Na kw’oko kwake kwa aũme kwĩmbĩtĩĩsya.'),
('kam', 'SNG', 8, 4, 'Nĩngũmwĩavĩthya, inyw’ĩ eĩtu ma Yelusaleme, Kana mũtikathũlũmũe, kana kũmũamũkya mwendwa wakwa, Kũvika endeew’a.'),
('kam', 'SNG', 8, 5, 'Nũũ ũũ wambatĩte kuma weũnĩ, Eyaĩĩsye mwendwa wake? Ĩtina wa mũtĩ wa mũevo nĩnakũamũkisye: Vau nĩvo inyia waku wakwaũnyie, Vau nĩvo waũnyĩe ũla wakũsyaie.'),
('kam', 'SNG', 8, 6, 'Mbĩkĩa ta ũsiĩlũ ĩũlũ wa ngoo yaku, Ta ũsiĩlo ĩũlũ wa kw’oko kwaku: Nũndũ wendo wĩ vinya ta kĩkw’ũ; Kĩwĩu nĩ kyai ta Seoli; Itw’ĩki syakyo nĩ itw’ĩki sya mwaki, O kĩtw’ĩki ki kya mwaki wa Yeova.'),
('kam', 'SNG', 8, 7, 'Manzĩ maingĩ matitonya kũvosya wendo, O na kĩw’ũ kingĩ ki kũũthika: Ethĩwa mũndũ nũnengane syĩndũ syonthe sya nyũmba yake nũndũ wa wendo, Akavũthw’a vyũ.'),
('kam', 'SNG', 8, 8, 'Twĩ na mwĩĩtu‐a‐ia mũnini, Na nde nondo: Tũkeka ata ũndũ wa mwĩĩtu‐u‐ia Mũthenya ũla ũkevaw’a?'),
('kam', 'SNG', 8, 9, 'Kethĩwa nĩ ũvai, Tũmwakĩĩa nthongole ya vetha: Na kethĩwa nĩ mũomo, Tũkamwiiĩa na mbwaũ sya mĩkũũ.'),
('kam', 'SNG', 8, 10, 'Nyie nĩ ũvai, na nondo syakwa nĩ ta myako mĩtũlu ya mĩnyoolo yaw’o: Na ĩndĩ methonĩ make naĩ ta ũmwe ũla wonie mũuo.'),
('kam', 'SNG', 8, 11, 'Solomoni aĩ na mũũnda wa mĩsavivũ ku Mbaali‐amoni; Atiĩa mũũnda wa mũsavivũ asũvĩi; Kĩla ũmwe ũndũ wa ũsyao waw’o aĩ wa kũete ilungu sya vetha ngili.'),
('kam', 'SNG', 8, 12, 'Mũũnda wakwa wa mĩsavivũ, ũla wakwa, wĩ mbee wakwa: We, o we Solomoni, ũkeethĩwa na i ngili, Na ala masũvĩaa ũsyao waw’o makeethĩwa na maana elĩ.'),
('kam', 'SNG', 8, 13, 'We ũla ũtũaa mĩũndanĩ, Atindan’ya mĩmethukĩĩasya mew’e wasya waku: Tuma nakwa nĩwĩw’a.'),
('kam', 'SNG', 8, 14, 'Ĩkalaate, mwendwa wakwa, Na ĩthĩwa ta nthwaia nga kana ta ĩswii ya ndaatai Ĩũlũ wa iĩma syĩ mĩtĩ ĩla ĩnyungaa nesa.'),
('kam', 'ISA', 1, 1, 'Woni wa Isaia mwana wa Amosu, ũla wonie ũndũ wa Yuta na Yelusaleme, mĩthenya ya Usia, na Yothamu, na Aasu, na Esekia, asumbĩ ma Yuta.'),
('kam', 'ISA', 1, 2, 'Ĩw’ai, inyw’ĩ matu, na tea kũtũ, we nthĩ; nũndũ Yeova nũneenete: niniĩthĩtye syana na kũea, nasyo nimbaĩte matũ.'),
('kam', 'ISA', 1, 3, 'Ng’ombe nĩyĩsĩ mwene wayo, na ĩng’oi vandũ va kũĩthĩw’a nĩ vwana wayo; ĩndĩ Isilaeli ndesĩ, andũ makwa matisũanĩaa.'),
('kam', 'ISA', 1, 4, 'A! Mbaĩ mbathe, andũ ala makuĩte ũthũku, ũsyao wĩki wa naĩ, syana ila syĩkaa ũthũku! Nĩmamũtiĩte Yeova, nĩmamũvũthĩtye Ũla Mũtheu wa Isilaeli, nĩmevathĩte na kũsyoka na ĩtina.'),
('kam', 'ISA', 1, 5, 'Nũndũ wa kĩ mũũkũnangwa kũvika na yu, nĩ kana mũendeee na kũng’enda? Mũtwe w’onthe nĩ mũwau, na ngoo yonthe nĩ ndevu.'),
('kam', 'ISA', 1, 6, 'Kuma ũnyaĩĩ wa kũũ o na kũvika mũtwe vati vandũ vaima; no mawũkite, na maiĩsya, na makũna ma mĩtũkĩ: matyaatumwa, kana kwovwa, kana kwololow’a na mauta.'),
('kam', 'ISA', 1, 7, 'Nthĩ yenyu nĩ nthei; ndũa syenyu nivĩvĩtw’e na mwaki; aeni nĩmekũmina nthĩ yenyu mwene, na nĩ nthei, o ta ĩkulumanĩtw’e nĩ aeni.'),
('kam', 'ISA', 1, 8, 'Na mwĩĩtu wa Saioni nũtiĩtwe ta ĩlwanda mũũndanĩ wa mĩsavivũ, ta katũĩo mũũndanĩ wa mongũ, ta ndũa ĩtw’ĩkanĩw’e.'),
('kam', 'ISA', 1, 9, 'Keka Yeova wa nguthu watũtiĩe ũtialo mũnini mũno, twĩthĩwa tũilyĩ ta Sotomo, na kũvw’ananw’a na Ngomola.'),
('kam', 'ISA', 1, 10, 'Ĩthukĩĩsyei ndeto ya Yeova inyw’ĩ ala mũsumbĩkaa Sotomo; teai matũ mwĩw’e mĩao ya Ngai waitũ, inyw’ĩ andũ ma Ngomola.'),
('kam', 'ISA', 1, 11, 'Wingĩ wa nthembo syenyu ũmbaĩlĩte kyaũ? Easya ũu Yeova; nĩnĩkolete nthembo sya kũvĩvw’a sya ndũũme, na mathunya ma indo ila nou; na nditanĩaa nthakame ya tũsalũ twa mũew’a, kana tũtena twa malondu, kana nthenge.'),
('kam', 'ISA', 1, 12, 'Yĩla mũkaa kwĩyonan’ya mbee wakwa, nũũ ũla wendie ũu mokonĩ menyu, mũkinyangae nza syakwa?'),
('kam', 'ISA', 1, 13, 'Mũtikaete nthembo ingĩ sya mana; ũvani nĩ ũthatyo kwakwa; mwei mũtisu na savato, kũtw’a maũmbano‐nditonya ũthũku na ũmbano ũkilĩtye.'),
('kam', 'ISA', 1, 14, 'Ngoo yakwa nĩmenaa myei yenyu mĩtisu, na mboka syenyu ila itw’ĩtwe; nasyo nĩ mũio kwakwa; nĩnĩnoete nĩ kwikua.'),
('kam', 'ISA', 1, 15, 'Na yĩla mwĩtambũũkya moko menyu, ngavitha metho makwa ndikamwone; ĩĩ, yĩla mwĩvoya mboya mbingĩ, ndikethukĩĩsya: moko menyu nĩmausũĩte nthakame.'),
('kam', 'ISA', 1, 16, 'Thambai, ĩthesyei; vetai ũthũku wa meko menyu ndikawone na metho makwa; ekai kwĩka ũthũku;'),
('kam', 'ISA', 1, 17, 'ĩmanyĩsyei kwĩka nesa; manthai sila wa katĩ, mũtethyei ũla ũthĩnaw’a, masilanasyei ala makw’ĩĩwe nĩ aaĩthe, mũteteei mũndũ mũka ndiwa.'),
('kam', 'ISA', 1, 18, 'Ũkai yu, tũsũanĩe vamwe, easya ũu Yeova: o na ethĩwa naĩ syenyu nĩ ndune mũno, ikeethĩwa nzaũ ta ĩa; o na ethĩwa nĩ ndune ta mũkumbũ ikeethĩwa ta w’ĩa wa ĩlondu.'),
('kam', 'ISA', 1, 19, 'Ethĩwa mũkeetĩkĩla na kwĩw’a, mũkaĩsaa ũseo wa ĩ nthĩ:'),
('kam', 'ISA', 1, 20, 'ĩndĩ mwalea na kũng’enda, mũkaminwa na ũvyũ; nũndũ kanyw’a wa Yeova nũneenete ũu.'),
('kam', 'ISA', 1, 21, 'Kaĩ ndũa yĩ kĩthito nĩtw’ĩkĩte ĩlwaya! O ĩla yausũĩte ũsili wa katĩ! Ũlũngalu nĩwekalaa nthĩnĩ wayo, ĩndĩ yu no oaani.'),
('kam', 'ISA', 1, 22, 'Vetha waku nũtw’ĩkĩte makwaũ ma vetha, mbinyu yaku nĩvulanĩtw’e na manzĩ.'),
('kam', 'ISA', 1, 23, 'Ala maku me mbee ũsumbĩnĩ nĩ ang’endu, na atindan’ya ma ing’ei; kĩla mũndũ nĩwendaa mavaki, na nũatĩĩaa kũtuvwa: matisilanasya ala makw’ĩĩwe nĩ aaĩthe, o na vata wa mũndũmũka ndiwa ndũmavikĩaa.'),
('kam', 'ISA', 1, 24, 'Kwondũ wa ũu Mwĩaĩi, Yeova wa nguthu, Ũla Mwene Vinya wa Isilaeli, easya, A! Nĩngwĩvathana na nthũ syakwa, na kwĩĩvanĩsya kwa amaitha makwa;'),
('kam', 'ISA', 1, 25, 'na ngathyũũa kw’oko kwakwa kwĩthĩwe ĩũlũ waku, na kũthesya vyũ makwaũ maku, na kũveta matheũko maku;'),
('kam', 'ISA', 1, 26, 'na ngatũnga asili maku methĩwe ta ĩvinda ya mbee, na atai maku ta wambĩlĩlyonĩ: ĩtina wa ũu ũkeetwa Ndũa ya ũlũngalu, katũla ke kĩthito.'),
('kam', 'ISA', 1, 27, 'Saioni ĩkoovow’a na sila wa katĩ, na andũ mayo ala maalyũlile ngoo makoovow’a na ũlũngalu.'),
('kam', 'ISA', 1, 28, 'Ĩndĩ kwanangwa kwa avĩtan’ya na andũ athe kũkethĩwa ĩvinda yĩmwe, na ala mamũtiaa Yeova makaminwa.'),
('kam', 'ISA', 1, 29, 'Nũndũ makasonoka ũndũ wa mĩtĩ ya myaloni ĩla mwendie, mũkathokoanw’a ũndũ wa mĩũnda ĩla mũnyuvĩte.'),
('kam', 'ISA', 1, 30, 'Nũndũ mũkeethĩwa ta mwaloni ũla matũ maw’o mavovaa, na ta mũũnda ũte manzĩ.'),
('kam', 'ISA', 1, 31, 'Na ũla wĩ vinya akeethĩwa ta ngũno, na wĩa wake ta ngala ya mwaki; na akavya vamwe naw’o, na vaikethĩwa wa kũvosya.'),
('kam', 'ISA', 2, 1, 'Ndeto ĩla Isaia mwana wa Amosu wonie ũndũ wa Yuta na Yelusaleme.'),
('kam', 'ISA', 2, 2, 'Na kũkeethĩwa mĩthenya ya mũminũkĩlyo, kana kĩĩma kĩ nyũmba ya Yeova kĩkekalaa kĩ kĩtũlu kwĩ ila ingĩ, na kũkĩla ĩũlũ wa tũlĩma; na mbaĩ syonthe ikakĩendeaa.'),
('kam', 'ISA', 2, 3, 'Na ngo nyingĩ sya andũ ikaenda na kwasya, Ũkai inyw’ĩ, twambate kĩĩmanĩ kya Yeova, nyũmbanĩ ya Ngai wa Yakovo; nake akatũmanyĩsya nzĩa syake, na tũkaendaa nzĩanĩ syake: nũndũ mĩao ikauma Saioni, na ndeto ya Yeova ĩkauma Yelusaleme.'),
('kam', 'ISA', 2, 4, 'Na akasilan’ya mbaĩ, na kũtw’ĩĩa andũ ma ngo mbingĩ; na makatusya mbyũ syoo itw’ĩke mĩthya ya maembe ma ng’ombe, na matumo moo tũvyũ twĩ ngoto twa kũsea; mbaĩ ndĩkokĩlĩlya mbaĩ ũvyũ, o na itikemanyĩsya kaũ ĩngĩ.'),
('kam', 'ISA', 2, 5, 'Inyw’ĩ nyũmba ya Yakovo, ũkai, tũende kyeninĩ kya Yeova.'),
('kam', 'ISA', 2, 6, 'Nũndũ nũtiĩte andũ maku nyũmba ya Yakovo, nĩkwĩthĩwa nĩmausũĩtwe nĩ syĩthĩo ila syumĩte ngalĩ ya wumĩlonĩ wa syũa, nao nĩ ala mathanaa maũndũ ta Avilisiti, na nĩmakũnanĩaa kĩthalũ na syana sya andũ ma nthĩ ĩngĩ.'),
('kam', 'ISA', 2, 7, 'Na nthĩ yoo nĩyusũĩte vetha na thaavu, o na kũti mũminũkĩlyo wa mothwii moo maie; o na nthĩ yoo nĩyusũĩte mbalasi, o na kũti mũminũkĩlyo wa makasya moo ma kaũ.'),
('kam', 'ISA', 2, 8, 'O na nthĩ yoo nĩyusũĩte mĩvw’anano; nĩmathaithaa wĩa wa moko moo ene, ũla waseũviw’e nĩ syaa syoo.'),
('kam', 'ISA', 2, 9, 'Na mũndũ ũte nguma nũkwĩkunamya, na mũndũ mũnene nũkwĩnyivya: kwondũ wa ũu ndũkamaekee.'),
('kam', 'ISA', 2, 10, 'Lika ĩvianĩ, na ĩvithe kĩtoonĩ, kuma mbee wa ũtisyo wa Yeova, na ũtheu mũtisu wa ũnene wake.'),
('kam', 'ISA', 2, 11, 'Mũsyaĩlye wa ngathĩĩo wa mũndũ ũkanyivw’a, na wĩng’athĩlĩlyo wa andũ ũkatheew’a, na Yeova e weka akethĩwa mũnene mũthenya ũsu.'),
('kam', 'ISA', 2, 12, 'Nũndũ kũkeethĩwa mũthenya wa Yeova wa nguthu ũla wĩũkĩa kyonthe kĩla kĩ na ngathĩĩo na wĩng’athĩlĩlyo, na kyonthe kĩla kyũkĩlĩte; na kikatheew’a;'),
('kam', 'ISA', 2, 13, 'na ĩũlũ wa mĩkũũ yonthe ya Levanoni, ĩla mĩasa na mĩtũlu, na myaloni yonthe yĩ Mbasani'),
('kam', 'ISA', 2, 14, 'na ĩũlũ wa iĩma syonthe ndũlu, na tũlĩma tw’onthe tũtũlu,'),
('kam', 'ISA', 2, 15, 'na ĩũlũ wa kĩla mwako mũtũlu wa mũnyoolo, na kĩla ũvai mwiie,'),
('kam', 'ISA', 2, 16, 'na ĩũlũ wa ngalawa syonthe sya Talisisi, na mĩvw’anano yonthe yendeeasya.'),
('kam', 'ISA', 2, 17, 'Na wĩnenevyo wa mũndũ ũkanyivw’a, na wĩng’athĩlĩlyo wa andũ ũkatheew’a; na Yeova e weka akethĩwa mũnene mũthenya ũsu.'),
('kam', 'ISA', 2, 18, 'Na mĩvw’anano ĩkaaa vyũ.'),
('kam', 'ISA', 2, 19, 'Na andũ makalika ngunganĩ sya mavia, na maimanĩ ma nthĩ, maume mbee wa ũtĩsyo wa Yeova, na ũtheu mũtisu wa ũnene wake, yĩla wĩũkĩla athingithangye nthĩ na vinya.'),
('kam', 'ISA', 2, 20, 'Mũthenya ũsu andũ makekĩsya mbuko na mbuvu mĩvw’anano yoo ya vetha, na mĩvw’anano yoo ya thaavu, ĩla maseũvisye mamĩthaithae;'),
('kam', 'ISA', 2, 21, 'malike ngunganĩ sya mavia, na mĩvatĩnĩ ya mavia matũkangu, maume mbee wa ũtĩsyo wa Yeova, na ũtheu mũtisu wa ũnene wake, yĩla wĩũkĩla athingithangye nthĩ na vinya.'),
('kam', 'ISA', 2, 22, 'Taanĩsyai na mũndũ, ũla mĩthũmũ yake yĩ manyiũũnĩ make; nũndũ we atalawa kĩndũ ũndũnĩ wĩva?'),
('kam', 'ISA', 3, 1, 'Nũndũ, sisya, Mwĩaĩi, Yeova wa nguthu, nũnũũveta kumya Yelusaleme na Yuta wĩkwatyo na wĩlũmyo, wĩkwatyo w’onthe wa lĩu, na wĩkwatyo w’onthe wa manzĩ;'),
('kam', 'ISA', 3, 2, 'mũndũ wĩ ũtonyi, na mũndũ wa kũthi kaũnĩ; mũsili, na mwathani, na ũla ũaũasya, na mũtumĩa;'),
('kam', 'ISA', 3, 3, 'kavuteni wa andũ mĩongo ĩtano, na mũndũ wĩ ndaĩa, na mũtaani, na ndũĩka mbũĩ mũno, na ũla mũĩ wa kwathana na ndata.'),
('kam', 'ISA', 3, 4, 'Na ngatw’a syana syĩthĩwe anene moo me mbee ũsumbĩnĩ, na tũũkenge tũkamasumbĩka.'),
('kam', 'ISA', 3, 5, 'Na andũ makathĩnw’a, kĩla ũmwe nĩ ũla ũngĩ, na kĩla ũmwe nĩ mũtũi wake: kana kakeeng’athĩlĩlya kwa mũtumĩa, na ala me ĩtheo kwa ala me na ndaĩa.'),
('kam', 'ISA', 3, 6, 'Yĩla mũndũ ũkakwata mwana‐a‐inyia nyũmbanĩ ya ĩthe wake, akĩmwĩa, Wĩ na ngũa, tũsumbĩke, na ũvalũku ũũ wĩthĩwe ungu wa kw’oko kwaku;'),
('kam', 'ISA', 3, 7, 'mũthenya ũsu akookĩlya wasya wake, akyasya, Ndikethĩwa mũvosya; nũndũ nyũmbanĩ yakwa vati lĩu kana ngũa: mũtikandw’ĩkĩthye mũnene wa andũ.'),
('kam', 'ISA', 3, 8, 'Nũndũ Yelusaleme nĩ mbanangĩku, na Yuta nĩ mbalũku; nĩkwĩthĩwa nĩmĩ syoo na meko moo nĩmeũthĩn’ya Yeova, mathatye metho ma ũtheu mũtisu wake.'),
('kam', 'ISA', 3, 9, 'Kwoneka kwa mothyũ moo nĩkũũmakũsĩĩa; na nĩmekwonan’ya naĩ yoo ta Sotomo, matiũmĩvitha. Woo nĩ wa thayũ woo! Nĩkwĩthĩwa nĩmeyĩkĩte ũthũku.'),
('kam', 'ISA', 3, 10, 'Neenai ũndũ wa ũla mũlũngalu, atĩ kũkeethĩwa ũseo kwake; nĩkwĩthĩwa makaya ũsyao wa meko moo.'),
('kam', 'ISA', 3, 11, 'Woo nĩ wa ũla mũthũku! Kũkeethĩwa ũthũku kwake; nĩkwĩthĩwa o ũndũ moko make mekĩte now’o ũkekwa.'),
('kam', 'ISA', 3, 12, 'Ũndũ wa andũ makwa, syana nĩ anyamasya moo, na aka nĩmeũmasumbĩka. Inyw’ĩ andũ makwa, ala makũtongoeasya nĩmeũkũvĩtĩthya, na kwananga mũendele wa nzĩa syaku.'),
('kam', 'ISA', 3, 13, 'Yeova nĩwũkĩlĩte atetee, na nũũngeme asilĩle ngo sya andũ.'),
('kam', 'ISA', 3, 14, 'Yeova akalika silanĩ na atumĩa ma andũ make, na anene moo me mbee ũsumbĩnĩ: Nĩ inyw’ĩ ala mũĩte mũũnda wa mĩsavivũ; mbuta ila mũvutĩte ngya syĩ nyũmbanĩ syenyu:'),
('kam', 'ISA', 3, 15, 'nĩkĩ mũũvinyĩĩa andũ makwa, na kũthia mothyũ ma ngya? Easya ũu Mwĩaĩi, Yeova wa nguthu.'),
('kam', 'ISA', 3, 16, 'Na ĩngĩ Yeova asya, Nĩkwĩthĩwa eĩtu ma Saioni me na mĩng’athĩlĩlyo, na maendaa malũngĩte ngingo me na metho mausĩe ũlaalai, makĩtambũka matonete mbola, makĩkayĩthya nzili maũũnĩ;'),
('kam', 'ISA', 3, 17, 'kwondũ wa ũu Mwĩaĩi akaete ũwau wa ivala malolotyanĩ ma mĩtwe ya eĩtu ma Saioni, na Yeova akavua kũndũ kwoo kwĩ nthoni.'),
('kam', 'ISA', 3, 18, 'Mũthenya ũsu Mwĩaĩi akaveta ũseo wa nzili syoo, na ũlũalũĩ wa kwova nzw’ĩĩ, na mavuo;'),
('kam', 'ISA', 3, 19, 'na mĩnai, na itang’a, na ngũa sya kwĩkunĩkĩlya;'),
('kam', 'ISA', 3, 20, 'tũkovila twĩ wanake, na mĩthanga, na mĩsivi, na tũkusu twĩ kĩndũ kĩnyungaa nesa, na iawa;'),
('kam', 'ISA', 3, 21, 'ngome, na syĩndũ sya wanake sya kwĩkĩa manyiũũ;'),
('kam', 'ISA', 3, 22, 'ngũa sya kwĩkĩa yĩla kwĩ mboka, na makoti maasa, na masuka ma ũvw’ĩka mũtwe, na ngusu sya mbesa;'),
('kam', 'ISA', 3, 23, 'tũsisyo, na katane nzeo, na tũkutw’a, na masuka mavũthũ.'),
('kam', 'ISA', 3, 24, 'Na kũkeethĩwa, vandũ va mĩtĩ ĩnyungaa nesa vakeethĩwa wou; na vandũ wa mũsivi, ĩkanda; na vandũ va nzw’ĩĩ mbokothe, ũvaa; na vandũ va ngũa ndasa, ĩkunia ya kwĩvotoa; na kwowa kyoo vandũ va kwanakava.'),
('kam', 'ISA', 3, 25, 'Andũ maku makavalũkw’a na ũvyũ, o na ala maku me ũtonyi kaũnĩ.'),
('kam', 'ISA', 3, 26, 'Na mbingĩlo syake ikaĩa na kũmeta; nake akeethĩwa aeketwe na kwĩkala nthĩ.'),
('kam', 'ISA', 4, 1, 'Na aka mũonza makakwata mũndũ mũũme ũmwe mũthenya ũsu, makyasya, Tũkaĩsaa lĩu witũ ene, na kwĩvw’ĩkaa ngũa sitũ ene: ĩndĩ tũeke twĩtanĩaw’e na syĩtwa yaku; veta kũvũthw’a kwitũ.'),
('kam', 'ISA', 4, 2, 'Mũthenya ũsu ũvonge wa Yeova ũkethĩwa mwanakavu na wĩ na ndaĩa, na ũsyao wa nthĩ ũkethĩwa mũseo mũno na mwaĩlu kwondũ wa ala ma Isilaeli ala mavonokete.'),
('kam', 'ISA', 4, 3, 'Na kũkeethĩwa, o ũla wĩtiala Saioni, na ũla wĩtiwa Yelusaleme, akeetwa mũtheu, o kĩla ũmwe ũla ũandĩkĩtwe katĩ wa ala me thayũ Yelusaleme;'),
('kam', 'ISA', 4, 4, 'yĩla Mwĩaĩi ũkethĩwa athambĩtye ũvuku wa eĩtu ma Saioni, na kũthesya nthakame ya Yelusaleme yume nthĩnĩ wayo, kwondũ wa veva wa ũsili wa katĩ, na kwondũ wa veva wa kũvĩvya.'),
('kam', 'ISA', 4, 5, 'Yeova akatambũũkya ĩũlũ wa wĩkalo w’onthe wa kĩĩma kya Saioni, na ĩũlũ wa maũmbano makyo, mũumbĩ wa syũki mũthenya, na kũkena kwa kĩtw’ĩki kya mwaki ũtukũ; nũndũ kũkatambũũkw’a kĩla kya kũvw’ĩka ĩũlũ wa ũtheu mũtisu w’onthe.'),
('kam', 'ISA', 4, 6, 'Na vakeethĩwa ĩeema ũndũ wa muunyĩ mũthenya kwondũ wa muutĩa, na vandũ wa kũkĩĩa na kwĩvitha kwondũ wa kĩuutani na mbua.'),
('kam', 'ISA', 5, 1, 'Nĩnĩmwinĩe mwendwa wakwa wathi wa mwendwa wakwa ũndũ wa mũũnda wake wa mĩsavivũ. Mwendwa wakwa aĩ na mũũnda wa mĩsavivũ kĩĩmanĩ kĩnou mũno:'),
('kam', 'ISA', 5, 2, 'na awĩnza, na aumya mavia nthĩnĩ waw’o, na avanda mĩsavivũ mĩseo mũno, na aaka mwako mũtũlu wa mũnyoolo katĩ waw’o, o na enza katĩ waw’o kĩangĩo kya nzavivũ: na asyaĩĩsya ũsyae nzavivũ, na wasyaa nzavivũ sya kĩthekanĩ.'),
('kam', 'ISA', 5, 3, 'Na yu, inyw’ĩ mũtwĩe Yelusaleme na andũ ma Yuta, nĩngũmwĩsũva, tũsilan’yei nyie na mũũnda wakwa wa mĩsavivũ.'),
('kam', 'ISA', 5, 4, 'Nĩ ũndũ ũngĩ wĩva waĩ ũtonya kwĩkwa mũũndanĩ wakwa wa mĩsavivũ, ũla ndaawĩka? Nũndũ wa kĩ ĩndĩ, yĩla nasyaĩĩsye ũsyae nzavivũ, wasyaie nzavivũ sya kĩthekanĩ?'),
('kam', 'ISA', 5, 5, 'Na yu nĩngũmũtavya ũndũ nĩwĩka mũũnda wakwa wa mĩsavivũ: ngaveta wiio waw’o, na ũkalĩka; ngaomboanga ũvai waw’o, na ũkakinyangwa:'),
('kam', 'ISA', 5, 6, 'na ngootw’ĩkĩthya ĩei; ndũkasewa kana kũĩmwa; ĩndĩ ũkamesya mĩtae na mĩw’a: o na ngeeaĩa mathweo matikausye mbua ĩũlũ waw’o.'),
('kam', 'ISA', 5, 7, 'Nũndũ mũũnda wa mĩsavivũ wa Yeova wa nguthu nĩw’o nyũmba ya Isilaeli, na andũ ma Yuta nĩ mũkenge wake wa ũmwendeesya: nake nĩwamanthie sila wa katĩ, ĩndĩ, sisya, no thĩna; amantha ũlũngalu, ĩndĩ, sisya, no kĩĩo.'),
('kam', 'ISA', 5, 8, 'Woo nĩ wa ala mathengeanĩasya nyũmba na nyũmba, ala mathengeanĩasya mũũnda na mũũnda, mũvaka vati ũthei, na nĩmwĩkalĩtw’e mwĩ inyw’oka katĩ wa ĩ nthĩ!'),
('kam', 'ISA', 5, 9, 'Matũnĩ makwa Yeova wa nguthu easya atĩĩ, Nĩ w’o nyũmba nyingĩ ikeethĩwa nthei, o ila nene na nzeo, ite na mũndũ wa kũsyĩkala.'),
('kam', 'ISA', 5, 10, 'Nũndũ matambya maana ana ma mũũnda wa mĩsavivũ makasyaa vathi ĩmwe, na omeli ĩmwe ya mbeũ ĩkasyaa eva ĩmwe.'),
('kam', 'ISA', 5, 11, 'Woo nĩ wa ala mokĩlaa kĩoko tene, nĩ kana maatĩĩe kĩla kĩtoonasya; ala mekalaa kũvika ũtukũ katĩ, kũvika mbinyu ĩkwate mwaki nthĩnĩ woo!'),
('kam', 'ISA', 5, 12, 'Na mbeve na kananda, kathembe na mũtũlilũ, na mbinyu, syĩ mbokanĩ syoo; ĩndĩ matisyaĩĩasya wĩa wa Yeova, o na matiũsũanĩa wĩa wa moko make.'),
('kam', 'ISA', 5, 13, 'Kwondũ wa ũu andũ makwa nĩ aendu me atave kwondũ wa kũnyivĩwa nĩ ũmanyi; na andũ moo me ndaĩa me na nzaa, na ĩkomano yoo nĩyĩũnyalw’a nĩ waũni.'),
('kam', 'ISA', 5, 14, 'Kwondũ wa ũu Seoli nĩvanenevetye kwenda kwavo, na kwathamya kanyw’a wavo vate kũthima; na ũnene woo, na ĩkomano yoo, na kwĩtaĩa kwoo, na ũla ũtanaa katĩ woo, nĩmatheeaa nthĩnĩ wavo.'),
('kam', 'ISA', 5, 15, 'Na mũndũ ũte nguma nũnũũkunamw’a, na mũndũ mũnene nũnũũnyivw’a, na metho ma ala mekwĩng’athĩlĩlya nĩmeũsonoka:'),
('kam', 'ISA', 5, 16, 'ĩndĩ Yeova wa nguthu nũnũũtaĩwa kwondũ wa ũtw’ĩo wa sila wa katĩ, na Ngai Ũla Mũtheu nũkwonanw’a atĩ nĩ mũtheu ũlũngalunĩ.'),
('kam', 'ISA', 5, 17, 'Na ĩndĩ tũtena twa malondu tũkaĩthw’a o ta twĩ kĩsesinĩ kyatw’o, na kũndũ kwanangĩku kwa ala anou kũkaĩsawa nĩ angangi.'),
('kam', 'ISA', 5, 18, 'Woo nĩ wa ala makusasya ũthũku na ndii sya ũvũngũ, na kũkusya naĩ na ĩkanda ya ĩkasya;'),
('kam', 'ISA', 5, 19, 'ala maasya, Nĩekalaate, nĩethangaasye wĩanĩ wake, nĩ kana tũwone; na ũtao wa Ũla Mũtheu wa Isilaeli ũthengeee na kũka, nĩ kana tũmanye!'),
('kam', 'ISA', 5, 20, 'Woo nĩ wa ala metaa ũthũku ũseo, na ũseo ũthũku; ala mekĩaa kĩvindu vandũ va kyeni, na kyeni vandũ va kĩvindu; ala mekĩaa ũũ vandũ va mũyo, na mũyo vandũ va ũũ!'),
('kam', 'ISA', 5, 21, 'Woo nĩ wa ala meyonaa me kĩlĩko, na meyonaa me na ũmanyi!'),
('kam', 'ISA', 5, 22, 'Woo nĩ wa ala ai ma kũnyw’a mbinyu, na andũ me vinya ma kũvulan’ya kĩla kĩtoonasya;'),
('kam', 'ISA', 5, 23, 'ala kwondũ wa ĩvaki matalaa athũku atĩ nĩ alũngalu, na kũmũvena ũla mũlũngalu ũlũngalu wake!'),
('kam', 'ISA', 5, 24, 'Kwondũ wa ũu o tondũ ũmũĩ wa mwaki ũvĩvasya mavuthĩ, na tondũ nyeki nyũmũ ivalũkaa ũmũĩnĩ, now’o mĩi yoo ĩkethĩwa ta wou, na malaa moo makaũlũkw’a ta kĩtoo; nĩkwĩthĩwa nĩmaleete mĩao ya Yeova wa nguthu, na kũvũthya ndeto ya Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 5, 25, 'Kwondũ wa ũu ũthatu wa Yeova nũmakanĩe andũ make, nake nũmatambũũkĩĩtye kw’oko kwake, na kũmakũna; na iĩma nikũthingithanga, na simba syoo nĩ ta mavuthĩ nzĩanĩ nene katĩ. Ĩndĩ o na ũu w’onthe ũthatu wake ndũnathyũũwa, ĩndĩ kw’oko kwake nĩ kũtambũũku o na yu.'),
('kam', 'ISA', 5, 26, 'Nake akookĩlĩlya i mbaĩ kĩvevelo syĩ kũasa, na kũsyuĩsya kĩlũli kuma kĩtulu kya nthĩ; na, sisya, ikooka mĩtũkĩ isembete mũno.'),
('kam', 'ISA', 5, 27, 'Vai ũmwe katĩ woo ũkethĩwa na mĩnoo kana kũlulutĩka; vai ũmwe ũkombosya kana kũkoma; o na mĩsivi ya inyunyu syoo ndĩkaleela, kana tũmĩkwa twa iatũ syoo tũĩkatw’ĩka:'),
('kam', 'ISA', 5, 28, 'mauumu moo nĩ moĩ, na mata moo onthe nĩ makoote; mavũngũ ma mbalasi syoo makatalwa ta mavia momũ, na ndĩa syoo ta kĩlingi:'),
('kam', 'ISA', 5, 29, 'kũluma kwoo kũkethĩwa ta kũluma kwa mũnyambũ mũka, makaluma ta mĩnyambũ ya mũika; ĩĩ, makaluma, na kũkwata sya nzyĩma, na kũkua vate mũisyo, na vaikethĩwa ũmwe wa kũvonokya.'),
('kam', 'ISA', 5, 30, 'Na makamalitũkĩla mũthenya ũsu ta kĩlitũko kya ũkanga: na ethĩwa mũndũ akasisya nthĩ, sisya, no kĩvindu na thĩna; na kyeni nĩkĩkĩĩtwe kĩvindu nĩ mathweo maw’o.'),
('kam', 'ISA', 6, 1, 'Mwaka ũla mũsumbĩ Usia wakwie nyie nĩnoonie Mwĩaĩi ekalĩte kĩvĩlanĩ kya ũsumbĩ, kĩtũlu na kyũkĩlĩtw’e; na ngũa yake ya mũnyelele yausũĩte ĩkalũ.'),
('kam', 'ISA', 6, 2, 'Aselavi mekalaa vala ũĩ ĩũlũ: kĩla ũmwe aĩ na nthwau thanthatũ: avw’ĩka ũthyũ wake na ilĩ, na avw’ĩka maũũ make na ilĩ, na aũlũka na ilĩ.'),
('kam', 'ISA', 6, 3, 'Na kĩla ũmwe aneenanasya na ũla ũngĩ akyasya, Mũtheu, mũtheu, mũtheu, nĩ Yeova wa nguthu: nthĩ yonthe nĩyusũĩtwe nĩ ũtheu mũtisu wake.'),
('kam', 'ISA', 6, 4, 'Na myambĩlĩlyo ya myalyo yathingithangw’a nĩ wasya wa ũla waneenaa, na nyũmba yausũwa nĩ syũki.'),
('kam', 'ISA', 6, 5, 'Nĩvo ĩndĩ naisye, Woo nĩ wakwa! Nũndũ nĩnathela; nĩkwĩthĩwa nyie nĩ mũndũ wĩ ilomo ite ntheu, na nĩkalaa katĩ wa andũ me ilomo ite ntheu: nũndũ metho makwa nĩmonete Mũsumbĩ, Yeova wa nguthu.'),
('kam', 'ISA', 6, 6, 'Nĩvo ĩndĩ ũmwe wa aselavi wangũlũkĩle, e na ĩkaa ya mwaki kw’okonĩ kwake, yĩla wosie na mĩveto kumya kĩthembeonĩ:'),
('kam', 'ISA', 6, 7, 'na akiita kanyw’a wakwa nayo, na asya, Sisya, yĩĩ nĩyakiita ilomo syaku; na ũthũku waku nĩwavetwa, na naĩ yaku nĩyaekwa.'),
('kam', 'ISA', 6, 8, 'Nakwa neew’a wasya wa Mwĩaĩi, ũkyasya, Ngatũma ũũ, na nũũ wĩthi kwondũ witũ? Nĩvo naisye, Ninyioo; ndũma nyie.'),
('kam', 'ISA', 6, 9, 'Nake asya, Enda, ũtavye andũ aa, Kwĩw’a nĩmũkwĩw’a, ĩndĩ mũtiũmanya; kũsisya nĩmũkũsisya, ĩndĩ mũtikwona.'),
('kam', 'ISA', 6, 10, 'Tuma ngoo sya andũ aa syĩthĩwa na mathunya, na matũ moo matw’ĩkĩthye maito, na metho moo malalĩthye; maikese kwona na metho moo, na kwĩw’a na matũ moo, na kũmanya na ngoo syoo, na kwĩalyũla, na kũvow’a.'),
('kam', 'ISA', 6, 11, 'Nĩvo naisye, Mwĩaĩi, nĩ kũvika ĩndĩĩ? Na asũngĩa, Kũvika ndũa itw’ĩke maanzo ite mũndũ witwĩe, na nyũmba ite mũndũ, na nthĩ ĩthĩwe mbanangĩku vyũ,'),
('kam', 'ISA', 6, 12, 'na Yeova athamĩĩsya andũ kũasa, na kũndũ kũtie kwĩthĩwa kwingĩ katĩ wa ĩ nthĩ.'),
('kam', 'ISA', 6, 13, 'Na ethĩwa kũkatiala nthĩnĩ wayo kĩlungu kya ĩkũmi, o nakyo kĩkaĩwa: ta mũtĩ wa mwelo, na ta mũtĩ wa mwaloni, ĩla kĩtina kyayo kĩkalaa, yĩla ĩtemetwe; no ta ũu ũsyao mũtheu nĩ kĩtina kyayo.'),
('kam', 'ISA', 7, 1, 'Na kweethĩwa mĩthenya ya Aasu mwana wa Yothamu, mwana wa Usia, mũsumbĩ wa Yuta, nĩvo Lesini mũsumbĩ wa Silia, na Veka mwana wa Lemalia, mũsumbĩ wa Isilaeli, mambatie Yelusaleme mokite nayo, ĩndĩ matyaatonya kũmĩkĩlya vinya.'),
('kam', 'ISA', 7, 2, 'Na nyũmba ya Ndaviti yataviw’e, yeewa, Silia nĩyĩw’anĩte na Evalaimu. Na ngoo yake yatetema, o na ngoo ya andũ make, o tondũ mĩtĩ yĩ mũtitũnĩ ĩthingithangaw’a nĩ kĩseve.'),
('kam', 'ISA', 7, 3, 'Nĩvo ĩndĩ Yeova wamwĩie Isaia, Umaala yu wĩ na Sieali‐yasuvu mwana waku, mũkomanĩe na Aasu mũthyanĩ wa mũtaũ wa ndia yĩ ngalĩ ya ĩũlũ, lelũnĩ ũelete kĩsesinĩ kya mũthambya wa ngũa;'),
('kam', 'ISA', 7, 4, 'ũmwĩe, Ĩsũvĩe, noivindya; ndũkakĩe, o na ngoo yaku ndĩkaleele, nũndũ wa isithe isu ilĩ sya isinga syĩ syũki, nũndũ wa ũthatu mwai wa Lesini na Silia, na wa mwana wa Lemalia.'),
('kam', 'ISA', 7, 5, 'Nĩkwĩthĩwa Silia, na Evalaimu, na mwana wa Lemalia, nĩmasũanĩĩte ũkwĩka ũthũku, makyasya,'),
('kam', 'ISA', 7, 6, 'Twambatei tũkite na Yuta, na kũmĩthĩn’ya, na tũvũthũe vandũ vaitũ va ũlikĩla, na kũsumbĩkya mũsumbĩ katĩ wayo, o mwana wa Taveeli;'),
('kam', 'ISA', 7, 7, 'ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Ũndũ ũsu ndũkaũngama, o na ndũkethĩwa.'),
('kam', 'ISA', 7, 8, 'Nũndũ mũtwe wa Silia nĩ Ndamasiku, na mũtwe wa Ndamasiku nĩ Lesini; na ĩvinda ya myaka mĩongo thanthatũ na ĩtano Evalaimu akatilangwa tũlungu, o na ndakethĩwa mbaĩ:'),
('kam', 'ISA', 7, 9, 'na mũtwe wa Evalaimu nĩ Samalia, na mũtwe wa Samalia nĩ mwana wa Lemalia. Ethĩwa mũtikwĩtĩkĩla, vate ndĩi mũtikalũlũmĩlw’a.'),
('kam', 'ISA', 7, 10, 'Na Yeova aneena na Aasu ĩngĩ, akĩmwĩa,'),
('kam', 'ISA', 7, 11, 'Mwĩtye Yeova Ngai waku wonan’yo; ĩtya ũlikunĩ, kana ũtũlunĩ ĩũlũ.'),
('kam', 'ISA', 7, 12, 'Ĩndĩ Aasu asya, Ndiketya, o na ndikamũtata Yeova.'),
('kam', 'ISA', 7, 13, 'Nake asya, Ĩw’ai yu, inyw’ĩ nyũmba ya Ndaviti: Nĩ ũndũ ũnini kwenyu kũmanosya andũ, o na mũkanosya Ngai wakwa nake?'),
('kam', 'ISA', 7, 14, 'Kwondũ wa ũu Mwĩaĩi mwene akamũnenga wonan’yo: sisyai, mwĩĩtu mũtheu akaitava, na kũsyaa kavĩsĩ, nako syĩtwa yako akaketa Imanueli.'),
('kam', 'ISA', 7, 15, 'Kakaĩsaa mauta na ũkĩ wa nzũkĩ, kũvika yĩla kakamanya kũlea ũthũku, na kũnyuva ũseo.'),
('kam', 'ISA', 7, 16, 'Nũndũ kana kau katanamba kũmanya kũlea ũthũku, na kũnyuva ũseo, nthĩ ĩla asumbĩ elĩ mayo ũmathĩthaa, ĩkethĩwa ĩeketwe.'),
('kam', 'ISA', 7, 17, 'Yeova akaete ĩũlũ waku, na andũ maku, na nyũmba ya au, mĩthenya ĩla ĩtaamba kũka, kuma mũthenya ũla Evalaimu waumie katĩ wa Yuta — o mũsumbĩ wa Asuli.'),
('kam', 'ISA', 7, 18, 'Na kũkethĩwa mũthenya ũsu, Yeova akauĩsya ngi ila syĩ mĩthyanĩ ya mbũsĩ sya Misili, na nzũkĩ ila syĩ nthĩ ya Asuli.'),
('kam', 'ISA', 7, 19, 'Nasyo ikooka, na syonthe ikathũmũa myandanĩ mĩthei, na mĩvatĩnĩ ya mavia, na mbiionĩ syonthe syĩ mĩw’a, na isesinĩ syonthe.'),
('kam', 'ISA', 7, 20, 'Mũthenya ũsu Mwĩaĩi akeenza mũtwe na maw’ĩa ma maũũ na wenzi ũla wavoyie kũndũ kwĩ mũingo wa ũla Ũsĩ, naw’o nĩ mũsumbĩ wa Asuli; o na ũkamina kĩng’ew’a.'),
('kam', 'ISA', 7, 21, 'Na kũkethĩwa mũthenya ũsu, kana mũndũ akaĩthya moi, na malondu elĩ;'),
('kam', 'ISA', 7, 22, 'na kũkethĩwa, nũndũ wa wingĩ wa ĩia yasyo akaĩsaa mauta: nũndũ kĩla mũndũ ũla wĩtiwa katĩ wa ĩ nthĩ akaĩsaa mauta na ũkĩ wa nzũkĩ.'),
('kam', 'ISA', 7, 23, 'Na kũkethĩwa mũthenya ũsu, kĩla vandũ vala vaĩ mĩsavivũ ngili ya thooa wa sekeli ngili, vakethĩwa mĩtae na mĩw’a.'),
('kam', 'ISA', 7, 24, 'Mũndũ akaendaa kw’o na mĩsyĩ na ũta, nũndũ nthĩ yonthe ĩkethĩwa’mĩtae na mĩw’a.'),
('kam', 'ISA', 7, 25, 'Na tũlĩma tw’onthe tũla twenziwe na tũlembe, ndũkaenda kw’o nũndũ wa kũkĩa mĩtae na mĩw’a; ĩndĩ vakethĩwa vandũ va kũtwaĩa ng’ombe, na va kũkinyangĩthya malondu.'),
('kam', 'ISA', 8, 1, 'Na Yeova ambĩa, Ĩyosee kĩndũ kĩnene kya ũandĩkwa, ũandĩke ĩũlũ wakyo na kĩandĩki kya mũndũ, Kwondũ wa Maeli‐salali‐asi‐vasi;'),
('kam', 'ISA', 8, 2, 'na ngeeyosea ngũsĩ syĩ kĩthito sya kũandĩka, nasyo nĩ mũthembi Ulia, na Nzekalia mwana wa Yevelekia.'),
('kam', 'ISA', 8, 3, 'Na nalika kwa mwathani mũndũ mũka; nake aitava, na asyaa mwana. Nĩvo ĩndĩ Yeova wambĩie, Mwĩte syĩtwa yake Maeli‐salali‐asi‐vasi.'),
('kam', 'ISA', 8, 4, 'Nũndũ kana kau katanamba kwĩthĩwa na ũmanyi wa kwĩtana, Nau, na, Mwaitũ, mothwii ma Ndamasiku na mũtavo wa Samalia ũkatwawa mũsumbĩ wa Asuli ene na metho make.'),
('kam', 'ISA', 8, 5, 'Na Yeova aneena nakwa ĩngĩ, akyasya,'),
('kam', 'ISA', 8, 6, 'Nĩkwĩthĩwa andũ aa nĩmaleete manzĩ ma Siloa ala maendaa mbola, na matanĩaa Lesini na mwana wa Lemalia;'),
('kam', 'ISA', 8, 7, 'yu kwondũ wa ũu, sisya, Mwĩaĩi nũnũũmaetee manzĩ ma ũla Ũsĩ, me vinya na maingĩ, namo nĩ mũsumbĩ wa Asuli na ũnene wake w’onthe: na ũkausũa na kũvinga tũlũsĩnĩ twaw’o tw’onthe, na kũkĩla ngũka syaw’o syonthe;'),
('kam', 'ISA', 8, 8, 'na ũkavĩta na kũlika Yuta; ũkavinga na kũvĩta mũkuthũ; ũkavika o na ngingonĩ; na kũtambũũka kwa nthwau syaw’o kũkausũa ũthanthau wa nthĩ yaku, we Imanueli.'),
('kam', 'ISA', 8, 9, 'Ũkĩlyai kĩtuu, inyw’ĩ, ngo sya andũ, na tilĩkangaĩ tũlungu; na teai matũ, inyw’onthe ma nthĩ syĩ kũasa: ĩvotoei, na tilĩkangai tũlungu; ivotoei, na tilĩkangai tũlungu.'),
('kam', 'ISA', 8, 10, 'Sũanĩai vamwe, na ũndũ ũsu ũkaanangwa; neenai ndeto, nayo ndĩkalũma: nũndũ Ngai e vamwe naitũ.'),
('kam', 'ISA', 8, 11, 'Nũndũ Yeova ambĩie ndeto ii na kw’oko kwĩ vinya, na amanyĩsya ndikaende mũendelenĩ wa andũ aa, akyasya,'),
('kam', 'ISA', 8, 12, 'Mũtikasye, Nĩ wĩw’ano mũthũku, ũndũ wa w’onthe ũla andũ aa mekwasya, Nĩ wĩw’ano mũthũku; o na mũikakĩe kũtĩsya kwoo, kana kwĩthĩwa na w’ĩa.'),
('kam', 'ISA', 8, 13, 'Yeova wa nguthu, nĩwe mũkonan’ya atĩ nĩ mũtheu; nake nĩethĩwe kũkĩa kwenyu, na nĩethĩwe kũtelema kwenyu.'),
('kam', 'ISA', 8, 14, 'Nake akeethĩwa nĩwe vandu vatheu; ĩndĩ kwa nyũmba syelĩ sya Isilaeli akeethĩwa ĩvia ya ũtulya na ĩvia ĩnene ya ũlulutĩkya, akeethĩwa mũkwa na kĩtei kya ala matwĩe Yelusaleme.'),
('kam', 'ISA', 8, 15, 'Na aingĩ makakĩlulutĩkĩla na kũvalũka, na kũtũlĩka, na kũkwatw’a, na kũlũmw’a.'),
('kam', 'ISA', 8, 16, 'Ova ũkũsĩ, siĩla mĩao katĩ wa amanyĩw’a makwa.'),
('kam', 'ISA', 8, 17, 'Nakwa ngamweteela Yeova, ũla ũvithĩte nyũmba ya Yakovo ũthyũ wake, na ngamũsyaĩĩsya.'),
('kam', 'ISA', 8, 18, 'Sisya, nyie na syana ila Yeova ũnengete twĩ mawonan’yo na moseng’yo nthĩnĩ wa Isilaeli kuma kwa Yeova wa nguthu, ũla ũtwĩe kĩĩmanĩ kya Saioni.'),
('kam', 'ISA', 8, 19, 'Na yĩla makamwĩa, Endai kwa ala mesene na maveva na ala mombasya ithitũ, ala manyiilaa na kũmumungĩlya: andũ matyaĩle kũenda kwa Ngai woo? Nĩmaĩle kũendaa kwa ala akw’ũ ũndũ wa ala me thayũ?'),
('kam', 'ISA', 8, 20, 'Endai mĩaonĩ na ũkũsĩnĩ! Ethĩwa matineenaa kwĩanana na ndeto ĩno, vate ndĩi kũikesaa kwoo.'),
('kam', 'ISA', 8, 21, 'Na makavĩtĩla katĩ wa nthĩ, me athĩnu mũno na me na nzaa; na kũkeethĩwa, yĩla me na nzaa, makeenyamasya, na kũuma mũsumbĩ woo na Ngai woo, na kũng’elelya mothyũ moo ĩũlũ:'),
('kam', 'ISA', 8, 22, 'na makasisya nthĩ, na, sisya, no thĩna na kĩvindu, mũki wa woo; na makalũngw’a maende kĩvindunĩ kya ngokomi.'),
('kam', 'ISA', 9, 1, 'Ĩndĩ kũikethĩwa mũki kwa ũsu ũla waĩ na woo. Ivinda ĩvĩtu nĩwavũthasya nthĩ ya Nzevuluni na nthĩ ya Navitali; ĩndĩ ĩvinda ya ĩtina nũtaĩĩte, ngalĩ ya ũkanganĩ mũingo wa Yolotani, Kalilii ya i mbaĩ.'),
('kam', 'ISA', 9, 2, 'Andũ ala maendaa me kĩvindunĩ nĩmonete kyeni kĩnene: ala matwĩe nthĩ yĩ kyuu kya kĩkw’ũ, kyeni nĩkyamakenee.'),
('kam', 'ISA', 9, 3, 'Naku nĩwingĩvĩtye ĩ mbaĩ, nĩwongelete ũtanu wayo: nĩtanaa mbee waku o ta ũtanu wa ngethanĩ, o tondũ matanaa yĩla mekũaana mũtavo.'),
('kam', 'ISA', 9, 4, 'Nũndũ ũito wa ĩsoki yayo, na ndata ya kĩtuo kyayo, ndata ya mũthĩn’ya wayo, nũtũlĩte o ta mĩthenya ya Mitiani.'),
('kam', 'ISA', 9, 5, 'Nũndũ mĩio yonthe ya mũndũ ũla wĩkĩĩte mĩio ya kaũ kĩtuunĩ, na ngũa iindĩtwe nthakamenĩ, ĩkeethĩwa sya kũvĩvw’a, ngũ sya mwaki.'),
('kam', 'ISA', 9, 6, 'Nũndũ nĩkũsyaĩtwe kana kwondũ witũ, nĩtũnengetwe mwana mũndũ mũũme; na ũsumbĩko ũkeethĩwa kĩtuonĩ kyake: na syĩtwa yake akeetwa Ũseng’yo, Mũtai, Ngai Mwene Vinya, Ĩthe wa Tene na Tene, Mũnene wa Mũuo.'),
('kam', 'ISA', 9, 7, 'Wingĩvo wa ũsumbĩ wake na wa mũuo ndũkethĩwa na mũminũkĩlyo kĩvĩlanĩ kya ũsumbĩ kya Ndaviti, na ũsumbĩnĩ wake, kũlũlũmĩlya, na kũwĩkalya na sila wa katĩ na ũlũngalu kuma yu kũvika tene na tene. Kĩwĩu kya Yeova wa nguthu kĩkeanĩsya ũndũ ũũ.'),
('kam', 'ISA', 9, 8, 'Mwĩaĩi nĩwatũmie ndeto kwa Yakovo, na nĩyavikĩe Isilaeli.'),
('kam', 'ISA', 9, 9, 'Na andũ onthe makamanya, o na Evalaimu na ũla ũtwĩe Samalia, ala maneenaa na ngathĩĩo na vinya wa ngoo,'),
('kam', 'ISA', 9, 10, 'Mavali nĩ mavalũku, ĩndĩ tũkaaka na mavia masũvye; mĩkũyũ nĩ mĩteme, ĩndĩ tũkeekĩa mĩkũũ vandũ vayo.'),
('kam', 'ISA', 9, 11, 'Kwondũ wa ũu Yeova akamũkĩlĩlya nthũ sya Lesini, na kũingĩanĩsya amaitha make,'),
('kam', 'ISA', 9, 12, 'Asilia ngalĩko ya mbee, na Avilisiti ngalĩko ya ĩtina; na makaya Isilaeli na kanyw’a wathamĩtye. Ĩndĩ o na ũu w’onthe ũthatu wake ndwaalyũlwa, ĩndĩ kw’oko kwake nĩ kũtambũũku o na yu.'),
('kam', 'ISA', 9, 13, 'Ĩndĩ andũ matyaaĩthũũa na kũmwelekela ũla wamakũnie, o na matyaamantha Yeova wa nguthu.'),
('kam', 'ISA', 9, 14, 'Kwondũ wa ũu Yeova akatila Isilaeli mũtwe na kĩsithe, ĩthangũ ya mĩtende na malula, mũthenya o ũmwe.'),
('kam', 'ISA', 9, 15, 'Mũndũ mũkũũ wĩ ndaĩa, nĩwe mũtwe; na mwathani ũla ũmanyĩasya movũngũ, nĩwe kĩsithe.'),
('kam', 'ISA', 9, 16, 'Nũndũ ala matongoeasya andũ aa nĩo mamavĩtĩthasya; na ala matongoeaw’a nĩo manangawa.'),
('kam', 'ISA', 9, 17, 'Kwondũ wa ũu Mwĩaĩi ndakatanĩa anake moo, o na ndakew’ĩa tei ala moo makw’ĩĩwe nĩ aaĩthe na aka moo ndiwa; nũndũ kĩla ũmwe nĩ mũvuku na nĩ mwĩki wa naĩ, na kĩla kanyw’a nũneenaa ũtumanu. Ĩndĩ o na ũu w’onthe ũthatu wake ndwaalyũlwa, ĩndĩ kw’oko kwake nĩ kũtambũũku o na yu.'),
('kam', 'ISA', 9, 18, 'Nũndũ ũthũku nũvĩvasya ta mwaki; nũvĩvasya mĩtae na mĩw’a; ĩĩ, nũkwakana ikuthunĩ sya mũtitũ, na kwambata ta muumbĩ wa syũki.'),
('kam', 'ISA', 9, 19, 'Nthĩ nĩvĩvĩtwe vyũ ũndũ wa ũthilĩku wa Yeova wa nguthu; na andũ nĩ ta ngũ sya mwaki: vai mũndũ wĩmwĩw’ĩa tei mwana‐a‐inyia.'),
('kam', 'ISA', 9, 20, 'Na mũndũ akavenana ngalĩ ya kw’oko kwa aũme, na akeethĩwa na nzaa; na akaya ngalĩ ya kw’oko kwa aka, na matikavũna: makaya kĩla mũndũ nyama ya kw’oko kwake mwene:'),
('kam', 'ISA', 9, 21, 'Manase akaya Evalaimu; na Evalaimu, Manase; na me elĩ vamwe makamũkĩlĩla Yuta. Ĩndĩ o na ũu w’onthe ũthatu wake ndwaalyũlwa, ĩndĩ kw’oko kwake nĩ kũtambũũku o na yu.'),
('kam', 'ISA', 10, 1, 'Woo nĩ wa ala matusaa motw’ĩo mate malũngalu, na wa aandĩki ala maandĩkaa mong’endu;'),
('kam', 'ISA', 10, 2, 'masiĩĩe athĩni sila wa katĩ, na kũvuta ngya sya andũ makwa kĩla kyoo, nĩ kana aka ndiwa methĩwe mũtavo woo, na nĩ kana matw’ĩkĩthye ala makw’ĩĩwe nĩ aaĩthe mũtavo woo!'),
('kam', 'ISA', 10, 3, 'Inyw’ĩ mũkeeka ata mũthenya wa kũsilĩlwa, na wanangĩkonĩ ũla wĩũka kuma kũasa? Mũkakĩĩa kwa ũũ mwone ũtethyo? Na mũkatia ndaĩa yenyu va?'),
('kam', 'ISA', 10, 4, 'Nde vo nyie makeekunamya nthĩ ĩtheo wa ala ove, na kũvalũka ĩtheo wa ala oai. Ĩndĩ o na ũu w’onthe ũthatu wake ndwaalyũlwa, ĩndĩ kw’oko kwake nĩ kũtambũũku o na yu.'),
('kam', 'ISA', 10, 5, 'We Mũasuli, ndata ya ũthatu wakwa, ndata ĩla nthĩnĩ wa kw’oko kwaku ve kũthilĩka kwakwa!'),
('kam', 'ISA', 10, 6, 'Ngamũtũma okite na mbaĩ mbuku, na ngamwĩaĩa ũndũ wa andũ ma ũthilĩku wakwa, atave mũtavo, na ose sya mbuta, na kũmakinyanga ta ndaka nzĩanĩ nene.'),
('kam', 'ISA', 10, 7, 'Ĩndĩ ndeĩsĩ ũu, o na ngoo yake ndĩũsũanĩaa ũu; ĩndĩ ngoonĩ yake kwĩ ũvoo wa kwananga, na kũveta mbaĩ mbingĩ.'),
('kam', 'ISA', 10, 8, 'Nũndũ easya, Anene makwa onthe me mbee ũsumbĩnĩ ti asumbĩ?'),
('kam', 'ISA', 10, 9, 'Kalino ti ta Kalikemisi? Amathi ti ta Alivati? Samalia ti ta Ndamasiku?'),
('kam', 'ISA', 10, 10, 'Tondũ kw’oko kwakwa kwonete mosumbĩ ma mĩvw’anano, ala mĩvw’anano yamo myasũvye nĩvĩtũkĩte ĩla ya Yelusaleme na ya Samalia;'),
('kam', 'ISA', 10, 11, 'ndikeka Yelusaleme na mĩvw’anano yayo o tondũ neekie Samalia na mĩvw’anano yayo?'),
('kam', 'ISA', 10, 12, 'Kwondũ wa ũu kũkeethĩwa, kana, o yĩla Mwĩaĩi ũkethĩwa aminĩte wĩa wake w’onthe kĩĩmanĩ kya Saioni na Yelusaleme, nyie ngakũna ũsyao wa ngoo yĩ vinya ya mũsumbĩ wa Asuli, na ũnene wa mũsyaĩlye wa mĩng’athĩlĩlyo.'),
('kam', 'ISA', 10, 13, 'Nũndũ nũneenete, Kwondũ wa vinya wa kw’oko kwakwa nĩnĩkĩte ũu, na kwondũ wa ũĩ wakwa; nũndũ nĩ na ũmanyi: na nĩnĩthamĩtye mĩvaka ya ngo sya andũ, na kũtava mothwii moo maie, na ta mũndũ ngũmbaũ nĩnĩtheeetye ala mekalaa ivĩlanĩ sya ũsumbĩ:'),
('kam', 'ISA', 10, 14, 'na kw’oko kwakwa nĩkwonete mothwii na ngo sya andũ ta ndala; na tondũ mũndũ wũmbanasya matumbĩ ala matiĩtwe, now’o nũmbanĩtye nthĩ yonthe: na vatyaĩ ũmwe ũla waavaalalya ũthwau, kana kwathamya kanyw’a, kana kũnyiila.'),
('kam', 'ISA', 10, 15, 'Ĩthoka yĩkamwĩkathĩĩĩa ũla ũtemaa nayo? Ĩng’weli yĩkamwĩnenevesya ũla ũtethasya wĩa nayo? Nĩ ta kwasya ndata ĩkatethya wĩa na ala mamyũkĩlasya, kana ndata ĩkamũkĩlya mwene nake ti mũtĩ.'),
('kam', 'ISA', 10, 16, 'Kwondũ wa ũu Mwĩaĩi, Yeova wa nguthu, akamaetee ala anou make ũmosu; na ĩtheo wa ũnene wake kũkakanw’a yekethe ta yekethe ya mwaki.'),
('kam', 'ISA', 10, 17, 'Na kyeni kya Isilaeli kĩkeethĩwa mwaki, na Ũla Mũtheu wake akeethĩwa ũmũĩ wa mwaki; na ũkavĩvya na kũmina mĩw’a yake na mĩtae yake mũthenya ũmwe.'),
('kam', 'ISA', 10, 18, 'Nake akamina ndaĩa ya mũtitũ wake, na ya mũũnda wake ũla ũsyaaa mũno, thayũ na mwĩĩ vamwe: na kũkeethĩwa kũilyĩ ta yĩla mũkui wa kĩvevelo ũnyalaa.'),
('kam', 'ISA', 10, 19, 'Na mĩtĩ ya mũtitũ wake ĩla yĩtiala ĩkeethĩwa ĩte mingĩ, ũndũ kana katonya kũandika ũtalo wayo.'),
('kam', 'ISA', 10, 20, 'Na kũkethĩwa mũthenya ũsu, atĩ ũtialo wa Isilaeli, na ala avonoku ma nyũmba ya Yakovo, matikamwĩkwatya ĩngĩ ũla wamakũnie, ĩndĩ makamwĩkwatya Yeova, Ũla Mũtheu wa Isilaeli, na w’o.'),
('kam', 'ISA', 10, 21, 'Ũtialo, naw’o nĩ ũtialo wa Yakovo, ũkamũsyokea Ngai ũla wĩ vinya.'),
('kam', 'ISA', 10, 22, 'O na kau andũ maku, Isilaeli, nĩ aingĩ ta kĩthangathĩ kya ũkanga, no ũtialo woo ũkasyoka: wanangĩko nũtw’ĩtwe, wusũĩte ũlũngalu.'),
('kam', 'ISA', 10, 23, 'Nũndũ wĩanĩu wa wanango, naw’o nĩ ũla ũtw’ĩtwe, Mwĩaĩi, Yeova wa nguthu, akawĩanĩsya katĩ wa nthĩ yonthe.'),
('kam', 'ISA', 10, 24, 'Kwondũ wa ũu Mwĩaĩi, Yeova wa nguthu, easya atĩĩ, Inyw’ĩ andũ makwa ala mũtwĩe Saioni, mũtikakĩe Mũasuli, o na ethĩwa emũkũna na ndata, na ũmũkĩlĩlya ndata yake, o tondũ kweekiwe Misili.'),
('kam', 'ISA', 10, 25, 'Nũndũ no kavinda kanini mũno, na ũthilĩku ĩũlũ waku ũkeanĩw’a, na ũthatu wakwa ũkamũvikĩa anangwe.'),
('kam', 'ISA', 10, 26, 'Na Yeova wa nguthu akamũkĩlĩlya mũsalisa, o tondũ kweekiwe kũawanĩ kwa Mitiani ĩvianĩ ya Olevi: na ndata yake ĩkeethĩwa ĩũlũ wa ũkanga, na akamyũkĩlya o tondũ kweekiwe Misili.'),
('kam', 'ISA', 10, 27, 'Na kũkethĩwa mũthenya ũsu, mũio wake ũkauma kĩtuonĩ kyaku, na ĩsoki yake yĩkauma ngingonĩ yaku, na ĩsoki yĩkaanangwa kwondũ wa ũnou.'),
('kam', 'ISA', 10, 28, 'Nũvikĩte Aiathi, nũvĩtĩle Mikiloni katĩ; nĩwiĩte mĩio yake ku Mikimasi;'),
('kam', 'ISA', 10, 29, 'nĩmakĩlĩle ũingĩloni; nĩmatw’ĩkĩthĩtye Ngeva vandũ voo va ũkoma; Lama nĩnĩũtetema; Ngivea ya Saulo nĩkĩĩte.'),
('kam', 'ISA', 10, 30, 'Ua mbu na wasya waku, we mwĩĩtu wa Ngalimu! Ĩthukĩĩsye, we Laisa! We Anathothi ya kũmakĩwa!'),
('kam', 'ISA', 10, 31, 'Matimena nĩ mũkĩi; ala matwĩe Ngevimu nĩmeũkĩĩa vandũ vate mũisyo.'),
('kam', 'ISA', 10, 32, 'Mũnthĩ ũũ akaũngama ku Novu: nũnũũkĩtukangĩa kw’oko kwake kĩĩma kya mwĩĩtu wa Saioni, nakyo nĩ kĩĩma kya Yelusaleme.'),
('kam', 'ISA', 10, 33, 'Sisya, Mwĩaĩi, Yeova wa nguthu, akatema mbonge na wai: na ala aasa makavalũkw’a, na ala me na wĩng’athĩlĩlyo makatheew’a.'),
('kam', 'ISA', 10, 34, 'Na akatema ikuthu syĩ mũtitũnĩ na kĩaa, na Levanoni ĩkavalũkw’a nĩ ũla wĩ ũtonyi.'),
('kam', 'ISA', 11, 1, 'Na kũkathongooa nthongooo kuma kĩtinanĩ kya Yese, na ũvonge kuma mĩinĩ yake ũkasyaa ũsyao.'),
('kam', 'ISA', 11, 2, 'Na Veva wa Yeova nũkekalaa ĩũlũ wake, veva wa ũĩ na ũmanyi, veva wa ũtao na vinya, veva wa kũmanya na wa kũmũkĩa Yeova.'),
('kam', 'ISA', 11, 3, 'Kwendeew’a kwake kũkethĩawa nthĩnĩ wa kũmũkĩa Yeova; na ndakasila kwĩanana na kwona kwa metho make, kana kũtw’a kwĩanana na kwĩw’a kwa matũ make;'),
('kam', 'ISA', 11, 4, 'ĩndĩ nũkasilĩlaa ngya na ũlũngalu, na kũmatusĩaa ala auu ma nthĩ katĩ; na nũkakũnaa nthĩ na ndata ya kanyw’a wake; na nũkoaaa ala athũku na mĩthũmũ ya ilomo syake'),
('kam', 'ISA', 11, 5, 'Na ũlũngalu ũkethĩawa mũsivi wa kwĩvotoa kwake, na kĩthito mũsivi wa kĩnyunyu kyake.'),
('kam', 'ISA', 11, 6, 'Na nzũi nĩkekalanasya na katena ka ĩlondu, na ngo nĩkatindianĩaa na katena ka mbũi; na kasaũ ka ng’ombe na mũnyambũ wa mũika na ng’ombe nou vamwe; na kana kanini nĩkakaitongoeasya.'),
('kam', 'ISA', 11, 7, 'Na ng’ombe na nduva nikaĩsanĩaa vamwe; tũsaũ twasyo tũkatindiaa vamwe; mũnyambũ nũkaĩsaa nyeki ta ng’ombe.'),
('kam', 'ISA', 11, 8, 'Na kana kekwonga nĩkakathaũkĩaa vala ve ĩima ya kĩko, na kana kaaĩu nĩkakekĩaa kw’oko kwako ĩĩmanĩ ya kĩmbuva.'),
('kam', 'ISA', 11, 9, 'Kũtikew’anĩthw’a woo kana kwanangana kĩĩmanĩ kyakwa kyonthe kĩtheu; nũndũ nthĩ ĩkausũw’a nĩ kũmũmanya Yeova, o tondũ manzĩ mekunĩkĩlye ũkanga.'),
('kam', 'ISA', 11, 10, 'Na kũkethĩwa mũthenya ũsu, kĩtina kya Yese, kĩla kĩũngamaa kĩthĩwe kĩvevelo kya ngo sya andũ, mbaĩ ikamũmantha; na vandũ vake va ũthũmũa vakethĩwa va ndaĩa.'),
('kam', 'ISA', 11, 11, 'Na kũkethĩwa mũthenya ũsu, Yeova nũkatambũũkya kw’oko kwake ĩvinda ya kelĩ atũnge ũtialo wa andũ make ala makatiala, kuma nthĩ ya Asuli, na Misili, na Vathilosi, na Kusi, na Elamu, na Sinali, na Amathi, na ithamanĩ sya ũkanga.'),
('kam', 'ISA', 11, 12, 'Na nũkokĩlya kĩvevelo ũndũ wa mbaĩ, na kũmban’ya alũngw’a ma Isilaeli, na kũmban’ya vamwe ala anyaĩĩku ma Yuta kuma ikotonĩ inya sya nthĩ.'),
('kam', 'ISA', 11, 13, 'O na kĩwĩu kya Evalaimu nĩkĩkathela, na ala mathĩnasya Yuta nĩmakavetwa: Evalaimu ndakamwĩw’ĩa Yuta kĩwĩu, na Yuta ndakamũthĩn’ya Evalaimu.'),
('kam', 'ISA', 11, 14, 'Na nĩmakaũlũka mavuĩle ituonĩ sya Avilisiti ũthũĩlonĩ wa syũa; me vamwe makavuta ana ma wumĩlonĩ wa syũa: nĩmakatambũũkĩsya Etomu na Moavi kw’oko kwoo; na ana ma Amimoni nĩmakamew’a.'),
('kam', 'ISA', 11, 15, 'Na Yeova nũkananga vyũ ũĩmĩ wa ũkanga wa Misili; na e na kĩseve kyake kĩla kĩvĩvasya nũkatukangĩa kw’oko kwake ũla Ũsĩ, na kũkũna ũtw’ĩke tũlũsĩ mũonza, na kũvĩtĩlya andũ iatũ iteũkinya manzĩ.'),
('kam', 'ISA', 11, 16, 'Na nĩkũkethĩwa lelũ kwondũ wa ũtialo wa andũ make, ala makatiala, kuma nthĩ ya Asuli; o tondũ kwailyĩ kwondũ wa Isilaeli mũthenya ũla waumie nthĩ ya Misili.'),
('kam', 'ISA', 12, 1, 'Na mũthenya ũsu nũkasya, Ngakũtũngĩa mũvea, ame Yeova; o na kau waĩ ũnanthatĩa, ũthatu waku nũalyũlĩte, naku nũũngiakisya.'),
('kam', 'ISA', 12, 2, 'Sisya, Ngai nĩ ũtangĩĩo wakwa; ngaĩkĩĩa, na ndikakĩa: nũndũ Yeova, o Yeova, nĩ vinya wakwa na wathi wakwa; nake nũtw’ĩkĩte ũtangĩĩo wakwa.'),
('kam', 'ISA', 12, 3, 'Kwondũ wa ũu mũkatava manzĩ na ũtanu ithimanĩ sya ũtangĩĩo.'),
('kam', 'ISA', 12, 4, 'Na mũthenya ũsu nĩmũkasya, Tũngĩai Yeova mũvea, ĩkaĩlei syĩtwa yake, tavan’yai meko make katĩ wa andũ, wetai kana syĩtwa yake nĩyĩũnenevw’a.'),
('kam', 'ISA', 12, 5, 'Mũkumyei Yeova; nũndũ nĩwĩkĩte maũndũ manene: ũu ũmanyĩke nthĩ yonthe.'),
('kam', 'ISA', 12, 6, 'Neena mũno, ũkĩlya wasya mũnene, we Ũla ũtwĩe Saioni; nũndũ Ũla Mũtheu wa Isilaeli nĩ mũnene katĩ waku.'),
('kam', 'ISA', 13, 1, 'Ndeto ngito ũndũ wa Mbaviloni, ĩla Isaia mwana wa Amosu wonie.'),
('kam', 'ISA', 13, 2, 'Ũngamyai kĩvevelo kĩĩmanĩ kĩthei, mokĩlĩlyei wasya, onenelyai na kw’oko, nĩ kana malike mbingĩlonĩ sya ala anene me ndaĩa.'),
('kam', 'ISA', 13, 3, 'Nĩnĩmeaĩe andũ makwa ala mavathanĩtw’e, ĩĩ, nĩnĩmetĩte ngũmbaũ syakwa kwondũ wa kwĩanĩsya ũthatu wakwa, o makwa ala metaĩaa makĩkathĩĩa.'),
('kam', 'ISA', 13, 4, 'Kĩlonzo kya nguthu iĩmanĩ, o ta kya andũ aingĩ! Kĩlonzo kya kĩtuu kya mosumbĩ ma i mbaĩ syũmbanĩte vamwe! Yeova wa nguthu nũkũmban’ya nguthu ũndũ wa kaũ.'),
('kam', 'ISA', 13, 5, 'Nĩmaumĩte nthĩ ĩ kũasa, kuma kĩtulu kya ĩtu, o Yeova, na mĩio ya kaũ ya ũthatu wake, kwananga nthĩ yonthe.'),
('kam', 'ISA', 13, 6, 'Metai: nũndũ mũthenya wa Yeova nĩ mũthengeeu, ũkooka ta wanangĩko wumĩte kwa Mwene Vinya W’onthe.'),
('kam', 'ISA', 13, 7, 'Kwondũ wa ũu moko onthe makeethĩwa maleelu, na kĩla ngoo ya mũndũ ĩkatweka:'),
('kam', 'ISA', 13, 8, 'na makateva; makakwatwa nĩ mawoo na imako; makeethĩwa na woo ta mũndũ mũka akyaũnya: makasyan’ya na ũseng’yo; mothyũ moo makeethĩwa mothyũ ma ũmũĩ wa mwaki.'),
('kam', 'ISA', 13, 9, 'Sisya, mũthenya wa Yeova nĩwũkĩte, mwai, wĩ na ũthilĩku na ũthatu mwai; ũtw’ĩkĩthye nthĩ nthei, na kwananga ala athe mayo mamyume.'),
('kam', 'ISA', 13, 10, 'Nũndũ ndata sya ĩtunĩ na syeni syavo itikaumya kyeni kyasyo; syũa yĩkaya kĩvindu yĩkyuma, na mwei ndũkaumya kyeni kyaw’o.'),
('kam', 'ISA', 13, 11, 'Na ngakũna nthĩ ũndũ wa ũthũku, na ala athũku ũndũ wa ũthũku woo: na ngamina ngathĩĩo ya ekathĩĩi, na ngatheesya wĩng’athĩlĩlyo wa ala ma kũtĩsya.'),
('kam', 'ISA', 13, 12, 'Ngatw’ĩkĩthya mũndũ ethĩwe vata mũno kwĩ thaavu mũseo, o mũndũ kwĩ thaavu mũtheu wa Ovilu.'),
('kam', 'ISA', 13, 13, 'Kwondũ wa ũu ngatetemya matu, na nthĩ ĩkathingithangw’a yume vandũ vayo, kũthilĩkanĩ kwa Yeova wa nguthu, na mũthenya wa ũthatu wake mwai.'),
('kam', 'ISA', 13, 14, 'Na kũkeethĩwa, o ta nthwaia nga ĩlũngĩtw’e, na ta malondu ala mate mũndũ o na wĩva wa kũmatũngĩanĩa, makaalũka kĩla mũndũ kwa andũ make, na makakĩa kĩla mũndũ aende nthĩ yake mwene.'),
('kam', 'ISA', 13, 15, 'Kĩla mũndũ wĩoneka akatonywa mũkuthũ; na kĩla mũndũ wĩkwatwa akavalũkw’a na ũvyũ.'),
('kam', 'ISA', 13, 16, 'Na tũũkenge twoo tũkang’atang’anw’a tũtilĩkange tũlungu mene na metho moo; nyũmba syoo ikatavwa mĩio, na iveti syoo ikakindwa.'),
('kam', 'ISA', 13, 17, 'Sisya, ngamokĩlĩlya Ametia, ala matakasisya vetha, o na thaavu matikendeew’a nĩw’o.'),
('kam', 'ISA', 13, 18, 'Na mata moo makavalũkya anake mavevenzeke; na matikawĩw’ĩa tei ũsyao wa ĩvu; metho moo matikaeka syana.'),
('kam', 'ISA', 13, 19, 'Na Mbaviloni, ndaia ya mosumbĩ, ũseo wa ngathĩĩo ya Akalitei, ĩkeethĩwa ĩilyĩ ta yĩla Ngai wang’uthũlangile Sotomo na Ngomola.'),
('kam', 'ISA', 13, 20, 'Ndĩkatũwa nĩ andũ o na ĩndĩĩ, o na ndĩkekalwa kuma nzyawa na nzyawa: o na Mwalavu ndakamba ĩeema kw’o; o na aĩthi maikatindisya ndĩthya syoo sya mbũi na malondu kw’o.'),
('kam', 'ISA', 13, 21, 'Ĩndĩ nyamũ mbai sya weũnĩ ikatindiaa kw’o; na nyũmba syoo ikausũa nyamũ ila syĩ wasya wa kũtĩsya; na nyaa ikekalaa kw’o, na mbũi sya kĩthekanĩ ĩkatũvanasya kw’o.'),
('kam', 'ISA', 13, 22, 'Na nzũĩ ikakũmĩaa nyũmbanĩ syoo nene syĩ kĩemo, na mbĩwa nyũmbanĩ nene mbanakavye sya kwendeesya: na ĩvinda yayo nĩ ĩthengeeu, na mĩthenya yayo ndĩkongeleka.'),
('kam', 'ISA', 14, 1, 'Nũndũ Yeova akamwĩw’ĩa Yakovo tei, o na akanyuva Isilaeli, na kũmaia nthĩ yoo ene: na mwĩkali wa ũeninĩ akavulana nao, na makalũman’ya na nyũmba ya Yakovo.'),
('kam', 'ISA', 14, 2, 'Na ngo sya andũ ikamosa, na kũmatwaa vandũ voo, na nyũmba ya Isilaeli ĩkeethĩwa nasyo nthĩ ya Yeova syĩthĩwe athũkũmi aũme na eĩtu: na makaitava ila syamatavĩte, na makaisumbĩka ila syamathĩnisye.'),
('kam', 'ISA', 14, 3, 'Na kũkeethĩwa mũthenya ũla Yeova wĩkũthũmũsya woo waku, na thĩna waku, na ũthũkũmi wĩ vinya ũla wathũkũmĩthiw’e,'),
('kam', 'ISA', 14, 4, 'nĩw’o wĩneena nthimo ĩno ĩũlũ wa mũsumbĩ wa Mbaviloni, na kwasya, Kaĩ! Mũthĩn’ya nũthelete! Ndũa ya thaavu nĩthelete!'),
('kam', 'ISA', 14, 5, 'Yeova nũtũlĩte ndata ya athũku, ndata ya ũsumbĩ ya ala masumbĩkaa;'),
('kam', 'ISA', 14, 6, 'ala makũnie ngo sya andũ kũthilĩkanĩ na ĩkũna ya mavinda onthe, ala masumbĩkie i mbaĩ na ũthatu, na thĩna ũla ũtaĩ ũsiĩĩĩka nĩ mũndũ.'),
('kam', 'ISA', 14, 7, 'Nthĩ yonthe nĩthũmũĩte, na nĩvindĩtye: nĩmakwatĩtye kwina.'),
('kam', 'ISA', 14, 8, 'Ĩĩ, mĩtĩ ya mĩsonovali nĩnĩũkũtanĩa, o na mĩkũũ ya Levanoni, ĩkyasya, Kuma wanyivw’a, vai mũtemi wa mĩtĩ waatwambatĩĩa.'),
('kam', 'ISA', 14, 9, 'Seoli nĩveũthingithw’a ku nthĩnĩ kwondũ waku vakũthaũe ũkyũka; nĩvokĩlangĩtye akw’ũ kwondũ waku, o anene onthe ma nthĩ; nĩvokĩlĩtye kumya ivĩlanĩ syoo sya ũsumbĩ asumbĩ onthe ma i mbaĩ.'),
('kam', 'ISA', 14, 10, 'Asu onthe makasũngĩa na ũkũkũlya, Naku nĩwonzie taitũ? Nũtw’ĩkĩte taitũ?'),
('kam', 'ISA', 14, 11, 'Wĩnenevyo waku nũtheeetw’e Seoli, vamwe na mawasya ma tũnanda twaku: walanĩlw’e kĩinyu, na iinyu niũkũvw’ĩka.'),
('kam', 'ISA', 14, 12, 'Kaĩ! Wĩ mũvalũku kuma ĩtunĩ, we ndata ya mũthenya, mwana wa kĩoko! Ũtemetwe ũkavikw’a nthĩ, we ũla wavalũkilye i mbaĩ nthĩ!'),
('kam', 'ISA', 14, 13, 'Naku wasya ngoonĩ yaku, Ngambata ĩtunĩ, ngookĩlya kĩvĩla kyakwa kya ũsumbĩ ĩũlũ wa ndata sya Ngai; na ngekala kĩĩmanĩ kya ũmbano, kĩtulunĩ kya ngalĩ ya ĩũlũ;'),
('kam', 'ISA', 14, 14, 'ngambata kũvĩta ũtũlu wa mathweo; ngeetw’ĩkĩthya ta Ũla Wĩ Ĩũlũ wa Onthe.'),
('kam', 'ISA', 14, 15, 'Ĩndĩ ũkatheew’a Seoli, mũthelekelyonĩ wa yĩla ĩima.'),
('kam', 'ISA', 14, 16, 'Ala mekwona makakũketeea, na makasũanĩa ũndũ waku, makyasya, Mũndũ ũũ nĩwe ũla watetemasya nthĩ, ũla wathingithangasya mosumbĩ;'),
('kam', 'ISA', 14, 17, 'ũla watw’ĩkĩthisye nthĩ weũ, na kwananga ndũa syayo; ũla ũtaathasya ovwa make menũke?'),
('kam', 'ISA', 14, 18, 'Asumbĩ onthe ma i mbaĩ, onthe vyũ, nĩmakomete ndaĩanĩ, kĩla ũmwe nyũmbanĩ yake mwene.'),
('kam', 'ISA', 14, 19, 'Ĩndĩ we nĩwĩkĩtw’e kũasa na ngunga yaku vala akw’ũ maiawa ta ũvonge ũthatasya, ũvw’ĩkĩtwe ala mooaiwe, ala matonyiwe mũkuthũ na ũvyũ, ala matheeaa kũvika mavianĩ ma ĩima; ta kimba kĩkinyangĩwe nthĩ na maũũ.'),
('kam', 'ISA', 14, 20, 'Ndũkavulanw’a nao kũthikwanĩ, nĩkwĩthĩwa nĩwanangĩte nthĩ yaku, nĩwũaĩte andũ maku; ũsyao wa eki ma naĩ ndũkawetwa o na ĩndĩĩ.'),
('kam', 'ISA', 14, 21, 'Seũvyai vandũ va kũaĩa syana syake nũndũ wa ũthũku wa aaĩthe masyo, itikaaũkĩle, na kũmesya nthĩ, na kusũsya nthĩ ndũa.'),
('kam', 'ISA', 14, 22, 'Nakwa ngasyũkĩlĩla, easya ũu Yeova wa nguthu, na kũveta kuma Mbaviloni syĩtwa na ũtialo, na mwana na nzũkũlũ, easya ũu Yeova.'),
('kam', 'ISA', 14, 23, 'O na ngatw’ĩkĩthya nthĩ ya ũtũa nzee, na maia ma manzĩ: na ngamĩvyaĩa na ũvyaĩo wa wanangĩko, easya ũu Yeova wa nguthu.'),
('kam', 'ISA', 14, 24, 'Yeova wa nguthu nĩwĩvĩtĩte, akyasya, Vate ndĩi, o ũndũ nasũanĩe, now’o kũkethĩwa; na ũndũ natwie, now’o kũkekĩka:'),
('kam', 'ISA', 14, 25, 'atĩ ngaananga Mũasuli ũla wĩ nthĩ yakwa, na kũmũkinyangĩa iĩmanĩ syakwa: nĩvo ĩndĩ ĩsoki yake yĩuma kwoo, na mũio wake wĩuma ituonĩ syoo.'),
('kam', 'ISA', 14, 26, 'Ũsu nĩw’o ũtw’ĩo ũla ũtw’ĩĩwe nthĩ yonthe; na kũu nĩkw’o kw’oko kũla kũtambũũkĩw’e mbaĩ syonthe.'),
('kam', 'ISA', 14, 27, 'Nũndũ Yeova wa nguthu nũtw’ĩte, na nũũ ũla wĩũalyũla? Na kw’o kokwake nĩ kũtambũũku, na nũũ ũla wĩkũluta?'),
('kam', 'ISA', 14, 28, 'Mwaka ũla mũsumbĩ Aasu wakwie kwaĩ ndeto ĩno ngito.'),
('kam', 'ISA', 14, 29, 'Ndũkatane, we Vilisitia yonthe, nĩkwĩthĩwa ndata ĩla yakũkũnie nĩ ndũlĩku; nũndũ kĩmbuva kĩkauma kĩtinani kya nzoka, na ũsyao wakyo ũkeethĩwa nzoka ĩũlũkaa ĩilyĩ mwaki.'),
('kam', 'ISA', 14, 30, 'Na makithathi ma ngya makaĩsaa, na ala athĩni makakomaa mate na mũisyo; na ngooaa kĩtina kyaku na yũa, na ũtialo waku ũkooawa.'),
('kam', 'ISA', 14, 31, 'Kaya, we mbingĩlo; ĩa, we ndũa; nũtwekete, we Vilisitia yonthe; nũndũ syũki nĩyũkĩte kuma ngalĩ ya ĩũlũ, na vati ũmwe wĩtiĩlwa ĩtina mĩkwĩlĩnĩ yake.'),
('kam', 'ISA', 14, 32, 'Na ĩndĩ mũndũ akasũngĩa atũmwa ma ĩ mbaĩ ata? Atĩ Yeova nĩwambĩlĩlye wambĩlĩlyo wa Saioni, na nthĩnĩ wayo andũ make mathĩnaw’a makeevitha.'),
('kam', 'ISA', 15, 1, 'Ndeto ngito ũndũ wa Moavi. Nũndũ ũtukũ o ũmwe ndũa ya Ali nthĩ ya Moavi nĩtw’ĩkĩthĩtw’e ĩanzo, na kwanangwa vyũ; nũndũ ũtukũ o ũmwe ndũa ya Kili nthĩ ya Moavi nĩtw’ĩkĩthĩw’e ĩanzo, na kwanangwa vyũ.'),
('kam', 'ISA', 15, 2, 'Nĩmambatĩte Mbayithi, na Ndivoni, kũndũ kũtũlu, maĩĩe kw’o: Moavi nĩnĩkũmetea Nevo, na Meteva; mĩtwenĩ yoo yonthe yĩ mbaa, ing’ew’a syonthe nĩ ndile.'),
('kam', 'ISA', 15, 3, 'Nzĩanĩ syoo nene nĩmevotoaa makunia; nyũmbanĩ syoo ĩũlũ, na kũndũ kwoo kũthanthau, kĩla mũndũ nũmetaa na kũĩa mũno.'),
('kam', 'ISA', 15, 4, 'Na Esivoni na Eleale nikũĩa; wasya wasyo nũkwĩw’ĩka o kũvika Yaasa: kwondũ wa ũu andũ ma Moavi ala mekĩĩte mĩio ya kaũ nĩmaĩaa na wasya mũnene; ngoo yake nĩnĩũtetemea nthĩnĩ wake.'),
('kam', 'ISA', 15, 5, 'Ngoo yakwa nĩnĩkũĩa kwondũ wa Moavi; anene mayo me ndaĩa masemba Nzoali, kũvika Ekilathi‐selisiya: nũndũ nĩmekwambata kyambatonĩ kya Luithi makĩĩa; nũndũ nzĩanĩ ya Olonaimu nĩmeũkĩlya wasya wa kĩĩo ũndũ wa wanangĩko.'),
('kam', 'ISA', 15, 6, 'Nũndũ manzĩ ma Nimilimu makeethĩwa mang’alĩte; nũndũ nyeki nĩyũmĩte, nyeki ya vuvĩ nĩvovete, vati kĩndũ kĩũ.'),
('kam', 'ISA', 15, 7, 'Kwondũ wa ũu wingĩ ũla mombanĩtye, na kĩla maiĩte, makakua maingye kalũsĩ ke ĩla mĩtĩ ĩmeaa vo.'),
('kam', 'ISA', 15, 8, 'Nũndũ kĩĩo nĩkĩthyũlũlũkĩte mĩvakanĩ yonthe ya Moavi; kũmeta kwayo nĩkũvikĩte Ekilaimu, na kũmeta kwayo nĩkũvikĩte Mbeeli‐elimu.'),
('kam', 'ISA', 15, 9, 'Nũndũ manzĩ ma Ndimoni nĩmausũĩte nthakame; nũndũ ngamĩetee Ndimoni ũndũ ũngĩ, mũnyambũ kwa ala ma Moavi ala mevonoka, na ala metiala ĩ nthĩ.'),
('kam', 'ISA', 16, 1, 'Mũtwaĩei mũsumbĩki wa nthĩ tũla tũtena twa malondu kumya Sela kũvika weũnĩ, kũvika kĩĩma kya mwĩĩtu wa Saioni.'),
('kam', 'ISA', 16, 2, 'Nũndũ kũkeethĩwa atĩ ta nyũnyi ila iũlũkaa kũũ na kũũ, ta ndala mbalaan’ye, now’o eĩtu ma Moavi makethĩwa mailyĩ masyũkonĩ ma Alinoni.'),
('kam', 'ISA', 16, 3, 'Taa, sila katĩ; tw’ĩkĩthya muunyĩ waku wa mũthenya katĩ wĩthĩwe ta ũtukũ; vitha alũngw’a; ndũkamũvũnyanĩe mũkĩi.'),
('kam', 'ISA', 16, 4, 'Alũngw’a makwa matũe kwaku; ũvoo wa Moavi, we wĩthĩwe wĩvitho wake kuma ũthyũnĩ wa mwanangi. Nũndũ mũvutani nũtw’ĩkĩthĩtw’e wa mana, wanangĩko nĩ mũthelu, anyamasya nĩmanangĩtwe kuma nthĩ.'),
('kam', 'ISA', 16, 5, 'Na kĩvĩla kya ũsumbĩ kĩkalũlũmĩlw’a ũseonĩ wĩ wendo; na ũmwe akakĩkalĩla na w’o, ĩeemanĩ ya Ndaviti, akĩsila, na akĩmantha kũsila katĩ, na kwĩthĩwa e mĩtũkĩ wa kwĩka ũlũngalu.'),
('kam', 'ISA', 16, 6, 'Nĩtwĩw’ĩte ũvoo wa ngathĩĩo ya Moavi, atĩ e na ngathĩĩo mũno; o na wĩng’athĩlĩlyo wake, na ngathĩĩo yake, na kũthilĩka kwake; mĩtũlyo yake nĩ mana.'),
('kam', 'ISA', 16, 7, 'Kwondũ wa ũu Moavĩ akameta nũndũ wa Moavi, kĩla ũmwe akameta: mũkameta nũndũ wa tũmũtũ twĩ nzavivũ twa Kili‐alesethi, mwĩ akũne vyũ.'),
('kam', 'ISA', 16, 8, 'Nũndũ mĩũnda ya Esivoni nĩnĩkũma, na mũsavivũ wa Sivima; eaĩi ma i mbaĩ nĩmatũlĩte mbonge nzeo syaw’o, ila syavilie o Yaseli, ila syatambie kũvika weũnĩ; nthongooo syaw’o nĩsyeenyaisye mũno, nĩkĩlĩte ũkanga.'),
('kam', 'ISA', 16, 9, 'Kwondũ wa ũu ngaĩa vamwe na andũ ma ku Yaseli ũndũ wa mũsavivũ wa Sivima; ngakũnyithya na methoi makwa, we Esivoni, na Eleale; nũndũ wasya wa kaũ nũvalũkĩle mosyao maku ma ĩvinda ya syũa na ngetha yaku.'),
('kam', 'ISA', 16, 10, 'Mũyo nũvetetwe, na ũtanu nĩumĩtw’e mũũndanĩ wĩ ũsyao; na mĩũndanĩ ya mĩsavivũ kũikethĩwa kwina, kana wasya wĩ ũtanu: mũkinyangi o na wĩva ndakakinyanga nzavivũ iangĩonĩ; nĩnĩkilĩthĩtye wasya wa ngetha ya nzavivũ.'),
('kam', 'ISA', 16, 11, 'Kwondũ wa ũu ngoo yakwa nĩnĩũkaya ta mbeve kwondũ wa Moavi, na nthĩnĩ wakwa ve kĩĩo kwondũ wa Kili‐elesi.'),
('kam', 'ISA', 16, 12, 'Na kũkeethĩwa, yĩla Moavi wĩĩyumĩlya, yĩla wĩĩnoesya kũndũ kũtũlu, na aiũka vandũ vake vatheu avoye, ndakakĩlya vinya.'),
('kam', 'ISA', 16, 13, 'Ĩno nĩyo ndeto ĩla Yeova waneenie ũndũ wa Moavi ĩvinda ĩvĩtu.'),
('kam', 'ISA', 16, 14, 'Ĩndĩ yu Yeova nũneenete, akyasya, Nthĩnĩ wa myaka ĩtatũ, ta myaka ya mũthũkũmi, ũnene wa Moavi ũkavũthw’a, vamwe na wingĩ wa andũ make; na ũtialo ũkeethĩwa mũnini mũno na ũte vata.'),
('kam', 'ISA', 17, 1, 'Ndeto ngito ũndũ wa Ndamasiku. Sisya, Ndamasiku nĩvetetwe ndĩkethĩwe ndũa, na ĩkeethĩwa kĩvumbu kya ũomboku.'),
('kam', 'ISA', 17, 2, 'Ndũa sya Aloeli nĩtiĩtwe; itw’ĩkĩte sya ndĩthya sya mbũi na malondu, ila ikatindĩa, na vai ũla ũkaitelemya.'),
('kam', 'ISA', 17, 3, 'Na ngome ĩkathela kwa Evalaimu, na ũsumbĩ kuma Ndamasikũ, na ũtialo wa Silia; makeethĩwa ta ũnene wa ana ma Isilaeli, easya ũu Yeova wa nguthu.'),
('kam', 'ISA', 17, 4, 'Na kũkeethĩwa mũthenya ũsu, kana ũnene wa Yakovo ũkaoleka, na ũnou wa mwĩĩ wake ũkatw’ĩka kĩmosa.'),
('kam', 'ISA', 17, 5, 'Na kũkeethĩwa o ta yĩla mũkethi ũkethaa lĩu ũtũĩtye, na kw’oko kwake kũiketha iia; ĩĩ, kũkeethĩwa o ta yĩla mũndũ wĩthĩanasya iia mwandanĩ wa Alevai.'),
('kam', 'ISA', 17, 6, 'Ĩndĩ kũkatiala mothean’yo, ta kũthingithangw’a kwa mũthata, tũthata twĩlĩ kana tũtatũ mũthyanĩ wa ũvonge wĩ ĩũlũ kwĩ syonthe, tũna kana tũtano mbongenĩ itambũkĩte ndee kwĩ ila ingĩ syonthe, mũtĩnĩ wĩ ũsyao, easya ũu Yeova, Ngai wa Isilaeli.'),
('kam', 'ISA', 17, 7, 'Mũthenya ũsu andũ makasisya Mũmbi woo, na metho moo makamũsiasya Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 17, 8, 'Na matikasiasya ithembeo, wia wa moko moo; o na matikasiasya kĩla kyaseũviw’e nĩ syaa syoo, Aselimu, kana mĩvw’anano ya syũa.'),
('kam', 'ISA', 17, 9, 'Mũthenya ũsu ndũa syoo syĩ vinya ikeethĩwa ta kũndũ kũtie mũtitũnĩ na kĩĩmanĩ ĩũlũ, ila syatiiwe makĩindũka ana ma Isilaeli; na kw’o kũkeethĩwa kũthei.'),
('kam', 'ISA', 17, 10, 'Nũndũ nĩwũlĩtwe nĩ Ngai wa ũtangĩĩo waku, na ndwaalilikana ĩvia ya vinya waku; kwondũ wa ũu nũvandaa mĩtĩ ya kwendeesya, na kũvanda tũũvonge twa kũngĩ.'),
('kam', 'ISA', 17, 11, 'Mũthenya ũla ũvandaa nũvaiiaa, na kĩoko ũituma mbeũ yaku ĩlaũka; ĩndĩ ngetha nĩkĩaa mũthenya wa kĩmako na wa woo mũnene.'),
('kam', 'ISA', 17, 12, 'A! Kĩtuu kya andũ aingĩ, ala malitũkaa ta kĩlitũko kya maũkanga; na kũsemba kwa mbaĩ, ila isembaa mĩtũkĩ ta kũsemba kwa manzĩ maingĩ!'),
('kam', 'ISA', 17, 13, 'Mbaĩ ikasemba mĩtũkĩ ta kũsemba kwa manzĩ maingĩ: ĩndĩ akaĩkan’ya, na ikakĩa iende kũasa, na ikalũngw’a ta wewa wĩ iĩmanĩ nĩ kĩseve, na ta kũũlũkw’a kwa kĩtoo nĩ kĩuutani.'),
('kam', 'ISA', 17, 14, 'Wĩoo, sisya ũtĩsyo; na kũtanakya mativaĩ. Kĩĩ nĩkyo kĩanda kya ala meũtũtava, na kĩanda kya ala meũtũvuta.'),
('kam', 'ISA', 18, 1, 'A! Nthĩ ya kĩuumo kya nthwau, ĩla yĩ mũingo wa mbũsĩ sya Ethiovia;'),
('kam', 'ISA', 18, 2, 'ĩla ĩtũmĩlaa atũmwa nzĩanĩ ya ũkanga, tũkalawanĩ twa malula manzĩnĩ, ĩkyasya, Endai, inyw’ĩ atũmwa mwĩ mĩtũkĩ, kwa mbaĩ ndasa na ndendeu, kwa andũ ma ũtĩsya kuma wambĩlĩlyo woo kũvika na yu, mbaĩ ĩla ĩthimaa na kũkinyanga, ĩla nthĩ yayo yatũanganĩtw’e nĩ mbũsĩ!'),
('kam', 'ISA', 18, 3, 'Inyw’onthe ala mũtwĩe nthĩ, na inyw’ĩ mwĩkalaa kũũ nthĩ, sisyai, yĩla kĩvevelo kĩũkĩlw’a iĩmanĩ; ĩthũkĩĩsyei, yĩla soo wĩvuvwa.'),
('kam', 'ISA', 18, 4, 'Nũndũ ũu nĩw’o Yeova wambĩie, Ngavindya, na ngasisya nĩ wĩkalonĩ wakwa, ta muutĩa mũkelemu syũanĩ, ta mũmbĩ wĩ ĩmwe muutĩanĩ wa ĩvinda ya ngetha.'),
('kam', 'ISA', 18, 5, 'Nũndũ ngetha ĩtanavika, yĩla kũlaũka kũthelete, na ĩlaa yĩitwĩ’ka nzavivũ ĩla ĩkwĩw’a, akatema tũmĩlĩso na kavyũ ke ngoto ka kũsea, na ndĩso ila syĩnyaĩtwe ila ndeme akaveta.'),
('kam', 'ISA', 18, 6, 'Syonthe vamwe ikatiĩwa nyũnyi mbai sya iĩmanĩ, na nyamũ sya nthĩ; na nyũnyi isu mbai ikekala ĩũlũ woo ĩvinda ya syũa, na nyamũ syonthe sya nthĩ ikekala ĩũlũ wasyo ĩvinda ya mbevo.'),
('kam', 'ISA', 18, 7, 'Ĩvinda yĩu mũthĩnzĩo ũkaetewe Yeova wa nguthu kuma andũnĩ aasa na atendeu, o kuma andũnĩ ma kũtĩsya kuma wambĩlĩlyo woo kũvika na yu, mbaĩ ĩla ĩthimaa na kũkinyanga, ĩla nthĩ yayo yatũanganĩtw’e nĩ mbũsĩ, kũvika vandũ va syĩtwa ya Yeova wa nguthu, kĩĩma kya Saioni.'),
('kam', 'ISA', 19, 1, 'Ndeto ngito ũndũ wa Misili. Sisya, Yeova nũendete akuĩtwe nĩ ĩthweo yĩendaa mĩtũkĩ, kũvika Misili: na mĩvw’anano ya Misili ĩkathingithangĩa mbee wake; na ngoo ya Misili ĩkatweka nthĩnĩ wayo.'),
('kam', 'ISA', 19, 2, 'Na ngookĩlya Amisili mokite na Amisili: na makokita kĩla ũmwe na mwana‐a‐inyia, na kĩla ũmwe na mũtũi wake; ndũa ĩkokita na ndũa, na ũsumbĩ na ũsumbĩ.'),
('kam', 'ISA', 19, 3, 'Na veva wa Misili ũkathelekela nthĩnĩ wayo; na ngaananga ũtao wayo; na makamantha ũtethyo kwa mĩvw’anano, na kwa eki ma syama, na kwa ala mesene na maveva, na kwa ala mombasya ithitũ.'),
('kam', 'ISA', 19, 4, 'Na nganengane Amisili kw’okonĩ kwa mwĩaĩi mũthũku; na mũsumbĩ mwai akamasumbĩka, easya ũu Mwĩaĩi, Yeova wa nguthu.'),
('kam', 'ISA', 19, 5, 'Na manzĩ makanyiva ũkanganĩ, na ũla ũsĩ ũkang’ala wũme vyũ.'),
('kam', 'ISA', 19, 6, 'Na mbũsi ikanyunga naĩ; na mĩtaũnĩ mĩnene manzĩ makanyiva na kũng’ala; mĩangi na makangaa makavova.'),
('kam', 'ISA', 19, 7, 'Nyeki yĩ vakuvĩ na ũsĩ wa Naelo, mwaĩĩonĩ wa Naelo, na kw’onthe kũla kũvandĩtwe vakuvĩ na Naelo, kũkooma, na kũvetwa, na kũikethĩwa kw’o ĩngĩ.'),
('kam', 'ISA', 19, 8, 'Na atei ma makũyũ makaĩa, na onthe ala mekasya itei ũsĩnĩ wa Naelo makameta, na ala malanasya itei sya makũyũ manzĩnĩ ĩũlũ makaaa vinya.'),
('kam', 'ISA', 19, 9, 'Na ĩngĩ ala matethasya wĩa na ndii nzanũe sya katane, na ala matumaa ngũa nzaũ, makathokoanw’a.'),
('kam', 'ISA', 19, 10, 'Na ituĩ sya Misili ikatũlangwa ilungu; onthe ala matethasya wĩa wa ũtuvwa makeew’a woo ngoonĩ syoo.'),
('kam', 'ISA', 19, 11, 'Anene me mbee ũsumbĩnĩ ma Nzoani nĩ atumanu vyũ; ũtao wa atai ala oĩ mbee ma Valao nũtw’ĩkĩte ta wa nyamũ: mwĩmwĩa Valao ata, Nyie nĩ mwana wa ala oĩ, mwana wa asumbĩ ma tene tene?'),
('kam', 'ISA', 19, 12, 'Andũ maku oĩ maĩva ĩndĩ? Makũtavye yu; nĩmamanye ũndũ Yeova wa nguthu ũsũanĩĩte wa Misili.'),
('kam', 'ISA', 19, 13, 'Anene me mbee ũsumbĩnĩ ma Nzoani nĩmatw’ĩkĩte ndia, ala me mbee ũsumbĩnĩ wa Memivisi nĩmakengetwe; nĩmatumĩte Misili yaa, asu ĩvia ya kĩkotonĩ ya mbaĩ syayo.'),
('kam', 'ISA', 19, 14, 'Yeova nũvulanĩtye veva wa ũng’endu nthĩnĩ wayo; na nĩmatumĩte Misili yaa kĩla wĩanĩ wayo, o ta mũndũ ũnyw’ĩte ailũalũa matavĩkanĩ make.'),
('kam', 'ISA', 19, 15, 'O na kũikethĩwa wĩa o na wĩva wa Misili, ũla mũtwe kana kĩsithe, ĩthangũ ya mĩtende kana malula, ikatonya kwĩka.'),
('kam', 'ISA', 19, 16, 'Mũthenya ũsu Amisili makethĩwa mailyĩ ta aka; na makatetema na kũkĩa nũndũ wa kũtukangĩwa kw’oko nĩ Yeova wa nguthu, kũla wĩmatukangĩa.'),
('kam', 'ISA', 19, 17, 'Na nthĩ ya Yuta ĩkatw’ĩka ũtĩsyo kwa Misili; kĩla ũmwe ũla wĩĩw’a ĩkĩwetwa akakwatwa nĩ w’ĩa, nũndũ wa ũtw’ĩo wa Yeova wa nguthu, ũla ũmĩtw’ĩĩe.'),
('kam', 'ISA', 19, 18, 'Mũthenya ũsu kũkethĩwa ndũa itano nthĩ ya Misili ila ineenaa kĩthyomo kya Kanaani, na kũmwĩvĩtĩa Yeova wa nguthu; ĩmwe ĩkeetwa Ndũa ya wanangĩko.'),
('kam', 'ISA', 19, 19, 'Mũthenya ũsu kũkethĩwa kĩthembeo kwondũ wa Yeova katĩ wa nthĩ ya Misili, na kĩtuĩ mũvakanĩ wayo kwondũ wa Yeova.'),
('kam', 'ISA', 19, 20, 'Na ũu ũkethĩwa wonan’yo na ũkũsĩ kwa Yeova wa nguthu nthĩ ya Misili; nũndũ makamwĩkaĩla Yeova nũndũ wa athĩn’ya, nake akamaetee mũtangĩĩi, na mũsesei, na akamavonokya.'),
('kam', 'ISA', 19, 21, 'Na Yeova akamanyĩka Misili, na Amisili makamũmanya Yeova mũthenya ũsu; ĩĩ, makathaitha na kũete nthembo ya kũtonywa na mĩthĩnzĩo, na makamwĩvĩtĩa Yeova wĩvĩto, na kũwĩanĩsya.'),
('kam', 'ISA', 19, 22, 'Na Yeova akakũna Misili, kũkũna na kũvosya; na makamũsyokea Yeova, nake akeesũvĩka nĩo, na akamavosya.'),
('kam', 'ISA', 19, 23, 'Mũthenya ũsu kũkethĩwa lelũ kũma Misili kũvika Asuli, na Mũasuli akathi Misili, na Mũmisili akathi Asuli; na Amisili makathaitha vamwe na Aasuli.'),
('kam', 'ISA', 19, 24, 'Mũthenya ũsu Isilaeli akethĩwa wa katatũ we na Misili na Asuli, ũathimo katĩ wa nthĩ;'),
('kam', 'ISA', 19, 25, 'nũndũ Yeova wa nguthu nũmaathimĩte, akyasya, Nĩ aathime Misili andũ makwa, na Asuli wĩa wa moko makwa, na Isilaeli ũtiĩwa wakwa.'),
('kam', 'ISA', 20, 1, 'Mwaka ũla Talitani wavikie ndũa ya Asitoti, yĩla Salikoni mũsumbĩ wa Asuli wamũtũmie, na okita na Asitoti na amĩkwata;'),
('kam', 'ISA', 20, 2, 'o ĩvinda yĩu Yeova aneenie na kanyw’a wa Isaia mwana wa Amosu, akyasya, Enda, umye ĩkunia yĩla wĩvotoete kĩnyunyunĩ kyaku, noyumya iatũ syaku maũũ. Nake eeka ũu, akĩenda e mũthei na maũũ me mathei.'),
('kam', 'ISA', 20, 3, 'Na Yeova asya, O tondũ mũthũkũmi wakwa Isaia ũendete e mũthei na maũũ mathei myaka ĩtatũ ethĩwe wonan’yo na ũseng’yo ũndũ wa Misili na ũndũ wa Ethiovia;'),
('kam', 'ISA', 20, 4, 'now’o mũsumbĩ wa Asuli ũkatwaa ala atave me Misili, na ala mathamĩthĩtw’e kuma Ethiovia, syana na akũũ, me athei na maũũ mathei, na itimba ite mbw’ĩke, Misili ĩsonoke.'),
('kam', 'ISA', 20, 5, 'Na makateva na kũthokoanw’a, nũndũ wa Ethiovia wĩkwatyo woo, na nũndũ wa Misili kwĩkathĩĩa kwoo.'),
('kam', 'ISA', 20, 6, 'Na ũla ũtwĩe nthĩ ĩsu yĩ ũtee wa ũkanga akaneena mũthenya ũsu, Sisya, wĩkwatyo witũ ũilyĩ ũu, vala twakĩĩe twone ũtethyo wa kumw’a mokonĩ ma mũsumbi wa Asuli: na ithyĩ tũkavonoka ata?'),
('kam', 'ISA', 21, 1, 'Ndeto ngito ũndũ wa weũ wa ũkanga. Ta ilingi sya ngalĩ ya Ĩtheo ivĩtaa na vinya, nĩsyũkaa kũma weũnĩ, kuma nthĩ ya kũtĩsya.'),
('kam', 'ISA', 21, 2, 'Nĩnonetw’e woni wĩ woo; mũndũ nzeleke nĩwĩkaa ũseleke, na mwanangi nĩwanangaa. Ambata, we Elamu; tw’ĩkanĩsya, we Metia; kũvevũũka kw’onthe kwa vo nĩnĩkũminĩte.'),
('kam', 'ISA', 21, 3, 'Kwondũ wa ũu kĩnyunyu kyakwa nĩkyusũĩte woo; woo nũngwatĩte ta woo wa mũndũ mũka akyaũnya: nĩngwalw’a ũndũ ndatonya kwĩw’a; nĩngũteva ũndũ ndatonya kwona.'),
('kam', 'ISA', 21, 4, 'Ngoo yakwa nĩnĩũtumatuma, ũtĩsyo nũmbĩkĩĩte w’ĩa; ũmololi ũla nendaa nũalyũlĩtwe ũtw’ĩke kũtetema kwakwa.'),
('kam', 'ISA', 21, 5, 'Nĩmekwalan’ya mesa, nĩmekwia asũvĩi, nĩmekũya, nĩmekũnyw’a: ũkĩlai, ĩnyw’ĩ anene me mbee ũsumbinĩ, vakai ngao mauta.'),
('kam', 'ISA', 21, 6, 'Nũndũ ũũ nĩw’o Mwĩaĩi ũndavĩtye, Enda, wie mũsyaĩĩsya; natavan’ye ũndũ ũnũkwona;'),
('kam', 'ISA', 21, 7, 'na esa kwona nguthu, andũ elĩ, elĩ, matũlĩte mbalasĩ, o na nguthu ya mang’oi, o na nguthu ya ngamĩle, nĩethukĩĩsye mũno akĩsũvĩa mũno.'),
('kam', 'ISA', 21, 8, 'Na aluma ta mũnyambũ: Ame Mwĩaĩi, nĩũngamaa mavinda onthe mũthenya mwakonĩ mũtũlu wa mũnyoolo kũsyaĩĩsya, na nĩĩtwe ũsyaĩĩsyonĩ wakwa ũtukũ na ũtukũ;'),
('kam', 'ISA', 21, 9, 'na, sisya, nguthu ya andũ nĩyũkĩte, andũ elĩ, elĩ, matũlĩte mbalasi. Na asũngĩa na asya, Mbaviloni nĩ mbalũku, mbalũku; na mĩvw’anano yonthe myasũvye ya ngai syayo nĩtũlĩtwe na kũvalũkw’a nthĩ.'),
('kam', 'ISA', 21, 10, 'We ngetha yakwa ĩvũĩtwe, na lĩu wa mbaa ngetha wa kĩvũĩo kyakwa! Ũla nĩw’ĩte kuma kwa Yeova wa nguthu, Ngai wa Isilaeli, now’o nĩkũtavĩtye.'),
('kam', 'ISA', 21, 11, 'Ndeto ngito ũndũ wa Ndũma. Ũmwe akĩmbĩta kuma Seili, Mũsyaĩĩsya, ũtukũ ũkũvika va?'),
('kam', 'ISA', 21, 12, 'Mũsyaĩĩsya asya, Kĩoko nĩkyũkĩte, o na ũtukũ naw’o; ethĩwa nĩmũkwenda ũkũlya, kũlyai: ĩthyũũei, ũkai.'),
('kam', 'ISA', 21, 13, 'Ndeto ngito ũndũ wa Alavia. Mũtitũnĩ wa Alavia mũkakoma, inyw’ĩ Andetani, aendi ma syalo.'),
('kam', 'ISA', 21, 14, 'Nĩmamũeteie ũla waĩ na waũni manzĩ; ala matwĩe nthĩ ya Tema nĩmamathaũie akĩi mamakuĩe lĩu.'),
('kam', 'ISA', 21, 15, 'Nũndũ nĩmakĩĩte mbyũ, ũvyũ ũkũĩtwe, na ũta ũkootetwe, na ũthũku wa kaũ.'),
('kam', 'ISA', 21, 16, 'Nũndũ ũũ nĩw’o Mwĩaĩi ũndavĩtye, Ĩvinda ya mwaka ũmwe, kwĩanana na myaka ya mũthũkũmi, ndaĩa yonthe ya Ketali ĩkathela;'),
('kam', 'ISA', 21, 17, 'na ũtialo wa andũ ala mokitaa na mata, ngũmbaũ sya ana ma Ketali, ũkeethĩwa wĩ mũnini; nũndũ Yeova, Ngai wa Isilaeli, nũneenete ũu.'),
('kam', 'ISA', 22, 1, 'Ndeto ngito ũndũ wa mwanda wa woni. Wĩ na ũndũ mwaũ yu, ũndũ wambatie vyũ ĩũlũ wa nyũmba?'),
('kam', 'ISA', 22, 2, 'We ũla wusũĩte mawasya manene, ndũa ya kĩthokoo, katũla ke ũtanu; oae maku matyũaĩtwe na ũvyũ, o na maikw’ĩĩe kaũnĩ.'),
('kam', 'ISA', 22, 3, 'Asumbĩki maku onthe nĩmakĩie vamwe, nĩmoviwe nĩ andũ ma mata; onthe ala wonie maĩ ove vamwe; nĩmakĩie mathi kũasa.'),
('kam', 'ISA', 22, 4, 'Kwondũ wa ũu nasya, Ndũkanzisye nyie, ngaĩa kĩĩo kĩ woo; ndũkethĩn’ye ũndũ wa kũngiakisya ũndũ wa kwanangwa kwa mwĩĩtu wa andũ makwa.'),
('kam', 'ISA', 22, 5, 'Nũndũ nĩ mũthenya wa kũthokoanw’a, na wa kũkinyangĩwa nthĩ, na wa kũsũanĩwa, ũetetwe nĩ Mwĩaĩi, Yeova wa nguthu, mwandanĩ wa woni; kũombowa kwa maũvai, na kwĩkaĩla iĩma.'),
('kam', 'ISA', 22, 6, 'Na Elamu akua thyaka, e vamwe na makasya ma kaũ me na andũ, na andũ matũlĩte mbalasi; na Kili avuĩte ngao.'),
('kam', 'ISA', 22, 7, 'Na kweethĩwa, myanda yaku ĩla mĩseo mũno yaĩ myusũu makasya, na andũ matũlĩte mbalasi meetaũsya mokitĩe mbingĩlonĩ.'),
('kam', 'ISA', 22, 8, 'Na aveta kĩla kĩvw’ĩkĩte Yuta; na mũthenya ũsu wasisya mĩio ya kaũ nyũmbanĩ yĩ mũtitũnĩ.'),
('kam', 'ISA', 22, 9, 'Na mwoona kũndũ kũvũthũku kwa ndũa ya Ndaviti, atĩ nĩ kwingĩ; na mwatũngĩanĩa manzĩ ma ndia yĩ ngalĩ ya ĩtheo;'),
('kam', 'ISA', 22, 10, 'na mwatala nyũmba sya Yelusaleme, na mwaomboanga nyũmba mũlũlũmĩlye ũvai;'),
('kam', 'ISA', 22, 11, 'o na katĩ wa maũvai elĩ mwaseũvya ndia ya manzĩ ala ma ndia ngũũ. Ĩndĩ mũtyaamũsisya ũla wekie ũu, o na mũtyaamũtaĩa ũla wasũanĩe ũu tene.'),
('kam', 'ISA', 22, 12, 'Na mũthenya ũsu Mwĩaĩi, Yeova wa nguthu, eetana kwĩthĩwe kĩĩo, na kĩmeto, na kwĩyenza mbaa, na kwĩvotoa makunia:'),
('kam', 'ISA', 22, 13, 'na, kaĩ, nĩ ũtanu na mũyo, kũthĩnza ng’ombe na kũaa malondu, kũya nyama na kũnyw’a mbinyu: Tũye na tũnyw’e nũndũ ũnĩ tũkakw’a.'),
('kam', 'ISA', 22, 14, 'Na Yeova wa nguthu eembuanĩsya matũnĩ makwa, Nĩ w’o, mũikaekewa ũthũku ũũ kũvika mwakw’a, easya ũu Mwĩaĩi, Yeova wa nguthu.'),
('kam', 'ISA', 22, 15, 'Ũũ nĩw’o Mwĩaĩi, Yeova wa nguthu, ũnũkwasya, Thi kwa mũsũvĩi ũsu wa ũthwii, o Sevina, ũla ũsũvĩaa nyũmba, noimũkũlya,'),
('kam', 'ISA', 22, 16, 'Wĩĩka ata vaa? Na wĩ naũ vaa, ũndũ ũkwĩyasĩa ngunga ya mathiko vaa? Ta ũla wĩyasĩe ngunga ĩũlũ, akĩyasĩa wĩkalo ĩvianĩ!'),
('kam', 'ISA', 22, 17, 'Sisya, Yeova, ta mũndũ wĩ vinya, akakwĩkya na vinya kũasa; ĩĩ, akakũlinga mũno.'),
('kam', 'ISA', 22, 18, 'Akakũlingalinga na kũkwĩkya nthĩ nene ta mũvĩla; ũkakw’ĩa kw’o, na makasya ma ndaĩa yaku makeethĩwa kw’o, we ũsonokyo wa nyũmba ya mwĩaĩi waku.'),
('kam', 'ISA', 22, 19, 'Na ngakumya ũsũvĩinĩ waku; na ũkavalũkw’a kumw’a ũũngamĩinĩ waku.'),
('kam', 'ISA', 22, 20, 'Na kũkethĩwa mũthenya ũsu, ngamwĩta mũthũkũmi wakwa Eliakimu mwana wa Ilikia:'),
('kam', 'ISA', 22, 21, 'na ngamũvw’ĩka ngũa yaku ndasa, na ngamwĩkĩa vinya ũndũ wa kũmwova mũsivi waku, na ngeekĩa ũsumbĩko waku kw’okonĩ kwake; nake akeethĩwa ĩthe kwa ala matwĩe Yelusaleme, na kwa nyũmba ya Yuta.'),
('kam', 'ISA', 22, 22, 'Na ũvũngũo wa nyũmba ya Ndaviti ngatũlya kĩtuonĩ kyake; nake akavingũa na vai wĩvinga; na akavinga, na vai wĩvingũa.'),
('kam', 'ISA', 22, 23, 'Na ngamũlũmya ta mũsumaa vandũ valũmu; nake akeethĩwa kĩvĩla kya ũsumbĩ kya ndaĩa nyũmbanĩ ya ĩthe wake.'),
('kam', 'ISA', 22, 24, 'Na makanĩka ĩũlũ wake ndaĩa yonthe ya nyũmba ya ĩthe wake, ũsyao na nzyawa, kĩla mũio mũnini, kuma ikombe kũvika masũva onthe.'),
('kam', 'ISA', 22, 25, 'Mũthenya ũsu, easya Yeova wa nguthu, mũsumaa ũla walũlũmĩlw’e vandũ valũmu ũkakũka; na ũkatemwa na kũvalũka; na mũio ũla wanĩkiwe ĩũlũ waw’o ũkavetwa; nũndũ Yeova nũneenete ũu.'),
('kam', 'ISA', 23, 1, 'Ndeto ngito ũndũ wa Tile. Kayai, inyw’ĩ ngalawa sya Talisisi; nũndũ nĩnĩtw’ĩkĩthĩtw’e ĩanzo, o na vati nyũmba, vati ũlikĩlo: nĩmataviw’e me nthĩ ya Kitimu.'),
('kam', 'ISA', 23, 2, 'Kilyai inyw’ĩ ala mũtwĩe ũtee wa ũkanga, athoosya ma Sitoni, ala maingĩlaa ũkanganĩ, nĩmakusũĩtye.'),
('kam', 'ISA', 23, 3, 'Na ĩũlũ wa manzĩ maingĩ mbeũ sya ũsĩ wa Sioli, ngetha ya Naelo, yaĩ ũtandĩthyo wayo; nayo yaĩ kĩng’ang’a kya mbaĩ.'),
('kam', 'ISA', 23, 4, 'Sonoka, we Sitoni, nũndũ ũkanga ũneenete, ngome yĩ vinya ya ũkanga, ũkyasya, Ndyaaũnya, kana kũsyaa, o na ndyaaea anake, kana kũea eĩtu atheu.'),
('kam', 'ISA', 23, 5, 'Yĩla ũvoo wĩvika Misili makeew’a woo mũno ũndũ wa ũvoo wa Tile.'),
('kam', 'ISA', 23, 6, 'Ingai mũende Talisisi; metai, inyw’ĩ mũtwĩe ũtee wa ũkanga.'),
('kam', 'ISA', 23, 7, 'Ĩno nĩyo ndũa yenyu yĩ ũtanu, ĩla yakiwe tene tene, ĩla maũũ mayo mamĩtwaie kũasa yĩkale ũeni?'),
('kam', 'ISA', 23, 8, 'Nũũ ũla wamĩtw’ĩĩe Tile ũndũ ũũ, ĩla ĩnenganae ngovia ya ũsumbĩ, na athoosya mayo nĩ anene me mbee ũsumbĩnĩ, na atandĩthya mayo nĩ ala me na nguma kũũ nthĩ?'),
('kam', 'ISA', 23, 9, 'Yeova wa nguthu nĩwe watwie ũndũ ũũ, nĩ kana avukye ngathĩĩo ya ũnene w’onthe, na amavũthĩthye onthe ma nthĩ ala me nguma.'),
('kam', 'ISA', 23, 10, 'Vĩtĩla katĩ wa nthĩ yaku ta ũsĩ wa Naelo, we mwĩĩtu wa Talisisi; vati kĩsiĩĩi ĩngĩ.'),
('kam', 'ISA', 23, 11, 'Nũtambũũkĩtye kw’oko kwake ĩũlũ wa ũkanga, nũthingithangĩtye mosumbĩ; Yeova nĩwĩaĩte ũndũ wa Kanaani, anange ngome syĩ vinya sya vo.'),
('kam', 'ISA', 23, 12, 'Nake asya, Ndũkatana ĩngĩ, we mwĩĩtu mũtheu wa Sitoni ũla ũthĩnĩtw’e: ũkĩla noiinga ũende Kitimu; o na kw’o ndũkona ũthũmũo.'),
('kam', 'ISA', 23, 13, 'Sisya, nthĩ ya Akalitei: andũ asu mati vo; Mũasuli amiĩte yĩthĩwe ya ala matũaa weũnĩ; nĩmaakie myako yoo mĩtũlu ya mĩnyoolo; nĩmaing’uthũlile nyũmba nene mbanakavye sya vo; nĩmamĩtw’ĩkĩthisye nthei.'),
('kam', 'ISA', 23, 14, 'Kayai, inyw’ĩ ngalawa sya Talisisi; nũndũ ngome yenyu yĩ vinya nĩtw’ĩkĩthĩtw’e ĩanzo.'),
('kam', 'ISA', 23, 15, 'Na kũkethĩwa mũthenya ũsu, kana Tile ĩkoola myaka mĩongo mũonza, kwĩanana na mĩthenya ya mũsumbĩ ũmwe: myaka mĩongo mũonza yathela kũkeethĩwa kũilyĩ kwa Tile o tondũ kũilyĩ kwinanĩ kwa ĩlwaya.'),
('kam', 'ISA', 23, 16, 'Osa mbeve, noianganga ndũanĩ, we ĩlwaya yĩla yũlĩte; ũkĩlya wasya wĩ mũyo, ina mbathi nyingĩ, nĩ kana ũlilikanwe.'),
('kam', 'ISA', 23, 17, 'Na kũkeethĩwa myaka mĩongo mũonza yathela, Yeova akavikĩa Tile, nayo ĩkasyokea ĩtuvi yayo, na ĩkeeka ũmalwaya na mosumbĩ onthe ala me ĩũlũ wa nthĩ.'),
('kam', 'ISA', 23, 18, 'Na mĩio yayo ya ũthoosya na ĩtuvi yayo yĩkeethĩwa ĩvathan’ye kwa Yeova: yĩtikasũvĩwa kana kwiwa; nũndũ mĩio yayo ya ũthoosya ĩkeethĩwa ya ala mekalaa mbee wa Yeova, maĩsae lĩu wa kũmeanĩa, na mekĩae ngũa sya kwĩkalaa.'),
('kam', 'ISA', 24, 1, 'Sisya, Yeova nũkũmĩtw’ĩkĩthya nthĩ nthei, na kũmyananga, na kũmĩkuluman’ya, na kũnyaĩĩkya ala mamĩtwĩe.'),
('kam', 'ISA', 24, 2, 'Na kũkeethĩwa, o tondũ kũilyĩ kwa andũ, now’o kwa mũthembi; o tondũ kũilyĩ kwa mũthũkũmi, now’o kwa vwana wake; o tondũ kũilyĩ kwa mwĩĩtu mũthũkũmi, now’o kwa vivi wake; o tondũ kũilyĩ kwa ũla ũthooaa, now’o kwa mũthoosya; o tondũ kũilyĩ kwa ũla ũkovethasya, now’o kwa ũla ũkovethaw’a; o tondũ kũilyĩ kwa ũla wosaa ũtandĩthyo, now’o kwa ũla ũmũtandĩthĩasya.'),
('kam', 'ISA', 24, 3, 'Nthĩ ĩkatw’ĩka nthei vyũ, na ĩkaanangwa vyũ; nũndũ Yeova nũneenete ndeto ĩno.'),
('kam', 'ISA', 24, 4, 'Nthĩ nĩnĩũmeta na kũthelekelya, nthĩ yonthe nĩnĩũleela na kũthelekelya, andũ me na wĩng’athĩlĩlyo kũũ nthĩ nĩmeũleela.'),
('kam', 'ISA', 24, 5, 'Nthĩ nayo nĩvukĩtw’e ĩtheo wa ala mamĩtũaa; nĩkwĩthĩwa nĩmavĩtĩtye mĩao, na kũlea myamũlo, na kũtũla ũtianĩo wa tene na tene.'),
('kam', 'ISA', 24, 6, 'Kwondũ wa ũu kĩumo nĩkĩminĩte nthĩ, na ala mamĩtwĩe nĩmekwoneka me avĩtan’ya: kwondũ wa ũũ ala matwĩe nthĩ nĩmavĩtĩtw’e, no andũ avũthũ matiele.'),
('kam', 'ISA', 24, 7, 'Mbinyu mbĩthĩ nĩnĩũmeta, mũsavĩvũ nũũvova, na onthe ala matanĩte ngoo nĩmeũvevũũka.'),
('kam', 'ISA', 24, 8, 'Ũtanu wa tũthembe nũũvindya, kĩlonzo kya ala matanaa nĩkĩũthela, ũtanu wa mbeve nũũvindya.'),
('kam', 'ISA', 24, 9, 'Matikanyw’a mbinyu makina wathĩ; kĩla kĩtoonasya kĩkeethĩwa kĩ ũũ kwa ala makĩnyusaa.'),
('kam', 'ISA', 24, 10, 'Ndũa nthei nĩomboetwe; kĩla nyũmba nĩvingĩtwe, mũndũ o na wĩva ndakalike.'),
('kam', 'ISA', 24, 11, 'Ve kĩĩo nzĩanĩ nene nũndũ wa ĩla mbinyu; ũtanu w’onthe nũtw’ĩkĩte kĩvindu, ũtanu wa nthĩ nũthelete.'),
('kam', 'ISA', 24, 12, 'Nthĩnĩ wa ndũa kũtiĩtwe ĩanzo, na mbingĩlo nĩ ngũne nĩ wanangĩko.'),
('kam', 'ISA', 24, 13, 'Nũndũ kũkeethĩwa ũu katĩ wa nthĩ katĩ wa ngo sya andũ, ta kũthingithangw’a kwa mũthata, ta mothean’yo yĩla ngetha ya mũũnda wa mũsavivũ yathela.'),
('kam', 'ISA', 24, 14, 'Asu nĩmakokĩlya mawasya moo, makanĩĩsya; kwondũ wa ũnene wa Yeova nĩmokĩlasya wasya mũnene me ũkanganĩ.'),
('kam', 'ISA', 24, 15, 'Kwondũ wa ũu mũtaĩei Yeova wumĩlonĩ wa syũa, o syĩtwa ya Yeova, Ngai wa Isilaeli, ithamanĩ syĩ ũkanganĩ.'),
('kam', 'ISA', 24, 16, 'Kuma kĩtulunĩ kya nthĩ nĩtwĩw’ĩte mbathi: Ndaĩa kwa ala alũngalu. Ĩndĩ nasya, Nĩngũsonzoma, nĩngũsonzoma, woo nĩ wakwa! Ala nzeleke nĩmekĩte ũseleke; ĩĩ, ala nzeleke nĩmekĩte ũseleke mũno.'),
('kam', 'ISA', 24, 17, 'W’ĩa, na ĩima, na kĩtei, nikwoveesye, we ũla ũtwĩe nthĩ.'),
('kam', 'ISA', 24, 18, 'Na kũkeethĩwa, ũla ũsembaa akĩĩte kĩlonzo kya w’ĩa akavalũka ĩimanĩ; na ũla wĩĩyumya ĩimanĩ nthĩnĩ akakwatw’a nĩ kĩtei: nũndũ mbũthi syĩ ĩũlũ nivingũĩtwe, na myambĩlĩlyo ya nĩnĩũtetema.'),
('kam', 'ISA', 24, 19, 'Nthĩ nĩ ndũlĩkangu, nthĩ nĩ mbatũkangu, nthĩ nĩthingithĩkĩte na vinya.'),
('kam', 'ISA', 24, 20, 'Nthĩ ĩkalũalũa ta mũthengi, na ĩkasũa kũũ na kũũ ta mũsũo; na ĩvĩtyo yayo yĩkeethĩwa ĩito ĩũlũ wayo, na ĩkavalũka, na ndĩkokĩla ĩngĩ.'),
('kam', 'ISA', 24, 21, 'Na kũkethĩwa mũthenya ũsu, Yeova akakũna nguthu ya ala me ĩũlũ vandũ vatũlu, na asumbĩ ma nthĩ kũũ nthĩ.'),
('kam', 'ISA', 24, 22, 'Na makoombanw’a vamwe, tondũ ala ove mombanaw’a kasũmbanĩ ke nthĩnĩ wa nthĩ, na makavingĩwa kolokolonĩ; na mĩthenya mingĩ yathela makasilĩlwa.'),
('kam', 'ISA', 24, 23, 'Nĩvo ĩndĩ mwei ũkavũavũana, na syũa yĩkasonoka; nũndũ Yeova wa nguthu akasumbĩka kĩĩmanĩ kya Saioni, naku Yelusaleme; na mbee wa atumĩa make kũkeethĩwa ndaĩa.'),
('kam', 'ISA', 25, 1, 'Ame Yeova, nue Ngai wakwa; ngakũnenevya, ngataĩa syĩtwa yaku; nũndũ nĩwĩkĩte maũndũ ma ũseng’ya, o motw’ĩo ma tene, wĩ na kĩthito na w’o.'),
('kam', 'ISA', 25, 2, 'Nũndũ nũtw’ĩkĩthĩtye ndũa kĩvumbu, na ndũa mbiie, ũomboko, na nyũmba nene mbanakavye ya aeni ndĩkethĩwe ndũa; ndĩkakwa ĩngĩ o na ĩndĩĩ.'),
('kam', 'ISA', 25, 3, 'Kwondũ wa ũu andũ me vinya makakũtaĩa; ndũa ya mbaĩ sya ũtĩsya ĩkakũkĩa.'),
('kam', 'ISA', 25, 4, 'Nũndũ we nĩweethĩawa ngome yĩ vinya kwa ngya, ngome yĩ vinya kwa ũla mũthĩni thĩnanĩ wake, wĩvitho kwondũ wa kĩuutani, muunyĩ kwondũ wa muutĩa, yĩla kĩseve kya ala ma kũtĩsya kĩilyĩ ta kĩuutani kĩiuutanĩa ũvai.'),
('kam', 'ISA', 25, 5, 'O ta muutĩa vandũ vomũ now’o wĩtheeesya nthĩ kĩlonzo kya aeni; wathi wa ala ma kũtĩsya ũkatheew’a nthĩ, o tondũ muutĩa wĩkawa nĩ muunyĩ wa ĩthweo.'),
('kam', 'ISA', 25, 6, 'Na kĩĩmanĩ kĩĩ Yeova wa nguthu akavokea ngo syonthe sya andũ mboka ya syĩndũ nou, mboka ya mbinyu syĩ ĩũlũ wa kĩmongoyo, ya syĩndũ nou syusũĩte mũthungo, ya mbinyu syĩ ĩũlũ wa kĩmongoyo ikeletwe nesa.'),
('kam', 'ISA', 25, 7, 'Na kĩĩmanĩ kĩĩ akaananga kĩvw’ĩkĩi kĩla kĩvw’ĩkaa ngo syonthe sya andũ, na suka mũvũthũ ũla walanĩtw’e ĩũlũ wa mbaĩ syonthe.'),
('kam', 'ISA', 25, 8, 'Nũmeletye kĩkw’ũ tene na tene; na Mwĩaĩi Yeova akavyaĩa methoi mothyũnĩ onthe; na kũvũthw’a kwa andũ make akaveta kuma nthĩ yonthe: nũndũ Yeova nũneenete ũu.'),
('kam', 'ISA', 25, 9, 'Na kũkaneenwa mũthenya ũsu, Sisya, ũũ nĩwe Ngai waitũ, nĩtwamweteelile, nake akatũtangĩĩa: ũũ nĩwe Yeova; nĩtwamweteelile, tũkeethĩwa na mũyo na kũtana ũtangĩĩonĩ wake.'),
('kam', 'ISA', 25, 10, 'Nũndũ kw’oko kwa Yeova kũkekalaa kĩĩmanĩ kĩĩ; na Moavi ĩkakinyangĩwa nthĩ vandũ vayo, o tondũ ũa ũkinyangĩawa ũtũndanĩ wa kyaa.'),
('kam', 'ISA', 25, 11, 'Nake akatambũũkya moko make katĩ wayo, otondũ mũthambĩĩ ũtambũũkasya moko make athambĩe; ĩndĩ Yeova akatheesya ngathĩĩo yayo vamwe na ũĩ wa moko mayo.'),
('kam', 'ISA', 25, 12, 'Na ngome ndũlu ya maũvai maku nũmĩtheeetye, nũmĩvalũkĩtye, na nũmĩkĩtye nthĩ, o kũvika kĩtoonĩ.'),
('kam', 'ISA', 26, 1, 'Mũthenya ũsu wathi ũũ ũkainwa nthĩ ya Yuta: Twĩ na ndũa yĩ vinya; akaia ũtangĩĩo wĩthĩwe maũvai na ngome.'),
('kam', 'ISA', 26, 2, 'Vingũai mbingĩlo, nĩ kana mbaĩ ndũngalu ĩla ĩlũmasya mũĩkĩĩo ĩtonye kũlika.'),
('kam', 'ISA', 26, 3, 'Ũkamwĩkalya e mũuonĩ mwĩanĩu we ũla kĩlilikano kyake kĩlũlũmĩle kwaku we; nũndũ nũkũĩkĩĩaa.'),
('kam', 'ISA', 26, 4, 'Mũĩkĩĩeĩ Yeova tene na tene; nũndũ nthĩnĩ wa Yeova, O Yeova, nĩ ĩvia ya tene na tene.'),
('kam', 'ISA', 26, 5, 'Nũndũ nũmatheeetye ala mekalaa ĩũlũ, ndũa mbũkĩlu: nũmĩvalũkĩtye, o na nũmĩvalũkĩtye, kũvika nthĩ, nũmĩvikĩtye o kũvika kĩtoonĩ.'),
('kam', 'ISA', 26, 6, 'Ũnyaĩĩ ũkamĩkinyanga; o na nyaĩĩ sya ngya, na matambya ma ala athĩni.'),
('kam', 'ISA', 26, 7, 'Nzĩa ya ala alũngalu nĩ ya ũlũngalu: we ũla wĩ mũlũngalu nũmũlũngalĩlasya ũla mũlũngalu mũendele wake.'),
('kam', 'ISA', 26, 8, 'Ĩĩ, nzĩanĩ ya motw’ĩo maku, ame Yeova, nĩtwakweteelile; kwenda kwa ngoo sitũ nĩkwelekele syĩtwa yaku, o yĩla ya kũlilikanwa.'),
('kam', 'ISA', 26, 9, 'Nĩnakwendie na ngoo yakwa ũtukũ; ĩĩ, ngakũmantha na kĩthing’ĩĩsyo na veva wakwa ũla wĩ nthĩnĩ wakwa: nũndũ yĩla mosilĩlo maku me kũũ nthĩ, ala matwĩe nthĩ memanyĩasya ũlũngalu.'),
('kam', 'ISA', 26, 10, 'Ũseo wonanw’e kwa ũla mũthũku, ĩndĩ ndakemanyĩsya ũlũngalu; e nthĩ ya ũlũngalu akeekaa naĩ, na ndakona ũnene wa Yeova.'),
('kam', 'ISA', 26, 11, 'Yeova, kw’oko kwaku nĩ kũkĩlu, o na matyonaa: ĩndĩ makoona kĩwĩu kyaku kwondũ wa andũ, nao makasonokw’a; ĩĩ, mwaki ũkamina nthũ syaku.'),
('kam', 'ISA', 26, 12, 'Yeova, ũkatũtw’ĩĩa mũuo; nũndũ nue wĩkĩte mawĩa maitũ onthe kwondũ witũ.'),
('kam', 'ISA', 26, 13, 'Ame Yeova Ngai waitũ, eaĩi angĩ ate o we nĩmatũsumbĩkie; ĩndĩ we wĩ weka tũkawetaa syĩtwa yaku.'),
('kam', 'ISA', 26, 14, 'Nĩ akw’ũ, matikethĩwa thayũ; nĩmakwie, matikathayũũka; kwondũ wa ũu nĩwamavikĩie na kũmananga, na ũlilikano w’onthe ũndũ woo nũwanangĩte.'),
('kam', 'ISA', 26, 15, 'Nũmyongelete ĩ mbaĩ, ame Yeova, nũmyongelete ĩ mbaĩ; nũtaĩĩtwe; nĩwongelete mĩvaka yonthe ya ĩ nthĩ.'),
('kam', 'ISA', 26, 16, 'Yeova, nĩmookie kwaku me thĩnanĩ; nĩmeekaĩlile na mboya yĩla wamakũnaa.'),
('kam', 'ISA', 26, 17, 'Ta mũndũ mũka mũito, ũla ũthengeesye ĩvinda ya kũsyaa, e na woo na nũĩaa kwaũnyanĩ kwake; now’o twailyĩ mbee waku, ame Yeova.'),
('kam', 'ISA', 26, 18, 'Twaĩ aito, twaĩ na woo, twailyĩ ta twasyaa kĩseve; tũtyaaseũvĩsya nthĩ ũvonokyo; o na ala ma kũtũa nthĩ matyaasyawa.'),
('kam', 'ISA', 26, 19, 'Akw’ũ maku makeethĩwa thayũ; simba syakwa ikookĩla. Amũkaĩ mwine, inyw’ĩ ala mũtũaa kĩtoonĩ; nũndũ ĩmwe yaku nĩ ta ĩmwe yĩ nyũnyinĩ, na nthĩ ĩkaumya ala akw’ũ.'),
('kam', 'ISA', 26, 20, 'Ũkaĩ, andũ makwa, lika tũsũmbanĩ twaku, noivinga mĩomo yaku: ĩvithe kavinda kanini, kũvika ũthatu ũvĩte.'),
('kam', 'ISA', 26, 21, 'Nũndũ, sisya, Yeova nĩwumĩte vandũ vake akũne ala matwĩe nthĩ nũndũ wa ũthũku woo: nthĩ nayo ĩkavua nthakame yayo yoneke, na ndĩkambĩla kũvw’ĩka andũ mayo ala mooaiwe.'),
('kam', 'ISA', 27, 1, 'Mũthenya ũsu Yeova e na ũvyũ wake mwetu na mũnene na wĩ vinya akasilĩla leviathani ĩla nzoka ya kũnyoloka mĩtũkĩ, na leviathani ĩla nzoka ĩendaa ĩkĩmilanga; na akooaa mũkũnga wĩ ũkanganĩ.'),
('kam', 'ISA', 27, 2, 'Mũthenya ũsu: Mũũnda wa mĩsavivũ, mwĩwinĩa.'),
('kam', 'ISA', 27, 3, 'Nyie Yeova nĩ mũsũvĩi waw’o; ngoonyithya kĩla kavinda: mũndũ ndakese kũwananga, ngoosũvĩa ũtukũ na mũthenya.'),
('kam', 'ISA', 27, 4, 'Kũthilĩka kũti nthĩnĩ wakwa: nenda kethĩwa mĩtae na mĩw’a niũmbũkita kaũnĩ! Ngaiendea, ngaivĩvya vamwe.'),
('kam', 'ISA', 27, 5, 'Ethĩwa ti ũu nakwate vinya wakwa, nĩ kana aseũvye mũuo nakwa; ĩĩ, naseũvye mũuo nakwa.'),
('kam', 'ISA', 27, 6, 'Mĩthenya ĩla yũkĩte Yakovo akatambũũkya mĩi; Isilaeli akalaũka na kũthongooa; na makausũsya nthĩ ũsyao.'),
('kam', 'ISA', 27, 7, 'Nũmakũnĩte o tondũ wakũnie asu ala mamakũnie? Kana nĩmooaiwe kwĩanana na kũawa kwa ala mooaiwe nĩmo?'),
('kam', 'ISA', 27, 8, 'Yĩla ũmalũngya, nũkĩlanasya vinya nao ũthimĩte; nũmavetete na kĩseve kyake kĩ vinya mũthenya wa kĩseve kyumĩte wumĩlonĩ wa syũa.'),
('kam', 'ISA', 27, 9, 'Kwondũ wa ũu ũthũku wa Yakovo ũkaekwa, na ũu nĩw’o ũsyao w’onthe wa mũvetelwe wa naĩ yake: nũtw’ĩkĩthasya mavia onthe ma kĩthembeo ta mavia ma sokaa ala mavevenzetwe ilungu, nĩ kana Aselimu na mĩvw’anano ya syũa ndĩkaaũkĩle ĩngĩ.'),
('kam', 'ISA', 27, 10, 'Nũndũ ĩla ndũa mbiie ĩtiĩtwe yĩ yoka, ũtũo ũketwe na nĩ ĩanzo, ta weũ: kasaũ kakaĩthw’a kw’o, na kakatindia kw’o, na kũya mbonge sya kw’o.'),
('kam', 'ISA', 27, 11, 'Mbonge sya kw’o syavova, ikatũlwa, aka makooka na kwivĩvya, nũndũ nĩ andũ mate na ũmanyi: kwondũ wa ũu ũla wamombie ndakamew’ĩa ĩnee, na ũla wamombie ndakamon’ya ũseo.'),
('kam', 'ISA', 27, 12, 'Na kũkethĩwa mũthenya ũsu, Yeova akavũa ngetha yake kuma ũla Ũsĩ ũvingu kũvika kalũsĩ ka Misili; na inyw’ĩ mũkoombanw’a ũmwe na ũmwe, inyw’ĩ ana ma Isilaeli.'),
('kam', 'ISA', 27, 13, 'Na kũkethĩwa mũthenya ũsu, soo mũnene ũkavuvwa, na ala makilĩlye kwanangĩkĩa nthĩ ya Asuli, na ala maĩ alũngw’a nthĩ ya Milili makooka, na makamũthaitha Yeova kĩĩmanĩ kĩtheu ku Yelusaleme.'),
('kam', 'ISA', 28, 1, 'Woo nĩ wa ngovia ya ũsumbĩ ya ngathĩĩo ya athengi ma Evalaimu, na wa ĩlaa ĩvovu ya ũseo wake wa ndaĩa, yĩla yĩ mũtweni wa mwanda mũnou wa ala mamilĩtwe nĩ mbinyu!'),
('kam', 'ISA', 28, 2, 'Sisya, Mwĩaĩi e na ũmwe wĩ na ũtonyi na vinya; o ta kĩuutani kya mbua ya mavia, kĩuutani kĩnene kĩla kyanangaa, ta kĩuutani kya manzĩ me vinya mavingĩte na kũkĩla, akekya nthĩ na kw’oko.'),
('kam', 'ISA', 28, 3, 'Ngovia ya ũsumbĩ ya ngathĩĩo ya athengi ma Evalaimu ĩkakinyangwa na nyaĩĩ:'),
('kam', 'ISA', 28, 4, 'na ĩlaa ĩvovu ya ũseo wake wa ndaĩa, yĩla yĩ mũtwenĩ wa mwanda mũnou, yĩkeethĩwa ta ĩkũyũ yila yambaa kwĩw’a mũniino ũtanavika; nayo ũla wĩyĩsisya ayona, o yĩ kw’okonĩ kwake akĩya.'),
('kam', 'ISA', 28, 5, 'Mũthenya ũsu Yeova wa nguthu akatw’ĩka ngovia ya ũsumbĩ ya ndaĩa, na ngovia ya kwanakava kwa ũtialo wa andũ make;'),
('kam', 'ISA', 28, 6, 'na veva wa kũsila katĩ kwa ũla wĩkalaa aisila, na vinya kwa ala matũngaa kaũ wĩ mbingĩlonĩ.'),
('kam', 'ISA', 28, 7, 'Ĩndĩ o na aa nao maendaa mailũw’a nĩ mbinyu, na kũlulutĩkaw’a nĩ kĩla kĩtoonasya; mũthembĩ na mwathani malũaw’a nĩ kĩla kĩtoonasya, nĩmameeletw’e nĩ mbinyu, nĩmalulutĩkw’a nĩ kĩla kĩtoonasya; nĩmavĩtasya kwonanĩ kwoo, nĩmalulutĩkaa motw’ĩonĩ moo.'),
('kam', 'ISA', 28, 8, 'Nũndũ mesa syonthe nĩsyusũĩtwe nĩ matavĩka na ũvuku, o na vati vandũ vatheu.'),
('kam', 'ISA', 28, 9, 'Akamanyĩsya ũmanyi aaũ? Na akamanyĩthya ũvoo aaũ? Nĩ ala maaĩĩtw’e, na kũvatwa kwonga?'),
('kam', 'ISA', 28, 10, 'Nũndũ nĩ wĩaĩo ĩũlũ wa wĩaĩo, wĩaĩo ĩũlũ wa wĩaĩo; mũsoa ĩũlũ wa mũsoa, mũsoa ĩũlũ wa mũsoa; vaa ũndũ ũnini, vaya ũndũ ũnini.'),
('kam', 'ISA', 28, 11, 'Aiee, ĩndĩ akaneena na andũ aa na ilomo ngeni na ũĩmĩ ũngĩ;'),
('kam', 'ISA', 28, 12, 'ala wameie, Ũũ nĩw’o ũthũmũo, mũnengei ũthũmũo ũla ũnoete; na ũũ nĩw’o ũvuũkyo: ĩndĩ matyaaĩw’a.'),
('kam', 'ISA', 28, 13, 'Kwondũ wa ũu ndeto ya Yeova ĩkeethĩwa kwoo wĩaĩo ĩũlũ wa wĩaĩo, wĩaĩo ĩũlũ wa wĩaĩo; mũsoa ĩũlũ wa mũsoa, mũsoa ĩũlũ wa mũsoa, vaa ũndũ ũnini, vaya ũndũ ũnini; nĩ kana maende, na kũvalũka na ngala, na kũtũlĩka, na kũtewa, na kũkwatw’a.'),
('kam', 'ISA', 28, 14, 'Kwondũ wa ũu ĩw’ai ndeto ya Yeova, inyw’ĩ akaakaan’ya, ala mũsumbĩkaa andũ aa ala me Yelusaleme:'),
('kam', 'ISA', 28, 15, 'Nĩkwĩthĩwa nĩmwaĩtye, Nĩtũtianĩĩte ũtianĩo na kĩkw’ũ, na nĩtwĩw’anĩte na Seoli; yĩla ũthĩn’yo wũkĩlanĩtye wĩvĩtĩla katĩ, ndũkatũvikia; nũndũ nĩtwatwie movũngũ wĩvitho witũ, na nĩtweevithie ungu wa ũvũngũ:'),
('kam', 'ISA', 28, 16, 'kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ, Sisya, nĩngwia nthĩnĩ wa Saioni ĩvia yĩthĩwe wambĩlĩlyo, ĩvia ĩtate, ĩvia ya kĩkotonĩ yĩ vata mũno ya wambĩlĩlyo mũlũmu: ũla wĩtĩkĩlaa ndakekalaata.'),
('kam', 'ISA', 28, 17, 'Na ngatw’ĩkĩthya ũsili wa katĩ ũlii wa kũthima, na ũlũngalu nĩw’o kavilũ; na mbua ya mavia ĩkatwaa ũla wĩvitho wa movũngũ, na manzĩ makakĩla vandũ va kwĩvitha.'),
('kam', 'ISA', 28, 18, 'Na ũtianĩo wenyu ũla mwatianĩe na kĩkw’ũ ũkaanangwa, na wĩw’ano wenyu ũla mweew’anie na Seoli ndũkaũngama; yĩla ũthĩn’yo wũkĩlanĩtye wĩvĩtĩla katĩ, nĩvo ĩndĩ mwĩkinyangwa nĩw’o.'),
('kam', 'ISA', 28, 19, 'O yĩla wĩvĩtĩla katĩ, ũkakũkwata; nũndũ ũkavĩtĩla kĩoko na kĩoko, mũthenya na ũtukũ; na kũkeethĩwa no ũtĩsyo mũthei kũmanya ũvoo ũsu.'),
('kam', 'ISA', 28, 20, 'Nũndũ ũkomo nĩ mũkuvĩ ũndũ mũndũ ũtatonya kwĩkootea ĩũlũ waw’o; na ngũa ya kwĩvw’ĩka nĩ ntheke ũndũ ũtatonya kwĩlingĩlĩĩla.'),
('kam', 'ISA', 28, 21, 'Nũndũ Yeova akookĩla o tondũ wekie kĩĩmanĩ kya Velasimu, na akathilĩka o tondũ wekie mwandanĩ wa Ngiveoni; nĩ kana atethye wĩa wake, wĩa wake mũeni, na kwĩkĩthya wĩko wake, wĩko wake mũeni.'),
('kam', 'ISA', 28, 22, 'Kwondũ wa ũu mũtikethĩwe akaakaan’ya, syĩndũ ila mwovetwe nasyo itikese kwongelwa vinya; nũndũ nĩnĩw’ĩte ũtw’ĩo wa wanangĩko kuma kwa Mwĩaĩi, Yeova wa nguthu, ĩũlũ wa nthĩ yonthe.'),
('kam', 'ISA', 28, 23, 'Teai matũ, mwĩw’e wasya wakwa; ĩthukĩĩsyei, mwĩw’e kũneena kwakwa.'),
('kam', 'ISA', 28, 24, 'Ũla wĩnzaa avande nĩwĩnzaa mavinda onthe? Nĩwũkĩlasya na kũvukũlya nthĩ yake mavinda onthe?'),
('kam', 'ISA', 28, 25, 'Amina kwĩanan’ya ũthyũ wayo, ndavuĩaa kesa, na kũvuĩa kumini, na kũvanda nganũ mĩselele, na mbaale kũndũ kũtw’e, na kusemethu mũvakanĩ wayo?'),
('kam', 'ISA', 28, 26, 'Nũndũ Ngai wake nũmũmanyĩasya nesa, na kũmwon’ya.'),
('kam', 'ISA', 28, 27, 'Nũndũ kesa ndĩvũawa na kĩndũ kyũĩ, o na ndĩa ya ĩkasya ndĩvingilitaw’a ĩũlũ wa kumini; ĩndĩ kesa nĩvũawa na mũvũi, na kumini na mũvũi.'),
('kam', 'ISA', 28, 28, 'Nganũ ya kũseũvya kĩmũtũ nĩthiawa; nũndũ ndekwenda kwĩkalaa aimĩvũa mavinda onthe; o na kau ndĩa ya ĩkasya yake na mbalasi syake nimĩnyaĩĩkasya, ndamĩthiaa.'),
('kam', 'ISA', 28, 29, 'Ũndũ ũsu naw’o nĩwumĩte kwa Yeova wa nguthu, ũla wa ũseng’yo ũtaonĩ, na mũnene ũĩnĩ.'),
('kam', 'ISA', 29, 1, 'We, Alieli, Alieli ndũa ĩla Ndaviti wambie maeema make! Ongelai mwaka na mwaka; syathĩ sya mboka niatĩanĩe:'),
('kam', 'ISA', 29, 2, 'nĩvo ĩndĩ nĩthĩn’ya Alieli, na kũkeethĩwa kĩmeto na kĩĩo, ĩndĩ ĩkeethĩwa kwakwa ta Alieli.'),
('kam', 'ISA', 29, 3, 'Na ngamba maeema makwa makũthyũlũlũkĩte, na ngakũtw’ĩkanĩsya na nguthu sya asikalĩ maiĩtwe, na ngaaka ngome sya ũkũtw’ĩkanĩsya.'),
('kam', 'ISA', 29, 4, 'Naku ũkatheew’a nthĩ, na ũkaneena wĩ nthĩ, na kũneena kwaku kũkeethĩwa kwĩ ĩtheo kĩtoonĩ; na wasya waku ũkeethĩwa ta wa mũndũ ũla wĩsene na veva, ũkyuma mũthanganĩ, na kũneena kwaku kũkanyiila kuma kĩtoonĩ.'),
('kam', 'ISA', 29, 5, 'Ĩndĩ wingĩ wa amaitha maku ũkeethĩwa ta kĩtoo kĩvinyu mũno, na wingĩ wa ala ma kũtĩsya ta wewa ũla ũvĩtaa: ĩĩ, ũu ũkeethĩwa na mĩtũkĩ ta kĩthũlũmũko.'),
('kam', 'ISA', 29, 6, 'Ĩkookĩwa nĩ Yeova wa nguthu e na kĩtundumo, na kĩtetemo kya, nthĩ, na kĩlonzo kĩnene, vamwe na kĩlingi na kĩuutani, na kĩtw’ĩki kya mwaki ũla ũvĩvasya.'),
('kam', 'ISA', 29, 7, 'Na wingĩ wa mbaĩ syonthe ila syũkitaa na Alieli, o syonthe ila syũkitaa nayo na ngome yayo yĩ vinya, na ila imĩthĩnasya, ikeethĩwa ta ndoto, woni wa ũtukũ.'),
('kam', 'ISA', 29, 8, 'Na kũkeethĩwa ta mũndũ wĩ nzaa aiota ndoto, na, sisya, akyona ta ũnũũya; ĩndĩ aamũka, thayũ wake nĩ mũthei: kana ta mũndũ wĩ na waũni aiota ndoto, na, sisya, akyona ta ũnũũnyw’a; ĩndĩ aamũka na, sisya, nĩ mũnyalu, na thayũ wake wĩ na nzaa: now’o wingĩ wa mbaĩ syonthe ũkethĩwa ũilyĩ, ũla wũkitaa na kĩĩma kya Saioni.'),
('kam', 'ISA', 29, 9, 'Eteelai mũseng’e; ĩtanĩthyei na mũkĩthĩwa ililinda: nĩmatoonetw’e, ĩndĩ ti ũndũ wa mbinyu; nĩmalũaa, ĩndĩ ti ũndũ wa kĩla kĩtoonasya.'),
('kam', 'ISA', 29, 10, 'Nũndũ Yeova nũmũtulũlĩte veva wa too mũnene, na mũlalĩtye metho menyu, ala athani; na nũvw’ĩkĩte atongoi menyu, ala monaa mawoni.'),
('kam', 'ISA', 29, 11, 'Na woni w’onthe nũtw’ĩkĩte kwenyu ta ndeto sya ĩvuku yĩla yĩvingĩtwe yĩkasiĩlwa, yĩla andũ mamũnenga mũndũ ũla ũmanyĩĩtw’e mũno, makĩmwĩa, Soma yĩĩ, nĩngũkwĩsũva; nake asya, Nditonya, nũndũ yĩvingĩtwe yĩkasiĩlwa:'),
('kam', 'ISA', 29, 12, 'na ĩvuku yĩienengwa ũla ũtamanyĩĩtw’e, makĩmwĩa, Soma yĩĩ, nĩngũkwĩsũva, nake asya, Ndimanyĩĩtw’e.'),
('kam', 'ISA', 29, 13, 'Na Mwĩaĩi asya, Nĩkwĩthĩwa andũ aa nĩmanthengeeaa, na nĩmandaĩaa na kanyw’a woo na ilomo syoo, ĩndĩ nĩmavetete ngoo syoo kũasa nakwa, na kũngĩa kwoo nĩ mwĩao wa andũ ũla mamanyĩĩtw’e;'),
('kam', 'ISA', 29, 14, 'kwondũ wa ũu, sisya, ngaendeea kũtethya wĩa wa ũseng’ya katĩ wa andũ aa, o wĩa wa ũseng’ya na wa kũmakya; na ũĩ wa andũ moo oĩ ũkaa, na ũmanyi wa andũ moo me kĩlĩko ũkavithwa.'),
('kam', 'ISA', 29, 15, 'Woo nĩ wa ala mamũvithaa Yeova maũndũ moo mũno, na mawĩa moo me kĩvindunĩ, maiasya, Nũũ ũla ũtwonaa? Na nũũ ũla ũtwĩsĩ?'),
('kam', 'ISA', 29, 16, 'Inyw’ĩ nĩmũkulumanasya maũndũ! Mũmbi akatalwa ta yũmba, kana kĩndũ kĩla kyoombiwe kĩkasya ũndũ wa ũla wakyũmbie, Ndaambũmba; kana kĩla kyoombiwe kĩkasya ũndũ wa ũla wakyũmbie, Nde na ũmanyi?'),
('kam', 'ISA', 29, 17, 'Ti kavinda kanini mũno, na Levanoni ĩkĩalyũlwa ĩtw’ĩke mũũnda wĩ ũsyao, na mũũnda wĩ ũsyao ũkĩtalwa ta mũtitũ?'),
('kam', 'ISA', 29, 18, 'Na mũthenya ũsu ala au matũ makeew’a ndeto sya yĩla ĩvuku, na metho ma ala matonaa makoona kuma mbindunĩ na kĩvindunĩ.'),
('kam', 'ISA', 29, 19, 'Na ala auu nao makaingĩvya ũtanu woo nthĩnĩ wa Yeova, na ala ngya katĩ wa andũ makatanĩa Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 29, 20, 'Nũndũ ũla wa kũtĩsya nũtw’ĩtwe wa mana, na ũla mũkaakaasya nũekete, na onthe ala meteelaa ũthũku nĩmavetetwe;'),
('kam', 'ISA', 29, 21, 'ala mavĩtĩthasya mũndũ ndetonĩ, na kũmwiĩa kĩtei ũla ũkananasya mbingĩlonĩ, na kwathũkya ala alũngalu na ũndũ wa mana.'),
('kam', 'ISA', 29, 22, 'Kwondũ wa ũu Yeova, ũla wamwovoisye Avalaamu, easya ũndũ wa nyũmba ya Yakovo: Yũ Yakovo ndakasonoka, o na yu ũthyũ wake ndũkaalyũka.'),
('kam', 'ISA', 29, 23, 'Ĩndĩ yĩla wĩona syana syake, wĩa wa moko makwa, syĩ katĩ wake, ikoonan’ya syĩtwa yakwa nĩ ĩtheũ; ĩĩ, ikoonan’ya nĩ mũtheu Ũla Mũtheu wa Yakovo, na ikamũkĩa Ngai wa Isilaeli.'),
('kam', 'ISA', 29, 24, 'Nao ala mavĩtasya vevanĩ makamanya, na ala manyungunyĩasya makeetĩkĩla kũmanyĩw’a.'),
('kam', 'ISA', 30, 1, 'Woo nĩ wa syana ng’endu, easya Yeova, ila ĩsũanĩaa maũndũ, ĩndĩ ti kuma kwakwa, na ila iseũvasya wĩw’ano, ĩndĩ ti wa Veva wakwa, nĩ kana syongelele naĩ ĩũlũ wa naĩ;'),
('kam', 'ISA', 30, 2, 'ila ikũasya itheee Misili, na ityaakũlya kanyw’anĩ wakwa; syĩyĩkĩe vinya vinyanĩ wa Valao, na syĩvithe muunyĩnĩ wa Misili!'),
('kam', 'ISA', 30, 3, 'Kwondũ wa ũu vinya wa Valao ũkeethĩwa nthoni syenyu, na wĩvitho muunyĩnĩ wa Misili kũthokoanw’a kwenyu.'),
('kam', 'ISA', 30, 4, 'Nũndũ anene moo me mbee ũsumbĩnĩ ma Nzoanĩ, na atũmwa moo mavikĩte Anise.'),
('kam', 'ISA', 30, 5, 'Onthe makasonoka nũndũ wa andũ ala matatonya kũmauna, ala mate ũtethyo kana ũuno, ĩndĩ nthoni, o na ũvũthyo.'),
('kam', 'ISA', 30, 6, 'Ndeto ngito ũndũ wa nyamũ sya ngalĩ ya Ĩtheo. Mavĩtĩlaa nthĩ ya thĩna na woo, vala vaumaa mũnyambũ mũka na mũnyambũ, nzoka mbai na nzoka ĩũlũkaa ĩilyĩ mwaki, makĩkua mothwii moo ituonĩ sya ndena sya mang’oi, na mothwii moo ngathĩnĩ sya ngamĩle, mamatwaĩe andũ ala matakamauna.'),
('kam', 'ISA', 30, 7, 'Nũndũ ũtethyo wa Misili nĩ wa mana, na ndwaĩlaa; kwondũ wa ũu nĩnĩmĩtĩte Misili Laavi, mwĩkali wa nthĩ.'),
('kam', 'ISA', 30, 8, 'Yu enda, ũandĩke ĩsengeanĩ mene, na ũivana ĩvukunĩ, nĩ kana wĩthĩwe wa ĩvinda yĩla yũkĩte tene na tene.'),
('kam', 'ISA', 30, 9, 'Nũndũ nĩ andũ ang’endu, syana ila ineenaa movũngũ, syana ila ileaa kwĩthukĩĩsya mĩao ya Yeova;'),
('kam', 'ISA', 30, 10, 'ila itavasya ala monaa mawoni, Ekai kwona; na athani, Ekai kũtwathanĩa maũndũ ma w’o, tũtavye maũndũ maseo, athanai mokengani,'),
('kam', 'ISA', 30, 11, 'umai nzĩanĩ, athũkai nzĩanĩ, mũekethyei Ũla Mũtheu wa Isilaeli ndakethĩwe mbee waitũ.'),
('kam', 'ISA', 30, 12, 'Kwondũ wa ũu Ũla Mũtheu wa Isilaeli easya atĩĩ, Nĩkwĩthĩwa nĩmũvũthasya ndeto ĩno, na kwĩkwatya ũndũ wa kũthĩn’ya na wa ngũlũ, na kwĩlũmya nthĩnĩ wamo;'),
('kam', 'ISA', 30, 13, 'kwondũ wa ũu ũthũku ũsu ũkeethĩwa kwenyu ta vandũ vatũku vakilĩlye kũvalũka, vandũ veeku ũvainĩ mũtũlu, ũla kũvalũka kwaw’o kwĩũka na mĩtũkĩ ta kĩthũlũmũko.'),
('kam', 'ISA', 30, 14, 'Na akamyananga o tondũ mũio wa mũmbi wũaawa, akyũvevenza vate kũsũvĩa; nĩ kana kũikoneke katĩ wa ilĩo syaw’o kalĩo ka kwoka mwaki ikonĩ, kana ka kũtava manzĩ kĩthimanĩ.'),
('kam', 'ISA', 30, 15, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova, Ũla Mũtheu wa Isilaeli, waisye, Kũsyokanĩ na kũthũmũanĩ mũkatangĩĩwa; ũuunĩ na wĩkwatyonĩ kũkeethĩwa vĩnya wenyu. Na inyw’ĩ mũtyaaĩtĩkĩla:'),
('kam', 'ISA', 30, 16, 'ĩndĩ mwasya, Aiee, ĩndĩ tũkakĩa tũkuĩtwe nĩ mbalasi; kwondũ wa ũu mũkakĩa: na mwasya, Tũkaenda tũtũlĩte ila syĩ mĩtũkĩ; kwondũ wa ũu ala makamũatĩĩa makeethĩwa me mĩtũkĩ.'),
('kam', 'ISA', 30, 17, 'Ngili ĩmwe ĩkakĩa ũndũ wa kũkandĩwa nĩ ũmwe; ũndũ wa kũkandĩwa nĩ atano inyw’ĩ mũkakĩa: kũvika mwĩtiwa ta mũtĩ mũasa kĩĩmanĩ ĩũlũ, na ta kĩvevelo kalĩmanĩ.'),
('kam', 'ISA', 30, 18, 'Na kwondũ wa ũu Yeova aketeela, nĩ kana amwĩke nesa; na kwondũ wa ũu akanenevw’a, nĩ kana amwĩw’ĩe tei: nũndũ Yeova nĩ Ngai ũla ũsilaa katĩ; nĩ aathime onthe ala mamweteelaa.'),
('kam', 'ISA', 30, 19, 'Nũndũ andũ makekala Saioni ku Yelusaleme; ndũkaĩa ĩngĩ; vate ndĩi akakwĩka nesa ũndũ wa wasya wa kĩĩo kyaku; yĩla wĩĩw’a akakũsũngĩa.'),
('kam', 'ISA', 30, 20, 'O na ethĩwa Mwĩaĩi nũkũnengae lĩu wa thĩna na manzĩ ma woo, ĩndĩ amanyĩsya maku matikavithwa ĩngĩ, ĩndĩ metho maku makoona amanyĩsya maku;'),
('kam', 'ISA', 30, 21, 'na matũ maku makeew’a ndeto ĩtina waku, ĩkyasya, Nzĩa nĩ ĩno, endaai nayo; yĩla mwĩathũka kw’oko kwa aũme, na yĩla mwĩathũka kw’oko kwa aka.'),
('kam', 'ISA', 30, 22, 'Na mũkavukya kĩla kĩvw’ĩkĩte mĩvw’anano yaku ya vetha, na kwanakavw’a kwa mĩvw’anano yaku ya thaavu ĩla yaseũviw’e na syĩndũ ila syatwekethiw’e: ũkamĩkya kũasa ta kĩndũ kĩvuku; ũkootavya, Uma vaa.'),
('kam', 'ISA', 30, 23, 'Nake akanenganae mbua kwondũ wa mbeũ syaku, ila wĩvanda nthĩ; na lĩu wa ũsyao wa nthĩ, na ũkeethĩwa mũnou na mwingĩ. Mũthenya ũsu indo syaku ikaĩthaw’a isesinĩ nene;'),
('kam', 'ISA', 30, 24, 'o ta ũu ng’ombe na ndena sya mang’oi ila iĩmaa nthĩ ikaĩsaa lĩu wĩ mũsamo, ũla ũũlũkĩtw’e na mwĩko na kĩũlũkya.'),
('kam', 'ISA', 30, 25, 'Na ĩũlũ wa kĩla kĩĩma kĩtũlu, na ĩũlũ wa kĩla kalĩma katũlu, kũkeethĩwa tũlũsĩ na mbũsĩ sya manzĩ, mũthenya wa ũaani mũnene, yĩla myako mĩtũlu ya mĩnyoolo ĩvalũka.'),
('kam', 'ISA', 30, 26, 'O na ũndũ ũngĩ kyeni kya mwei kĩkatw’ĩka ta kyeni kya syũa, na kyeni kya syũa kĩkeethĩwa kũndũ mũonza, ta kyeni kya mĩthenya mũonza, mũthenya ũla Yeova wĩova ĩkũna ya andũ make, na kũvosya ĩkũna ya wũkite woo.'),
('kam', 'ISA', 30, 27, 'Sisya, syĩtwa ya Yeova nĩyũkĩte kuma kũasa, yakanĩte na ũthatu wake, nthĩnĩ wa syũki yingĩ yĩkyũkĩla: ilomo syake nĩsyusĩe ũthilĩku, na ũĩmĩ wake nĩ ta mwaki ũvĩvasya;'),
('kam', 'ISA', 30, 28, 'na mĩthũmũ yake nĩ ta ũsĩ ũvingĩte ũkakĩla, ũla ũvikaa ngingonĩ, asunge mbaĩ na kĩsungi kya wanangĩko: na mũkwa ũla ũvĩtĩthasya ũkeethĩwa ngambuunĩ sya ngoo sya andũ.'),
('kam', 'ISA', 30, 29, 'Mũkeethĩwa na wathi o ta ũtukũ yĩla mũlilikanaa mboka ntheu; na ũtanu wa ngoo, ta yĩla mũndũ ũendaa na mũtũlilũ avike kĩĩma kya Yeova, kũvika Ĩvia ya Isilaeli.'),
('kam', 'ISA', 30, 30, 'Na Yeova akatuma wasya wake mũseo wĩw’ĩka, na akoonan’ya kũtheesya kwa kw’oko kwake, vamwe na kũthilĩka kwa ũthatu wake, na kĩtw’ĩki kya mwaki ũla ũvĩvasya, na wanango, na kĩuutani, na mbua na mavia.'),
('kam', 'ISA', 30, 31, 'Nũndũ kwondũ wa wasya wa Yeova Mũasuli akateva; akamũkũna na ndata yake.'),
('kam', 'ISA', 30, 32, 'Na kĩla ĩkũna ya ndata nyuve, yĩla Yeova wĩmũkũna, yĩkeethĩwa vamwe na wasya wa tũthembe na mbeve; na akokita nao kaũnĩ wa kũthingithangya.'),
('kam', 'ISA', 30, 33, 'Nũndũ Tovethi nĩvaseũviw’e kuma tene; ĩĩ, nĩvaseũviw’e ũndũ wa mũsumbĩ; nũseũvĩtye vethĩwe valiku na vanene; ĩvuvĩo ya vo nĩ mwaki wĩ ngũ nyingĩ; mĩthũmũ ya Yeova, ta kalũsĩ ka mũvĩlĩtĩ, nĩnĩkwakan’ya.'),
('kam', 'ISA', 31, 1, 'Woo nĩ wa ala matheeaa Misili mone ũtethyo, na kwĩkwatya mbalasi, na kwĩkwatya makasya nĩkwĩthĩwa nĩ maingĩ, na andũ matũlĩte mbalasi nĩkwĩthĩwa me vinya mũno, ĩndĩ matiũsisya Ũla Mũtheu wa Isilaeli, kana kũmantha Yeova!'),
('kam', 'ISA', 31, 2, 'Ĩndĩ nake nĩ mũĩ, na akaete ũthũku, na ndakaalyũla ndeto syake, ĩndĩ akamyũkĩlĩla nyũmba ya eki ma naĩ, o na akookĩlĩla ũtethyo wa ala mekaa ũthũku.'),
('kam', 'ISA', 31, 3, 'Ĩndĩ Amisili nĩ andũ, o na ti Ngai; na mbalasi syoo nĩ nyama na ti veva: na yĩla Yeova wĩtambũũkya kw’oko kwake, ũla ũtethanasya akalulutĩka, o na ũla ũtethaw’a akavalũka, na onthe makaminwa vamwe.'),
('kam', 'ISA', 31, 4, 'Nũndũ ũũ nĩw’o Yeova ũnũũmbĩa, O tondũ mũnyambũ vamwe na mũnyambũ wa mũika ũlulumaa ũtũlĩte, ethĩwa aĩthi aingĩ makeetwa maende kũwũkita, ũtatevaa kwondũ wa mawasya moo, o na ũtenyivasya kwondũ wa kĩlonzo kyoo: o ta ũu Yeova wa nguthu akatheea okite kĩĩmanĩ kya Saioni, na kalĩmanĩ kakyo.'),
('kam', 'ISA', 31, 5, 'O tondũ nyũnyi ilelaa, o ta ũu Yeova wa nguthu akasũvĩa Yelusaleme; akamĩsũvĩa na kũmĩvonokya, akavĩtĩla ĩũlũ na kũmĩsũvĩa.'),
('kam', 'ISA', 31, 6, 'Mũsyokeei ũla mwamũng’endeie mũno, inyw’ĩ ana ma Isilaeli.'),
('kam', 'ISA', 31, 7, 'Nũndũ mũthenya ũsu makekya kĩla mũndũ mĩvw’anano yake ya vetha, na mĩvw’anano yake ya thaavu, ĩla moko menyu ene maseũvĩsye yĩthĩwe naĩ kwenyu.'),
('kam', 'ISA', 31, 8, 'Na Mũasuli akavalũkw’a na ũvyũ, naw’o ti wa mũndũ; na ũvyũ, naw’o ti wa andũ, ũkamũmina; na akakũka akĩe ũvyũ, na anake make makeethĩwa ngombo.'),
('kam', 'ISA', 31, 9, 'Na ĩvia yake yĩkavĩta ũndũ wa kũtĩsw’a, na anene make me mbee ũsumbĩnĩ makateva ũndũ wa kĩvevelo, easya ũu Yeova, ũla mwaki wake wĩ Saioni, na iko yake ĩnene yĩ Yelusaleme.'),
('kam', 'ISA', 32, 1, 'Sisya, mũsumbĩ akasumbĩka na ũlũngalu, na anene me mbee ũsumbĩnĩ makasumbĩka na kũsilaa katĩ.'),
('kam', 'ISA', 32, 2, 'Na mũndũ akeethĩwa ta vandũ va kwĩvitha kĩseve, na ta kwĩvitha kĩuutani, ta tũlũsĩ twa manzĩ vandũ vomũ, ta muunyĩ wa ĩvia ĩnene yĩ nthĩ yĩ mĩnoo.'),
('kam', 'ISA', 32, 3, 'Na metho ma ala monaa matikethĩwa mbindu, na matũ ma ala mew’aa makethukĩĩasya.'),
('kam', 'ISA', 32, 4, 'Na ngoo ya ala me mĩtũkĩ ĩkamanya ũĩ, na nĩmĩ sya ala mavũvũtaa ikeethĩwa syĩyũmbanĩtye kũneena nesa vyũ.'),
('kam', 'ISA', 32, 5, 'Ndia ndĩketwa mũnene ĩngĩ, kana ũla wĩ ĩtomo ndaketwa mũlau.'),
('kam', 'ISA', 32, 6, 'Nũndũ ndia ĩkaneena ũtumanu, na ngoo yayo ĩkeeka ũthũku, yĩkae ũvuku, na kũmũneenea Yeova ũndũ ũte wa w’o, ĩtume thayũ wa ala me na nzaa wĩthĩwa mũthei, na kũtuma kya ũnyw’a kya ala me na waũni kyaa.'),
('kam', 'ISA', 32, 7, 'Na mĩio ya ũla wĩ na ĩtomo nĩ mĩthũku: nũsũanĩaa mosũanĩo mathũku anange ala auu na ndeto sya ũvũngũ, o yĩla ala athĩni meũneena w’o.'),
('kam', 'ISA', 32, 8, 'Ĩndĩ ũla wĩ ndaĩa nũsũanĩaa maũndũ me ndaĩa; na akekalaa maũndũnĩ me ndaĩa.'),
('kam', 'ISA', 32, 9, 'Ũkĩlai, inyw’ĩ aka ala mũthũmũĩte, mwĩw’e wasya wakwa; inyw’ĩ eĩtu mũte kĩio, teai matũ menyu mwĩw’e ndeto syakwa.'),
('kam', 'ISA', 32, 10, 'Nũndũ mũkathĩnw’a mĩthenya kũvĩtũka mwaka, inyw’ĩ aka mũte kĩio; nũndũ ngetha ya mĩsavivũ ndĩkoneka, kũikethĩwa kũtusya.'),
('kam', 'ISA', 32, 11, 'Tetemai, inyw’ĩ aka ala mũthũmũĩte; ũũyai, inyw’ĩ mũte kĩio; umyai ngũa, mwĩthĩwe athei, na mũkĩvotoa makunia inyunyu syenyu.'),
('kam', 'ISA', 32, 12, 'Makakũnanga ithũi nũndũ wa mĩũnda yaĩ ya kwendeesya, na nũndũ wa mũsavivũ wasyaaa mũno.'),
('kam', 'ISA', 32, 13, 'Nthĩ ya andũ makwa ĩkamesya mĩw’a na mĩtae; ĩĩ, ĩũlũ wa nyũmba syonthe sya ũtanu ndũanĩ yĩ na ũtanu.'),
('kam', 'ISA', 32, 14, 'Nũndũ nyũmba nene mbanakavye ĩkaekwa; ndũa yĩ andũ aingĩ ĩkeethĩwa ĩte mũndũ; kalĩma na mwako mũtũlu wa kũsyaĩĩsya ikeethĩwa ngunga ĩndĩ yonthe, ũtanu wa mang’oi ma kĩthekanĩ, kĩsesi kya ndĩthya sya mbũi na malondu;'),
('kam', 'ISA', 32, 15, 'kũvika yĩla Veva wĩtulũĩlwa ithyĩ kuma ĩũlũ, na weũ wĩtw’ĩka mũũnda ũla ũsyaaa mũno, na mũũnda ũla ũsyaaa mũno ũitalwa ta mũtitũ.'),
('kam', 'ISA', 32, 16, 'Nĩvo ĩndĩ sila wa katĩ ũkekala weũnĩ; na ũlũngalu ũkekala mũũndanĩ ũla ũsyaaa mũno.'),
('kam', 'ISA', 32, 17, 'Na wĩa wa ũlũngalu ũkeethĩwa mũuo; na ũlũngalu ũkaetae ũuu na wĩkwatyo tene na tene.'),
('kam', 'ISA', 32, 18, 'Na andũ makwa makatũaa ũtũonĩ wĩ mũuo, na mawĩkalonĩ mate na mũisyo, na kũndũnĩ kũuu kwa kũthũmũa.'),
('kam', 'ISA', 32, 19, 'Ĩndĩ kũkaua mbua ya mavia ĩvinda ya kũvalũka kwa mũtitũ; na ndũa ĩkatheew’a nthĩ vyũ.'),
('kam', 'ISA', 32, 20, 'Mwĩ aathime inyw’ĩ ala mũvandaa ũtee wa manzĩ kw’onthe, inyw’ĩ ala mũekaa ng’ombe na ĩng’oi itũũe kw’o.'),
('kam', 'ISA', 33, 1, 'Woo nĩ waku we ũla wanangaa, naku ndwaaanangwa; na wĩkaa ũseleke, nao matyaakwĩka ũseleke! Yĩla wĩĩthĩwa ũekete kwananga, ũkaanangwa; na yĩla wĩĩthĩwa ũminĩte kwĩka ũseleke, nao makakwĩka ũseleke.'),
('kam', 'ISA', 33, 2, 'Ame Yeova, twĩke nesa; nĩtũkweteelete: ĩthĩwa kw’oko kwitũ kĩla kĩoko, o na ũtangĩĩo witũ ĩvinda ya thĩna.'),
('kam', 'ISA', 33, 3, 'Ngo sya andũ syeew’a kĩlonzo kya kĩtuu nĩsyakĩa; mbaĩ ninyaĩĩkĩte ũndũ wa kũkĩla kwaku mwene.'),
('kam', 'ISA', 33, 4, 'Na mũtavo waku ũkoombanw’a o tondĩ ithesa syũmbanaa: o tondũ ngie ithaanyũkaa now’o andũ makothaanyũkĩa.'),
('kam', 'ISA', 33, 5, 'Yeova nũkũtaĩwa; nũndũ nũtũaa ĩũlũ: nĩwusũĩtye Saioni sila wa katĩ na ulũngalu.'),
('kam', 'ISA', 33, 6, 'Na kũkeethĩwa ũlũmu mavindanĩ maku, na wingĩ wa ũtangĩĩo, na ũĩ, na ũmanyi: kũmũkĩa Yeova nĩ ũthwii waku.'),
('kam', 'ISA', 33, 7, 'Sisya, ngũmbaũ syoo nikũĩĩa ũtee; atũmwa ma mũuo maĩaa kĩĩo kĩ woo.'),
('kam', 'ISA', 33, 8, 'Malelũ nĩ manangĩku, ũla ũendaa kyalo nũekete kũthi: nĩwanangĩte ũtianĩo, nũvũthĩtye ndũa, ndeona mũndũ ta kĩndũ.'),
('kam', 'ISA', 33, 9, 'Nthĩ nĩnĩkũmeta na kũleela; Levanoni nĩnĩkũthokoana na kũvova; Saloni ĩilyĩ ta yalata; na Mbasani na Kalimeli nikwĩtĩkya matũ masyo.'),
('kam', 'ISA', 33, 10, 'Yu nĩngũkĩla, easya ũu Yeova, yu nĩngwĩyũkĩlya; yu nĩngũnenevw’a.'),
('kam', 'ISA', 33, 11, 'Mũkaitava wewa, mũkasyaa mavuthĩ: mĩthũmũ yenyu nĩ mwaki ũkamũmina.'),
('kam', 'ISA', 33, 12, 'Na ngo sya andũ ikeethĩwa ta sokaa ũivĩvw’a, ta mĩw’a mĩteme, ĩla ĩvĩvaw’a na mwaki.'),
('kam', 'ISA', 33, 13, 'Ĩthukĩĩsyei, inyw’ĩ ala mwĩ kũasa, ũndũ nĩkĩte; na, inyw’ĩ ala mwĩ vakuvĩ, ĩtĩkĩlai vinya wakwa.'),
('kam', 'ISA', 33, 14, 'Ala athe me Saioni nĩmeũkĩa; kũtetema nĩkũkwatĩte ala matakĩaa Ngai: Nũũ katĩ waitũ ũtonya kwĩkalaa na mwaki ũla ũvĩvasya? Nũũ katĩ waitũ ũtonya kwĩkalaa yekethenĩ ya tene na tene?'),
('kam', 'ISA', 33, 15, 'Ũla ũkinyaa ũlũngalunĩ, na kũneenaa w’o; ũla ũmenaa ũtandĩthyo wa kũthĩn’ya, ũla ũvuunzaa moko make ndakose ĩvaki, ũla ũlindaa matũ make matikew’a ũvoo wa nthakame, na kũlalya metho make matikone ũthũku:'),
('kam', 'ISA', 33, 16, 'ũsu akekalaa ĩũlũ; vandũ vake va kũsũvĩĩwa vakeethĩwa ngome ya mavia; akanengwa lĩu wake; manzĩ make maikang’ala.'),
('kam', 'ISA', 33, 17, 'Metho maku makoona mũsumbĩ ũtanakavunĩ wake: makoona nthĩ ĩthanthaĩte kũasa.'),
('kam', 'ISA', 33, 18, 'Ngoo yaku ĩkasũanĩa ũtĩsyo: Aĩva we ũla ũtalile, aĩva ũla wathimie mbesa sya koti? Aĩva ũla watalile myako mĩtũlu ya mĩnyoolo?'),
('kam', 'ISA', 33, 19, 'Ndũkona andũ ai, andũ me ndeto ndiku ila ũtatonya kũmanya, na me nĩmĩ ngeni ila ũtatonya kũmanya, na me nĩmĩ ngeni ila ũtatonya kũmanya.'),
('kam', 'ISA', 33, 20, 'Sisya Saioni, ndũa ya mboka sitũ itw’ĩtwe: metho maku makoona Yelusaleme ũtũo mũuu, ĩeema yĩla yĩtakambũwa, syambo syayo itakakũwa o na ĩndĩĩ, o na makanda o na meva mayo matikatw’ĩka.'),
('kam', 'ISA', 33, 21, 'Ĩndĩ Yeova akeethĩwa vo vamwe naitũ ũnenenĩ, vandũ va mbũsĩ nthanthau na tũlũsĩ, vala vatakaenda kakalawa katwaĩtwe na mĩtĩ, o na ngalawa nene ndĩkavĩtĩla vo.'),
('kam', 'ISA', 33, 22, 'Nũndũ Yeova nĩ mũsili waitũ, Yeova nĩ mũtũnengi wa mĩao, Yeova nĩ mũsumbĩ waitũ, nake akatũtangĩĩa.'),
('kam', 'ISA', 33, 23, 'Makanda maku nĩ maleelu; matyaatonya kũlũmya nesa ĩtina ya mũlingoti woo, matyaatonya kũtambũũkya ĩla ngũa ya kwosa kĩseve: nĩvo ĩndĩ mũtavo watavĩtwe mwingĩ waaaniw’e; ala mathuaa nĩmosie mũtavo.'),
('kam', 'ISA', 33, 24, 'Na ũla ũtwĩe kw’o ndakasya, Nyie nĩ mũwau; andũ ala matwĩe kw’o makaekewa ũthũku woo.'),
('kam', 'ISA', 34, 1, 'Thengeeai, inyw’ĩ mbaĩ, mwĩw’e; ĩthukĩĩsyei, inyw’ĩ ngo sya andũ: nthĩ nĩyĩw’e, na ila imyusĩe; nthĩ, na syĩndũ syonthe ila syumaa nthĩnĩ wayo.'),
('kam', 'ISA', 34, 2, 'Nũndũ Yeova e na ũthatu kwa mbaĩ syonthe na ũthilĩku kwa nguthu syasyo syonthe: nũsyanangĩte vyũ, nĩwinenganĩte syũawe.'),
('kam', 'ISA', 34, 3, 'Ala moo mooaiwe makekw’a nza, na mũuke mũthũku wa simba syoo ũkambata; na iĩma ikatweka nũndũ wa nthakame yoo.'),
('kam', 'ISA', 34, 4, 'Na nguthu yonthe ya ĩtunĩ ĩkatweka, na matu makakũnzwa ta ũsomwa; na nguthu yamo yonthe ĩkavova, o tondũ ĩtũ yĩvovaa na kũvalũka kuma mũsavivũnĩ, na ta ĩtũ yĩkĩvova na kũvalũka kuma mũkũyũnĩ.'),
('kam', 'ISA', 34, 5, 'Nũndũ ũvyũ wakwa nũnyw’ĩĩe ĩtunĩ ũkakola: sisya, ũkatheeea Etomu, o andũ ma kĩumo kyakwa, ũsilĩle.'),
('kam', 'ISA', 34, 6, 'Ũvyũ wa Yeova nĩusũĩte nthakame, nũnoetw’e nĩ kĩla kĩnoasya, na nthakame ya tũtena twa malondu na mbũi, na ĩthunya ya mbio sya ndũũme; nũndũ Yeova e na nthembo ku Mbosila, na ũai mũnene nthĩ ya Etomu.'),
('kam', 'ISA', 34, 7, 'Na mboo ikatheean’ya natw’o, na tũsalũ twa mũew’a vamwe na nzaũ: na nthĩ yoo ĩkeethĩwa ĩtoonetw’e nĩ nthakame, na mũthanga woo ũnoetw’e nĩ kĩla kĩnoasya.'),
('kam', 'ISA', 34, 8, 'Nũndũ Yeova e na mũthenya wa ũĩvanĩsyo, mwaka wa kũĩvanĩsya ũndũ wa Saioni.'),
('kam', 'ISA', 34, 9, 'Na tũlũsĩ twa Etomu tũkaalyũlwa twĩthĩwe kĩsia, na kĩtoo kyayo kĩthĩwe mũvĩlĩtĩ, nayo ĩ nthĩ ĩkatw’ĩka kĩsia kyakanĩte mwaki.'),
('kam', 'ISA', 34, 10, 'Kĩtikavoeka ũtukũ kana mũthenya; syũki yĩkambata tene na tene; ĩkeethĩwa mbanangĩku kuma nzyawa na nzyawa; vai mũndũ ũkamĩvĩtĩla tene na tene.'),
('kam', 'ISA', 34, 11, 'Ĩndĩ ngunĩ na nzee ikamĩtũa; na ndundu na ngũngũũ ikekala kw’o: na akatambũũkya ĩũlũ wayo ũlii wa kĩthokoo, na kavilũ ka vathei.'),
('kam', 'ISA', 34, 12, 'Makameta anene mayo me ndaĩa moke ũsumbĩnĩ, ĩndĩ o na ũmwe ndakethĩwa vo; na anene mayo onthe me mbee ũsumbĩnĩ matikethĩwa kĩndũ.'),
('kam', 'ISA', 34, 13, 'Na mĩw’a ĩkamea nyũmbanĩ nene mbanakavye syayo, syĩnyeelya na thangila ngomenĩ syayo; na ĩkeethĩwa ũtũo wa mbĩwa, na wĩkalo wa nyaa.'),
('kam', 'ISA', 34, 14, 'Na nyamũ mbai sya weũnĩ ikoombana na nzũi, na mbũi ya kĩthekanĩ ĩkanĩsya ĩla ĩngĩ; ĩĩ, mũnyũũ ũkatũa kw’o, na kwĩyonea vandũ va ũthũmũa.'),
('kam', 'ISA', 34, 15, 'Na ndundu nene ĩkaaka ndala yayo kw’o, na kũlekya matumbĩ, na kũvw’ĩkĩa yalĩkye, na kũmbanĩa muunyĩnĩ wa vo; ĩĩ, vau nĩvo imangaũ syĩũmbanĩa, kĩla kĩmwe na mũũme wakyo.'),
('kam', 'ISA', 34, 16, 'Manthai ĩvukunĩ ya Yeova, mũsome: vai ĩmwe ya isu ĩtakoneka, vai ĩmwe ĩkaĩwa nĩ mũũme; nũndũ kanyw’a wakwa, nĩw’o wĩaĩte, na Veva wake, nĩwe wasyũmbanisye.'),
('kam', 'ISA', 34, 17, 'Nake nũlimanĩte kwondũ wasyo, na kw’oko kwake nĩkũmĩaanĩtye na ũlii kwondũ wasyo: ĩkeethĩwa yasyo tene na tene; ikamĩtũa kuma nzyawa na nzyawa.'),
('kam', 'ISA', 35, 1, 'Weũ na nthĩ nyũmũ ikatana; na yalata yĩkatana, na kũlaũka ta ĩlaa ya lose.'),
('kam', 'ISA', 35, 2, 'Yĩkalaũka mũno, na kũtana na mũyo na kwina; yĩkanengwa ndaĩa ya Levanoni, ũnene wa Kalimeli na Saloni: makoona ũtheu mũtisu wa Yeova, ũnene wa Ngai waitũ.'),
('kam', 'ISA', 35, 3, 'Ĩkĩai vinya moko monzu, lũlũmĩlyai mau mate vinya.'),
('kam', 'ISA', 35, 4, 'Matavyei ala me na ngoo yĩ w’ĩa, Ĩthĩwai na vinya, mũtikakĩe: sisyai, Ngai wenyu akooka na ũĩvanĩsyo, ũĩvanĩsyo wa Ngai; akooka amũtangĩĩe.'),
('kam', 'ISA', 35, 5, 'Nĩvo metho ma ililinda mesalukw’a, na matũ ma ala au matũ melindũka.'),
('kam', 'ISA', 35, 6, 'Nĩvo mũndũ ũthuaa wĩtũlĩla ta ndaatai nũme, na ũĩmĩ wa ũla ũtaneenaa wĩina; nũndũ manzĩ makavulutya weũnĩ, na tũlũsĩ yalatanĩ.'),
('kam', 'ISA', 35, 7, 'Na kĩthangathĩ kĩtisatisu kĩkeethĩwa kĩilyĩ ĩia ya manzĩ, na nthĩ yĩ waũni mbuluti sya manzĩ: ũtũonĩ wa mbĩwa, vala ikomaa, kũkeethĩwa nyeki vamwe na mĩangi na malula.'),
('kam', 'ISA', 35, 8, 'Na lelũ ũkeethĩwa kw’o, na nzĩa, nayo ĩkeetawa, Nzĩa ya ũtheu; ala avuku matikamĩvĩtĩla; ĩndĩ ĩkeethĩwa ya ala ovosye: aendi ma syalo, ĩĩ ndia, matikamĩvĩtya.'),
('kam', 'ISA', 35, 9, 'Vatikethĩwa mũnyambũ kw’o, o na nyamũ mbai ndĩkambata nayo; itikoneka kw’o; ĩndĩ ala ovosye makamĩkinyĩlaa:'),
('kam', 'ISA', 35, 10, 'na ala ovosye ma Yeova makasyoka, na makavika Saioni makina; na ũtanu wa tene na tene ũkeethĩwa mĩtwenĩ yoo: makoosa mũyo na ũtanu, na kĩmako na kũvevũũka kũkathela.'),
('kam', 'ISA', 36, 1, 'Na kweethĩwa mwaka wa ĩkũmi na ĩna wa kũsumbĩka kwa mũsumbĩ Esekia, Senakelivu mũsumbĩ wa Asuli ambatĩĩa ndũa mbiie syonthe sya Yuta, na asyosa.'),
('kam', 'ISA', 36, 2, 'Na mũsumbĩ wa Asuli atũma Lavi‐sake kuma Lakisi kũthi Yelusaleme kwa mũsumbĩ Esekia e na ita nene. Na aũngama vakuvĩ na mũtaũ wa ndia yĩ ngalĩ ya ĩũlũ lelũnĩ ũelete kĩsesinĩ kya mũthambya wa ngũa.'),
('kam', 'ISA', 36, 3, 'Nĩvo ĩndĩ waumaalĩlwe nĩ Eliakimu, mwana wa Ilikia, ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba, na mũandĩki Sevina, na Yoa, mwana wa Asavu, ũla mũandĩki wa maũndũ.'),
('kam', 'ISA', 36, 4, 'Na Lavi‐sake amea, Mũtavyei Esekia yu, Ũũ nĩw’o mũsumbĩ mũnene, mũsumbĩ wa Asuli, ũnũkwasya, Wĩkwatyo ũũ nĩ mwaũ ũla wĩkwatĩtye?'),
('kam', 'ISA', 36, 5, 'Nĩngwasya, ũtao waku na vinya waku ũndũ wa kaũ no ndeto sya mana: yu wĩkwatasya ũũ, nũndũ nũng’endee nyie?'),
('kam', 'ISA', 36, 6, 'Sisya, wĩkwatasya ndata ya mũangi ũũ mũkanyange, nayo nĩ Misili, na ethĩwa mũndũ nũnũkwĩvandĩĩa nayo, ĩkalika kw’okonĩ kwake, na kũtonya: now’o Valao mũsumbĩ wa Misili ũilyĩ kwa onthe ala mamũĩkĩĩaa.'),
('kam', 'ISA', 36, 7, 'Ĩndĩ ethĩwa wĩmbĩa, Ithyĩ nĩtũmũĩkĩĩa Yeova Ngai waitũ: ĩndĩ tiwe, ũla Esekia ũvetete kũndũ kwake kũtũlu o na ithembeo syake, na nũtavĩtye Yuta na Yelusaleme, Mũkathaithĩaa kĩthembeonĩ kĩĩ?'),
('kam', 'ISA', 36, 8, 'Yu kwondũ wa ũu, nĩngũkwĩsũva, nenga vwana wakwa mũsumbĩ wa Asuli ngwatĩlĩlyo, na ngakũnenga mbalasi ngili ilĩ, ethĩwa ngalĩko ĩ yaku nũtonya kũtũlya andũ ĩũlũ wasyo.'),
('kam', 'ISA', 36, 9, 'Ũtonya ata ĩndĩ kũthyũũa ũthyũ wa kavuteni ũmwe wa ala anini mũno ma athũkũmi ma vwana wakwa, na kwĩkwatya Misili ĩkũnenge makasya na andũ ma ũtũlaa mbalasi?'),
('kam', 'ISA', 36, 10, 'Na yu nĩnambatĩte nde na Yeova kũkita na nthĩ ĩno nĩmyanange? Yeova ambĩa, Ambata ũkite na nthĩ ĩsu, ũmyanange.'),
('kam', 'ISA', 36, 11, 'Nĩvo ĩndĩ Eliakimu na Sevina na Yoa mamwĩa Lavi‐sake, Nĩtũũkwĩsũva, neena na athũkũmi maku na kĩthyomo kya Asilia; nũndũ nĩtũũkĩmanya: na ndũkaneene naitũ na kĩthyomo kya Ayuti, ala me ũvainĩ matikew’e.'),
('kam', 'ISA', 36, 12, 'Ĩndĩ Lavi‐sake akũlya, Vwana wakwa nũndũmĩte kwa vwana waku, na kwaku, nĩneene ndeto ii? Ndandũmĩte kwa andũ ala mekalaa ũvainĩ, maye mai moo ene, na manyw’e maumao moo ene vamwe nenyu?'),
('kam', 'ISA', 36, 13, 'Nĩvo ĩndĩ Lavi‐sake waũngamie, na aneena na wasya mũnene na kĩthyomo kya Ayuti, na asya, Ĩthukĩĩsyei ndeto sya mũsumbĩ mũnene, mũsumbĩ wa Asuli.'),
('kam', 'ISA', 36, 14, 'Ũũ nĩw’o mũsumbĩ ũnũkwasya, Esekia ndakamũkenge; nũndũ ndakatonya kũmũvonokya:'),
('kam', 'ISA', 36, 15, 'o na Esekia ndakamũĩkĩĩthye Yeova, akyasya, Yeova ndakatĩa kũtũvonokya; ndũa ĩno ndĩkanenganwe kw’okonĩ kwa mũsumbĩ wa Asuli.'),
('kam', 'ISA', 36, 16, 'Mũtikamwĩthukĩĩsye Esekia: nũndũ ũũ nĩw’o mũsumbĩ wa Asuli ũnũkwasya, Seũvyai mũuo nakwa, mumaale mũke vala nĩĩ; na mũiĩsaa kĩla ũmwe wa mũsavivũ wake, na kĩla ũmwe wa mũkũyũ wake, na mũkĩnyusaa kĩla ũmwe manzĩ ma kĩthima kyake mwene;'),
('kam', 'ISA', 36, 17, 'kũvika yĩla nĩũka na kũmũtwaa nthĩ ĩilyĩ ta nthĩ ĩno yenyu, nthĩ yĩ lĩu wa mbaa ngetha na mbinyu mbĩthĩ, nthĩ yĩ lĩu na mĩũnda ya mĩsavivũ.'),
('kam', 'ISA', 36, 18, 'Ĩsũvĩei Esekia ndakamũkikye, akyasya, Yeova akatũvonokya. Ve ngai o na yĩva ya mbaĩ ĩvonoketye nthĩ yayo kuma kw’okonĩ kwa mũsumbĩ wa Asuli?'),
('kam', 'ISA', 36, 19, 'Ngai sya Amathi na Alivati iĩva? Ngai sya Sevalivaimu iĩva? Na nivonoketye Samalia kw’okonĩ kwakwa?'),
('kam', 'ISA', 36, 20, 'Nĩ syĩva katĩ wa ngai syonthe sya nthĩ isu, ila ivonoketye nthĩ yasyo kw’okonĩ kwakwa, nĩ kana Yeova avonokye Yelusaleme kw’okonĩ kwakwa?'),
('kam', 'ISA', 36, 21, 'Ĩndĩ mavindya ki, na matyaamũsũngĩa ndeto; nũndũ mwĩao wa mũsumbĩ waĩtye, Mũtikamũsũngĩe.'),
('kam', 'ISA', 36, 22, 'Nĩvo ĩndĩ Eliakimu mwana wa Ilikia, ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba, na mũandĩki Sevina, na Yoa, mwana wa Asavu, mũandĩki wa maũndũ, mathi kwa Esekia matembũangĩte ngũa syoo, na mamũtavya ndeto sya Lavi‐sake.'),
('kam', 'ISA', 37, 1, 'Na kweethĩwa, yĩla mũsumbĩ Esekia wewie ũu, atembũanga ngũa syake, na eekĩa makunia, na alika nyũmbanĩ ya Yeova.'),
('kam', 'ISA', 37, 2, 'Na atũma Eliakimu, ũla waĩ mũsyaĩĩsya wa andũ ma nyũmba, na mũandĩki Sevina, na atumĩa athembi, kwa mwathani Isaia mwana wa Amosu, mekĩĩte makunia.'),
('kam', 'ISA', 37, 3, 'Nao mamwĩa, Ũũ nĩw’o Esekia ũnũkwasya, Ũmũnthĩ nĩ mũthenya wa thĩna, na wa ũkanw’a, na wa kũvũthw’a; nũndũ twana nĩtũvikĩte ĩvinda ya kũsyawa, na vati vinya wa kũsyaa.'),
('kam', 'ISA', 37, 4, 'Nokwĩthĩwa Yeova Ngai waku akeew’a ndeto sya Lavi‐sake, ũla mũsumbĩ wa Asuli vwana wake ũmũtũmĩte amũvũthĩĩsye Ngai wĩ thayũ, na akakan’ya ndeto ila Yeova Ngai waku wĩw’ĩte: kwondũ wa ũu ũkĩlya mboya yaku kwondũ wa ũtialo ũla ũtialĩte.'),
('kam', 'ISA', 37, 5, 'Kwondũ wa ũu athũkũmi ma mũsumbĩ Esekia mavika kwa Isaia.'),
('kam', 'ISA', 37, 6, 'Na Isaia amea, Ũũ nĩw’o mwĩmũtavya vwana wenyu, Ũũ nĩw’o Yeova ũnũkwasya, Ndũkakĩe ndeto ila wĩw’ĩte, ila athũkũmi ma mũsumbĩ wa Asuli manumangĩte nasyo.'),
('kam', 'ISA', 37, 7, 'Sisya, ngeekĩa veva nthĩnĩ wake na akeew’a maũvoo, na akasyoka nthĩ yake mwene; na ngatuma avalũkĩlw’a na ũvyũ nthĩ yake mwene.'),
('kam', 'ISA', 37, 8, 'Kwondũ wa ũu Lavi‐sake asyoka, na amwĩthĩa mũsumbĩ wa Asuli aiũkita na Livina; nũndũ aĩ aneew’a kana nĩwumĩte vu Lakisi.'),
('kam', 'ISA', 37, 9, 'Na nĩwewie kũineenwa ũndũ wa Tiliaka mũsumbĩ wa Ethiovia, Nĩwumaalĩte okite naku. Na yĩla wewie ũu, atũma atũmwa kwa Esekia, akyasya,'),
('kam', 'ISA', 37, 10, 'Ũũ nĩw’o mwĩmũtavya Esekia mũsumbĩ wa Yuta, mũkĩmwĩa, Ngai waku ũla ũmwĩkwatasya ndakakũkenge, aikwĩa, Yelusaleme ndĩkanenganwe kw’okonĩ kwa mũsumbĩ wa Asuli.'),
('kam', 'ISA', 37, 11, 'Sisya, nĩwĩw’ĩte ũndũ asumbĩ ma Asuli mekĩte nthĩ syonthe, ũndũ wa kũsyananga vyũ: naku ũkavonoka?'),
('kam', 'ISA', 37, 12, 'Ngai sya mbaĩ nĩsyaivonokisye, ila aasa makwa masyanangie, Ngosani, na Aalani, na Lesevu, na ana ma Eteni ala maĩ Telasali?'),
('kam', 'ISA', 37, 13, 'Aĩva mũsumbĩ wa Amathi, na mũsumbĩ wa Alivati, na mũsumbĩ wa ndũa ya Sevalivaimu, na ya Ena, na ya Iva?'),
('kam', 'ISA', 37, 14, 'Na Esekia oosa valũa kuma mokonĩ ma ala matũmiwe, na oosoma; na Esekia ambata alika nyũmbanĩ ya Yeova, na ootambũũkĩsya mbee wa Yeova.'),
('kam', 'ISA', 37, 15, 'Na Esekia amũvoya Yeova, akyasya,'),
('kam', 'ISA', 37, 16, 'Ame Yeova wa nguthu, Ngai wa Isilaeli, ũla wĩkalaa ĩũlangũ wa akeluvi, nue Ngai, o we wĩ weka, wa mosumbĩ onthe ma nthĩ; nue woombie ĩtu na nthĩ.'),
('kam', 'ISA', 37, 17, 'Tea kũtũ kwaku, ame Yeova, wĩw’e; salukya metho maku, ame Yeova, wone; ĩw’a ndeto syonthe sya Senakelivu, ũla ũtũmanĩte avũthĩĩsye Ngai wĩ thayũ.'),
('kam', 'ISA', 37, 18, 'Nĩ w’o, Yeova, asumbĩ ma Asuli nĩmanangĩte nthĩ syonthe, o na mĩũnda yasyo,'),
('kam', 'ISA', 37, 19, 'na nĩmekisye ngai syasyo mwakinĩ: nũndũ ityaĩ ngai, ĩndĩ nĩ wĩa wa moko ma andũ, mĩtĩ na mavia; kwondũ wa ũu nĩmasyanangĩte.'),
('kam', 'ISA', 37, 20, 'Yu kwondũ wa ũu, ame Yeova Ngai waitũ, tũtangĩĩe kuma kw’okonĩ kwake, nĩ kana mosumbĩ onthe ma nthĩ mamanye atĩ nue Yeova, o we wĩ weka.'),
('kam', 'ISA', 37, 21, 'Nĩvo ĩndĩ Isaia mwana wa Amosu watũmanie kwa Esekia, akyasya, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Nĩkwĩthĩwa nũmboyete ũndũ wa Senakelivu mũsumbĩ wa Asuli,'),
('kam', 'ISA', 37, 22, 'ĩno nĩyo ndeto ĩla Yeova ũneenete ũndũ wake: Mwĩĩtu mũtheu wa Saioni nũkũvũthĩtye na nũkũthekeete mũno; mwĩĩtu wa Yelusaleme nũkũthingithangĩĩtye mũtwe wake.'),
('kam', 'ISA', 37, 23, 'Nũũ ũla ũvũthĩĩtye na kũmũumanga? Na nũũ ũla ũmũkĩlĩlye wasya waku na kũmũkĩlĩlya metho maku ĩũlũ? No Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 37, 24, 'Nũvũthĩĩtye Mwĩaĩi na makanyw’a ma athũkũmi maku, na waĩtye, Nĩnambatĩte iĩmanĩ ĩũlũ nĩ na wingĩ wa makasya makwa, kũvika Levanoni nthĩnĩ; na ngatũla mĩkũũ mĩasa ya vo, na mĩtĩ ya mĩsonovali mĩseo ya vo; na ngalika vala vatũlu mbee, o mũtitũnĩ wa mũũnda wa vo ũla ũsyaaa mũno;'),
('kam', 'ISA', 37, 25, 'nĩnĩnzĩte na kũnyw’a manzĩ, na ngang’alĩthya mbũsĩ syonthe sya Misili na nyaĩĩ syakwa.'),
('kam', 'ISA', 37, 26, 'Ndwaaĩw’a ũndũ neekie ũndũ ũsu tene mũno, na naseũvya ũu kuma tene tene? Na yu nĩnoovĩtũkĩthisye, atĩ nĩ ũndũ waku kwananga ndũa mbiie syĩthĩwe ivumbu sya moomboe.'),
('kam', 'ISA', 37, 27, 'Kwondũ wa ũu ala maitwĩe maĩ na vinya mũnini, mateva na mathokoana; mailyĩ ta nyeki sya kĩsesi, na nyũnyi nziũ, ta nyeki nyũmbanĩ ĩũlũ, na ta mũũnda wa lĩu wa mbaa ngetha ũtanamba kwĩana.'),
('kam', 'ISA', 37, 28, 'Ĩndĩ nĩnĩsĩ kwĩkala nthĩ kwaku, na kumaala kwaku, na kũlika kwaku, na kũnthilĩkĩla kwaku.'),
('kam', 'ISA', 37, 29, 'Nũndũ wa kũnthilĩkĩla, na nĩkwĩthĩwa wĩnenevyo waku nũvikĩte matũnĩ makwa, kwondũ wa ũu ngeekĩa kavoloi kakwa manyiũũnĩ maku, na mũkwa wakwa ilomonĩ syaku, na ngakũthyũũa ũsyoke na nzĩa ĩla ũnesĩle.'),
('kam', 'ISA', 37, 30, 'Na ũũ ũkeethĩwa wonan’yo kwaku: mwaka ũũ mũkaya metĩkĩa, na mwaka wa kelĩ mathongooo mamo; na mwaka wa katatũ vandai, na mũiketha, na vandai mĩũnda ya mĩsavivũ, mũye ũsyao wayo.'),
('kam', 'ISA', 37, 31, 'Na ũtialo ũla mũvonoku wa nyũmba ya Yuta ũkatambũũkya mĩi ĩngĩ ĩlikĩte na nthĩ, na kũsyaa ũsyao welekele ĩũlũ.'),
('kam', 'ISA', 37, 32, 'Nũndũ ũtialo ũkauma Yelusaleme, na ala avonoku makauma kĩĩmanĩ kya Saioni. Kĩwĩu kya Yeova wa nguthu kĩkeanĩsya ũndũ ũsu.'),
('kam', 'ISA', 37, 33, 'Kwondũ wa ũu Yeova easya ũndũ wa mũsumbĩ wa Asuli, Ndakalika ndũanĩ ĩno, o na ndakamĩkya mũsyĩ, o na ndakoka mbee wayo na ngao, o na ndakamyũmbĩĩa kĩvumbu.'),
('kam', 'ISA', 37, 34, 'Na nzĩa ĩla ũnookie nayo, akasyokela o yo, na ndakalika ndũanĩ ĩno, easya ũu Yeova.'),
('kam', 'ISA', 37, 35, 'Nũndũ ngasesea ndũa ĩno nĩmĩtangĩĩe, kwondũ wakwa mwene, na kwondũ wa mũthũkũmi wakwa Ndaviti.'),
('kam', 'ISA', 37, 36, 'Na mũlaĩka wa Yeova aumaala, na akũna andũ ngili ĩana na mĩongo nyanya na itano mwakonĩ wa maeema wa Aasuli; na yĩla andũ maamũkie kĩoko tene, sisya, asu onthe maĩ simba.'),
('kam', 'ISA', 37, 37, 'Na kwondũ wa ũu Senakelivu mũsumbĩ wa Asuli ookĩla, na aenda na asyoka kwake, na atũa Nineva.'),
('kam', 'ISA', 37, 38, 'Na kweethĩwa, aithaitha nyũmbanĩ ya Nisiloki ngai yake, Atalameleki na Saleseli ana make mamũkũna na ũvyũ; na maindũka mathi nthĩ ya Alalati. Na Esali‐atoni mwana wake asumbĩka vandũ vake.'),
('kam', 'ISA', 38, 1, 'Mĩthenya ĩsu Esekia aĩ mũwau akathengeea kũkw’a. Na mwathani Isaia mwana wa Amosu amũkĩa, na amwĩa, Ũũ nĩw’o Yeova ũnũkwasya, Ĩae ũndũ wa nyũmba yaku; nũndũ nũũkw’a, ndwĩĩkala thayũ.'),
('kam', 'ISA', 38, 2, 'Nĩvo ĩndĩ Esekia wethyũũie na eelekelya ũthyũ wake wakonĩ, na amũvoya Yeova,'),
('kam', 'ISA', 38, 3, 'na amwĩa, Lilikana yu, ame Yeova, nĩngũkwĩsũva, ũndũ nĩendete mbee waku nthĩnĩ wa w’o na ngoo mbĩanĩu, na nĩnĩkĩte ũla wonaa wĩ ũseo. Na Esekia aĩa mũno.'),
('kam', 'ISA', 38, 4, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩie Isaia, ĩkĩmwĩa,'),
('kam', 'ISA', 38, 5, 'Enda, ũmwĩe Esekia, Ũũ nĩw’o Yeova, Ngai wa Ndaviti ĩthe waku ũnũkwasya, Nĩnĩw’ĩte mboya yaku, nĩnonete methoi maku: sisya, ngongela thayũ waku myaka ĩkũmi na ĩtano.'),
('kam', 'ISA', 38, 6, 'Na ngakũvonokya we na ndũa ĩno kuma kw’okonĩ kwa mũsumbĩ wa Asuli; na ngasesea ndũa ĩno.'),
('kam', 'ISA', 38, 7, 'Na ũũ nĩw’o wĩĩthĩwa wonan’yo kwaku kuma kwa Yeova, atĩ Yeova akeeka ũndũ ũũ ũla ũneenete:'),
('kam', 'ISA', 38, 8, 'sisya, ngatuma muunyĩ wĩ mbasyanĩ, ũla ũtheeanĩtye na syũa vala ve saa wa syũa wa Aasu, ũsyoka ĩtina matambya ĩkũmi. Na ĩndĩ syũa yasyoka matambya ĩkũmi saanĩ ũsu vala yavĩtũkĩte.'),
('kam', 'ISA', 38, 9, 'Ũũ nĩw’o ũandĩko wa Esekia mũsumbĩ wa Yuta, yĩla wavoie ũwau wake, ũla wawaĩte.'),
('kam', 'ISA', 38, 10, 'Na naisye, Mĩthenyanĩ yakwa katĩ, ngalika mbingĩlonĩ sya Seoli: Nĩnĩvenetwe ũtialo wa myaka yakwa.'),
('kam', 'ISA', 38, 11, 'Na naisye, Ndikamwona Yeova, o Yeova nĩ nthĩ ya ala me thayũ: Ndikona mũndũ ĩngĩ nĩ vamwe na ala matwĩe nthĩ.'),
('kam', 'ISA', 38, 12, 'Wĩkalo wakwa nũthamĩtw’e, na kũtwawa kũasa nakwa ta ĩeema ya mũĩthi: Nĩnĩkũnzĩte thayũ wakwa, ta mũtumi wa ngũa; nake akandila nume kĩtuminĩ: Kuma mũthenya kũvika ũtukũ ũkamina nyie.'),
('kam', 'ISA', 38, 13, 'Nĩneekilĩlye kũvika kĩoko; o ta mũnyambũ, now’o wĩtũlanga mavĩndĩ makwa onthe: Kuma mũthenya kũvika ũtukũ ũkamina nyie.'),
('kam', 'ISA', 38, 14, 'Ta nthũngũlũlũ kana kanyange, now’o nĩnanyiilaa; Nĩnang’ulasya ta ĩvũĩ; metho makwa nĩmeũseekea kwondũ wa kũsisya ĩũlũ: Ame Yeova, nĩngũnyamaw’a, ĩthĩwa mũĩkĩĩthya wakwa.'),
('kam', 'ISA', 38, 15, 'Ngasya ata? Nũneenete nakwa, o na we mwene nĩwĩkĩte ũu: Ngaendaa mbola myaka yakwa yonthe nũndũ wa ũũ wa thayũ wakwa.'),
('kam', 'ISA', 38, 16, 'Ame Mwĩaĩi, andũ methĩawa thayũ kwondũ wa maũndũ aa; Na no nthĩnĩ wamo kwĩ thayũ wa veva wakwa: Kwondũ wa ũu mbosya nyie, ũmbĩkalye thayũ.'),
('kam', 'ISA', 38, 17, 'Sisya, vandũ va mũuo naĩ na ũũ mwingĩ: Ĩndĩ kwondũ waku kwenda thayũ wakwa nĩwũtangĩĩĩte kuma ĩimanĩ ya wanangĩko; Nũndũ nĩwĩkĩtye naĩ syakwa syonthe ĩtina waku.'),
('kam', 'ISA', 38, 18, 'Nũndũ Seoli vaitonya ũkũtaĩa, kĩkw’ũ kĩitonya ũkũkatha: Ala matheeaa yĩla ĩimanĩ maitonya kwĩkwatya w’o waku.'),
('kam', 'ISA', 38, 19, 'Ũla wĩ thayũ, ũla wĩ thayũ, nĩwe ũkakũtaĩa, o tondũ ngwĩka ũmũnthĩ: Ĩthe akamanyĩthya syana w’o waku.'),
('kam', 'ISA', 38, 20, 'Yeova nĩwĩyũmbanĩtye kũndangĩĩa; Kwondũ wa ũu tũkaina mbathi syakwa na syĩndũ sya kũinga syĩ mĩkunzu Mĩthenya yonthe ya mathayũ maitũ nyũmbanĩ ya Yeova.'),
('kam', 'ISA', 38, 21, 'Ĩndĩ Isaia aĩ ananeena, Nĩmose kakũmbwa ka makũyũ, na makailĩĩle mũimũnĩ wĩthĩwe mũtĩ, nake akavoa.'),
('kam', 'ISA', 38, 22, 'Na Esekia aĩ ananeena ũndũ ũngĩ, Wonan’yo nĩ wĩva kana ngambata nyũmbanĩ ya Yeova?'),
('kam', 'ISA', 39, 1, 'Ĩvinda yĩu Melotaki‐mbalatani mwana wa Mbalatani, mũsumbĩ wa Mbaviloni, amũtwaĩa Esekia mavalũa na mũthĩnzĩo; nũndũ nĩwewie atĩ anaĩ mũwau, na nũvoete.'),
('kam', 'ISA', 39, 2, 'Na Esekia atana ũndũ wasyo, nake amon’ya nyũmba yĩ na syĩndũ syake syĩ vata mũno, vetha, na thaavu, na mĩtĩ ĩla ĩnyungaa nesa, na mauta me vata mũno, na nyũmba yonthe yĩ mĩio yake ya kaũ, na kyonthe kĩla kyoonekie mothwiinĩ make maie: vatyaĩ kĩndũ nyũmbanĩ yake, kana ũsumbĩnĩ wake w’onthe, kĩla Esekia ũtaamon’ya.'),
('kam', 'ISA', 39, 3, 'Nĩvo ĩndĩ mwathani Isaia wamũendeie mũsumbĩ Esekia, na amũkũlya, Andũ aa maisye ata? Na makyũka kwaku maumie va? Na Esekia asya, Nĩmanthokee maumĩte nthĩ yĩ kũasa, o kuma Mbaviloni.'),
('kam', 'ISA', 39, 4, 'Nĩvo ĩndĩ wakũlilye, Moonie kyaũ nyũmbanĩ yaku? Na Esekia asũngĩa, Kyonthe kĩla kĩ nyũmbanĩ yakwa nĩmonete: vati kĩndũ mothwiinĩ makwa maie kĩla ndaamon’ya.'),
('kam', 'ISA', 39, 5, 'Nĩvo ĩndĩ Isaia wamwĩie Esekia, Ĩthukĩĩsye ndeto ya Yeova wa nguthu:'),
('kam', 'ISA', 39, 6, 'Sisya, mĩthenya nĩyũkĩte, yĩla kyonthe kĩ nyũmbanĩ yaku, na kĩla aaĩthe maku maiĩte kũvika ũmũnthĩ, kĩkatwawa Mbaviloni: vati kĩndũ kĩkatiala, easya ũu Yeova.'),
('kam', 'ISA', 39, 7, 'Na amwe ma ana maku ala makauma nthĩnĩ waku, ala ũkasyaa, makamatwaa; na makeethĩwa me avakũe nyũmbanĩ nene mbanakavye ya mũsumbĩ wa Mbaviloni.'),
('kam', 'ISA', 39, 8, 'Nĩvo ĩndĩ Esekia wamwĩie Isaia, Ndeto ya Yeova ĩla waneena nĩ nzeo. Na aneena ĩngĩ, Kũkeethĩwa mũuo na w’o mĩthenyanĩ yakwa.'),
('kam', 'ISA', 40, 1, 'Kiakisyai, kiakisyai andũ makwa, easya ũu Ngai wenyu.'),
('kam', 'ISA', 40, 2, 'Neenai na Yelusaleme ndeto sya ũkiakisyo; ĩtanai mũimwĩa, kana kũkita kwake nĩ kũthelu, na ũthũku wake nũeketwe, na nĩwosete kuma kw’okonĩ kwa Yeova kũndũ kwĩlĩ ũndũ wa naĩ syake syonthe.'),
('kam', 'ISA', 40, 3, 'Wasya wa mũndũ ũkĩneena mũno, Seũvyai nzĩa ya Yeova weũnĩ; seũvyai lelũ mũtindimalu yalatanĩ kwondũ wa Ngai waitũ.'),
('kam', 'ISA', 40, 4, 'Kĩla mwanda ũkookĩlw’a, na kĩla kĩĩma na kalĩma ikeananw’a na nthĩ; na kĩla vandũ vokĩlu vakatindimalw’a, na kũndũ kũthũku kũkatindimalw’a;'),
('kam', 'ISA', 40, 5, 'na ũtheu mũtisu wa Yeova ũkavuanw’a, na mĩĩ yonthe ĩkawona vamwe; nũndũ kanyw’a wa Yeova nũneenete ũu.'),
('kam', 'ISA', 40, 6, 'Wasya wa mũndũ ũkyasya, Neena mũno. Na ũngĩ akũlya, Nĩneene ata? Mĩĩ yonthe nĩ nyeki, na ũseo wayo w’onthe nĩ ta ĩlaa ya kĩsesinĩ.'),
('kam', 'ISA', 40, 7, 'Nyeki nĩyũmaa, na ĩlaa nĩyĩvovaa, nũndũ mĩthũmũ ya Yeova nĩyĩveveaa; vate ndĩi andũ nĩ nyeki.'),
('kam', 'ISA', 40, 8, 'Nyeki nĩyũmaa, na ĩlaa nĩyĩvovaa; ĩndĩ ndeto ya Ngai waitũ ĩkekala tene na tene.'),
('kam', 'ISA', 40, 9, 'We ũla ũtavasya Saioni maũvoo maseo, ambata kĩĩmanĩ kĩtũlu; we ũla ũtavasya Yelusaleme maũvoo maseo, ũkĩlya wasya waku na vinya; wũkĩlye, ndũkakĩe; tavya ndũa sya Yuta, Sisyai, Ngai wenyu!'),
('kam', 'ISA', 40, 10, 'Sisya, Mwĩaĩi Yeova akooka ta ũla wĩ ũtonyi, na kw’oko kwake kũkamũsumbĩkĩthya: Sisya, ĩtuvi yake yĩ vamwe nake, na mũthĩnzĩo wake wĩ mbee wake.'),
('kam', 'ISA', 40, 11, 'Akaĩthya ĩĩthya yake ta mũĩthi, akoomban’ya tũtena twa malondu mokonĩ make, na akatũkua na kĩthũi kyake, na akatongoeasya mbola ala mekwongya.'),
('kam', 'ISA', 40, 12, 'Nũũ ũla ũthimĩte iw’ũ na kĩtaa kya kw’oko kwake, na kũthima ĩtu na ĩkwata ya kĩtaa, na kũthima kĩtoo kya nthĩ na kĩthimi, na kũthima iĩma na latili, na tũlĩma na kĩthimi?'),
('kam', 'ISA', 40, 13, 'Nũũ ũla watongoesye Veva wa Yeova, kana wamũmanyĩĩsye ethĩwe mũtai wake?'),
('kam', 'ISA', 40, 14, 'We akũlanilye naũ, na nũũ ũla wamũmanyĩsye, na kũmũmanyĩsya nzĩa ya kũsila katĩ, na kũmũmanyĩsya ũĩ, na kũmwon’ya nzĩa ya ũmanyi?'),
('kam', 'ISA', 40, 15, 'Sisya, mbaĩ nĩ ta kavoloto ke ndoonĩ, na nitalawa ta kĩtoo kĩvinyu kĩthiminĩ: sisya, nĩwũkĩlasya ithama ta kĩndũ kĩnini mũno.'),
('kam', 'ISA', 40, 16, 'Na Levanoni kĩtyĩanĩsya ngũ sya kũvĩvya, kana nyamũ syakyo kwĩanĩsya nthembo ya kũvĩvw’a.'),
('kam', 'ISA', 40, 17, 'Mbai syonthe ti kĩndũ mbee wake; nitalawa nĩwe ta kĩndũ kĩte vata nongi, na sya mana.'),
('kam', 'ISA', 40, 18, 'Mwĩelekan’ya Ngai naũ? Kana nĩ mũvw’anano wĩva mũelekan’ya nake?'),
('kam', 'ISA', 40, 19, 'Ndũĩka nĩtwekethetye mũvw’anano, na mũtwii wa thaavu nĩwũvw’ĩkaa thaavu, na kũtuĩa mĩnyoo ya vetha.'),
('kam', 'ISA', 40, 20, 'Ũla ngya ũtatonya nthembo nũnyuvaa mũtĩ ũtakoa; na nũkwĩmanthĩa mũtethya wa wĩa mũĩ aũngamye mũvw’anano mwasũvye, ũla ũtakathingithĩka.'),
('kam', 'ISA', 40, 21, 'Mũtyaamanya? Mũtyaaĩw’a? Mũtyaatavw’a kuma wambĩlĩlyonĩ? Mũtyaamanya kuma myambĩlĩlyonĩ ya nthĩ?'),
('kam', 'ISA', 40, 22, 'Nĩwe ũla wĩkalaa ĩũlũ wa kilinge kya nthĩ, na ala mamĩtwĩe mailyĩ ta itooli; ũla ũtambũũkasya matu ta suka, na ũmalanasya ta ĩeema ya kũtũawa;'),
('kam', 'ISA', 40, 23, 'ũla ũtw’ĩkĩthasya anene me mbee ũsumbĩnĩ ta ti kĩndũ; ũla ũtumaa asili ma nthĩ methĩwa ma mana.'),
('kam', 'ISA', 40, 24, 'Ĩĩ, matyaavandwa; ĩĩ, matyaavuĩwa; ĩĩ, kĩtina kyoo kĩtyaatambũũkya mĩi nthĩ: o na ĩngĩ amaveveea, maivova, na kĩlingi kĩimatwaa ta mavuthĩ.'),
('kam', 'ISA', 40, 25, 'Na ĩndĩ mũkangelekan’ya naũ, nĩthĩwe nĩanene nake? Ekũlya ũu Ũla Mũtheu.'),
('kam', 'ISA', 40, 26, 'Ũkĩlyai metho menyu ĩũlũ, mũsisye ũla wombie ii, ũla wumĩlasya nguthu yasyo kwa kũtala; nũsyĩtaa syonthe na masyĩtwa; kwondũ wa ũnene wa vinya wake, na nũndũ e na vinya ũtonyinĩ, vati ĩmwe ĩte vo.'),
('kam', 'ISA', 40, 27, 'Nĩkĩ ũkwasya, we Yakovo, na ũneenaa, we Isilaeli, Nzĩa yakwa nĩvithĩtwe Yeova ndakamyone, na ũsili wa katĩ ũla naĩlwe nĩw’o ndũsiananw’a nĩ Ngai wakwa?'),
('kam', 'ISA', 40, 28, 'Ndwaamanya? Ndwaaĩw’a? Ngai wa tene na tene, Yeova, Mũmbi wa itulu sya nthĩ, ndatevaa, o na ndanoaa; ũmanyi wake ndũmanyĩka.'),
('kam', 'ISA', 40, 29, 'Nũmanengae vinya ala meũnyala; nũmwongelaa vinya ũla ũte vinya.'),
('kam', 'ISA', 40, 30, 'O na masanga makanyala na kũnoa, na anake makavalũka vyũ:'),
('kam', 'ISA', 40, 31, 'ĩndĩ ala mamweteelaa Yeova makeeũvw’a vinya woo; makambata na nthwau ta ndiũ; makasemba, na maikanoa; makatambũka, na maikanyala.'),
('kam', 'ISA', 41, 1, 'Vindyai mbee wakwa, inyw’ĩ ĩthama; na ekai ngo sya andũ syeũvw’e vinya wasyo: ithengeee; na ĩndĩ ineene; tũthengeee vamwe ũsilĩlonĩ.'),
('kam', 'ISA', 41, 2, 'Nũũ wũkĩlĩtye ũmwe kuma wumĩlonĩ wa syũa, ũla ũmwĩtaa ũlũngalunĩ oke kũũnĩ kwake? Nũnenganae i mbaĩ kwake, na kũmũsumbĩkya ĩũlũ wa asumbĩ: nĩwinenganae ta kĩtoo ũvyũnĩ wake iũlũkaw’a nĩ ũta wake o ta mavuthĩ.'),
('kam', 'ISA', 41, 3, 'Nĩwiatĩĩaa, na kũvĩta vate mũisyo, o nzĩanĩ ĩla ũtaamĩendela na maũũ make.'),
('kam', 'ISA', 41, 4, 'Nũũ ũla wekie na kũseũvya ũndũ ũsu, akĩsyĩta nzyawa kuma wambĩlĩlyonĩ? Nyie, Yeova, ũla wa mbee, na wa mũminũkĩlyo, ninyie we.'),
('kam', 'ISA', 41, 5, 'Ithama nĩsyonete, na kũkĩa; itulu sya nthĩ nitetemaa; nithengeeaa, na nĩsyũkaa.'),
('kam', 'ISA', 41, 6, 'Nĩmatethanasya kĩla ũmwe na mũtũi wake; na kĩla ũmwe nũmwĩaa mwana‐a‐inyia, Ĩthĩwa na ũkũmbaũ mũnene.'),
('kam', 'ISA', 41, 7, 'Kwondũ wa ũu mũseũvya wa mbwaũ nũmwĩkĩaa vinya mũtwii wa thaavu, na ũla ũtendeasya na kĩiva nũmwĩkĩaa vinya ũla ũkũnaa kĩtuĩo, akyasya ũndũ wa kũkwatan’ya na ĩvulũ, Nĩ kũkwatan’ya kũseo; na nũkũathĩa na mĩsumaa, ndũkathingithĩke.'),
('kam', 'ISA', 41, 8, 'Ĩndĩ we, Isilaeli, mũthũkũmi wakwa, Yakovo ũla nĩnyuvĩte, ũsyao wa mũnyanyawa Avalaamu,'),
('kam', 'ISA', 41, 9, 'we ũla nakũkwatie ũkumya itulunĩ sya nthĩ, na kũkwĩta wume ikotonĩ syayo, na ũkwĩa, We wĩ mũthũkũmi wakwa, nĩngũnyuvĩte na ndyaakwĩkya ũtee;'),
('kam', 'ISA', 41, 10, 'ndũkakĩe, nũndũ nĩ vamwe naku; ndũkateve, nũndũ nyie nĩ Ngai waku; ngakwĩkĩa vinya; ĩĩ, ngakũtethya; ĩĩ, ngakũũngamya na kw’oko kwa aũme kwa ũlũngalu wakwa.'),
('kam', 'ISA', 41, 11, 'Sisya, onthe ala makũthatĩe makasonokw’a na kũthokoanw’a; ala makĩlanasya vinya naku makeethĩwa ti kĩndũ, na makaa.'),
('kam', 'ISA', 41, 12, 'Ũkamamantha, na ndũkamona, o asu ala makĩlanasya vinya naku: ala mokitaa naku makeethĩwa ma mana, na ta kĩndũ kĩte vata.'),
('kam', 'ISA', 41, 13, 'Nũndũ nyie, Yeova Ngai waku, ngakũkwata kw’oko kwaku kwa aũme, ngĩkwĩa, Ndũkakĩe; ngakũtethya.'),
('kam', 'ISA', 41, 14, 'Ndũkakĩe, we kĩinyũ Yakovo, na inyw’ĩ andũ ma Isilaeli; ngakũtethya, easya ũu Yeova, na Mwovosya waku nĩ Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 41, 15, 'Sisya, nĩnĩkũtw’ĩkĩthĩtye kĩvũi kyeũ kyũĩ kĩ maeo; ũkavũa iĩma, na kwikũna syĩthĩwe nini, na ũkatw’ĩkĩthya tũlĩma ta wewa.'),
('kam', 'ISA', 41, 16, 'Ũkaiũlũkya, na kĩseve kĩkaitwaa, na kĩlingi kĩkainyaĩĩkya; naku ũkatana nthĩnĩ wa Yeova, ũkeekathĩĩa nthĩnĩ wa Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 41, 17, 'Ngya na ala athĩni nĩmamanthaa manzĩ, na vatiĩ, na nĩmĩ syoo nĩ nyiau nũndũ wa waũni; nyie, Yeova, ngamasũngĩa, nyie, Ngai wa Isilaeli, ndikamatia.'),
('kam', 'ISA', 41, 18, 'Ngavingũa mbũsĩ kũndũ kũtũlu kũthei, na nthongo myandanĩ katĩ; ngatw’ĩkĩthya weũ ndia ya manzĩ, na nthĩ nyũmũ mbuluti sya manzĩ.'),
('kam', 'ISA', 41, 19, 'Ngamesya weũnĩ mũkũũ, na mũea, na mũandasi, na mwaĩki; ngavanda yalatanĩ mũsonovali, na mũtindali, na mũvuena vamwe:'),
('kam', 'ISA', 41, 20, 'nĩ kana mone, na kũmanya, na kũsũanĩa, na kwĩmanyĩsya vamwe, atĩ nĩ kw’oko kwa Yeova kwĩkĩte ũu, na Ũla Mũtheu wa Isilaeli nĩwũtw’ĩkĩthĩtye.'),
('kam', 'ISA', 41, 21, 'Etei ndeto syenyu, easya ũu Yeova; umĩlyai itumi syenyu syĩ vinya, easya ũu Mũsumbĩ wa Yakovo.'),
('kam', 'ISA', 41, 22, 'Masyumĩlye, na kũtũtavya ũndũ wĩĩkĩka: tavan’yai maũndũ mavĩtu, nĩ meva, nĩ kana tũmasũanĩe, na kũmanya mũminũkĩlyo wamo; kana twon’yei maũndũ ala mokĩte.'),
('kam', 'ISA', 41, 23, 'Tavan’yai maũndũ ala mokĩte ĩtina, nĩ kana tũmanye mwĩ ngai; ĩĩ, ĩkai ũseo, kana ĩkai ũthũku, nĩ kana tũteve, na kũsisya ũu vamwe.'),
('kam', 'ISA', 41, 24, 'Sisyai, mwĩ ma mana, na wĩa wenyu nĩ wa mana; ũla ũmũnyuvaa nĩ ũthatyo.'),
('kam', 'ISA', 41, 25, 'Nĩnũkĩlĩtye ũmwe kuma ngalĩ ya ĩũlũ, nake nĩ mũku; kuma vala syũa yumĩlaa ũmwe ũla wĩkaĩlaa syĩtwa yakwa: nake akooka ĩũlũ wa asumbĩki ta kũka ĩũlũ wa ndaka, na tondũ mũmbi ũkinyangaa yũmba.'),
('kam', 'ISA', 41, 26, 'Nũũ ũla wathanie kuma wambĩlĩlyonĩ, nĩ kana tũmanye? Na ĩvinda yĩtanavika, nĩ kana twasye, Nake aneena w’o? Ĩĩ, vatiĩ o na ũmwe wathanaa, ĩĩ, vatiĩ o na ũmwe wonanasya, ĩĩ, vatiĩ o na ũmwe wĩw’aa ndeto syenyu.'),
('kam', 'ISA', 41, 27, 'Nyie nĩ wa mbee wa kũtavya Saioni, Sisya, nĩmo aa; na nganenga Yelusaleme ũmwe ũla ũetae maũvoo maseo.'),
('kam', 'ISA', 41, 28, 'Na yĩla ngũsisya, vati mũndũ; o katĩ wamo vati mũtai, ũla ũtonya kũnzũngĩa ũndũ yĩla nĩmakũlya.'),
('kam', 'ISA', 41, 29, 'Sisya, asu onthe, mawĩa moo nĩ mana na ti kĩndũ; mĩvw’anano yoo ĩla maseũvisye na syĩndũ ila matwekethetye nĩ kĩseve na kĩthokoan’yo.'),
('kam', 'ISA', 42, 1, 'Sisya, mũthũkũmi wakwa, ũla nĩmũũngamĩtye; mũnyuvwa wakwa, ũla ngoo yakwa ĩtanaw’a nĩwe: nĩnĩmwĩkĩĩte Veva wakwa; akamaetee Andũ‐ma‐mbaĩ‐ingĩ ũsili wa katĩ.'),
('kam', 'ISA', 42, 2, 'Ndakaĩa, o na ndakokĩlya wasya wake, o na ndakatuma wĩw’ĩka nzĩanĩ nene.'),
('kam', 'ISA', 42, 3, 'Mũangi mũkanyange ndakatũla, na ũtambi ũtoaa syũki ndakavosya: akaumasya sila wa katĩ nthĩnĩ wa w’o.'),
('kam', 'ISA', 42, 4, 'Ndakaleela o na ndakayĩtũka, kũvika aia sila wa katĩ kũũ nthĩ; na ithama ikeeteela mĩao yake.'),
('kam', 'ISA', 42, 5, 'Ũũ nĩw’o Ngai Yeova ũnũũneena, we ũla wombie matu, na kũmatambũũkya; ũla walanilye nthĩ, na kĩla kyumaa nthĩnĩ wayo; ũla ũnengae andũ ala mamĩtũaa mĩthũmũ, na veva ala mamĩkinyaa:'),
('kam', 'ISA', 42, 6, 'nyie, Yeova, nĩnĩkwĩtĩte ũlũngalunĩ, na ngakwata kw’oko kwaku, na ngakũsũvĩa, na ngakũnengane wĩthĩwe ũtianĩo wa andũ, wĩthĩwe kyeni kya Andũ‐ma‐mbaĩ‐ingĩ;'),
('kam', 'ISA', 42, 7, 'ũsalukye metho ma ililinda, wumye ala ove kasũmbanĩ ke nthĩnĩ wa nthĩ, na wumye nyũmbanĩ ya kolokolo ala mekalĩte kĩvindunĩ.'),
('kam', 'ISA', 42, 8, 'Ninyie Yeova, nĩyo syĩtwa yakwa; na ũnene wakwa ndikanenga ũngĩ, kana ndaĩa yakwa kũmĩnenga mĩvw’anano myasũvye.'),
('kam', 'ISA', 42, 9, 'Sisya, maũndũ ma mbee nĩmekĩkĩte, na nĩngũtavan’ya maũndũ meũ; matanamba kumĩla nĩngũmũtavya ũndũ wamo.'),
('kam', 'ISA', 42, 10, 'Mwinĩei Yeova wathi weũ, na ndaĩa yake kuma kĩtulu kya nthĩ; inyw’ĩ ala mũtheeaa mũende na ũkanga, na kyonthe kĩla kĩ nthĩnĩ waw’o, ithama, na ala maitwĩe.'),
('kam', 'ISA', 42, 11, 'Weũ na ndũa syaw’o nĩsyũkĩlye wasya wasyo, mĩsyĩ ĩla andũ ma Ketali mamĩtũaa; ala matwĩe Sela maine, mokĩlye wasya mũnene kuma iĩmanĩ ĩũlũ.'),
('kam', 'ISA', 42, 12, 'Mamũnenevye Yeova, na kũtavan’ya ndaĩa yake ithamanĩ.'),
('kam', 'ISA', 42, 13, 'Yeova akaumaala ta ngũmbaũ; akakan’ya kĩwĩu kyake ta mũndũ wa kaũ: akaĩa, ĩĩ, akookĩlya wasya mũnene; akameka amaitha make maũndũ me vinya.'),
('kam', 'ISA', 42, 14, 'Nĩnĩvindĩtye ĩvinda ĩasa; nĩnĩkilĩtye, na kwĩsiĩĩa: yu nĩngũĩa na wasya mũnene ta mũndũ mũka akyaũnya; ngavevũũka na kũvevaveva ĩmwe.'),
('kam', 'ISA', 42, 15, 'Ngaananga iĩma na tũlĩma, na ngoomya nyũnyi syasyo syonthe; na ngatw’ĩkĩthya mbũsĩ ithama, na ngang’alya ndia.'),
('kam', 'ISA', 42, 16, 'Na ngatwaa ililinda nzĩanĩ ĩla itesi; ngaitongoesya nzĩanĩ ila itesĩ; ngatw’ĩkĩthya kĩvindu kyeni mbee wasyo, na kũndũ kũthyoeku kwĩthĩwe kũlũngalu. Maũndũ asu ngeeka, na ndikamaeka.'),
('kam', 'ISA', 42, 17, 'Makatũngwa, makasonokw’a vyũ, ala mekwatasya mĩvw’anano myasũvye, ala matavasya mĩvw’anano mĩseũvye ya syĩndũ ila matwekethisye, Inyw’ĩ mwĩ ngai sitũ.'),
('kam', 'ISA', 42, 18, 'Ĩthukĩĩsyei, inyw’ĩ au matũ; na sisyai, inyw’ĩ ililinda, mwone.'),
('kam', 'ISA', 42, 19, 'Nũũ kĩlilinda, ate o mũthũkũmi wakwa? Kana mwau matũ, ta mũtũmwa wakwa? Nũũ kĩlilinda ta ũla wĩ na mũuo nakwa, na kĩlilinda ta mũthũkũmi wa Yeova?'),
('kam', 'ISA', 42, 20, 'Nĩwonaa maũndũ maingĩ, ĩndĩ ndũmasũvĩaa; nũteete matũ make, ĩndĩ ndew’aa.'),
('kam', 'ISA', 42, 21, 'Yeova kwondũ wa ũlũngalu wake nĩwendeeiw’e nĩ kũnenevya mĩao, na kũmĩtw’ĩkĩthya yĩ ndaĩa.'),
('kam', 'ISA', 42, 22, 'Ĩndĩ aa nĩ andũ mavutĩtwe na kũtavĩwa; onthe nĩmakwatĩtwe nĩ itei maimanĩ, na nĩmavithĩtwe nyũmbanĩ sya kolokolo: nao nĩ mũtavo, na vai wovoasya; nĩ kũvutwa, na vai wasya, Tũnga.'),
('kam', 'ISA', 42, 23, 'Nũũ katĩ wenyu wĩtea kũtũ ũndũnĩ ũũ? Ũla wĩthukĩĩsya na kwĩw’a ũndũ wa ĩvinda yũkĩte?'),
('kam', 'ISA', 42, 24, 'Nũũ wanenganie Yakovo atavwe, na Isilaeli kwa avutani? Ti Yeova? We ũla twamũvĩtanĩsye, we ũla maleile kũkinyaa nzĩanĩ syake, o na matyaaĩw’a mĩao yake.'),
('kam', 'ISA', 42, 25, 'Kwondũ wa ũu nĩwamwonoisye wai wa ũthatu wake, na vinya wa kaũ; na nĩwamũkwatisye mwaki ngalĩ syonthe, ĩndĩ ndaamanya; naw’o wamũvĩvya, ĩndĩ ndaaĩkĩa ngoonĩ.'),
('kam', 'ISA', 43, 1, 'Ĩndĩ yu Yeova ũla wakũmbie, we Yakovo, na ũla wakũmbie, we Isilaeli, easya atĩĩ: Ndũkakĩe, nũndũ nĩnĩkwovoetye; nĩnĩkwĩtĩte na syĩtwa yaku, wĩ wakwa.'),
('kam', 'ISA', 43, 2, 'Yĩla wĩvĩtĩla manzĩnĩ, ngeethĩwa vamwe naku; na yĩla wĩvĩtĩla mbũsĩnĩ, itikakũvw’ĩka: yĩla wĩvĩtĩla mwakinĩ, ndũkavya, o na ũmũĩ ndũkakana ĩũlũ waku.'),
('kam', 'ISA', 43, 3, 'Nũndũ nyie nĩ Yeova Ngai waku, Ũla Mũtheu wa Isilaeli, Mũtangĩĩi waku; nĩnĩnenganĩte Misili yĩthĩwe mbovosya yaku, Ethiovia na Seva vandũ vaku.'),
('kam', 'ISA', 43, 4, 'Nĩkwĩthĩwa waĩ vata mũno methonĩ makwa, na waĩ na ndaĩa, na nĩnĩkwendete; kwondũ wa ũu nganengane andũ vandũ vaku, na ngo sya andũ vandũ va thayũ waku.'),
('kam', 'ISA', 43, 5, 'Ndũkakĩe; nũndũ nĩ vamwe naku: ngaete ũsyao waku kuma wumĩlonĩ wa syũa, na ũkũmban’ya kuma ũthũĩlonĩ wa syũa;'),
('kam', 'ISA', 43, 6, 'ngatavya ngalĩ ya ĩũlũ, Umya; na ngalĩ ya ĩtheo, Ndũkasiĩĩe; ete ana makwa kuma kũasa, na eĩtu makwa kuma kĩtulunĩ kya nthĩ;'),
('kam', 'ISA', 43, 7, 'kĩla ũmwe wĩtanĩaw’a na syĩtwa yakwa, na ũla noombie ethĩwe wa kũndaĩa, ũla noombie, ĩĩ, ũla namũtw’ĩkĩthisye.'),
('kam', 'ISA', 43, 8, 'Etei ililinda syĩ metho, na ala au matũ me matũ.'),
('kam', 'ISA', 43, 9, 'Mbaĩ syonthe syũmbanw’e vamwe, na ngo sya andũ syũmbanw’e: nũũ katĩ woo ũtonya kũtavan’ya ũu, na kũtwon’ya maũndũ mavĩtu? Nĩmaete ngũsĩ syoo, nĩ kana matalwe alũngalu; kana mew’e, na kwasya, Nĩ w’o.'),
('kam', 'ISA', 43, 10, 'Inyw’ĩ mwĩ ngũsĩ syakwa, easya ũu Yeova, na mũthũkũmi wakwa ũla namũnyuvie; nĩ kana mũmanye na mũmbĩtĩkĩle, na kũmanya ninyie we: vatyaĩ Ngai wombiwe mbee wakwa, o na kũikethĩwa ĩtina wakwa.'),
('kam', 'ISA', 43, 11, 'Nyie, o nyie, nĩ Yeova; na nde vo vati mũtangĩĩi.'),
('kam', 'ISA', 43, 12, 'Nĩnĩneenete, na nĩnĩtangĩĩĩte, na nĩnonetye; na vatyaĩ ngai ngeni katĩ wenyu; kwondũ wa ũu mwĩ ngũsĩ syakwa, easya ũu Yeova, na ninyie Ngai.'),
('kam', 'ISA', 43, 13, 'Ĩĩ, kuma o yĩla kwambĩlilye mũthenya no nyie we; na vati ũmwe ũtonya kumya kw’okonĩ kwakwa: ngatethya wĩa, na nũũ ũla ũtonya kũsiĩĩa?'),
('kam', 'ISA', 43, 14, 'Ũũ nĩw’o Yeova, Mwovosya wenyu, Ũla Mũtheu wa Isilaeli, ũnũkwasya: Kwondũ wenyu nĩnĩtũmanĩte ku Mbaviloni, na ngamaete asu onthe ta akĩi, o Akalitei, ngalawanĩ ila matanĩaa,'),
('kam', 'ISA', 43, 15, 'Ninyie Yeova, Ũla Mũtheu wenyu, Mũmbi wa Isilaeli, Mũsumbi wenyu.'),
('kam', 'ISA', 43, 16, 'Ũũ nĩw’o Yeova ũnũkwasya, ũla ũseũvasya nzĩa ũkanganĩ, na nzĩa manzĩnĩ maingĩ:'),
('kam', 'ISA', 43, 17, 'ũla umaalasya ĩkasya na mbalasi, ita na ala me ũtonyi (nĩmakomaa vamwe, matikokĩla; nĩ athelu, nĩmavoetw’e ta ũtambi):'),
('kam', 'ISA', 43, 18, 'Mũtikalilikane maũndũ mavĩtu, o na mũtikasũanĩe maũndũ ma tene.'),
('kam', 'ISA', 43, 19, 'Sisya, ngeeka ũndũ weũ; oyu ũkaumĩla; mũtikomanya? O na ngaseũvya nzĩa weũnĩ, na mbũsĩ yalatanĩ.'),
('kam', 'ISA', 43, 20, 'Nyamũ sya kĩthekanĩ ikandaĩa, mbĩwa na nyaa; nĩkwĩthĩwa numasya manzĩ weũnĩ, na mbũsĩ yalatanĩ, nĩmanyw’ĩthye andũ makwa, ala anyuve makwa,'),
('kam', 'ISA', 43, 21, 'andũ ala namombie kwondũ wakwa mwene, nĩ kana monan’ye ndaĩa yakwa.'),
('kam', 'ISA', 43, 22, 'Ĩndĩ ndwaambĩkaĩla, we Yakovo; ĩndĩ nĩwangolile, we Isilaeli.'),
('kam', 'ISA', 43, 23, 'Ndwaandetee malondu maku methĩwe nthembo sya kũvĩvw’a; o na ndwaandaĩa na nthembo syaku sya kũtonywa. Ndyaaũthĩn’ya ũndũ wa nthembo, o na ndyaakũnosya ũndũ wa ũvumba.'),
('kam', 'ISA', 43, 24, 'Ndwaanthooea ithua na mbesa, o na ndwaambũn’ya na mathunya ma nthembo syaku: ĩndĩ nĩwanthĩnisye na naĩ syaku, nĩwanoisye na mothũku maku.'),
('kam', 'ISA', 43, 25, 'Nyie, o nyie, ninyie ũla ũvutaa mavĩtyo maku kwondũ wakwa mwene; na ndikalilikana naĩ syaku.'),
('kam', 'ISA', 43, 26, 'Ndilikan’ya; tũneenan’ye vamwe; umĩlya ũvoo waku, nĩ kana ũtalwe mũlũngalu.'),
('kam', 'ISA', 43, 27, 'Ĩthe waku wa mbee nĩwavĩtisye, na amanyĩsya maku nĩmambĩtanĩsye.'),
('kam', 'ISA', 43, 28, 'Kwondũ wa ũu ngavukya atongoi ma vala vandũ vatheu; na ngatw’ĩkĩthya Yakovo kĩumo, na Isilaeli wa kumangwa.'),
('kam', 'ISA', 44, 1, 'Ĩndĩ yu ĩw’a, we Yakovo mũthũkũmi wakwa, na Isilaeli, ũla nĩnyuvĩte:'),
('kam', 'ISA', 44, 2, 'Ũũ nĩw’o Yeova ũnũkwasya ũla wakũtw’ĩkĩthisye, na ũkũmbĩa ĩvunĩ, ũla ũkakũtethya: Ndũkakĩe, we Yakovo mũthũkũmi wakwa; na we Yesuluni, ũla nĩnyuvĩte.'),
('kam', 'ISA', 44, 3, 'Ngamwĩtĩkĩsya manzĩ ũla wĩ na waũni, na ngoonosya tũlũsĩ nthĩ nyũmũ; ngatulũla Veva wakwa ĩũlũ wa ũsyao waku, na ũathimo wakwa syananĩ syaku:'),
('kam', 'ISA', 44, 4, 'na ikathandĩkangĩla nyekinĩ, ta mĩtĩ ĩla ĩmeaa vakuvĩ na mbũsĩ.'),
('kam', 'ISA', 44, 5, 'Ũmwe akasya, Nyie nĩ wa Yeova; na ũngĩ akeeyĩtanĩsya na syĩtwa ya Yakovo; na ũngĩ akaandĩka kw’okonĩ kwake atĩ nĩ wa Yeova, na akeenenga syĩtwa yĩngĩ ya Isilaeli.'),
('kam', 'ISA', 44, 6, 'Yeova, Mũsumbĩ wa Isilaeli, ũla Mwovosya wake, Yeova wa nguthu, easya atĩĩ: Ninyie wa mbee, na ninyie wa mũminũkĩlyo; na vati Ngai ate o nyie.'),
('kam', 'ISA', 44, 7, 'Na nũũ, takwa, ũketana, na kũtavan’ya ũu, na kũseũvya ũndũ wakwa, kuma yĩla naiie andũ ma tene tene? O na maũndũ ala mokĩte, na ala makethĩwa, nĩmatavan’ye.'),
('kam', 'ISA', 44, 8, 'Mũtikakĩe, o na mũtikethĩwe na w’ĩa: ndyaakũtavya kuma tene, na kwonan’ya ũu? Na inyw’ĩ mwĩ ngũsĩ syakwa. Ve Ngai ate nyie? Ĩĩ, vati Ĩvia; ndyĩsĩ ũngĩ.'),
('kam', 'ISA', 44, 9, 'Nao onthe ala maseũvasya mũvw’anano mwasũvye nĩ ma mana; na maũndũ ala mamatanĩaa matikauna kĩndũ; na ngũsĩ syoo ene ityonaa, o na itimanyaa: nĩ kana masonokw’e.'),
('kam', 'ISA', 44, 10, 'Nũũ ũla waseũvisye ngai ĩmwe, kana watwekethisye syĩndũ sya kũseũvya mũvw’anano ũla ũtaunaa kĩndũ?'),
('kam', 'ISA', 44, 11, 'Sisya, atindan’ya make onthe makasonokw’a; na ndũĩka, nasyo no sya andũ: onthe mombanw’e vamwe, nĩmaũngame; makakĩa, makasonokw’a vamwe.'),
('kam', 'ISA', 44, 12, 'Mũtwii nũtuaa ĩthoka, na kũtethya wĩa na makaa, na kũyĩseũvya na syĩiva, na kũyũmba na kw’oko kwake kwĩ vinya: ĩĩ, nĩwĩw’aa nzaa, na vinya wake nũũthela; ndanyusaa manzĩ, na nũnũũnyala.'),
('kam', 'ISA', 44, 13, 'Mũseũvya wa mbwaũ nũtambũũkasya ũlii; nũkululaa na kĩandĩki; nũseũvasya na landa, na nũkululaa na kambasi, na nĩwũmbaa ta mũvw’anano wa mũndũ, kwĩanana na mũmbĩlw’e mũseo wa mũndũ, wĩkale nyũmbanĩ.'),
('kam', 'ISA', 44, 14, 'Nĩwĩtemeaa mĩkũũ na nĩwosaa mũtĩ wa mũtilisa na wa mwaloni, na kwĩsavĩĩa mũtĩ ũmwe katĩ wa mĩtĩ ya mũtitũ kwondũ wake mwene; nũvandaa mũsonovali, na mbua nĩyũnyithasya.'),
('kam', 'ISA', 44, 15, 'Nĩvo ĩndĩ ũkethĩwa wa kũvĩvw’a nĩ mũndũ; nake nĩwosaa kĩlungu kyaw’o, na aikyota; ĩĩ, nũkyakanasya, na kũua kĩmũtũ: ĩĩ, nũseũvasya ngai, na kũmĩthaitha; nũkĩtw’ĩkĩthasya mũvw’anano mwasũvye, na aivalũka mbee waw’o.'),
('kam', 'ISA', 44, 16, 'Nũvĩvasya kĩlungu kyaw’o na mwaki; nũĩsaa nyama na kĩlungu kyaw’o; nũkaangaa nyama, na aivũna; ĩĩ, nũkyota aiasya, Aa! Nĩngwĩw’a muutĩa, nĩnonete mwaki.'),
('kam', 'ISA', 44, 17, 'Na kĩlungu kĩla kyatiala nũkĩseũvasya ngai, o mũvw’anano wake mwasũvye; nũvalũkaa mbee waw’o na kũthaitha, na kũvoya, na aiasya, Ndangĩĩa, nũndũ nue Ngai wakwa.'),
('kam', 'ISA', 44, 18, 'Matyĩsĩ, o na matiũsũanĩa: nũndũ nũlalĩtye metho moo, ũndũ matatonya kwona; na ngoo syoo, ũndũ matatonya kũmanya.'),
('kam', 'ISA', 44, 19, 'Na vai ũla ũlilikanasya, o na vai ũĩ kana ũmanyi wa kwasya, Nĩnĩvĩvĩtye kĩlungu kyaw’o na mwaki; ĩĩ, o na nĩnĩuĩte kĩmũtũ na makaa maw’o; nĩnĩkaangĩte nyama na ngamĩya: na ngatw’ĩkĩthya kĩlungu kĩla kyatiala ũthatyo? Ngavalũka mbee wa ĩtina ya mũtĩ?'),
('kam', 'ISA', 44, 20, 'Nũĩsaa mũu; ngoo ĩkengetwe nĩnĩmwathũkĩtye; na ndatonya kũtangĩĩa thayũ wake, kana kũkũlya, Vati ũvũngũ kw’okonĩ kwakwa kwa aũme?'),
('kam', 'ISA', 44, 21, 'Lilikana maũndũ aa, we Yakovo, na Isilaeli; nũndũ wĩ mũthũkũmi wakwa: nĩnakũmbie; wĩ mũthũkũmi wakwa: we Isilaeli, ndikolwa nue.'),
('kam', 'ISA', 44, 22, 'Nĩnĩvutĩte mavĩtyo maku ta ĩthweo ĩkamu, na ta ĩthweo, naĩ syaku: nzyokea; nũndũ nĩngwovoetye.'),
('kam', 'ISA', 44, 23, 'Inai, inyw’ĩ matu, nũndũ Yeova nĩwĩkĩte ũu; ũkĩlyai wasya mũnene, inyw’ĩ kũndũ kwĩ nthĩnĩ wa nthĩ; ambĩlĩlyai kwina, inyw’ĩ iĩma, we mũtitũ, na kĩla mũtĩ wĩ nthĩnĩ: nũndũ Yeova nũmwovoetye Yakovo, na akeetaĩa nthĩnĩ wa Isilaeli.'),
('kam', 'ISA', 44, 24, 'Yeova, Mwovosya waku, ũla wakũmbĩe ĩvunĩ easya atĩĩ: Ninyie Yeova, ũla ũseũvasya syĩndũ syonthe; ũla ũtambũũkasya matu nĩ nyioka; ũla walanasya nthĩ (nũũ wĩ nakwa?);'),
('kam', 'ISA', 44, 25, 'Ũla ũtw’ĩkĩthasya sya mana syama sya aneeni ma ũvũngũ, na kũmaũũkĩthya ala maaũasya; ũla ũtũngaa na ĩtina andũ oĩ, na kũtw’ĩkĩthya ũmanyi woo ũtumanu;'),
('kam', 'ISA', 44, 26, 'ũla ũlũlũmĩlasya ndeto ya mũthũkũmi wake, na kwĩanĩsya ũtao wa atũmwa make; ũla ũneenaa ũndũ wa Yelusaleme atĩĩ, Ĩkatũwa nĩ andũ; na ũndũ wa ndũa sya Yuta, Ikaakwa, na ngookĩlya kũndũ kwanangĩku kwasyo;'),
('kam', 'ISA', 44, 27, 'ũla ũtavasya manzĩ maliku, Ng’ala, nakwa nĩngũng’alĩthya mbũsĩ syaku;'),
('kam', 'ISA', 44, 28, 'ũla ũneenaa ũndũ wa Kulusi, Nĩ mũĩthi wakwa, na akeeka kwenda kwakwa kw’onthe, o na akĩneena ũndũ wa Yelusaleme, Ĩkaakwa; na ũndũ wa ĩkalũ, Wambĩlĩlyo waku ũkakwatw’a.'),
('kam', 'ISA', 45, 1, 'Ũũ nĩw’o Yeova ũnũũmũtavya Kulusi mwĩtĩkĩw’a mauta wake, ũla nĩkwatĩte kw’oko kwake kwa aũme, nĩkĩlasye mbaĩ vinya ũndũ wake, na ngaleelya inyunyu sya asumbĩ; nĩvingũae mĩomo mbee wake, na mbingĩlo itikavingwa:'),
('kam', 'ISA', 45, 2, 'ngathi mbee waku, na ngatw’ĩkĩthya kũndũ kũthũku kũtindimalu; ngatilanga ilungu mĩomo ya ũthuku, na ngatilanga ivingi sya iaa;'),
('kam', 'ISA', 45, 3, 'na ngakũnenga syĩndũ syĩ vata mũno syĩ kĩvindunĩ, na mothwii mavithe ma kũndũ kũtesĩkĩwe, nĩ kana ũmanye atĩ ninyie Yeova, ũla ũkwĩtaa na syĩtwa yaku, o Ngai wa Isilaeli.'),
('kam', 'ISA', 45, 4, 'Kwondũ wa Yakovo mũthũkũmi wakwa, na Isilaeli mũnyuvwa wakwa, nĩnĩkwĩtĩte na syĩtwa yaku: nĩngũnengete syĩtwa yĩngĩ, o na kau ndũnambĩsĩ.'),
('kam', 'ISA', 45, 5, 'Ninyie Yeova, na vati ũngĩ; nde vo vati Ngai. Ngakũvotoa, o na kau ndũnambĩsĩ;'),
('kam', 'ISA', 45, 6, 'nĩ kana mamanye kuma vala syũa yumĩlaa, oa kuma ũthũĩlonĩ wa syũa kana vati ũngĩ ate o nyie: ninyie Yeova, na vati ũngĩ.'),
('kam', 'ISA', 45, 7, 'Nĩngũseũvya kyeni, na ngyũmba kĩvindu; nĩngũseũvya mũuo, na ngyũmba ũthũku; ninyie Yeova, ũla wĩkaa maũndũ asu onthe.'),
('kam', 'ISA', 45, 8, 'Volotangai, inyw’ĩ matu, kuma ĩũlũ, na mathweo metĩkye ũlũngalu: nthĩ ĩvingũke, nĩ kana ĩetae ũtangĩĩo, na yumĩlye ũlũngalu vamwe; nyie, Yeova, nĩnĩmĩtw’ĩkĩthĩtye.'),
('kam', 'ISA', 45, 9, 'Woo nĩ wa ũla ũkĩlanasya vinya na Mũmbĩ wake! Kĩlĩo katĩ wa ilĩo sya nthĩ! Yũmba yĩkakũlya ũla wayũmbie, Wĩũmba kyaũ? Kana wĩa waku ũkasya, Nde moko?'),
('kam', 'ISA', 45, 10, 'Woo nĩ wa ũla ũkũlasya ĩthe, Wĩsyaa kyaũ? Kana mũndũ mũka, Wĩaũnya kyaũ?'),
('kam', 'ISA', 45, 11, 'Yeova, Ũla Mũtheu wa Isilaeli, na nĩwe Mũmbi wake, easya atĩĩ: Ngũlyai ũndũ wa maũndũ ala mokĩte; ĩndaĩei ũndũ wa ana makwa, na ũndũ wa wĩa wa moko makwa.'),
('kam', 'ISA', 45, 12, 'Nĩnĩtw’ĩkĩthĩtye nthĩ, na nĩnũmbĩte mũndũ ĩũlũ wayo: nyie, o moko makwa, nĩnĩtambũũkĩtye matu; na nguthu yamo yonthe nĩnĩmĩaĩĩte.'),
('kam', 'ISA', 45, 13, 'Nĩnĩmũkĩlĩtye nthĩnĩ wa ũlũngalu, na ngalũngalya nzĩa syake syonthe: akaaka ndũa yakwa, na akathasya makwa ala malũngilw’e kwoo, ti ũndũ wa kũĩvwa kana kũnengwa mbesa, easya ũu Yeova wa nguthu.'),
('kam', 'ISA', 45, 14, 'Ũũ nĩw’o Yeova ũnũkwasya, Wĩa wa Misili, na mĩio ya kũthoosya ya Ethiovia, na Aseva, andũ aasa mũno, makooka ngalĩ yaku, na makeethĩwa maku; makakũatĩĩa; makooka me ove na mĩnyololo; na makavalũka nthĩ mbee waku, makakwĩsũva, makyasya, Vate ndĩĩ Ngai e nthĩnĩ waku; na vati ũngĩ, vati Ngai ũngĩ.'),
('kam', 'ISA', 45, 15, 'Nĩ w’o nue Ngai ũla wĩvithaa, ame Ngai wa Isilaeli, Mũtangĩĩi.'),
('kam', 'ISA', 45, 16, 'Makasonokw’a, ĩĩ, makathokoanw’a, asu onthe; ala maseũvasya mĩvw’anano makalika kĩthokoonĩ vamwe.'),
('kam', 'ISA', 45, 17, 'Ĩndĩ Isilaeli akatangĩĩwa nĩ Yeova na ũtangĩĩo wa tene na tene: mũtikasonokw’a kana kũthokoanw’a kũvika tene na tene.'),
('kam', 'ISA', 45, 18, 'Nũndũ Yeova ũla watw’ĩkĩthisye matu, Ngai ũla watw’ĩkĩthisye nthĩ na kũmyũmba, ũla wamĩlũlũmĩlye na ndaamyũmba yĩ nthei, ũla wamyũmbie yĩthĩwe ya kũtũa andũ, easya atĩĩ: Ninyie Yeova; na vati ũngĩ.'),
('kam', 'ISA', 45, 19, 'Ndyaaneenea kĩmbithĩnĩ, vandũ va nthĩ ve kĩvindu; ndyaatavya ũsyao wa Yakovo, Manthai nyie mana: nyie, Yeova, nĩneenaa ũlũngalu, nĩtavanasya maũndũ ma w’o.'),
('kam', 'ISA', 45, 20, 'Ĩyũmban’yei na mũyũka; thengeeai vamwe, inyw’ĩ ala mwavonokie ma i mbai: mati na ũmanyi ala makuaa mũvw’anano woo mwasũvye wa mũtĩ, na kũvoya ngai ĩla ĩtatonya kũtangĩĩa.'),
('kam', 'ISA', 45, 21, 'Tavan’yai, ũmyai ũvoo; ĩĩ, masũanĩe vamwe: nũũ ũla wonanisye ũu kuma tene tene? Nũũ ũla watavanisye ũu kuma tene? Ti nyie Yeova? Na vati Ngai ũngĩ ate nyie, Ngai mũlũngalu na Mũtangĩĩi; vati ũngi ate o nyie.'),
('kam', 'ISA', 45, 22, 'Nzisyai, mũtangĩĩwe, itulu syonthe sya nthĩ; nũndũ ninyie Ngai, na vati ũngĩ.'),
('kam', 'ISA', 45, 23, 'Nĩnĩavĩte nakwa mwene, ndeto nĩyumĩte kanyw’anĩ wakwa nthĩnĩ wa ũlũngalu, na ndĩkasyoka, atĩ kĩla ĩu yĩkatulya ndu mbee wakwa, kĩla ũĩmĩ ũkeevĩta.'),
('kam', 'ISA', 45, 24, 'Nĩkũneenetwe ũndũ wakwa, No nthĩnĩ wa Yeova ve ũlũngalu na vinya; andũ makooka vala ũĩ; na onthe ala mamũthatĩe makasonokw’a.'),
('kam', 'ISA', 45, 25, 'Ũsyao w’onthe wa Isilaeli ũkatalwa mũlũngalu, na kwĩkathĩĩa nthĩnĩ wa Yeova.'),
('kam', 'ISA', 46, 1, 'Veli nĩkũtulya ndu, Nevo nĩkwĩkunamya; mĩvw’anano yasyo yĩ ĩũlũ wa nyamũ, na ĩũlũ wa indo: syĩndũ ila mwangangie mũkuĩte nĩsyatw’ĩkie mũio, mũio wa kũnosya nyamũ ĩla ĩkuĩte.'),
('kam', 'ISA', 46, 2, 'Nasyo nikwĩkunamya, nikũtulya ndu vamwe; ityaatonya kũmĩvonokya, ĩndĩ syo nĩ nendu syĩ ndave.'),
('kam', 'ISA', 46, 3, 'Mbĩthukĩĩsya, we nyũmba ya Yakovo, na ũtialo w’onthe wa nyũmba ya Isilaeli, inyw’ĩ ala mwakuiwe ninyie kuma kũsyawa kwenyu, o ala mwakuiwe ninyie mwauma ĩvunĩ;'),
('kam', 'ISA', 46, 4, 'o na kũvika mwatumĩa ninyie we, o na kũvika nzw’ĩĩ syĩ mbuĩ, ngamũkua: nĩnoombie na ngakua; ĩĩ, ngakua, na ngavonokya.'),
('kam', 'ISA', 46, 5, 'Mũkangelekan’ya nyie naũ, na kũmbĩanan’ya, na kũngelekan’ya, nĩ kana twĩthĩwe tũvw’anene?'),
('kam', 'ISA', 46, 6, 'Ala maumasya thaavu mũvukonĩ, na kũthima vetha kĩthiminĩ, nĩmamũtuvaa mũtwii wa thaavu, nake nũseũvasya ngai; nĩmavalũkaa, ĩĩ, nĩmathaithaa.'),
('kam', 'ISA', 46, 7, 'Nĩmamĩkuaa kĩtuonĩ, maimĩkua, na kũmĩũngamya vandũ vayo, nayo nĩũngamaa; ndĩkauma vandũ vayo: ĩĩ, mũndũ nũtonya kũmĩkaĩla, ĩndĩ ndĩtonya kũsũngĩa, kana kũmũtangĩĩa thĩnanĩ wake.'),
('kam', 'ISA', 46, 8, 'Lilikanai ũu, na mũkyonan’ya mwĩ aũme; lilikanai ĩngĩ, ĩnyw’ĩ avĩtan’ya.'),
('kam', 'ISA', 46, 9, 'Lilikanai maũndũ mavĩtu ma tene: nũndũ ninyie Ngai, na vati ũngĩ; ninyie Ngai, na vati ũngĩ takwa;'),
('kam', 'ISA', 46, 10, 'ngĩtavan’ya mũminũkĩlyo kuma mwambĩlĩlyonĩ, na kuma tene tene maũndũ ala matanamba kwĩkwa; ngyasya, Ũtao wakwa ũkaũngama, na ngeeka kwenda kwakwa kw’onthe;'),
('kam', 'ISA', 46, 11, 'ngĩta nyũnyi mbai kuma ngalĩ ya wumĩlonĩ wa syũa, mũndũ wa ũtao wakwa kuma nthĩ ndasa; ĩĩ, nĩnĩneenete, na ngawĩanĩsya; nĩnĩsũanĩĩte, na ngawĩka.'),
('kam', 'ISA', 46, 12, 'Mbĩthukĩĩsyai, inyw’ĩ mwĩ ngoo nyũmũ, ala mwĩ kũasa na ũlũngalu:'),
('kam', 'ISA', 46, 13, 'nĩngũthengeesya ũlũngalu wakwa, ndwĩĩthĩwa wĩ kũasa, na ũtangĩĩo wakwa ndũtĩa kũka; na ngaia ũtangĩĩo nthĩnĩ wa Saioni kwondũ wa Isilaeli ũtaĩo wakwa.'),
('kam', 'ISA', 47, 1, 'Theea, wĩkale kĩtoonĩ, we mwĩĩtu mũtheu wa Mbaviloni; ĩkala nthĩ ũte na kĩvĩla kya ũsumbĩ, we mwĩĩtu wa Akalitei: nũndũ ndũketwa mwololo na mwanake ĩngĩ.'),
('kam', 'ISA', 47, 2, 'Osa mavia ma kũthia, ũthie mũtu; umya suka waku mũvũthũ ũthyũnĩ, umya ngũa ya mũnyelele, vua kũũ, vĩtĩla mbũsĩnĩ'),
('kam', 'ISA', 47, 3, 'Ũkavuwa woneke wĩ mũthei, ĩĩ, nthoni syaku ikooneka: ngeeĩvanĩsya, na ndikatia mũndũ o na wĩva.'),
('kam', 'ISA', 47, 4, 'Mwovosya waitũ, Yeova wa nguthu nĩyo syĩtwa yake, Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 47, 5, 'Ĩkala ũvindĩtye, na enda kĩvindunĩ, we mwĩĩtu wa Akalitei; nĩkwĩthĩwa ndũketwa ĩngĩ Vivi wa mosumbĩ.'),
('kam', 'ISA', 47, 6, 'Nĩnathilĩkĩle andũ makwa, nĩnavukisye ũtiĩwa wakwa, na nĩnamanenganie kw’okonĩ kwaku: naku ndwaamew’ĩa tei; nũmekĩĩte ala akũũ ĩsoki yaku na vinya.'),
('kam', 'ISA', 47, 7, 'Naku wasya, Ngeethĩwa vivi tene na tene; kwondũ wa ũu ndwaaia maũndũ aa ngoonĩ yaku, o na ndwaalilikana mũminũkĩlyo wamo.'),
('kam', 'ISA', 47, 8, 'Kwondũ wa ũu ĩw’a ũũ, we ũla wĩnenganĩte motanunĩ, ũla wĩkalaa ũlũmĩte, ũla ũkwasya ngoonĩ yaku, Ninyie, na vati ũngĩ ate o nyie; ndikekala ta mũndũ mũka ndiwa o na ndikamanya kũkw’ĩĩwa nĩ syana:'),
('kam', 'ISA', 47, 9, 'ĩndĩ maũndũ aa elĩ makakũkĩa na kĩthũlũmũko mũthenya ũmwe, kũkw’ĩĩwa nĩ syana na kwĩkala wĩ ndiwa; makakũkĩa na kĩthimi kĩanĩu, wĩ na wingĩ wa mooi maku, na wingĩ wa mowe maku.'),
('kam', 'ISA', 47, 10, 'Nĩwĩkwatĩtye ũthũku waku; nũneenete, Vai ũmbonaa; ũĩ waku na ũmanyi waku nũkwelelũkĩtye; na nũneenete ngoonĩ yaku, Ninyie, na vati ũngĩ ate o nyie.'),
('kam', 'ISA', 47, 11, 'Kwondũ wa ũu ũthũku ũkakũkĩa; ndũkamanya vala wumĩte: na ũthũku ũkakũvalũkĩla; ndũkatonya kũveta: na wanangĩko ũla ũtesĩ ũkakũkĩa na kĩthũlũmũko.'),
('kam', 'ISA', 47, 12, 'Ũngama yu wĩ na mowe maku, na mooi maku maingĩ, ala wathĩnĩe kuma wana waku; ethĩwa nũtonya kwĩuna, ethĩwa nũtonya kũkĩlya vinya.'),
('kam', 'ISA', 47, 13, 'Nũnoetwe nĩ motao maku maingĩ: na yu ala mathanaa na ndata, o ala masiasya ndata, ala mathanaa kĩla mwei, nĩmaũngame, makũtangĩĩe kuma maũndũnĩ ala meũka kwaku.'),
('kam', 'ISA', 47, 14, 'Sisya makeethĩwa ta mavuthĩ; mwaki ũkamavĩvya; matiketangĩĩa kuma vinyanĩ wa ũmũĩ: ndũkethĩwa ĩkaa ya kwota, o na mwaki wa kũthengeewa.'),
('kam', 'ISA', 47, 15, 'Maũndũ ala watethisye makeethĩwa mailyĩ ũu kwaku: ala matandĩthasya naku kuma wana waku makanyaĩĩka kĩla ũmwe na nzĩa yake; vatikethĩwa ũmwe wa ũkũtangĩĩa.'),
('kam', 'ISA', 48, 1, 'Ĩw’ai ũũ, inyw’ĩ nyũmba ya Yakovo, ala mwĩtanĩaw’a na syĩtwa ya Isilaeli, na mumĩte kĩnyunyunĩ kya Yuta; ala mwĩvĩtaa na syĩtwa ya Yeova, na kũweta Ngai wa Isilaeli, ĩndĩ ti nthĩnĩ wa w’o, o na ti nthĩnĩ wa ũlũngalu'),
('kam', 'ISA', 48, 2, '(nũndũ nĩmeyĩtaa ma ndũa ntheu, na kwĩtw’ĩĩka na Ngai wa Isilaeli; Yeova wa nguthu nĩyo syĩtwa yake):'),
('kam', 'ISA', 48, 3, 'nĩnĩtavanĩtye maũndũ mavitu kuma tene; ĩĩ, nĩmaumie kanyw’anĩ wakwa, na namonan’ya: nĩnamekie na kĩthũlũmũko, na meekĩka.'),
('kam', 'ISA', 48, 4, 'Nĩkwĩthĩwa nesĩ wĩ mũng’endu, na ngingo yaku nĩ ĩkono ya kĩaa, na kĩtulya kyaku nĩ ũthuku;'),
('kam', 'ISA', 48, 5, 'kwondũ wa ũu nĩnakũtavĩtye kuma tene; ũtanamba kwĩthĩwa nĩnakwonisye; ndũkese kwasya, Mũvw’anano wakwa nĩwĩkĩte ũu, na mũvw’anano wakwa mwasũvye, na mũvw’anano wakwa naseũvisye na syĩndũ natwekethisye, nĩyeeaie mekwe.'),
('kam', 'ISA', 48, 6, 'Nĩwĩw’ĩte ũu, sisya, ũndũ ũũ w’onthe; na inyw’ĩ mũtikatavan’ya ũu? Nĩngwonetye maũndũ meũ kuma ĩvinda yĩĩ, o maũndũ mavithe, ala ũtaamanya.'),
('kam', 'ISA', 48, 7, 'Nĩmombĩtwe yu, na ti kuma tene; ndwaamew’a ate o ũmũnthĩ; ndũkese kwasya, Sisya, nĩnamesĩ.'),
('kam', 'ISA', 48, 8, 'Ĩĩ, ndwaaĩw’a; ĩĩ, ndwaamanya; ĩĩ, kuma tene kũtũ kwaku kũtyaĩ kũvingũe: nũndũ nĩneesĩ kana nĩweekie ũseleke mũno, na weetiwe mũvĩtan’ya o kuma ĩvunĩ.'),
('kam', 'ISA', 48, 9, 'Kwondũ wa syĩtwa yakwa ngatĩsya kyathĩ kya ũthatu wakwa, na kwondũ wa ndaĩa yakwa ngeesiĩĩa ũndũ waku, ndikakũvete.'),
('kam', 'ISA', 48, 10, 'Sisya, nĩnĩkũtheetye, ĩndĩ ti ta vetha; nĩnĩkũtatĩe ikonĩ ĩnene ya thĩna.'),
('kam', 'ISA', 48, 11, 'Kwondũ wakwa mwene, kwondũ wakwa mwene, ngawĩka; nũndũ syĩtwa yakwa yĩtonya kũthũkw’a ata? Na ndaĩa yakwa ndikanenga ũngĩ.'),
('kam', 'ISA', 48, 12, 'Mbĩthukĩĩsya, we Yakovo, na Isilaeli mwĩtwa wakwa: ninyie we; ninyie mwambĩlĩlyo, o na ninyie mũninũkĩlyo.'),
('kam', 'ISA', 48, 13, 'Ĩĩ, kw’oko kwakwa nĩkwambĩlĩlye wambĩlĩlyo wa nthĩ, na kw’oko kwakwa kwa aũme nĩkũtambũũkĩtye matu: yĩla nzyĩtaa niũngamaa vamwe.'),
('kam', 'ISA', 48, 14, 'Ĩyũmban’yei, inyw’onthe, mwĩthukĩĩsye; nũũ katĩ woo ũtavanĩtye maũndũ aa? Ũla Yeova ũmwendete nĩwe ũkeanĩsya kwenda kwake ĩũlũ wa Mbaviloni, na kw’oko kwake kũkeethĩwa ĩũlũ wa Akalitei.'),
('kam', 'ISA', 48, 15, 'Nyie, o nyie, nĩnĩneenete; ĩĩ, nĩnĩmwĩtĩte; nĩnĩmũetete, na akaaĩlya nzĩa yake.'),
('kam', 'ISA', 48, 16, 'Thengeeai vakuvĩ nakwa, ĩw’ai ũũ; kuma wambĩlĩlyonĩ ndyaaneena na kĩmbithĩ; kuma ĩvinda yĩla ũũ wambĩlĩlw’e, naĩ vo: na yu Mwĩaĩĩ Yeova, vamwe na Veva wake, nũndũmĩte.'),
('kam', 'ISA', 48, 17, 'Ũũ nĩw’o Yeova, Mwovosya waku, Ũla Mũtheu wa Isilaeli, ũnũkwasya: Ninyie Yeova Ngai waku, ũla ũkũmanyĩasya kwaĩla, ũla ũkũtongoeasya nzĩanĩ ĩla waĩle kũthi nayo.'),
('kam', 'ISA', 48, 18, 'A! Kethĩwa wethukĩĩsye mĩao yakwa! Nĩvo ĩndĩ mũuo waku wĩthĩwa wailyĩ ta ũsĩ, na ũlũngalu waku ta itulumo sya ũkanga:'),
('kam', 'ISA', 48, 19, 'ũsyao waku wĩthĩwa wailyĩ kĩthangathĩ, na ũsyao wa ĩvu yaku ta mbeke syakyo: syĩtwa yake yĩtyĩthĩwa yĩ ĩvete kana kwanangwa kuma vala nĩĩ.'),
('kam', 'ISA', 48, 20, 'Umai Mbaviloni, kĩai mume vala ve Akalitei; tavan’yai na wasya wa kwina, tavan’yai ũndũ ũũ, nyaĩĩkyai o kũvika kĩtulu kya nthĩ: neenai atĩĩ, Yeova nũmwovoetye mũthũkũmi wake Yakovo.'),
('kam', 'ISA', 48, 21, 'Na matyaaĩw’a waũni yĩla wamatongoesye malatanĩ; nĩwamaumĩsye manzĩ yĩla ĩvianĩ; na ĩngĩ aatũa ĩvia, na manzĩ mauma na vinya.'),
('kam', 'ISA', 48, 22, 'Vati mũuo kwa athũku, easya ũu Yeova.'),
('kam', 'ISA', 49, 1, 'Mbĩthukĩĩsyai, inyw’ĩ ithama; ĩw’ai, inyw’ĩ ngo sya andũ, ila syĩ kũasa: Yeova nĩwambĩtie o kuma ĩvunĩ; kuma nĩ nda kwa mwaitũ nĩwawetie syĩtwa yakwa:'),
('kam', 'ISA', 49, 2, 'na nũseũvĩtye kanyw’a wakwa wĩthĩwe ta ũvyũ mũĩ; nũmbithĩte muunyĩnĩ wa kw’oko kwake: na nũndw’ĩkĩthĩtye mũsyĩ mũtendeu mũno; nũmbithĩte thyakanĩ wake:'),
('kam', 'ISA', 49, 3, 'na ambĩa, Nue mũthũkũmi wakwa; Isilaeli, ũla ngataĩwa nthĩnĩ waku.'),
('kam', 'ISA', 49, 4, 'Ĩndĩ nasya, Nĩnĩtethetye wĩa mana, nĩnanangĩte vinya wakwa mana vate kĩndũ; ĩndĩ kũtw’ĩĩwa kwakwa kũmbaĩle kwĩ na Yeova, na kũĩvwa kwakwa kwĩ na Ngai wakwa.'),
('kam', 'ISA', 49, 5, 'Na yu Yeova easya, we ũla wambũmbĩe ĩvunĩ nĩthiwe mũthũkũmi wake, nĩmũtũnge Yakovo kwake ĩngĩ, na Isilaeli ombanw’e kwake (nũndũ nĩ na ndaĩa methonĩ ma Yeova, na Ngai wakwa nũtw’ĩkĩte vinya wakwa);'),
('kam', 'ISA', 49, 6, 'ĩĩ, easya, Nĩ ũndũ ũvũthũ mũno kwĩthĩwa mũthũkũmi wakwa wa kũkĩlya mbaĩ sya Yakovo, na kũtũnga ala masũvĩiwe ma Isilaeli: o na ĩngĩ ngakũnengane wĩthĩwe kyeni kya Andũ‐ma‐mbaĩ‐ingĩ, nĩ kana wĩthĩwe ũtangĩĩo wakwa kũvika kĩtulu kya nthĩ.'),
('kam', 'ISA', 49, 7, 'Yeova, Mwovosya wa Isilaeli, Ũla Mũtheu wake, emwĩa ũla ũvũthaw’a nĩ andũ, ũla ũthĩthawa nĩ mbaĩ, mũthũkũmi wa asumbĩki atĩĩ: Asumbĩ makoona na makookĩla; o na anene me mbee ũsumbĩnĩ, na makathaitha; ũndũ wa Yeova ũla wĩ na kĩthito, Ũla Mũtheu wa Isilaeli, ũla wakũnyuvie.'),
('kam', 'ISA', 49, 8, 'Ũũ nĩw’o Yeova ũnũkwasya, Nĩnakũsũngĩie ĩvinda yĩla yĩtĩkĩlĩtwe, na mũthenya wa ũtangĩĩo nĩnaũtethisye; na ngakũsũvĩa, na ũkũnengane wĩthĩwe ũtianĩo wa andũ, wũkĩlye nthĩ ĩno, ũtume matiĩwa motiĩo ala maeketwe:'),
('kam', 'ISA', 49, 9, 'ũkĩtavya ala ove, Umaalai; na ala me kĩvindunĩ, Ĩyonan’yei. Makaĩsĩaa nzĩanĩ, na kĩsesi kyoo kĩkeethĩwa kĩla vandũ vatũlu vathei.'),
('kam', 'ISA', 49, 10, 'Matikew’a nzaa kana waũni; o na ũvyũvu kana syũa itikamakũna: nũndũ ũla ũmew’ĩaa tei akamatongoesya, o na akamatongoesya vakuvĩ na mbuluti sya manzĩ.'),
('kam', 'ISA', 49, 11, 'Na ngatw’ĩkĩthya iĩma syakwa syonthe nzĩa, na malelũ makwa makataĩwa.'),
('kam', 'ISA', 49, 12, 'Sisya, aa makooka kuma kũasa; na, sisya, aa kuma ngalĩ ya ĩũlũ na kuma ũthũĩlonĩ wa syũa; na aa kuma nthĩ ya Sinimu.'),
('kam', 'ISA', 49, 13, 'Inai, inyw’ĩ matu; ĩthĩwa na ũtanu, we nthĩ; ambĩlĩlyai kwina, inyw’ĩ iĩma: nũndũ Yeova nũkiakiĩtye andũ make, na akamew’ĩa tei ala make ala mathĩnaw’a.'),
('kam', 'ISA', 49, 14, 'Ĩndĩ Saioni aisye, Yeova nũndiĩte, na Mwĩaĩi nĩwũlĩtwe ninyie.'),
('kam', 'ISA', 49, 15, 'Mũndũ mũka nũtonya kũlwa nĩ kana kake kala kekwonga, ndakew’ĩe tei mwana wa ĩvu yake? Ĩĩ, nĩmatonya kũlwa, ĩndĩ ndikolwa nue.'),
('kam', 'ISA', 49, 16, 'Sisya, nĩngũvanĩte itaanĩ sya moko makwa; maũvai maku me mbee wakwa mavinda onthe.'),
('kam', 'ISA', 49, 17, 'Syana syaku nikwĩkalaata; akwanangi na ala makũtw’ĩkĩthisye ĩanzo makauma nthĩnĩ waku.'),
('kam', 'ISA', 49, 18, 'Ũngalalya metho maku ngalĩ syonthe, wone: asu onthe nĩmekwĩyũmban’ya vamwe, na kũka vala ũĩ. O ũndũ nĩ thayũ, easya ũu Yeova, ũkamekĩa onthe ta wanake, na kũmevotoa, o ta mũtwawa.'),
('kam', 'ISA', 49, 19, 'Ĩndĩ, ũndũ wa kũndũ kwaku kwĩ maanzo na kũte andũ, na nthĩ yaku ĩla yanangĩtwe, vate ndĩi yu ũkeethĩwa wĩ mũtheke ũteanĩa ala makũtwĩe, na ala makũmelilye makeethĩwa kũasa.'),
('kam', 'ISA', 49, 20, 'Syana sya ũtiwa waku ikaneenea matũnĩ maku atĩĩ, Vandũ vaa nĩ vatheke vaimbĩanĩa; nenga vandũ nĩtũe.'),
('kam', 'ISA', 49, 21, 'Nĩvo ĩndĩ wĩneena ngoonĩ yaku, Nũũ ũla wanzyaĩe aa, nũndũ nĩnakw’ĩĩwe nĩ syana syakwa, na nĩtiĩtwe nĩ nyioka; nĩnĩthamĩtw’e, na nĩ mwangangi kũũ na kũũ? Na nũũ ũla ũeete ii? Sisya, nĩnatiiwe nĩ nyioka; ii, syaĩ na kũ?'),
('kam', 'ISA', 49, 22, 'Ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Sisya, ngookĩlĩlya i mbaĩ kw’oko kwakwa, na ngamaũngamĩsya ngo sya andũ kĩvevelo kyakwa; na makaete ana maku me kĩthũinĩ kyoo, na eĩtu maku makakuwa na ituo syoo.'),
('kam', 'ISA', 49, 23, 'Na asumbĩ makeethĩwa aaĩthe maku ma kũeaa syana, na iveti syoo ainyia maku ma kũeaa syana: makakũkunamĩa mothyũ moo melekele nthĩ, na makanyenya kĩtoo kĩ maũũnĩ maku; na ũkamanya kana minyie Yeova; na ala mambeteelaa maikasonokw’a.'),
('kam', 'ISA', 49, 24, 'Mũtavo ũkaumw’a mokonĩ ma ngũmbaũ, kana ala mataviwe ũndũ waĩle makavonokw’a?'),
('kam', 'ISA', 49, 25, 'Ĩndĩ ũũ nĩw’o Yeova ũnũkwasya, O na ala mataviwe nĩ ngũmbaũ makaumw’a, na mũtavo wa ala ma ũtĩsya ũkatangĩĩwa; nũndũ ngakĩlan’ya vinya na ũla ũkĩlanasya naku, na ngatangĩĩa syana syaku.'),
('kam', 'ISA', 49, 26, 'Na ala makũthĩnasya ngamaathĩsya nyama sya mĩĩ yoo ene; na makatoonwa nĩ nthakame yoo ene, o ta mbinyu yĩ mũyo: na mĩĩ yonthe ĩkamanya kana nyie, Yeova, nĩ Mũtangĩĩi waku, na Mwovosya waku, Ũla Mwene Vinya wa Yakovo.'),
('kam', 'ISA', 50, 1, 'Ũũ nĩw’o Yeova ũnũkwasya, Valũa wa kũtaanĩsya wa mwenyu, ũla namũekie naw’o, ũĩva? Kana nũũ wa ala manandũaa ũla namũthooisye inyw’ĩ kwake? Sisya, nũndũ wa mothũku menyu nĩmwathooiw’e, na nũndũ wa mavĩtyo menyu mwenyu nĩwaekiwe.'),
('kam', 'ISA', 50, 2, 'Nũndũ wa kĩ vatyaĩ mũndũ yĩla nookie? Yĩla neetanie vatyaĩ ũmwe wa kwĩtĩka? Kw’oko kwakwa nĩ kũkuvĩvye o na vanini, ũndũ kũtatonya kwovosya? Kana ndi na vinya wa kũtangĩĩa? Sisya, nĩnĩng’alasya ũkanga kwondũ wa ũkan’yo wakwa, nĩnĩtw’ĩkĩthasya mbũsĩ weũ: makũyũ masyo nĩmanyungaa, ũndũ vati manzĩ, na nĩmakusaa ũndũ wa waũni.'),
('kam', 'ISA', 50, 3, 'Nĩnĩvw’ĩkaa matu na wiũ, na ngĩtw’a kya kwĩvw’ĩka kwamo makunia.'),
('kam', 'ISA', 50, 4, 'Mwĩaĩi Yeova nũnengete ũĩmĩ wa ala mamanyĩĩtw’e, nĩ kana nĩmanye nzĩa ya kũmũtetheesya na ndeto ũla wĩ na mĩnoo: nũamũkasya kĩoko na kĩoko, nũamũkasya kũtũ kwakwa nĩw’e, o ta ala mamanyĩĩtw’e.'),
('kam', 'ISA', 50, 5, 'Mwĩaĩi Yeova nũvingũĩte kũtũ kwakwa, na ndyaaĩthĩwa na ũng’endu, o na ndyaasyoka na ĩtina.'),
('kam', 'ISA', 50, 6, 'Nĩnamon’ya mũongo wakwa ala makũnaa, na matau makwa ala mangunyũasya kĩng’ew’a; ndyaavitha ũthyũ wakwa kũsonokw’a na kũtw’ĩlwa mata.'),
('kam', 'ISA', 50, 7, 'Nũndũ Mwĩaĩi Yeova akandethya; kwondũ wa ũu ndyaathokoana: kwondũ wa ũu nĩnĩlũmĩtye ũthyũ wakwa ta ĩvia yũmũ, na nĩnĩsĩ ndikasonokw’a.'),
('kam', 'ISA', 50, 8, 'Ũla ũndalaa mũlũngalu e vakuvĩ; nũũ ũla wĩtetan’ya nakwa? Tũũngamane: nthũ yakwa nũũ? Ĩnthengeee.'),
('kam', 'ISA', 50, 9, 'Sisya, Mwĩaĩi Yeova akandethya; nũũ ũla wĩndw’a mũvĩtan’ya? Sisya, asu onthe makakũa ta ngũa; lungulu ũkamaya.'),
('kam', 'ISA', 50, 10, 'Nũũ katĩ wenyu ũla ũmũkĩaa Yeova, ũla wĩw’aa wasya wa mũthũkũmi wake? Ũla ũkinyaa kĩvindunĩ na nde na kyeni, naĩkĩĩe syĩtwa ya Yeova na kwĩkwatya Ngai wake.'),
('kam', 'ISA', 50, 11, 'Sisyai, inyw’onthe ala mwakanasya mwaki, ala mwĩvotoaa isinga; kinyai ũmũĩnĩ wa mwaki wenyu, na katĩ wa isinga ila mwakanĩtye. Ũũ nĩw’o mũkethĩwa naw’o kuma kw’okonĩ kwakwa; mũkakoma mwĩ na kĩmako.'),
('kam', 'ISA', 51, 1, 'Mbĩthukĩĩsyai, inyw’ĩ ala mũvikĩlaa ũlũngalu, inyw’ĩ ala mũmanthaa Yeova; sisyai ĩvia vala mwasũviw’e; na ĩima ĩliku vala mwenziwe.'),
('kam', 'ISA', 51, 2, 'Sisyai Avalaamu ĩthe wenyu na Sala ũla wamũsyaie ĩnyw’ĩ; nũndũ yĩla waĩ o ũmwe nĩnamwĩtie, na namũathima, na namũtw’ĩkĩthya aingĩ.'),
('kam', 'ISA', 51, 3, 'Nũndũ Yeova nũkiakiĩtye Saioni; nũkiakiĩtye kũndũ kwayo kw’onthe kwanangĩku, na nũtw’ĩkĩthĩtye weũ wayo ta Eteni, na yalata yayo ta mũũnda wa Yeova; ũtanu na mũyo ũkooneka nthĩnĩ wayo, na kũtũnga mũvea, na wasya mũseo.'),
('kam', 'ISA', 51, 4, 'Mbĩthukĩĩsyai, inyw’ĩ andũ makwa; ngunũĩai matũ, we mbaĩ yakwa: nũndũ mwĩao ũkauma kwakwa, na ngalũmya ũsili wakwa wa katĩ wĩthĩwe kyeni kya ngo sya andũ.'),
('kam', 'ISA', 51, 5, 'Ũlũngalu wakwa wĩ vakuvĩ, ũtangĩĩo wakwa nĩwumaalĩte, na moko makwa makasilĩla ngo sya andũ; ithama ikambeteela, na ikeekwatya kw’oko kwakwa.'),
('kam', 'ISA', 51, 6, 'Ũkĩlyai metho menyu mũsisye matu, na sisyai nthĩ ĩtheo; nũndũ matu makaaa ta syũki, na nthĩ ĩkakũa ta ngũa; na ala mamĩtwĩe makakw’a o ta ũu: ĩndĩ ũtangĩĩo wakwa ũkeethĩwa tene na tene, na ũlũngalu wakwa ndũkathela.'),
('kam', 'ISA', 51, 7, 'Mbĩthukĩĩsyai, inyw’ĩ ala mwĩsĩ ũlũngalu, andũ ala mwĩao wakwa wĩ ngoonĩ syenyu; mũtikakĩe kĩvũthya kya andũ, o na mũikateve ũndũ wa kũumana kwoo.'),
('kam', 'ISA', 51, 8, 'Nũndũ lungulu ũkamaya ta ngũa, na kĩinyu kĩkamaya ta w’ĩa wa ĩlondu; ĩndĩ ũlũngalu wakwa ũkeethĩwa tene na tene, na ũtangĩĩo wakwa kũvika nzyawa syonthe.'),
('kam', 'ISA', 51, 9, 'Amũka, amũka, ĩkĩa vinya, we kw’oko kwa Yeova, amũka, o ta mĩthenya ya tene, nzyawa sya tene tene. Tuue ũla watilangile Laavi ilungu, na ũla watonyie mũkũnga?'),
('kam', 'ISA', 51, 10, 'Tuue ũla wang’alilye ũkanga, manzĩ ma syũngũ nene; na ũla watw’ĩkĩthisye moliku ma ũkanga nzĩa ya ala moovoiw’e maingĩle?'),
('kam', 'ISA', 51, 11, 'Na ala ovosye ma Yeova makasyoka, na kuka Saioni makina; na ũtanu ũtathelaa ũkeethĩwa mĩtwenĩ yoo: makeethĩwa na mũyo na ũtanu; na kũmaka na kũvevũũka kũkakĩa.'),
('kam', 'ISA', 51, 12, 'Nyie, o nyie; ninyie ũla ũkũkiakiasya; nue ũũ, ũndũ ũkĩaa mũndũ ũla ũkakw’a, na mwana wa mũndũ ũla ũkatw’ĩkĩthw’a ta nyeki;'),
('kam', 'ISA', 51, 13, 'na nĩwũlĩtwe nĩ Yeova Mũmbi waku, ũla watambũũkisye matu, na wambĩlĩlye myambĩlĩlyo ya nthĩ; na nũkĩaa mũthenya w’onthe mavinda onthe nũndũ wa ũthatu mwai wa mũthĩn’ya, yĩla wĩyũmbanasyai anange? Na ũthatu mwai wa mũthĩn’ya ũĩva?'),
('kam', 'ISA', 51, 14, 'Mũndũ ũla ũtavĩtwe akalũngw’a kwake akathaw’a mĩtũkĩ; na ndakakw’a na kũtheea yĩla ĩimanĩ, o na lĩu wake ndũkanyiva.'),
('kam', 'ISA', 51, 15, 'Nũndũ ninyie Yeova Ngai waku, ũla wũkĩlangasya ũkanga, ũkethĩa itulumo syaw’o nĩlitũkaa: Yeova wa nguthu nĩyo syĩtwa yake.'),
('kam', 'ISA', 51, 16, 'Na nĩnĩkĩĩte ndeto syakwa kanyw’anĩ waku, na nĩnĩkũvw’ĩkĩte muunyĩnĩ wa kw’oko kwakwa, nĩ kana nĩlũmye matu, na kwambĩlĩlya myambĩlĩlyo ya nthĩ, na kũtavya Saioni, Nue andũ makwa.'),
('kam', 'ISA', 51, 17, 'Amũka, amũka, ũngama, we Yelusaleme, ũla ũnyw’ĩte kw’okonĩ kwa Yeova kĩkombe kya kũthilĩka kwake; we nũnyw’ĩte kĩkombe kĩnene kya kũlũsya, na ũkakĩmina.'),
('kam', 'ISA', 51, 18, 'Vati ũmwe katĩ wa ana make onthe ala wasyaie wa kũmũtongoesya; o na vati ũla ũmũkwataa kw’oko katĩ wa ana onthe ala waeie.'),
('kam', 'ISA', 51, 19, 'Maũndũ aa elĩ nĩmekĩkĩte kwaku; nũũ ũla wĩkũmetea? Wanango na wanangĩko, na yũa na ũvyũ; ngakũkiakisya ata?'),
('kam', 'ISA', 51, 20, 'Ana maku nĩmanyalile, nĩmakomete wambĩlĩlyonĩ wa nzĩa syonthe, ta ngondi kĩteinĩ; nĩmausũĩtw’e kũthilĩka kwa Yeova, ũkan’yo wa Ngai waku.'),
('kam', 'ISA', 51, 21, 'Kwondũ wa ũu yu ĩw’a ũũ, we ũla ũthĩnĩtw’e, na ũla ũmilĩtwe, ĩndĩ ti ũndũ wa mbinyu:'),
('kam', 'ISA', 51, 22, 'Mwĩaĩi waku Yeova na Ngai waku, ũla ũteteaa ũvoo wa andũ make, easya atĩĩ, Sisya, nĩnĩkyumĩtye kw’okonĩ kwaku kĩla kĩkombe kya kũlũsya, o kĩkombe kĩnene kya kũthilĩka kwakwa; ndũkakĩnyw’a ĩngĩ:'),
('kam', 'ISA', 51, 23, 'na ngakĩkĩa mokonĩ ma ala makũthĩnasya, ala matavĩtye thayũ waku, Kunama, nĩ kana tũvĩte; naku nĩwiĩte mũongo waku wĩthĩwe ta nthĩ, na wĩthĩwe ta nzĩa nene kwa ala mavĩtĩlaa vo.'),
('kam', 'ISA', 52, 1, 'Amũka, amũka, ĩkĩa vinya waku, we Saioni; ĩkĩa ngũa syaku nzeo, we Yelusaleme, ndũa ntheu; nũndũ kuma yu ala mate aĩke na ala mate atheu matikalika nthĩnĩ waku.'),
('kam', 'ISA', 52, 2, 'Ĩvangũle kĩtoo; ũkĩla nokĩkala kĩvĩlanĩ kyaku kya ũsumbĩ, we Yelusaleme: ĩthasye syĩndũ ila wovetwe nasyo ngingonĩ yaku, we, mwĩĩtu mũtave wa Saioni.'),
('kam', 'ISA', 52, 3, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Nĩmwathooiw’e mana; na mũkoovow’a vate mbesa.'),
('kam', 'ISA', 52, 4, 'Nũndũ ũũ nĩw’o Mwĩaĩi Yeova ũnũkwasya, Mbee andũ makwa nĩmatheeie Misili mekale ũeni kw’o: na Mũasuli nũmathĩnĩtye vate kĩtumi.'),
('kam', 'ISA', 52, 5, 'Kwondũ wa ũu yu, nĩĩka ata vaa, easya ũu Yeova, nũndũ andũ makwa matwaĩtwe mana? Ala mamasumbĩkaa maneenaa na wasya mũnene, easya ũu Yeova, na syĩtwa yakwa nĩyĩumangawa mũthenya mũima ĩndĩ yonthe.'),
('kam', 'ISA', 52, 6, 'Kwondũ wa ũu andũ makwa makamanya syĩtwa yakwa: kwondũ wa ũu mũthenya ũsu makamanya kana ninyie ũla ũneenaa; sisya, ninyie.'),
('kam', 'ISA', 52, 7, 'Ko nĩ maseo iĩmanĩ maũũ ma ũla ũetae ũvoo mũseo, ũla ũnyaĩĩkasya ũvoo wa mũuo, ũla ũetae ũvoo mũseo wa maũndũ maseo, ũla ũtavanasya ũtangĩĩo, ũla ũtavasya Saioni, Ngai waku nũsumbĩkaa!'),
('kam', 'ISA', 52, 8, 'Wasya wa asyaĩĩsya maku! Nĩmokĩlasya wasya, nĩmainaa vamwe; nũndũ makoonana itho kwa itho, yĩla Yeova wĩsyoka Saioni.'),
('kam', 'ISA', 52, 9, 'Ambĩlĩlyai kũtana, inai vamwe, inyw’ĩ kũndũ kwanangĩku kwa Yelusaleme; nũndũ Yeova nũkiakiĩtye andũ make, nĩwovoetye Yelusaleme.'),
('kam', 'ISA', 52, 10, 'Yeova nũvuĩte kw’oko kwake kũtheu mbaĩ syonthe syene; na itulu syonthe sya nthĩ nĩsyonete ũtangĩĩo wa Ngai waitũ.'),
('kam', 'ISA', 52, 11, 'Endai, endai, umai ku, mũikakiite kĩndũ kĩvuku; umai katĩ wayo; ĩthesyei, inyw’ĩ ala mũkuaa mĩio ya Yeova.'),
('kam', 'ISA', 52, 12, 'Nũndũ mũtikauma mwĩkalaatĩte, o na mũtikaenda mũkĩĩte: nũndũ Yeova akaenda mbee wenyu; na Ngai wa Isilaeli akeethĩwa ĩtina wenyu.'),
('kam', 'ISA', 52, 13, 'Sisya, mũthũkũmi wakwa akeeka na ũĩ, akanenevw’a na kũkĩlw’a, na akeethĩwa e ĩũlũ mũno.'),
('kam', 'ISA', 52, 14, 'O tondũ aingĩ maseng’ie ũndũ waku (ũthyũ wake nĩwanangiwe kũvĩtũka mũndũ o na wĩva, na mũvw’ano wake kũvĩtũka ana ma andũ),'),
('kam', 'ISA', 52, 15, 'o ta ũu akaminzangĩsya mbaĩ nyingĩ; asumbĩ makatumya makanyw’a moo ũndũ wake: nĩkwĩthĩwa ũndũ ũla mataatavw’a makoona; na ũla mataaĩw’a makamanya.'),
('kam', 'ISA', 53, 1, 'Nũũ ũla wetĩkĩlile ũvoo ũsu twaetie? Na kw’oko kwa Yeova kwavuanĩw’e ũũ?'),
('kam', 'ISA', 53, 2, 'Nũndũ nĩweanie mbee wake o ta mũtĩ mwololo, na ta mũĩ, ũla ũthongooeaa nthĩ nyũmũ: nde na mũvw’ano kana ũseo wa mwĩĩ; na yĩla tũũmwona, vati ũseo wa wũmbe o na wĩva ũtuma tũmwenda.'),
('kam', 'ISA', 53, 3, 'Nĩwavũthiw’e, na kũlewa nĩ andũ; aĩ mũndũ wa mawoo, na mũmanyi wa thĩna: na nĩwavũthiw’e ta ũmwe ũla andũ mamũvithaa mothyũ moo; naitũ tũtyaamũtw’a ta kĩndũ.'),
('kam', 'ISA', 53, 4, 'Nĩ w’o, we nĩwakuie mathĩna maitũ, na eeyaĩkya mawoo maitũ; na ũu w’onthe ithyĩ twamwona kwĩthĩwa nĩ mũkũne, kũkũnwa nĩ Ngai, na kũthĩnw’a.'),
('kam', 'ISA', 53, 5, 'Ĩndĩ nĩwatonyiwe kwondũ wa mavĩtyo maitũ, auauĩkw’a kwondũ wa mothũku maitũ; ũsilĩlo ũndũ wa mũuo witũ waĩ ĩũlũ wake; naitũ nĩtũvoetw’e kwondũ wa makũnwa make.'),
('kam', 'ISA', 53, 6, 'Ithyonthe ta malondu nĩtwaaĩte; nĩtweethyũũie kĩla ũmwe na kũatĩĩa nzĩa yake mwene; nake Yeova amwaĩkisye ũthũku witũ ithyonthe.'),
('kam', 'ISA', 53, 7, 'We nĩwathĩniw’e, ĩndĩ akĩthĩnw’a ndaathamya kanyw’a wake; o ta katena ka ĩlondu katongoew’e kũthi kũthĩnzwa, na ta ĩlondu yĩ mbee wa ala mayĩtilaa maw’ĩa yĩvindĩtye, o ta ũu we ndaathamya kanyw’a wake.'),
('kam', 'ISA', 53, 8, 'Nĩwaumiw’e kwondũ wa kũng’endewa na kũsilĩlwa; na nzyawanĩ yake, nũũ ũla wamũtalĩthisye kana nĩwavetiwe aume nthĩ ya ala me thayũ kwondũ wa ĩvĩtyo ya andũ makwa ala maĩ ma ũsilĩlwa?'),
('kam', 'ISA', 53, 9, 'Na nĩmamũseũvĩsye mbũa vamwe na ala athũku, o na vamwe na ũla mũthwii kĩkw’ũnĩ kyake; o na kau we ndaaĩka ũng’endu, o na vatyaĩ ũkengani kanyw’anĩ wake nongi.'),
('kam', 'ISA', 53, 10, 'Na ũu w’onthe Yeova nĩwendeew’e nĩ kũmũuauĩkya; nĩwamũthĩnisye: o yĩla wĩtw’ĩkĩthya thayũ wake wĩthĩwe nthembo kwondũ wa naĩ, akoona ũsyao wake, akongeleela matukũ make, na ũndũ ũla wendeeasya Yeova ũkaathimĩka kw’okonĩ kwake.'),
('kam', 'ISA', 53, 11, 'Akoona thĩna wa ngoo yake, nake akeanĩwa: kwondũ wa ũmanyi wake mwene ũsu mũthũkũmi wakwa mũlũngalu akatw’ĩkĩthya aingĩ methĩwe alũngalu; na akakua mothũku moo.'),
('kam', 'ISA', 53, 12, 'Kwondũ wa ũu ngamũaĩa kĩanda vamwe na ala anene, nake akaaana mũtavo vamwe na ala me na vinya; nĩkwĩthĩwa nĩwetĩkisye thayũ wake kũvika akw’a, nake nĩwatalanĩlw’e na avĩtan’ya: ĩndĩ nĩwakuie naĩ sya aingĩ, na amavoyea avĩtan’ya.'),
('kam', 'ISA', 54, 1, 'Ina, we ngũngũ, we ũla ũtaasyaa; ambĩlĩlya kwina, noiũkĩlya wasya mũnene, we ũla ũtaaũnya: nũndũ syana sya ũla ũtwĩe e weka nĩ mbingĩ kũte syana sya mũndũ mũka mũtwae, easya ũu Yeova.'),
('kam', 'ISA', 54, 2, 'Nenevya vandũ va ĩeema yaku, na matambũũkye motũtũ ma ngũa ma mawĩkalo maku; ndũkaeke: asavya makanda maku, noiĩkĩa vinya syambo syaku.'),
('kam', 'ISA', 54, 3, 'Nũndũ ũkanyaĩĩka ngalĩ ya kw’oko kwa aũme na kw’oko kwa aka; na ũsyao waku ũkoosa mbaĩ syĩthĩwe syaw’o, na kũtuma ndũa syĩ maanzo itũwa.'),
('kam', 'ISA', 54, 4, 'Ndũkakĩe; nũndũ ndũkasonoka: o na ndũkathokoanw’e; nũndũ ndũkasonokw’a: nũndũ ũkoolwa nĩ nthoni sya wana waku; na kũvũthw’a nũndũ wĩ ndiwa ndũkakũlilikana ĩngĩ.'),
('kam', 'ISA', 54, 5, 'Nũndũ Mũmbi waku nĩwe mũemeu; Yeova wa nguthu nĩyo syĩtwa yake: na Ũla Mũtheu wa Isilaeli nĩ Mwovosya waku; akeetwa Ngai wa nthĩ yonthe.'),
('kam', 'ISA', 54, 6, 'Nũndũ Yeova nũkwĩtĩte ta kĩveti kĩeketwe na kwĩw’ĩthw’a woo vevanĩ, o kĩveti kya mũika, yĩla kĩeketwe, easya ũu Ngai waku.'),
('kam', 'ISA', 54, 7, 'Nĩnĩkũtiĩte kavinda kanini mũno; ĩndĩ ngakũmban’ya na matei maingĩ.'),
('kam', 'ISA', 54, 8, 'Yĩla kũthilĩka kwausũie nĩnakũvithie ũthyũ wakwa kavinda kanini; ĩndĩ ngakwĩw’ĩa tei nĩ na ũseo wĩ wendo ũtathelaa, easya ũu Yeova, Mwovosya waku.'),
('kam', 'ISA', 54, 9, 'Nũndũ ũu ũilyĩ kwakwa ta ala manzĩ ma Noa; o tondũ neevĩtie atĩ manzĩ ma Noa matikavw’ĩka nthĩ ĩngĩ, o ta ũu nĩnĩvĩtĩte ndikakũthilĩkĩla, o na ndikakũkan’ya.'),
('kam', 'ISA', 54, 10, 'Nũndũ iĩma nitonya kũthi, na tũlĩma tũtonya kũthamw’a; ĩndĩ ũseo wakwa wĩ wendo ndũkakũtia, o na ũtianĩo wakwa wa mũuo ndũkavetwa, easya ũu Yeova ũla ũkwĩw’ĩaa tei.'),
('kam', 'ISA', 54, 11, 'We ũla ũthĩnaw’a, wĩkangaw’a nĩ kĩuutani, na ũtakiakiaw’a, sisya, ngalũmanĩthya tũvila twaku iĩndĩnĩ syatw’o na langi mũseo, na ngakwatya myambĩlĩlyo yaku na tũvila twa savili.'),
('kam', 'ISA', 54, 12, 'Na ngaseũvya mĩthya yaku na tũvila twa maliani, na mbingĩlo syaku na alimasi ndune, na mũvaka waku w’onthe na tũvila twa thooa mũnene.'),
('kam', 'ISA', 54, 13, 'Na syana syaku syonthe ikamanyĩw’a nĩ Yeova; na mũuo wa syana syaku ũkeethĩwa mwingĩ.'),
('kam', 'ISA', 54, 14, 'We ũkalũlũmĩlw’a ũlũngalunĩ: ũkeethĩwa kũasa na kũthĩnw’a, nũndũ ndũkakĩa; na kũasa na kũtĩsw’a, nũndũ kũtikakũthengeea.'),
('kam', 'ISA', 54, 15, 'Sisya, matonya kũmbana, ĩndĩ ti kwondũ wakwa: o ũla ũkakũmbanĩa akavalũka nũndũ waku.'),
('kam', 'ISA', 54, 16, 'Sisya, nĩnũmbĩte mũtwii ũla ũvuvaa mwaki wa makaa, na aiumya mũio wa wĩa wake; na nĩnũmbĩte mwanangi wa kwananga.'),
('kam', 'ISA', 54, 17, 'Mũio o na wĩva ũla ũseũvĩtw’e ũkũkite ndũkaĩla; na kĩla ũĩmĩ ũla ũkakũkĩlĩla ũkũsilĩle ũkoosilĩla. Ũũ nĩw’o ũtiĩwa wa athũkũmi ma Yeova, na ũlũngalu woo ũla wumaa kwakwa, easya ũu Yeova.'),
('kam', 'ISA', 55, 1, 'Inyw’ĩ, kĩla mũndũ wĩ na waũni, ũkai vala ve manzĩ, o na ũla ũte na mbesa; ũkai inyw’ĩ, thooa, mũye; ĩĩ, ũkai, mũthooe mbinyu na ĩia vate mbesa na vate kũĩvĩa.'),
('kam', 'ISA', 55, 2, 'Nũndũ wa kĩ mwanangaa mbesa na kĩla nakyo ti lĩu? Na kũtethya wĩa ũndũ wa kĩla kĩtavũnĩthasya? Mbĩthukĩĩsyai na kĩthing’ĩĩsyo, mũye kĩla kĩseo, na thayũ wenyu ũtanĩe ũnou.'),
('kam', 'ISA', 55, 3, 'Teai matũ, na mũimbũkĩa; ĩthukĩĩsyei, na ngoo syenyu ikeethĩwa thayũ: na ngatianĩa ũtianĩo nenyu wa tene na tene, o matei malũmu ma Ndaviti.'),
('kam', 'ISA', 55, 4, 'Sisya, nĩnĩmũnenganĩte ethĩwe ngũsĩ kwa ngo sya andũ, mũtongoi na mwĩaĩi wa ngo sya andũ.'),
('kam', 'ISA', 55, 5, 'Sisya, ũkeeta mbaĩ ĩla ũtamĩsĩ; na mbaĩ ĩtaakũmanya ĩkasemba vala ũĩ, nũndũ wa Yeova Ngai waku, na nũndũ wa Ũla Mũtheu wa Isilaeli; nũndũ nũkũtaĩĩthĩtye.'),
('kam', 'ISA', 55, 6, 'Manthai Yeova o yĩla ũtonya kwoneka; mwĩkaĩlei yĩla wĩ vakuvĩ:'),
('kam', 'ISA', 55, 7, 'ũla mũthũku natie mũendele wake, na mũndũ ũte mũlũngalu mosũanĩo make; na namũsyokee Yeova, na akamwĩw’ĩa tei; na Ngai waitũ, nũndũ akamũekea vyũ.'),
('kam', 'ISA', 55, 8, 'Nũndũ mosũanĩo makwa ti mosũanĩo menyu, o na nzĩa syenyu ti nzĩa syakwa, easya ũu Yeova.'),
('kam', 'ISA', 55, 9, 'O tondũ matu me ĩũlũ kwĩ nthĩ o ta ũu nzĩa syakwa syĩ ĩũlũ kwĩ nzĩa syenyu, na mosũanĩo makwa kwĩ mosũanĩo menyu.'),
('kam', 'ISA', 55, 10, 'O tondũ mbua yuaa na ĩa kuma ĩtunĩ, nasyo itisyokaa kw’o, ĩndĩ ninyithasya nthĩ, na nitumaa ĩmesya na kũthongoosya, na nĩmũnengae mbeũ ũla ũvuĩaa na lĩu ũla ũĩsaa;'),
('kam', 'ISA', 55, 11, 'ndeto yakwa ĩkeethĩwa ĩilyĩ o ta ũu ĩla yumaa kanyw’anĩ wakwa: ndĩkanzyokea mana, ĩndĩ ĩkeanĩsya ũndũ nendete, nayo ĩkaaĩla ũndũnĩ ũla namĩtũmĩe.'),
('kam', 'ISA', 55, 12, 'Nũndũ mũkaumaala na ũtanu, na mũkatongoew’a na mũuo: iĩma na tũlĩma ikambĩlĩlya kwina syĩ mbee wenyu; na mĩtĩ yonthe ya kĩsesinĩ ĩkakũnangan’ya mbĩ syayo.'),
('kam', 'ISA', 55, 13, 'Vandũ va mĩw’a kũkamea mũtĩ wa mũsonovali; na vandũ va mũtae wa kĩthekanĩ kũkamea mũtĩ wa mwandasi: na ũu ũkeethĩwa syĩtwa kwa Yeova, wonan’yo wa tene na tene ũla ũtakavetwa.'),
('kam', 'ISA', 56, 1, 'Ũũ nĩw’o Yeova ũnũkwasya, Lũmyai sĩla wa katĩ, na kwĩka ũlũngalu; nũndũ ũtangĩĩo wakwa ũkilyĩ kũka, na ũlũngalu wakwa kwonanw’a.'),
('kam', 'ISA', 56, 2, 'Nĩ mũathime mũndũ ũla wĩkaa ũu, na mwana wa mũndũ ũla ũlũmanasya naw’o; ũla ũlilikanaa mũthenya wa savato ndakovukye, na ũla ũsiĩĩa kw’oko kwake kũtikeke ũthũku o na wĩva.'),
('kam', 'ISA', 56, 3, 'O na mũndũ wa nthĩ ĩngĩ, ũla ũlũmanĩtye na Yeova ndakaneene, akyasya, Nĩ w’o Yeova akambathan’ya na andũ make; o na mũvakũe ndakasye, Sisya, nyie nĩ mũtĩ mũmũ.'),
('kam', 'ISA', 56, 4, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya ũndũ wa avakũe ala malilikanaa masavato makwa, na manyuvaa maũndũ ala mambendeesyaa, na kũlũman’ya na ũtianĩo wakwa:'),
('kam', 'ISA', 56, 5, 'Nyũmbanĩ yakwa na maũvainĩ makwa ngamanenga ũlilikan’yo na syĩtwa ĩseo kwĩ ya ana na eĩtu; ngamanenga syĩtwa ya tene na tene, yĩla yĩtakavetwa.'),
('kam', 'ISA', 56, 6, 'O na andũ ma nthĩ ĩngĩ ala melũman’ya na Yeova, mamũthũkũme, na kwenda syĩtwa ya Yeova, methĩwe athũkũmi make, kĩla ũmwe ũla ũlilikanaa savato ndakovukye, na kũlũman’ya na ũtianĩo wakwa;'),
('kam', 'ISA', 56, 7, 'o asu ngamaete kĩĩmanĩ kyakwa kĩtheu, na kũmatanĩthĩsya nyũmbanĩ yakwa ya kũvoyea: nthembo syoo sya kũvĩvw’a na nthembo syoo sya kũtonywa ikeetĩkĩlwa kĩthembeonĩ kyakwa; nũndũ nyũmba yakwa ĩkeetwa nyũmba ya kũvoyea kwondũ wa andũ onthe.'),
('kam', 'ISA', 56, 8, 'Mwĩaĩi Yeova, ũla ũmbanasya alũngw’a ma Isilaeli, easya, Ngamũmbanĩsya angĩ, eka ala make ala mombanĩtw’e.'),
('kam', 'ISA', 56, 9, 'Inyw’ĩ nyamũ syonthe sya kĩthekanĩ, ũkai mũye, ĩĩ, inyw’ĩ nyamũ syonthe sya mũtitũnĩ.'),
('kam', 'ISA', 56, 10, 'Asyaĩĩsya make nĩ ililinda, onthe mati na ũĩ; onthe nĩ ngitĩ, matitonya kũkũma; makĩota, makĩkoma, makyenda kwombosya.'),
('kam', 'ISA', 56, 11, 'Ĩĩ, ngitĩ nĩ ndoonu, ititonya kũvũna nongi; na aa nĩ aĩthi matatonya kũmanya; onthe nĩmethyũũĩe nzĩa syoo ene, kĩla ũmwe ũtandĩthyonĩ wake, kuma kĩla ngalĩko.'),
('kam', 'ISA', 56, 12, 'Measya, Ũkai inyw’i, ngaete mbinyu, na tũkeeyusũsya na kĩla kĩtoonasya; na ũnĩ ũkeethĩwa ta ũmũnthĩ, mũthenya mũnene ũtathimĩka.'),
('kam', 'ISA', 57, 1, 'Ũla mũlũngalu nũkwaa, na vati ũwiaa ũndũ ũsu ngoonĩ; na andũ me tei nĩmeũvetwa, vati ũmwe ũsũanĩaa kana mũlũngalu nũkũvetwe aume ũthũkunĩ ũla wũkĩte.'),
('kam', 'ISA', 57, 2, 'Nake nũlikaa mũuonĩ nĩmathũmũaa mokomonĩ moo, kĩla ũmwe ũla ũendaa ũlũngalunĩ wake.'),
('kam', 'ISA', 57, 3, 'Ĩndĩ thengeeai vaa, inyw’ĩ ana ma kĩveti kĩoi, ũsyao wa kĩlaalai na ĩlwaya.'),
('kam', 'ISA', 57, 4, 'Mwĩthaũkĩa ũũ? Na nũũ mũkwathamangĩsya makanyw’a, na kumĩlangĩlya nĩmĩ? Mũti syana sya ũvĩtyo, ũsyao wa ũvũngũ,'),
('kam', 'ISA', 57, 5, 'inyw’ĩ ala mũkwĩyakan’ya ene katĩ wa mĩtĩ ya myaloni, ĩtina wa kĩla mũtĩ mwĩũ; ala mũaĩaa syana myandanĩ, ungu wa mĩvatĩ ya mavia?'),
('kam', 'ISA', 57, 6, 'Kĩanda kyaku kĩ katĩ wa mavia matendeu me mwandanĩ; asu, nĩmo kĩanda kyaku; o asu nĩwametĩe nthembo ya kũnyuwa, nũthembete nthembo ya mũtu. Ngavoovw’a nĩ syĩndũ isu?'),
('kam', 'ISA', 57, 7, 'Nĩwiĩte ũkomo waku kĩĩmanĩ kĩtũlu na kĩnene; o na vau nĩvo wambatie kũthemba.'),
('kam', 'ISA', 57, 8, 'Na mbĩlĩlo wa mĩomo na ituĩ nũngamĩtye ũlilikan’yo waku: nĩwĩvuĩe ũngĩ na ti nyie, na nĩwambatĩte; nũnenevetye ũkomo waku, na kũtianĩa ũtianĩo nao: nĩwendie ũkomo woo vala wawonie.'),
('kam', 'ISA', 57, 9, 'Na niwaendie na mauta kwa mũsumbĩ, na waingĩvisye syĩndũ syaku ila inyungaa nesa, na watũma atũmwa maku kũasa, na weethũkya o na kũvika Seoli.'),
('kam', 'ISA', 57, 10, 'Waĩ ũnanow’a nĩ ũasa wa nzĩa yaku; ĩndĩ ndwaaasya, Nĩ mana: nĩwoonie vinya waku ũkyongelela: kwondũ wa ũu ndwaanyala.'),
('kam', 'ISA', 57, 11, 'Naku ũkĩĩte ũũ na kũkwatwa nĩ w’ĩa, kana ũneene ũvũngũ, na ndwaandilikana, kana kwia ũndũ ũsu ngoonĩ yaku? Ndyaavindya ĩvinda ĩasa, naku ndũngĩa?'),
('kam', 'ISA', 57, 12, 'Ngatavan’ya ũlũngalu waku; na ũndũ wa mawĩa maku, matikakũuna.'),
('kam', 'ISA', 57, 13, 'Yĩla wĩĩa, ala woombanisye nĩmakũtangĩĩe; ĩndĩ kĩseve kĩkamatwaa, mĩthũmũ ĩkamatwaa onthe: ĩndĩ ũla wĩĩvitha nthĩnĩ wakwa akamĩmesya ĩ nthĩ, na akatiĩwa kĩĩma kyakwa kĩtheu.'),
('kam', 'ISA', 57, 14, 'Na akasya, Ĩnzai, ĩnzai, seũvyai nzĩa, vetai ũlulutĩkyo nzĩanĩ ya andũ makwa.'),
('kam', 'ISA', 57, 15, 'Nũndũ Ũla wĩ ĩũlũ na wa ũtaĩwa mũno, ũla wĩkalaa tene na tene, ũla syĩtwa yake nĩ Mũtheu, easya atĩĩ: Nĩkalaa vandũ vatũlu na vatheu, vamwe na ũla wĩ na veva wa kwĩlila na kwĩnyivya, nĩvuũkye veva wa ũla wĩ na wĩnyivyo, na kũvuũkya ngoo ya ũla ũnũkwĩlila.'),
('kam', 'ISA', 57, 16, 'Nũndũ ndikakĩlan’ya vinya tene na tene, o na ndikethĩwa na kũthilĩka mavinda onthe; nũndũ ũ veva ũkeethĩwa ũiteva mbee wakwa, na syuu ila noombie.'),
('kam', 'ISA', 57, 17, 'Nĩnathilĩkile nũndũ wa ũthũku wa ĩtomo yake, na namũkũna; nĩnavithie ũthyũ wakwa na nathilĩka; nake aendeea kwathũka akĩatĩĩa mũendele wa ngoo yake.'),
('kam', 'ISA', 57, 18, 'Nĩnonete nzĩa syake na ngamũvosya; o na ngamũtongoeasya, na ngamũtũngĩanĩsya maũndũ ala mamwaĩle vamwe na ala mamũmeteaa.'),
('kam', 'ISA', 57, 19, 'Nyie nũmbaa ũsyao wa ilomo: Mũuo, mũuo, kwa ũla wĩ kũasa na kwa ũla wĩ vakuvĩ, easya ũu Yeova; na ngamũvosya.'),
('kam', 'ISA', 57, 20, 'Ĩndĩ ala athũku mailyĩ ta ũkanga ũkyũkĩlangw’a; nũndũ ndũtonya kũthũmũa, na manzĩ maw’o mekangasya ndaka na mũluũ.'),
('kam', 'ISA', 57, 21, 'Vati mũuo kwa ala athũku, easya ũu Ngai wakwa.'),
('kam', 'ISA', 58, 1, 'Neena na wasya mũnene, ndũkaeke, ũkĩlya wasya waku ta soo, noitavya andũ makwa ĩvĩtyo yoo, na nyũmba ya Yakovo naĩ syayo.'),
('kam', 'ISA', 58, 2, 'Ĩndĩ nĩmamanthaa nyie kĩla mũthenya, na nĩmendeeaw’a nĩ kũmanya nzĩa syakwa: nĩmangũlasya mosilĩlo malũngalu, ta mbaĩ ĩla yekaa ũlũngalu, na ĩtaatia ũtw’ĩo wa Ngai wayo; nĩmatanĩaa kũmũthengeea Ngai.'),
('kam', 'ISA', 58, 3, 'Nĩmeũkũlya, Tũtĩĩaa kũya nĩkĩ, naku ndwonaa? Tũthĩnĩasya thayũ witũ kĩ, naku ndũũsisya? Sisyai, mũthenya wa kũtĩĩa ũya kwenyu nĩmũkwĩtanĩthya inyw’ĩ ene, na athũkũmi menyu onthe nĩmũmaingĩĩasya wĩa.'),
('kam', 'ISA', 58, 4, 'Sisyai, nĩmũtĩĩaa ũya na mũikananĩa na kũtetan’ya, na kũkũnangana ngundi sya ũthũku: mũtikũtĩĩa ũya ũmũnthĩ nĩ kana wasya wenyu wĩw’ĩke ĩũlũ.'),
('kam', 'ISA', 58, 5, 'Ku nĩkw’o kũtĩĩa ũya kũla nĩnyuvĩte? Mũthenya wa mũndũ kũthĩn’ya ngoo yake? Nĩ kũkunamya mũtwe wake ta malula, na kwalan’ya makunia na mũu ungu wake? Ũkeeta ku kũtĩĩa ũya, na mũthenya wĩtĩkĩlawa nĩ Yeova?'),
('kam', 'ISA', 58, 6, 'Kũtĩĩa ũya kũla nĩnyuvĩte ti kũũ: kũthasya syĩndũ sya kwovwa nasyo sya ũthũku, na kũthasya mĩkwa ya ĩsoki, na kũthasya ala mathĩnaw’a maende, na kũtũla kĩla ĩsoki?'),
('kam', 'ISA', 58, 7, 'Tĩ kũmanenga lĩu waku ala me na nzaa, na kũete nyũmbanĩ yaku ngya ila ilũngĩtw’e? Na yĩla wĩona ũla mũthei, ũmũvw’ĩke; na kũlea kwĩvitha ala ma nyũmba yaku?'),
('kam', 'ISA', 58, 8, 'Nĩvo ĩndĩ kyeni kyaku kĩkakenaa ta kĩoko, na kũvow’a kwaku kũkaumĩla mĩtũkĩ; na ũlũngalu waku ũkaendaa mbee waku; ndaĩa ya Yeova ĩkakũatĩĩaa ĩtina waku.'),
('kam', 'ISA', 58, 9, 'Nĩvo ĩndĩ wĩĩtana, na Yeova akĩtĩka; ũkamwĩkaĩla, nake akasya, Ninyioo. Ethĩwa ũkaveta katĩ waku ĩsoki, na kwolota na kyaa, na kũneena ũthũku;'),
('kam', 'ISA', 58, 10, 'na ethĩwa ũkaumya ngoo yaku ũmwĩw’ĩe tei ũla wĩ na nzaa, na kũvũn’ya ũla ũthĩnaw’a: nĩvo ĩndĩ kyeni kyaku kĩũkĩla kĩvindunĩ, na kĩvindu kyaku kĩkĩthĩwa ta mũthenya katĩ;'),
('kam', 'ISA', 58, 11, 'na Yeova akakũtongoeasya ĩndĩ yonthe, na akavũnĩsya thayũ waku kũndũ kũmũ, na kwĩkĩa mavĩndĩ maku vinya; na ũkeethĩwa ta mũũnda mũnyithye, na ta mbuluti ya manzĩ, ĩla manzĩ mayo matinyivaa o na indĩĩ.'),
('kam', 'ISA', 58, 12, 'Na ala makethĩwa kwaku makaaka kũndũ kwanangĩkie tene; ũkookĩlya myambĩlĩlyo ya nzyawa nyingĩ; naku ũkeetwa Mũseũvya wa vala vavũthũiwe, Mũtũngĩĩi wa nzĩa sya kwĩkalawa.'),
('kam', 'ISA', 58, 13, 'Ethĩwa ũkatũnga kũũ kwaku kũeke mũthenya wa savato, ũte kwĩka kwenda kwaku mũthenya wakwa mũtheu; na ĩndĩ ũkeeta savato wa kũtanĩthya, na mũthenya mũtheu wa Yeova wa kũtaĩwa; na ũkootaĩa, ũkĩlea nzĩa syaku, kana kũmantha ũtanu waku mwene, kana kũneena ndeto syaku mwene:'),
('kam', 'ISA', 58, 14, 'nĩvo ĩndĩ wĩĩtanĩthya nthĩnĩ wa Yeova; na ngakwambatya kũndũ kũtũlu kwa nthĩ; na ngakũĩthya na ũtiĩwa wa ĩthe waku Yakovo: nũndũ kanyw’a wa Yeova nũneenete ũu.'),
('kam', 'ISA', 59, 1, 'Sisya, kw’oko kwa Yeova ti kũkuvĩvye, ũndũ kũtatonya kũtangĩĩa; o na kũtũ kwake ti kũito, ũndũ kũtatonya kwĩw’a:'),
('kam', 'ISA', 59, 2, 'ĩndĩ mothũku menyu nĩmamũtaanĩtye inyw’ĩ na Ngai wenyu, na naĩ syenyu nivithĩte ũthyũ wake kwenyu, ũndũ ũtew’a.'),
('kam', 'ISA', 59, 3, 'Nũndũ moko menyu nĩmavukĩtw’e nĩ nthakame, na syaa syenyu nĩ ũthũku; ilomo syenyu nineenete movũngũ, ũĩmĩ wenyu nũneenaa ũthũku.'),
('kam', 'ISA', 59, 4, 'Vati ũandũaa na ũlũngalu, na vati ũsilĩlaa na w’o: nĩmekwatasya vathei, na kũneena movũngũ; nĩmaitavaa ũthũku, na maisyaa naĩ.'),
('kam', 'ISA', 59, 5, 'Nĩmalĩkasya matumbĩ ma syĩmbuva, na matumaa ũlũalũĩ wa mbũambũĩ: ũla ũĩsaa matumbĩ masyo nũkusaa; na yĩla yakanyangwa yĩkyuma nzoka mbai.'),
('kam', 'ISA', 59, 6, 'Molũalũĩ moo matikatw’ĩka ngũa, o na matikevw’ĩka mawĩa moo: mawĩa moo nĩ mawĩa ma ũthũku, na wĩko wa ũng’endu wĩ mokonĩ moo.'),
('kam', 'ISA', 59, 7, 'Maũũ moo nĩmasembaa maatĩĩe ũthũku, nao mekalaataa metĩkye nthakame ĩte na ĩvĩtyo: mosũanĩo moo nĩ mosũanĩo ma ũthũku; wanango na wanangĩko syĩ nzĩanĩ syoo.'),
('kam', 'ISA', 59, 8, 'Ĩla nzĩa ya mũuo maimĩsĩ; na vati sila wa katĩ mĩendelenĩ yoo: nĩmeseũvĩsye nzĩa nthyoeku; o ũla ũendaa nasyo ndesĩ mũuo.'),
('kam', 'ISA', 59, 9, 'Kwondũ wa ũu sila wa katĩ wĩ kũasa naitũ, o na ũlũngalu ndũũtũwĩla: nĩtũmanthaa kyeni, ĩndĩ, kaĩ, no kĩvindu; na ũtisu, ĩndĩ tũkinyaa kĩvindunĩ.'),
('kam', 'ISA', 59, 10, 'Nĩtũvavataa ũvai ta kĩlilinda; ĩĩ, nĩtũvavataa ta ala mate metho: nĩtũlulũtĩkaa mũthenya katĩ o ta ũmololinĩ; katĩ wa ala me vinya tũilyĩ ta ala akw’ũ.'),
('kam', 'ISA', 59, 11, 'Ithyonthe nĩtũlumaa ta nduva, na kũamba mũno ta mavũĩ: nĩtũmanthaa sila wa katĩ ĩndĩ vatiĩ; na ũtangĩĩo, ĩndĩ wĩ kũasa naitũ.'),
('kam', 'ISA', 59, 12, 'Nũndũ mavĩtyo maitũ nĩmaingĩvie mbee waku, na naĩ sitũ nĩtũkũsĩĩaa; nũndũ mavĩtyo maitũ me vamwe naitũ, na ũndũ wa mothũku maitũ, nĩtũmesĩ:'),
('kam', 'ISA', 59, 13, 'kũmũvĩtanĩsya na kũmũkaĩa Yeova, na kwĩthyũũa na kũeka kũatĩĩa Ngai waitũ, kũneena na ũng’endu na ũlei, kũsũanĩa ndeto sya ũvũngũ na kwineena kuma ngoonĩ.'),
('kam', 'ISA', 59, 14, 'Na sila wa katĩ nũtũngĩtwe na ĩtina, na ũlũngalu nũũngeme wĩ kũasa; nũndũ w’o nũvalũkĩte nzĩanĩ nene, na ũlũngalu ndũtonya kũlika.'),
('kam', 'ISA', 59, 15, 'Ĩĩ, w’o nĩ mwau; na ũla ũtiaa ũthũku nũtw’ĩkaa mũsyĩmwa. Na Yeova nĩwonie ũu, na ndaaendeew’a nũndũ vatyaĩ sila wa katĩ.'),
('kam', 'ISA', 59, 16, 'Na oona kana vati mũndũ, na aseng’a nũndũ vati ũmwe wa kũvoyea; kwondũ wa ũu kw’oko kwake mwene nĩkwamũetee ũtangĩĩo; na ũlũngalu wake, nĩw’o wamũtw’ĩĩkie.'),
('kam', 'ISA', 59, 17, 'Nake eekĩa ũlũngalu ta ngao ya kĩthũi, na ngovia ya ũtangĩĩo mũtwenĩ wake; nake eevw’ĩka ũĩvanĩsyo wĩthĩwe ngũa syake, na eevw’ĩka kĩwĩu ta suka.'),
('kam', 'ISA', 59, 18, 'Kwĩanana na meko moo, now’o ũkeĩvanĩsya, ũthatu kwa nthũ syake, ũĩvanĩsyo kwa amaitha make; ila ithama akaĩvanĩsya ũndũ syeekie.'),
('kam', 'ISA', 59, 19, 'Kwondũ wa ũu makakĩa syĩtwa ya Yeova kuma ũthũĩlonĩ wa syũa, na ũnene wake kuma vala syũa yumĩlaa. Yĩla mũmaitha ũkoka ta kĩw’ũ kingĩ, Veva wa Yeova akamũkĩlĩlya kĩvevelo.'),
('kam', 'ISA', 59, 20, 'Na Mwovosya akooka Saioni, na kwa ala ma Yakovo ala methyũũaa makĩtia mavĩtyo, easya ũu Yeova.'),
('kam', 'ISA', 59, 21, 'Na ũndũ wakwa, ũũ nĩw’o ũtianĩo wakwa nao, easya ũu Yeova: Veva wakwa ũla wĩ ĩũlũ waku, na ndeto syakwa ila nĩkĩĩte kanyw’anĩ waku, itikauma kanyw’anĩ waku, kana kanyw’anĩ wa ũsyao waku, kana kanyw’anĩ wa ũsyao wa ũsyao waku, kuma yu na kũvika tene na tene, easya ũu Yeova.'),
('kam', 'ISA', 60, 1, 'Ũkĩla, ũtisũke; nũndũ kyeni kyaku nĩ kyũku, na ũtheu mũtisu wa Yeova nĩwumĩlĩte ĩũlũ waku.'),
('kam', 'ISA', 60, 2, 'Nũndũ, sisya, kĩvindu kĩkavw’ĩka nthĩ, na kĩvindu kya ngokomi kĩkavw’ĩka ngo sya andũ; ĩndĩ Yeova akakumĩlĩla, na ũtheu mũtisu wake ũkooneka ĩũlũ waku.'),
('kam', 'ISA', 60, 3, 'Na mbaĩ ikooka kyeninĩ kyaku, na asumbĩ ũtisũkunĩ wa kumĩla kwaku.'),
('kam', 'ISA', 60, 4, 'Ũngalalya metho maku ngalĩ syonthe, wone: onthe nĩmekwĩyũmban’ya vamwe, nĩmekũka vala ũĩ; ana maku makooka kuma kũasa, na eitu maku makakuwa na moko.'),
('kam', 'ISA', 60, 5, 'Nĩvo ĩndĩ wĩona na kũtisa, na ngoo yaku nayo ĩkatana na kũneneva; nĩkwĩthĩwa wingĩ wa ũkanga ũkathyũũwa welekelw’e kwaku, ũthwii wa i mbaĩ ũkooka kwaku.'),
('kam', 'ISA', 60, 6, 'Wingĩ wa ngamĩle ũkakũvw’ĩka, ngamĩle sya mũika sya Mitaini na Evaa; onthe ma Sieva makooka; makaete thaavu na ũvumba, na makatavan’ya ndaĩa sya Yeova.'),
('kam', 'ISA', 60, 7, 'Ndĩthya syonthe sya mbũi na malondu sya Ketali ikoombanw’a vala ũĩ, ndũũme sya Nevaiothi ikakũthũkuma; ikambata kĩthembeonĩ kyakwa ikĩtĩkĩlwa; na ngaanakavya nyũmba ya ũtheu mũtisu wakwa.'),
('kam', 'ISA', 60, 8, 'Aa naaũ ala maũlũkaa ta ĩthweo, na ta mavũĩ mbũthinĩ syamo?'),
('kam', 'ISA', 60, 9, 'Nĩ w’o ithama ikambeteela, na ngalawa sya Talisisi ikeethĩwa sya mbee sya kũete ana maku kuma kũasa, vetha woo na thaavu woo vamwe nao, ũndũ wa syĩtwa ya Yeova Ngai waku, na ũndũ wa Ũla Mũtheu wa Isilaeli, nĩkwĩthĩwa nũkũnenevetye.'),
('kam', 'ISA', 60, 10, 'Na andũ ma nthĩ ĩngĩ makaaka maũvai maku, na asumbĩ moo makakũthũkũma: nũndũ nĩnakũkũnie nĩ mũthatu, ĩndĩ ũseonĩ wakwa nĩngwĩw’ĩĩte tei.'),
('kam', 'ISA', 60, 11, 'Mbingĩlo syaku ikeethĩwa mbingũe mavinda onthe; itikavingwa mũthenya kana ũtukũ; nĩ kana andũ makũetee ũthwii wa i mbaĩ, na asumbĩ moo me atave.'),
('kam', 'ISA', 60, 12, 'Nũndũ mbaĩ na ũsumbĩ ũla ũleaa ũkũthũkũma ũkaaa; ĩĩ, mbaĩ isu ĩkaanangwa vyũ.'),
('kam', 'ISA', 60, 13, 'Ndaĩa ya Levanoni ĩkooka vala ũĩ, mũtĩ wa mũsonovali, na mũtindali, na mũtĩ wa mũvuena vamwe, yanakavye vandũ vakwa vatheu; na ngaseũvya vandũ va maũũ makwa vethĩwe va ndaĩa.'),
('kam', 'ISA', 60, 14, 'Na ana ma ala makũthĩnisye makooka vala ũĩ makĩkwĩkunamĩsya; na onthe ala makũvũthisye makeekunamya nyaĩĩnĩ syaku; na makakwĩta, Ndũa ya Yeova, Saioni ya Ũla Mũtheu wa Isilaeli.'),
('kam', 'ISA', 60, 15, 'Nĩkwĩthĩwa nĩwatiĩtwe na kũmenwa, o na mũndũ o na wĩva ndaĩ avĩtĩla kwaku, ngakũtw’ĩkĩthya ũnene wa tene na tene, ũtanu wa nzyawa nyingĩ.'),
('kam', 'ISA', 60, 16, 'O na ũkoonga ĩia ya i mbaĩ, na kwonga nondo sya asumbĩ; na ũkamanya kana nyie, Yeova, nĩ Mũtangĩĩi waku, na Mwovosya waku, Ũla Mwene Vinya wa Yakovo.'),
('kam', 'ISA', 60, 17, 'Vandũ va ũthuku ngaete thaavu, na vandũ va kĩaa ngaete vetha, na vandũ va mĩtĩ, ũthuku, na vandũ va mavia, kĩaa. Na ĩngĩ ngatw’ĩkĩthya anene ma kwaku mũuo, na aũngamĩi maku, ũlũngalu.'),
('kam', 'ISA', 60, 18, 'Ũng’endu ndũkew’ĩka ĩngĩ nthĩ yaku, wanango kana wanangĩko mĩvakanĩ yaku; ĩndĩ ũkeeta maũvai maku Ũtangĩĩo, na mbingĩlo syaku Ndaĩa.'),
('kam', 'ISA', 60, 19, 'Syũa yĩtikethĩwa ĩngĩ kyeni kyaku ĩvinda ya mũthenya; o na ũtisũku wa mwei ndũkakumĩsya kyeni: ĩndĩ Yeova akeethĩwa kwaku kyeni kya tene na tene, na Ngai waku ndaĩa yaku.'),
('kam', 'ISA', 60, 20, 'Syũa yaku yĩtikathũa ĩngĩ, o na mwei waku ndũkakw’a; nũndũ Yeova akeethĩwa kyeni kyaku tene na tene, na mĩthenya ya kũmeta kwaku ĩkeethĩwa ĩ mĩthelu.'),
('kam', 'ISA', 60, 21, 'O na andũ maku onthe makeethĩwa alũngalu; makatiĩwa ĩ nthĩ tene na tene, ũvonge wa kũvanda kwakwa, wĩa wa moko makwa, nĩ kana nĩtaĩwe.'),
('kam', 'ISA', 60, 22, 'Ũla mũnini akatw’ĩka ngili, na ũla mũnini akeethĩwa mbaĩ yĩ vinya: nyie, Yeova, ngakalaata ũndũ ũsu ĩvinda yaw’o.'),
('kam', 'ISA', 61, 1, 'Veva wa Mwiaiĩ Yeova e ĩũlũ wakwa; nũndũ Yeova nĩwambĩtĩkĩsye mauta nĩtavye ala auu ũvoo mũseo; nũndũmĩte nove ala me na ngoo ndũlĩku, na nĩtavan’ye ũthasyo kwa ala atave, na nĩmavingũĩe kolokolo ala movetwe;'),
('kam', 'ISA', 61, 2, 'na nĩtavan’ye mwaka wa ũseo wa Yeova, na mũthenya wa ũĩvanĩsyo wa Ngai waitũ; na nĩmakiakisye onthe ala mametaa;'),
('kam', 'ISA', 61, 3, 'na kũmaiĩa ala mameteaa ku Saioni, nĩmanenge ngovia ya ndaĩa vandũ va mũu, mauta ma ũtanu vandũ va kũmeta, ngũa ya ndaĩa vandũ va veva wa kũmaka; nĩ kana matonye kwĩtwa mĩtĩ ya ũlũngalu, ĩvandĩtwe nĩ Yeova, nĩ kana ataĩwe.'),
('kam', 'ISA', 61, 4, 'Na makaaka kũla kwaanangĩkie tene, makookĩlya kũla kwaekiwe mbee, na makatũngĩĩa ndũa ila syaĩ maanzo, kũla kwaekiwe nĩ nzyawa nyingĩ.'),
('kam', 'ISA', 61, 5, 'Na aeni makaũngamaa na kũĩthya ndĩthya syenyu sya mbũi na malondu, na andũ ma nthĩ ĩngĩ makeethĩwa andũ menyu ma kũima, na asei ma mĩsavivũ mĩũndanĩ yenyu.'),
('kam', 'ISA', 61, 6, 'Ĩndĩ inyw’ĩ mũkeetawa athembi ma Yeova; andũ makamwĩtaa athũkũmi ma Ngai waitũ: mũkaĩsaa ũthwii wa i mbaĩ, na mũkeekathĩĩaa ndaĩanĩ yoo.'),
('kam', 'ISA', 61, 7, 'Vandũ va nthoni syenyu kũndũ kwĩlĩ; na vandũ va kũtataĩwa makatanĩa kĩandanĩ kyoo: kwondũ wa ũu me nthĩ yoo makanengwa kũndũ kwĩlĩ; ũtanu ũtathelaa ũkeethĩwa woo.'),
('kam', 'ISA', 61, 8, 'Nũndũ nyie Yeova, nendaa sĩla wa katĩ, nĩmenaa ũng’ei vamwe na ũthũku; na ngamanenga ĩtuvi yoo na w’o, na ngatianĩa ũtianĩo wa tene na tene nao.'),
('kam', 'ISA', 61, 9, 'Na ũsyao woo ũkamanyĩka katĩ wa i mbaĩ, na ũsyao woo katĩ wa ngo sya andũ: onthe ala mamonaa makametĩkĩla, atĩ nĩmo ũsyao ũla ũathimĩtwe nĩ Yeova.'),
('kam', 'ISA', 61, 10, 'Ngatana mũno nthĩnĩ wa Yeova, ngoo yakwa ĩkeethĩwa na ũtanu nthĩnĩ wa Ngai wakwa; nũndũ nũmbw’ĩkĩte ngũa sya ũtangĩĩo, nũmbw’ĩkĩte ngũa ya ũlũngalu, o tondũ mũtwaani wĩyanakavasya na ngovia ya ndaĩa, na tondũ mũtwawa wĩyanakavasya na mĩio yake ya wanake.'),
('kam', 'ISA', 61, 11, 'O tondũ nthĩ ĩmeasya wenze wayo, na tondũ mũũnda ũmeasya mbeũ ila ivandĩtwe nthĩnĩ waw’o; o ta ũu Mwĩaĩi Yeova akaumĩlangya ũlũngalu na ndaĩa kwa mbaĩ syonthe.'),
('kam', 'ISA', 62, 1, 'Kwondũ wa Saioni ndikavindya, na kwondũ wa Yelusaleme ndikathũmũa, kũvika ũlũngalu wake wumĩle ta kyeni, na ũtangĩĩo wake ta taa mwakanu.'),
('kam', 'ISA', 62, 2, 'Na i mbaĩ ikoona ũlũngalu waku, na asumbĩ onthe ndaĩa yaku; na ũkeetwa syĩtwa yeũ, yĩla kanyw’a wa Yeova ũketana'),
('kam', 'ISA', 62, 3, 'Na ĩngĩ ũkeethĩwa ngovia ya ũsumbĩ mbanakavu kw’okonĩ kwa Yeova, na kĩlemba kya kĩũsumbĩ kw’okonĩ kwa Ngai waku.'),
('kam', 'ISA', 62, 4, 'Ndũketwa ĩngĩ Mũtiwa; o na nthĩ yaku ndĩketwa ĩngĩ Nthei: ĩndĩ ũkeetwa Evisiva, na nthĩ yaku Mbeula; nũndũ Yeova nũtanĩthaw’a nue, na nthĩ yaku ĩkatwanĩthw’a'),
('kam', 'ISA', 62, 5, 'Nũndũ o tondũ mwanake ũtwaaa mwĩĩtu mũtheu, now’o ana maku makakũtwaa; na tondũ mũtwaani ũtanĩaa mũtwawa, now’o Ngai ũkakũtanĩaa.'),
('kam', 'ISA', 62, 6, 'Nĩnĩite asyaĩĩsya maũvainĩ maku, we Yelusaleme; matikavindya mũthenya kana ũtukũ: inyw’ĩ ala mũmũlilikanasya Yeova, mũikathũmũe,'),
('kam', 'ISA', 62, 7, 'na mũtikamũeke athũmũe, kũvika alũlũmĩlya, na atw’ĩkĩthya Yelusaleme ndaĩa kũũ nthĩ.'),
('kam', 'ISA', 62, 8, 'Yeova nĩwĩvĩtĩte na kw’oko kwake kwa aũme, o kw’oko kwake kwĩ vinya, atĩĩ, Vate ndiĩ ndikanengane ĩngĩ lĩu waku wa mbaa ngetha wĩthĩwe lĩu wa amaitha maku; na andũ ma nthĩ ĩngĩ matikanyw’a mbinyu yaku mbĩthĩ, ĩla watethisye wĩa kwondũ wayo:'),
('kam', 'ISA', 62, 9, 'ĩndĩ ala makethie nĩo makaya, na kũtaĩa Yeova; na ala moombanisye makanyw’a me nza sya vandũ vakwa vatheu.'),
('kam', 'ISA', 62, 10, 'Vĩtai, vĩtai mbingĩlonĩ; seũvyai nzĩa ya andũ; ĩnzai, ĩnzai lelũ; ũmyai mavia; ũkĩlyai kĩvevelo ũndũ wa ngo sya andũ.'),
('kam', 'ISA', 62, 11, 'Sisya, Yeova nũtavanĩtye kũvika kĩtulu kya nthĩ, Mwĩei mwĩĩtu wa Saioni, Sisya, ũtangĩĩo wake nĩwũkĩte; sisya, ĩtuvi yake yĩ vamwe nake, na ũĩvanĩsyo wake wĩ mbee wake.'),
('kam', 'ISA', 62, 12, 'Na makametaa Andũ atheu, Ala moovoiw’e nĩ Yeova: naku ũkeetwa Ũla wamanthiwe, Ndũa ĩtaaekwa.'),
('kam', 'ISA', 63, 1, 'Ũũ nũũ ũla wũkĩte kuma Etomu, wĩkĩĩte ngũa syĩ langi mũtune mũno kuma Mbosila? Ũũ ũla wĩ na ngũa syake sya ndaĩa, ũendete ũnenenĩ wa vinya wake? Ninyie ũla ũneenaa na ũlũngalu, mũtonyi wa kũtangĩĩa.'),
('kam', 'ISA', 63, 2, 'Nũndũ wa kĩ ngũa syaku nĩ ndune, na ngũa syaku nĩ ta sya ũla ũkinyangaa nzavivũ kĩangĩonĩ?'),
('kam', 'ISA', 63, 3, 'Nyie nĩnĩkinyangĩte kĩangĩo kya nzavivũ nĩ nyioka; na katĩ wa ngo sya andũ kũtyaĩ mũndũ waĩ nakwa: ĩĩ, nĩnamakinyangie nĩ mũthatu, nĩnamaanganisye nĩ mũthilĩku; na nthakame ya thayũ woo nĩtalĩkangĩle ngũa syakwa, na nĩnĩthũkĩtye ngũa syakwa syonthe.'),
('kam', 'ISA', 63, 4, 'Nũndũ mũthenya wa kũĩvanĩsya waĩ ngoonĩ yakwa, na mwaka wa ovosye makwa nĩ mũku.'),
('kam', 'ISA', 63, 5, 'Nakwa nasisya, na vatyaĩ ũmwe wa kũtethya; na naseng’a nũndũ vatyaĩ ũmwe wa kũtw’ĩĩka: kwondũ wa ũu kw’oko kwakwa mwene nĩkwambonee ũtangĩĩo; na kũthilĩka kwakwa nĩkw’o kwandw’ĩĩkie.'),
('kam', 'ISA', 63, 6, 'Na nĩnakinyangie ngo sya andũ nĩ mũthatu, na nĩnamatoonethisye kũthilĩkanĩ kwakwa, na netĩkya nthĩ nthakame ya mathayũ moo.'),
('kam', 'ISA', 63, 7, 'Ngaweta moseo me wendo ma Yeova, na ndaĩa sya Yeova, kwĩanana na w’onthe ũla Yeova watũnengie, na ũseo mũnene ũla welekele nyũmba ya Isilaeli, ũla wamanengie kwĩanana na matei make, na kwĩanana na kwingĩva kwa moseo make me wendo.'),
('kam', 'ISA', 63, 8, 'Nũndũ aisye, Nĩ w’o, nĩ andũ makwa, syana ila iteĩka ũkengani: kwondũ wa ũu aĩ Mũtangĩĩi woo.'),
('kam', 'ISA', 63, 9, 'Thĩnanĩ woo w’onthe nake nĩwathĩnaw’a, na mũlaĩka wa ũthyũ wake amatangĩĩa: ũndũ wa wendo wake na tei wake amovosya; na amokilya, na amakua mĩthenya yonthe ya tene.'),
('kam', 'ISA', 63, 10, 'Ĩndĩ mang’enda na meew’ĩthya Veva wake mũtheu woo: kwondũ wa ũu eealyũla ethĩwe mũmaitha woo, nake mwene okita nao.'),
('kam', 'ISA', 63, 11, 'Nĩvo ĩndĩ walilikanile mĩthenya ya tene, Mose na andũ make, akyasya, Aĩva ũla wamaumisye ũkanganĩ vamwe na aĩthi ma ndĩthya yake ya mbũi na malondu? Aĩva ũla wekĩie Veva wake mũtheu katĩ woo?'),
('kam', 'ISA', 63, 12, 'Ũla watumie kw’oko kwake kũtheu kũtongoesya kw’oko kwa aũme kwa Mose, ũla wataanisye manzĩ mbee woo, eseũvĩsye mwene syĩtwa ya tene na tene?'),
('kam', 'ISA', 63, 13, 'Ũla wamatongoesye mavĩtĩle syũngũnĩ, ta mbalasi weũnĩ, matikalulutĩke?'),
('kam', 'ISA', 63, 14, 'O ta indo ila itheeaa mwandanĩ now’o Veva wa Yeova wamathũmũisye: now’o watongoeasya andũ maku, wĩseũvĩsye mwene syĩtwa ĩnene'),
('kam', 'ISA', 63, 15, 'Sisya wĩ ĩtunĩ, noisisya wĩ wĩkalonĩ wa ũtheu waku na wa ũnene waku: ũthangaau waku na meko maku ma vinya maĩva? Mea ma ngoo yaku na matei maku nĩmeũsiĩĩwa maikambikĩe.'),
('kam', 'ISA', 63, 16, 'Nũndũ nue Asa waitũ, o na kau Avalaamu ndeũtũmanya, na Isilaeli ndeũtwĩtĩkĩla: we, ame Yeova, wĩ Asa waitũ; syĩtwa yaku nĩ Mwovosya waitũ kuma tene tene.'),
('kam', 'ISA', 63, 17, 'Ame Yeova, wĩtũvĩtĩthya nzĩa syaku nũndũ wa kĩ, na kũmya ngoo sitũ ieke ũkũkĩa? Kwondũ wa athũkũmi maku tũnga mbaĩ sya ũtiĩwa waku.'),
('kam', 'ISA', 63, 18, 'Andũ maku atheu nĩmekalile naw’o ĩvinda ĩnini kĩ: nthũ sitũ nikinyangĩte vandũ vaku vatheu.'),
('kam', 'ISA', 63, 19, 'Nĩtũtw’ĩkĩte ta ala mataasumbĩkwa nue nongi, ta ala mataaĩtanĩw’a na syĩtwa yaku.'),
('kam', 'ISA', 64, 1, 'A! Kethĩwa nũtembũa matu, kethĩwa nũtheea kũũ nthĩ, nĩ kana iĩma itetemee mbee waku,'),
('kam', 'ISA', 64, 2, 'o ta mwaki yĩla ũũvĩvya kĩtheka, na mwaki ũũtheũkya manzĩ; nĩ kana ũmanyĩthye nthũ syaku syĩtwa yaku, nĩ kana i mbaĩ itetemee mbee waku!'),
('kam', 'ISA', 64, 3, 'Yĩla weekie maũndũ ma ũtĩsya ala tũtaasũanĩa, nĩvo watheeie nthĩ, iĩma syatetemea mbee waku.'),
('kam', 'ISA', 64, 4, 'Nũndũ kuma tene andũ matyaaĩw’a, o na matyaakwata na kũtũ makamanya, o na itho yĩtyaaona Ngai ũngĩ ate o we, ũla ũtetheeasya ũla ũmweteelaa.'),
('kam', 'ISA', 64, 5, 'We nũthaũaa ũla ũtanaa na kwĩkaa ũlũngalu, ala makũlilikanaa nzĩanĩ syaku: sisya, waĩ mũthilĩku, naitũ nĩtwavĩtisye: nĩtwĩkalĩte nthĩnĩ wamo ĩvinda ĩasa; na ithyĩ tũkatangĩĩwa?'),
('kam', 'ISA', 64, 6, 'Nũndũ ithyonthe nĩtũtw’ĩkĩte ta ũmwe mũvuku, na molũngalu maitũ onthe mailyĩ ta ngũa mbuku mũno: na ithyonthe nĩtũvovaa ta ĩtũ; na mothũku maitũ nĩmeũtũtwaa ta kĩseve.'),
('kam', 'ISA', 64, 7, 'Na vati ũmwe wĩkaĩlaa syĩtwa yaku, ũla wĩvindũaa mwene akwĩkwatye; nũndũ nũtũvithĩte ũthyũ waku, na nũtũminĩte kwondũ wa mothũku maitũ.'),
('kam', 'ISA', 64, 8, 'Ĩndĩ yu, ame Yeova, nue Asa waitũ; ithyĩ twĩ yũmba, na nue mũmbi waitũ; na ithyonthe twĩ wĩa wa kw’oko kwaku.'),
('kam', 'ISA', 64, 9, 'Ndũkathilĩke mũno, ame Yeova, o na ndũkalilikane ũthũku tene na tene: sĩsya, ũketee, nĩtũũkwĩkaĩla, ithyonthe twĩ andũ maku.'),
('kam', 'ISA', 64, 10, 'Ndũa syaku ntheu nĩtw’ĩkĩte weũ, Saioni nĩtw’ĩkĩte weũ, na Yelusaleme ĩanzo.'),
('kam', 'ISA', 64, 11, 'Nyũmba yaitũ ntheu na mbanakavye, ĩla aaithe maitũ makũtaĩĩaa nthĩnĩ wayo nĩvĩvĩtw’e na mwaki; na kũndũ kwĩtũ kw’onthe kwa kwendeesya nĩkũtw’ĩkĩthĩtw’e kũthei.'),
('kam', 'ISA', 64, 12, 'Ukeesiĩĩa kwondũ wa maũndũ asu, ame Yeova ũkavindya ki, na kũtũthĩn’ya mũno?'),
('kam', 'ISA', 65, 1, 'Nĩngwĩsũvĩka nĩ ala mataangũlya; nĩnonekete nĩ ala mataamantha: mbaĩ ĩla ĩtaaĩtanĩw’a na syĩtwa yakwa nĩnamĩtavisye, Nzisya, nzisya.'),
('kam', 'ISA', 65, 2, 'Nĩnĩmatambũũkĩsye andũ ang’endu moko makwa mũthenya mũima, ala maendaa mũendelenĩ ũte mũseo, makĩatĩĩa mosũanĩo moo ene;'),
('kam', 'ISA', 65, 3, 'andũ ala manthatasya ũthyũnĩ wakwa mavinda onthe, makĩthemba mĩũndanĩ, na kũtoeeesya ũvani ĩũlũ wa mavali;'),
('kam', 'ISA', 65, 4, 'ala mekalaa nthĩ katĩ wa mbũa, na kũkoma kũndũ kĩmbithĩnĩ; ala maĩsaa nyama sya ngũlũe, na mũsavũ wa syĩndũ imenetwe wĩ mĩionĩ yoo;'),
('kam', 'ISA', 65, 5, 'ala maasya, Ũngama weka, ndũkanthengeee, nũndũ nyie nĩ mũtheu kwĩ we. Asu nĩ syũki manyiũũnĩ makwa, mwaki ũla wakanaa mũthenya w’onthe.'),
('kam', 'ISA', 65, 6, 'Sisya, nĩkũandĩkĩtwe mbee wakwa: Ndikavindya, ĩndĩ ngaĩvanĩsya, ĩĩ, ngaĩvanĩsya kĩthũinĩ kyoo,'),
('kam', 'ISA', 65, 7, 'mothũku menyu ene na mothũku ma aaĩthe menyu vamwe, easya ũu Yeova, ala matoeeesye ũvani iĩmanĩ na kũnumĩa tũlĩmanĩ: kwondũ wa ũu ngamba kũthimĩa wĩa woo kĩthũinĩ kyoo.'),
('kam', 'ISA', 65, 8, 'Ũũ nĩw’o Yeova ũnũkwasya, O tondũ mbinyu mbĩthĩ yonekaa kĩtũngonĩ, na ũmwe easya, Ndũkakyanange, nũndũ ũathimo wĩ nthĩnĩ wakyo: now’o ngeka kwondũ wa athũkũmi makwa, nĩ kana ndikamanange onthe.'),
('kam', 'ISA', 65, 9, 'Na ngaumya ũsyao nthĩnĩ wa Yakovo, na mũtiĩwa wa iĩma syakwa kuma nthĩnĩ wa Yuta; na anyuve makwa makatiĩwa yo, na athũkũmi makwa makatũaa kw’o.'),
('kam', 'ISA', 65, 10, 'Na Saioni ĩkeethĩwa kĩsesi kya ndĩthya sya mbũi na malondu, na mwanda wa Akoli vandũ va ndĩthya sya ng’ombe kũtindiaa, kwondũ wa andũ makwa ala mamanthie nyie.'),
('kam', 'ISA', 65, 11, 'Ĩndĩ inyw’ĩ ala mũtiaa Yeova, ala mũlawa nĩ kĩĩma kyakwa kĩtheu, ala mwalanasya mesa kwondũ wa ngai yĩtawa Ũthwii, na ala musũasya mĩio mbinyu ĩvulanĩtw’e kwondũ wa ngai yĩtawa Ĩvuso;'),
('kam', 'ISA', 65, 12, 'ngamũtw’ĩĩa inyw’ĩ kũawa na ũvyũ, na inyw’onthe mũkakunama mũawe; nĩkwĩthĩwa yĩla neetanie, mũtyaaĩtĩka; yĩla naneenie, mũtyaaĩw’a; ĩndĩ nĩmweekie ũla nonaa wĩ ũthũku, na mwanyuva ũla ndaatanĩa.'),
('kam', 'ISA', 65, 13, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ, Sisya, athũkũmi makwa makaĩsaa, ĩndĩ inyw’ĩ mũkeethĩwa na nzaa; sisya, athũkũmi makwa makanyusaa ĩndĩ inyw’ĩ mũkeethĩwa na waũni: sisya, athũkũmi makwa makatanaa, ĩndĩ inyw’ĩ mũkasonokw’a;'),
('kam', 'ISA', 65, 14, 'sisya, athũkũmi makwa makainaa ũndũ wa ũtanu wa ngoo, ĩndĩ inyw’ĩ mũkaĩaa ũndũ wa kĩmako kya ngoo, na mũkakaya ũndũ wa woo wa veva.'),
('kam', 'ISA', 65, 15, 'Na mũkatia syĩtwa yenyu yĩthĩwe kĩumo kwa anyuve makwa; na Mwĩaĩi Yeova akakũaa; na akeeta athũkũmi syĩtwa yĩngĩ:'),
('kam', 'ISA', 65, 16, 'nĩ kana ũla wĩĩathimaa mwene kũũ nthĩ akeeathimaa nthĩnĩ wa Ngai wa w’o, na ũla wĩĩvĩtaa kũũ nthĩ, akeevĩtaa na Ngai wa w’o; nĩkwĩthĩwa mathĩna ma mbee nĩmolĩte, na nĩkwĩthĩwa nĩmavithĩtwe ũndũ ndatonya kũmona.'),
('kam', 'ISA', 65, 17, 'Nũndũ, sisya, nĩngũmba matu meũ na nthĩ nzaũ; na maũndũ ma mbee matikalilikanwa, o na matikalika kĩlilikanonĩ.'),
('kam', 'ISA', 65, 18, 'Ĩndĩ ĩthĩwai na mũyo na mũitanĩaa tene na tene kĩla nũmbaa; nũndũ, sisya, nĩngũmba Yelusaleme yĩthĩwe ya kũtanĩthya, na andũ mayo methĩwe ũtanu.'),
('kam', 'ISA', 65, 19, 'Na ngatanĩaa Yelusaleme, na kũtanĩaa andũ makwa; na kũtikew’ĩka nthĩnĩ wayo ĩngĩ wasya wa kũmeta na wasya wa kũĩa.'),
('kam', 'ISA', 65, 20, 'Kũtikethĩwa kw’o ĩngĩ kaũkenge ka mĩthenya, kana mũtumĩa ũla ũtaaĩanĩsya mĩthenya yake; nũndũ kana kakakusaa ke ka myaka ĩana, na mũndũ mwathe e wa myaka ĩana akw’a akethĩwa e mũumanĩe.'),
('kam', 'ISA', 65, 21, 'Na makaaka nyũmba, na kũtũa nthĩnĩ wasyo; na makavanda mĩũnda ya mĩsavivũ, na makaya ũsyao wayo.'),
('kam', 'ISA', 65, 22, 'Matikaka na ũngĩ aitũa; matikavanda na ũngĩ aiya; nũndũ o tondũ mũtĩ wĩan’ya mĩthenya now’o kũkethĩwa mĩthenya ya andũ makwa, na anyuve makwa makatanĩaa wĩa wa moko moo ĩvinda ĩasa.'),
('kam', 'ISA', 65, 23, 'Matikathĩnĩa wĩa mana, o na matikasyaĩa thĩna; nũndũ nĩ ũsyao wa ala aathime ma Yeova, na ũsyao woo vamwe nao.'),
('kam', 'ISA', 65, 24, 'Na kũkeethĩwa atĩ, matanamba kũmbĩkaĩla, ngeetĩka; na o yĩla meũneena, ngeew’a.'),
('kam', 'ISA', 65, 25, 'Nzũi na katena ka ĩlondu ikaya vamwe, na mũnyambũ ũkaya nyeki ta ng’ombe; na mũthanga ũkeethĩwa lĩu wa nzoka. Kũikew’anĩthw’a woo kana kwanangana kĩĩmanĩ kyakwa kyonthe kĩtheu, easya ũu Yeova.'),
('kam', 'ISA', 66, 1, 'Ũũ nĩw’o Yeova ũnũkwasya, Ĩtu nĩ kĩvĩla kyakwa kya ũsumbĩ, na nthĩ nĩ kavĩla kakwa kya nyaĩĩ: mũkambakĩa nyũmba ĩilyĩ ata? Na nĩ va vakethĩwa vandũ vakwa va ũthũmũa?'),
('kam', 'ISA', 66, 2, 'Nũndũ kw’oko kwakwa nĩkũmbĩte syĩndũ ii syonthe, na kwondũ wa ũu syĩndũ ii syonthe syeethĩwa, easya ũu Yeova; ĩndĩ mũndũ ũũ nĩwe nĩsiasya, o ũla ngya na wĩ na veva wa kwĩlila, na ũla ũtetemaa ũndũ wa ndeto yakwa.'),
('kam', 'ISA', 66, 3, 'Ũla wũaaa ng’ombe ailyĩ ta ũla wũaaa mũndũ; ũla ũthembaa katena ka ĩlondu, ta ũla ũtũlaa ngingo ya ngitĩ; ũla ũthembaa nthembo ya mũtu, ta ũla ũthembaa nthakame ya ngũlũe; ũla ũtoeeasya ũvumba, ta ũla ũathimaa mũvw’anano. Ĩĩ, nĩmanyuvĩte nzĩa syoo, na thayũ woo nũtanĩaa mothatyo moo:'),
('kam', 'ISA', 66, 4, 'nakwa nganyuva o mokengani moo, na ngamaetee maũndũ ala makĩaa; nĩkwĩthĩwa yĩla neetanie, vai ũmwe waaĩtĩka; yĩla naneenie, matyaaĩw’a: ĩndĩ nĩmeekie ũla nonaa wĩ ũthũku, na manyuva ũla ndaatanĩa.'),
('kam', 'ISA', 66, 5, 'Ĩw’ai ndeto ya Yeova, inyw’ĩ ala mũtetemaa ũndũ wa ndeto yake: Ana‐a‐ĩthe menyu ala mamũmenaa, ala mamwĩkasya nza kwondũ wa syĩtwa yakwa, nĩmaĩtye, Yeova nataĩwe, nĩ kana twone ũtanu wenyu; ĩndĩ nĩmo makasonokw’a.'),
('kam', 'ISA', 66, 6, 'Wasya wa kĩtuu kuma ndũanĩ, wasya kuma ĩkalũnĩ, wasya wa Yeova ũla ũĩvaa amaitha make.'),
('kam', 'ISA', 66, 7, 'Atanamba kwaũnya asyaa, atanambĩlĩlya kwĩw’a woo, asyaa kana ka kavĩsĩ.'),
('kam', 'ISA', 66, 8, 'Nũũ wewie ũndũ ta ũsu? Nũũ wonie maũndũ ta asu? Nthĩ ĩkasyawa mũthenya ũmwe? Mbaĩ ĩkasyawa o ĩmwe? Nũndũ o yĩla Saioni waũnyie nĩwasyaie syana syake.'),
('kam', 'ISA', 66, 9, 'Ngavikya va kũsyaa, na ndituma kũsyawa? Easya ũu Yeova: nyie ũla ndumaa kũsyawa ngatuma kũtasyawa? Easya ũu Ngai waku.'),
('kam', 'ISA', 66, 10, 'Tanai vamwe na Yelusaleme, na ĩthĩwai na mũyo ũndũ wayo, inyw’onthe ala mũmyendaa: tanai vamwe nayo ũtanu mũnene, inyw’onthe ala mũmĩmeteaa;'),
('kam', 'ISA', 66, 11, 'nĩ kana mwonge nondo sya ũkiakisyo wayo na mwĩthĩwe mũvũnĩte; nĩ kana mũkame, na mũitanw’a nĩ wingĩ wa ndaĩa yayo.'),
('kam', 'ISA', 66, 12, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Sisya, ngamĩvikĩsya mũuo ta ũsĩ ũvingĩte ũkakĩla: na inyw’ĩ mũkoonga; mũkakuwa na ĩvava, na mũkathakĩw’a maunĩ.'),
('kam', 'ISA', 66, 13, 'Ta ũla ũkiakiaw’a nĩ nyinyia, now’o ngamũkiakisya; na mũkakiakiĩaw’a Yelusaleme.'),
('kam', 'ISA', 66, 14, 'Na mũkoona, na ngoo yenyu ĩkatana, na mavĩndĩ menyu makaneneva ta nyeki ya vuvĩ: na kw’oko kwa Yeova kũkamanyĩka kwa athũkũmi make; na akamathatĩa amaitha make.'),
('kam', 'ISA', 66, 15, 'Nũndũ, sisya, Yeova akooka e na mwaki, na makasya make makeethĩwa ta kĩlingi; aĩve na wai ũthatu wake, na ũkan’yo wake e na mũĩ sya mwaki.'),
('kam', 'ISA', 66, 16, 'Nũndũ Yeova akasilĩla mĩĩ yonthe na mwaki, na ũvyũ wake; na ala meũawa nĩ Yeova makeethĩwa aingĩ.'),
('kam', 'ISA', 66, 17, 'Ala mevathanasya na kwĩthesya ene malike mĩũndanĩ, ĩtina wa mũtĩ ũmwe wĩ katĩ, makĩya nyama sya ngũlũe, na kĩla kĩmenetwe. O na kavĩla, nao makaminwa vamwe, easya ũu Yeova.'),
('kam', 'ISA', 66, 18, 'Nũndũ nĩnĩsĩ mawĩa moo na mosũanĩo moo: ĩvinda nĩyũkĩte yĩla ngomban’ya mbaĩ syonthe na ithyomo syonthe; na ikooka na kwona ũtheu mũtisu wakwa.'),
('kam', 'ISA', 66, 19, 'Na ngaia ũvano katĩ wasyo, na ngatũma ala mevonoka katĩ wasyo maende mbaĩnĩ, ku Talisisi, na Vulu, na Luti, ila ikootaa ũta, maende ku Tuvali na Yavani, na ithamanĩ ila syĩ kũasa, ila itaaĩw’a nguma yakwa, o na itaaona ũtheu mũtisu wakwa; na makatavan’ya ũnene wakwa katĩ wa i mbaĩ.'),
('kam', 'ISA', 66, 20, 'Na makaete ana‐a‐ĩthe menyu onthe kũmaumya mbaĩnĩ syonthe methĩwe nthembo kwa Yeova, matũlĩte mbalasi, na makasya, na mĩsekeseke, na nyũmbũ, na ngamĩle sya mũika, mavike kĩĩmanĩ kyakwa kĩtheu Yelusaleme, easya ũu Yeova, o tondũ ana ma Isilaeli maetae nthembo yoo yĩ kĩndũnĩ kĩtheu nyũmbanĩ ya Yeova.'),
('kam', 'ISA', 66, 21, 'O na ngoosa katĩ woo andũ methĩwe athembi na Alivai, easya ũu Yeova.'),
('kam', 'ISA', 66, 22, 'O ũndũ matu meũ na nthĩ nzaũ ila ngomba ĩkekalaa mbee wakwa, now’o ũsyao wenyu na syĩtwa yenyu ikekalaa, easya ũu Yeova.'),
('kam', 'ISA', 66, 23, 'Na kũkeethĩwa, kuma mwei ũmwe watisa kũvika ũla ũngĩ, na kuma mũthenya ũmwe wa savato kũvika ũla ũngĩ, mĩĩ yonthe ĩkookaa kũthaitha mbee wakwa, easya ũu Yeova.'),
('kam', 'ISA', 66, 24, 'Na makaumaala, na kũsisya simba sya andũ ala mambĩtanĩsye: nũndũ kĩinyu kyoo kĩtikakw’a, o na mwaki woo ndũkavow’a; na makeethĩwa kĩthĩtha kwa mĩĩ yonthe.'),
('kam', 'JER', 1, 1, 'Ndeto sya Yelemia mwana wa Ilikia, wa athembi ala maĩ Anathothi nthĩ ya Mbenyamini:'),
('kam', 'JER', 1, 2, 'ũla wokĩwe nĩ ndeto ya Yeova mĩthenyanĩ ya Yosia mwana wa Amoni, mũsumbĩ wa Yuta, mwaka wa ĩkũmi na ĩtatũ wa kũsumbĩka kwake.'),
('kam', 'JER', 1, 3, 'O na nĩyokie mĩthenya ya Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, kũvika mũminũkĩlyo wa mwaka wa ĩkũmi na ũmwe wa kũsumbĩka kwa Nzetekia, mwana wa Yosia, mũsumbĩ wa Yuta, kũvika kũtavwa kwa Yelusaleme mwei wa katano.'),
('kam', 'JER', 1, 4, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'JER', 1, 5, 'Ndanamba ũkũmbĩa ĩvunĩ nĩnakwĩsĩ, na ũtanamba kuma ĩvunĩ nĩnakũvathie wĩthĩwe mũtheu; nĩnakwiie wĩthĩwe mwathani kwa ĩ mbaĩ.'),
('kam', 'JER', 1, 6, 'Nĩvo ĩndĩ naisye, A! Mwĩaĩi Yeova! Sisya, ndiũmanya kũneena; nũndũ nyie nĩ kana.'),
('kam', 'JER', 1, 7, 'Ĩndĩ Yeova ambĩa, Ndũkasye, Nyie nĩ kana; nũndũ ũkathi kwa o ũla nĩkũtũma, na o ũndũ nĩkwĩaĩa ũkaneena.'),
('kam', 'JER', 1, 8, 'Ndũkakĩe nũndũ woo; nũndũ nĩ vamwe naku kũũvonokya, easya ũu Yeova.'),
('kam', 'JER', 1, 9, 'Nĩvo ĩndĩ Yeova watambũũkisye kw’oko kwake, na akiita kanyw’a wakwa; na Yeova ambĩa, Sisya, nĩnĩkĩĩte ndeto syakwa kanyw’anĩ waku:'),
('kam', 'JER', 1, 10, 'sisya, ũmũnthĩ nĩnakwia wĩthĩwe mũnene wa i mbaĩ na wa mosumbĩ, kũkũa na kũomboa na kwananga na kũng’uthũla, kwaka na kũvanda.'),
('kam', 'JER', 1, 11, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkĩngũlya, Yelemia, wĩona kyaũ? Nakwa nasya, Nĩngwona ndata ya mũtĩ wa mũlosi.'),
('kam', 'JER', 1, 12, 'Na ĩndĩ Yeova ambĩa, Nĩwoona nesa: nũndũ nĩsyaĩĩsyaa ndeto yakwa nĩmĩanĩsye.'),
('kam', 'JER', 1, 13, 'Na ndeto ya Yeova yambũkĩa ĩvinda ya kelĩ, ĩkĩngũlya, Wĩona kyaũ? Nakwa nasya, Nĩngwona kĩteve kĩkĩtheũka: nĩkyonanĩtye kanyw’a wakyo kuma ngalĩ ya ĩũlũ.'),
('kam', 'JER', 1, 14, 'Nĩvo ĩndĩ Yeova wambĩie, Kuma ngalĩ ya ĩũlũ ũthũku ũkamaumĩlĩla onthe ala matũaa ĩ nthĩ.'),
('kam', 'JER', 1, 15, 'Nũndũ, sisya, ngeeta mĩvĩa yonthe ya mosumbĩ ma ngalĩ ya ĩũlũ, easya ũu Yeova; na ĩkooka, na kĩla ũmwe wayo ũkaũngamya kĩvĩla kyaw’o kya ũsumbĩ vandũ va ũlikĩla mbingĩlonĩ sya Yelusaleme, na vakuvĩ na maũvai onthe mayo ngalĩ syonthe, na vakuvĩ na ndũa syonthe sya Yuta.'),
('kam', 'JER', 1, 16, 'Na ngamatavya motw’ĩo makwa kwondũ wa ũthũku woo w’onthe, nũndũ nĩmandiĩte, na kwitoeesya ngai ingĩ ũvani, na kũthaitha mawĩa ma moko moo ene.'),
('kam', 'JER', 1, 17, 'Kwondũ wa ũu ĩvotoe kĩnyunyu kyaku, noyũkĩla, ũneene nao w’onthe ũla ngũkwĩaĩa: ndũkatevw’e nĩmo, ndikese ũkũteaesya mbee woo.'),
('kam', 'JER', 1, 18, 'Nũndũ, sisya, ũmũnthĩ nĩnakũtw’ĩkĩthya ndũa mbiie, na kĩtuĩ kya kĩaa, na maũvai ma ũthuku, ĩũlũ wa nthĩ yonthe, na ĩũlũ wa asumbĩ ma Yuta, na ĩũlũ wa anene mayo me mbee ũsumbĩnĩ, na ĩũlũ wa athembi mayo, na ĩũlũ wa andũ ma ĩ nthĩ.'),
('kam', 'JER', 1, 19, 'Nao makokita naku; ĩndĩ maikakũtonya: nũndũ nyie nĩ vamwe naku kũũvonokya, easya ũu Yeova.'),
('kam', 'JER', 2, 1, 'Na ndeto ya Yeova yambũkĩa, ĩkĩmbĩa,'),
('kam', 'JER', 2, 2, 'Enda, ũneene na wasya mũnene matũnĩ ma Yelusaleme, ũkyasya, Ũũ nĩw’o Yeova ũnũkwasya, Nĩngũlilikana ũndũ waku ũseo wa wana waku, wendo wa kwĩvaw’a kwaku; ũndũ wangatĩĩie weũnĩ, nthĩ ĩla ĩtaĩ mbande.'),
('kam', 'JER', 2, 3, 'Isilaeli aĩ mũtheu kwa Yeova, mosyao ma mbee ma wingĩvo wake: onthe ala makamũya makatalwa avĩtan’ya; ũthũku ũkamokĩa, easya ũu Yeova.'),
('kam', 'JER', 2, 4, 'Ĩw’ai ndeto ya Yeova, inyw’ĩ nyũmba ya Yakovo, na mĩvĩa yonthe ya nyũmba ya Isilaeli:'),
('kam', 'JER', 2, 5, 'Ũũ nĩw’o Yeova ũnũkwasya, Nĩ ũndũ wĩva ũla ũte ũlũngalu aaĩthe menyu moonie nthĩnĩ wakwa, ũndũ maendie kũasa nakwa, na kũatĩĩa maũndũ ma mana, na matw’ĩkĩte mate kĩĩĩ?'),
('kam', 'JER', 2, 6, 'O na matyaakũlya, Aĩva Yeova ũla watumisye nthĩ ya Misili, ũla watũtongoesye weũnĩ, nthĩ yĩ malata na maima, nthĩ yĩ mũnyao na kyuu kya kĩkw’ũ, nthĩ ĩla ĩtavĩtĩlwa nĩ mũndũ, na ĩla ĩtatũwa nĩ andũ?'),
('kam', 'JER', 2, 7, 'Nakwa namũete nthĩ yĩ lĩu mwingĩ, mũye ũsyao wayo na ũseo wayo; ĩndĩ yĩla mwalikile, mwamĩthũkya nthĩ yakwa, na mwatw’ĩkĩthya ũtiĩwa wakwa ũthatyo.'),
('kam', 'JER', 2, 8, 'Athembi matyaakũlya, Yeova aĩva? Na ala mekalaa na ĩla mĩao matyambĩsĩ: na asumbĩki nao mambĩtanĩsya, na athani mathana na syĩtwa ya Mbaali, na maatĩĩa maũndũ ala mataunaa.'),
('kam', 'JER', 2, 9, 'Kwondũ wa ũu ngatetan’ya nenyu, easya Yeova, na ngatetan’ya na esũkũũu.'),
('kam', 'JER', 2, 10, 'Ĩndĩ ingai mũende ithama sya Kitimu, mwone; na tũmanai Ketali, mũkĩsũanĩa mũno; mũmanye ethĩwa kwaĩ ũndũ wailyĩ ũu.'),
('kam', 'JER', 2, 11, 'Kwĩ mbaĩ yaakũan’ya ngai syayo, o na kaũ ti ngai? Ĩndĩ andũ makwa nĩmakũanisye ũtheu woo na kĩla kĩtauna.'),
('kam', 'JER', 2, 12, 'Seng’ai, inyw’ĩ matu, kwondũ wa ũndũ ũsu, na kĩai mũno, valaanĩkai, easya ũu Yeova.'),
('kam', 'JER', 2, 13, 'Nũndũ andũ makwa nĩmekĩte mothũku elĩ: nĩmandiĩte nyie, nthongo ya manzĩ ma thayũ, na nĩmeyakĩĩte ithima, ithima mbatũku, ĩla itatonya kwĩkalya manzĩ.'),
('kam', 'JER', 2, 14, 'Isilaeli nĩ mũthũkũmi? Nĩ ngombo ĩla yasyaĩwe kwoo? Atw’ĩkĩte mũtavo nĩkĩ?'),
('kam', 'JER', 2, 15, 'Mĩnyambũ ya mũika nĩyamũtundumĩe, na kĩlumo kĩnene; na nĩyanangĩte nthĩ yake: ndũa syake nĩ mbĩvye, iti mũndũ.'),
('kam', 'JER', 2, 16, 'O na andũ ma ndũa sya Memivisi na Tavanesi nĩmakũnĩte lolotya wa mũtwe waku.'),
('kam', 'JER', 2, 17, 'Tuue weeyĩkie ũndũ ũsu, nũndũ nĩwatiie Yeova Ngai waku, yĩla wakũtongoesye nzĩanĩ?'),
('kam', 'JER', 2, 18, 'Na yu wĩĩka ata nzĩanĩ ĩsu yĩendete Misili, kũnyw’a manzĩ ma Sioli? Kana wĩĩka ata nzĩanĩ yĩendete Asuli, kũnyw’a manzĩ ma ũla Ũsĩ?'),
('kam', 'JER', 2, 19, 'Ũthũku waku ũkakũsilĩla, na kũsyoka na ĩtina kwaku kũkakũkan’ya: manya ĩndĩ wone nĩ ũndũ ũthũku na wĩ ũũ, ũmũtiĩte Yeova Ngai waku, na kũngĩa kũi nthĩnĩ waku, easya ũu Mwĩaĩi, Yeova wa nguthu.'),
('kam', 'JER', 2, 20, 'Nũndũ kuma tene nĩwatũlile ĩsoki yaku, na kũtw’a syĩndũ syaku sya kwovwa nasyo; na wasya, Ndikathũkũma; nũndũ kĩla kalĩmanĩ katũlu na ĩtina wa kĩla mũtĩ mwĩũ nĩweekunamisye, ũkĩka ũmalwaya.'),
('kam', 'JER', 2, 21, 'Ĩndĩ nyie nakũvandie mũsavivũ mũseo, mbeũ ya w’o ki: ũalyũkĩte ata ĩndĩ ũtw’ĩke kwakwa mbonge ite nzeo sya mũsavivũ wa kũngĩ?'),
('kam', 'JER', 2, 22, 'Nũndũ o na ethĩwa wĩthamba na ĩati, na kwosa savuni mwingĩ, ũthũku waku nũandĩkĩtwe mbee wakwa, easya ũu Mwĩaĩi Yeova.'),
('kam', 'JER', 2, 23, 'Ũtonya ata kwasya, Ndivukĩtw’e, ndyaaatĩĩa Mbaalimu? Sisya nzĩa yaku mwandanĩ, ũmanye ũndũ wĩkĩte: wĩ ngamĩle ya mũika ĩendaa mĩtũkĩ ĩkĩenda nzĩanĩ syayo;'),
('kam', 'JER', 2, 24, 'ĩng’oi ya kĩthekanĩ yĩsĩ weũ, ĩla yĩvũngaa kĩseve yĩla yĩ na mũmeo; ĩvinda yayo nũũ ũtonya kũyĩsiĩĩa? Onthe ala mayĩmanthaa maikenosya; mweinĩ wayo makayona.'),
('kam', 'JER', 2, 25, 'Siĩĩa kũũ kwaku kũikalee kwĩthĩwa na kĩatũ, na mũmeo waku ndũkethĩwe na waũnĩ. Ĩndĩ we waisye, Nĩ mana; aiee, nũndũ nĩnĩmendete aeni, na ngamaatĩĩaa.'),
('kam', 'JER', 2, 26, 'O tondũ kĩng’ei kĩsonokaa kyakwatwa, now’o nyũmba ya Isilaeli ĩsonokaa; mo, asumbĩ moo, anene moo me mbee ũsumbĩnĩ, na athembi moo, na athani moo;'),
('kam', 'JER', 2, 27, 'ala matavasya kĩtina kya mũtĩ, Nue nau wakwa; na ĩvia, Nue wanzyaie: nũndũ nĩmambonetye mĩongo, na ti ũthyũ; ĩndĩ ĩvinda ya thĩna woo makasya, Ũkĩla, ũtũtangĩĩe.'),
('kam', 'JER', 2, 28, 'Ĩndĩ ngai syaku ila weeseũvĩsye iĩva? Syũkĩle, ethĩwa nitonya ũkũtangĩĩa ĩvinda ya thĩna waku: nũndũ ngai syaku syĩanene na ũtalo wa ndũa syaku, we Yuta.'),
('kam', 'JER', 2, 29, 'Mwĩtetan’ya nakwa nĩkĩ? Mũmbĩtanĩĩtye inyw’onthe, easya ũu Yeova.'),
('kam', 'JER', 2, 30, 'Nĩkũnĩte syana syenyu mana; nũndũ ityaaĩtĩkĩla kũkanw’a: ũvyũ wenyu nũminĩte athani menyu, o tondũ mũnyambũ wanangaa.'),
('kam', 'JER', 2, 31, 'We nzyawa, sisya ndeto ya Yeova. Nyie naĩ weũ kwa Isilaeli? Kana naĩ nthĩ yĩ kĩvindu kya ngokomi? Nũndũ wa kĩ andũ makwa mekwasya, Nĩtwatw’a mĩkwa; tũikakũsyokea ĩngĩ?'),
('kam', 'JER', 2, 32, 'Mwĩitu mũtheu nũtonya kũlwa nĩ mawanake make, kana mũtwawa nĩ ngũa syake? Ĩndĩ andũ makwa nĩmolĩtwe ninyie mĩthenya ĩtatalĩka.'),
('kam', 'JER', 2, 33, 'Ko nũseũvasya mũendele waku ũmanthe wendo! Kwondũ wa ũu o na aka athũku nũmamanyĩthĩtye mĩendele yaku.'),
('kam', 'JER', 2, 34, 'O na ngũanĩ syaku nĩkwonekete nthakame ya andũ ngya mate na ĩvĩtyo: ndinamyona ũndũ wa kũmantha mũno; ĩndĩ o ĩũlũ wa ii syonthe.'),
('kam', 'JER', 2, 35, 'Ĩndĩ naku wasya, Ndi na ĩvĩtyo; nĩ w’o ũthatu wake nũalyũlĩtwe kuma kwakwa. Sisya, ngakwatya sila naku, nũndũ nũkwasya, Ndinavĩtya.'),
('kam', 'JER', 2, 36, 'Ũendaa kũũ na kũũ ũalyũle nzĩa yaku nĩkĩ? Ũkasonoka ũndũ wa Misili nayo, o tondũ wasonokie ũndũ wa Asuli.'),
('kam', 'JER', 2, 37, 'Kuma kw’o ũkauma, wilĩĩle moko maku mũtwe: nũndũ Yeova nũleete ala wĩkwatasya, na ndũkaathimĩka wĩ namo.'),
('kam', 'JER', 3, 1, 'Nao measya, Ethĩwa mũndũ akaeka mũka wake, nake akauma kwake, na kũtwawa nĩ mũndũ ũngĩ, ũ mũndũ mũũme wa mbee akamũsyokea ĩngĩ? Nthĩ ĩsu ndĩkathũkwa mũno? Ĩndĩ we nĩwĩkĩte ũmalwaya na anyanyau aingĩ, na ĩndĩ nũnzyokea ĩngĩ, easya ũu Yeova.'),
('kam', 'JER', 3, 2, 'Ũngalalya metho maku kũndũ kũtũlu kũthei, wone; nĩ va vala ũtakomewa nakũ? Wailyĩ ũtee wa nzĩa ũmeteele, ta Mwalavu weũnĩ; na nũthũkĩtye nthĩ na ũmalwaya waku na ũthũku waku.'),
('kam', 'JER', 3, 3, 'Kwondũ wa ũu mĩono ya mbua yasiĩĩwa ndĩkaue, na vatyaĩ mbua yasiĩĩwa ndĩkaue, na vatyaĩ mbua ya uũa; ĩndĩ we waĩ na kĩtulya kya ĩlwaya, na walea kũsonoka.'),
('kam', 'JER', 3, 4, 'Kuma yu ũkeengaĩla, ũkyasya, Nau wakwa, nue mũtongoi wa wana wakwa?'),
('kam', 'JER', 3, 5, 'Akeethĩwa na ũthatu tene na tene? Akekala naw’o kũvika mũminũkĩlyo? Sisya, nũneenete na nĩwĩkĩte maũndũ mathũku, na nũvikĩlĩte nzĩa yaku mwene.'),
('kam', 'JER', 3, 6, 'Na ĩngĩ Yeova angũlya mĩthenyanĩ ya mũsumbĩ Yosia, Nĩwoonie ũndũ Isilaeli ũla wasyokie na ĩtina wekie? Nĩwambatie ĩũlũ wa kĩla kĩĩma kĩtũlu na ĩtina wa kĩla mũtĩ mwĩũ, na ku nĩwekĩe ũmalwaya.'),
('kam', 'JER', 3, 7, 'Aminĩte kwĩka maũndũ asu onthe, nyie nasya, Akanzyokea; ĩndĩ ndaasyoka: na mwĩĩtu‐a‐inyia Yuta ũla nzeleke oona ũndũ ũsu.'),
('kam', 'JER', 3, 8, 'Nakwa noona, yĩla, kwondũ wa kĩtumi o kĩĩ kya atĩ Isilaeli ũla wasyokie na ĩtina nĩwĩkĩte ũlaalai, namũekie na kũmũnenga valũa wa kũtaanĩsya, Yuta mwĩĩtu‐a‐inyia ũla nzeleke ndaakĩa; ĩndĩ nake athi na eeka ũmalwaya.'),
('kam', 'JER', 3, 9, 'Na kweethĩwa kwondũ wa ũvũthũ wake wa kwĩka ũlaalai, nthĩ yathũkw’a, nake eeka ũlaalai kwa kũatĩĩa mavia na matina ma mĩtĩ.'),
('kam', 'JER', 3, 10, 'Ĩndĩ o na ũu w’onthe mwĩĩtu‐a‐inyia Yuta ũla nzeleke ndanamba kũnzyokea na ngoo yake yonthe, ĩndĩ no ũkengani, easya ũu Yeova.'),
('kam', 'JER', 3, 11, 'Na Yeova ambĩa, Isilaeli ũla wasyokie na ĩtina nĩwĩyonanĩtye nĩ mũlũngalu kwĩ Yuta ũla nzeleke.'),
('kam', 'JER', 3, 12, 'Enda, ũtavan’ye ndeto ii kwelekela ngalĩ ya ĩũlũ, ũiasya, Syoka, we Isilaeli ũla wasyokie na ĩtina, easya ũu Yeova; ndikakũsisya nĩ mũthatu; nũndũ nĩ wa tei, easya Yeova, ndikekala na ũthatu tene na tene.'),
('kam', 'JER', 3, 13, 'Ĩndĩ umbũla ũthũku waku, kana nĩwamũvĩtanĩsye Yeova Ngai waku, na nĩwanyaĩĩkisye mĩendele yaku ũithi kwa aeni ĩtina wa kĩla mũtĩ mwĩũ na mũtyaaĩthukĩĩsya wasya wakwa, easya ũu Yeova.'),
('kam', 'JER', 3, 14, 'Syokai, inyw’ĩ syana ila mwasyokie na ĩtina, easya ũu Yeova; nũndũ nĩ mũũme wenyu: na ngamwosa inyw’ĩ, ũmwe wa ndũa, na elĩ ma mũvĩa, na ngamũete Saioni'),
('kam', 'JER', 3, 15, 'Na ngamũnenga aĩthi kwĩanana na ngoo yakwa, ala makamũĩthasya ũĩ na ũmanyi.'),
('kam', 'JER', 3, 16, 'Na kũkeethĩwa, mwaingĩva na kwongeleka mwĩ nthĩ, mĩthenya ĩsu, easya Yeova, matikaneena ĩngĩ, Ĩsandũkũ ya ũtianĩo ya Yeova; o na yĩtikethĩwa mosũanĩonĩ; o na matikayĩlilikana; o na matikayĩendea; o na matikayĩseũvya ĩngĩ.'),
('kam', 'JER', 3, 17, 'Ĩvinda yĩu makeeta Yelusaleme kĩvĩla kya ũsumbĩ kya Yeova; na mbaĩ syonthe ikoombanĩw’a vo Yelusaleme, kwondũ wa syĩtwa ya Yeova: o na matikaatĩĩa ĩngĩ ngũlũ sya ngoo yoo nthũku.'),
('kam', 'JER', 3, 18, 'Mĩthenya ĩsu nyũmba ya Yuta ĩkaendan’ya na nyũmba ya Isilaeli, na makakomana kuma nthĩ yĩ ngalĩ ya ĩũlũ kũvika nthĩ ĩla namanengie aaĩthe menyu yĩthĩwe ũtiĩwa.'),
('kam', 'JER', 3, 19, 'Ĩndĩ nasya, Ngakũlikya ata syananĩ, na ũkũnenga nthĩ ya kwendeesya, ũtiĩwa mũseo wa nguthu sya mbaĩ? Na ĩngĩ nasya, Mũkambĩta Nau Wakwa, na mũtikethyũũa na kũeka kũngatĩĩa.'),
('kam', 'JER', 3, 20, 'Nĩ w’o o tondũ kĩveti nzeleke kĩmũtiaa mũũme, o ta ũu nĩmwambĩkie ũseleke, inyw’ĩ nyũmba ya Isilaeli, easya ũu Yeova.'),
('kam', 'JER', 3, 21, 'Wasya nũkwĩw’ĩka kũndũ kũtũlu kũthei, iĩo na mawĩsũvano ma ana ma Isilaeli; nĩkwĩthĩwa nĩmelelũkĩtye mũendele woo, nĩmolĩtwe nĩ Yeova Ngai woo.'),
('kam', 'JER', 3, 22, 'Syokai inyw’ĩ syana ila mwasyokie na ĩtina, ngavosya kũsyoka na ĩtina kwenyu. Sisya, nĩtwakũkĩa; nũndũ nue Yeova Ngai waitũ.'),
('kam', 'JER', 3, 23, 'Nĩ w’o nĩ mana ũtethyo ũla weteelwe kuma tũlĩmanĩ, ĩkomano yĩkĩlonzan’ya yĩ iĩmanĩ: nĩ w’o ũtangĩĩo wa Isilaeli wĩ nthĩnĩ wa Yeova Ngai waitũ.'),
('kam', 'JER', 3, 24, 'Ĩndĩ ũndũ ũsu wĩ nthoni nũminĩte wĩa wa aaĩthe maitũ, kuma wana witũ, ndĩthya syoo sya mbũi na malondu na ndĩthya syoo sya ng’ombe, ana moo na eĩtu moo.'),
('kam', 'JER', 3, 25, 'Tũkomei nthoninĩ sitũ, na kĩthokoo kitũ kĩtũvw’ĩke; nũndũ nĩtwamũvĩtanĩsye Yeova Ngai waitũ, ithyĩ na aaĩthe maitũ, kuma wana witũ kũvika ũmũnthĩ; na tũtyaaĩthukĩĩsya wasya wa Yeova Ngai waitũ.'),
('kam', 'JER', 4, 1, 'Ethĩwa ũkasyoka, we Isilaeli, easya Yeova, ethĩwa ũkanzyokea, na ethĩwa ũkaveta mothatyo maku nĩeke ũmona; nĩvo ĩndĩ ndũkavetwa;'),
('kam', 'JER', 4, 2, 'nĩvo ĩndĩ ũkevĩta na w’o, na sila wa katĩ, na ũlũngalu atĩĩ, O tondũ Yeova wĩ thayũ; na i mbaĩ ikeeathima nthĩnĩ wake, na nthĩnĩ wake ikeekathĩĩa.'),
('kam', 'JER', 4, 3, 'Nũndũ ũũ nĩw’o Yeova ũnũũmea aũme ma Yuta na Yelusaleme, Ĩnzai maei menyu, na mũikavande mĩw’anĩ.'),
('kam', 'JER', 4, 4, 'Ĩyaĩkei mwĩthĩwe ma Yeova, mumye ikonde sya ngoo syenyu, inyw’ĩ aũme ma Yuta na inyw’ĩ ala matwĩe Yelusaleme; ũthilĩku wakwa ndũkese kumĩla ta mwaki, na kwakana ũndũ mũndũ ũtatonya kũũvosya, nũndũ wa ũthũku wa meko menyu.'),
('kam', 'JER', 4, 5, 'Tavan’yai nthĩ ya Yuta, na mũinyaĩĩkĩsya Yelusaleme; mũkyasya, Vuvai soo ĩũlũ wa nthĩ: ũkĩlyai wasya mũnene mũno, mũkyasya, Ũmbanai vamwe, na tũilika ndũanĩ mbiie.'),
('kam', 'JER', 4, 6, 'Ũngamyai kĩvevelo kwelekela Saioni: kĩai mũvonoke, mũtiketeele; nũndũ ngaete ũthũku kuma ngalĩ ya ĩũlũ, na wanangĩko mũnene.'),
('kam', 'JER', 4, 7, 'Mũnyambũ nĩwumĩte kĩthekanĩ kyaw’o, na mwanangi wa mbaĩ; e nzĩanĩ yake, nũminĩte kuma vandũ vake, atw’ĩkĩthye nthĩ yaku nthei, nĩ kana ndũa syaku syĩthĩwe maanzo, ite mũndũ witwĩe.'),
('kam', 'JER', 4, 8, 'Kwondũ wa ũu ĩvotoe makunia, meta na kũkaya; nũndũ ũthatu mwai wa Yeova ndũnaalyũlwa wume kwitũ.'),
('kam', 'JER', 4, 9, 'Na kũkethĩwa mũthenya ũsu, easya Yeova, kana ngoo ya mũsumbĩ ĩkakw’a, na ngoo sya anene me mbee ũsumbĩnĩ; na athembi makaseng’a, na athani makasaanĩw’a.'),
('kam', 'JER', 4, 10, 'Nĩvo ĩndĩ naisye, A! Mwĩaĩi Yeova! Vate ndĩi nũmakengete mũno andũ aa na Yelusaleme, ũkĩmea, Mũkeethĩwa na mũno; ĩndĩ ũvyũ nũvikĩte thayũnĩ.'),
('kam', 'JER', 4, 11, 'Ĩvinda yĩu andũ aa na Yelusaleme makatavw’a atĩĩ, Kĩseve kĩvyũ kuma kũndũ kũtũlu kũthei weũnĩ kwelekela mwĩĩtu wa andũ makwa, ti kya kũũlũkya. Kana kya kũthesya;'),
('kam', 'JER', 4, 12, 'kĩseve kĩnene kuma kũndũ kũu kĩkooka kwondũ wakwa: yu ngamaumĩsya motw’ĩo.'),
('kam', 'JER', 4, 13, 'Sisya, akookĩla ta mathweo, na makasya make ma kaũ makeethĩwa ta kĩlingi: mbalasi syake syĩ mĩtũkĩ kwĩ ndiũ. Woo nĩ witũ! Nũndũ nĩtwaanangwa.'),
('kam', 'JER', 4, 14, 'We Yelusaleme, thambya ngoo yaku ũthũku wume, nĩ kana ũtangĩĩwe. Mosũanĩo maku mathũku makekala nthĩnĩ waku kũvika ĩndĩĩ?'),
('kam', 'JER', 4, 15, 'Nũndũ wasya nũtavanasya kuma Ndani, na kũnyaĩĩkya ũthũku kuma tũlĩmanĩ twa Evalaimu.'),
('kam', 'JER', 4, 16, 'Manyĩthyai i mbaĩ; sisyai, tavanĩsyai Yelusaleme, kana asyaĩĩsya nĩmokĩte kuma nthĩ yĩ kũasa, na kumya wasya woo ĩũlũ wa ndũa sya Yuta.'),
('kam', 'JER', 4, 17, 'O ta asyaĩĩsya ma mũũnda nĩmathyũlũlũkĩte ngalĩ syonthe, nĩkwĩthĩwa nĩwang’endee, easya ũu Yeova.'),
('kam', 'JER', 4, 18, 'Nzĩa yaku na meko maku nĩmakũetee maũndũ aa; ũsu nĩw’o ũthũku waku; nũndũ wĩ ũũ, nũndũ nĩvikĩte ngoonĩ yaku.'),
('kam', 'JER', 4, 19, 'Woo wakwa, woo wakwa! Nĩngwalw’a ngoonĩ yakwa nthĩnĩ; ngoo yakwa nĩkũmbũavũan’ya; nditonya kũvindya; nũndũ nĩwĩw’ĩte, we thayũ wakwa wasya wa soo, mbu ya kaũ.'),
('kam', 'JER', 4, 20, 'Wanangĩko ĩũlũ wa wanangĩko nũtavanaw’a; nũndũ nthĩ yonthe nĩtw’ĩkĩthĩtw’e nthei: maeema makwa nĩmanangĩtwe na kĩthũlũmũko, na ngũa syakwa sya kũtũta kavinda o kau.'),
('kam', 'JER', 4, 21, 'Ngoona kĩvevelo, na kwĩw’a wasya wa soo kũvika ĩndĩĩ?'),
('kam', 'JER', 4, 22, 'Nũndũ andũ makwa nĩ atumanu, matimbĩsĩ; nĩ syana ndumanu, na iti na ũmanyi; syĩ na ũĩ wa kwĩka ũthũku, ĩndĩ iti na ũmanyi wa kwĩka ũseo.'),
('kam', 'JER', 4, 23, 'Nasisya nthĩ, na, kaĩ, yaĩ nthei na ndĩaĩ kĩndũ; na nasisya matu, na matyaĩ na kyeni.'),
('kam', 'JER', 4, 24, 'Nasisya iĩma, na, kaĩ, syatetema, na tũlĩma tw’onthe twathingithanga kũũ na kũũ.'),
('kam', 'JER', 4, 25, 'Nasisya, na, kaĩ, vatyaĩ mũndũ, na nyũnyi syonthe sya yayaya nĩsyakĩie.'),
('kam', 'JER', 4, 26, 'Nasisya, na, kaĩ, mũũnda ũla waĩ na ũsyao watw’ĩkĩte ĩei, na ndũa syonthe syaw’o nĩsyaomboetwe mbee wa ũthyũ wa Yeova, na mbee wa ũthatu wake mwai.'),
('kam', 'JER', 4, 27, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Nthĩ yonthe ĩkeethĩwa nthei; ĩndĩ ndikamamina vyũ.'),
('kam', 'JER', 4, 28, 'Kwondũ wa ũu nthĩ ĩkameta, na matu ĩũlũ makeethĩwa maiũ; nĩkwĩthĩwa nĩneenete ũu, nĩtw’ĩte ũu, na ndinelila, o na ndikethyũũa na kũeka ũndũ ũsu.'),
('kam', 'JER', 4, 29, 'Kĩla ndũa nĩkĩaa kwondũ wa kĩlonzo kya andũ matũlĩte mbalasi, na andũ me na mata; malikaa ithekanĩ, na kwambata ĩũlũ wa mavia: kĩla ndũa nĩ ndie, na vai mũndũ ũtwĩe nthĩnĩ wayo.'),
('kam', 'JER', 4, 30, 'Naku, yĩla wĩtw’ĩkĩthw’a ĩei, ũkeeka ata? O na ethĩwa wĩĩvw’ĩka ngũa ndune mũno, o na ethĩwa wĩĩseũvya na mawanake ma thaavu, o na ethĩwa wĩnenevya metho maku na langi, nũkwĩseũvya mana; endwa maku nĩmeũkũvũthya, nĩmeũmantha thayũ waku.'),
('kam', 'JER', 4, 31, 'Nũndũ nĩneewie wasya ũilyĩ wa mũndũ mũka akyaũnya, woo ũilyĩ wa ũla ũsyaa kana kake ka mbee, wasya wa mwĩĩtu wa Saioni, ũla ũvevũũkaa, na kũtambũũkya moko make, akyasya, Woo nĩ wakwa yu! Nũndũ thayũ wakwa nũũthelekelela mbee wa oaani.'),
('kam', 'JER', 5, 1, 'Sembai kũũ na kũũ nzĩanĩ nene sya Yelusaleme, mwone yu, na kũmanya, na kũmantha kũndũnĩ kũla kwaamu kwayo, ethĩwa mũtonya kwona mũndũ, ethĩwa ve ũmwe ũla wĩkaa ũlũngalu, ũla ũmanthaa w’o; na ngamĩeka.'),
('kam', 'JER', 5, 2, 'O na ethĩwa measya, O tondũ Yeova wĩ thayũ; vate ndĩi meĩvĩta ũvũngũ.'),
('kam', 'JER', 5, 3, 'Ame Yeova, metho maku matiũsisya ũ w’o? Nũmakũnĩte, ĩndĩ matyaaĩw’a woo; nũmanangĩte, ĩndĩ nĩmaleete kũkanw’a: nĩmomĩtye mothyũ moo kũvĩtũka ĩvia; nĩmaleete kũsyoka.'),
('kam', 'JER', 5, 4, 'Nĩvo ĩndĩ naisye, Vate ndĩi aa nĩ ngya; nĩ atumanu; nũndũ matyĩsĩ nzĩa ya Yeova, kana mĩao ya Ngai woo:'),
('kam', 'JER', 5, 5, 'ngathi vala ve andũ anene, na kũneena nao; nũndũ asu nĩmesĩ nzĩa ya Yeova, na mĩao ya Ngai woo. Ĩndĩ aa na ngoo ĩmwe nĩmatũlĩte ĩsoki, na kũtw’a syĩndũ movetwe nasyo.'),
('kam', 'JER', 5, 6, 'Kwondũ wa ũu mũnyambũ ũla wĩuma mũtitũnĩ ũkamoaa, nzũi ĩla yũkaa mawĩoo ĩkamamina, ngo ĩkooveesya ndũanĩ syoo; kĩla mũndũ ũla wĩumaala akatilangwa ilungu; nĩkwĩthĩwa mavĩtyo moo nĩ maingĩ, na kũsyoka na ĩtina kwoo nĩkwongelekile.'),
('kam', 'JER', 5, 7, 'Ndonya ata ũkũekea? Ana maku nĩmandiĩte, na kwĩvĩta na isu ite ngai. Yĩla namavũnĩthisye na lĩu, mekaa ũlaalai, na kũmbana vamwe nguthu nguthu nyũmbanĩ sya malwaya;'),
('kam', 'JER', 5, 8, 'mailyĩ mbalasi iĩthĩtw’e ikavũna ikyanganga; kĩla ũmwe aimwanĩsya mũka wa mũtũi wake.'),
('kam', 'JER', 5, 9, 'Ndikasilĩla nũndũ wa maũndũ asu? Easya ũu Yeova; na thayũ wakwa ndũkeĩvanĩsya mbaĩnĩ ĩilyĩ ĩno?'),
('kam', 'JER', 5, 10, 'Ambatai maũvainĩ mayo, na kwananga; ĩndĩ mũikamĩmine vyũ: vetai mbonge syayo; nũndũ ti sya Yeova.'),
('kam', 'JER', 5, 11, 'Nũndũ nyũmba ya Ĩsilaeli na nyũmba ya Yuta nĩsyambĩkie ũseleke, easya ũu Yeova.'),
('kam', 'JER', 5, 12, 'Nĩmamũkaĩĩte Yeova, na kwasya, Ti we: o na ũthũku ndũkatũkĩa; o na tũikona ũvyũ kana yũa:'),
('kam', 'JER', 5, 13, 'na athani makatw’ĩka kĩseve, na ndeto iti nthĩnĩ woo: ũu nĩw’o makekwa.'),
('kam', 'JER', 5, 14, 'Kwondũ wa ũu Yeova Ngai wa nguthu, easya atĩĩ, Nũndũ nĩmũneenaa ndeto ĩno, sisya, ngatw’ĩkĩthya ndeto syakwa mwaki kanyw’anĩ waku, na andũ aa ngamatw’ĩkĩthya ngũ, na ũkamamina.'),
('kam', 'JER', 5, 15, 'Sisya, ngamũetee mbaĩ kuma kũasa, inyw’ĩ nyũmba ya Isilaeli, easya ũu Yeova: nĩ mbaĩ yĩ vinya, nĩ mbaĩ ya tene, mbaĩ ĩla ũtesĩ kĩthyomo kyayo, o na ũtamanya ũndũ ĩkwasya.'),
('kam', 'JER', 5, 16, 'Thyaka woo nĩ mbũa mbingũe, onthe nĩ ngũmbaũ.'),
('kam', 'JER', 5, 17, 'Na makaya ngetha yaku, na lĩu waku, ũla ana maku na eĩtu maku maĩle kũya; makaya ndĩthya syaku sya mbũi na malondu na ndĩthya syaku sya ng’ombe; makaya mĩsavivũ yaku na mĩkũyũ yaku; makaomboanga na ũvyũ ndũa syaku mbiie, ila wĩkwatasya.'),
('kam', 'JER', 5, 18, 'Ĩndĩ o na mĩthenya ĩsu ndikamũmina vyũ, easya ũu Yeova.'),
('kam', 'JER', 5, 19, 'Na kũkeethĩwa, yĩla mwĩasya, Nũndũ wa kĩ Yeova Ngai waitũ watwĩkie maũndũ aa onthe? Nĩvo ũkamea, O tondũ mwandiie, na kũthũkũmĩa ngai ngeni nthĩ yenyu, o ta ũu mũkathũkũmĩa aeni nthĩ ĩte yenyu.'),
('kam', 'JER', 5, 20, 'Tavan’yai ndeto ii nyũmbanĩ ya Yakovo, na mũinyaĩĩkya nthĩnĩ wa Yuta, mũkyasya,'),
('kam', 'JER', 5, 21, 'Yu ĩw’ai ũu, inyw’ĩ andũ atumanu, mũte na ũmanyi; ala mwĩ na metho, na mũtyonaa; ala mwĩ na matũ na mũtyĩw’aa:'),
('kam', 'JER', 5, 22, 'Mũtingĩa? Easya Yeova: mũtitetema mbee wakwa, nyie ũla naiie kĩthangathĩ kĩthĩwe mũvaka wa ũkanga, ũndũ ũtatonya kũkĩla, ũtw’ĩo wa tene na tene? O na ethĩwa itulumo syaw’o niĩyũkĩlangya, ititonya kũkĩlya vinya; o na ethĩwa niũlitũka ititonya kũkĩla.'),
('kam', 'JER', 5, 23, 'Ĩndĩ andũ aa me na ngoo ya ũlei na ũng’endu; nĩmang’endeie na mathi.'),
('kam', 'JER', 5, 24, 'O na matineenaa ngoonĩ syoo, Yu tũmũkĩe Yeova Ngai waitũ, ũla uasya mbua, ĩla ya nthwa na ya uũa, ĩvinda yayo; ũla wiaa kwondũ witũ syumwa ila itw’ĩtwe sya ngetha.'),
('kam', 'JER', 5, 25, 'Mothũku menyu nĩmaalyũlĩte maũndũ asu, na naĩ syenyu nĩsyamũsiĩĩe ũseo.'),
('kam', 'JER', 5, 26, 'Nũndũ andũnĩ makwa nĩvekwoneka andũ athũku: nĩmekwoveesya, o tondũ asyĩmi ma nyũnyi moveeasya; nĩmeũtea kĩtei, na maikwatya andũ.'),
('kam', 'JER', 5, 27, 'O tondũ kyũũ kyusũawa nyũnyi, now’o nyũmba syoo syusũĩtw’e ũkengani: kwondũ wa ũu nĩmatw’ĩkĩte anene, namakathua.'),
('kam', 'JER', 5, 28, 'Nĩmanoete mũno, na makatendea: ĩĩ, nĩmathonokete na kwĩka meko mathũku; maimateteaa ala makw’ĩĩwe nĩ aaĩthe, nĩ kana maunĩke; na maimatw’ĩĩaa ala athĩni ũndũ ũmaĩle.'),
('kam', 'JER', 5, 29, 'Ndikasilĩla ũndũ wa maũndũ asu? Easya ũu Yeova; thayũ wakwa ndũkeĩvanĩsya mbaĩnĩ ĩilyĩ ĩno?'),
('kam', 'JER', 5, 30, 'Ũndũ wa ũseng’ya na wa kũtĩsya nĩweekĩkie nthĩ ĩno:'),
('kam', 'JER', 5, 31, 'athani nĩmathanaa ũvũngũ, na athembi nĩmasumbĩkaa me mokonĩ moo; na andũ makwa nĩmendaa ũu: na mũminũkĩlyo mũkeeka ata?'),
('kam', 'JER', 6, 1, 'Indũkai, inyw’ĩ syana sya Mbenyamini, mume Yelusaleme, na mũivuvĩa soo ndũanĩ ya Tekoa, na kũkĩlya kĩvevelo ĩũlũ wa Mbethi‐akelemu; nũndũ ũthũku nũũsisya kuma ngalĩ ya ĩũlũ, na wanangĩko mũnene.'),
('kam', 'JER', 6, 2, 'Mwĩĩtu wa Saioni, ũla mũmbe nesa na mwanake, ngaveta.'),
('kam', 'JER', 6, 3, 'Aĩthi me na ndĩthya syoo sya mbũi na malondu makooka vala ũĩ; makamba maeema moo makĩmũthyũlũlũka ngalĩ syonthe; makaĩsĩaa kĩla ũmwe vala ũĩ.'),
('kam', 'JER', 6, 4, 'Ĩyũmbany’ei kũkita nake; ũkĩlai, twambate syũa yaũngama. Woo nĩ witũ! Nũndũ mũthenya nũũthela, nũndũ myuunyĩ ĩ ya wĩoo nĩyĩkootete.'),
('kam', 'JER', 6, 5, 'Ũkĩlai twambate ũtukũ, tũkanange nyũmba syake mbanakavye.'),
('kam', 'JER', 6, 6, 'Nũndũ ũũ nĩw’o Yeova wa nguthu ũneenete, Temai mĩtĩ, myũmbĩĩe Yelusaleme kĩvumbu: ĩsu nĩyo ndũa ya kũsilĩlwa; nĩyusũĩte mothĩn’yo ki nthĩnĩ wayo.'),
('kam', 'JER', 6, 7, 'O tondũ kĩthima kyumasya manzĩ makyo, o ta ũu ndũa ĩsu nĩvulutasya ũthũku wayo: ũng’endu na wanangĩko nikwĩw’ĩka nthĩnĩ wayo; mowau na mawũkite me mbee wakwa mavinda onthe.'),
('kam', 'JER', 6, 8, 'Manyĩw’a, we Yelusaleme, ngoo yakwa ndĩkese kũtaanĩsya naku; ndikese ũkũtw’ĩkĩthya nthi, nthĩ ĩtatwĩe andũ.'),
('kam', 'JER', 6, 9, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Makeethĩan’ya vyũ ũtialo wa Isilaeli ta mũsavivũ: tũnga kw’oko kwaku ikavũnĩ ta mũtwi wa nzavivũ.'),
('kam', 'JER', 6, 10, 'Nganeena naũ na kumya ũkũsĩ, nĩ kana mew’e? Sisya, matũ moo ti maĩke, na maitonya kwĩw’a: sisya, ndeto ya Yeova nĩyatw’ĩkie kwoo ya kũvũthw’a; maiũmĩtanĩa.'),
('kam', 'JER', 6, 11, 'Kwondũ wa ũu nĩnusũĩtwe nĩ ũthilĩku wa Yeova; nĩ na mĩnoo ũndũ wa kwĩsiĩĩa: wonosye syananĩ syĩ nzĩanĩ nene, na ũmbanonĩ wa anake me vamwe; nũndũ o na mũũme vamwe na mũka makooswa, ũla mũkũũ vamwe na ũla mũtumĩu mũno.'),
('kam', 'JER', 6, 12, 'Na nyũmba syoo ikeethĩwa sya angĩ, mĩũnda yoo na iveti syoo vamwe; nũndũ ngamatambũũkĩsya andũ ala matwĩe ĩ nthĩ kw’oko kwakwa, easya ũu Yeova.'),
('kam', 'JER', 6, 13, 'Nũndũ kuma ũla mũnini woo kũvika ũla mũnene woo kĩla ũmwe nũatĩĩaa ĩtomo; na kuma mwathani kũvika mũthembi kĩla ũmwe nũkenganaa.'),
('kam', 'JER', 6, 14, 'Nĩmavoisye vanini ĩkũna ya andũ makwa, makyasya, Mũuo, mũuo; yĩla vate mũuo.'),
('kam', 'JER', 6, 15, 'Nĩmasonokie yĩla meekie ũthatyo? Aiee, matyaasonoka nongi, o na nthoni sya mothyũ ityaoneka: kwondũ wa ũu makavalũka katĩ wa ala mavalũkaa; ĩvinda yĩla ngamasilĩla makavalũkw’a nthĩ, easya ũu Yeova.'),
('kam', 'JER', 6, 16, 'Ũũ nĩw’o Yeova ũnũkwasya, Ũngamai nzĩanĩ mwone, na mũikũlya nzĩa sya tene, vala ve nzĩa nzeo; na mũienda nayo, na mũkoonea ngoo syenyu ũthũmũo: ĩndĩ masya, Tũtikaenda nayo.'),
('kam', 'JER', 6, 17, 'Nakwa nĩnamwiĩe asyaĩĩsya, ngyasya, Ĩthukĩĩsyei wasya wa soo; ĩndĩ masya, Tũtikethukĩĩsya.'),
('kam', 'JER', 6, 18, 'Kwondũ wa ũu ĩw’ai, inyw’ĩ mbaĩ, na mũimanya, inyw’ĩ ũmbano, kĩla kĩ katĩ woo.'),
('kam', 'JER', 6, 19, 'Ĩw’a, we nthĩ: sisya, ngamaetee andũ aa ũthũku, o ũsyao wa mosũanĩo moo, nĩkwĩthĩwa matyaaĩthukĩĩsya ndeto syakwa; na mĩao yakwa nĩmamĩleile.'),
('kam', 'JER', 6, 20, 'Nĩ ũndũ wa kĩ ũvumba nũũetwe kwakwa kuma Sieva, na ithua kuma nthĩ yĩ kũasa mũno? Nthembo syenyu sya kũvĩvw’a itikwĩtĩkĩlwa, o na nthembo syenyu sya kũtonywa itiũmbendeesya.'),
('kam', 'JER', 6, 21, 'Kwondũ wa ũu Yeova easya atĩĩ, Sisya, ngaia molulutĩkyo mbee wa andũ aa; na aaĩthe na ana vamwe makalulutĩkw’a nĩmo; mũtũi na mũnyanyae makaaa.'),
('kam', 'JER', 6, 22, 'Ũũ nĩw’o Yeova ũnũkwasya, Sisya, ũko wa andũ nĩwũkĩte kuma nthĩ ya ngalĩ ya ĩũlũ; na mbaĩ nene ĩkookĩlw’a kuma itulunĩ sya nthĩ.'),
('kam', 'JER', 6, 23, 'Nao makwete mata na matumo; nĩ ai, na mati na tei; wasya woo nũlitũka ta ũkanga, na matũlĩte mbalasi, kĩla ũmwe nĩwĩtaũĩtye, ta mũndũ wa kaũ, kũkita naku, we mwĩĩtu wa Saioni.'),
('kam', 'JER', 6, 24, 'Nĩtwĩw’ĩte ĩsyũ ya ũvoo ũsu; moko maitũ nĩmaleelete: thĩna nũtũkwete, na woo ta wa mũndũ mũka akyaũnya.'),
('kam', 'JER', 6, 25, 'Mũtikaume mũende mũũndanĩ, kana kũtambũka nzĩanĩ; nũndũ ũvyũ wa mũmaitha, na motĩsyo, syĩ ngalĩ syonthe.'),
('kam', 'JER', 6, 26, 'We mwĩĩtu wa andũ makwa, ĩvotoe makunia, na kwĩyalalya mũunĩ: meta ta ũũmetea mwana e ũmwe; kĩĩo kĩnene kĩ woo; nũndũ mwanangi akatũkĩa na kĩthũlũmũko.'),
('kam', 'JER', 6, 27, 'Nĩngũtw’ĩte wĩthĩwe mwako mũtũlu wa mũnyoolo na ngome andũnĩ makwa; nĩ kana ũmanye na kũtata nzĩa yoo.'),
('kam', 'JER', 6, 28, 'Asu onthe nĩ alei athũku, ala maendaa makĩsukana; nao nĩ ũthuku na kĩaa: onthe nĩmekaa ũthũku.'),
('kam', 'JER', 6, 29, 'Mua nũuutaa na vinya; ĩvulũ nĩyĩvĩvaw’a na mwaki: nĩ mana kwoo kũendeea na wĩa wa kũthesya; nũndũ athũku matiũvetwa.'),
('kam', 'JER', 6, 30, 'Andũ makameta masyũlyo ma vetha, nũndũ Yeova nũmaleete.'),
('kam', 'JER', 7, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, ĩkĩmwĩa,'),
('kam', 'JER', 7, 2, 'Ũngama mbingĩlonĩ ya nyũmba ya Yeova, ũtavanĩsye vo ndeto ĩno, wasye, Ĩw’ai ndeto ya Yeova, inyw’onthe ma Yuta, ala mũvotelaa mbingĩlonĩ ii mũthaithe Yeova.'),
('kam', 'JER', 7, 3, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, Lũngalyai mĩendele yenyu o na meko menyu, na ngamwĩkalya vandũ vaa.'),
('kam', 'JER', 7, 4, 'Mũtikaĩkĩĩe ndeto sya ũvũngũ, mũkyasya, Ĩkalũ ya Yeova, ĩkalũ ya Yeova, ĩkalũ ya Yeova, nĩ yĩĩ.'),
('kam', 'JER', 7, 5, 'Nũndũ ethĩwa mũkalũngalya vyũ mĩendele yenyu o na meko menyu; ethĩwa mũkasilanasya w’o mũndũ na mũtũi wake,'),
('kam', 'JER', 7, 6, 'ethĩwa mũtikathĩn’ya mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, na mũtiketĩkya nthakame ĩte na ĩvĩtyo vandũ vaa, kana kũatĩĩa ngai ingĩ ila imũnengae wasyo:'),
('kam', 'JER', 7, 7, 'nĩvo ĩndĩ ngamwĩkalya vandũ vaa, nthĩ ĩla namanengie aaĩthe menyu, kuma tene o na kũvika tene na tene.'),
('kam', 'JER', 7, 8, 'Sisyai, nĩmwĩkwatĩtye ndeto sya ũvũngũ, ila itatonya kũuna.'),
('kam', 'JER', 7, 9, 'Mũkooyaa, na kũaaa, na kũlaalaaa, na kwĩvĩtaa movũngũ, na kũmũtoeeasya Mbaali ũvani, na kũatĩĩaa ngaĩ ingĩ ila mũtaamanya,'),
('kam', 'JER', 7, 10, 'na ĩndĩ mũyũka na kũũngama mbee wakwa nyũmbani ĩno, ĩla yĩtanĩaw’a na syĩtwa yakwa, na kwasya, Ithyĩ twĩ avonoku; nĩ kana mwĩke mothatyo aa onthe?'),
('kam', 'JER', 7, 11, 'Nyũmba ĩno ĩla yĩtanĩaw’a na syĩtwa yakwa, nĩyatw’ĩkie ngunga ya avutani methonĩ menyu? Sisya, nyie, o nyie, nĩnonete ũu, easya ũu Yeova.'),
('kam', 'JER', 7, 12, 'Ĩndĩ yu endai vandũ vakwa vala vaĩ kũu Silo, vala nekalilye syĩtwa yakwa mbee, mwone ũndũ navekie kwondũ wa ũthũku wa andũ makwa Isilaeli.'),
('kam', 'JER', 7, 13, 'Na yu, nĩkwĩthĩwa nĩmwĩkĩte maũndũ aa onthe, easya Yeova, na naneena nenyu, ngyũkĩla tene na ngĩneena, ĩndĩ mũtyaaĩw’a; nanamwĩta, ĩndĩ mũtyaambĩtĩka:'),
('kam', 'JER', 7, 14, 'kwondũ wa ũu, o tondũ neekie Silo now’o ngamĩka nyũmba ĩla yĩtanĩaw’a na syĩtwa yakwa, ĩla mwĩkwatĩtye, na vandũ vala namũnengie inyw’ĩ na aaĩthe menyu.'),
('kam', 'JER', 7, 15, 'Na ngamũlũngya nĩeke ũmwona, o tondũ namalũngilye ana‐a‐au onthe, o ũsyao w’onthe wa Evalaimu.'),
('kam', 'JER', 7, 16, 'Kwondũ wa ũu ndũkamavoyee andũ aa, o na ndũkaokĩlye kĩĩo kana mboya kwondũ woo, o na ndũkaambĩsũve; nũndũ ndikakwĩw’a.'),
('kam', 'JER', 7, 17, 'Ndũkwona ũndũ mekaa ndũanĩ sya Yuta na nzĩanĩ nene sya Yelusaleme?'),
('kam', 'JER', 7, 18, 'Syana niuna ngũ, na aaĩthe mavuva mwaki, na aka meũmba ngũmbwa, mamũseũvĩsye mũsumbĩ mũndũ mũka wa ĩtunĩ tũmũtũ, na kwĩtĩa ngai ingĩ nthembo sya kũnyuwa, nĩ kana manthatye.'),
('kam', 'JER', 7, 19, 'Nĩmeũnthatya? Ekũlya ũu Yeova; matikwĩthatya ene, mothyũ moo methĩwe na nthonĩ?'),
('kam', 'JER', 7, 20, 'Kwondũ wa ũu Mwĩaĩi Yeova easya atĩĩ: Sisya, ũthatu wakwa, na ũthilĩku wakwa ũkoonow’a vandũ vaa, andũnĩ, na nyamũnĩ, na mĩtĩnĩ ya mũũnda, na ũsyaonĩ wa nthĩ; na ũkakana, na ndũkavoeka.'),
('kam', 'JER', 7, 21, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Vulan’yai nthembo syenyu sya kũvĩvw’a vamwe na nthembo syenyu sya kũtonywa, mũye nyama.'),
('kam', 'JER', 7, 22, 'Nũndũ ndyaaneena na aaĩthe menyu, kana kũmeaĩa mũthenya ũla namaumisye nthĩ ya Misili, ũndũ wa nthembo sya kũvĩvw’a kana nthembo sya kũtonywa:'),
('kam', 'JER', 7, 23, 'ĩndĩ nameaĩe ũndũ ũũ, ngyasya, Ĩthukĩĩsyei wasya wakwa, na ngeethĩwa Ngai wenyu, na mũkeethĩwa andũ makwa; na kinyaai nzĩanĩ yonthe ĩla ngũmwĩaĩa, nĩ kana kwĩthĩwe ũseo kwenyu.'),
('kam', 'JER', 7, 24, 'Ĩndĩ matyaaĩthukĩĩsya, kana kũtea matũ moo, ĩndĩ nĩmakinyaa motaonĩ moo ene, makĩatĩĩa ngũlũ sya ngoo syoo nthũku, na masyoka na ĩtina, na matyaaendeea mbee.'),
('kam', 'JER', 7, 25, 'Kuma mũthenya ũla aaĩthe menyu maumie nthĩ ya Misili kũvika ũmũnthĩ, nĩnĩtũmĩte kwenyu athũkũmi makwa onthe athani, kĩla mũthenya ngyũkĩla tene ngĩmatũma:'),
('kam', 'JER', 7, 26, 'ĩndĩ matyaambĩthukĩĩsya, kana kũtea matũ moo, ĩndĩ moomisye ngingo syoo: nĩmeekie naĩ kũvĩtũka aaĩthe moo.'),
('kam', 'JER', 7, 27, 'Naku ũkamatavya ndeto ii syonthe; ĩndĩ matikakwĩthukĩĩsya: naku ũkameta; ĩndĩ matikakwĩtĩka.'),
('kam', 'JER', 7, 28, 'Na ũkamatavya, Ĩno nĩyo mbaĩ ĩtaethukĩĩsya wasya wa Yeova Ngai wayo, kana kwĩtĩkĩla kũkanw’a: w’o nĩwaĩte, na nũvetetwe kũasa na kanyw’a wayo.'),
('kam', 'JER', 7, 29, 'Enza nzw’ĩĩ syaku, we Yelusaleme, wĩkye ĩtheka, noyambĩlĩlya kĩĩo kũndũnĩ kũtũlu kũthei; nũndũ Yeova nũmĩleete na kũmĩtia nzyawa ĩmũthilĩkĩtye.'),
('kam', 'JER', 7, 30, 'Nũndũ ana ma Yuta nĩmekĩte ũla nonaa wĩ ũthũku, easya ũu Yeova: nĩmekĩĩte mothatyo moo nyũmbanĩ ĩla yĩtanĩaw’a na syĩtwa yakwa, mamĩvukye.'),
('kam', 'JER', 7, 31, 'Na nĩmakĩte kũndũ kũtũlu kwa Tovethi, mwandanĩ wa mwana wa Inomu, mavĩvye ana moo na eĩtu moo na mwaki, ũla ndaawĩaa, o na ndwaalika ngoonĩ yakwa.'),
('kam', 'JER', 7, 32, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, vatiketwa Tovethi ĩngĩ, kana Mwanda wa mwana wa Inomu, ĩndĩ vakeetwa Mwanda wa Kũaĩa: nũndũ makenzĩa andũ nthĩ kũu Tovethi, kũvika vathela vandũ va kwĩnzĩa nthĩ.'),
('kam', 'JER', 7, 33, 'Na simba sya andũ aa ikethĩwa lĩu wa nyũnyi sya yayaya, na wa nyamũ sya nthĩ; na vaikethĩwa mũndũ wa kwilũngya.'),
('kam', 'JER', 7, 34, 'Na ĩvinda yĩu ngaekethya wasya wa kũtheka na wasya wa ũtanu, wasya wa mũtwaani na wasya wa mũtwawa, ndũanĩ sya Yuta na nzĩanĩ nene sya Yelusaleme; nũndũ nthĩ ĩkaanangĩka.'),
('kam', 'JER', 8, 1, 'Ĩvinda yĩu, easya Yeova, makavukũa na kumya mbũanĩ syamo, mavĩndĩ ma asumbĩ ma Yuta, na mavĩndĩ ma anene make me mbee ũsumbĩnĩ, na mavĩndĩ ma athembi, na mavĩndĩ ma athani; na mavĩndĩ ma andũ matwĩe Yelusaleme;'),
('kam', 'JER', 8, 2, 'na makamanĩkĩa syũa, na mwei, na mbee wa nguthu yonthe ya ĩtunĩ, ila mendete, na kwithũkũma, na kwiatĩĩa, na kwimantha, na kwĩthaitha: matikakolanw’a, kana kwĩnzĩwa nthĩ, makethĩwa ta vũũ ĩũlũ wa nthĩ.'),
('kam', 'JER', 8, 3, 'Na kĩkw’ũ kũkanyuvwa kũte thayũ nĩ ũtialo w’onthe ũla wĩtiala wa mũvĩa ũũ mũthũku, ala metiala kũndũ kw’onthe kũla namalũngĩlĩĩlye, easya ũu Yeova wa nguthu.'),
('kam', 'JER', 8, 4, 'Na ĩngĩ ũkamatavya, Ũũ nĩw’o Yeova ũnũkwasya: Andũ makavalũka, na maikokĩla ĩngĩ? Mũndũ akaathũka, na ndakasyoka?'),
('kam', 'JER', 8, 5, 'Nũndũ wa kĩ ĩndĩ andũ aa ma Yelusaleme nĩmasyokete na ĩtina, na kũsyoka na ĩtina kwoo nĩ kwa tene na tene? Nĩmalũmasya ũkengani, nĩmaleaa kũsyoka.'),
('kam', 'JER', 8, 6, 'Nethukĩĩsya na neew’a, ĩndĩ matyaaneena w’o: vai mũndũ wĩlila ũndũ wa ũthũku wake, akyasya, Nĩkĩte ata? Kĩla ũmwe nĩwĩthyũũĩe nzĩa yake, ta mbalasi ĩla ĩendaa na vinya kaũnĩ.'),
('kam', 'JER', 8, 7, 'Ĩĩ, ĩsaũ ya yayaya nĩyĩsĩ mavinda mayo ala matw’ĩtwe; na ndumbũ na nthũngũlũlũ na kanyange nililikanaa ĩvinda ya kũsyoka kwasyo; ĩndĩ andũ makwa matyĩsĩ mĩao ya Yeova.'),
('kam', 'JER', 8, 8, 'Mwĩasya ata, Twĩ oĩ, na mĩao ya Yeova yĩ vamwe naitũ? Ĩndĩ, sisya, kĩandĩki kya ũkengani kya ala aandĩki nĩkĩmĩalyũlĩte yĩthĩwe ũvũngũ.'),
('kam', 'JER', 8, 9, 'Andũ oĩ nĩmeũsonokw’a, nĩmeũteva na kũkwatwa: sisya, nĩmaleete ndeto ya Yeova; na nĩ ũĩ mwaũ wĩ nthĩnĩ woo?'),
('kam', 'JER', 8, 10, 'Kwondũ wa ũu nganenga angĩ iveti syoo, na mĩũnda yoo nganenga ala makamĩmesya: nũndũ kĩla mũndũ kuma ũla mũnini o na kũvika ũla mũnene mbee nũatĩĩaa kĩwĩu; kuma mwathani o na kũvika mũthembi kĩla ũmwe nũkenganaa.'),
('kam', 'JER', 8, 11, 'Na nĩmavoisye vanini ĩkũna ya mwĩĩtu wa andũ makwa, makyasya, Mũuo, mũuo, yĩla vate mũuo.'),
('kam', 'JER', 8, 12, 'Nĩmasonokie yĩla meekie ũthatyo? Aiee, matyaasonoka nongi, o na nthoni sya mothyũ ityaoneka: kwondũ wa ũu makavalũka katĩ wa ala mavalũkaa; ĩvinda ya kũsilĩlwa kwoo makavalũkw’a, easya ũu Yeova.'),
('kam', 'JER', 8, 13, 'Ngamamina vyũ, easya ũu Yeova: vatikethĩwa nzavivũ mũsavivũnĩ, kana makũyũ mũkũyũnĩ, na ĩtũ yĩkavova; na syĩndũ ila nĩmanengete ikamaĩa.'),
('kam', 'JER', 8, 14, 'Twĩkalaa tũvindĩtye nĩkĩ? Tũkomanei, tũlike ndũanĩ mbiie, na twĩkale tũvindĩtye kw’o; nũndũ Yeova Ngai waitũ nũtũvindĩthĩtye, na kũtũnenga manzĩ me ũũ ta nyongo tũnyw’e, nĩkwĩthĩwa nĩtũmũvĩtanĩsye Yeova.'),
('kam', 'JER', 8, 15, 'Twamanthaa mũuo, ĩndĩ ũseo ndwaũka; na twamanthaa ĩvinda ya kũvow’a, na, kaĩ, nĩ kũteva!'),
('kam', 'JER', 8, 16, 'Kũtiva kwa mbalasi syake nĩ kwĩw’ĩku kuma Ndani: nthĩ yonthe nĩnĩũtetemw’a nĩ wasya wa kwan’ya wa ila syake syĩ vinya; nũndũ nĩ oku, na nĩmanangĩte nthĩ na kyonthe kĩla kĩ nthĩnĩ wayo; ndũa na ala matwĩe nthĩnĩ wayo.'),
('kam', 'JER', 8, 17, 'Nũndũ, sisya ngatũma nzoka sya syĩmbuva katĩ wenyu, ila itatonya kũvoovw’a; na ikamũũma, easya ũu Yeova.'),
('kam', 'JER', 8, 18, 'A! Kethĩwa ndonya kwĩkiakisya ũndũ wa mawoo! Ngoo yakwa nĩ ndevu nthĩnĩ wakwa.'),
('kam', 'JER', 8, 19, 'Sisya, wasya wa kũĩa kwa mwĩĩtu wa andũ makwa kuma nthĩ yĩ kũasa mũno: Yeova nde Saioni? Mũsumbĩ wayo nde vu nthĩnĩ? Nĩkĩ manthatisye na mĩvw’anano yoo myasũvye, na syĩndũ ngeni sya mana?'),
('kam', 'JER', 8, 20, 'Ngetha nĩ mbĩtu, ĩvinda ya syũa nĩ ĩthelu, na ithyĩ tũtyaatangĩĩwa.'),
('kam', 'JER', 8, 21, 'Kwondũ wa kũkũnwa kwa mwĩĩtu wa andũ makwa nyie nĩnakũniwe: nyie nĩngũmeta; mũtevo nũngwatĩte.'),
('kam', 'JER', 8, 22, 'Vati seli vu Ngileati? Vati mũiiti kw’o? Nĩkĩ ĩndĩ kũitonyeka mwĩĩtu wa andũ makwa kũvoeka?'),
('kam', 'JER', 9, 1, 'A! Kethĩwa mũtwe wakwa nĩ manzĩ, na metho makwa nthongo ya methoi, nĩ kana nĩmaĩĩe mũthenya na ũtukũ ala moaaiwe ma mwĩĩtu wa andũ makwa!'),
('kam', 'JER', 9, 2, 'A! Kethĩwa nĩ na vandũ weũnĩ va kũkomya andũ ala maendaa kyalo; nĩ kana ndonye kũtia andũ makwa, na kuma vala maĩ! Nũndũ onthe nĩ ilaalai, ũmbano wa andũ nzeleke.'),
('kam', 'JER', 9, 3, 'Na nĩmeũkonza nĩmĩ syoo, o ta ũta woo, maneene ũvũngũ; nao nĩmatw’ĩkie me na vinya ĩ nthĩ, ĩndĩ ti kwondũ wa w’o: nũndũ nĩmaendeeaa kuma ũthũkunĩ kũendeea ũthũkunĩ, na matimbĩsĩ, easya ũu Yeova.'),
('kam', 'JER', 9, 4, 'Ĩsũvĩei kĩla ũmwe na mũtũi wake, na mũtikamũĩkĩĩe mwana‐a‐asa o na wĩva; nũndũ kĩla mwana‐a‐asa akoosa vyũ vandũ va ũla ũngĩ, na kĩla mũtũi akaendaa kũũ na kũũ akĩsukana.'),
('kam', 'JER', 9, 5, 'Na kĩla ũmwe akakenga mũtũi wake, na kũlea kũneena w’o: nĩmamanyĩĩtye nĩmĩ syoo kũneena movũngũ; nĩmekwĩnosya meke ũthũku.'),
('kam', 'JER', 9, 6, 'Ũtũo waku wĩ ũkenganinĩ katĩ; kwondũ wa ũkengani nĩmeũlea kũmanya nyie, easya ũu Yeova.'),
('kam', 'JER', 9, 7, 'Kwondũ wa ũu Yeova wa nguthu easya atĩĩ, Sisya, ngamatwekethya, na kũmatata; nũndũ naĩle kwĩka ũndũ ũngĩ wĩva, ũndũ wa mwĩĩtu wa andũ makwa?'),
('kam', 'JER', 9, 8, 'Ũĩmĩ woo nĩ mũsyĩ wũaaa; nũneenaa ũkengani: mũndũ nũneenaa na mũuo na mũtũi wake na kanyw’a wake, ĩndĩ ngoonĩ yake nũmwoveeasya.'),
('kam', 'JER', 9, 9, 'Ndikamasilĩla ũndũ wa maũndũ asu? Easya ũu Yeova; thayũ wakwa ndũkeĩvanĩsya mbaĩnĩ ĩilyĩ ĩno?'),
('kam', 'JER', 9, 10, 'Ngambĩlĩlya kũĩĩa na kũmetea iĩma, na ngambĩlĩlya kĩĩo kwondũ wa isesi sya weũnĩ, nĩkwĩthĩwa nĩ mbĩvye, ũndũ vataendelwa nĩ mũndũ; o na andũ maitonya kwĩw’a wasya wa indo; nyũnyi sya yayaya, o na nyamũ, nikĩĩte, ikathi.'),
('kam', 'JER', 9, 11, 'Na ngatw’ĩkĩthya Yelusaleme ivumbu, wĩkalo wa mbĩwa; na ngatw’ĩkĩthya ndũa sya Yuta maanzo, ite mũndũ witũa.'),
('kam', 'JER', 9, 12, 'Mũndũ mũĩ nũũ, ũla ũtonya kũmanya ũndũ ũsu? Nake nũũ ũla kanyw’a wa Yeova ũneenete nake, nĩ kana otavan’ye? Nũndũ wa kĩ nthĩ yanangĩkĩte, na kũvĩvw’a ta weũ, ũkethĩa vati mũndũ ũmĩvĩtĩla?'),
('kam', 'JER', 9, 13, 'Na Yeova easya, Nĩkwĩthĩwa nĩmatiie mĩao yakwa ĩla naiie mbee woo, na matyaaĩw’a wasya wakwa, o na matyaoatĩĩa,'),
('kam', 'JER', 9, 14, 'ĩndĩ nĩmaatĩĩe ngũlũ sya ngoo syoo ene, na kũatĩĩa Mbaalimu, ala aaĩthe moo mamamanyĩisye;'),
('kam', 'JER', 9, 15, 'kwondũ wa ũu Yeova wa nguthu, Ngai wa Isilaeli, easya atĩĩ, Sisya, namaathĩsya, o andũ aa, kĩndũ kĩ ũũ, na kũmanenga manzĩ me ũũ ta nyongo manyw’e.'),
('kam', 'JER', 9, 16, 'O na ngamanyaĩĩkya mbaĩnĩ, ila mo kana aaĩthe moo mataaimanya; na ngatũma ũvyũ ũmaatĩĩe, kũvika namamina.'),
('kam', 'JER', 9, 17, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Sũanĩai, mũmete aka ma kũĩa, moke; na tũmanai aka ala oĩ, moke:'),
('kam', 'JER', 9, 18, 'na mekalaate, na kwambĩlĩlya kĩĩo kwondũ witũ, nĩ kana metho maitũ metĩkye methoi, na ilomo sya metho maitũ syĩtĩkye manzĩ.'),
('kam', 'JER', 9, 19, 'Nũndũ wasya wa kĩĩo nũkwĩw’ĩka kuma Saioni. A! Nĩtwanangĩtwe! Nĩtũthokoanĩtw’e mũno, nĩkwĩthĩwa nĩtũtiĩte nthĩ, nĩkwĩthĩwa nĩmaomboangĩte nyũmba sitũ.'),
('kam', 'JER', 9, 20, 'Ĩndĩ ĩw’ai ndeto ya Yeova, inyw’ĩ aka, na matũ menyu nĩmose ndeto ya kanyw’a wake; na manyĩsyai eĩtu menyu kĩmeto, na kĩla ũmwe mũtũi wake kĩĩo.'),
('kam', 'JER', 9, 21, 'Nũndũ kĩkw’ũ nĩkĩlikĩle mbũthinĩ sitũ, nĩkĩlikĩte nyũmbanĩ sitũ mbanakavye; kĩmine syana itikaumaale nza, na anake matikaumaale nzĩanĩ nene'),
('kam', 'JER', 9, 22, 'Ũũ nĩw’o Yeova ũnũkwasya, Neena atĩĩ, Simba sya andũ ikavalũkaa ta vũũ weũnĩ, na ta ngundi ĩtina wa mũkethi; na kũtikethĩwa wa kũsyũmban’ya.'),
('kam', 'JER', 9, 23, 'Ũũ nĩw’o Yeova ũnũkwasya, Mũndũ mũĩ ndakekathĩĩe ũĩnĩ wake, na ngũmbaũ ndĩkekathĩĩe ũtonyinĩ wayo, o na mũndũ mũthwii ndakekathĩĩe ũthwiinĩ wake;'),
('kam', 'JER', 9, 24, 'ĩndĩ ũla wĩkathĩĩaa nĩekathĩĩe ũndũnĩ ũũ, atĩ e na ũmanyi, na nũmbĩsĩ nyie, kana ninyie Yeova ũla wonanasya ũseo wĩ wendo, na ũsili wa katĩ, na ũlũngalu, kũũ nthĩ: nũndũ nĩtanĩaa maũndũ asu, easya ũu Yeova.'),
('kam', 'JER', 9, 25, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngasilĩla onthe ala aĩke nũndũ mo ti aĩke:'),
('kam', 'JER', 9, 26, 'Misili, na Yuta, na Etomu, na ana ma Amimoni, na Moavi, na onthe ala menzawa ithũkũ mĩtwe yoo, ala matũaa weũnĩ; nũndũ mbaĩ syonthe ti mbaĩke, na nyũmba yonthe ya Isilaeli ti mbaĩke ngoonĩ.'),
('kam', 'JER', 10, 1, 'Ĩthukĩĩsyei ndeto ĩla Yeova ũnũũmũtavya inyw’ĩ, nyũmba ya Isilaeli:'),
('kam', 'JER', 10, 2, 'Ũũ nĩw’o Yeova ũnũkwasya, Mũtikemanyĩsye mũendele wa i mbaĩ, na mũikateve nũndũ wa syama syĩ ĩtunĩ; nũndũ kwondũ wasyo i mbaĩ nitevaa.'),
('kam', 'JER', 10, 3, 'Nũndũ mokũũ ma andũ nĩ mana; mũndũ ũmwe nũtemaa mũtĩ mũtitũnĩ, wĩa wa moko ma ndũĩka yĩ na ĩthoka.'),
('kam', 'JER', 10, 4, 'Nĩmeũwanakavya na vetha na thaavu; na kũathĩa na mĩsumaa na syĩiva, ndũkathingithe.'),
('kam', 'JER', 10, 5, 'Ĩilyĩ mĩtende, ya wĩa wa mwasũvya, ndĩneenaa: mũvaka ĩkuwe, nĩkwĩthĩwa ndĩtonya kũthi. Mũikamĩkĩe; nũndũ ndĩtonya kwĩka ũthũku, o na nthĩnĩ wayo kũti ũtonyi wa kwĩka ũseo.'),
('kam', 'JER', 10, 6, 'Vai ũmwe taku, we Yeova; nue mũnene, na syĩtwa yaku nĩ ĩnene vinyanĩ.'),
('kam', 'JER', 10, 7, 'Nũũ ũla ũtaĩle ũkũkĩa, we Mũsumbĩ wa mbaĩ? Nũndũ ũũ nĩwaĩle kwaku; nĩkwĩthĩwa katĩ wa andũ oĩ onthe ma i mbaĩ, na ũnenenĩ woo w’onthe wa kĩũsumbĩ, vai ũilyĩ taku.'),
('kam', 'JER', 10, 8, 'Ĩndĩ onthe vamwe mailyĩ nyamũ na nĩ atumanu: ũmanyĩsyo wa mĩvw’anano! No mũtĩ ki.'),
('kam', 'JER', 10, 9, 'Kwĩ vetha ũmandĩtwe ũkavũtha mũno, ũla ũetetwe kuma Talisisi, na thaavu kuma Uvasi, wĩa wa ndũĩka na wa moko ma mũtwii wa thaavu; ngũa syayo nĩ sya vuluu na ila itilyĩ ndune; yonthe nĩ wĩa wa andũ oĩ.'),
('kam', 'JER', 10, 10, 'Ĩndĩ Yeova nĩ Ngai wa w’o; nake nĩ Ngai wĩ thayũ na Mũsumbĩ wa tene na tene: nthĩ nĩtetemaa kwondũ wa ũthilĩku wake, na mbaĩ ititonya kũmĩĩsya ũthatu wake.'),
('kam', 'JER', 10, 11, 'Ũũ nĩw’o mwĩsyĩa, Ila ngai itaomba matu na nthĩ, isu ikathela nthĩ, na ĩtheo wa matu.'),
('kam', 'JER', 10, 12, 'Nũtw’ĩkĩthĩtye nthĩ kwondũ wa vinya wake, nũlũmĩtye nthĩ kwondũ wa ũĩ wake, na nũtambũũkĩtye matu kwondũ wa ũmanyi wake.'),
('kam', 'JER', 10, 13, 'Yĩla waumya wasya wake ve kĩlitũko kya manzĩ matunĩ, na nũtumaa mũki kwambata kuma itulunĩ sya nthĩ; nũseũvĩasya mbua motisi, na kumya kĩseve ũthwiinĩ wake.'),
('kam', 'JER', 10, 14, 'Kĩla mũndũ nũtw’ĩkĩte ta nyamũ na nde na ũmanyi; kĩla mũtwii wa thaavu nũsonokaw’a nĩ mũvw’anano wake mwasũvye; nũndũ mũvw’anano wake ũla waseũvisye na syĩndũ ila watwekethisye nĩ wa ũvũngũ, na vai veva nthĩnĩ wayo.'),
('kam', 'JER', 10, 15, 'Nayo nĩ mana, wĩa wa ũkengani: ĩvinda ya kũsiw’a kwayo ĩkaaa.'),
('kam', 'JER', 10, 16, 'Kĩanda kya Yakovo ti ta ĩsu; nũndũ nĩwe mũmbi wa syĩndũ syonthe; na Isilaeli nĩ mbaĩ ya ũtiĩwa wake: Yeova wa nguthu nĩ syĩtwa yake.'),
('kam', 'JER', 10, 17, 'Ũmban’ya syĩndũ syaku ũsyumye nthĩ ĩno, we ũla wĩkalaa ngomenĩ yĩ vinya.'),
('kam', 'JER', 10, 18, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Sisya, ĩvinda yĩĩ ngamekya na vinya ala matwĩe nthĩ ĩno maume, na kũmathĩn’ya, nĩ kana mew’e.'),
('kam', 'JER', 10, 19, 'Woo nĩ wakwa nũndũ wa kũkũnwa kwakwa! Wũkite wakwa nĩ mũnene: ĩndĩ nasya, Nĩ w’o ũũ nĩ woo wakwa, no mũvaka nĩwũmĩĩsye.'),
('kam', 'JER', 10, 20, 'Ĩeema yakwa nĩ yanangĩku, na makanda makwa onthe nĩ matw’ĩkangu: syana syakwa nĩsyumĩte kwakwa na iti vo: vati wa kwamba ĩeema yakwa ĩngĩ, na kũkĩlya motũtũ makwa ma ngũa.'),
('kam', 'JER', 10, 21, 'Nũndũ aĩthi nĩmatw’ĩkĩte ta nyamũ, na matyaakũlya Yeova: kwondũ wa ũu matyaaathimĩka, na ndĩthya syoo syonthe sya mbũi na malondu ninyaĩĩkĩte.'),
('kam', 'JER', 10, 22, 'Sisya, wasya wa ũvoo nĩwũkĩte, na kĩtuu kĩnene kuma nthĩ ya ngalĩ ya ĩũlũ, kũtw’ĩkĩthya ndũa sya Yuta maanzo, wĩkalo wa mbĩwa.'),
('kam', 'JER', 10, 23, 'Ame Yeova, nĩnĩsĩ kana nzĩa ya mũndũ ndĩ nthĩnĩ wake mwene; kũtongoesya matambya make kũti nthĩnĩ wa mũndũ ũla ũendaa.'),
('kam', 'JER', 10, 24, 'Ame Yeova, ngan’ya, ĩndĩ ũthimĩte; ti ũthatunĩ waku, ndũkese kũmina nyie.'),
('kam', 'JER', 10, 25, 'Onosya ũthilĩku waku mbaĩnĩ ila iteũkũmanya, na mĩvĩanĩ ĩla ĩtekaĩlaa syĩtwa yaku; nũndũ nĩmaĩte Yakovo, ĩĩ, nĩmamũĩte na kũmũnina, na kwananga wĩkalo wake.'),
('kam', 'JER', 11, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, ĩkyasya,'),
('kam', 'JER', 11, 2, 'Ĩthukĩĩsyei ndeto sya ũtianĩo ũũ, ũneene na andũ ma Yuta, na ala matwĩe Yelusaleme;'),
('kam', 'JER', 11, 3, 'ũmatavye, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya: Naumanĩwe mũndũ ũla ũtethukĩĩasya ndeto sya ũtianĩo ũũ,'),
('kam', 'JER', 11, 4, 'ila nameaĩe aaĩthe menyu mũthenya ũla namaumisye nthĩ ya Misili, kũmaumya ikonĩ ĩnene ya kĩaa, ngyasya, Ĩw’ai wasya wakwa, na kũsyĩka kwĩanana na w’onthe ũla nĩmwĩaĩaa: na ĩndĩ mũkeethĩwa andũ makwa, nakwa ngeethĩwa Ngai wenyu;'),
('kam', 'JER', 11, 5, 'nĩ kana nĩlũlũmĩlye wĩvĩto ũla namevĩtĩe aaĩthe menyu, kũmanenga nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, o ũndũ kũilyĩ ũmũnthĩ. Na ĩndĩ nasũngĩa, nasya, Ameni, ame Yeova.'),
('kam', 'JER', 11, 6, 'Na Yeova ambĩa, Tavan’ya ndeto ii syonthe ndũanĩ sya Yuta, na nzĩanĩ nene sya Yelusaleme, ũkyasya, Ĩthukĩĩsyei ndeto sya ũtianĩo ũũ, na mũisyĩka.'),
('kam', 'JER', 11, 7, 'Nũndũ nĩnamakũsĩĩe mũno aaĩthe menyu mũthenya ũla namaumisye nthĩ ya Misili, o na kũvika ũmũnthĩ, ngyũkĩla tene ngĩkũsĩĩa, ngyasya, Ĩw’ai wasya wakwa.'),
('kam', 'JER', 11, 8, 'Ĩndĩ matyaaĩw’a, o na kũtea matũ moo, ĩndĩ nĩmaatĩĩe kĩla ũmwe ngũlũ sya ngoo yake nthũku: kwondũ wa ũu namaetee ndeto syonthe sya ũtianĩo ũũ, ila nameaĩe meke, ĩndĩ matyaasyĩka.'),
('kam', 'JER', 11, 9, 'Na Yeova ambĩa, Wĩw’ano mũthũku nĩwonekete andũnĩ ma Yuta, na andũnĩ ala matwĩe Yelusaleme.'),
('kam', 'JER', 11, 10, 'Nĩmasyokete mothũkũnĩ ma aaũmae moo, ala maleile kwĩw’a ndeto syakwa; na nĩmaatĩĩie ngai ingĩ maithũkũme: nyũmba ya Isilaeli na nyũmba ya Yuta nĩsyanangĩte ũtianĩo wakwa ũla natianĩe na aaĩthe moo.'),
('kam', 'JER', 11, 11, 'Kwondũ wa ũu Yeova easya atĩĩ, Sisya, ngaietee ũthũku, ũla itakatonya kũvonoka; na ikengaĩla, ĩndĩ ndikasyĩthukĩĩsya.'),
('kam', 'JER', 11, 12, 'Nĩvo ĩndĩ ndũa sya Yuta na ala matwĩe Yelusaleme makathi na kwĩkaĩla ngai ila matoeeasya ũvani: ĩndĩ itikamatangĩĩa nongi ĩvinda ya thĩna woo.'),
('kam', 'JER', 11, 13, 'Nũndũ o ũndũ ũtalo wa ndũa syaku wĩana, now’o ngai syaku syĩana, we Yuta; na kwĩanana na ũtalo wa nzĩa sya Yelusaleme nĩmaũngamĩsye kĩndũ kĩ nthoni ithembeo, o ithembeo sya kũtoeeasya Mbaali ũvani.'),
('kam', 'JER', 11, 14, 'Kwondũ wa ũu ndũkamavoyee andũ aa, o na ndũkokĩlye kĩĩo kana mboya kwondũ woo; nũndũ ndikamew’a yĩla meĩngaĩla nũndũ wa thĩna woo.'),
('kam', 'JER', 11, 15, 'Mwendwa wakwa e na ũndũ mwaũ nyũmbanĩ yakwa, nũndũ nĩwĩkĩte molaalai na aingĩ, na nyama ntheu nithelete kwaku? Yĩla ũkwĩka ũthũku nĩvo ũtanaa.'),
('kam', 'JER', 11, 16, 'Yeova nĩwetie syĩtwa yaku, Mũthata mwĩũ, wa kwendeesya wĩ na ũsyao mũseo: nũkwatĩtye mwaki ĩũlũ waw’o na kĩlonzo kya kĩtuu kĩnene, na mbonge syaw’o nĩ ndũlĩku.'),
('kam', 'JER', 11, 17, 'Nũndũ Yeova wa nguthu ũla wakũvandie, nũkũwetete ũthũku, nũndũ wa ũthũku wa nyũmba ya Isilaeli na wa nyũmba ya Yuta, ũla meyĩkĩte makĩnthatya kwondũ wa kũtoeeasya Mbaali ũvani.'),
('kam', 'JER', 11, 18, 'Na Yeova amanyĩthya, na namanya: nĩvo ĩndĩ wambonisye meko moo.'),
('kam', 'JER', 11, 19, 'Ĩndĩ nailyĩ ta katena kauu ka ĩlondu katwaĩtwe kĩthĩnzĩonĩ; na ndyaamanya kana nĩmanzũanĩĩĩte maũndũ, makyasya, Twanange mũtĩ vamwe na ũsyao waw’o, na tũmũvete nthĩ ya ala me thayũ, nĩ kana syĩtwa yake yĩtikalilikanwe ĩngĩ.'),
('kam', 'JER', 11, 20, 'Ĩndĩ, ame Yeova wa nguthu, ũla ũtusaa katĩ, ũla ũoasya ngoo na mosũanĩo, ngoona ũĩvanĩsyo waku kwoo; nũndũ nĩnakwonisye ũvoo wakwa.'),
('kam', 'JER', 11, 21, 'Kwondũ wa ũu Yeova eneena ũndũ wa ana ma Anathothi, ala mamanthaa thayũ waku, makyasya, Ndũkathane syĩtwanĩ ya Yeova, ndũkoawe nĩ moko maitũ;'),
('kam', 'JER', 11, 22, 'kwondũ wa ũu Yeova wa nguthu easya atĩĩ, Sisya, ngamasilĩla: anake makooawa na ũvyũ; ana moo na eĩtu moo makooawa nĩ yũa;'),
('kam', 'JER', 11, 23, 'na vatikethĩwa ũtialo kwoo; nũndũ ngamaetee aũme ma Anathothi ũthũku, mwaka wa kũsilĩlwa kwoo.'),
('kam', 'JER', 12, 1, 'Ame Yeova, wĩ mũlũngalu yĩla ngũkũlan’ya naku; ĩndĩ nĩngwenda tũneenan’ye ũndũ ũũ: nũndũ wa kĩ nzĩa ya athũku nĩnĩkwaĩla? Nũndũ wa kĩ onthe ala mekaa ũseleke mũno me na ũthũmũo?'),
('kam', 'JER', 12, 2, 'We nĩwamavandie, ĩĩ, nĩmatambũũkĩtye mĩi; nĩmekwĩana, ĩĩ, nĩmekũsyaa mosyao: we wĩ vakuvĩ na makanyw’a moo, na wĩ kũasa na ngoo syoo.'),
('kam', 'JER', 12, 3, 'Ĩndĩ we, ame Yeova, nũmbĩsĩ; nũmbonaa, na kũtata ngoo yakwa kana nĩkwelekele: makwate ta malondu ma kũthĩnzwa, ũmavathe ũndũ wa mũthenya wa kũawa.'),
('kam', 'JER', 12, 4, 'Nthĩ ĩkameta, na nyũnyi ila imeaa nthĩ yonthe ikavova kũvika ĩndĩĩ? Nyamũ na nyũnyi nikũminwa kwondũ wa ũthũku wa ala mamĩtwĩe; nũndũ nĩmaisye, Ndakona mũminũkĩlyo witũ.'),
('kam', 'JER', 12, 5, 'Ethĩwa nĩwasembanisye na ala maendaa na maũũ, na makũnosya, ũtonya ata ĩndĩ kũkĩlan’ya maũũ na mbalasi? O na ethĩwa ndwĩ na mũisyo yĩla wĩkalaa nthĩ yĩ mũuo, ũkeeka ata ĩndĩ kũvinganĩ kwa Yolotani?'),
('kam', 'JER', 12, 6, 'Nũndũ o na ana‐a‐au, na nyũmba ya au, o asu nĩmakwĩkĩte ũseleke; o mo nĩmakũĩĩĩte ĩtina waku: ndũkametĩkĩle, o na makũtavya ndeto nzeo.'),
('kam', 'JER', 12, 7, 'Nĩndiĩte nyũmba yakwa, nĩnĩvetete ũtiĩwa wakwa; nĩnĩnenganĩte mwendwa wa ngoo yakwa kw’okonĩ kwa amaitha make.'),
('kam', 'JER', 12, 8, 'Ũtiĩwa wakwa nũtw’ĩkĩte kwakwa ta mũnyambũ mũtitũnĩ: nũmbũkĩlĩlye wasya wake; kwondũ wa ũu nĩnĩmũmenete.'),
('kam', 'JER', 12, 9, 'Ũtiĩwa wakwa ũilyĩ kwakwa ta nyũnyi yĩ makwele ĩla ĩsyĩmaa? Nyũnyi ila isyĩmaa nimũkiita ngalĩ syonthe? Endai, mũmban’ye nyamũ syonthe sya kĩthekanĩ, mwiete iye.'),
('kam', 'JER', 12, 10, 'Aĩthi aingĩ nĩmaanangie mũũnda wakwa wa mĩsavivũ, na kũkinyanga kĩlungu kyakwa, na kũtw’ĩkĩthya kĩlungu kyakwa kĩseo weũ mũthei.'),
('kam', 'JER', 12, 11, 'Nĩmakĩtw’ĩkĩthĩtye kĩthei; nĩkĩkũndĩĩa kĩ kĩthei; nthĩ yonthe nĩtw’ĩkĩthĩtw’e nthei, nũndũ vati mũndũ wa ũmĩlilikana ngoonĩ yake.'),
('kam', 'JER', 12, 12, 'Anangi nĩmambatĩte kũndũ kw’onthe kũtũlu kũthei weũnĩ; nũndũ ũvyũ wa Yeova nũminaa kuma ngalĩ ĩmwe ya nthĩ o na kũvika ngalĩ ĩla ĩngĩ ya nthĩ: vati mwĩĩ wĩ na mũuo.'),
('kam', 'JER', 12, 13, 'Nĩmavuĩie nganũ, na maketha mĩw’a; nĩmeethĩnĩsye, na matyaaona ũunĩko: na inyw’ĩ mũkasonoka ũndũ wa mosyao menyu, nũndũ wa ũthatu mwai wa Yeova.'),
('kam', 'JER', 12, 14, 'Ũũ nĩw’o Yeova ũnũũmaneenea atũi makwa onthe athũku, ala makiitaa ũtiĩwa ũla natumie andũ makwa Isilaeli matiĩwa: Sisya, ngamakũa maume nthĩ yoo, na kũkũa nyũmba ya Yuta yume katĩ woo.'),
('kam', 'JER', 12, 15, 'Na kũkeethĩwa, namina kũmakũa, ngasyoka na kũmew’ĩa tei; na ngamaete ĩngĩ, kĩla mũndũ ũtiĩwani wake, na kĩla mũndũ nthĩ yake.'),
('kam', 'JER', 12, 16, 'Na kũkeethĩwa, ethĩwa makeemanyĩsya na kĩthing’ĩĩsyo nzĩa sya andũ makwa, kwĩvĩta na syĩtwa yakwa atĩĩ, O tondũ Yeova wĩ thayũ; o tondũ mamanyĩisye andũ makwa kwĩvĩta na Mbaali; nĩvo ĩndĩ makaakwa katĩ wa andũ makwa.'),
('kam', 'JER', 12, 17, 'Ĩndĩ ethĩwa nĩmeũlea kwĩthukĩĩsya, nĩvo ĩndĩ ngakũa mbaĩ ĩsu, ngĩkũa na ngĩmyananga, easya ũu Yeova.'),
('kam', 'JER', 13, 1, 'Ũũ nĩw’o Yeova wambĩie, Enda, wĩthooee mũsivi wa katane, na kwĩyova kĩnyunyunĩ kyaku, na ndũkawĩkĩe manzĩnĩ.'),
('kam', 'JER', 13, 2, 'Kwondũ wa ũu nathooa mũsivi kwĩanana na ndeto ya Yeova, na neeyova kĩnyunyunĩ kyakwa.'),
('kam', 'JER', 13, 3, 'Na ndeto ya Yeova yambũkĩa ya kelĩ, ĩkyasya,'),
('kam', 'JER', 13, 4, 'Osa mũsivi ũla wathooie, ũla wĩyovete kĩnyunyunĩ kyaku, wũkĩle, ũende ũsĩnĩ wa Euvalati, noyũvitha ku mũvatĩnĩ wa ĩvia.'),
('kam', 'JER', 13, 5, 'Kwondũ wa ũu nathi, na noovitha vakuvĩ na ũsĩ wa Euvalati, o tondũ Yeova wambĩaĩe.'),
('kam', 'JER', 13, 6, 'Na kweethĩwa, mĩthenya mingĩ yathela, Yeova ambĩa, Ũkĩla, ũende ũsĩnĩ wa Euvalati, wumye mũsivi vu, ũla nakwĩaĩe ũvithe vo.'),
('kam', 'JER', 13, 7, 'Nĩvo ĩndĩ naendie ũsĩnĩ wa Euvalati, na nenza, na naumya mũsivi vandũ vala noovithĩte; na, sisya, mũsivi waĩ mwanangĩku, ndwaĩ vata nongi.'),
('kam', 'JER', 13, 8, 'Na ĩndĩ ndeto ya Yeova yambũkĩa, ĩkyasya,'),
('kam', 'JER', 13, 9, 'Ũũ nĩw’o Yeova ũnũkwasya, O ta ũu ngaananga ngathĩĩo ya Yuta, na ngathĩĩo nene ya Yelusaleme.'),
('kam', 'JER', 13, 10, 'Andũ aa athũku, ala maleaa kwĩw’a ndeto syakwa, ala maendaa makĩatĩĩa ngũlũ sya ngoo syoo, na kũatĩĩa ngai ingĩ maithũkũme, na kwithaitha, makeethĩwa o ta mũsivi ũũ, ũla ũte vata nongi.'),
('kam', 'JER', 13, 11, 'Nũndũ o ũndũ mũsivi ũlũmanasya na kĩnyunyu kya mũndũ, o ta ũu nakwa natuma nyũmba yonthe ya Isilaeli na nyũmba yonthe ya Yuta ilũman’ya nakwa, easya ũũ Yeova; nĩ kana methĩwe kwakwa ũko wa andũ, na syĩtwa, na ngatho, na ndaĩa: ĩndĩ nĩmaleile kwĩw’a.'),
('kam', 'JER', 13, 12, 'Kwondũ wa ũu wĩmatavya ndeto ĩno: Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Kĩla sũva ũkausũw’a mbinyu: nao makakũkũlya, Tũtyĩsĩ kana nĩw’o kĩla sũva ũkausũw’a mbinyu?'),
('kam', 'JER', 13, 13, 'Nĩvo ĩndĩ wĩmea, Ũũ nĩw’o Yeova ũnũkwasya, Sisya, ngausũsya na ũthengi onthe ala matwĩe nthĩ ĩno, o asumbĩ ala mekalaa vandũ va Ndaviti kĩvĩlanĩ kyake kya ũsumbĩ, na athembi, na athani, na onthe ala matwĩe Yelusaleme.'),
('kam', 'JER', 13, 14, 'Na ngamatinangan’ya kĩla mũndũ na ũla ũngĩ, o aaĩthe na ana vamwe, easya ũu Yeova: ndikew’ĩa tei, kana kũeka, kana kwĩthĩwa na ĩnee, ndikamanange.'),
('kam', 'JER', 13, 15, 'Ĩthukĩĩsyei na kũtea matũ, mũtikekathĩĩe; nũndũ Yeova nũneenete.'),
('kam', 'JER', 13, 16, 'Mũnengei Yeova Ngai wenyu ndaĩa, atanamba kũete kĩvindu, na maũũ menyu matanamba kũlulutĩka iĩmanĩ syĩ kĩvindu, na, yĩla mũũmantha kyeni, nake aikĩalyũla kĩthĩwe kyuu kya kĩkw’ũ, na kũkĩtw’ĩkĩthya kĩvindu kya ngokomĩ.'),
('kam', 'JER', 13, 17, 'Ĩndĩ ethĩwa mwĩlea kwĩw’a, ngoo yakwa ĩkaĩa kĩmbithĩ ũndũ wa ngathĩĩo syenyu; na itho yakwa yĩkaĩa mũno, na kwĩtĩkya methoi, nũndũ ndĩthya ya Yeova nĩtavĩtwe.'),
('kam', 'JER', 13, 18, 'Mũtavye mũsumbĩ na inyia wake, Ĩnyivyei, mwĩkale nthĩ; nũndũ tũkovila twenyu nĩ tũvalũku, o ngovia ya ũsumbi ya ndaĩa yenyu.'),
('kam', 'JER', 13, 19, 'Ndũa sya ngalĩ ya Ĩtheo nĩ mbinge, na vati mũndũ wa kwivingũa: Yuta yonthe nĩtavĩtwe; nĩtwaĩtwe vyũ yĩ ndave.'),
('kam', 'JER', 13, 20, 'Ũngalalyai metho menyu, mũsisye ala mokĩte kuma ngalĩ ya ĩũlũ: ndĩthya ĩla wanengiwe, ndĩthye yaku nzeo, ĩĩva?'),
('kam', 'JER', 13, 21, 'Ũkasya ata, yĩla wĩmaia methĩwe atongoi maku asu ala we mwene wamamanyĩĩsye methĩwe anyanyau? Mawoo maikakũkwata, ta ma mũndũ mũka akyaũnya?'),
('kam', 'JER', 13, 22, 'Na ethĩwa wĩasya ngoonĩ yaku, Maũndũ aa membũkĩa nũndũ wa kĩ? Nũndũ wa ũthũku waku kwingĩva nũvuĩtwe ngũa syaku, na itiinyo syaku nĩ ndine.'),
('kam', 'JER', 13, 23, 'Mũethiovia nũtonya kũalyũla kĩkonde kyake, kana ngo maa mayo? Nĩvo ĩndĩ mũkatonya kwĩka nesa, ala mũkothaa kwĩka ũthũku.'),
('kam', 'JER', 13, 24, 'Kwondũ wa ũu ngamanyaĩĩkya, o ta ũa ũvĩtaa ũũlũkĩtw’e nĩ kĩseve kya weũnĩ.'),
('kam', 'JER', 13, 25, 'Kyu nĩ kĩanda kyaku, kĩlungu kĩla wathimĩwe ninyie, easya ũu Yeova; nũndũ nĩwũlĩtwe ninyie, na kũĩkĩĩa ũvũngũ.'),
('kam', 'JER', 13, 26, 'Kwondũ wa ũu ngavua ngũa syaku nĩvikye ũthyũnĩ waku, na nthoni syaku ikooneka.'),
('kam', 'JER', 13, 27, 'Nĩnonete mothatyo maku, o molaalai maku, na kwan’ya kwaku, wathe wa ũlwaya waku, wĩ iĩmanĩ syĩ weũnĩ. Woo nĩ waku, we Yelusaleme! Ndwĩtĩkĩla kũthew’a; kũkethĩwa ũu kũvika ĩndĩĩ?'),
('kam', 'JER', 14, 1, 'Ndeto ya Yeova ĩla yamũkĩe Yelemia ũndũ wa mũnyao.'),
('kam', 'JER', 14, 2, 'Yuta nũnũkũmeta na mbingĩlo yake nĩnĩũleela, mailyĩ nthĩ mevw’ĩkĩte ngũa nziũ; na kĩĩo kya Yelusaleme nĩkyũkĩlĩte.'),
('kam', 'JER', 14, 3, 'Na anene moo me ndaĩa matũma ala anini moo maende manzĩnĩ: mavika ithimanĩ, na mailea kwona manzĩ; nĩmasyokaa na ikuu syo syĩ nthei; nĩmasonokaa na kũthokoana, na kũvw’ĩka mĩtwe yoo.'),
('kam', 'JER', 14, 4, 'Aĩmi nĩmasonokaa na kũvw’ĩka mĩtwe yoo, nĩkwĩthĩwa nthĩ nĩ mbatũkangu, nũndũ kũtyeethĩawa mbua nthĩ.'),
('kam', 'JER', 14, 5, 'Ĩĩ, o na ndaatai nĩsyaĩaa weũnĩ, na kũtia ĩswii yayo, nĩkwĩthĩwa vati nyeki.'),
('kam', 'JER', 14, 6, 'Na mang’oi ma kĩthekanĩ maũngamaa kũndũ kũtũlu kũthei makĩvevaveva ta mbĩwa; metho mamo makĩseekea, nũndũ vati kya ũya.'),
('kam', 'JER', 14, 7, 'O na ethĩwa mothũku maitũ nĩmeũtũkũsĩĩa, tethya wĩa kwondũ wa syĩtwa yaku, ame Yeova; nũndũ kũsyoka na ĩtina kwitũ nĩ kwingĩ; nĩtwakũvĩtanĩsye.'),
('kam', 'JER', 14, 8, 'We wĩkwatyo wa Isilaeli, Mũtangĩĩi wake ĩvinda ya thĩna, wĩĩthĩwa ta mũeni nthĩ nĩkĩ, na ta mũndũ wa kyalo ũla wathũkaa one vandũ va ũkoma ũtukũ?'),
('kam', 'JER', 14, 9, 'Wĩĩthĩwa ta mũndũ mũtelemu nĩkĩ, ta ngũmbaũ ĩla ĩtatonya kũtangĩĩa? Ĩndĩ, ame Yeova, wĩ katĩ waitũ, na ithyĩ nĩtũkwĩtanĩw’a na syĩtwa yaku; ndũkatũtie.'),
('kam', 'JER', 14, 10, 'Ũũ nĩw’o Yeova ũnũũmatavya andũ aa, Nĩmendaa kwanganga; matyaasiĩĩa maũũ moo: kwondũ wa ũu Yeova ndeũmetĩkĩla; yu akalilikana ũthũku woo, na kũsilĩla naĩ syoo.'),
('kam', 'JER', 14, 11, 'Na Yeova ambĩa, Ndũkamavoyee andũ aa mone ũseo.'),
('kam', 'JER', 14, 12, 'Matĩĩa ũya, ndikew’a kĩĩo kyoo; na mathemba nthembo ya kũvĩvw’a na nthembo ya mũtu, ndikasyĩtĩkĩla; ĩndĩ ngamamina na ũvyũ, na yũa, na mũimũ.'),
('kam', 'JER', 14, 13, 'Nĩvo naisye, Ai! Mwĩaĩi Yeova! Sisya, athani mamatavasya, Mũtikona ũvyũ, o na mũtikethĩwa na yũa; ĩndĩ ngamũnengae mũuo wa w’o vandũ vaa.'),
('kam', 'JER', 14, 14, 'Nĩvo ĩndĩ Yeova wandavisye, Athani mathanaa movũngũ syĩtwanĩ yakwa; ndyaamatũma, o na ndyaameaĩa, o na ndyaaneena nao: mamwathanĩaa woni wa ũvũngũ, na kũaũsya, na ũndũ wa mana, na ũkengani wa ngoo syoo ene.'),
('kam', 'JER', 14, 15, 'Kwondũ wa ũu Yeova easya ũndũ wa athani ala mathanaa syĩtwanĩ yakwa, na ndyaamatũma, ĩndĩ measya, Ũvyũ na yũa itikethĩwa nthĩ ĩno: Athani asu makaminwa na ũvyũ na yũa.'),
('kam', 'JER', 14, 16, 'Na andũ ala mamathanĩaa makekw’a nzĩanĩ nene sya Yelusaleme nũndũ wa yũa na ũvyũ; na matikethĩwa na mũndũ wa kũmenzĩa nthĩ — mo, kana iveti syoo, kana ana moo, kana eĩtu moo: nũndũ ngamonoesya ũthũku woo.'),
('kam', 'JER', 14, 17, 'Naku wĩmatavya ndeto ĩno, Metho makwa nĩmetĩkye methoi ũtukũ na mũthenya, na matikaeke; nũndũ mwĩĩtu mũtheu wa andũ makwa nĩwanangĩtwe wanangĩko mũnene, na wũkite mũnene mũno.'),
('kam', 'JER', 14, 18, 'Ethĩwa nĩngumaala nĩende weũnĩ, nĩvo, sisya, ala moaiwe na ũvyũ! Na ethĩwa nĩngũlika ndũanĩ, nĩvo, sisya, ala mang’ong’etw’e nĩ yũa! Nũndũ mwathani na mũthembi me elĩ mangangaa nthĩ kũũ na kũũ, na mati na ũmanyi.'),
('kam', 'JER', 14, 19, 'Nũleete Yuta vyũ? Ngoo yaku nĩmenete Saioni? Nĩkĩ watũkũnie, na vati kũvoa kwitũ? Twamanthaa mũuo, ĩndĩ ũseo ndwaaũka; na twamanthaa ĩvinda ya kũvow’a, na, kaĩ, nĩ kũteva!'),
('kam', 'JER', 14, 20, 'Ame Yeova, nĩtũkumbũla ũthũku witũ, na ũthũku wa aaĩthe maitũ; nũndũ nĩtwakũvĩtanĩsye.'),
('kam', 'JER', 14, 21, 'Kwondũ wa syĩtwa yaku, ndũkatũthĩthe; ndũkasonokye kĩvĩla kya ũsumbĩ kya ũnene waku: lilikana, ndũkanange ũtianĩo waku naitũ.'),
('kam', 'JER', 14, 22, 'Ve imwe sya syĩndũ sya mana sya mbaĩ itonya kusya mbua? Kana matu nĩmatonya kũete mĩono ya mbua? Tuue we, ame Yeova Ngai waitũ? Kwondũ wa ũu tũkakweteela; nũndũ nue waseũvisye syĩndũ isu syonthe.'),
('kam', 'JER', 15, 1, 'Nĩvo ĩndĩ Yeova wambĩie, O na kethĩwa Mose na Samueli nĩmaũngeme mbee wakwa, kĩlilikano kyakwa kĩikamelekela andũ aa: mekye nĩeke ũmona, maende.'),
('kam', 'JER', 15, 2, 'Na kũkeethĩwa, yĩla mekũkũlya, Ithyĩ twĩenda va? Nĩvo ũkamatavya, Ũũ nĩw’o Yeova ũnũkwasya; Ala ma kĩkw’ũ, kĩkw’ũnĩ; na ala ma ũvyũ, ũvyũnĩ; na ala ma yũa, yũanĩ; na ala ma ũtavwa, mũtavonĩ.'),
('kam', 'JER', 15, 3, 'Na Yeova easya, Ngamaiĩa mĩthemba ĩna: ũvyũ wa kũaa, na ngitĩ sya kũtembũanga, na nyũnyi sya yayaya, na nyamũ sya nthĩ, sya kũya na kwananga.'),
('kam', 'JER', 15, 4, 'Nakwa ngamekangya kũũ na kũũ mosumbĩnĩ onthe ma nthĩ nũndũ wa Manase, mwana wa Esekia, mũsumbĩ wa Yuta, nũndũ wa ũndũ ũla wekie Yelusaleme.'),
('kam', 'JER', 15, 5, 'Nũndũ nũũ ũla ũkakwĩw’ĩa tei, we Yelusaleme? Kana nũũ ũla ũkakũmetea? Kana nũũ ũla ũkathũka ũtee aũkũlye ũndũ ũilyĩ?'),
('kam', 'JER', 15, 6, 'Nũndeete, easya Yeova, nũsyokete na ĩtina: kwondũ wa ũu nĩkũtambũũkĩĩtye kw’oko kwakwa, na kũkwananga; nĩnĩnoete nĩ kwĩlila.'),
('kam', 'JER', 15, 7, 'Na nĩnĩmaũlũkĩlye na kĩũlũkya mbingĩlonĩ sya ĩ nthĩ; nĩnĩmakw’ĩĩthĩsye syana, nĩnĩmanangĩte andũ makwa; matyaasyoka kuma mĩendelenĩ yoo.'),
('kam', 'JER', 15, 8, 'Aka moo ndiwa nĩmaingĩvie kwakwa kũvĩtũka kĩthangathĩ kya maũkanga; nĩnĩmaeteete mwanangi ĩũlũ wa aainyia ma anake mũthenya katĩ: nĩnĩtumĩte woo na motĩsyo mamavalũkĩla na kĩthũlũmũko.'),
('kam', 'JER', 15, 9, 'Ũla ũsyaĩte mũonza nũnũkũthelelwa nĩ vinya; nĩwumĩtwe nĩ veva; syũa yake nĩyĩthũĩte kwĩ o mũthenya; nũsonoketw’e na kũthokoanw’a: na nganengane ũtialo woo wũawe na ũvyũ mbee wa amaitha moo, easya ũu Yeova.'),
('kam', 'JER', 15, 10, 'Woo nĩ wakwa, mwaitũ, nũndũ nĩwanzyaie nyie mũndũ wa kũtetw’a na mũndũ wa kũkananĩaw’a nĩ nthĩ yonthe! Ndyaakovethya none ũtandĩthyo, o na andũ matyaangovethya mone ũtandĩthyo; ĩndĩ kĩla mũndũ woo nũkũnumanĩa.'),
('kam', 'JER', 15, 11, 'Yeova aisye, Nĩ w’o ngakwĩkĩa vinya kwondũ wa ũseo; nĩ w’o ngatuma mũmaitha akwĩsũva ĩvinda ya ũthũku na ĩvinda ya thĩna.'),
('kam', 'JER', 15, 12, 'Mũndũ nũtonya kũtũlan’ya kĩaa, o kĩaa na ũthuku syumĩte ngalĩ ya ĩũlũ?'),
('kam', 'JER', 15, 13, 'Syĩndũ syaku na mothwii maku maie ngainengane syĩthĩwe mũtavo vate kũthoowa, na ũu nũndũ wa naĩ syaku syonthe, o mĩvakanĩ yaku yonthe.'),
('kam', 'JER', 15, 14, 'Ngaivĩtĩlya syĩ na amaitha maku kũlika nthĩ ĩla ũtamanya; nũndũ mwaki nĩwakanĩtw’e ũthatunĩ wakwa, ũla ũkamũvĩvya.'),
('kam', 'JER', 15, 15, 'Ame Yeova, we nĩwĩsĩ; ndilikana, na kũmbũkĩa, na kũndĩvanĩĩsya ala manthĩnasya; kwondũ wa wũmĩĩsyo waku, ndũkambete: manya kana nĩ kwondũ waku nĩnavũthiw’e.'),
('kam', 'JER', 15, 16, 'Ndeto syaku nĩsyoonekie, nakwa naiya; na ndeto syaku kwakwa syaĩ mũyo na ũtanu wa ngoo yakwa: nũndũ nĩtanĩaw’a na syĩtwa yaku, ame Yeova, Ngai wa nguthu.'),
('kam', 'JER', 15, 17, 'Ndyaaĩkala ũmbanonĩ wa ala mathekaa, kana kũtana; nekalaa nĩ nyioka nũndũ wa kw’oko kwaku; nũndũ nũmbusũĩtye na ũthatu.'),
('kam', 'JER', 15, 18, 'Nĩkĩ kwalw’a kwakwa nĩ kwa mavinda onthe, na wũkite wakwa ũtivoeka, ũla ũleaa kũvow’a? Nĩ w’o ũkethĩwa kwakwa ta kalũsĩ kakenganaa, ta manzĩ ala mang’alaa?'),
('kam', 'JER', 15, 19, 'Kwondũ wa ũu Yeova easya atĩĩ, Ethĩwa ũkasyoka, nĩvo ĩndĩ ngakũete ĩngĩ, nĩ kana ũũngame mbee wakwa; na ethĩwa ũkaumya kĩla kĩ vata nthĩnĩ wa kĩla kĩthũku, ũkeethĩwa kanyw’a wakwa: makakũsyokea, ĩndĩ ndũkamasyokea.'),
('kam', 'JER', 15, 20, 'Na ngakũtw’ĩkĩthya ũvai mwiie wa ũthuku kwa andũ aa; na makokita naku, ĩndĩ matikakũkĩlya vinya; nũndũ nyie nĩ vamwe naku kũũtangĩĩa na kũũvonokya, easya ũu Yeova.'),
('kam', 'JER', 15, 21, 'Na ngakũvonokya wume kw’okonĩ kwa athũku, na ngakwovosya wume kw’okonĩ kwa ala ma kũtĩsya.'),
('kam', 'JER', 16, 1, 'Na ĩngĩ ndeto ya Yeova yambũkĩa, ĩkyasya,'),
('kam', 'JER', 16, 2, 'Ndũkaaĩtwaĩe mũka, kana kwĩthĩwa na ana kana eĩtu, vandũ vaa.'),
('kam', 'JER', 16, 3, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya ũndũ wa ana na ũndũ wa eĩtu ala masyaĩwe vandũ vaa, na ũndũ wa aainyia moo ala mamasyaĩe, na ũndũ wa aaĩthe moo ala mamasyaĩe nthĩ ĩno:'),
('kam', 'JER', 16, 4, 'Makakw’a ikw’ũ nthũku: maikametewa, o na maikenzĩwa nthĩ; makethĩwa ta vũũ ĩũlũ wa nthĩ; na makooawa na ũvyũ, na yũa; na simba syoo ikethĩwa lĩu wa nyũnyi sya yayaya, na wa nyamũ sya nthĩ.'),
('kam', 'JER', 16, 5, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Ndũkalike nyũmbanĩ ya kũĩĩa, o na ndũkathi kũmeta, kana kũmaĩĩa; nĩnumĩtye mũuo wakwa kwa andũ aa, o ũseo wĩ wendo na tei mwololo, easya ũu Yeova.'),
('kam', 'JER', 16, 6, 'Anene na anini makakw’ĩa nthĩ ĩno; matikenzĩwa nthĩ, o na andũ matikamaĩĩa, kana kwĩtemanga, kana kwĩyenza ũvaa kwondũ woo;'),
('kam', 'JER', 16, 7, 'o na andũ matikatilan’ya kĩmũtũ kwondũ woo makĩĩa, mamakiakisye ũndũ wa akw’ũ; o na andũ matikamanenga kĩkombe kya ũkiakisyo manyw’e ũndũ wa ĩthe woo kana ũndũ wa inyia woo.'),
('kam', 'JER', 16, 8, 'O na ndũkalike nyũmbanĩ ya kũvokea mboka wĩkale nao, kũya na kũnyw’a.'),
('kam', 'JER', 16, 9, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Sisya, ngaekethya vandũ vaa wasya wa kũtheka na wasya wa ũtanu, wasya wa mũtwaani na wasya wa mũtwawa, mũsyaĩtye na metho menyu mĩthenyanĩ yenyu.'),
('kam', 'JER', 16, 10, 'Na kũkeethĩwa, yĩla wĩmon’ya andũ aa ndeto ii syonthe, na makakũkũlya, Nũndũ wa kĩ Yeova ũtũneeneete ũthũku ũũ w’onthe? Kana ũthũku witũ nĩ mwaũ? Kana naĩ yaitũ ĩla twamũvĩtanĩsye Yeova Ngai waitũ nĩ myaũ?'),
('kam', 'JER', 16, 11, 'Nĩvo ĩndĩ ũkamea, Yeova easya, Nĩkwĩthĩwa aaĩthe menyu nĩmandiĩte, na kũatĩĩa ngai ingĩ, na kwithũkũma, na kwithaitha, na kũndia, na matyaakwata mĩao yakwa;'),
('kam', 'JER', 16, 12, 'na inyw’ĩ nĩmwĩkĩte ũthũku kũvĩtũka aaĩthe menyu; nũndũ, sisya, nĩmũendaa kĩla mũndũ akĩatĩĩa ngũlũ sya ngoo yake nthũku, kwondũ wa ũu mũimbĩthukĩĩasya:'),
('kam', 'JER', 16, 13, 'kwondũ wa ũu ngamwĩkya mume nthĩ ĩno mũende nthĩ ĩla mũtaamanya, inyw’ĩ kana aaĩthe menyu; na kw’o mũkathũkũmĩa ngai ingĩ mũthenya na ũtukũ; nũndũ ndikamwon’ya ũseo.'),
('kam', 'JER', 16, 14, 'Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla kũikaneenwa ĩngĩ, O tondũ Yeova wĩ thayũ, ũla waumisye ana ma Isilaeli Misili;'),
('kam', 'JER', 16, 15, 'ĩndĩ, O tondũ Yeova wĩ thayũ, ũla waetie ana ma Isilaeli kũmaumya nthĩ yĩ ngalĩ ya ĩũlũ, na kuma nthĩ syonthe vala wamalũngĩlĩĩlye. Na ngamaete ĩngĩ nthĩ yoo ĩla nanengie aaĩthe moo.'),
('kam', 'JER', 16, 16, 'Sisya, ngatũmana atei aingĩ na makamatea, easya ũu Yeova; na ĩtina ngatũmana asyĩmi aingĩ, na makamasyĩma maume kĩla kĩĩmanĩ, na kuma kĩla kalĩma, na kuma mĩvatĩnĩ ya mavia.'),
('kam', 'JER', 16, 17, 'Nũndũ metho makwa nĩmasyaĩĩtye mĩendele yoo yonthe; ti mĩvithe ũthyũnĩ wakwa, o na ũthũku woo ti mũvithe ũndũ ndatonya kũwona.'),
('kam', 'JER', 16, 18, 'Na ũndũ wa mbee ngaĩva ũthũku woo na naĩ syoo kũndũ kwĩlĩ, nũndũ nĩmathũkĩtye nthĩ yakwa na simba sya syĩndũ syoo imenetwe, na kusũsya ũtiĩwa wakwa na mothatyo moo.'),
('kam', 'JER', 16, 19, 'Ame Yeova, vinya wakwa, na ngome yakwa yĩ vinya, na wĩvitho wakwa mũthenya wa thĩna, mbaĩ ikooka vala ũĩ kuma itulunĩ sya nthĩ, na ikasya, Aaĩthe maitũ matyaatiĩwa kĩndũ no movũngũ, o kĩndũ kya mana na syĩndũ ila ite na ũuno.'),
('kam', 'JER', 16, 20, 'Mũndũ akeeseũvĩsya ngai, nasyo ti ngai?'),
('kam', 'JER', 16, 21, 'Kwondũ wa ũu, sisya, ngamamanyĩthya, no ĩvinda yĩĩ yĩmwe ngamamanyĩthya kw’oko kwakwa na vinya wakwa; na makamanya kana syĩtwa yakwa nĩ Yeova.'),
('kam', 'JER', 17, 1, 'Naĩ ya Yuta nĩandĩkĩtwe na kĩandĩki kya kĩaa, na mũthya wa kavila ka salitonyi: nĩvanĩtwe masengeanĩ ma ngoo syoo, na mbyanĩ sya ithembeo syenyu;'),
('kam', 'JER', 17, 2, 'yĩla syana syoo ililikanaa ithembeo syasyo na Aselimu yasyo vakuvĩ na mĩtĩ mĩũ tũlĩmanĩ tũtũlu.'),
('kam', 'JER', 17, 3, 'We kĩĩma kyakwa kĩ mũũndanĩ, nganengane syĩthĩwe mũtavo syĩndũ syaku, na ũthwii waku w’onthe mwie, na kũndũ kwaku kũtũlu, nũndũ wa naĩ, mĩvakanĩ yaku yonthe.'),
('kam', 'JER', 17, 4, 'Naku, o we mwene, ũkaeka ũtiĩwa waku ũla nakũnengie; na ngakũthũkũmĩthya amaitha maku wĩ nthĩ ĩla ũtesĩ: nũndũ nĩmwakanĩtye ũthatunĩ wakwa mwaki ũla ũkakanaa tene na tene.'),
('kam', 'JER', 17, 5, 'Ũũ nĩw’o Yeova ũnũkwasya: Nũumanĩwe mũndũ ũla ũĩkĩĩaa mũndũ, na kwĩkwatya mwĩĩ wĩthĩwe kw’oko kwake, na ngoo yake ĩimũeka Yeova.'),
('kam', 'JER', 17, 6, 'Nũndũ akeethĩwa ailyĩ ta mũtĩ weũnĩ mwĩtĩku matu, na ndakona yĩla ũseo wĩũka, ĩndĩ akekalaa kũndũ kwenzeku weũnĩ, nthĩ yĩ mũnyũ ĩtatwĩe andũ.'),
('kam', 'JER', 17, 7, 'Nĩ mũathime mũndũ ũla ũmũĩkĩĩaa Yeova, na Yeova nĩwe wĩkwatyo wake.'),
('kam', 'JER', 17, 8, 'Nũndũ akeethĩwa ta mũtĩ ũvandĩtwe ũtee wa manzĩ, ũla ũtambũũkasya mĩi yaw’o vakuvĩ na ũsĩ, na ndũkakĩa yĩla ũvyũvu wĩũka, ĩndĩ ĩtũ yaw’o yĩkeethĩwa yĩũ; na ndũkemakĩa mwaka wa mũnyao, kana kũeka kũsyaa ũsyao.'),
('kam', 'JER', 17, 9, 'Ngoo nĩ ngengani kũvĩtũka syĩndũ syonthe, na nĩ nthũku ki: nũũ ũtonya kũmĩmanya?'),
('kam', 'JER', 17, 10, 'Nyie, Yeova, nĩmanthaa kĩlilikanonĩ, na kũtataa ngoo, nĩnengae kĩla mũndũ o kwĩanana na mĩendele yake, kwĩanana na ũsyao wa meko make.'),
('kam', 'JER', 17, 11, 'Ta ngwae ĩla ĩvw’ĩkĩaa matumbĩ ala ĩtaalekya, now’o ũilyĩ ũla wĩyũmbanĩasya mothwii, na ti nzĩanĩ yaĩle; mĩthenyanĩ yake katĩ makamũtia, na mũminũkĩlyo wake akeethĩwa ndia.'),
('kam', 'JER', 17, 12, 'Kĩvĩla kya ũsumbĩ kya ndaĩa, kyũkĩlĩtw’e kuma mwambĩlĩlyonĩ, nĩkyo vandũ vatheu vaitũ.'),
('kam', 'JER', 17, 13, 'We Yeova, wĩkwatyo wa Isilaeli, onthe ala makũtiaa makasonokw’a. Ala mandiaa nyie makaandĩkwa kũũ nthĩ, nĩkwĩthĩwa nĩmamũtiĩte Yeova, nthongo ya manzĩ ma thayũ.'),
('kam', 'JER', 17, 14, 'Mbosya, ame Yeova, na ngavoeka; ndangĩĩa, na ngatangĩĩka: nũndũ nue ndaĩa yakwa.'),
('kam', 'JER', 17, 15, 'Sisya, nĩmeũngũlya, Ndeto ya Yeova ĩĩva? Nĩyũke oyu.'),
('kam', 'JER', 17, 16, 'Ngali ĩ yakwa ndyaaĩkalaata kwĩyumya wĩanĩ wa mũĩthi ngĩkũatĩĩa; o na ndyaenda mũthenya wa woo; naku nĩwĩsĩ: kĩla kyaumie ilomonĩ syakwa kyaĩ mbee wa ũthyũ waku.'),
('kam', 'JER', 17, 17, 'Ndũkethĩwe ũtĩsyo kwakwa: nue wĩvitho wakwa mũthenya wa ũthũku.'),
('kam', 'JER', 17, 18, 'Masonokw’e ala manthĩnasya, ĩndĩ ndikaasonokw’e: asu mateve, ĩndĩ ndikaateve; maetee mũthenya wa ũthũku, noimananga na wanangĩko kũndũ kwĩlĩ.'),
('kam', 'JER', 17, 19, 'Ũũ nĩw’o Yeova wambĩie: Enda, ũũngame mbingĩlonĩ ya ana ma andũ, vala asumbĩ ma Yuta malikĩlaa, na kumaalĩla, o na mbingĩlonĩ syonthe sya Yelusaleme;'),
('kam', 'JER', 17, 20, 'noimatavya, Ĩw’ai ndeto ya Yeova, inyw’ĩ asumbĩ ma Yuta, na Yuta yonthe, na onthe ala matwĩe Yelusaleme, ala mũlikĩlaa mbingĩlonĩ ii:'),
('kam', 'JER', 17, 21, 'Ũũ nĩw’o Yeova ũnũkwasya, Ĩsũvĩei, mũikakue mũio mũthenya wa savato, o na kũlikĩlya mbingĩlonĩ sya Yelusaleme;'),
('kam', 'JER', 17, 22, 'o na mũikaumaalye mũio nyũmbanĩ syenyu mũthenya wa savato, kana kũtethya wĩa o na wĩva: ĩndĩ vathan’yai mũthenya wa savato wĩthĩwe mũtheu, o tondũ nameaĩe aaĩthe menyu.'),
('kam', 'JER', 17, 23, 'Ĩndĩ matyaaĩthukĩĩsya, kana kũtea kũtũ kwoo, ĩndĩ moomya ngingo syoo, matikew’e na kwosa ũmanyĩsyo.'),
('kam', 'JER', 17, 24, 'Na kũkeethĩwa, easya Yeova, ethĩwa nĩmũmbĩthukĩĩasya mũno, atĩ mũtikatwae mũio o na wĩva na kũlikĩlya mbingĩlonĩ sya ndũa ĩno mũthenya wa savato, ĩndĩ kũvathan’ya mũthenya wa savato wĩthĩwe mũtheu, mũtekũtethya wĩa o na wĩva mũthenya ũsu;'),
('kam', 'JER', 17, 25, 'nĩvo ĩndĩ kũkalikĩla mbingĩlonĩ sya ndũa ĩno asumbĩ na anene me mbee ũsumbĩnĩ makĩkala kĩvĩlanĩ kya ũsumbĩ kya Ndaviti, makuĩtwe nĩ makasya na matũlĩte mbalasi, mo, na anene moo me mbee ũsumbĩnĩ, aũme ma Yuta, na ala matwĩe Yelusaleme; na ndũa ino ĩkekalaa tene na tene.'),
('kam', 'JER', 17, 26, 'Na makooka kuma ndũanĩ sya Yuta, na kuma ndeenĩ sya Yelusaleme, na kuma nthĩ ya Mbenyamini, na kuma nthĩ ndindimalu, na kuma nthĩ yĩ tũlĩma, na kuma ngalĩ ya Ĩtheo, makĩete nthembo sya kũvĩvw’a, na nthembo sya kũtonywa, na nthembo sya mũtu, na ũvumba, na makĩete nthembo sya mũvea, nyũmbanĩ ya Yeova.'),
('kam', 'JER', 17, 27, 'Ĩndĩ ethĩwa mũkalea kũmbĩthukĩĩsya, atĩ mũvathan’ye mũthenya wa savato wĩthĩwe mũtheu, na mũtikakue mũio na kũlikĩlya mbingĩlonĩ sya Yelusaleme mũthenya wa savato; nĩvo ĩndĩ ngakan’ya mwaki mbingĩlonĩ syayo, na ũkavĩvya nyũmba nene mbanakavye sya Yelusaleme, na ndũkavoeka.'),
('kam', 'JER', 18, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, ĩkyasya,'),
('kam', 'JER', 18, 2, 'Ũkĩla, ũende nyũmbanĩ ya mũmbi, na ngakwĩw’ĩthĩsya ndeto syakwa vu.'),
('kam', 'JER', 18, 3, 'Na ĩndĩ natheea nyũmbanĩ ya mũmbi, na, sisya, aĩ vo akĩtethya wĩa wake ndĩanĩ.'),
('kam', 'JER', 18, 4, 'Na yĩla mbisũ ĩla wombie ya yũmba yanangĩkĩe kw’okonĩ kwa mũmbi, nĩwamyũmbie ĩngĩ yĩthĩwe mbisũ ĩngĩ, o tondũ mũmbi wonie nĩ ũseo kũmyũmba.'),
('kam', 'JER', 18, 5, 'Na ĩndĩ ndeto ya Yeova yambũkĩa, ĩkyasya,'),
('kam', 'JER', 18, 6, 'We nyũmba ya Isilaeli, nditonya kwĩka nenyu ta mũmbi ũũ? Easya ũu Yeova. Sisya, ta yũmba kw’okonĩ kwa mũmbi, now’o mũilyĩ kw’okonĩ kwakwa, inyw’ĩ nyũmba ya Isilaeli.'),
('kam', 'JER', 18, 7, 'O kavinda kala nganeena ũvoo wa mbaĩ, na ũvoo wa ũsumbĩ, kũkũa, na kũomboa na kwananga;'),
('kam', 'JER', 18, 8, 'ethĩwa mbaĩ ĩsu ĩla nĩneenete ũvoo wayo, ĩkeethyũũa na kũtia ũthũku wayo, ngeetũnga ũndũ wa ũthũku ũla nasũanĩe kũmĩka.'),
('kam', 'JER', 18, 9, 'Na o kavinda kala nganeena ũvoo wa mbaĩ, na ũvoo wa ũsumbĩ, kũwaka na kũvanda;'),
('kam', 'JER', 18, 10, 'ethĩwa makeeka ũla nonaa wĩ ũthũku, mateĩw’a wasya wakwa, nĩvo ĩndĩ ngeetũnga ũndũ wa ũseo ũla naisye ngameka.'),
('kam', 'JER', 18, 11, 'Yu kwondũ wa ũu, neena na aũme ma Yuta, na ala matwĩe Yelusaleme, ũkĩmea, Ũũ nĩw’o Yeova ũnĩkwasya: Sisya, nĩngũseũvya ũthũku ĩũlũ wenyu, na kũmũsũanĩĩa ũndũ: syokai yu kĩla ũmwe kuma mũendelenĩ wake mũthũku, na kũlũngalya mĩendele yenyu o na meko menyu.'),
('kam', 'JER', 18, 12, 'Ĩndĩ measya, Nĩ mana; nũndũ tũkaenda tũatĩĩe mũsũanĩo maitũ ene, na tũkeeka kĩla ũmwe aatĩĩe ngũlũ sya ngoo yake nthũku.'),
('kam', 'JER', 18, 13, 'Kwondũ wa ũu Yeova easya atĩĩ: Yu kũlyai mbaĩnĩ, ũla wewie maũndũ mailyĩ aa; mwĩĩtu mũtheu wa Isilaeli nĩwĩkĩte ũndũ ũthũku mũno.'),
('kam', 'JER', 18, 14, 'Ĩa ya Levanoni yĩkathela kuma ĩvianĩ yĩ mũũndanĩ? Kana manzĩ mathithu ala matheeaa kuma kũasa makang’ala?'),
('kam', 'JER', 18, 15, 'Nũndũ andũ makwa nĩmolĩtwe ninyie, nĩmaitoeesye ngai sya ũvũngũ ũvani; na nĩmalulutĩkĩtw’e nzĩanĩ syoo, nzĩanĩ sya tene tene, maende na nzĩa sya myathũko, nzĩa ĩte nzeũvye;'),
('kam', 'JER', 18, 16, 'kũtw’ĩkĩthya nthĩ yoo ũseng’yo, na ya kũtimbwa ĩndĩ yonthe; kĩla mũndũ wĩmĩvĩtĩla akaseng’a, na kũthingithya mũtwe wake.'),
('kam', 'JER', 18, 17, 'Ngamanyaĩĩkya mbee wa mũmaitha o ta kũnyaĩĩkya na kĩseve kya wumĩlonĩ wa syũa; ngamon’ya mũongo, na ti ũthyũ, mũthenya wa wanangĩko woo.'),
('kam', 'JER', 18, 18, 'Nĩvo ĩndĩ maisye, Ũkai, tũmũsamĩe Yelemia; nũndũ mĩao ndĩkaa kwa mũthembi, kana ũtao kwa ala oĩ, kana ndeto kwa mwathani. Ũkai, tũmũkũne na ũĩmĩ, na tũikethukĩĩsye ndeto syake o na syĩva.'),
('kam', 'JER', 18, 19, 'Mbĩw’a, ame Yeova, noyĩthukĩĩsya wasya wa ala mekũtetan’ya nakwa.'),
('kam', 'JER', 18, 20, 'Ũthũku ũkaĩvwa vandũ va ũseo? Nũndũ nĩmenzĩe thayũ wakwa ĩima. Lilikana ũndũ naũngamie mbee waku nĩneene ũseo kwondũ woo, nĩthyũũe ũthilĩku waku wume kwoo.'),
('kam', 'JER', 18, 21, 'Kwondũ wa ũu nengane syana syoo yũanĩ, na kwinengane vinyanĩ wa ũvyũ; na iveti syoo syĩthĩwe ite na syana, na syĩthĩwe ndiwa; na aũme moo nĩmoawe nĩ kĩkw’ũ, na anake moo nĩmoawe na ũvyũ kaũnĩ.'),
('kam', 'JER', 18, 22, 'Kĩĩo nĩkĩw’ĩke kuma nyũmbanĩ syoo, yĩla wĩmaetee nguthu na kĩthũlũmũko; nũndũ nĩmenzĩte ĩima mangwatye, na kũvitha itei ingwatye maũũ.'),
('kam', 'JER', 18, 23, 'Ĩndĩ, Yeova, we nĩwĩsĩ kũsaman’ya kwoo kw’onthe ũndũ wa kũmbũaa; ndũkamaekee ũthũku woo, o na ndũkavute naĩ yoo ũeke kũmyona; ĩndĩ mavalũkw’e mbee waku; meke ũu ĩvinda ya ũthatu waku.'),
('kam', 'JER', 19, 1, 'Ũũ nĩw’o Yeova waisye, Enda ũthooe sũva wa yũmba wũmbĩtwe nĩ mũmbi, noyosa amwe ma atumĩa ma andũ, na ma atumĩa ma athembi;'),
('kam', 'JER', 19, 2, 'na ũyumaala ũende mwandanĩ wa mwana wa Inomu, ũla wĩ vala valikĩlawa mbingĩlonĩ yĩtaw’a Alisithi, na kũtavanĩsya kw’o ndeto ila ngakũtavya:'),
('kam', 'JER', 19, 3, 'na kwasya, Ĩthukĩĩsyei ndeto ya Yeova, inyw’ĩ asumbĩ ma Yuta, na ala mũtwĩe Yelusaleme: Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, Sisya ngavaetee vandũ va ũthũku, o ũla ũkawĩw’a matũ make makasĩĩlĩla.'),
('kam', 'JER', 19, 4, 'Nĩkwĩthĩwa nĩmandiĩte, na matw’ĩkĩthĩtye vandũ vaa va mũeni, na kwitoeesya vaa ngai ingĩ ũvani, ila mataamanya, mo na aaĩthe moo na asumbĩ ma Yuta, na kusũsya vandũ vaa na nthakame ya ala mate na ĩvĩtyo,'),
('kam', 'JER', 19, 5, 'na nĩmakĩte kũndũ kũtũlu kwa Mbaali, mamũvĩvĩsye Mbaali ana moo mwakinĩ methĩwe nthembo sya kũvĩvw’a; ũndũ ũla ndaawĩaa, kana kũneena, o na ndwaalika kĩlilikanonĩ kyakwa;'),
('kam', 'JER', 19, 6, 'kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla vandũ vaa vatiketwa ĩngĩ Tovethi, kana Mwanda wa mwana wa Inomu, ĩndĩ vaketwa Mwanda wa Kũaĩa.'),
('kam', 'JER', 19, 7, 'Na ngatw’ĩkĩthĩsya mosũanĩo ma Yuta na ma Yelusaleme ma mana vaa; na ngamavalũkya na ũvyũ mbee wa amaitha moo, na kwa moko ma ala mamanthaa mathayũ moo: na simba syoo nganengane syĩthĩwe lĩu wa nyũnyi sya yayaya, na wa nyamũ sya nthĩ.'),
('kam', 'JER', 19, 8, 'Na ngatw’ĩkĩthya ndũa ĩno ũseng’yo, na ya kũtimbwa; kĩla mũndũ ũla wĩmĩvĩtĩla akaseng’a na kũmĩtimba nũndũ wa mothĩn’yo onthe mayo.'),
('kam', 'JER', 19, 9, 'Na ngatuma maya nyama sya mĩĩ ya ana moo na eĩtu moo; na makaya kĩla ũmwe nyama sya mũnyanyae, kũtw’ĩkanĩw’anĩ na ũnyamaonĩ, ũla amaitha moo, na ala mamanthaa mathayũ moo, makamanyamasya naw’o.'),
('kam', 'JER', 19, 10, 'Nĩvo ĩndĩ ũkoaa sũva ũsu atumĩa mene ala maendie vamwe naku,'),
('kam', 'JER', 19, 11, 'na kũmatavya, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: O tondũ mũndũ wũaa kĩndũ kyũmbĩtwe nĩ mũmbi, kĩla kĩtatonya kũmbwa ĩngĩ kĩthĩwe kĩima, o ta ũu ngooaa andũ aa na ndũa ĩno; na makenzĩa andũ nthĩ kũu Tovethi, kũvika vathela vandũ va kwĩnzĩa nthĩ.'),
('kam', 'JER', 19, 12, 'Ũũ nĩw’o ngaveka vandũ vaa, na ala matwĩe vo, o na kũtw’ĩkĩthya ndũa ĩno ta Tovethi, easya ũu Yeova:'),
('kam', 'JER', 19, 13, 'na nyũmba sya Yelusaleme, na nyũmba sya asumbĩ ma Yuta, ila syavukiw’e, ikethĩwa ta vandũ va Tovethi, o nyũmba syonthe ila ialanĩ syasyo matoeesye nguthu yonthe ya ĩtunĩ ũvani, na kwĩtĩkĩsya ngai ingĩ nthembo sya kũnyuwa.'),
('kam', 'JER', 19, 14, 'Na ĩndĩ Yelemia auma Tovethi, vala Yeova wamũtũmie athanĩe vo; na aũngama nza ya nyũmba ya Yeova, na amea andũ onthe:'),
('kam', 'JER', 19, 15, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, Sisya, ngamĩetee ndũa ĩno na tũtũla twayo tw’onthe ũthũku w’onthe ũla natavanisye ĩũlũ wayo; nĩkwĩthĩwa nĩmoomisye ngingo syoo, matikew’e ndeto syakwa.'),
('kam', 'JER', 20, 1, 'Vasuli, mwana wa mũthembi Imeli, ũla waĩ mũnene nyũmbanĩ ya Yeova, eew’a Yelemia akyathana maũndũ asu.'),
('kam', 'JER', 20, 2, 'Nĩvo ĩndĩ Vasuli wamũkũnie mwathani Yelemia, na amwoveea maũũ mĩtĩnĩ ĩla yaĩ mbingĩlonĩ ya ngalĩ ya ĩũlũ ya Mbenyamini, ĩla yaĩ nyũmbanĩ ya Yeova.'),
('kam', 'JER', 20, 3, 'Na kweethĩwa ũnĩ ũsu, Vasuli amumya Yelemia mĩtĩnĩ ĩsu. Na ĩndĩ Yelemia amwĩa, Yeova ndaaĩta syĩtwa yaku Vasuli, ĩndĩ Makoli‐misavivu.'),
('kam', 'JER', 20, 4, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Sisya, ngakũtw’ĩkĩthya ũtĩsyo kwaku mwene, na kwa anyanyau onthe; na makavalũkw’a na ũvyũ wa amaitha moo, na metho maku makoona ũu; na nganengane Yuta onthe kw’okonĩ kwa mũsumbĩ wa Mbaviloni, na akamatava amatwae Mbaviloni, na kũmoaa na ũvyũ.'),
('kam', 'JER', 20, 5, 'O na ũndũ ũngĩ nganengane ũthwii w’onthe wa ndũa ĩno, na motandĩthyo onthe mayo, na syĩndũ syonthe syayo syĩ vata mũno, ĩĩ, mothwii onthe maie ma asumbĩ ma Yuta nganengane kw’okonĩ kwa amaitha moo; na makamatava mũtavo, na kũmatwaa, na kũenda nao Mbaviloni.'),
('kam', 'JER', 20, 6, 'Naku, Vasuli, na onthe ala matwĩe nyũmbanĩ yaku mũkaenda mwĩ atave; na ũkavika Mbaviloni, na ũkakw’ĩa kw’o, na ũkenzĩwa nthĩ kw’o, we, na anyanyau onthe, ala wamathanĩe ũvũngũ.'),
('kam', 'JER', 20, 7, 'Ame Yeova, nĩwambĩsũvie, nakwa neesũvĩka; wĩ vinya kwĩ nyie, naku nĩwakĩlya vinya: nĩnatw’ĩka wa kũthekeewa mũthenya w’onthe, kĩla mũndũ nũkũmbũĩa ngũĩ.'),
('kam', 'JER', 20, 8, 'Nũndũ o yĩla ngũneena, nĩngũkĩlya wasya; nĩngwasya mũno, Ũng’endu na wanangĩko! Nĩkwĩthĩwa ndeto ya Yeova nĩtw’ĩkĩthaw’a kwakwa kĩvũthya na ntheko, mũthenya w’onthe.'),
('kam', 'JER', 20, 9, 'Na ethĩwa nĩasya, Ndikamũweta, kana kũneena ĩngĩ syĩtwanĩ yake nĩvo ngoonĩ yakwa ve ta mwaki mwakanu ũvingĩĩtwe mavĩndĩnĩ makwa, na nĩ na mĩnoo ũndũ wa kũmĩĩsya, o na nditonya kwĩsiĩĩa.'),
('kam', 'JER', 20, 10, 'Nũndũ nĩnĩw’ĩte nzukũ sya aingĩ, ũtĩsyo ngalĩ syonthe. Anyanyawa onthe ala twĩsene ala masiasya mone ũvalũko wakwa measya, Mwilĩĩlei, naitũ tũkamũneenea, nokwĩthĩwa akakusĩka, na tũkamũkĩlya vinya, na kwĩĩvanĩsya ũndũ wake.'),
('kam', 'JER', 20, 11, 'Ĩndĩ Yeova e vamwe nakwa ta ũla wĩ vinya mũno na wa kũtĩsya: kwondũ wa ũu ala manthĩnasya makalulutĩka, na matikakĩlya vinya; makasonokw’a vyũ, nũndũ matyaaĩka na ũĩ, o kwanangĩwa ndaĩa tene na tene kũla kũtakola nongi.'),
('kam', 'JER', 20, 12, 'Ĩndĩ, ame Yeova wa nguthu, ũla ũtataa ala alũngalu, ũla wonaa ngoo na kĩlilikano, none ũĩvanĩsya waku kwoo; nũndũ nĩnakwonisye ũvoo wakwa.'),
('kam', 'JER', 20, 13, 'Mwinĩei Yeova, mũkathei Yeova; nũndũ nũvonoketye thayũ wa mũthĩni kũmumya kw’okonĩ kwa eki ma naĩ.'),
('kam', 'JER', 20, 14, 'Nũumanĩwe mũthenya ũla nasyaiwe: mũthenya ũla mwaitũ wanzyaie ndũkaathimwe.'),
('kam', 'JER', 20, 15, 'Naumanĩwe mũndũ ũla wamũtwaĩe nau ũvoo, akĩmwĩa, Nũsyaĩwe kavĩsĩ; akĩmũtanĩthya mũno.'),
('kam', 'JER', 20, 16, 'Na mũndũ ũsu nĩethĩwe ta ndũa ila Yeova waing’uthũlile, na ndaalyũla: nake nĩew’e kĩĩo kĩoko, na mbu katambanga;'),
('kam', 'JER', 20, 17, 'nĩkwĩthĩwa ndaambũaa nĩ ĩvunĩ; na nĩw’o ĩndĩ mwaitũ ethĩwa aĩ mbũa yakwa, na ĩvu yake yĩkekalaa.'),
('kam', 'JER', 20, 18, 'Nũndũ wa kĩ naumie ĩvunĩ none thĩna na woo, nĩ kana mĩthenya yakwa yanangĩke na nthoni?'),
('kam', 'JER', 21, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, yĩla mũsumbĩ Nzetekia watũmie kwake Vasuli mwana wa Malikiya, na Nzevania mwana wa mũthembi Maaseia, makĩmwĩa,'),
('kam', 'JER', 21, 2, 'Nĩngũkwĩsũva ũtũkũlĩlye kwa Yeova; nũndũ Nevukatilesa mũsumbĩ wa Mbaviloni nũnũũkwatya kaũ naitũ: nokwĩthĩwa Yeova akatwĩka kwĩanana na mawĩa make onthe ma ũseng’ya, nĩ kana aende kuma kwitũ.'),
('kam', 'JER', 21, 3, 'Nĩvo ĩndĩ Yelemia wameie, Ũũ nĩw’o mũkamwĩa Nzetekia:'),
('kam', 'JER', 21, 4, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Sisya, ngathyũũa mĩio ya kaũ ĩla yĩ mokonĩ menyu, ĩla mũkũkita mũsumbĩ wa Mbaviloni nayo, na Akalitei ala meũmũtwĩkanĩsya, me ũtee wa maũvai; na ngamyũmbanĩsya ndũanĩ katĩ.'),
('kam', 'JER', 21, 5, 'Nakwa mwene ngokita nenyu na kw’oko kũtambũũku na kw’oko kwĩ vinya, nĩ na ũthatu, na ũthilĩku, na woo mwingĩ.'),
('kam', 'JER', 21, 6, 'Na ngakũna andũ ala matwĩe ndũanĩ ĩno, mũndũ vamwe na nyamũ: makooawa nĩ mũimũ mũthũku.'),
('kam', 'JER', 21, 7, 'Na Yeova easya, Ĩtina wa ũu nganengane Nzetekia mũsumbĩ wa Yuta, na athũkũmi make, na andũ, o ala metialw’a ndũanĩ ĩno nĩ mũimũ, na ũvyũ, na yũa, kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, na mokonĩ ma amaitha moo, na mokonĩ ma ala mamanthaa mathayũ moo: nake akamakũna kwa kũmatemanga na ũvyũ; ndakamaeka, kana kũmew’ĩa ĩnee kana teĩ.'),
('kam', 'JER', 21, 8, 'Na ũkatavya andũ aa, Ũũ nĩw’o Yeova ũnũkwasya: Sisya, nĩngwia mbee wenyu nzĩa ya thayũ na nzĩa ya kĩkw’ũ.'),
('kam', 'JER', 21, 9, 'Ũla wĩĩkala ndũanĩ ĩno akooawa na ũvyũ, na yũa, na mũimũ; ĩndĩ ũla wĩumaala na kwĩnengane kwa Akalitei ala meũmũtwĩkanĩsya, ũsu akekala thayũ, na thayũ wake ũkeethĩwa mũtavo wake.'),
('kam', 'JER', 21, 10, 'Nũndũ nĩnamĩlutĩle ndũa ĩno ũthyũ wakwa nĩmĩke ũthũku, na ti ũseo, easya ũu Yeova: ĩkanenganwe kw’okonĩ kwa mũsumbĩ wa Mbaviloni, nake akamĩvĩvya na mwaki.'),
('kam', 'JER', 21, 11, 'Na ĩw’ai ndeto ya Yeova ũndũ wa nyũmba ya mũsumbĩ wa Yuta:'),
('kam', 'JER', 21, 12, 'Yeova easya atĩĩ, We nyũmba ya Ndaviti, silai ũsili wa katĩ kĩoko, na kũmumya ũla ũvutĩtwe kw’okonĩ kwa ũla ũthĩnasya, ũthilĩku wakwa ndũkese kumĩla ta mwaki, na kwakana ũndũ mũndũ o na wĩva ũtatonya kũvosya, nũndũ wa ũthũku wa meko menyu.'),
('kam', 'JER', 21, 13, 'Sisya, nĩ ũndũ naku, we ũla wĩkalaa mwandanĩ, ĩvia yĩ ũiĩnĩ, easya ũu Yeova; inyw’ĩ ala mwĩasya, Nũũ ũla wĩtũtheeea ithyĩ? Kana nũũ wĩlika mawĩkalonĩ maitũ?'),
('kam', 'JER', 21, 14, 'Na ngamũkũna kwĩanana na ũsyao wa meko menyu, easya ũu Yeova; na ngakan’ya mwaki mũtitũnĩ wake, naw’o ũkavĩvya kyonthe kĩla kĩthyũlũlũkĩte ngalĩ syonthe.'),
('kam', 'JER', 22, 1, 'Ũũ nĩw’o Yeova waisye: Theea nyũmbanĩ ya mũsumbĩ wa Yuta ũneenee ndeto ĩno vo,'),
('kam', 'JER', 22, 2, 'na kwasya, Ĩthukĩĩsye ndeto ya Yeova, we mũsumbĩ wa Yuta, ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ kya Ndaviti, we, na athũkũmi maku, na andũ maku ala mavotelaa mbingĩlonĩ ii.'),
('kam', 'JER', 22, 3, 'Ũũ nĩw’o Yeova ũnũkwasya: Silai sila wa katĩ na mũlũngalu, na kũmumya ũla ũvutĩtwe kw’okonĩ kwa ũla ũthĩnasya: na ndũkamwĩke ũthũku, kana kũmũng’endea, mwĩkali wa ũeninĩ, kana ũla wakw’ĩĩwe nĩ ĩthe, kana mũndũ mũka ndiwa; o na ndũketĩkye nthakame ĩte na ĩvĩtyo vandũ vaa.'),
('kam', 'JER', 22, 4, 'Nũndũ ethĩwa mwĩĩka ũndũ ũsu ki, nĩvo ĩndĩ kũkavotela mbingĩlonĩ sya nyũmba ĩno asumbĩ mekalĩle kĩvĩla kya ũsumbĩ kya Ndaviti, maikuwa nĩ makasya na matũlĩte mbalasi, we, na athũkũmi make, na andũ make.'),
('kam', 'JER', 22, 5, 'Ĩndĩ ethĩwa nĩmũũlea kwĩthukĩĩsya ndeto ii, nyie mwene nĩngwĩvĩta kana nyũmba ĩno ĩkatw’ĩka ĩanzo, easya ũu Yeova.'),
('kam', 'JER', 22, 6, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya kwondũ wa nyũmba ya mũsumbĩ wa Yuta: We wĩ Ngileati kwakwa, mũthya wa Levanoni; ĩndĩ vate ndĩi ngakũtw’ĩkĩthya weũ, ndũa ite andũ.'),
('kam', 'JER', 22, 7, 'Nakwa ngaseũvya ala makakwanangaa, kĩla ũmwe na mĩio yake ya kaũ; na makatemanga mĩkũũ yaku mĩseo, na kũmĩkya mwakinĩ.'),
('kam', 'JER', 22, 8, 'Na mbaĩ nyingĩ ikavĩtĩla ndũa ĩno, na makakũlan’ya kĩla ũmwe na mũtũi wake, Nũndũ wa kĩ Yeova wĩkĩte ndũa ĩno nene ũu?'),
('kam', 'JER', 22, 9, 'Nĩvo ĩndĩ makasũngĩa, Nũndũ nĩmatiie ũtianĩo wa Yeova Ngai woo, na kũthaitha ngai ingĩ, na kwithũkũma.'),
('kam', 'JER', 22, 10, 'Mũikaĩĩe ũla mũkw’ũ, kana kũmũmetea; ĩndĩ ĩai mũno kwondũ wa ũla wĩenda kũasa; nũndũ ndakasyoka ĩngĩ, kana kwona ĩngĩ nthĩ ĩla wasyaĩwe.'),
('kam', 'JER', 22, 11, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, ũndũ wa Salumu mwana wa Yosia, mũsumbĩ wa Yuta, ũla wasumbĩkie vandũ va Yosia ĩthe wake, ũla waumie vandũ vaa: Ndakasyoka vo ĩngĩ;'),
('kam', 'JER', 22, 12, 'ĩndĩ vandũ vala mamũtwaie e mũtave, akakw’ĩa o vo, na ndakona nthĩ ĩno ĩngĩ.'),
('kam', 'JER', 22, 13, 'Woo nĩ wake ũla wakaa nyũmba yake na nzĩa ĩte ndũngalu, na tũsũmba twake na nzĩa ĩte ya katĩ; ũla wĩtethasya na ũthũkũmi wa mũtũi wake mana, na ndeũmũnenga ĩtuvi yake;'),
('kam', 'JER', 22, 14, 'ũla ũkwasya, Ngeeyakĩa nyũmba nthanthau na tũsũmba twĩ ũthei, na kwĩvũthũĩa mbũthi; nayo nĩ nzeũvye nthĩnĩ na mbwaũ sya mĩkũũ, na kũvakwa langi mũtune mũno.'),
('kam', 'JER', 22, 15, 'Ũkasumbĩka, nũndũ nũkũtata na vinya kwĩvĩtũkya mbee na mbwaũ sya mĩkũũ? Au ndaaya na kũnyw’a, na kwĩka katĩ o na ũlũngalu? Nĩvo ĩndĩ kwaĩ ũseo kwake.'),
('kam', 'JER', 22, 16, 'Nĩwasilanasya ngya na ala athĩni; nĩvo ĩndĩ kwaĩ ũseo. Ũũ tiw’o kũmanya nyie? Easya ũu Yeova.'),
('kam', 'JER', 22, 17, 'Ĩndĩ metho maku na ngoo yaku ndĩ ũndũ yendaa ate o ĩtomo yaku, na kwĩtĩkya nthakame ĩte na ĩvĩtyo, na kũnyamasya, na kũng’endea, na kwĩkaa ũu.'),
('kam', 'JER', 22, 18, 'Kwondũ wa ũu Yeova easya ũndũ wa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta: Matikamũmetea, makyasya, Aa mwana‐a‐ia! Kana, Aa mwĩĩtu‐a‐ia! Matikamũmetea, makyasya, Aa mwĩaĩi! Kana, Aa ũnene wake!'),
('kam', 'JER', 22, 19, 'Akenzĩwa nthĩ tondũ ĩng’oi yĩnzĩawa nthĩ, kũkusw’a na kwĩkw’a ũtee wa mbingĩlo sya Yelusaleme.'),
('kam', 'JER', 22, 20, 'Ambata ũende Levanoni, ũĩe; na ũkĩlya wasya waku ku Mbasani, na kũĩa wĩ Avalimu; nũndũ endwa maku onthe nĩ anangĩku.'),
('kam', 'JER', 22, 21, 'Nĩnaneenie naku kwingĩvanĩ kwaku; ĩndĩ we wasya, Ndikethukĩĩsya. Ũũ nĩw’o mwĩkalĩle waku kuma wana waku, kana ndwĩthukĩĩasya wasya wakwa.'),
('kam', 'JER', 22, 22, 'Kĩseve kĩkaya aĩthi maku onthe, na endwa maku makaenda me atave: nĩ w’o ĩndĩ ũkasonoka na kũthokoanw’a ũndũ wa ũthũku waku w’onthe.'),
('kam', 'JER', 22, 23, 'We ũla ũtwĩe Levanoni, ũla wakaa ndala yaku mĩtĩnĩ ya mĩkũũ, ko ũkethĩwa wa kwĩw’ĩwa tei mũno yĩla woo ũkakũkĩa, woo ta wa mũndũ mũka akyaũnya!'),
('kam', 'JER', 22, 24, 'Yeova easya, O tondũ nĩ thayũ, o na kethĩwa Konia mwana wa Yeoiakimu mũsumbĩ wa Yuta nĩ ngome ya ũvana ũsiĩlo kw’okonĩ kwakwa kwa aũme, ngakwĩkya kũasa;'),
('kam', 'JER', 22, 25, 'na ngakũnengane kw’okonĩ kwa ala mamanthaa thayũ waku, na kw’okonĩ kwa ala ũmakĩaa, o kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, na kw’okonĩ kwa Akalitei.'),
('kam', 'JER', 22, 26, 'Na ngakwĩkya ũtee, vamwe na mwenyu ũla wakũsyaie, nthĩ ĩngĩ, ĩla mũtaasyaĩwa; na mũkakw’ĩa kw’o.'),
('kam', 'JER', 22, 27, 'Ĩndĩ nthĩ ĩla ngoo yoo yendaa kũmĩsyokea, ku maikasyoka.'),
('kam', 'JER', 22, 28, 'Mũndũ ũsu Konia nĩ mũio mũvũthye ũla mwanangĩku? Nĩ mũio ũla ũte mũndũ wa kũtanĩa? Nũndũ wa kĩ mekĩtw’e nza, we na ũsyao wake, na kwĩkw’a nthĩ ĩla matesĩ?'),
('kam', 'JER', 22, 29, 'We nthĩ, nthĩ, nthĩ, ĩthukĩĩsye ndeto ya Yeova.'),
('kam', 'JER', 22, 30, 'Ũũ nĩw’o Yeova ũnũkwasya, Andĩkai mũndũ ũũ nde kana, mũndũ ũla ũtakaathimĩka mĩthenyanĩ yake; nũndũ vati mũndũ nongi wa ũsyao wake ũla ũkaathimĩka kwĩkala kĩvĩlanĩ kya Ndaviti, kana kũsumbĩka nthĩnĩ wa Yuta.'),
('kam', 'JER', 23, 1, 'Woo nĩ wa aĩthi ala manangaa na kũnyaĩĩkasya malondu ma kĩsesi kyakwa! Easya ũu Yeova.'),
('kam', 'JER', 23, 2, 'Kwondũ wa ũu Yeova, Ngai wa Isilaeli, ũnũũmaneenea aĩthi ala maĩthasya andũ makwa atĩĩ: Nĩmwanyaĩĩkisye ndĩthya yakwa, na kũmĩlũngya, na mũtyaaenda kũmĩsisya; sisya, ngamũetee ũthũku wa meko menyu, easya ũu Yeova.'),
('kam', 'JER', 23, 3, 'Na ngoomban’ya ala matialile ma ndĩthya yakwa kũmaumya nthĩ syonthe vala namalũngĩlĩĩlye, na kũmaete ĩngĩ syengonĩ syoo; na makasyaana na kwingĩva.'),
('kam', 'JER', 23, 4, 'Na ngamaiĩa aĩthi, ala makamaĩthya; na matikakĩa ĩngĩ, kana kũteva, o na vai ũmwe ũkanyivĩwa, easya ũu Yeova.'),
('kam', 'JER', 23, 5, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngamũkĩlĩlya Ndaviti Ũvonge mũlũngalu, na akasumbĩka e mũsumbĩ na kwĩka na ũĩ, na akasila sila wa katĩ na mũlũngalu e ĩ nthĩ.'),
('kam', 'JER', 23, 6, 'Mĩthenyanĩ yake Yuta akatangĩĩwa, na Isilaeli akekala ate na mũisyo; na syĩtwa yake yĩla ũketwa nĩ yĩĩ: Yeova ũlũngalu witũ.'),
('kam', 'JER', 23, 7, 'Yeova easya atĩĩ, Kwondũ wa ũu, sisya, mĩthenya nĩyũkĩte ĩla matakasya ĩngĩ, O tondũ Yeova wĩ thayũ, ũla waumisye ana ma Isilaeli nthĩ ya Misili;'),
('kam', 'JER', 23, 8, 'ĩndĩ, O tondũ Yeova wĩ thayũ, ũla waetie na kũtongoesya ũsyao wa nyũmba ya Isilaeli kuma nthĩ yĩ ngalĩ ya ĩũlũ, na kuma nthĩ syonthe ila namalũngĩlĩĩlye. Na makatũa nthĩ yoo ene.'),
('kam', 'JER', 23, 9, 'Ũndũ wa athani. Ngoo yakwa nĩtũlĩkĩle nthĩnĩ wakwa, mavĩndĩ makwa onthe nĩmeũthingithanga; nĩilyĩ ta mũndũ ũnyw’ĩte, na ta mũndũ ũla ũmilĩtwe nĩ mbinyu, nũndũ wa Yeova, na nũndũ wa ndeto syake ntheu.'),
('kam', 'JER', 23, 10, 'Nũndũ nthĩ nĩyusũĩte ilaalai; nĩkwĩthĩwa nũndũ wa kĩumo nthĩ nĩmetaa; isesi sya weũ nĩsyũmĩte. Nzĩa yoo nĩ nthũku, na ũtonyi woo ti wa w’o;'),
('kam', 'JER', 23, 11, 'nũndũ mwathani na mũthembi me elĩ nĩ avuku; ĩĩ, nĩnonete ũthũku woo nyũmbanĩ yakwa, easya ũu Yeova.'),
('kam', 'JER', 23, 12, 'Kwondũ wa ũu nzĩa yoo ĩkeethĩwa kwoo ta kũndũ kũtendeu kĩvindunĩ: makalũngĩlĩĩlwa, na kũvalũka o kw’o; nũndũ ngamaetee ũthũku, o mwaka wa kũsilĩlwa kwoo, easya ũu Yeova.'),
('kam', 'JER', 23, 13, 'Nakwa nĩnonete ũtumanu athaninĩ ma Samalia; nĩmathanie na syĩtwa ya Mbaali, na kũmavĩtĩthya andũ makwa Isilaeli.'),
('kam', 'JER', 23, 14, 'Na ĩngĩ nĩnonete ũndũ wa ũtĩsya mũno athaninĩ ma Yelusaleme: nĩmekaa ũlaalai, na kũendaa na movũngũ; na nĩmekĩaa vinya moko ma eki ma naĩ, ũkethĩa vai ũmwe ũsyoka kuma ũthũkunĩ wake: nao onthe nĩmatw’ĩkĩte kwakwa ta Sotomo, na ala matwĩe kw’o ta Ngomola.'),
('kam', 'JER', 23, 15, 'Kwondũ wa ũu Yeova wa nguthu easya ũndũ wa athani: Sisya, ngamaathĩsya kĩndũ kĩ ũũ, na kũmanyw’ĩthya manzĩ me ũũ ta nyongo; nũndũ kũlea kũkĩa Ngai nĩkumĩte athaninĩ ma Yelusaleme, kũkathi nthĩ yonthe.'),
('kam', 'JER', 23, 16, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Mũtikethukĩĩsye ndeto sya athani ala mamwathanĩaa inyw’ĩ; nĩmamũmanyĩasya maũndũ ma mana; nĩmaneenaa woni wa ngoo syoo ene, na ti kuma kanyw’anĩ wa Yeova.'),
('kam', 'JER', 23, 17, 'Mavinda onthe nĩmamatavasya ala mambũthasya, Yeova nũneenete atĩĩ, Mũkeethĩwa na mũuo; na kĩla mũndũ ũla ũendaa akĩatĩĩa ngũlũ sya ngoo yake mwene mamũtavasya, Vai ũthũku ũkakũkwata.'),
('kam', 'JER', 23, 18, 'Nũndũ nũũ ũla waũngamie nzamanĩ ya Yeova, amanye na kwĩw’a ndeto yake? Nũũ ũla wasũvĩie ndeto yakwa, na kũmĩthukĩĩsya?'),
('kam', 'JER', 23, 19, 'Sisya, kĩuutani kya Yeova, nĩkyo ũthilĩku wake, nĩkyumĩte, ĩĩ, kĩuutani kya kĩlingi: kĩkatolekela mĩtwenĩ ya ala athũku.'),
('kam', 'JER', 23, 20, 'Ũthatu wa Yeova ndũkasyoka, mũvaka amina kwĩka, na mũvaka amina kwĩanĩsya kwenda kwa ngoo yake: mĩthenya ya mũminũkĩlyo mũkamanya vyũ.'),
('kam', 'JER', 23, 21, 'Ndyaatũma athani aa, ĩndĩ nĩmasembie: ndyaaneena nao, ĩndĩ nĩmathanie.'),
('kam', 'JER', 23, 22, 'Ĩndĩ kethĩwa nĩmaũngamie nzamanĩ yakwa, nĩvo ĩndĩ methĩwa mamew’ĩthisye andũ makwa ndeto syakwa, na kũmaalyũla matie mũendele woo mũthũku, na ũthũku wa meko moo.'),
('kam', 'JER', 23, 23, 'Yeova easya atĩĩ, Nyie nĩ Ngai wĩ vakuvĩ, na ti Ngai wĩ kũasa?'),
('kam', 'JER', 23, 24, 'Mũndũ nũtonya kwĩvitha mawĩvithonĩ ũndũ ndamwona? Easya ũu Yeova. Nyie ndyusũĩte ĩtu na nthĩ? Easya ũu Yeova.'),
('kam', 'JER', 23, 25, 'Nĩnĩw’ĩte ũndũ athani maneenete, ala mathanaa movũngũ syĩtwanĩ yakwa, makyasya, Nĩnĩotete ndoto, nĩnĩotete ndoto.'),
('kam', 'JER', 23, 26, 'Ũũ ũkethĩwa ngoonĩ sya athani ala mathanaa movũngũ, o athani ma ũkengani wa ngoo syoo ene kũvika ĩndĩĩ?'),
('kam', 'JER', 23, 27, 'Ala masũanĩaa kũlĩthya andũ makwa syĩtwa yakwa kwondũ wa ndoto syoo ila matavasya kĩla mũndũ mũtũi wake, o tondũ aaĩthe moo moolilwe nĩ syĩtwa yakwa kwondũ wa Mbaali.'),
('kam', 'JER', 23, 28, 'Mwathani ũla wĩ na ndoto, natavan’ye ndoto; na ũla wĩ na ndeto yakwa, naneene ndeto yakwa na kĩthito. Ũa nĩ kĩndũ kyaũ vala ve nganũ? Ekũlya ũu Yeova.'),
('kam', 'JER', 23, 29, 'Ndeto yakwa ndĩilyĩ ta mwaki? Ekũlya ũu Yeova; na ta kĩiva kĩla kĩkanyangaa ĩvia ilungu?'),
('kam', 'JER', 23, 30, 'Kwondũ wa ũu, sisya, nĩ na ũndũ na athani ala moyaa ndeto syakwa kĩla ũmwe kwa mũtũi wake, easya ũu Yeova.'),
('kam', 'JER', 23, 31, 'Sisya, nĩ na ũndũ na athani, easya Yeova, ala maneenaa na nĩmĩ syoo, na kwasya, We nũnũkwasya.'),
('kam', 'JER', 23, 32, 'Sisya, nĩ na ũndũ na ala mathanaa wathani wa ndoto sya ũvũngũ, easya Yeova, na kwitavan’ya, na kũvĩtĩthya andũ makwa kwondũ wa movũngũ moo, na kwĩkathĩĩa kwoo kwa mana: ĩndĩ ndyaamatũma, kana kũmeaĩa; o nao matimaunaa andũ aa nongi, easya ũu Yeova.'),
('kam', 'JER', 23, 33, 'Na yĩla andũ aa, kana mwathani, kana mũthembi, mekũkũlya, makyasya Mũio wa Yeova nĩ mwaũ? Nĩvo ĩndĩ wĩmea, Mũio wĩva! Ngamũveta vyũ, easya ũu Yeova.'),
('kam', 'JER', 23, 34, 'Na ũndũ wa mwathani, na mũthembi, na andũ ala makasya, Mũio wa Yeova, ngasilĩla mũndũ ũsu vamwe na nyũmba yake.'),
('kam', 'JER', 23, 35, 'Ũũ nĩw’o mũkaneena kĩla ũmwe na mũtũi wake, na kĩla ũmwe na mwana‐a‐ĩthe, Yeova asũngĩĩte ata? Na, Yeova, aneenete ata?'),
('kam', 'JER', 23, 36, 'Na mũikawete mũio wa Yeova ĩngĩ: nũndũ ndeto ya kĩla mũndũ mwene ĩkeethĩwa mũio wake; nĩmwelelũkĩtye ndeto sya Ngai ũla wĩ thayũ, sya Yeova wa nguthu Ngai waitũ.'),
('kam', 'JER', 23, 37, 'Ũũ nĩw’o wĩkũlya mwathani, Yeova akũsũngĩĩte ata? Na, Yeova aneenete ata?'),
('kam', 'JER', 23, 38, 'Ĩndĩ ethĩwa mwĩasya, Mũio wa Yeova; kwondũ wa ũu Yeova easya atĩĩ: Nũndũ nĩmũneenaa ndeto ĩno, Mũio wa Yeova; nakwa nĩnĩtũmanĩte kwenyu, ngyasya, Mũtikaneene, Mũio wa Yeova;'),
('kam', 'JER', 23, 39, 'kwondũ wa ũu, sisya, ngoolwa nĩ inyw’ĩ vyũ, na ngamũveta, vamwe na ndũa ĩla namũnengie inyw’ĩ na aaĩthe menyu, mume mbee wakwa:'),
('kam', 'JER', 23, 40, 'na ngamũetee kũvũthw’a kwa tene na tene, na nthoni sya mavinda onthe, ĩla itakola.'),
('kam', 'JER', 24, 1, 'Yeova ambon’ya, na, sisya, ikavũ ilĩ sya makũyũ syiĩtwe mbee wa ĩkalũ ya Yeova, ĩtina wa Nevukatilesa mũsumbĩ wa Mbaviloni kũtava Yekonia mwana wa Yeoiakimu, mũsumbĩ wa Yuta, na anene me mbee ũsumbĩnĩ ma Yuta, vamwe na ndũĩka na atwii, kũmaumya Yelusaleme, na kũmatwaa Mbaviloni.'),
('kam', 'JER', 24, 2, 'Kĩkavũ kĩmwe kyaĩ na makũyũ maseo mũno, ta makũyũ ala mambaa kwĩw’a; na kĩkavũ kĩla kĩngĩ kyaĩ na makũyũ mathũku mũno, ala mataĩka, nũndũ wa kũthũka kwamo.'),
('kam', 'JER', 24, 3, 'Nĩvo ĩndĩ Yeova wangũlilye, Wĩona kyaũ, Yelemia? Nakwa nasya, Makũyũ; ala makũyũ maseo, maseo mũno; na ala mathũku, mathũku mũno, ala mataĩka, nũndũ wa kũthũka kwamo.'),
('kam', 'JER', 24, 4, 'Na ndeto ya Yeova yambũkĩa, ĩkyasya,'),
('kam', 'JER', 24, 5, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya: Ta makũyũ aa maseo, now’o ngasisya kwondũ wa ũseo ala atave ma Yuta, ala namalũngilye maume vaa mathi nthĩ ya Akalitei.'),
('kam', 'JER', 24, 6, 'Nũndũ ngamaketeea na metho makwa kwondũ wa ũseo, na ngamaete ĩngĩ nthĩ ĩno: na ngamaka, na ti kũmaomboa; na ngamavanda, na ti kũmakũa.'),
('kam', 'JER', 24, 7, 'Na ngamanenga ngoo ya kũmanya nyie, atĩ ninyie Yeova: na makeethĩwa andũ makwa, na ngeethĩwa Ngai woo; nũndũ makanzyokea na ngoo yoo yonthe.'),
('kam', 'JER', 24, 8, 'Ũũ nĩw’o Yeova ũnũkwasya, O tondũ ala makũyũ mathũku mataĩka nũndũ wa kũthũka kwamo, now’o nganengane Nzetekia mũsumbĩ wa Yuta, na anene make me mbee ũsumbĩnĩ, na ũtialo wa Yelusaleme, ala matialĩte nthĩ ĩno, na ala matwĩe nthĩ ya Misili,'),
('kam', 'JER', 24, 9, 'ngamanengane kwondũ wa ũthũku mekangw’e kũũ na kũũ mosumbĩnĩ onthe ma nthĩ; methĩwe ũvũthyo na nthimo, ntheko na kĩumo, kũndũ kw’onthe kũla ngamalũngĩlĩĩlya.'),
('kam', 'JER', 24, 10, 'Na ngatũma ũvyũ, na yũa, na mũimũ, katĩ woo, kũvika yĩla meanangwa kumw’a nthĩ ĩla namanengie mo na aaĩthe moo.'),
('kam', 'JER', 25, 1, 'Ndeto ĩla yamũkĩe Yelemia ũndũ wa andũ onthe ma Yuta, mwaka wa kana wa kũsumbĩka kwa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta (mwaka ũsu nĩw’o wa mbee wa kũsumbĩka kwa Nevukatilesa mũsumbĩ wa Mbaviloni),'),
('kam', 'JER', 25, 2, 'ĩla mwathani Yelemia wamatavisye andũ onthe ma Yuta, na onthe ala matwĩe Yelusaleme, akyasya:'),
('kam', 'JER', 25, 3, 'Kuma mwaka wa ĩkũmi na ĩtatũ wa Yosia mwana wa Amoni, mũsumbĩ wa Yuta, o na kũvika mũnthĩ ũũ, myaka ĩsu mĩongo ĩlĩ na ĩtatũ, ndeto ya Yeova nĩyambũkĩaa, nakwa naneenaa nenyu, ngyũkĩla tene na ngĩneena; ĩndĩ mũtyaaĩthukĩĩsya.'),
('kam', 'JER', 25, 4, 'Na Yeova nũtũmĩte kwenyu athũkũmi make onthe athani, akyũkĩla tene na kũmatũma (ĩndĩ mũtyaaĩthukĩĩsya, kana kũtea matũ menyu mwĩw’e),'),
('kam', 'JER', 25, 5, 'akyasya, Syokai yu kĩla ũmwe kuma mũendelenĩ wake mũthũku, na kuma ũthũkunĩ wa meko menyu, mwĩkalae nthĩ ĩla Yeova wamũnengie inyw’ĩ na aaĩthe menyu, kuma tene na kũvika tene na tene;'),
('kam', 'JER', 25, 6, 'na mũikaatĩĩe ngai ingĩ mwithũkũme, na kwithaitha, na mũikanthatye na wĩa wa moko menyu, nakwa ndikamwĩka ũndũ ũthũku.'),
('kam', 'JER', 25, 7, 'Ĩndĩ mũtyaambĩthukĩĩsya, easya ũu Yeova; nĩ kana mũnthatye na wĩa wa moko menyu na kwĩyĩka ũthũku.'),
('kam', 'JER', 25, 8, 'Kwondũ wa ũu Yeova wa nguthu easya atĩĩ: Nĩkwĩthĩwa mũtyaaĩthukĩĩsya ndeto syakwa,'),
('kam', 'JER', 25, 9, 'sisya, ngatũmana na kwosa mĩvĩa yonthe ya ngalĩ ya ĩũlũ, easya Yeova, na ngatũmana kwa Nevukatilesa mũsumbĩ wa Mbaviloni, mũthũkũmi wakwa, na kũmaete mokite na nthĩ ĩno, na ala mamĩtwĩe, na mbaĩ ii syonthe ithyũlũlũkĩte ngalĩ syonthe; na ngasyananga vyũ, na kwitw’ĩkĩthya ũseng’yo, na sya kũtimbwa, na mawanangĩko ma tene na tene.'),
('kam', 'JER', 25, 10, 'O na ũndũ ũngĩ ngaumya kwoo wasya wa kũtheka na wasya wa ũtanu, wasya wa mũtwaani na wasya wa mũtwawa, wasya wa mavia ma kũthia, na kyeni kya taa.'),
('kam', 'JER', 25, 11, 'Na nthĩ ĩno yonthe ĩkeethĩwa nthei, na ũseng’yo; na mbaĩ ii ikathũkũma mũsumbĩ wa Mbaviloni myaka mĩongo mũonza.'),
('kam', 'JER', 25, 12, 'Na kũkeethĩwa, myaka mĩongo mũonza yathela, ngakũna mũsumbĩ wa Mbaviloni, na mbaĩ ĩsu, na nthĩ ya Akalitei, ũndũ wa ũthũku wayo, na ngamĩtw’ĩkĩthya nthei tene na tene, easya ũu Yeova.'),
('kam', 'JER', 25, 13, 'Ngamĩetee nthĩ ĩsu ndeto syakwa syonthe ĩla naneenie ĩũlũ wayo, o ũndũ w’onthe ũla ũandĩkĩtwe ĩvukunĩ yĩĩ, ũla Yelemia wathanĩe mbaĩ syonthe,'),
('kam', 'JER', 25, 14, 'Nũndũ mbaĩ nyingĩ na asumbĩ anene. Makamatw’ĩkĩthya ngombo, o mo; na ngamaĩva kwĩanana na meko moo, na kwĩanana na wĩa wa moko moo.'),
('kam', 'JER', 25, 15, 'Nũndũ ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũũmbĩa: Osa kĩkombe kĩĩ kya mbinyu ya ũthilĩku kĩ kw’okonĩ kwakwa, na kũnyw’ĩthya mbaĩ syonthe ila ngakũtũma kwasyo.'),
('kam', 'JER', 25, 16, 'Na makanyw’a, na kũlũa kũũ na kũũ, na kwĩthĩwa na ndũũka, nũndũ wa ũvyũ ũla ngatũma katĩ woo.'),
('kam', 'JER', 25, 17, 'Nĩvo ĩndĩ noosie kĩkombe kw’okonĩ kwa Yeova, na nainyw’ĩthya mbaĩ syonthe, ila Yeova wandũmie kwasyo:'),
('kam', 'JER', 25, 18, 'nasyo nĩ, Yelusaleme, na ndũa sya Yuta, na asumbĩ masyo, na anene me mbee ũsumbĩnĩ masyo, kwitw’ĩkĩthya maanzo, na ũseng’yo, na sya kũtimbwa, na kĩumo, o ũndũ kũilyĩ ũmũnthĩ;'),
('kam', 'JER', 25, 19, 'na Valao mũsumbĩ wa Misili, na athũkũmi make, na anene make me mbee ũsumbĩnĩ, na andũ make onthe;'),
('kam', 'JER', 25, 20, 'na andũ onthe ala mavulanĩte, na asumbĩ onthe ma nthĩ ya Usi, na asumbĩ onthe ma nthĩ ya Avilisiti, na Asikeloni, na Ngasa, na Ekiloni, na ũtialo wa Asitoti;'),
('kam', 'JER', 25, 21, 'na Etomu, na Moavi, na ana ma Amimoni;'),
('kam', 'JER', 25, 22, 'na asumbĩ onthe ma Tile, na asumbĩ onthe ma Sitoni, na asumbĩ ma kĩthama kĩla kĩ mũingo wa ũkanga;'),
('kam', 'JER', 25, 23, 'na Ndetani, na Tema, na Mbusi, na onthe ala menzetwe ithũkũ mĩtwe;'),
('kam', 'JER', 25, 24, 'na asumbĩ onthe ma Alavia, na asumbĩ onthe ma andũ mavulanĩte ala matwĩe weũnĩ;'),
('kam', 'JER', 25, 25, 'na asumbĩ onthe ma Nzimili, na asumbĩ onthe ma Elamu, na asumbĩ onthe ma Ametia;'),
('kam', 'JER', 25, 26, 'na asumbĩ onthe ma ngalĩ ya ĩũlũ, kũasa na vakuvĩ, ũmwe na ũmwe; na mosumbĩ onthe ma nthĩ, ala me ĩũlũ wa nthĩ: na mũsumbĩ wa Sesaki akanyw’a ĩtina woo.'),
('kam', 'JER', 25, 27, 'Na ũkamea, Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Nyw’ai, mũtoone, na kũtavĩka, na kũvalũka, na kũlea kũkĩla ĩngĩ, nũndũ wa ũvyũ ũla ngatũma katĩ wenyu.'),
('kam', 'JER', 25, 28, 'Na kũkeethĩwa, malea kwosa kĩkombe kw’okonĩ kwaku manyw’e, nĩvo ĩndĩ wĩmea, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: No mũvaka mũnyw’e.'),
('kam', 'JER', 25, 29, 'Nũndũ, sisya, nĩngwambĩlĩlya kwĩka ũthũku ndũanĩ ĩla yĩtanĩaw’a na syĩtwa yakwa; na inyw’ĩ mũkatĩa kũkũnwa? Mũtikaekwa mũte akũne; nũndũ ngeetĩsya andũ onthe ũvyũ ala matwĩe nthĩ, easya ũu Yeova wa nguthu.'),
('kam', 'JER', 25, 30, 'Kwondũ wa ũu mathanĩe ndeto ii syonthe, na kũmea, Yeova akaluma e ĩũlũ, na kumya wasya wake wĩkalonĩ wake mũtheu; akalumĩla na vinya ĩĩthya yake; akamokĩlĩlya onthe ala matwĩe nthĩ wasya mũnene, o ta wa ala makinyangaa nzavivũ.'),
('kam', 'JER', 25, 31, 'Kĩlonzo kĩkavika kĩtulu kya nthĩ; nũndũ Yeova e na ngananĩo na i mbaĩ; akasilĩla mĩĩ yonthe: na ũndũ wa ala athũku, akamanengane moawe na ũvyũ, easya ũu Yeova.'),
('kam', 'JER', 25, 32, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Sisya, ũthũku ũkaendaa kuma mbaĩnĩ kũvika mbaĩnĩ, na kĩuutani kĩnene kĩkookĩlw’a kuma itulunĩ sya nthĩ.'),
('kam', 'JER', 25, 33, 'Na mũthenya ũsu ala oae ma Yeova makethĩwa kuma ngalĩ ĩmwe ya nthĩ kũvika ngalĩ ĩla ĩngĩ ya nthĩ: matikametewa, kana kũmbanw’a, kana kwĩnzĩwa nthĩ; makethĩwa ta vũũ ĩũlũ wa nthĩ.'),
('kam', 'JER', 25, 34, 'Kayai, inyw’ĩ aĩthi, na kũĩa; ĩyalalyei mũunĩ, inyw’ĩ anene ma ndĩthya; nũndũ mĩthenya ya kũawa kwenyu na ya kũnyaĩĩkw’a kwenyu nĩ mĩviku ki, na mũkavalũka ta mũio mũseo.'),
('kam', 'JER', 25, 35, 'Na aĩthi matikethĩwa na nzĩa ya kũkĩĩla, kana mũnene wa ndĩthya nzĩa ya kũvonokela.'),
('kam', 'JER', 25, 36, 'Wasya wa kĩĩo kya aĩthi, na kũkaya kwa ũla mũnene wa ndĩthya! Nũndũ Yeova nũnũkwananga kĩsesi kyoo.'),
('kam', 'JER', 25, 37, 'Na syengo syaĩ na mũuo nivindĩthĩtwe nũndũ wa ũthatu mwai wa Yeova.'),
('kam', 'JER', 25, 38, 'Nũtiĩte kĩsumo kyake ta mũnyambũ; nũndũ nthĩ yoo nĩtw’ĩkĩte ũseng’yo nũndũ wa wai wa ũvyũ ũla ũthĩnasya, na nũndũ wa ũthatu wake mwai.'),
('kam', 'JER', 26, 1, 'Wambĩlĩlyo wa kũsumbĩka kwa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, ndeto ĩno yaumie kwa Yeova, ĩkĩmbĩa,'),
('kam', 'JER', 26, 2, 'Ũũ nĩw’o Yeova ũnũkwasya: Ũngama nza ya nyũmba ya Yeova, noineena na ndũa syonthe sya Yuta, ila syũkaa kũthaitha nyũmbanĩ ya Yeova, ndeto syonthe ila ngũkwĩaĩa witavye; ndũkatialye ndeto o na ĩmwe.'),
('kam', 'JER', 26, 3, 'Nokwĩthĩwa makethukĩĩsya, na kĩla mũndũ kwĩthyũũa na kũtia mũendele wake mũthũku; nĩ kana nĩalyũle ũndũ wa ũthũku ũla nĩsũanĩĩte kũmeka nũndũ wa ũthũku wa meko moo.'),
('kam', 'JER', 26, 4, 'Na wĩmea, Ũũ nĩw’o Yeova ũnũkwasya: Ethĩwa mũtikambĩthukĩĩsya, mũende mĩaonĩ yakwa, ĩla niĩte mbee wenyu.'),
('kam', 'JER', 26, 5, 'Na kwĩthukĩĩsya ndeto sya athũkũmi makwa athani, ala nĩtũmaa kwenyu, ngyũkĩla tene na kũmatũma, ĩndĩ mũtyaaĩthukĩĩsya;'),
('kam', 'JER', 26, 6, 'nĩvo ĩndĩ ngatw’ĩkĩthya nyũmba ĩno ta Silo, na kũtw’ĩkĩthya ndũa ĩno kĩumo kwa mbaĩ syonthe sya nthĩ.'),
('kam', 'JER', 26, 7, 'Na athembi na athani na andũ onthe meew’a Yelemia aineenea ndeto isu nyũmbanĩ ya Yeova.'),
('kam', 'JER', 26, 8, 'Na kweethĩwa, Yelemia amina ũneena syonthe ila Yeova wamwĩaĩe amatavye andũ onthe, athembi na athani na andũ onthe mamũkwata, makĩmwĩa, No mũvaka ũkw’e.'),
('kam', 'JER', 26, 9, 'Nũndũ wa kĩ wathana syĩtwanĩ ya Yeova, ũkyasya, Nyũmba ĩno ĩkeethĩwa ta Silo, na ndũa ĩno ĩkeethĩwa ĩanzo, ĩte mũndũ ũmĩtũa? Na andũ onthe mamũmbanĩa Yelemia nyũmbanĩ ya Yeova.'),
('kam', 'JER', 26, 10, 'Na anene me mbee ũsumbĩnĩ ma Yuta meew’a maũndũ asu, mauma nyũmbanĩ ya mũsumbĩ mambata nyũmbanĩ ya Yeova; na mekala vandũ va ũlikĩla mbingĩlonĩ nzaũ ya nyũmba ya Yeova.'),
('kam', 'JER', 26, 11, 'Nĩvo ĩndĩ athembi na athani maneenie na anene me mbee ũsumbĩnĩ na andũ onthe, makyasya, Mũndũ ũũ nĩwaĩlwe nĩ kĩkw’ũ; nĩkwĩthĩwa nũmyathanĩe ndũa ĩno, o tondũ mwĩwie na matũ menyu.'),
('kam', 'JER', 26, 12, 'Nĩvo ĩndĩ Yelemia waneenie na anene onthe me mbee ũsumbĩnĩ na andũ onthe, akyasya, Yeova nũndũmĩte nĩmyathanĩe nyũmba ĩno na ndũa ĩno ndeto syonthe ila mwĩwie.'),
('kam', 'JER', 26, 13, 'Kwondũ wa ũu lũngalyai mĩendele yenyu o na meko menyu, na kwĩw’a wasya wa Yeova Ngai wenyu; na Yeova akeealyũla ũndũ wa ũthũku ũla ũneenete kũmwĩka.'),
('kam', 'JER', 26, 14, 'Ĩndĩ ũndũ wakwa nyie, sisya, nĩ mokonĩ menyu: mbĩkai ũndũ mwĩona wĩ ũseo na wa katĩ.'),
('kam', 'JER', 26, 15, 'Ĩndĩ manyai nesa kana, ethĩwa nĩmũũmbũaa, mwĩyĩetee ene na ndũa ĩno na ala mamĩtwĩe, nthakame ĩte ĩvĩtyo; nũndũ nĩ w’o Yeova nũndũmĩte kwenyu nĩneene ndeto isu syonthe matũnĩ menyu.'),
('kam', 'JER', 26, 16, 'Nĩvo ĩndĩ anene me mbee ũsumbĩnĩ na andũ onthe matavisye athembi na athani: Mũndũ ũũ ndaĩlwe nĩ kĩkw’ũ; nũndũ nũneenete naitũ syĩtwanĩ ya Yeova Ngai waitũ.'),
('kam', 'JER', 26, 17, 'Nĩvo ĩndĩ atumĩa amwe ma nthĩ mookĩlile na maneena na ĩkomano yonthe ya andũ, makyasya,'),
('kam', 'JER', 26, 18, 'Mĩka ũla Mũmolasiti nĩwathanie mĩthenyanĩ ya Esekia mũsumbĩ wa Yuta; na aneena na andũ onthe ma Yuta, akyasya, Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Saioni ĩkenzwa ta mũũnda, na Yelusaleme ĩkatw’ĩka ivumbu, na kĩĩma kĩla kĩ ĩla nyũmba kĩkatw’ĩka ta kũndũ kũtũlu kwa mũtitũ.'),
('kam', 'JER', 26, 19, 'Esekia mũsumbĩ wa Yuta na Yuta onthe nĩmamũaie? Ndaakĩa Yeova, na kũmwĩsũva Yeova onan’ye ũseo, na Yeova eealyũla ũndũ wa ũthũku ũla waneenie kũmeka? Tweka ũu tũkameka mathayũ maitũ ũthũku mũnene.'),
('kam', 'JER', 26, 20, 'Na ĩngĩ kwaĩ mũndũ ũla wathanie syĩtwanĩ ya Yeova, Ũlia mwana wa Semaia wa ndũa ya Kiliathi‐yealimu; nake nĩwamyathanĩe ndũa ĩno na nthĩ ĩno kwĩanana na ndeto syonthe sya Yelemia.'),
('kam', 'JER', 26, 21, 'Na yĩla mũsumbĩ Yeoiakimu, vamwe na ngũmbaũ syake syonthe, na anene onthe me mbee ũsumbĩnĩ, meewie ndeto syake, mũsumbĩ nĩwatatie kũmũaa; ĩndĩ Ulia eew’a ũu, akĩa, na aindũka, na athi Misili.'),
('kam', 'JER', 26, 22, 'Na mũsumbĩ Yeoiakimu atũma andũ Misili, nao nĩ aa, Elinathani mwana wa Akivoli, na andũ amwe vamwe nake, na mathi Misili;'),
('kam', 'JER', 26, 23, 'na mamumya Ulia Misili, na kũmũtwaa kwa mũsumbĩ Yeoiakimu, nake amũaa na ũvyũ, na ekya kimba kyake vala vaĩ mbũa sya andũ mate ndaĩa.'),
('kam', 'JER', 26, 24, 'Ĩndĩ kw’oko kwa Aikamu mwana wa Savani kwaĩ vamwe na Yelemia, nĩ kana matikamũnengane kw’okonĩ kwa andũ mamũae.'),
('kam', 'JER', 27, 1, 'Wambĩlilyo wa kũsumbĩka kwa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, ndeto ĩno yamũkĩa Yelemia kuma kwa Yeova, ĩkyasya,'),
('kam', 'JER', 27, 2, 'Ũũ nĩw’o Yeova ũnũũmbĩa: Ĩseũvĩsye tũmĩkwa na masoki, na kwĩkĩa ngingonĩ yaku;'),
('kam', 'JER', 27, 3, 'na mũtwaĩe mũsumbĩ wa Etomu, na mũsumbĩ wa Moavi, na mũsumbĩ wa ana ma Amimoni, na mũsumbĩ wa Tile, na mũsumbĩ wa Sitoni, na moko ma atũmwa ala mokaa Yelusaleme kwa Nzetekia mũsumbĩ wa Yuta:'),
('kam', 'JER', 27, 4, 'na kũmanenga wĩaĩo makatavye mavwana moo, ũkyasya, Ũũ nĩw’o Yeova wa nguthu Ngai wa Isilaeli, ũnũkwasya, Matavyei mavwana menyu atĩĩ:'),
('kam', 'JER', 27, 5, 'Nĩnoombie nthĩ, na andũ na nyamũ ila syĩ ĩũlũ wa nthĩ, kwondũ wa vinya wakwa mũnene na kwondũ wa kw’oko kwakwa kũtambũũku; na nĩnengae o ũla ngwona naĩle kũnenga.'),
('kam', 'JER', 27, 6, 'Na yu nĩnĩnenganĩte nthĩ isu syonthe kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni mũthũkũmi wakwa; o na nyamũ sya kĩtheka nĩnĩmũnengete imũthũkũme.'),
('kam', 'JER', 27, 7, 'Na mbaĩ syonthe ikamũthũkũma we, na mwana wake, na mwĩsukũũe, mũvaka yĩla ĩvinda ya nthĩ yake mwene yĩvika: nĩvo ĩndĩ mbaĩ nyingĩ na asumbĩ anene makamũtw’ĩkĩthya ngombo yoo.'),
('kam', 'JER', 27, 8, 'Na kũkeethĩwa, atĩ ũsumbĩ na mbaĩ ĩla ĩkalea kũthũkũma Nevukatilesa ũsu, mũsumbĩ wa Mbaviloni, na kũlea kwĩkĩa ngingo yayo ĩsokinĩ ya mũsumbĩ wa Mbaviloni, mbaĩ ĩsu ngamĩkũna na ũvyũ, na yũa, na mũimũ, kũvika namĩmina na kw’oko kwake, easya ũu Yeova.'),
('kam', 'JER', 27, 9, 'Ĩndĩ ũndũ wenyu, mũtikethukĩĩsye athani menyu, kana menyu ala maaũasya, kana ndoto syenyu, kana ala mathanaa maũndũ, kana aoi menyu, ala maneenaa nenyu, makĩmwĩa, Mũtikathũkũma mũsumbĩ wa Mbaviloni:'),
('kam', 'JER', 27, 10, 'nũndũ nĩmeũmwathanĩa ũvũngũ, mamumye kũasa na nthĩ yenyu, na nĩ kana nĩmũlũngye, mũkae.'),
('kam', 'JER', 27, 11, 'Ĩndĩ mbaĩ ĩla ĩkekĩa ngingo yayo ĩsokinĩ ya mũsumbĩ wa Mbaviloni, na kũmũthũkũma, mbaĩ ĩsu ngamĩeka ĩkalae nthĩ yoo ene, na makamĩnza, na kwĩkala kw’o, easya ũu Yeova.'),
('kam', 'JER', 27, 12, 'Na naneena na Nzetekia mũsumbĩ wa Yuta kwĩanana na ndeto ii syonthe, ngĩmwĩa, Ĩkĩai ngingo syenyu ĩsokinĩ ya mũsumbĩ wa Mbaviloni, na kũmũthũkũma we na andũ make, na kwĩkala thayũ.'),
('kam', 'JER', 27, 13, 'Nĩkĩ mũkw’e, we na andũ maku, nũndũ wa ũvyũ, na yũa, na mũimũ, o tondũ Yeova ũneenete ũndũ wa mbaĩ ĩla ĩtakamũthũkũma mũsumbĩ wa Mbaviloni?'),
('kam', 'JER', 27, 14, 'Na mũtikethukĩĩsye ndeto sya athani ala maneenaa nenyu, makĩmwĩa, Mũtikathũkũma mũsumbĩ wa Mbaviloni; nũndũ mamwathanĩaa ũvũngũ.'),
('kam', 'JER', 27, 15, 'Nũndũ ndyaamatũma, easya Yeova, ĩndĩ nĩmathanaa ũvũngũ syĩtwanĩ yakwa; nĩ kana nĩmũlũngye, mwae, inyw’ĩ, na athani ala mamwathanĩaa.'),
('kam', 'JER', 27, 16, 'Na ũndũ ũngĩ naneena na athembi na andũ aa onthe, ngĩmea, Ũũ nĩw’o Yeova ũnũkwasya: Mũtikethũkĩĩsye ndeto sya athani menyu ala mamwathanĩaa, makyasya, Sisya, mĩio ya nyũmba ya Yeova ĩkaetwe ĩngĩ mĩtũkĩ kuma Mbaviloni; nũndũ mamwathanĩaa ũvũngũ.'),
('kam', 'JER', 27, 17, 'Mũikamethukĩĩsye; thũkũmai mũsumbĩ wa Mbaviloni, mwĩkale thayũ: ndũa ĩno yĩalyũlĩlwa ĩanzo kĩ?'),
('kam', 'JER', 27, 18, 'Ĩndĩ ethĩwa nĩ athani, na ethĩwa ndeto ya Yeova yĩ nao, mamwĩsũve Yeova wa nguthu yu, kana mĩio ĩla ĩtialĩtw’e nyũmbanĩ ya Yeova, na nyũmbanĩ ya mũsumbĩ wa Yuta, na ku Yelusaleme, ndĩkatwawe Mbaviloni.'),
('kam', 'JER', 27, 19, 'Nũndũ ũũ nĩw’o Yeova wa nguthu ũnũkwasya ũndũ wa ituĩ, na ũndũ wa ũla ũkanga, na ũndũ wa ala matina, na ũndũ wa mĩio ĩla ĩtialĩtw’e ndũanĩ ĩno,'),
('kam', 'JER', 27, 20, 'ĩla Nevukatilesa mũsumbĩ wa Mbaviloni ũtaosa, yĩla wamũtavie Yekonia mwana wa Yeoiakimu, mũsumbĩ wa Yuta, kũmumya Yelusaleme kũthi Mbaviloni, o na anene onthe me ndaĩa ma Yuta na ma Yelusaleme;'),
('kam', 'JER', 27, 21, 'ĩĩ, ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, ũndũ wa mĩio ĩla ĩtialĩtw’e nyũmbanĩ ya Yeova, na nyũmbanĩ ya mũsumbĩ wa Yuta, na ku Yelusaleme:'),
('kam', 'JER', 27, 22, 'Ĩkatwawa Mbaviloni, nayo ĩkekala kw’o, kũvika mũthenya ũla ngamĩsĩsya, easya ũu Yeova; nĩvo ĩndĩ ngamyambatya, na kũmĩtũnga vaa.'),
('kam', 'JER', 28, 1, 'Na kweethĩwa mwaka o ũsu, wambĩlĩlyo wa kũsumbĩka kwa Nzetekia mũsumbĩ wa Yuta, mwaka wa kana, mwei wa katano, Aanania mwana wa mwathani Asulu, ũla waĩ wa ndũa ya Ngiveoni, aneenea nakwa nyũmbanĩ ya Yeova, athembi na andũ onthe me vo, akyasya,'),
('kam', 'JER', 28, 2, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũũneena, akyasya, Nĩndũlĩte ĩsoki ya mũsumbĩ wa Mbaviloni'),
('kam', 'JER', 28, 3, 'Kũithela myaka ĩlĩ mĩima ngatũnga vaa mĩio yonthe ya nyũmba ya Yeova, ĩla Nevukatilesa mũsumbĩ wa Mbaviloni waumisye vaa, akĩtwaa Mbaviloni:'),
('kam', 'JER', 28, 4, 'na ngamũete ĩngĩ vaa Yekonia mwana wa Yeoiakimu, mũsumbĩ wa Yuta, vamwe na onthe ala mataviwe ma Yuta, ala matwaiwe Mbaviloni; easya ũu Yeova; nũndũ ngatũla ĩsoki ya mũsumbĩ wa Mbaviloni.'),
('kam', 'JER', 28, 5, 'Nĩvo ĩndĩ mwathani Yelemia wamwĩie mwathani Aanania athembi me vo, na andũ onthe ala maũngamaa nyũmbanĩ ya Yeova me vo,'),
('kam', 'JER', 28, 6, 'o mwathani Yelemia asya, Ameni: Yeova eke ũu; Yeova eanĩsye ndeto syaku ila wathanie, kũete ĩngĩ kuma Mbaviloni kũvika vaa, mĩio ya nyũmba ya Yeova, na andũ onthe ala mataviwe.'),
('kam', 'JER', 28, 7, 'Ĩndĩ yu ĩthukĩĩsye ndeto ĩno ĩla ngũneena matũnĩ maku, na matũnĩ ma andũ onthe:'),
('kam', 'JER', 28, 8, 'Athani ala maĩ mbee wakwa na mbee waku kuma ĩvinda ya tene mathanĩe nthĩ nyingĩ, na mosumbĩ manene, kaũ, na ũthũku, na mũimũ.'),
('kam', 'JER', 28, 9, 'Mwathani ũla wathanaa mũuo, yĩla ndeto ya mwathani ũsu ĩkeanĩw’a, nĩvo ĩndĩ mwathani ũkamanyĩka, atĩ nĩ w’o Yeova nũmũtũmĩte.'),
('kam', 'JER', 28, 10, 'Nĩvo ĩndĩ mwathani Aanania waumisye ĩsoki ngingonĩ ya mwathani Yelemia, na ayĩtũla.'),
('kam', 'JER', 28, 11, 'Na Aanania aneena andũ onthe me vo, akyasya, Ũũ nĩw’o Yeova ũnũkwasya: O ta ũu ngatũla ĩsoki ya Nevukatilesa mũsumbĩ wa Mbaviloni, kũyumya ngingonĩ ya mbaĩ syonthe, myaka ĩlĩ mĩima ĩkĩthela. Na mwathani Yelemia eeyĩendea.'),
('kam', 'JER', 28, 12, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia, ĩtina wa mwathani Aanania kũtũla ĩsoki kũyumya ngĩngonĩ ya mwathani Yelemia, ĩkĩmwĩa,'),
('kam', 'JER', 28, 13, 'Enda, ũmũtavye Aanania, ũimwĩa, Ũũ nĩw’o Yeova ũnũkwasya: We nũtũlĩte masoki ma mĩtĩ; ĩndĩ vandũ vamo nũseũvĩtye masoki ma iaa.'),
('kam', 'JER', 28, 14, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Nĩnĩkĩĩte ĩsoki ya kĩaa ngingonĩ sya mbaĩ ii syonthe, nĩ kana mathũkũme Nevukatilesa mũsumbĩ wa Mbaviloni; no mũvaka mamũthũkũme: o na nĩnĩmũnengete nyamũ sya kĩtheka nasyo.'),
('kam', 'JER', 28, 15, 'Nĩvo ĩndĩ mwathani Yelemia wamwĩie mwathani Aanania, Ĩthukĩĩsye yu, Aanania: Yeova ndaakũtũma we; ĩndĩ naku wĩĩkĩĩthya andũ aa ũvũngũ.'),
('kam', 'JER', 28, 16, 'Kwondũ wa ũu Yeova easya atĩĩ, Sisya, ngakũlũngya wume ĩũlũ wa nthĩ: mwaka ũũ nũũkw’a, nũndũ nũmũneeneete Yeova ũng’endu.'),
('kam', 'JER', 28, 17, 'Kwondũ wa ũu mwathani Aanania nĩwakwie mwaka o ũsu mwei wa mũonza.'),
('kam', 'JER', 29, 1, 'Ii nĩsyo ndeto sya valũa ũla mwathani Yelemia e Yelusaleme watwaĩe ala matialile ma atumĩa ala mataviwe, na athembi, na athani, na andũ onthe, ala Nevukatilesa wamatwaie me atave kuma Yelusaleme kũthi Mbaviloni'),
('kam', 'JER', 29, 2, '(yĩla mũsumbĩ Yekonia, na inyia wake maminĩte kuma Yelusaleme vamwe na ala avakũe, na anene me mbee ũsumbĩnĩ ma Yuta na Yelusaleme, na ndũĩka, na atwii),'),
('kam', 'JER', 29, 3, 'na kw’oko kwa Elasa mwana wa Savani, na Ngemalia mwana wa Ilikia (ũla Nzetekia mũsumbĩ wa Yuta wamũtũmie Mbaviloni kwa Nevukatilesa mũsumbĩ wa Mbaviloni), akyasya,'),
('kam', 'JER', 29, 4, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũũmea onthe ala mataviwe, ala namatwaĩthisye me atave kuma Yelusaleme kũthi Mbaviloni:'),
('kam', 'JER', 29, 5, 'Akai nyũmba, mũsyĩkale; na vandai mĩũnda, mũye ũsyao wayo.'),
('kam', 'JER', 29, 6, 'Twaai aka, mũsyae ivĩsĩ na eĩtu; na matwaĩei ana menyu aka, na nenganei eĩtu menyu, nĩ kana masyae ivĩsĩ na eĩtu: na ingĩvĩai kw’o, na mũikaoleke.'),
('kam', 'JER', 29, 7, 'Na manthai mũuo wa ndũa vala namũtwaĩthisye mwĩ atave, na voyai Yeova kwondũ wayo; nũndũ mũuonĩ wayo inyw’ĩ mũkeethĩwa na mũuo'),
('kam', 'JER', 29, 8, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya; Athani menyu ala me katĩ wenyu, na menyu ala maaũasya, matikamũkenge; o na mũikethukĩĩsye ndoto syenyu ila mũotaa.'),
('kam', 'JER', 29, 9, 'Nũndũ nĩmamwathanĩaa movũngũ syĩtwanĩ yakwa: ndyaamatũma, easya ũu Yeova.'),
('kam', 'JER', 29, 10, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya, Myaka mĩongo mũonza yeanĩa kwondũ wa Mbaviloni, ngamũkĩa, na kwĩanĩsya ndeto yakwa nzeo kwenyu ya kũtuma mũsyoka vaa.'),
('kam', 'JER', 29, 11, 'Nũndũ nĩnĩsĩ mosũanĩo ala nĩsũanĩaa kwondũ wenyu, easya Yeova, mosũanĩo ma mũuo, na ti ma ũthũku, kũmũnenga wĩkwatyo mũminũkĩlyo wenyu.'),
('kam', 'JER', 29, 12, 'Na mũkeengaĩla, na mũkathi kũmboya, na ngamwĩthukĩĩsya.'),
('kam', 'JER', 29, 13, 'Na mũkamantha nyie, na kũmbona, yĩla mwĩmantha na ngoo yenyu yonthe.'),
('kam', 'JER', 29, 14, 'Na ngooneka kwenyu, easya Yeova, na ngamũtũnga mume kũtavwanĩ kwenyu, na ngamũmban’ya kuma mbaĩnĩ syonthe na kũndũ kw’onthe kũla namũlũngĩlĩĩlye, easya ũu Yeova; na ngamũete ĩngĩ vandũ vala natumie mumw’a vo mũtwawe mwĩ atave.'),
('kam', 'JER', 29, 15, 'Nĩkwĩthĩwa nĩmũneenete atĩĩ, Yeova nĩwatũkĩlĩlye athani ku Mbaviloni;'),
('kam', 'JER', 29, 16, 'ũũ nĩw’o Yeova ũnũkwasya ũndũ wa mũsumbĩ ũla wĩkalĩte kĩvĩlanĩ kya ũsumbĩ kya Ndaviti, na ũndũ wa andũ onthe ala matwĩe ndũanĩ ĩno, ana‐a‐ĩthe menyu ala mataathi me atave vamwe nenyu;'),
('kam', 'JER', 29, 17, 'ũũ nĩw’o Yeova wa nguthu ũnũkwasya: Sisya, ngamaetee ũvyũ, na yũa, na mũimũ, na ngamatw’ĩkĩthya ta makũyũ mathũku, ala matatonya kũĩka, nũndũ wa kũthũka kwamo.'),
('kam', 'JER', 29, 18, 'Na ngamaatĩĩa na ũvyũ, na yũa, na mũimũ, na ngamanengane mekangw’e kũũ na kũũ mosumbĩnĩ onthe ma nthĩ, methĩwe kĩumo, na ũseng’yo, na ma kũtimbwa, na ma kũvũthĩĩw’a, mbaĩnĩ syonthe vala namalũngĩlĩĩlye;'),
('kam', 'JER', 29, 19, 'nĩkwĩthĩwa matyaaĩthukĩĩsya ndeto syakwa, easya Yeova, ila natũmie athũkũmi makwa ala athani kwoo nasyo, ngyũkĩla tene, ngĩmatũma; ĩndĩ mũtyaaĩthukĩĩsya, easya ũu Yeova.'),
('kam', 'JER', 29, 20, 'Ĩthukĩĩsyei ĩndĩ ndeto ya Yeova, inyw’onthe ala mwataviwe, ala namũlũngilye mume Yelusaleme kũthi Mbaviloni.'),
('kam', 'JER', 29, 21, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, ũndũ wa Aavu mwana wa Kolaia, na ũndũ wa Nzetekia mwana wa Maaseia, ala mamwathanĩaa ũvũngũ syĩtwanĩ yakwa: Sisya, ngamanengane kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni; na akamoaa mũmene na metho menyu;'),
('kam', 'JER', 29, 22, 'na kwondũ woo kũkaneenwa kĩumo nĩ onthe ma Yuta ala mataviwe ala me Mbaviloni, makyasya, Yeova nakũtw’ĩkĩthye ta Nzetekia na ta Aavu, ala mũsumbĩ wa Mbaviloni wamavĩvisye na mwaki;'),
('kam', 'JER', 29, 23, 'nĩkwĩthĩwa nĩmekĩte ũtumanu nthĩnĩ wa Isilaeli, na kwĩka ũlaalai na iveti sya atũi moo, na nĩmaneenete ndeto sya ũvũngũ syĩtwanĩ yakwa, ila ndaameaĩa; na ninyie ũla wĩsĩ, na nĩ ngũsĩ, easyu ũu Yeova.'),
('kam', 'JER', 29, 24, 'Na ũndũ wa Semaia ũla Mũneelami ũkaneena, ũkyasya,'),
('kam', 'JER', 29, 25, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũũneena, akyasya, Nũndũ nũtwaĩte mavalũa syĩtwanĩ yaku mwene kwa andũ onthe ma Yelusaleme, na kwa Nzevania, mwana wa mũthembi Maaseia, na kwa athembi onthe, ũkyasya,'),
('kam', 'JER', 29, 26, 'Yeova nũkũtw’ĩkĩthĩtye mũthembi vandũ va mũthembi Yeoiata, nĩ kana vethĩwe anene nyũmbanĩ ya Yeova, kwondũ wa kĩla mũndũ ũla ũkwetwe nĩ ndũũka, na kwĩtw’ĩkĩthya mwene mwathani, nĩ kana ũmwĩkĩe ĩla mĩtĩnĩ ya kwoveea maũũ na ĩla ya ngingo.'),
('kam', 'JER', 29, 27, 'Kwondũ wa ũu, nũndũ wa kĩ ndwaamũkan’ya Yelemia wa Anathothi, ũla wĩtw’ĩte mwathani kwenyu,'),
('kam', 'JER', 29, 28, 'nũndũ nũtũmanĩte kwitũ Mbaviloni, akyasya, Ĩvinda ya kũtavwa nĩ ĩasa: akai nyũmba, mũsyĩkale; na vandai mĩũnda, mũĩsae ũsyao wayo?'),
('kam', 'JER', 29, 29, 'Na mũthembi Nzevania asoma valũa ũsu matũnĩ ma mwathani Yelemia.'),
('kam', 'JER', 29, 30, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia, ĩkĩmwĩa,'),
('kam', 'JER', 29, 31, 'Tũmana kwa onthe ala mataviwe, ũkyasya, Ũũ nĩw’o Yeova ũnũkwasya ũndũ wa Semaia ũla Mũneelami: Nũndũ Semaia nĩwamwathanĩe, na ndyaamũtũma, na nũmũĩkĩĩthĩtye ũvũngũ;'),
('kam', 'JER', 29, 32, 'kwondũ wa ũu Yeova easya atĩĩ, Sisya, ngakũna Semaia ũla Mũneelami, na ũsyao wake; ndakethĩwa na mũndũ mũũme wa kwĩkala andũnĩ aa, o na ndakona ũseo ũla ngameka andũ makwa, easya Yeova, nĩkwĩthĩwa nũneeneete Yeova ndeto sya ũng’endu.'),
('kam', 'JER', 30, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, ĩkyasya,'),
('kam', 'JER', 30, 2, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, akyasya, Andĩka ĩvukunĩ ndeto syonthe ila nakũtavisye.'),
('kam', 'JER', 30, 3, 'Nũndũ, sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngamatũnga andũ makwa Isilaeli na Yuta maume kũtavwanĩ kwoo, easya ũu Yeova; na ngatuma masyoka nthĩ ĩla nanengie aaĩthe moo, na makamĩmesya.'),
('kam', 'JER', 30, 4, 'Na ii nĩsyo ndeto ila Yeova waneenie ũndũ wa Isilaeli na ũndũ wa Yuta.'),
('kam', 'JER', 30, 5, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: Nĩtwĩw’ĩte wasya wa kũtetemya, wa kwĩw’ĩthya w’ĩa, na ti wa mũuo.'),
('kam', 'JER', 30, 6, 'Kũlyai yu, mwone ethĩwa mũndũ mũũme e na woo wa kũsyaa: nũndũ wa kĩ ngwona kĩla mũndũ mũũme ekwete kĩnyunyu kyake na moko make, ta mũndũ mũka akyaũn’ya, na mothyũ onthe nĩ maalyũku?'),
('kam', 'JER', 30, 7, 'A! Mũthenya ũsu nĩ mũnene, nũndũ vati ũilyĩ taw’o: naw’o nĩ ĩvinda ya thĩna wa Yakovo; ĩndĩ we akatangĩĩwa kumw’a nthĩnĩ waw’o.'),
('kam', 'JER', 30, 8, 'Na kũkethĩwa mũthenya ũsu, easya Yeova wa nguthu, ngatũla ĩsoki yake yume ngingonĩ yaku, na kũtusanga syĩndũ ila wovetwe nasyo; na aeni matikamũtw’ĩkĩthya ngombo ĩngĩ;'),
('kam', 'JER', 30, 9, 'ĩndĩ makathũkũma Yeova Ngai woo, na Ndaviti mũsumbĩ woo, ũla ngamokĩlĩlya.'),
('kam', 'JER', 30, 10, 'Kwondũ wa ũu ndũkakĩe, we Yakovo mũthũkũmi wakwa, easya ũu Yeova; o na ndũkateve, we Isilaeli: nũndũ sisya, ngakũtangĩĩa wume kũasa, na ũsyao waku kuma nthĩ ĩla watwaiwe wĩ mũtave; na Yakovo akasyoka, na akausya na kũthũmũa, na vai ũla wĩmũtĩsya.'),
('kam', 'JER', 30, 11, 'Nũndũ nyie nĩ vamwe naku, nĩkũtangĩĩe, easya ũu Yeova: nũndũ ngamina vyũ mbaĩ syonthe vala nakũnyaĩĩkisye, ĩndĩ ndikakũmina vyũ; ĩndĩ ngakũkan’ya nĩthimĩte, na ndikakũtia nongi ndaũkũnĩte.'),
('kam', 'JER', 30, 12, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: Kũkũnwa kwaku kũivoeka, na wũkite waku nĩ mũnene.'),
('kam', 'JER', 30, 13, 'Vai ũmwe wa ũkũtetea, nĩ kana wovwe makũnwa maku: ndwĩ na mĩtĩ ya kũvosya.'),
('kam', 'JER', 30, 14, 'Endwa maku onthe nĩmolĩtwe nue; maiũkũmantha: nũndũ nĩnakũkitie na wũkite wa mũmaitha, na ĩkũna ta ya ũla mwai, nũndũ wa ũthũku waku mwingĩ, nĩkwĩthĩwa naĩ syaku nĩsyongelekile.'),
('kam', 'JER', 30, 15, 'Wĩĩa ũndũ wa ĩkũna yaku nĩkĩ? Kwalw’a kwaku kũivoeka: nĩngwĩkĩte maũndũ aa nũndũ wa ũnene wa ũthũku waku, nĩkwĩthĩwa naĩ syaku nĩsyongelekile.'),
('kam', 'JER', 30, 16, 'Kwondũ wa ũu onthe ala makũĩsaa makaĩwa; na amaitha maku onthe, kĩla ũmwe, akaenda e mũtave; na ala makũtavaa makethĩwa mũtavo, na onthe ala makũsyĩmaa makethĩwa ma kũsyĩmwa.'),
('kam', 'JER', 30, 17, 'Nũndũ ngakũtũngĩa mwĩĩ mũseo, na ngakũvosya mawũkite maku, easya ũu Yeova; nĩkwĩthĩwa nĩmakwĩtie mũlũngwa, makyasya, Nĩ Saioni, ũla mũndũ o na wĩva ũtalũnganaa nake.'),
('kam', 'JER', 30, 18, 'Ũũ nĩw’o Yeova ũnũkwasya: Sisya, ngatũnga kuma kũtavwanĩ maeema ma Yakovo, na kwĩw’ĩa tei mawĩkalo make; na ndũa ĩkaakwa kalĩmanĩ o kayo, na nyũmba nene mbanakavye ĩkekalw’a kũatĩĩa mũthemba wayo.'),
('kam', 'JER', 30, 19, 'Na kw’o kũkauma mũvea na wasya wa ala matanaa: na ngamaingĩvya, na matikethĩwa avũthũ; o na ngamanenevya, na matikethĩwa anini.'),
('kam', 'JER', 30, 20, 'O na syana syoo ikethĩwa itilyĩ o ũndũ syailyĩ, na ũmbano woo ũkalũma mbee wakwa; na ngakũna onthe ala mamathĩnasya.'),
('kam', 'JER', 30, 21, 'Na mũnene woo wĩ mbee ũsumbĩnĩ akeethĩwa mũndũ wa kwoo, na ũla ũkamasumbĩka akauma kwoo; na ngamũthengeesya, nake akanthengeea: nũndũ nũũ ũla waĩ na ũkũmbaũ wa kũnthengeea? Easya ũũ Yeova.'),
('kam', 'JER', 30, 22, 'Nenyu mũkeethĩwa andũ makwa, nakwa ngeethĩwa Ngai wenyu.'),
('kam', 'JER', 30, 23, 'Sisya, kĩuutani kya Yeova, nakyo nĩ ũthilĩku wake, nĩkyumĩte, kĩuutani kyai: kĩkatolekela mĩtwenĩ ya ala athũku.'),
('kam', 'JER', 30, 24, 'Ũthatu mwai wa Yeova ndũkasyoka, mũvaka amina kwĩka, na mũvaka amina kwĩanĩsya kwenda kwa ngoo yake: mĩthenya ya mũminũkĩlyo mũkoomanya.'),
('kam', 'JER', 31, 1, 'Yeova easya, Ĩvinda yĩu ngeethĩwa Ngai wa mĩvĩa yonthe ya Isilaeli, nao makeethĩwa andũ makwa.'),
('kam', 'JER', 31, 2, 'Ũũ nĩw’o Yeova ũnũkwasya, Andũ ala matialilw’e nĩ ũvyũ nĩmoonee tei weũnĩ; O Isilaeli, yĩla naendie kũmũthũmũsya.'),
('kam', 'JER', 31, 3, 'Yeova anumĩlĩle tene, akĩmbĩa, Ĩĩ, nĩnakwendie na wendo ũtakathela: kwondũ wa ũu nĩnaũkusisye na ũseo wĩ wendo.'),
('kam', 'JER', 31, 4, 'Ngakwaka ĩngĩ, naku ũkaakĩka, we mwĩĩtu mũtheu wa Isilaeli: na ũkeeyanakavya ĩngĩ na tũthembe twaku, na kũenda mbathinĩ sya ala matanaa.'),
('kam', 'JER', 31, 5, 'Ũkavanda mĩũnda ya mĩsavivũ ĩngĩ iĩmanĩ sya Samalia; avandi makavanda, na makatanĩa ũsyao wayo.'),
('kam', 'JER', 31, 6, 'Nũndũ kũkeethĩwa mũthenya, ũla asyaĩĩsya me iĩmanĩ sya Evalaimu makokĩlya wasya na kwasya, Ukĩlai, twambate Saioni vala ve Yeova Ngai waitũ.'),
('kam', 'JER', 31, 7, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: Mwinĩei Yakovo na ũtanu, na mũkĩlĩlyei mũnene wa mbaĩ wasya mũnene: tavan’yai, taĩai, na kwasya, Ame Yeova, tangĩĩa andũ maku, ũtialo wa Isilaeli.'),
('kam', 'JER', 31, 8, 'Sisya, ngamaete kuma nthĩ yĩ ngalĩ ya ĩũlũ, na kũmomban’ya kuma itulu sya nthĩ, na vamwe nao ililinda na ala mathuaa, mũndũ mũka ũla wĩ ĩvu na ũla ũnũkwaũnya vamwe: makasyoka vaa me nguthu nene.'),
('kam', 'JER', 31, 9, 'Makooka makĩĩa; na ngamatongoesya makĩngaĩla: ngamakinyĩlya ũtee wa mbũsĩ sya manzi, nzĩanĩ ndũngalu ĩla matakalulutĩkĩla; nũndũ nyie nĩ ĩthe wa Isilaeli, na Evalaimu nĩ ĩkithathi yakwa.'),
('kam', 'JER', 31, 10, 'Inyw’ĩ mbaĩ, ĩthukĩĩsyei ndeto ya Yeova, mũmĩtavan’ye ithamanĩ ila syĩ kũasa; na kwasya, Ũla wanyaĩĩkisye Isilaeli akamũmban’ya, na kũmũsũvĩa, o tondũ mũĩthi ũsũvĩaa ndĩthya yake.'),
('kam', 'JER', 31, 11, 'Nũndũ Yeova nĩumĩtye mbovosya ũndũ wa Yakovo, na kũmwovosya kũmumya kw’okonĩ kwa ũla waĩ vinya kwĩ we.'),
('kam', 'JER', 31, 12, 'Na makooka na kwinĩa vandũ vatũlu va Saioni, na makaatĩanĩa vamwe makĩendea ũseo wa Yeova, lĩu wa mbaa ngetha, na mbinyu mbĩthĩ, na mauta, na tũtena twa mbũi na malondu na tũsaũ twa ng’ombe: na ngoo yoo ĩkethĩwa ta mũũnda mũnyithye; na matikethĩwa na kĩmako ĩngĩ nongi.'),
('kam', 'JER', 31, 13, 'Nĩvo ĩndĩ mwĩĩtu mũtheu akatana wathinĩ, na anake na atumĩa vamwe; nũndũ ngaalyũla kũmeta kwoo kwĩthĩwe ũtanu, na kũmakiakisya, na kũmatanĩthya maeke kĩmako kyoo.'),
('kam', 'JER', 31, 14, 'Na ngavũnĩthya mathayũ ma athembi na ũnou, na andũ makwa makavũnw’a na ũseo wakwa, easya ũu Yeova.'),
('kam', 'JER', 31, 15, 'Ũũ nĩw’o Yeova ũnũkwasya: Wasya nũkwĩw’ĩka Lama, kĩĩo na kĩmeto kĩ woo, Lakeli akĩĩĩa syana syake; na ndakiakiĩka ũndũ wa syana syake, nĩkwĩthĩwa iti vaĩ.'),
('kam', 'JER', 31, 16, 'Ũũ nĩw’o Yeova ũnũkwasya: Siĩĩa wasya waku ndũkaĩe, na metho maku matiketĩkye methoi; nũndũ wĩa waku ũkootuvĩwa, easya ũu Yeova; na makooka ĩngĩ kuma nthĩ ya mũmaitha.'),
('kam', 'JER', 31, 17, 'Na ve wĩkwatyo mũminũkĩlyonĩ waku, easya ũu Yeova; na syana syaku ikooka ĩngĩ mũvakanĩ wasyo.'),
('kam', 'JER', 31, 18, 'Nĩ w’o nĩnĩw’ĩte Evalaimu akĩmetea mwene, akyasya, Nĩwangũnie, nakwa nĩnakũnĩkie, ta kasaũ katamanyĩte ĩsoki: nthyũũa, nakwa ngathyũũĩka; nũndũ nue Yeova Ngai wakwa.'),
('kam', 'JER', 31, 19, 'Nĩ w’o ĩtina wa kũalyũlwa kwakwa, nĩneelilile; na ĩtina wa kũmanyĩw’a, nakũna nthũnũ yakwa: nasonoka, ĩĩ, o na kũsoomana, nikwĩthĩwa nĩnakuie kũvũthw’a kwa wana wakwa.'),
('kam', 'JER', 31, 20, 'Evalaimu nĩ mwana wakwa mwendwa? Nĩ mwana wendeeasya? Nũndũ o yĩla ngũmũneenea ndeto, nĩmũlilikanaa mũno: kwondũ wa ũu ngoo yakwa yĩ na mea nake: nditĩa kũmwĩw’ĩa tei, easya ũu Yeova.'),
('kam', 'JER', 31, 21, 'Ĩũngamĩsye movano ma mĩtĩ nzĩanĩ, ĩseũvĩsye mbwaũ sya ũkwon’ya nzĩa; elekelya ngoo yaku lelũ, o lelũ ũla waendie naw’o: ĩthyũũe, we mwĩĩtu mũtheu wa Isilaeli, ĩthyũũĩe ndũa ii syaku.'),
('kam', 'JER', 31, 22, 'Ũkaenda kũũ na kũũ kũvika ĩndĩĩ, we mwĩĩtu ũla ũsyokete na ĩtina? Nũndũ Yeova nĩwũmbĩte ũndũ mweũ kũũ nthĩ: mũndũ mũka akamwĩlingĩla mũndũ mũũme.'),
('kam', 'JER', 31, 23, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, Makaneenea kĩneeno kĩĩ ĩngĩ me nthĩ ya Yuta na ndũanĩ syayo, yĩla ngamatũnga maume kũtavwanĩ kwoo: Yeova nakũathime, we wĩkalo wa ũlũngalu, we kĩĩma kya ũtheu.'),
('kam', 'JER', 31, 24, 'Na Yuta na ndũa syonthe syake makekala vo vamwe, aĩmi, na ala mangangaa na ndĩthya sya mbũi na malondu.'),
('kam', 'JER', 31, 25, 'Nũndũ nĩnĩvũnĩthĩtye ngoo ĩla yĩ na mĩnoo, na kĩla ngoo yĩ na kĩmako nĩnĩmyusũĩtye.'),
('kam', 'JER', 31, 26, 'Na ĩndĩ naamũka, na noona; na too wakwa waĩ mũyo kwakwa.'),
('kam', 'JER', 31, 27, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngavanda nyũmba ya Isilaeli na nyũmba ya Yuta ũsyao wa mũndũ na ũsyao wa nyamũ.'),
('kam', 'JER', 31, 28, 'Na kũkeethĩwa atĩ o tondũ namasyaĩĩsye nĩ kana nĩkũe na kũomboa na kũng’uthũla na kwananga na kũthĩn’ya, now’o ngamasyaĩĩsya nĩ kana nake na kũvanda, easya ũu Yeova.'),
('kam', 'JER', 31, 29, 'Mĩthenya ĩsu matikaneena ĩngĩ, Aaĩthe nĩmaĩe nzavivũ syĩ ngaati, na maeo ma syana maya nthithi.'),
('kam', 'JER', 31, 30, 'Ĩndĩ kĩla mũndũ akakw’a ũndũ wa ũthũku wake mwene: kĩla mũndũ ũla ũĩsaa nzavivũ syĩ ngaati, maeo make makaya nthithi.'),
('kam', 'JER', 31, 31, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngatianĩa ũtianĩo mweũ na nyũmba ya Isilaeli, na nyũmba ya Yuta:'),
('kam', 'JER', 31, 32, 'ndũkethĩwa ũilyĩ ta ũtianĩo ũla natianĩe na aaĩthe moo mũthenya ũla namakwatie moko kũmaumya nthĩ ya Misili; ũtianĩo wakwa ũla maanangie, o na kau naĩ mwĩaĩi woo, easya ũu Yeova.'),
('kam', 'JER', 31, 33, 'Indĩ ũũ nĩw’o ũtianĩo ũla ngatianĩa na nyũmba ya Isilaeli ĩtina wa mĩthenya ĩsu, easya ũu Yeova: Ngeekĩa mĩao yakwa nthĩnĩ woo, na ngamĩandĩka ngoonĩ syoo; na ngeethĩwa Ngai woo, nao makeethĩwa andũ makwa.'),
('kam', 'JER', 31, 34, 'Na matikamanyĩan’ya ĩngĩ kĩla mũndũ na mũtũi wake, na kĩla mũndũ na mwana‐a‐inyia, makyasya, Mũmanye Yeova; nũndũ onthe makamanya nyie, kuma ũla mũnini woo kũvika ũla mũnene woo, easya ũu Yeova: nũndũ ngaekea ũthũku woo, na naĩ yoo ndikamĩlilikana ĩngĩ.'),
('kam', 'JER', 31, 35, 'Ũũ nĩw’o Yeova ũnũkwasya, we ũla ũnenganae syũa yĩthĩwe kyeni kya mũthenya, na motw’ĩo ma mwei na ma ndata syĩthĩwe kyeni kya ũtukũ, ũla wũkĩlasya ũkanga, ũndũ itulumo syaw’o ilitũkaa; Yeova wa nguthu nĩ syĩtwa yake:'),
('kam', 'JER', 31, 36, 'Ethĩwa motw’ĩo asu makauma mbee wakwa, easya Yeova, nĩvo ĩndĩ ũsyao wa Isilaeli naw’o ũkaeka kwĩthĩwa mbaĩ mbee wakwa tene na tene.'),
('kam', 'JER', 31, 37, 'Ũũ nĩw’o Yeova ũnũkwasya: Ethĩwa ĩtu ĩũlũ nĩyĩtonya kũthimwa, na myambĩlĩlyo ya nthĩ kũmanthwa ĩtheo, nĩvo ĩndĩ ngekya kũasa ũsyao w’onthe naw’o wa Isilaeli nũndũ wa maũndũ onthe ala meekie, easya ũu Yeova.'),
('kam', 'JER', 31, 38, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ĩ ndũa ĩkakĩwa Yeova kuma mwako mũtũlu wa mũnyoolo wa Ananeli kũvika mbingĩlo yĩ kĩkotonĩ.'),
('kam', 'JER', 31, 39, 'Na ĩkanda ya kũthima yĩkakootwa yĩlũngalĩte kũvika kĩĩma kya Ngalevu, na yĩkeelingĩla kũvika Ngoa.'),
('kam', 'JER', 31, 40, 'Na mwanda w’onthe wĩ simba na mũu, na isesi syonthe kũvika kalũsĩ ka Kitiloni, kũvika kĩkoto kya mbingĩlo ya mbalasi kwelekela wumĩlonĩ wa syũa, ũkeethĩwa mũtheu kwa Yeova; ndĩkakũwa, kana kũng’uthũlwa ĩngĩ tene na tene.'),
('kam', 'JER', 32, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova mwaka wa ĩkũmi wa kũsumbĩka kwa Nzetekia mũsumbĩ wa Yuta, naw’o waĩ mwaka wa ĩkũmi na nyanya wa kũsumbĩka kwa Nevukatilesa.'),
('kam', 'JER', 32, 2, 'Ĩvinda yĩu ita sya mũsumbĩ wa Mbaviloni nĩsyatwĩkanĩsye Yelusaleme; na mwathani Yelemia aĩ mwove nza ya kolokolo ũla waĩ nyũmbanĩ ya mũsumbĩ wa Yuta.'),
('kam', 'JER', 32, 3, 'Nũndũ Nzetekia mũsumbĩ wa Yuta aĩ anamwova, akĩkũlya, Nũndũ wa kĩ wathanaa, na kwasya, Ũũ nĩw’o Yeova ũnũkwasya, Sisya, nganengane ndũa ĩno kw’okonĩ kwa mũsumbĩ wa Mbaviloni, nake akamyosa;'),
('kam', 'JER', 32, 4, 'na Nzetekia mũsumbĩ wa Yuta ndakavonoka kuma mokonĩ ma Akalitei, ĩndĩ vate ndĩi akanenganwe kw’okonĩ kwa mũsumbĩ wa Mbaviloni, na akaneena nake kanyw’a kwa kanyw’a, na metho make makoona metho make;'),
('kam', 'JER', 32, 5, 'na akamũtwaa Nzetekia Mbaviloni, na akeethĩwa kw’o kũvika yĩla ngamũendea, easya ũu Yeova: o na ethĩwa mũkokita na Akalitei, mũikaunĩka?'),
('kam', 'JER', 32, 6, 'Na Yelemia asya, Ndeto ya Yeova yambũkĩa, ĩkyasya,'),
('kam', 'JER', 32, 7, 'Sisya, Anameli mwana wa Salumu mwendw’a ĩthe waku akakũkĩa, akĩkwĩa, Thooa mũũnda wakwa, ũla wĩ ndũanĩ ya Anathothi; nĩkwĩthĩwa nĩ ũndũ waku kũthooa, ũwovosye.'),
('kam', 'JER', 32, 8, 'Kwondũ wa ũu Anameli mwana wa mwendw’a asa ambũkĩa nĩ nza ya kolokolo kwĩanana na ndeto ya Yeova, na ambĩa, Nĩngũkwĩsũva, thooa mũũnda wakwa, ũla wĩ Anathothi, ĩla yĩ nthĩ ya Mbenyamini; nũndũ kĩanda kya ũtiĩwa nĩ kyaku, na kũwovosya nĩ kwaku; ĩthooee. Nĩvo ĩndĩ namanyie atĩ ĩsu nĩ ndeto ya Yeova.'),
('kam', 'JER', 32, 9, 'Na namũthooea Anameli mwana wa mwendw’a asa mũũnda ũla waĩ Anathothi, na namũthimĩa mbesa, o sekeli ĩkũmi na mũonza sya vetha.'),
('kam', 'JER', 32, 10, 'Nakwa naandĩka syĩtwa yakwa valũanĩ wa ũthooana, na kũwĩkĩa ũsiĩlo, na kũsyĩta ngũsĩ, na kũmũthimĩa ila mbesa kĩthiminĩ.'),
('kam', 'JER', 32, 11, 'Na ĩndĩ noosa valũa wa kũthooana, ũla weekĩĩtwe ũsiĩlo, kwĩanana na mwĩao o na kĩthĩo, na ũla ũngĩ ũtaĩ ũsiĩlo, me elĩ:'),
('kam', 'JER', 32, 12, 'na ũla valũa wa kũthooana namũnenga Mbaluku mwana wa Nelia, mwana wa Maaseia, Anameli mwana wa mwendw’a asa ene, na ngũsĩ ila syakũsĩĩe ũla valũa wa kũthooana syene, na Ayuti onthe ala mekalile nza ya kolokolo mene.'),
('kam', 'JER', 32, 13, 'Na namwĩaĩa Mbaluku mbee wamo, ngyasya,'),
('kam', 'JER', 32, 14, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Osa mavalũa aa, valũa ũũ wa kũthooana ũla wĩ na ũsiĩlo, na valũa ũũ ũte ũsiĩlo, noimekĩa kĩndũnĩ kya yũmba; nĩ kana mekale mĩthenya mingĩ.'),
('kam', 'JER', 32, 15, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Nyũmba na isesi na mĩũnda ya mĩsavivũ ikathoowa ĩngĩ nthĩ ĩno.'),
('kam', 'JER', 32, 16, 'Ĩtina wa kũmũnenga Mbaluku mwana wa Nelia valũa ũsu wa kũthooana, namũvoya Yeova, ngyasya,'),
('kam', 'JER', 32, 17, 'A! Mwĩaĩi Yeova! Sisya, nĩwoombie matu na nthĩ kwondũ wa vinya waku mũnene na kwondũ wa kw’oko kwaku kũtambũũku; vai ũndũ ũkũema,'),
('kam', 'JER', 32, 18, 'ũla wonanasya ũseo wĩ wendo kwa ngili na ngili, na kũĩvanĩsya ũthũku wa aaĩthe kĩthũinĩ kya syana syoo ĩtina woo; Ngai mũnene mwene vinya, Yeova wa nguthu nĩ syĩtwa yake;'),
('kam', 'JER', 32, 19, 'mũnene ũtaonĩ, na ũla wĩ ũtonyi wa kwĩka; ũla metho make masalukĩtye masyaĩtye mĩendele yonthe ya ana ma andũ, kũmũnenga kĩla mũndũ kwĩanana na mĩendele yake, na kwĩanana na ũsyao wa meko make;'),
('kam', 'JER', 32, 20, 'ũla wekie syama na moseng’yo nthĩ ya Misili, o na kũvika ũmũnthĩ, katĩ wa Isilaeli o na katĩ wa andũ nao; na kwĩseũvĩsya syĩtwa, o ũndũ kũilyĩ ũmũnthĩ;'),
('kam', 'JER', 32, 21, 'na waumya andũ maku Isilaeli nthĩ ya Misili na syama, na moseng’yo, na kw’oko kwĩ vinya, na kw’oko kũtambũũku, na ũtĩsyo mũnene;'),
('kam', 'JER', 32, 22, 'na wamanenga nthĩ ĩno, ĩla wamevĩtĩe aaĩthe moo kũmanenga, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ;'),
('kam', 'JER', 32, 23, 'nao malika na mamĩmesya; ĩndĩ matyaaĩthukĩĩsya wasya waku, o na matyaaenda mĩaonĩ yaku; matyaaĩka ũndũ o na ũmwe wa onthe ala wameaĩa meke: kwondũ wa ũu nũmaetee ũthũku ũũ w’onthe.'),
('kam', 'JER', 32, 24, 'Sisya, ivumbu, nĩmamyũkĩe ndũa ĩno kũmyosa; na ndũa nĩnenganĩtwe mokonĩ ma Akalitei ala meũmyũkita, nũndũ wa ũvyũ, na yũa, na mũimũ; na ũvoo ũla ũneenete nĩ mwĩanĩsye; na, sisya, naku nũkwona ũu.'),
('kam', 'JER', 32, 25, 'Naku, ame Mwĩaĩi Yeova, nĩwambĩie, Ĩthooee ũla mũũnda na mbesa, noyĩta ngũsĩ; o na kau ndũa nĩnenganĩtwe mokonĩ ma Akalitei.'),
('kam', 'JER', 32, 26, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia, ĩkyasya,'),
('kam', 'JER', 32, 27, 'Sisya, ninyie Yeova, Ngai wa mĩĩ yonthe: ve ũndũ ũnema?'),
('kam', 'JER', 32, 28, 'Kwondũ wa ũu Yeova nũnũkwasya: Sisya, nganengane ndũa ĩno mokonĩ ma Akalitei, na kw’okonĩ kwa Nevukatilesa mũsumbĩ wa Mbaviloni, nake akamyosa:'),
('kam', 'JER', 32, 29, 'na Akalitei, ala memyũkita ndũa ĩno, makooka na kũmĩkwatya ndũa ĩno mwaki, na kũmĩvĩvya, vamwe na nyũmba, ila matoeeasya Mbaali ũvani ialanĩ syasyo, na kwĩtĩa ngai ingĩ nthembo sya kũnyuwa, manthatye.'),
('kam', 'JER', 32, 30, 'Nũndũ ana ma Isilaeli na ana ma Yuta nĩmeekie ũla nonaa wĩ ũthũku ki kuma wana woo; nũndũ ana ma Isilaeli nĩmanthatĩtye kwondũ wa wĩa wa moko moo, easya ũu Yeova.'),
('kam', 'JER', 32, 31, 'Nũndũ ndũa ĩno nĩyatw’ĩkie kwakwa kĩtumi kya ũthatu wakwa na wa kũthilĩka kwakwa kuma mũthenya ũla mamyakie o na kũvika ũmũnthĩ; nĩ kana nĩmĩvete nĩeke kũmyona,'),
('kam', 'JER', 32, 32, 'nũndũ wa ũthũku w’onthe wa ana ma Isilaeli na wa ana ma Yuta, ũla meekie manthatye, mo, na asumbĩ moo, na anene moo me mbee ũsumbĩnĩ, na athembi moo, na athani moo, na andũ ma Yuta, na ala matwĩe Yelusaleme.'),
('kam', 'JER', 32, 33, 'Na nĩmambonetye mĩongo, na ti ũthyũ: o na kau nĩnamamanyĩisye, ngyũkĩla tene na ngĩmamanyĩsya, ĩndĩ matyaaĩthukĩĩsya mose ũmanyĩsyo.'),
('kam', 'JER', 32, 34, 'Ĩndĩ nĩmaiie mothatyo moo nyũmbanĩ ĩla yĩtanĩaw’a na syĩtwa yakwa, mamithũkye.'),
('kam', 'JER', 32, 35, 'Na nĩmaakie kũndũ kũtũlu kwa Mbaali, kũla kwĩ mwandanĩ wa mwana wa Inomu, mavĩtĩlye ana moo na eĩtu moo mwakinĩ kwondũ wa Moleki; ũndũ ũla ndaameaĩa, o na ndwaalika kĩlilikanonĩ kyakwa, kana meke ũthatyo ũsu, kũvĩtĩthya Yuta.'),
('kam', 'JER', 32, 36, 'Na kwondũ wa ũu Yeova, Ngai wa Isilaeli, easya, ũndũ wa ndũa ĩno, ĩla inyw’ĩ mũũneena ũndũ wayo atĩĩ: Nĩnenganĩtwe kw’okonĩ kwa mũsumbĩ wa Mbaviloni kwondũ wa ũvyũ, na yũa, na mũimũ:'),
('kam', 'JER', 32, 37, 'Sisya, ngamomban’ya kuma nthĩ syonthe, vala namalũngĩlĩĩlye ũthatunĩ wakwa, na kũthilĩkanĩ kwakwa, na woonĩ wakwa mwingĩ; na ngamaete ĩngĩ vaa, na ngamekalya mate na mũisyo.'),
('kam', 'JER', 32, 38, 'Nao makeethĩwa andũ makwa, nakwa ngeethĩwa Ngai woo:'),
('kam', 'JER', 32, 39, 'na ngamanenga ngoo ĩmwe na nzĩa ĩmwe, nĩ kana mangĩe tene na tene, mone ũseo, o na syana syoo ĩtina woo:'),
('kam', 'JER', 32, 40, 'na ngatianĩa ũtianĩo nao wa tene na tene, atĩ ndikethyũũa na kũeka kũmaatĩĩa, nĩ kana nĩmeke ũseo; na ngeekĩa kũngĩa ngoonĩ syoo, nĩ kana maikandie.'),
('kam', 'JER', 32, 41, 'Ĩĩ, ngamatanĩa nĩmeke nesa, na vate ndĩi ngamavanda nthĩ ĩno na ngoo yakwa yonthe na thayũ wakwa w’onthe.'),
('kam', 'JER', 32, 42, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: O tondũ namaetee andũ aa ũthũku ũũ w’onthe mũnene, now’o ngamaetee ũseo w’onthe ũla namathie.'),
('kam', 'JER', 32, 43, 'Na mĩũnda ĩkathoowa nthĩ ĩno ĩla mũũneena ũndũ wayo, Nĩ ĩei, ĩte mũndũ kana nyamũ; nĩnenganĩtwe mokonĩ ma Akalitei.'),
('kam', 'JER', 32, 44, 'Andũ makathooa mĩũnda na mbesa, na kũandĩka masyĩtwa moo mavalũanĩ ma kũthooana, na kũmekĩa ũsiĩlo, na kwĩta ngũsĩ, nthĩ ya Mbenyamini, na ku ndee sya Yelusaleme, na ndũanĩ sya Yuta, na ndũanĩ sya nthĩ yĩ tũlĩma, na ndũanĩ sya nthĩ ndindimalu, na ndũanĩ sya ngalĩ ya Ĩtheo: nũndũ ngamatũnga kuma kũtavwanĩ kwoo, easya ũu Yeova.'),
('kam', 'JER', 33, 1, 'Na ĩngĩ ndeto ya Yeova yamũkĩa Yelemia ĩvinda ya kelĩ, o yĩla waĩ mwove nza ya kolokolo, ĩkyasya,'),
('kam', 'JER', 33, 2, 'Ũũ nĩw’o Yeova ũnũkwasya ũla ũwĩkaa, Yeova ũla ũseũvasya kana olũlũmĩlye; Yeova nĩ syĩtwa yake:'),
('kam', 'JER', 33, 3, 'Mbĩkaĩla, na ngakũsũngĩa, na ngakwon’ya maũndũ manene, na me vinya, ũtamesĩ.'),
('kam', 'JER', 33, 4, 'Nũndũ ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya ũndũ wa nyũmba sya ndũa ĩno, na ũndũ wa nyũmba sya asumbĩ ma Yuta, ila iomboetwe syake syĩndũ sya kwĩlingan’ya nasyo ũndũ wa ivumbu na ũvyũ;'),
('kam', 'JER', 33, 5, 'yĩla mookĩte kũkita na Akalitei, na kũsyusũsya na simba sya andũ, ala nooaie nĩ mũthatu na mũthilĩku, na ũndũ wa ũthũku wa onthe nĩnĩmĩvithĩte ndũa ĩno ũthyũ wakwa:'),
('kam', 'JER', 33, 6, 'Sisya, ngamĩetee ũseo wa mwĩĩ na ũvosyo, na ngamavosya; na ngamon’ya wingĩ wa mũuo na w’o.'),
('kam', 'JER', 33, 7, 'Na ngatũnga Yuta na Isilaeli maume kũtavwanĩ kwoo, na ngamatũngĩĩa, o ũndũ mailyĩ mbee.'),
('kam', 'JER', 33, 8, 'Na ngamathesya ũthũku woo w’onthe, ũla mambĩtanĩsye; na ngamaekea mothũku moo onthe, ala mambĩtanĩsye, na ala mambĩkie.'),
('kam', 'JER', 33, 9, 'Na ndũa ĩno ĩkeethĩwa kwakwa syĩtwa ya ũtanu, na ũtaĩo, na ũnene, mbaĩ syonthe sya nthĩ syene, ila ikew’a w’onthe ũla nĩmekaa, na ikakĩa na kũtetema nũndũ wa ũseo w’onthe na mũuo w’onthe ũla nĩmyonea.'),
('kam', 'JER', 33, 10, 'Ũũ nĩw’o Yeova ũnũkwasya: o na ĩngĩ kũkeew’ĩka vandũ vaa, vala mwĩneena ũndũ wa vo, Nĩ ĩanzo, vate mũndũ na vate nyamũ, o na ndũanĩ sya Yuta, na nzĩanĩ nene sya Yelusaleme, ila syatiiwe, ite mũndũ, na ite andũ ma kwitũa, na ite nyamũ,'),
('kam', 'JER', 33, 11, 'kũkeew’ĩka wasya wa kũtheka na wasya wa ũtanu, wasya wa mũtwaani na wasya wa mũtwawa, wasya wa ala mekwasya, Mũtũngĩei mũvea Yeova wa nguthu, nũndũ Yeova nĩ mũseo, nũndũ ũseo wake wĩ wendo nĩwĩkalaa tene na tene; na wasya wa ala maetae nthembo sya mũvea nyũmbanĩ ya Yeova. Nũndũ ngatũnga atavwa ma ĩ nthĩ ĩkale tondũ yailyĩ mbee, easya ũu Yeova.'),
('kam', 'JER', 33, 12, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya: o na ĩngĩ vandũ vaa, vala nĩ ĩanzo, vate mũndũ na vate nyamũ, na ndũanĩ syonthe sya vo, vakeethĩwa wĩkalo wa aĩthi ala matindiasya ndĩthya syoo sya mbũi na malondu.'),
('kam', 'JER', 33, 13, 'Ndũanĩ sya nthĩ yĩ iĩma, na ndũanĩ sya nthĩ ndindimalu, na ndũanĩ sya ngalĩ ya Ĩtheo, na nthĩ ya Mbenyamini, na ku ndee sya Yelusaleme, na ndũanĩ sya Yuta, ndĩthya sya mbũi na malondu ikavĩtĩla ĩngĩ ungu wa moko ma ũla wĩtalaa, easya ũu Yeova.'),
('kam', 'JER', 33, 14, 'Sisya, mĩthenya nĩyũkĩte, easya Yeova, ĩla ngeanĩsya ndeto nzeo ĩla nĩneenete ũndũ wa nyũmba ya Isilaeli na ũndũ wa nyũmba ya Yuta.'),
('kam', 'JER', 33, 15, 'Mĩthenya ĩsu, na ĩvinda yĩu, ngathongoesya Ndaviti Ũvonge wa ũlũngalu; nake akasilaa sila wa katĩ na mũlũngalu e ĩ nthĩ.'),
('kam', 'JER', 33, 16, 'Mĩthenya ĩsu Yuta ĩkatangĩĩwa, na Yelusaleme ĩkekala ĩte na mũisyo; na yĩĩ nĩyo syĩtwa yĩla ĩketwa nayo: Yeova ũlũngalu wĩtũ.'),
('kam', 'JER', 33, 17, 'Nũndũ ũũ nĩw’o Yeova ũnũkwasya: Ndaviti ndakaĩwa nĩ mũndũ mũũme wa kwĩkalĩla kĩvĩla kya ũsumbĩ kya nyũmba ya Isilaeli;'),
('kam', 'JER', 33, 18, 'o na athembi Alivai matikaĩwa nĩ mũndũ wa kũthemba nthembo sya kũvĩvw’a, na wa kũvivya nthembo sya mũtu, na kũthemba mavinda onthe mbee wakwa.'),
('kam', 'JER', 33, 19, 'Na ndeto ya Yeova yamũkĩa Yelemia, ĩkyasya,'),
('kam', 'JER', 33, 20, 'Ũũ nĩw’o Yeova ũnũkwasya: Ethĩwa mũtonya kwananga ũtianĩo wakwa wa mũthenya, na ũtianĩo wakwa wa ũtukũ, kũikethiwe mũthenya na ũtukũ ĩvinda yaw’o;'),
('kam', 'JER', 33, 21, 'nĩvo ĩndĩ ũtianĩo wakwa naw’o ũtonya kwanangwa ũla natianĩe na Ndaviti mũthũkũmi wakwa, ndakethĩwe na mwana wa kũsumbĩka kĩvĩlanĩ kyake kya ũsumbĩ; o na ũla natianĩe na athembi Alivai, athũkũmi makwa.'),
('kam', 'JER', 33, 22, 'O ũndũ nguthu sya ĩtunĩ itatonya kũtalĩka, kana kĩthangathĩ kya ũkanga kĩtatonya kũthimĩka; now’o ngaingĩvya ũsyao wa Ndaviti mũthũkũmi wakwa, na Alivai ala manthũkũmaa.'),
('kam', 'JER', 33, 23, 'Na ndeto ya Yeova yamũkĩa Yelemia, ĩkĩmũkũlya,'),
('kam', 'JER', 33, 24, 'Ndũũsũanĩa ũndũ andũ aa maneenete, makyasya, Mĩvĩa ĩlĩ ĩla Yeova wanyuvie, nake nũmĩkĩtye ũtee? Now’o mavũthasya andũ makwa, nĩ kana matikethĩwe mbaĩ mbee woo ĩngĩ.'),
('kam', 'JER', 33, 25, 'Ũũ nĩw’o Yeova ũnũkwasya: Ethĩwa ũtianĩo wakwa wa mũthenya na ũtukũ ndũkethĩwa vo, ethĩwa nditw’ĩte motw’ĩo ma ĩtu na nthĩ;'),
('kam', 'JER', 33, 26, 'nĩvo ĩndĩ ngekya ũtee ũsyao wa Yakovo, na wa Ndaviti mũthũkũmi wakwa, kana ndikose ma ũsyao wake methĩwa ma kũsumbĩka ũsyao wa Avalaamu, na Isaka, na Yakovo: nũndũ ngamatũnga maume kũtavwanĩ kwoo, na kũmew’ĩa tei.'),
('kam', 'JER', 34, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, yĩla Nevukatilesa mũsumbi wa Mbaviloni, na ita syake syonthe, na mosumbĩ onthe ma nthĩ ala masumbĩkĩtwe nĩwe, na ngo syonthe sya andũ, mokitaa na Yelusaleme, na ndũa syonthe syayo, ĩkĩmwĩa,'),
('kam', 'JER', 34, 2, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Enda ũneene na Nzetekia mũsumbĩ wa Yuta, noimũtavya, Ũũ nĩw’o Yeova ũnũkwasya, Sisya, nganengane ndũa ĩno kw’okonĩ kwa mũsumbĩ wa Mbaviloni, nake akamĩvĩvya na mwaki:'),
('kam', 'JER', 34, 3, 'naku ndũkavonoka kuma kw’okonĩ kwake, ĩndĩ ndũkatĩa kũkwatwa, na kũnenganwe kw’okonĩ kwake; na metho maku makoona metho ma mũsumbĩ wa Mbaviloni, na akaneena naku kanyw’a kwa kanyw’a, naku ũkathi Mbaviloni.'),
('kam', 'JER', 34, 4, 'Ĩndĩ ĩw’a ndeto ya Yeova, we Nzetekia mũsumbĩ wa Yuta: Ũũ nĩw’o Yeova ũnũkwasya ũndũ waku, Ndũkoawa na ũvyũ;'),
('kam', 'JER', 34, 5, 'ũkakw’a wĩ na mũuo; na makakũtoeesya o ũndũ matoeesye aaĩthe maku, o asumbĩ ma tene ala masumbĩkie mbee waku; na makakũmetea, makyasya, A! Mwĩaĩi! Nũndũ nĩnĩneenete ndeto ĩno, easya ũu Yeova.'),
('kam', 'JER', 34, 6, 'Nĩvo ĩndĩ mwathani Yelemia wamũtavisye Nzetekia mũsumbĩ wa Yuta ndeto isu syonthe e Yelusaleme,'),
('kam', 'JER', 34, 7, 'yĩla ita sya mũsumbĩ wa Mbaviloni syokitaa na Yelusaleme, na ndũa syonthe sya Yuta ila syatialile, Lakisi na Aseka; nũndũ isu syĩ syoka nĩsyatialile syĩ ndũa mbiie katĩ wa ndũa sya Yuta.'),
('kam', 'JER', 34, 8, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova, ĩtina wa mũsumbĩ Nzetekia kũtianĩa ũtianĩo na andũ onthe ala maĩ Yelusaleme, kũtavan’ya ũthasyo kwoo;'),
('kam', 'JER', 34, 9, 'kana kĩla mũndũ nathasye mũthũkũmi wake mũndũ mũũme, na kĩla mũndũ mũthũkũmi wake mwĩĩtu, ethĩwa nĩ mũndũ mũũme Mũevelania kana mũndũ mũka Mũevelania; mũndũ ndakamũtw’ĩkĩthye ngombo, o Mũyuti mwana‐a‐ĩthe.'),
('kam', 'JER', 34, 10, 'Na anene onthe me mbee ũsumbĩnĩ na andũ onthe meeka ũu, ala malikĩte ũtianĩonĩ, kana kĩla ũmwe nathasye mũthũkũmi wake mũndũ mũũme, na kĩla ũmwe mũthũkũmi wake mwĩĩtu, mũndũ o na wĩva ndakamatw’ĩkĩthye ngombo ĩngĩ; nĩmeewie na mamathasya:'),
('kam', 'JER', 34, 11, 'ĩndĩ ĩtina maalyũka, na matũnga athũkũmi na athũkũmi eĩtu, ala mamathaĩtye, na mamaete ũkombonĩ methĩwe athũkũmi na athũkũmi eĩtu.'),
('kam', 'JER', 34, 12, 'Kwondũ wa ũu ndeto ya Yeova yamũkia Yelemia kuma kwa Yeova, ĩkyasya,'),
('kam', 'JER', 34, 13, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya: Nĩnatianĩe ũtianĩo na aaĩthe menyu mũthenya ũla namaumisye nthĩ ya Misili, kuma nyũmbanĩ ya ũkombo, ngyasya,'),
('kam', 'JER', 34, 14, 'Myaka mũonza yathela mwĩthaasya kĩla mũndũ mwana‐a‐ĩthe wake Mũevelania, ũla wathooiw’e kwaku, na nũkũthũkũmĩte myaka thanthatũ, ũkamũthasya aume kwaku: ĩndĩ aaĩthe menyu matyaambĩthukĩĩsya, kana kũtea matũ moo.'),
('kam', 'JER', 34, 15, 'Na yu nĩmweealyũlĩte na kwĩka ũla nonaa wĩ ũseo, ũndũ wa kũtavan’ya ũthasyo kĩla mũndũ kwa mũtũi wake; na nĩmwatianĩĩte ũtianĩo mbee wakwa nyũmbanĩ ĩla yĩtanĩaw’a na syĩtwa yakwa:'),
('kam', 'JER', 34, 16, 'ĩndĩ mwaalyũka na kũyĩuma syĩtwa yakwa, na mwatũnga kĩla mũndũ mũthũkũmi wake, na kĩla mũndũ mũthũkũmi wake mwĩĩtu, ala mwamathaĩtye maende o vala mekwenda; na mwamaete ũkombonĩ, methĩwe kwenyu athũkũmi na athũkũmi eĩtu.'),
('kam', 'JER', 34, 17, 'Kwondũ wa ũu Yeova easya atĩĩ: Mũtyaambĩthukĩĩsya, mũtavan’ye ũthasyo, kĩla mũndũ kwa mwana‐a‐ĩthe, na kĩla mũndũ kwa mũtũĩ wake: sisya, nĩngũtavan’ya kwenyu ũthasyo wa ũvyũ, na mũimũ, na yũa, easya ũu Yeova; na ngatuma mwĩkangw’a kũũ na kũũ mosumbĩnĩ onthe ma nthĩ.'),
('kam', 'JER', 34, 18, 'Na nganengane andũ ala mavĩtisye ũtianĩo wakwa, ala mataaĩanĩsya ndeto sya ũtianĩo ũla matianĩe nakwa, yĩla matũaanisye kala kasaũ myondo ĩlĩ na mavĩtĩla katĩ wa myondo yako;'),
('kam', 'JER', 34, 19, 'anene me mbee ũsumbĩnĩ ma Yuta, na anene me mbee ũsumbĩnĩ ma Yelusaleme, na avakũe, na athembi, na andũ onthe ma ĩ nthĩ, ala mavĩtĩle katĩ wa myondo ya kala kasaũ;'),
('kam', 'JER', 34, 20, 'ngamanengane mokonĩ ma amaitha moo, na mokonĩ ma ala mamanthaa mathayũ moo; na simba syoo ikethĩwa lĩu wa nyũnyi sya yayaya, na wa nyamũ sya nthĩ.'),
('kam', 'JER', 34, 21, 'Na Nzetekia mũsumbĩ wa Yuta na anene make me mbee ũsumbĩnĩ ngamanengane mokonĩ ma amaitha moo, na mokonĩ ma ala mamanthaa mathayũ moo, na mokonĩ ma ita sya mũsumbĩ wa Mbaviloni, ala mambatie kuma kwenyu.'),
('kam', 'JER', 34, 22, 'Sisya, ngeeaa, na kũmatũnga ndũanĩ ĩno, easya ũu Yeova; na makamyũkita na kũmyosa, na kũmĩvĩvya na mwaki: na ngatw’ĩkĩthya ndũa sya Yuta maanzo, ite mũndũ witũa.'),
('kam', 'JER', 35, 1, 'Ndeto ĩla yamũkĩe Yelemia kuma kwa Yeova mĩthenya ya Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, ĩkĩmwĩa.'),
('kam', 'JER', 35, 2, 'Enda nyũmbanĩ ya Alekavi, ũneene nao, na kũmaete nyũmbanĩ ya Yeova, kasũmbanĩ kamwe ka nthĩnĩ, na kũmanenga mbinyu ya ũnyw’a.'),
('kam', 'JER', 35, 3, 'Nĩvo ĩndĩ noosie Yaasania mwana wa Yelemia, mwana wa Avasinia, na ana‐a‐ĩthe make, na ana make onthe, na nyũmba yonthe ya Alekavi;'),
('kam', 'JER', 35, 4, 'na namaete nyũmbanĩ ya Yeova, kasũmbanĩ ka ana ma Aananu mwana wa Ikitalia mũndũ wa Ngai, kala kaĩ vakuvĩ na kasũmba ka anene me mbee ũsumbĩnĩ, kala kaĩ ĩũlũ wa kasũmba ka Maaseia mwana wa Salumu, mũsũvĩi wa mwalyonĩ.'),
('kam', 'JER', 35, 5, 'Nakwa naia mbee wa ana ma nyũmba ya Alekavi mbakũli syusĩe mbinyu, na ikombe; na namea, Nyw’ai mbinyu.'),
('kam', 'JER', 35, 6, 'Ĩndĩ masya, Tũtikanyw’a mbinyu; nũndũ Yonatavu mwana wa Lekavi, asa waitũ, atwĩaĩe, akyasya, Mũtikaanyw’e mbinyu, inyw’ĩ, kana ana menyu, tene na tene:'),
('kam', 'JER', 35, 7, 'o na mũtikaake nyũmba, kana kũvũĩa mbeũ, kana kũvanda mũũnda wa mĩsavivũ, kana kwĩthĩwa naw’o; ĩndĩ mĩthenya yenyu yonthe mũkatũaa maeemanĩ; nĩ kana mwĩkalae thayũ mĩthenya mingĩ nthĩ ĩla mũtũaa mwĩ aeni.'),
('kam', 'JER', 35, 8, 'Na nĩtweewie wasya wa Yonatavu mwana wa Lekavi, asa waitũ, ũndũnĩ w’onthe ũla watwĩaĩe, atĩ tũtikaanyw’e mbinyu mĩthenya yaitũ yonthe, ithyĩ, kana iveti sitũ, kana ana maitũ, kana eĩtu maitũ;'),
('kam', 'JER', 35, 9, 'kana kwaka nyũmba twĩkalae nthĩnĩ wasyo; o na tũti na mũũnda wa mĩsavivũ, kana mũũnda, kana mbeũ:'),
('kam', 'JER', 35, 10, 'ĩndĩ nĩtwĩkalaa maeemanĩ, na kwĩw’aa, na kwĩkaa kwĩanana na w’onthe ũla Yonatavu asa waitũ watwĩaĩe.'),
('kam', 'JER', 35, 11, 'Ĩndĩ kweethĩwa yĩla Nevukatilesa mũsumbĩ wa Mbaviloni wambatie na kũlika nthĩ ĩno, nĩvo twaisye, Ũkai, tũende Yelusaleme tũkĩĩte ita sya Akalitei, na tũkĩĩte ita sya Asilia; kwondũ wa ũu nĩtwĩkalaa Yelusaleme.'),
('kam', 'JER', 35, 12, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia, ĩkyasya,'),
('kam', 'JER', 35, 13, 'Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Enda, ũmakũlye andũ ma Yuta na ala matwĩe Yelusaleme, Mũtikwenda kwosa ũmanyĩsyo mwĩthukĩĩsye ndeto syakwa? Easya ũu Yeova.'),
('kam', 'JER', 35, 14, 'Ndeto sya Yonatavu mwana wa Lekavi, ila wameaĩe ana make, matikaanyw’e mbinyu, nikwĩanĩw’a; na kũvika mũnthĩ ũũ matinyusaa nongi, nũndũ nĩmew’aa mwĩano wa ĩthe woo. Ĩndĩ nĩnĩneenete nenyu, ngyũkĩla tene na ngĩneena; na mũtyaambĩthukĩĩsya.'),
('kam', 'JER', 35, 15, 'O na nĩnĩtũmĩte kwenyu athũkũmi makwa onthe athani, ngyũkĩla tene na ngĩmatũma, ngyasya, Syokai yu kĩla mũndũ kuma mũendelenĩ wake mũthũku, mũlũngalye meko menyu, na mũtikaatĩĩe ngai ingĩ mwithũkũme, na mũkekalaa nthĩ ĩla namũnengie inyw’ĩ na aaĩthe menyu: ĩndĩ mũtyaatea matũ menyu, kana kũmbĩthukĩĩsya.'),
('kam', 'JER', 35, 16, 'Nĩkwĩthĩwa ana ma Yonatavu mwana wa Lekavi nĩmeanĩsye mwĩao wa ĩthe woo ũla wameaĩe, ĩndĩ andũ aa matyaambĩthukĩĩsya;'),
('kam', 'JER', 35, 17, 'kwondũ wa ũu Yeova, Ngai wa nguthu, Ngai wa Isilaeli, easya: Sisya, ngaetee Yũta na onthe ala matwĩe Yelusaleme ũthũku w’onthe ũla namaneenee; nũndũ nĩnĩneenete nao, ĩndĩ matyaaĩw’a; na nĩnĩmetĩte, ĩndĩ matyaaĩtĩka.'),
('kam', 'JER', 35, 18, 'Na Yelemia atavya nyũmba ya Alekavi, Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Nĩkwĩthĩwa nĩmweewie mwĩao wa Yonatavu ĩthe wenyu, na kũkwata mawĩaĩo make onthe, na kwĩka kwĩanana na w’onthe ũla wamwĩaĩe;'),
('kam', 'JER', 35, 19, 'kwondũ wa ũu Yeova wa nguthu, Ngai wa Isilaeli, easya: Yonatavu mwana wa Lekavi ndakaĩwa nĩ mũndũ mũũme wa kũũngama mbee wakwa tene na tene.'),
('kam', 'JER', 36, 1, 'Na kweethĩwa mwaka wa kana wa kũsumbĩka kwa Yeoiakimu mwana wa Yosĩa, mũsumbĩ wa Yuta, ndeto ĩno yamũkĩa Yelemia kuma kwa Yeova, ĩkĩmwĩa,'),
('kam', 'JER', 36, 2, 'Ĩyose ĩvuku ĩkũnze, noiandĩka nthĩnĩ wayo ndeto syonthe ila nakũtavisye ngĩneenea Isilaeli, na Yuta, na mbaĩ syonthe, kuma mũthenya naneenie naku, kuma mĩthenya ya Yosia, o kũvika ũmũnthĩ.'),
('kam', 'JER', 36, 3, 'Nokwĩthĩwa nyũmba ya Yuta ĩkeew’a ũthũku w’onthe ũla nĩsũanĩĩte kũmeka; matonye kũsyoka kĩla mũndũ kuma mũendelenĩ wake mũthũku; nĩ kana nĩmaekee ũthũku woo na naĩ yoo.'),
('kam', 'JER', 36, 4, 'Nĩvo ĩndĩ Yelemia wamwĩtie Mbaluka mwana wa Nelia; na Mbaluku aandĩka kuma kanyw’anĩ wa Yelemia ĩvukunĩ ĩkũnze ndeto syonthe sya Yeova, ila wamũtavisye.'),
('kam', 'JER', 36, 5, 'Na Yelemia amwĩaĩa Mbaluku, akyasya, Nĩ mwove; nditonya kũthi nyũmbanĩ ya Yeova;'),
('kam', 'JER', 36, 6, 'kwondũ wa ũu enda, ũsome ĩvukunĩ ĩkũnze, yila ũandĩkĩte kuma kanyw’anĩ wakwa, ndeto sya Yeova matũnĩ ma andũ nyũmbanĩ ya Yeova mũthenya wa kũtĩĩa ũya; o na ũkaisoma matũnĩ ma Ayuta onthe ala maumaa ndũanĩ syoo.'),
('kam', 'JER', 36, 7, 'Nokwĩthĩwa makaete mboya syoo mbee wa Yeova, na kũsyoka kĩla ũmwe kuma mũendelenĩ wake mũthũku; nũndũ ũthatu na kũthilĩka kũla Yeova ũmaneeneete andũ aa nĩ kũnene.'),
('kam', 'JER', 36, 8, 'Na Mbaluku mwana wa Nelia eeka kwĩanana na w’onthe ũla mwathani Yelemia wamwĩaĩa, aisoma yĩla ĩvukunĩ ndeto sya Yeova nyũmbanĩ ya Yeova.'),
('kam', 'JER', 36, 9, 'Na kweethĩwa mwaka wa katano wa kũsumbĩka kwa Yeoiakimu mwana wa Yosia, mũsumbĩ wa Yuta, mwei wa kenda, andũ onthe ma Yelusaleme, na andũ onthe ala mookie Yelusaleme kuma ndũanĩ sya Yuta, matavan’ya kũtĩĩa ũya mbee wa Yeova.'),
('kam', 'JER', 36, 10, 'Nĩvo ĩndĩ Mbaluku wasomie yĩla ĩvukunĩ ndeto sya Yelemia e nyũmbanĩ ya Yeova, kasũmbanĩ ka Ngemalia mwana wa mũandĩki Savani, nza ya ĩũlũ, vandũ wa ũlikĩla mbingĩlonĩ nzaũ ya nyũmba ya Yeova, andũ onthe makĩw’a.'),
('kam', 'JER', 36, 11, 'Na yĩla Mikaia mwana wa Ngemalia, mwana wa Savani, wewie ndeto syonthe sya Yeova kuma yĩla ĩvukunĩ,'),
('kam', 'JER', 36, 12, 'atheea nyũmbanĩ ya mũsumbĩ, kasũmbanĩ ka mũandĩki: na, sisya, anene onthe me mbee ũsumbĩnĩ mekalĩte vo, nao nĩ aa; mũandĩki Elisama, na Ndelaia mwana wa Semaia, na Elinathani mwana wa Akivoli, na Ngemalia mwana wa Savani, na Nzetekia mwana wa Aanania, na anene onthe me mbee ũsumbĩnĩ.'),
('kam', 'JER', 36, 13, 'Nĩvo ĩndĩ Mikaia wamatavisye ndeto syonthe ila wewie, yĩla Mbaluku wasomie yĩla ĩvuku matũnĩ ma andũ.'),
('kam', 'JER', 36, 14, 'Kwondũ wa ũu anene onthe me mbee ũsumbĩnĩ matũma Yeuuti mwana wa Nethania, mwana wa Selemia, mwana wa Kusi, kwa Mbaluku, makĩmwĩa, Osa na kw’oko kwaku ivuku ĩkũnze yĩla wasomee matũnĩ ma andũ, noyũka. Kwondũ wa ũu Mbaluku mwana wa Nelia oosa ĩvuku na kw’oko kwake na athi vala maĩ.'),
('kam', 'JER', 36, 15, 'Nao mamwĩa, Yu ĩkala nthĩ, noiyĩsoma matũnĩ maitũ. Na ĩndĩ Mbaluku ayĩsoma matũnĩ moo.'),
('kam', 'JER', 36, 16, 'Na kweethĩwa, meew’a ndeto syonthe, masian’ya kĩla mũndũ na ũla ũngĩ na w’ĩa, na mamwĩa Mbaluku, Tũitĩa kũtavya mũsumbĩ ndeto ii syonthe.'),
('kam', 'JER', 36, 17, 'Na mamũkũlya Mbaluku, makyasya, Tũtavye yu, Waandĩkie ndeto ii syonthe ata kuma kanyw’anĩ wake?'),
('kam', 'JER', 36, 18, 'Nĩvo ĩndĩ Mbaluku wamasũngĩie, Nĩwawetie ndeto ii syonthe mbee wakwa na kanyw’a wake, nakwa naandĩka na ingi yĩla ĩvukunĩ.'),
('kam', 'JER', 36, 19, 'Nĩvo ĩndĩ anene me mbee ũsumbĩnĩ mamwĩie Mbaluku, Enda wĩvithe, we na Yelemia; na mũndũ o na wĩva ndakamanye vala mũĩ.'),
('kam', 'JER', 36, 20, 'Na malika nza kwa mũsumbĩ; ĩndĩ maĩ manaia ĩvuku ĩkũnze kasũmbanĩ ka mũandĩki Elisama; na maneena ndeto syonthe matũni ma mũsumbĩ.'),
('kam', 'JER', 36, 21, 'Kwondũ wa ũu mũsumbĩ amũtũma Yeuuti alatye yĩla ĩvuku; na ayumya kasũmbanĩ ka mũandĩki Elisama. Na Yeuuti ayĩsoma matũnĩ ma mũsumbĩ, na matũnĩ ma anene onthe me mbee ũsumbĩnĩ ala maũngeme vakuvĩ na mũsumbĩ.'),
('kam', 'JER', 36, 22, 'Na mũsumbĩ ekalĩte nyũmbanĩ ĩla ĩkalawa ĩvinda ya mbevo mwei wa kenda: na vaĩ mwaki wakanĩte kaikonĩ mbee wake.'),
('kam', 'JER', 36, 23, 'Na kweethĩwa, yĩla Yeuuti waminie kũsoma ilungu itatũ kana inya, mũsumbĩ atila kĩlungu kyu na kavyũ, na kũkĩkya mwakinĩ ũla waĩ kaikonĩ, kũvika ĩvuku ĩkũnze yonthe yavĩvw’a na mwaki ũla waĩ kaikonĩ.'),
('kam', 'JER', 36, 24, 'Na matyaakĩa, kana kũtembũanga ngũa syoo, o na mũsumbĩ, kana athũkũmi make o na meva ala meewie ndeto isu.'),
('kam', 'JER', 36, 25, 'Na ũndũ ũngĩ Elinathani na Ndelaia na Ngemalia maĩ manamwĩsũva mũsumbĩ ndakavĩvye yĩla ĩvuku ĩkũnze; ĩndĩ ndaaĩtĩkĩla kũmew’a.'),
('kam', 'JER', 36, 26, 'Na mũsumbĩ amwĩaĩa Yelameeli mwana wa mũsumbĩ, na Selaia mwana wa Anzilieli, na Selemia mwana wa Aviteeli, makwate mũandĩki Mbaluku na mwathani Yelemia; ĩndĩ Yeova amavitha.'),
('kam', 'JER', 36, 27, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe Yelemia, ĩtina wa mũsumbĩ kũvĩvya ĩvuku ĩkũnze, na ndeto ila Mbaluku waandĩkie syaumĩte kanyw’anĩ wa Yelemia, ĩkĩmwĩa,'),
('kam', 'JER', 36, 28, 'Osa ingĩ ĩvuku yĩngĩ ĩkũnze, noiandĩka nthĩnĩ wayo ndeto syonthe sya mbee ila syaĩ ĩvukunĩ ĩkũnze ya mbee, yĩla Yeoiakimu mũsumbĩ wa Yuta wavĩvisye.'),
('kam', 'JER', 36, 29, 'Na ũndũ wa Yeoiakimu mũsumbĩ wa Yuta ũkasya, Ũũ nĩw’o Yeova ũnũkwasya: Nĩwavĩvisye ĩvuku yĩu, ũkyasya, Nũndũ wa kĩ waandĩkie nthĩnĩ wayo, ũkyasya, Mũsumbĩ wa Mbaviloni ndatĩa kũka na kwananga nthĩ ĩno, na kũmina kw’o andũ na nyamũ?'),
('kam', 'JER', 36, 30, 'Kwondũ wa ũu Yeova easya ũndũ wa Yeoiakimu mũsumbĩ wa Yuta: Ndakethĩwa na mũndũ wa kwĩkalĩla kĩvĩla kya ũsumbĩ kya Ndaviti; na kimba kyake kĩkekw’a nza mũthenya kwĩ kũvyũ, na ũtukũ kwĩ ĩmwe yĩkamĩtw’e nĩ mbevo.'),
('kam', 'JER', 36, 31, 'Na ngamũkũna we na ũsyao wake na athũkũmi make ũndũ wa ũthũku woo; na ngamaetee, na ala matwĩe Yelusaleme, na andũ ma Yuta, ũthũku w’onthe ũla namawetee, ĩndĩ matyaaĩthukĩĩsya.'),
('kam', 'JER', 36, 32, 'Nĩvo ĩndĩ Yelemia wosie ĩvuku yĩngĩ ĩkũnze, na amũnenga mũandĩki Mbaluku, mwana wa Nelia, ũla waandĩkie nthĩnĩ wayo kuma kanyw’anĩ wa Yelemia ndeto syonthe sya ĩvuku yĩla Yeoiakimu mũsumbĩ wa Yuta wavĩvisye na mwaki; nasyo syongelelwa ndeto ingĩ mbingĩ iilyĩ tasyo.'),
('kam', 'JER', 37, 1, 'Na Nzetekia mwana wa Yosia nĩwasumbĩkie, vandũ va Konia mwana wa Yeoiakimu, ũla Nevukatilesa mũsumbĩ wa Mbaviloni wamũsumbĩkĩthisye nthĩ ya Yuta.'),
('kam', 'JER', 37, 2, 'Ĩndĩ we, kana athũkũmi make, kana andũ ma nthĩ ĩsu, matyaaĩthukĩĩsya ndeto sya Yeova, ila waneenie na kanyw’a wa mwathani Yelemia.'),
('kam', 'JER', 37, 3, 'Na mũsumbĩ Nzetekia atũma Yeukali mwana wa Selemia, na Nzevania mwana wa mũthembi Maaseia, mathi kwa mwathani Yelemia, akĩmwĩa, Mũvoye Yeova Ngai waitũ kwondũ witũ.'),
('kam', 'JER', 37, 4, 'Yelemia nĩwalikaa na kumaalaa andũnĩ; nũndũ matyaĩ manamwĩkĩa kolokolonĩ.'),
('kam', 'JER', 37, 5, 'Na ita sya Valao syaĩ inauma Misili; na Akalitei ala matwĩkanĩsye Yelusaleme meew’a ũvoo woo, mauma Yelusaleme mathi.'),
('kam', 'JER', 37, 6, 'Nĩvo ĩndĩ ndeto ya Yeova yamũkĩe mwathani Yelemia, ĩkyasya,'),
('kam', 'JER', 37, 7, 'Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Ũũ nĩw’o mũkamwĩa mũsumbĩ wa Yuta, ũla wamũtũmie kwakwa mũngũlye: Sisya, ita sya Valao, ila syũkĩte kũmũtethya, ikasyoka Misili nthĩ yoo ene.'),
('kam', 'JER', 37, 8, 'Na Akalitei makooka ĩngĩ, na kũkita na ndũa ĩno; na makamĩkwata na kũmĩvĩvya na mwaki.'),
('kam', 'JER', 37, 9, 'Ũũ nĩw’o Yeova ũnũkwasya, Mũikekenge, mũkyasya, Vate ndĩi Akalitei makatũeka; nũndũ matikamũtia.'),
('kam', 'JER', 37, 10, 'Nũndũ o na ethĩwa nĩmwakũnĩte ita syonthe sya Akalitei ala mokitaa nenyu, na vakatiala no andũ okite katĩ woo, o asu makookĩla kĩla mũndũ ĩeemanĩ yake, na kũvĩvya ndũa ĩno na mwaki.'),
('kam', 'JER', 37, 11, 'Na kweethĩwa, yĩla ita sya Akalitei syaumie Yelusaleme ũndũ wa ũkĩa ita sya Valao,'),
('kam', 'JER', 37, 12, 'nĩvo ĩndĩ Yelemia waumie Yelusaleme aende nthĩ ya Mbenyamini, kwosa kĩanda kyake kw’o, katĩ wa andũ.'),
('kam', 'JER', 37, 13, 'Na yĩla waĩ mbingilonĩ ya Mbenyamini, kavuteni wa asuvĩi aĩ vo, syĩtwa yake nĩ Iliya, mwana wa Selemia, mwana wa Aanania; nake amũkwata mwathani Yelemia, akĩmwĩa, Nũkwĩtila we ũende kwa Akalitei.'),
('kam', 'JER', 37, 14, 'Nĩvo Yelemia waisye, Nĩ ũvũngũ; ndikwĩtila nĩende kwa Akalitei. Ĩndĩ ndaamwĩthukĩĩsya; kwondũ wa ũu Iliya amũkwata Yelemia, na amũtwaa vala vaĩ anene me mbee ũsumbĩnĩ.'),
('kam', 'JER', 37, 15, 'Na anene asu mamũthilĩkĩla Yelemia, na mamũkũna, na mamwĩkĩa kolokolonĩ nyũmbanĩ ya mũandĩki Yonathani; nũndũ nĩmamĩtw’ĩkĩthĩtye kolokolo.'),
('kam', 'JER', 37, 16, 'Yĩla Yelemia walikĩte nyũmbanĩ yĩ nthĩnĩ wa nthĩ, na tũsũmbanĩ twayo, na Yelemia aĩ anekala vu mĩthenya mingĩ;'),
('kam', 'JER', 37, 17, 'nĩvo mũsumbĩ Nzetekia watũmanie, na kũmũete: na mũsumbĩ amũkũlĩlya na kĩmbithĩ nyũmbanĩ yake, na asya, Ve ndeto o na yĩva yumĩte kwa Yeova? Na Yelemia asya, Nĩvo ĩĩ. Na ĩngĩ asya, Ũkanenganwe kw’okonĩ kwa mũsumbĩ wa Mbaviloni.'),
('kam', 'JER', 37, 18, 'Na ĩngĩ Yelemia amwĩa mũsumbĩ Nzetekia, Nakũvĩtanĩsye ũndũnĩ wĩva, kana athũkũmi maku, kana andũ aa, ũndũ mwambĩkĩie kolokolonĩ?'),
('kam', 'JER', 37, 19, 'Yu maĩva athani menyu ala mamwathanĩe, makyasya, Mũsumbĩ wa Mbaviloni ndakoka kũkita nenyu, kana nthĩ ĩno?'),
('kam', 'JER', 37, 20, 'Na yu ĩw’a, nĩngũkwĩsũva, ame mwĩaĩi wakwa mũsumbĩ: nĩngũkwĩsũva wĩsũvano wakwa wĩtĩkĩlwe mbee waku, atĩ ndũkandũnge nyũmbanĩ ya mũandĩki Yonathani, ndikese kũkw’ĩa vo.'),
('kam', 'JER', 37, 21, 'Nĩvo ĩndĩ mũsumbĩ Nzetekia weaie, na mamwia Yelemia nza ya kolokolo; na mamũnengae o kĩla mũthenya mũkate ũmwe ũkyuma nzĩanĩ nene vala vekalaa aui ma mĩkate, kũvika mĩkate yonthe ĩla yaĩ ndũanĩ yathela. Ũũ nĩw’o Yelemia wekalile vu nza ya kolokolo.'),
('kam', 'JER', 38, 1, 'Na Sevatia mwana wa Matani, na Ngetalia mwana wa Vasuli, na Yukali mwana wa Selemia, na Vasuli mwana wa Malikiya, nĩmeewie ndeto ila Yelemia waneenie na andũ onthe, akyasya,'),
('kam', 'JER', 38, 2, 'Ũũ nĩw’o Yeova ũnũkwasya, Ũla wĩĩkala ndũanĩ ĩno akooawa na ũvyũ, na yũa, na mũimũ; ĩndĩ ũla wĩuma aende na Akalitei akekala thayũ, na thayũ wake ũkethĩwa mũtavo wake, na akekala thayũ.'),
('kam', 'JER', 38, 3, 'Ũũ nĩw’o Yeova ũnũkwasya, Ndũa ĩno ndĩtĩa kũnenganwe mokonĩ ma ita sya mũsumbĩ wa Mbaviloni, na akamyosa.'),
('kam', 'JER', 38, 4, 'Nĩvo ĩndĩ anene me mbee ũsumbĩnĩ mamwĩie mũsumbĩ, Nĩtũũkwĩsũva, mũndũ ũũ oawe; nĩkwĩthĩwa nũnũkwonzethya moko ma aũme ma kaũ ala matialĩte ndũanĩ ĩno, o na moko ma andũ onthe, aimatavya ndeto iilyĩ ũu: nũndũ mũndũ ũũ ndeũmanthĩa andũ aa ũseo, ĩndĩ ũthũku.'),
('kam', 'JER', 38, 5, 'Na mũsumbĩ Nzetekia asya, Sisya, e mokonĩ menyu; nũndũ mũsumbĩ tiwe ũla ũtonya kũmwĩkĩa inyw’ĩ ũndũ.'),
('kam', 'JER', 38, 6, 'Nĩvo ĩndĩ mamwosie Yelemia, na kũmwĩkya yĩla ĩimanĩ ya Malikiya mwana wa mũsumbĩ, yĩla yaĩ nza ya kolokolo: na mamũtheesya Yelemia na makanda. Na ĩimanĩ yĩu vatyaĩ manzĩ, no ndaka; na Yelemia alika ndakanĩ.'),
('kam', 'JER', 38, 7, 'Na yĩla Mũethiovia Eveti‐meleki, mũvakũe, ũla waĩ nyũmbanĩ ya mũsumbĩ, wewie atĩ nĩmamwĩkĩĩte Yelemia yĩla ĩimanĩ (ĩvinda yĩu mũsumbĩ ekalĩte mbingĩlonĩ ya Mbenyamini),'),
('kam', 'JER', 38, 8, 'Eveti‐meleki aumaala nyũmbanĩ ya mũsumbĩ, na aneena na mũsumbĩ, akĩmwĩa,'),
('kam', 'JER', 38, 9, 'Mwĩaĩi wakwa mũsumbĩ, andũ asu nĩmekĩte naĩ maũndũnĩ onthe ala mamwĩkie mwathani Yelemia, ũla mamwĩkisye yĩla ĩimanĩ; na ailyĩ ta ũnũkw’ĩa vala ũĩ, nũndũ wa yũa; nũndũ vati kĩmũtũ nongi ndũanĩ.'),
('kam', 'JER', 38, 10, 'Nĩvo ĩndĩ mũsumbĩ wamwĩaĩe Mũethiovia Eveti‐meleki akĩmwĩa, Osa andũ mĩongo ĩtatũ kuma vaa ũende nao, na mũyumya mwathani Yelemia ĩimanĩ, atanakw’a.'),
('kam', 'JER', 38, 11, 'Kwondũ wa ũu Eveti‐meleki aenda na ala andũ, na alika nyũmbanĩ ya mũsumbĩ ĩtheo wa vala vaiawa ũthwii, na oosa matani na ngũa ndwĩkangu, na aitheesya na makanda yĩla ĩimanĩ vala ve Yelemia.'),
('kam', 'JER', 38, 12, 'Na Mũethiovia Eveti‐meleki amwĩa Yelemia, Yu ĩkĩa matani aa na ngũa ii ndwĩkangu nzakwathanĩ syaku ungu wa makanda. Na Yelemia eeka ũu.'),
('kam', 'JER', 38, 13, 'Na ĩndĩ mambatya Yelemia na makanda, na kũmumya yĩla ĩimanĩ: na ũu nĩw’o Yelemia wekalile vu nza ya kolokolo.'),
('kam', 'JER', 38, 14, 'Nĩvo ĩndĩ mũsumbĩ Nzetekia watũmanie, na kũmũete mwathani Yelemia vala waĩ vandũ va katatũ va kũlikĩla nyũmbanĩ ya Yeova: na mũsumbĩ amwĩa Yelemia, Nĩngũũkũlya kaũndũ; ndũkambithe ko.'),
('kam', 'JER', 38, 15, 'Nĩvo ĩndĩ Yelemia wamũkũlilye Nzetekia, Ethĩwa ngakũvuanĩsya ko, nĩ w’o we ndwĩmbũaa? O na ethĩwa ngakũtaa, ndũkambĩthukĩĩsya.'),
('kam', 'JER', 38, 16, 'Kwondũ wa ũu mũsumbĩ Nzetekia eevĩta kwa Yelemia na kĩmbithĩ, akyasya, O tondũ Yeova wĩ thayũ, ũla watũmbĩe thayũ ũũ, ndikakũaa, o na ndikakũnengane mokonĩ ma andũ aa ala mamanthaa thayũ waku.'),
('kam', 'JER', 38, 17, 'Nĩvo ĩndĩ Yelemia wamwĩie Nzetekia, Ũũ nĩw’o Yeova, Ngai wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Ethĩwa ũkaumaala na kũmaendea anene me mbee ũsumbĩnĩ ma mũsumbĩ wa Mbaviloni, nĩvo ĩndĩ ũkekala thayũ, na ndũa ĩno ndĩkavĩvw’a na mwaki; naku ũkeethĩwa thayũ, o na nyũmba yaku.'),
('kam', 'JER', 38, 18, 'Ĩndĩ ethĩwa ndwĩumaala na kũmaendea anene asu ma mũsumbĩ wa Mbaviloni, nĩvo ĩndĩ ndũa ĩkanenganwe mokonĩ ma Akalitei, na makamĩvĩvya na mwaki, na ndũkavonoka kuma mokonĩ moo.'),
('kam', 'JER', 38, 19, 'Na mũsumbĩ Nzetekia amwĩa Yelemia, Nĩngũkĩa Ayuti ala metilĩte maende na Akalitei, maikese kũnengane mokonĩ moo, nao makĩmbũthya.'),
('kam', 'JER', 38, 20, 'Ĩndĩ Yelemia asya, Matikakũnengane. Nĩngũkwĩsũva, ĩw’a wasya wa Yeova, ũndũnĩ ũla ngũneena naku: na ĩndĩ kũkeethĩwa ũseo kwaku, na ũkekala thayũ.'),
('kam', 'JER', 38, 21, 'Ĩndĩ ethĩwa nũũlea kumaala, ĩno nĩyo ndeto ĩla Yeova ũmbonetye:'),
('kam', 'JER', 38, 22, 'Sisya, aka onthe ala matialile nyũmbanĩ ya mũsumbĩ wa Yuta makaumaalĩlw’a anene asu ma mũsumbĩ wa Mbaviloni, na aka asu makasya, Anyanyau ala mwĩsene nĩmaũkengete, na ũkũkĩlya vinya: yu maũũ maku malikĩte ndakanĩ, nĩmasyokete na ĩtina.'),
('kam', 'JER', 38, 23, 'Nao makaumaalĩlya Akalitei aka maku onthe, na syana syaku; naku ndũkavonoka kuma mokonĩ moo, ĩndĩ ũkakwatwa na kw’oko kwa mũsumbĩ wa Mbaviloni: na ũkatuma ndũa ĩno ĩvĩvw’a na mwaki.'),
('kam', 'JER', 38, 24, 'Nĩvo ĩndĩ Nzetekia wamwĩie Yelemia, Ndũkamanyĩthye mũndũ o na wĩva ndeto ii, na ndũkakw’a.'),
('kam', 'JER', 38, 25, 'Ĩndĩ ethĩwa anene asu makeew’a kana nĩnĩneenete naku, na kũka kwaku na ũkwĩa, Tũtavye yu ũvoo ũla wamũtavisye mũsumbĩ; ndũkatũvithe, na tũikakũaa; o na ũvoo ũla mũsumbĩ wakũtavisye:'),
('kam', 'JER', 38, 26, 'nĩvo ĩndĩ wĩmea, Nĩnamũvikĩsye mũsumbĩ wĩsũvano wakwa, atĩ ndakandũngĩthye nyũmbanĩ ya Yonathani, nĩkw’ĩe vo.'),
('kam', 'JER', 38, 27, 'Nĩvo ĩndĩ anene asu onthe mamũkĩe Yelemia na kũmũkũlya; nake amasũngĩa kwĩanana na ndeto ii syonthe ila mũsumbĩ wamwĩaĩe. Na ĩndĩ maeka kũneena nake; nũndũ ũvoo ndwaamanyĩka.'),
('kam', 'JER', 38, 28, 'Na ĩndĩ Yelemia ekala nza ya kolokolo kũvika mũthenya ũla Yelusaleme yosiwe.'),
('kam', 'JER', 39, 1, 'Na kweethĩwa yĩla Yelusaleme yosiwe (mwaka wa kenda wa kũsumbĩka kwa Nzetekia mũsumbĩ wa Yuta, mwei wa ĩkũmi, Nevukatilesa mũsumbĩ wa Mbaviloni na ita syake syonthe syoka kũkita na Yelusaleme, na syamĩtw’ĩkanĩsya;'),
('kam', 'JER', 39, 2, 'na mwaka wa ĩkũmi na ũmwe wa kũsumbĩka kwa Nzetekia, mwei wa kana, mũthenya wa kenda wa mwei, ndũa ĩsu yavũthũwa),'),
('kam', 'JER', 39, 3, 'na anene onthe me mbee ũsumbĩnĩ ma mũsumbĩ wa Mbaviloni malika, na mekala mbingĩlonĩ ĩla yaĩ katĩ, nao nĩ aa, Nelikali‐saleseli, na Samikali‐nevo, na Salisekimu, na Lavisalisi, na Nelikali‐saleseli, na Lavimaki, vamwe na anene ala angĩ onthe ma mũsumbĩ wa Mbaviloni.'),
('kam', 'JER', 39, 4, 'Na kweethĩwa, Nzetekia mũsumbĩ wa Yuta na andũ onthe ma kaũ mamona, makĩa, na mauma ndũanĩ ũtukũ, na nzĩa ya mũũnda wa mũsumbĩ, makĩvĩtĩla mbingĩlonĩ ĩla yĩ katĩ wa maũvai elĩ; nake aenda elekele mwanda wa Alava.'),
('kam', 'JER', 39, 5, 'Indĩ ita sya Akalitei syamaatĩĩa, na syamũvikĩlĩla Nzetekia ndiĩnĩ sya Yeliko: na syamũkwata, syamũtwaa kwa Nevukatilesa mũsumbĩ wa Mbaviloni ku Livila nthĩ ya Amathi; nake amũtw’ĩĩa sila.'),
('kam', 'JER', 39, 6, 'Nĩvo ĩndĩ mũsumbĩ wa Mbaviloni wamoaĩe ana ma Nzetekia ku Livila ene na metho make; o na mũsumbĩ wa Mbaviloni ooaa anene onthe me ndaĩa ma Yuta.'),
('kam', 'JER', 39, 7, 'Na ĩngĩ amũvũthũanga Nzetekia metho, na kũmwova na mbingũ, amũtwae Mbaviloni.'),
('kam', 'JER', 39, 8, 'Na Akalitei mavĩvya nyũmba ya mũsumbĩ, na nyũmba sya andũ, na mwaki, na maomboa maũvai ma Yelusaleme.'),
('kam', 'JER', 39, 9, 'Nĩvo ĩndĩ Nevusalatani kavuteni wa nguthu ya asũvĩi watwaie Mbaviloni me atave ũtialo wa andũ ala matialilw’e ndũanĩ, o na ala meetilĩle maende nake, na ũtialo wa andũ ala matialile.'),
('kam', 'JER', 39, 10, 'Ĩndĩ Nevusalatani kavuteni wa nguthu ya asũvĩi nĩwatiie ala ngya ma andũ, ala mataĩ na kĩndũ, nthĩ ya Yuta, na amanenga mĩũnda ya mĩsavivũ na mĩũnda o ĩvinda yĩu.'),
('kam', 'JER', 39, 11, 'Na Nevukatilesa mũsumbĩ wa Mbaviloni amwĩaĩa Nevusalatani kavuteni wa asũvĩi ũndũ wa Yelemia, akĩmwĩa,'),
('kam', 'JER', 39, 12, 'Mwose, noimũsũvĩa nesa, na ndũkamwĩke ũthũku; ĩndĩ mwĩke o ũndũ ũkakwĩa.'),
('kam', 'JER', 39, 13, 'Na ĩndĩ Nevusalatani kavuteni wa asũvĩi atũmana, o na Nevusasivani, na Lavisalisi, na Nelikali‐saleseli, na Lavimaki, na anene onthe ma mũsumbĩ wa Mbaviloni;'),
('kam', 'JER', 39, 14, 'nao matũmana, na maumya Yelemia vu nza ya kolokolo, na mamũnengane mokonĩ ma Ngetalia mwana wa Aikamu, mwana wa Savani, amũtwae kwake. Kwondũ wa ũu ekala na andũ.'),
('kam', 'JER', 39, 15, 'Na ĩndĩ ndeto ya Yeova yamũkĩa Yelemia, yĩla waĩ mwove nza ya kolokolo, ĩkĩmwĩa,'),
('kam', 'JER', 39, 16, 'Enda, ũneene na Mũethiovia Eveti‐meleki, ũkĩmwĩa, Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: Sisya, ngamĩetee ndũa ĩno ndeto syakwa nĩmĩke ũthũku, na ti kũmĩka ũseo; nasyo ikeanĩw’a mbee waku mũthenya ũsu.'),
('kam', 'JER', 39, 17, 'Ĩndĩ ngakũvonokya mũthenya ũsu, easya ũu Yeova; na ndũkanenganwe mokonĩ ma andũ ala ũmakĩaa.'),
('kam', 'JER', 39, 18, 'Nũndũ nditĩa ũkũtangĩĩa, na ndũkavalukw’a na ũvyũ, ĩndĩ thayũ waku ũkeethĩwa mũtavo waku; nĩkwĩthĩwa nĩwandĩkĩĩe, easya ũu Yeova.'),
('kam', 'JER', 40, 1, 'Ndeto ĩno yamũkĩe Yelemia kuma kwa Yeova, ĩtina wa Nevusalatani kavuteni wa nguthu ya asũvĩi kũmũlekya athi kuma Lama, yĩla waĩ anamũtwaa e mwove na mĩnyolo vamwe na onthe ala matwaiwe me Yelusaleme na Yuta, ala matwaiwe me atave kũvika Mbaviloni.'),
('kam', 'JER', 40, 2, 'Na ũla kavuteni amwosa Yelemia, na amwĩa, Yeova Ngai waku nĩwaneenee vandũ vaa ũthũku ũũ;'),
('kam', 'JER', 40, 3, 'na Yeova nũwũetete, na kwĩka kwĩanana na ũndũ waisye: nũndũ nĩmwamũvĩtanĩsye Yeova, na mũtyaaĩthukĩĩsya wasya wake, kwondũ wa ũu ũndũ ũsu nĩwĩkĩkĩte kwenyu.'),
('kam', 'JER', 40, 4, 'Na yu, sisya, nĩngũũthasya ũmũnthĩ kuma mĩnyololonĩ ĩla yĩ mokonĩ maku. Ethĩwa nũkwona nĩ ũseo kũenda nakwa Mbaviloni, ũka, na ngakũsũvĩa nesa; ĩndĩ ethĩwa nũkwona nĩ ũthũku kũenda nakwa Mbaviloni, eka: sisya, nthĩ yonthe yĩ mbee waku; o vala wĩona ve vaseo na vaĩlu va kũthi, enda vo.'),
('kam', 'JER', 40, 5, 'Na ĩndĩ atanamba kũsyoka, asya, Syoka ĩndĩ kwa Ngetalia mwana wa Aikamu, mwana wa Savani, ũla mũsumbĩ wa Mbaviloni ũmũtw’ĩkĩthĩtye ngavana wa ndũa sya Yuta, noyĩkala nake katĩ wa andũ; kana enda o vala wĩona ve vaseo va kũthi. Na ĩndĩ ũla kavuteni wa nguthu ya asũvĩi amũnenga lĩu na mũthĩnzĩo, na amũlekya athi.'),
('kam', 'JER', 40, 6, 'Nĩvo ĩndĩ Yelemia athi kwa Ngetelia mwana wa Aikamu ku Misiva, na ekala nake katĩ wa andũ ala matialile nthĩ ĩsu.'),
('kam', 'JER', 40, 7, 'Na yĩla makavuteni onthe ma asikalĩ ala maĩ weũnĩ, mo, na andũ moo, meewie kana mũsumbĩ wa Mbaviloni nũmũtw’ĩkĩthĩtye Ngetalia mwana wa Aikamu ngavana wa ĩ nthĩ, na kũmũnenga mokonĩ make aũme, na aka, na syana, na ala ngya mũno ma ĩ nthĩ, ma ala mataatwawa me atave Mbaviloni;'),
('kam', 'JER', 40, 8, 'nĩvo ĩndĩ mamũkĩe Ngetalia ku Misiva, nao nĩ aa, Isumaeli mwana wa Nethania, na Yoanani na Yonathani ana ma Kalea, na Selaia mwana wa Tanumethi, na ana ma Evai Mũnetovathi, na Yesania mwana wa Mũmaaka, mo na andũ moo.'),
('kam', 'JER', 40, 9, 'Na Ngetalia mwana wa Aikamu mwana wa Savani amevĩtĩa mo na andũ moo, akyasya, Mũtikakĩe kũthũkũma Akalitei: ĩkalai nthĩ ĩno, mũthũkũme mũsumbĩ wa Mbaviloni na kũkeethĩwa ũseo kwenyu.'),
('kam', 'JER', 40, 10, 'Ũndũ wakwa nyie, sisya, ngekala Misiva, nĩũngame mbee wa Akalitei ala makatũkĩa: ĩndĩ inyw’ĩ, ũmban’yai mbinyu na mosyao ma ĩvinda ya syũa na mauta, na mũisyĩkĩa mĩionĩ yenyu, na kwĩkalaa ndũanĩ syenyu ila mwosete.'),
('kam', 'JER', 40, 11, 'O ta ũu Ayuti onthe ala maĩ Moavi, na katĩ wa ana ma Amimoni, na Etomu, na nthĩ syonthe, meewie atĩ mũsumbĩ wa Mbaviloni nũtiĩte ũtialo wa Yuta, na kũmaiĩa Ngetalia mwana wa Aikamu, mwana wa Savani;'),
('kam', 'JER', 40, 12, 'nĩvo ĩndĩ Ayuti onthe masyokie kuma kũndũ kw’onthe kũla malũngĩlĩĩlw’e, na mamũkĩa Ngetalia, nthĩ ya Yuta, kũvika Misiva, na moomban’ya mbinyu na mosyao maingĩ ma ĩvinda ya syũa.'),
('kam', 'JER', 40, 13, 'Na ĩngĩ Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ ala maĩ maweũnĩ, mamũkĩa Ngetalia ku Misiva,'),
('kam', 'JER', 40, 14, 'na mamũkũlya, Nũũmanya kana Mbaalisi mũsumbĩ wa ana ma Amimoni nũtũmĩte Isumaeli mwana wa Nethania akũae? Ĩndĩ Ngetalia mwana wa Aikamu ndaamaĩkĩĩa.'),
('kam', 'JER', 40, 15, 'Nĩvo ĩndĩ Yoanani mwana wa Kalea waneenie na Ngetalia na kĩmbithĩ ku Misiva, akĩmwĩa, Nĩngũkwĩsũva, ũnenge ũthei nĩende, na ngooaa Isumaeli mwana wa Nethania, na vai mũndũ ũkamanya: akakũaĩa kĩ, Ayuti onthe ala makũmbanĩe manyaĩĩkw’e, na ũtialo wa Yuta ũkyaa?'),
('kam', 'JER', 40, 16, 'Ĩndĩ Ngetalia mwana wa Aikamu amwĩa Yoanani mwana wa Kalea, Ndũkeke ũndũ ũsu; nũndũ nũũneena ũvũngũ ũndũ wa Isumaeli.'),
('kam', 'JER', 41, 1, 'Na kweethĩwa mwei wa mũonza, Isumaeli mwana wa Nethania, mwana wa Elisama, wa ũsyao wa kĩũsumbĩ na ũmwe wa anene ma mũsumbĩ, na andũ ĩkũmi vamwe nake, mamũkĩa Ngetalia mwana wa Aikamu ku Misiva; na maĩa lĩu vamwe ku Misiva.'),
('kam', 'JER', 41, 2, 'Nĩvo ĩndĩ Isumaeli mwana wa Nethania wokĩlile, vamwe na ala andũ ĩkũmi ala maĩ nake, na mamũkũna Ngetalia mwana wa Aikamu, mwana wa Savani na ũvyũ, na mamũaa, ũla mũsumbĩ wa Mbaviloni wamũtw’ĩkĩthĩtye ngavana wa nthĩ.'),
('kam', 'JER', 41, 3, 'O na Isumaeli amoaa Ayuti onthe ala maĩ nake, nao nĩ ala maĩ na Ngetalia, ku Misiva, na Akalitei ala moonekie kw’o, andũ ma kaũ.'),
('kam', 'JER', 41, 4, 'Na kweethĩwa mũthenya wa kelĩ ĩtina wa kũmũaa Ngetalia, na vatyaĩ mũndũ waamanya,'),
('kam', 'JER', 41, 5, 'kwooka andũ kuma Sekemu, na Silo, na Samalia, o andũ mĩongo nyanya, menzete ing’ew’a syoo na matembũangĩte ngũa syoo, na metemangĩte mĩĩ, me na nthembo sya mũtu na ũvumba mokonĩ moo, maetete nyũmbanĩ ya Yeova.'),
('kam', 'JER', 41, 6, 'Na Isumaeli mwana wa Nethania auma ku Misiva amathaũe, akĩĩa aendete: na kweethĩwa, akomana nao, amea, Ũkai vala ve Ngetalia mwana wa Aikamu.'),
('kam', 'JER', 41, 7, 'Na kweethĩwa, malika ndũanĩ katĩ, Isumaeli mwana wa Nethania amoaa, na kũmekya nthĩnĩ wa yĩla ĩima, we, na andũ ala maĩ nake.'),
('kam', 'JER', 41, 8, 'Ĩndĩ kwooneka katĩ woo andũ ĩkũmi ala mamwĩie Isumaeli, Ndũkatũae; nũndũ twĩ na mĩio ya nganũ, na ya mbaale, na ya mauta, na ya ũkĩ wa nzũkĩ, ĩvithĩtwe mũũndanĩ. Kwondũ wa ũu amaeka, na ndaamoaa vamwe na ana‐a‐ĩthe moo.'),
('kam', 'JER', 41, 9, 'Na ĩima yĩla Isumaeli wekisye simba syonthe sya andũ ala wamoaie, vakuvĩ na Ngetalia, (nĩyo yĩla mũsumbĩ Asa wenzie ũndũ wa ũkĩa Mbaasa mũsumbĩ wa Isilaeli), Isumaeli mwana wa Nethania ayusũsya na ala mooaiwe.'),
('kam', 'JER', 41, 10, 'Nĩvo ĩndĩ Isumaeli watwaie me atave ũtialo w’onthe wa andũ ala matialilw’e Misiva, o na eĩtu ma mũsumbĩ, na andũ onthe ala matialilw’e Misiva, ala Nevusalatani kavuteni wa nguthu ya asũvĩi wamatiie mokonĩ ma Ngetalia mwana wa Aikamu; Isumaeli mwana wa Nethania amatwaa me atave, na akũsya eendea ananĩ ma Amimoni.'),
('kam', 'JER', 41, 11, 'Ĩndĩ yĩla Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ ala maĩ nake, meewie ũthũku ũsu w’onthe ũla Isumaeli mwana wa Nethania wekie,'),
('kam', 'JER', 41, 12, 'nĩvo ĩndĩ moosie andũ onthe, na mathi kũkita na Isumaeli mwana wa Nethania, na mamwĩthĩa ũtee wa manzĩ maingĩ ala me Ngiveoni.'),
('kam', 'JER', 41, 13, 'Na kweethĩwa atĩ yĩla andũ onthe ala maĩ na Isumaeli moonie Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ ala maĩ nake, matana.'),
('kam', 'JER', 41, 14, 'Na kwondũ wa ũu andũ onthe ala Isumaeli wamatwaie me atave kuma Misiva meethyũũa na masyoka, na mathi vala ve Yoanani mwana wa Kalea.'),
('kam', 'JER', 41, 15, 'Ĩndĩ Isumaeli mwana wa Nethania avonoka kuma mokonĩ ma Yoanani vamwe na andũ nyanya, na athi ananĩ ma Amimoni.'),
('kam', 'JER', 41, 16, 'Nĩvo ĩndĩ Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ ala maĩ nake, moosie ũtialo w’onthe wa andũ ala wamaumĩtye kwa Isumaeli mwana wa Nethania, kuma Misiva, ĩtina wa kũaa Ngetalia mwana wa Aikamu, nao nĩ aa, andũ ma kaũ, na aka, na syana, na avakũe, ala wamaetete kuma Ngiveoni.'),
('kam', 'JER', 41, 17, 'Nao maenda, na matũa Ngeluthi Kimiamu, ĩla yĩ vakuvĩ na Mbethileemu, maende kũlika Misili,'),
('kam', 'JER', 41, 18, 'nũndũ wa Akalitei; nũndũ nĩmamakĩaa, nũndũ Isumaeli mwana wa Nethania aĩ anamũaa Ngetalia mwana wa Aikamu, ũla mũsumbĩ wa Mbaviloni wamũtw’ĩkĩthĩtye ngavana wa ĩ nthĩ.'),
('kam', 'JER', 42, 1, 'Nĩvo ĩndĩ makavuteni onthe ma asikalĩ, na Yoanani mwana wa Kalea, na Yesania mwana wa Osaia, na andũ onthe kuma ũla mũnini kũvika ũla mũnene mbee, mathengeeie,'),
('kam', 'JER', 42, 2, 'na mamwĩa mwathani Yelemia, Nĩtũũkwĩsũva, wĩsũvano witũ wĩtĩkĩlwe mbee waku, naku tũvoyee kwa Yeova Ngai waku, o kwondũ wa ũtialo ũũ w’onthe (nũndũ nĩtũtialĩtw’e twĩ avũthũ twaĩ aingĩ, o tondũ metho maku matwene),'),
('kam', 'JER', 42, 3, 'kana Yeova Ngai waku atwon’ye nzĩa ĩla twaĩle kũthi nayo, na ũndũ ũla twaĩle kwĩka.'),
('kam', 'JER', 42, 4, 'Nĩvo ĩndĩ mwathani Yelemia wameie, Nĩnĩmwĩw’ĩte; sisya, ngamũvoya Yeova Ngai wenyu kwĩanana na ndeto syenyu; na kũkeethĩwa o ũndũ ũla Yeova ũkamũsũngĩa, ngamũtavya; ndikatialya ũndũ o na wĩva.'),
('kam', 'JER', 42, 5, 'Nĩvo ĩndĩ mamwĩie Yelemia, Yeova nĩethĩwe ngũsĩ ya w’o na yĩ kĩthito katĩ waitũ, ethĩwa tũtikeka kwĩanana na ndeto yonthe ĩla Yeova Ngai waku ũkakũtũma nayo kwitũ.'),
('kam', 'JER', 42, 6, 'Ethĩwa nĩ nzeo, kana ethĩwa nĩ nthũku, tũkeew’a wasya wa Yeova Ngai waitũ, ũla tũũkũtũma kwake; nĩ kana kwĩthĩwe ũseo kwitũ, o yĩla twĩĩw’aa wasya wa Yeova Ngai waitũ.'),
('kam', 'JER', 42, 7, 'Na kweethĩwa ĩtina wa mĩthenya ĩkũmi, ndeto ya Yeova yamũkĩa Yelemĩa.'),
('kam', 'JER', 42, 8, 'Nĩvo ĩndĩ wamwĩtie Yoanani mwana wa Kalea, na makavuteni onthe ma asikalĩ ala maĩ nake, na andũ onthe kuma ũla mũnini kũvika ũla mũnene mbee,'),
('kam', 'JER', 42, 9, 'na amea, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, ũla mwandũmie kwake nĩvikye wĩsũvano wenyu mbee wake:'),
('kam', 'JER', 42, 10, 'Ethĩwa mũkekala nthĩ ĩno, nĩvo ĩndĩ ngamwaka, na ti kũmũomboa, na ngamũvanda, na ti kũmũkũa; nũndũ nĩngwĩalyũla ũndũ wa ũthũku ũla namwĩkie.'),
('kam', 'JER', 42, 11, 'Mũtikakĩe mũsumbĩ wa Mbaviloni, ũla mũmũkĩaa; mũikamũkĩe, easya ũu Yeova; nũndũ nĩ vamwe nenyu nĩmũtangĩĩe, na kũmũvonokya kuma kw’okonĩ kwake.'),
('kam', 'JER', 42, 12, 'Na ngamwon’ya tei, nĩ kana amwĩw’ĩe inyw’ĩ tei, na kũmũtũnga nthĩ yenyu.'),
('kam', 'JER', 42, 13, 'Ĩndĩ ethĩwa mwĩasya, Tũtikekala nthĩ ĩno; mũtikew’e wasya wa Yeova Ngai wenyu,'),
('kam', 'JER', 42, 14, 'mũkyasya, Aiee: ĩndĩ tũkaenda nthĩ ya Misili, vala tũtakona kaũ, kana kwĩw’a wasya wa soo, kana kwaĩwa nĩ lĩu; na tũkekala kw’o:'),
('kam', 'JER', 42, 15, 'yu kwondũ wa ũu ĩw’ai ndeto ya Yeova, inyw’ĩ ũtialo wa Yuta: Ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya, Ethĩwa nĩ w’o mwĩelekelya mothyũ menyu kũlika Misili, na kũthi kwĩkala ũeni kw’o;'),
('kam', 'JER', 42, 16, 'nĩvo ĩndĩ kũkeethĩwa, ũvyũ ũla mũkĩaa, ũkamũvikĩla ku nthĩ ya Misili; na yũa yĩla mũkĩaa, yĩkamũatĩĩa na vinya ku Misili; na mũkakw’ĩa kw’o.'),
('kam', 'JER', 42, 17, 'Ũũ ũkeethĩwa kwa andũ onthe ala makelekelya mothyũ moo maende Misili mekale ũeni kw’o: makooawa na ũvyũ, na yũa, na mũimũ; na vai ũmwe ũkatiala kana kũvonoka kuma ũthũkunĩ ũla ngamaetee.'),
('kam', 'JER', 42, 18, 'Nũndũ ũũ nĩw’o Yeova wa nguthu, Ngai wa Isilaeli, ũnũkwasya: O tondũ ũthatu wakwa na kũthilĩka kwakwa nĩkwoonoew’e ala matwĩe Yelusaleme, now’o kũthilĩka kwakwa kũkonow’a ĩũlũ wenyu, yĩla mwĩlika Misili; na mũkeethĩwa ma kwĩvĩkwa, na ũseng’yo, na kĩumo, na ma kũvũthw’a; na mũtikona vandũ vaa ĩngĩ.'),
('kam', 'JER', 42, 19, 'Yeova nũneenete ũndũ wenyu, inyw’ĩ ũtialo wa Yuta, Mũtikaende Misili: manyai nĩ w’o nĩnamũkũsĩĩa ũmũnthĩ.'),
('kam', 'JER', 42, 20, 'Nũndũ nĩmũkengete mathayũ menyu; nũndũ nĩmwandũmie kwa Yeova Ngai wenyu, mũkyasya, Tũvoyee kwa Yeova Ngai waitũ; na kwĩanana na w’onthe ũla Yeova Ngai waitũ wĩneena, tũtavye o w’o, naitũ tũkawĩka.'),
('kam', 'JER', 42, 21, 'Na ũmũnthĩ nĩnĩmũtavĩtye; ĩndĩ mũtikwĩthukĩĩsya wasya wa Yeova Ngai wenyu ũndũnĩ o na wĩva ũla wandũmie kwenyu naw’o.'),
('kam', 'JER', 42, 22, 'Yu kwondũ wa ũu manyai ki mũkooaĩwa na ũvyũ, na yũa, na mũimũ, vandũ vala mwĩenda kũthi mwĩkale ũeni vo.'),
('kam', 'JER', 43, 1, 'Na kweethĩwa, yĩla Yelemia wamatavĩtye andũ onthe ndeto syonthe sya Yeova Ngai woo, ila Yeova Ngai woo wamũtũmie kwoo nasyo, o ndeto isu syonthe,'),
('kam', 'JER', 43, 2, 'nĩvo Asalia mwana wa Osaia, na Yoanani mwana wa Kalea, na ekathĩĩi onthe, maneenie, makĩmwĩa Yelemia, Nũũneena ũvũngũ: Yeova Ngai waitũ ndakũtũmĩte kũneena atĩĩ, Mũtikaende Misili mwĩkale ũeni kw’o;')
